let tok=null,prof=null,co=null,chkItems=[],people=[];
let rolePreview=null;
const RL={inspector:1,manager:2,admin:3,sephs_admin:4};
function isInternalSephsAdminAccount(){
  var role=prof?.role||'';
  var companyName=(co?.name||prof?.company_name||'').toLowerCase().trim();
  return role==='sephs_admin' || (role==='admin' && (companyName==='sephs consulting' || companyName==='auris360' || companyName==='auris 360'));
}
function activeRole(){
  if(isInternalSephsAdminAccount()) return rolePreview || 'sephs_admin';
  return prof?.role||'employee';
}
function rlv(){return RL[activeRole()]||0;}
function can(r){return rlv()>=RL[r];}
function isInsp(){return activeRole()==='inspector';}
function isMgr(){return can('manager');}
function isAdm(){return can('admin');}
function isSA(){return activeRole()==='sephs_admin';}
function canAdministerControlledRecord(){
  var r=activeRole();
  return r==='sephs_admin'||r==='admin'||r==='hse_manager';
}
function controlledStatusIsLocked(status){
  return ['submitted','pending_review','under_review','pending_approval','approved','active','completed','closed'].indexOf(String(status||'').toLowerCase())!==-1;
}
function controlledRecordCanEdit(rec){
  var st=String(rec?.approval_status||rec?.status||'draft').toLowerCase();
  return !controlledStatusIsLocked(st)||st==='revision_requested'||st==='rejected'||st==='draft'||canAdministerControlledRecord();
}
function controlledLockMessage(label, rec){
  var st=String(rec?.approval_status||rec?.status||'controlled').replace(/_/g,' ');
  return (label||'Record')+' is '+st+' and is locked. Admin/HSE Manager can release or revise it before changes are made.';
}
function controlledEnsureNotice(containerId, noticeId){
  var container=document.getElementById(containerId);if(!container)return null;
  var note=document.getElementById(noticeId);
  if(!note){
    note=document.createElement('div');
    note.id=noticeId;
    note.style.cssText='display:none;margin:10px 0;padding:10px 12px;border-radius:8px;background:#FEF9EC;border:1px solid #FCD34D;color:#854F0B;font-size:13px;font-weight:700';
    container.insertBefore(note,container.firstChild);
  }
  return note;
}
function controlledApplyFormLock(containerId, noticeId, rec, label){
  var container=document.getElementById(containerId);if(!container)return;
  var locked=!!rec&&!controlledRecordCanEdit(rec);
  var note=controlledEnsureNotice(containerId,noticeId);
  if(note){note.style.display=locked?'block':'none';note.textContent=locked?controlledLockMessage(label,rec):'';}
  container.querySelectorAll('input,select,textarea').forEach(function(el){
    if(el.type==='hidden')return;
    el.disabled=locked;
  });
  container.querySelectorAll('button').forEach(function(btn){
    var action=btn.getAttribute('onclick')||'';
    var keep=action.includes('Back')||action.includes('ShowList')||action.includes('FormTab')||action.includes('print')||action.includes('Print')||action.includes('Viewer')||action.includes('CreateNewRevision')||action.includes('Approve')||action.includes('Reject')||action.includes('Release');
    var isSave=action.includes('Save')||action.includes('SubmitForApproval');
    if(locked&&isSave)btn.style.display='none';
    else if(!locked&&isSave)btn.style.display='';
    if(locked&&!keep)btn.disabled=true;
    if(!locked)btn.disabled=false;
  });
}
var AI_ALLOWED_ROLES = ['sephs_admin','admin','hse_manager','hse_officer'];
function canUseAI(){
  return AI_ALLOWED_ROLES.indexOf(activeRole()) !== -1;
}

async function ensureContractorNameOptions(){
  var ids=['swms-contractor','wf-contractor','hwf-contractor','spf-cleanup-con'];
  ids.forEach(function(id){var el=document.getElementById(id);if(el)el.setAttribute('list','contractor-name-options');});
  var dl=document.getElementById('contractor-name-options');
  if(!dl){dl=document.createElement('datalist');dl.id='contractor-name-options';document.body.appendChild(dl);}
  var key=ccid()||'all';
  if(dl.getAttribute('data-company')===key)return;
  try{
    var rows=await api('/contractors?select=contractor_name,trading_name,status'+cf()+'&order=contractor_name.asc&limit=500');
    var names=[];
    (rows||[]).forEach(function(c){
      [c.contractor_name,c.trading_name].forEach(function(n){n=String(n||'').trim();if(n&&names.indexOf(n)===-1)names.push(n);});
    });
    dl.innerHTML=names.map(function(n){return '<option value="'+escH(n)+'"></option>';}).join('');
    dl.setAttribute('data-company',key);
  }catch(e){
    console.warn('Contractor suggestions unavailable',e);
  }
}
function apiCompanyScopeIssue(path,o,method){
  try{
    method=String(method||'GET').toUpperCase();
    if(method==='GET'||isSA()||!prof?.company_id)return '';
    var body=o?.b||{};
    var bodyCompany=body.company_id?String(body.company_id):'';
    var pathCompany=auditPathEq(path,'company_id')||'';
    var own=String(prof.company_id);
    if(bodyCompany&&bodyCompany!==own)return 'Blocked cross-company write. This record belongs to another company.';
    if(pathCompany&&pathCompany!==own)return 'Blocked cross-company update. This request targets another company.';
  }catch(_){}
  return '';
}
async function api(path,o={}
){
const resilienceFault=typeof window.aurisResilienceFaultForPath==='function'?window.aurisResilienceFaultForPath(path):'';
if(resilienceFault)throw new Error(resilienceFault);
const headers={'Content-Type':'application/json','apikey':KEY,'Authorization':'Bearer '+(tok||KEY),'Accept':'application/json'};
if(o.p)headers['Prefer']=o.p;
const method=o.m||'GET';
if((method==='POST'||method==='PATCH')&&/^\/documents(?:\?|$)/.test(path)&&o.b&&(Object.prototype.hasOwnProperty.call(o.b,'dept')||Object.prototype.hasOwnProperty.call(o.b,'doc_owner')||Object.prototype.hasOwnProperty.call(o.b,'doc_version'))){
  o=Object.assign({},o,{b:Object.assign({},o.b)});
  delete o.b.dept;
  delete o.b.doc_owner;
  delete o.b.doc_version;
}
const scopeIssue=apiCompanyScopeIssue(path,o,method);
if(scopeIssue)throw new Error(scopeIssue);
const r=await fetch(SB+'/rest/v1'+path,{method:o.m||'GET',headers:headers,body:o.b?JSON.stringify(o.b):undefined});
if(r.status===204||r.status===205){auditApiMutation(path,method,o,null);return null;}
const txt=await r.text();
if(!txt||txt.trim()===''){
  if(r.ok){auditApiMutation(path,method,o,null);return null;}
  throw new Error(r.statusText||'Request failed');
}
let d;
try{d=JSON.parse(txt);}catch(e){console.error('JSON parse error:',txt.slice(0,200));throw new Error('Invalid server response');}
if(!r.ok){
  const msg=(Array.isArray(d)?d[0]?.message:d.message)||d.error_description||d.hint||r.statusText;
  var missingDocCol='';
  try{
    var m=String(msg||'').match(/Could not find the '([^']+)' column of 'documents'/i);
    missingDocCol=m&&m[1]?m[1]:'';
  }catch(_){}
  if(missingDocCol&&(method==='POST'||method==='PATCH')&&/^\/documents(?:\?|$)/.test(path)&&o.b&&Object.prototype.hasOwnProperty.call(o.b,missingDocCol)){
    var skipped=o._skipMissingDocumentColumns||{};
    if(!skipped[missingDocCol]&&Object.keys(skipped).length<20){
      var retryBody=Object.assign({},o.b);
      delete retryBody[missingDocCol];
      var retryOpts=Object.assign({},o,{b:retryBody,_skipMissingDocumentColumns:Object.assign({},skipped,{[missingDocCol]:true})});
      console.warn('Document Control save skipped unsupported documents column:',missingDocCol);
      return api(path,retryOpts);
    }
  }
  console.error('API error '+r.status+':',msg,path);throw new Error(msg);
}
auditApiMutation(path,method,o,d);
return d;
}

// Shared reciprocal relationship service (AP-030). Module-specific relationship
// tables remain supported while modules migrate to this canonical interface.
function relationshipEndpoint(moduleKey,tableName,recordId,recordRef,revision){
  return {
    module:String(moduleKey||'').toLowerCase().trim(),
    table:String(tableName||'').toLowerCase().trim(),
    id:String(recordId||'').trim(),
    ref:recordRef==null?null:String(recordRef),
    revision:revision==null?null:String(revision)
  };
}
async function relationshipList(endpoint,options){
  endpoint=endpoint||{};options=options||{};
  if(!endpoint.module||!endpoint.table||!endpoint.id)return [];
  var path='/record_relationships_bidirectional?select=*'
    +'&record_module=eq.'+encodeURIComponent(endpoint.module)
    +'&record_table=eq.'+encodeURIComponent(endpoint.table)
    +'&record_id=eq.'+encodeURIComponent(endpoint.id)
    +cf();
  if(options.includeArchived!==true)path+='&status=neq.archived';
  try{return await api(path+'&order=created_at.desc');}
  catch(e){
    if(/record_relationships|schema cache|does not exist|not found/i.test(String(e?.message||e))){console.warn('Shared relationships are not installed yet');return [];}
    throw e;
  }
}
async function relationshipCreate(source,target,relationshipType,options){
  source=source||{};target=target||{};options=options||{};
  if(!source.module||!source.table||!source.id||!target.module||!target.table||!target.id)throw new Error('Both relationship endpoints require module, table and record ID.');
  var rows=await api('/rpc/create_record_relationship',{m:'POST',p:'return=representation',b:{
    p_company_id:options.company_id||ccid(),
    p_source_module:source.module,p_source_table:source.table,p_source_id:String(source.id),p_source_ref:source.ref||null,
    p_target_module:target.module,p_target_table:target.table,p_target_id:String(target.id),p_target_ref:target.ref||null,
    p_relationship_type:relationshipType||'related_to',
    p_source_revision:source.revision||null,p_target_revision:target.revision||null,
    p_applicability:options.applicability||{},p_allow_unresolved:options.allowUnresolved===true
  }});
  var row=Array.isArray(rows)?rows[0]:rows;
  try{auditLogEvent('link','relationships','Connected records linked',{relationship_type:relationshipType||'related_to',source:source,target:target},{related_table:'record_relationships',related_id:row?.id||null,related_ref:(source.ref||source.id)+' ↔ '+(target.ref||target.id),relationship_id:row?.id||null,company_id:options.company_id||ccid()});}catch(_){}
  return row||null;
}
async function relationshipArchive(relationshipId,reason){
  if(!relationshipId)return;
  var current=await api('/record_relationships?select=*&id=eq.'+encodeURIComponent(relationshipId)+'&limit=1');
  var applicability=Object.assign({},current?.[0]?.applicability||{},{archive_reason:reason||'Relationship removed by user',archived_at:new Date().toISOString()});
  await api('/record_relationships?id=eq.'+encodeURIComponent(relationshipId),{m:'PATCH',p:'return=minimal',b:{status:'archived',applicability:applicability,updated_at:new Date().toISOString()}});
  var relationship=current?.[0]||{};
  try{auditLogEvent('unlink','relationships','Connected-record relationship archived',{reason:reason||null,source:{module:relationship.source_module,table:relationship.source_table,id:relationship.source_id,ref:relationship.source_ref},target:{module:relationship.target_module,table:relationship.target_table,id:relationship.target_id,ref:relationship.target_ref}},{related_table:'record_relationships',related_id:relationshipId,related_ref:(relationship.source_ref||relationship.source_id||'Source')+' ↔ '+(relationship.target_ref||relationship.target_id||'Target'),relationship_id:relationshipId,company_id:relationship.company_id||ccid()});}catch(_){}
}

// Reusable Connected Records panel (AP-031). It intentionally discovers linkable
// records through the server-side registry so users never type raw record IDs.
var connectedRecordsState={};
var relationshipRegistryCache=null;
var relationshipSchemaReady=null;
async function relationshipRegistry(){
  if(relationshipRegistryCache)return relationshipRegistryCache;
  try{
    relationshipRegistryCache=await api('/relationship_module_registry?select=module_key,table_name,id_column,ref_column,display_label&enabled=eq.true&order=display_label.asc');
    relationshipSchemaReady=true;
    return relationshipRegistryCache||[];
  }catch(e){
    if(/relationship_module_registry|schema cache|does not exist|not found/i.test(String(e?.message||e))){relationshipSchemaReady=false;return [];}
    throw e;
  }
}
function connectedRecordsCanManage(options){
  if(options&&options.allowCreate===false)return false;
  var role=typeof activeRole==='function'?activeRole():'';
  return ['sephs_admin','admin','hse_manager','hse_officer','manager','site_manager','supervisor','document_controller','compliance_manager','risk_assessor','training_admin','hr_manager'].includes(role);
}
function connectedRecordsLabel(row,cfg){
  var ref=cfg&&cfg.ref_column&&row[cfg.ref_column];
  var title=['title','name','description','subject','activity','chemical_name','document_title','event_type','assessment_title','contractor_name','identifier']
    .map(function(k){return row&&row[k];}).find(Boolean);
  return [ref,title].filter(Boolean).join(' - ')||String(row?.[cfg?.id_column||'id']||'Record');
}
function connectedRecordsStatusStyle(status){
  if(status==='active')return {bg:'#E8F7F0',fg:'#087A55',label:'Connected'};
  if(status==='pending_verification')return {bg:'#FFF4D6',fg:'#9A5B00',label:'Verify'};
  if(status==='endpoint_archived')return {bg:'#FFFBEB',fg:'#92400E',label:'Endpoint archived'};
  if(status==='broken')return {bg:'#FDE8E8',fg:'#B42318',label:'Broken link'};
  return {bg:'#F5F3FF',fg:'#6D28D9',label:'Unresolved'};
}
async function connectedRecordsMount(mountId,endpoint,options){
  var host=document.getElementById(mountId);if(!host)return;
  connectedRecordsState[mountId]={endpoint:endpoint,options:options||{},rows:[],registry:[],pickerRows:[]};
  if(!endpoint||!endpoint.id){
    host.innerHTML='<div class="card" style="border-left:4px solid #94A3B8"><div class="card-title"><i class="ti ti-link"></i> Connected Records</div><div style="font-size:12px;color:var(--text2)">Save this record before adding relationships.</div></div>';
    return;
  }
  host.innerHTML='<div class="card"><div class="loading-msg">Loading connected records...</div></div>';
  try{
    var result=await Promise.all([relationshipList(endpoint),relationshipRegistry()]);
    var state=connectedRecordsState[mountId];if(!state)return;
    var role=typeof activeRole==='function'?activeRole():'';
    state.rows=(result[0]||[]).filter(function(row){return row.applicability?.confidentiality!=='privileged'||['sephs_admin','admin','hse_manager','compliance_manager'].includes(role);});state.registry=result[1]||[];
    connectedRecordsRender(mountId);
  }catch(e){host.innerHTML='<div class="card"><div style="color:var(--red);font-size:12px">Connected records could not be loaded: '+escH(e.message||e)+'</div></div>';}
}
function connectedRecordsRender(mountId){
  var state=connectedRecordsState[mountId],host=document.getElementById(mountId);if(!state||!host)return;
  var canManage=connectedRecordsCanManage(state.options);
  var h='<div class="card" style="border-left:4px solid #2563EB">'
    +'<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap"><div><div class="card-title" style="margin-bottom:2px"><i class="ti ti-link"></i> Connected Records <span style="background:#E8F0FE;color:#185FA5;border-radius:99px;padding:2px 7px;font-size:10px">'+state.rows.length+'</span></div><div style="font-size:11px;color:var(--text2)">Open related evidence, controls and actions without searching another module.</div></div>'
    +(canManage&&relationshipSchemaReady!==false?'<button type="button" class="btn btn-sm" data-auris-runtime-onclick="r0001" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([mountId]))+'"><i class="ti ti-plus"></i>Add relationship</button>':'')+'</div>';
  if(relationshipSchemaReady===false){
    h+='<div style="margin-top:12px;padding:10px;border-radius:8px;background:#FFF8E6;color:#854F0B;font-size:12px"><i class="ti ti-alert-triangle"></i> Run <b>shared_record_relationships_schema.sql</b> to enable Connected Records.</div>';
  }else if(!state.rows.length){
    h+='<div style="margin-top:12px;padding:14px;border:1px dashed var(--border);border-radius:8px;text-align:center;color:var(--text2);font-size:12px">No connected records yet.</div>';
  }else{
    h+='<div style="display:grid;gap:8px;margin-top:12px">';
    state.rows.forEach(function(row){
      var st=connectedRecordsStatusStyle(row.status),warning=row.status!=='active'||row.related_valid===false;
      h+='<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border:1px solid '+(warning?'#F5B7B1':'var(--border)')+';border-radius:9px;background:'+(warning?'#FFF8F7':'#fff')+'">'
        +'<div style="min-width:0"><div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><span style="font-size:12px;font-weight:800;color:var(--text)">'+escH(row.related_ref||row.related_id)+'</span><span style="font-size:10px;font-weight:700;background:#EEF2F6;color:#475569;padding:2px 7px;border-radius:99px">'+escH(String(row.related_module||'').replace(/_/g,' '))+'</span><span style="font-size:10px;font-weight:700;background:'+st.bg+';color:'+st.fg+';padding:2px 7px;border-radius:99px">'+st.label+'</span></div>'
        +'<div style="font-size:11px;color:var(--text2);margin-top:3px">'+escH(String(row.relationship_type||'related_to').replace(/_/g,' '))+(row.related_revision?' · Revision '+escH(row.related_revision):'')+(warning&&row.validation_error?' · '+escH(row.validation_error):'')+'</div></div>'
        +'<div style="display:flex;gap:5px;flex-shrink:0"><button type="button" class="btn btn-sm" '+(warning?'disabled title="Resolve this relationship before opening"':'onclick="connectedRecordsOpen(\''+mountId+'\',\''+row.id+'\')"')+'><i class="ti ti-external-link"></i>Open</button>'
        +(canManage?'<button type="button" class="btn btn-sm" title="Remove relationship" data-auris-runtime-onclick="r0002" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([mountId,row.id]))+'"><i class="ti ti-unlink"></i></button>':'')+'</div></div>';
    });
    h+='</div>';
  }
  if(canManage&&relationshipSchemaReady!==false){
    h+='<div id="'+mountId+'-picker" style="display:none;margin-top:12px;padding:12px;background:#F8FAFC;border:1px solid var(--border);border-radius:9px">'
      +'<div class="form3row"><div class="form3group"><label class="form3label">Record type</label><select id="'+mountId+'-module" data-auris-runtime-onchange="r0003" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([mountId]))+'"><option value="">Select module...</option>'
      +state.registry.filter(function(c){return !(c.module_key===state.endpoint.module&&c.table_name===state.endpoint.table);}).map(function(c){return '<option value="'+escH(c.module_key+'|'+c.table_name)+'">'+escH(c.display_label)+'</option>';}).join('')+'</select></div>'
      +'<div class="form3group"><label class="form3label">Relationship</label><select id="'+mountId+'-type"><option value="related_to">Related to</option><option value="learning_source">Learning source</option><option value="evidence_for">Evidence for</option><option value="action_for">Action for</option><option value="control_for">Control for</option><option value="supersedes">Supersedes</option><option value="derived_from">Derived from</option></select></div></div>'
      +'<div class="form3group"><label class="form3label">Find a record</label><input id="'+mountId+'-search" placeholder="Search reference, title or description..." data-auris-runtime-oninput="r0004" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([mountId]))+'"/></div>'
      +'<div class="form3group"><label class="form3label">Select verified record</label><select id="'+mountId+'-result"><option value="">Choose a record type first...</option></select></div>'
      +'<div style="display:flex;justify-content:flex-end;gap:7px"><button class="btn btn-sm" type="button" data-auris-runtime-onclick="r0005" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([mountId]))+'">Cancel</button><button class="btn btn-primary btn-sm" type="button" data-auris-runtime-onclick="r0006" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([mountId]))+'"><i class="ti ti-link-plus"></i>Connect selected record</button></div></div>';
  }
  h+='</div>';host.innerHTML=h;var defaultType=document.getElementById(mountId+'-type');if(defaultType&&state.options.defaultRelationshipType)defaultType.value=state.options.defaultRelationshipType;
}
function connectedRecordsTogglePicker(mountId,force){
  var el=document.getElementById(mountId+'-picker');if(!el)return;
  el.style.display=force===false?'none':(el.style.display==='none'?'block':'none');
}
async function connectedRecordsSearch(mountId){
  var state=connectedRecordsState[mountId],choice=document.getElementById(mountId+'-module')?.value||'',result=document.getElementById(mountId+'-result');if(!state||!result)return;
  var parts=choice.split('|'),cfg=state.registry.find(function(c){return c.module_key===parts[0]&&c.table_name===parts[1];});
  if(!cfg||!/^[a-z0-9_]+$/.test(cfg.table_name)){result.innerHTML='<option value="">Select a valid module...</option>';return;}
  result.innerHTML='<option value="">Loading records...</option>';
  try{
    var rows=await api('/'+cfg.table_name+'?select=*&limit=100'+cf());
    state.pickerCfg=cfg;state.pickerRows=(rows||[]).map(function(row){return {row:row,id:String(row[cfg.id_column]||''),ref:cfg.ref_column?row[cfg.ref_column]:null,label:connectedRecordsLabel(row,cfg)};}).filter(function(x){return x.id;});
    connectedRecordsFilterPicker(mountId);
  }catch(e){state.pickerRows=[];result.innerHTML='<option value="">Records unavailable for this module</option>';toast('This record type cannot be linked yet: '+(e.message||e),false);}
}
function connectedRecordsFilterPicker(mountId){
  var state=connectedRecordsState[mountId],result=document.getElementById(mountId+'-result');if(!state||!result)return;
  var q=String(document.getElementById(mountId+'-search')?.value||'').toLowerCase().trim();
  var rows=(state.pickerRows||[]).filter(function(x){return !q||x.label.toLowerCase().includes(q);}).slice(0,40);
  result.innerHTML='<option value="">Select a verified record...</option>'+rows.map(function(x){return '<option value="'+escH(x.id)+'">'+escH(x.label)+'</option>';}).join('');
}
async function connectedRecordsAdd(mountId){
  var state=connectedRecordsState[mountId],selected=document.getElementById(mountId+'-result')?.value||'',type=document.getElementById(mountId+'-type')?.value||'related_to';
  var pick=state&&(state.pickerRows||[]).find(function(x){return x.id===selected;});
  if(!state||!state.pickerCfg||!pick){toast('Select a record from the verified results.',false);return;}
  if(state.pickerCfg.table_name===state.endpoint.table&&pick.id===String(state.endpoint.id)){toast('A record cannot be connected to itself.',false);return;}
  try{
    var target=relationshipEndpoint(state.pickerCfg.module_key,state.pickerCfg.table_name,pick.id,pick.ref);
    await relationshipCreate(state.endpoint,target,type,{});toast('Record connected successfully.');
    await connectedRecordsMount(mountId,state.endpoint,state.options);
    if(typeof state.options.onChanged==='function')await state.options.onChanged();
  }catch(e){toast('Relationship could not be created: '+(e.message||e),false);}
}
async function connectedRecordsRemove(mountId,relationshipId){
  if(!confirm('Remove this relationship? The records themselves will not be deleted.'))return;
  var state=connectedRecordsState[mountId];
  try{await relationshipArchive(relationshipId,'Removed from Connected Records panel');toast('Relationship removed.');await connectedRecordsMount(mountId,state.endpoint,state.options);if(typeof state.options.onChanged==='function')await state.options.onChanged();}catch(e){toast('Relationship could not be removed: '+(e.message||e),false);}
}
async function connectedRecordsOpen(mountId,relationshipId){
  var state=connectedRecordsState[mountId],row=state&&(state.rows||[]).find(function(x){return x.id===relationshipId;});if(!row)return;
  if(row.related_module==='action'&&row.related_table==='action_tracker'){
    showPage('actions');await new Promise(function(resolve){setTimeout(resolve,140);});await mapEdit(row.related_id);return;
  }
  var synthetic={source_module:row.related_module,source_type:row.related_module,source_table:row.related_table,source_id:row.related_id,source_ref:row.related_ref||row.related_id};
  var adapter=mapSourceAdapter(synthetic);if(!adapter){toast('This module does not yet have a navigation adapter.',false);return;}
  showPage(adapter.page);await new Promise(function(resolve){setTimeout(resolve,140);});
  var opened=await mapOpenExactSource(adapter,synthetic);if(!opened)mapApplySourceSearch(adapter.page,synthetic.source_ref);
  toast(opened?'Opened connected record.':'Opened the related module and applied the record reference.');
}

async function apiWriteWithMissingColumnFallback(path,o,label){
  var attempt=Object.assign({},o,{b:Object.assign({},o&&o.b)}),skipped=[];
  for(var tries=0;tries<12;tries++){
    try{return await api(path,attempt);}catch(e){
      var msg=String((e&&e.message)||e||''),m=msg.match(/Could not find the '([^']+)' column/i),col=m&&m[1]?m[1]:'';
      if(!col||!attempt.b||!Object.prototype.hasOwnProperty.call(attempt.b,col)||!/(POST|PATCH)/i.test(attempt.m||''))throw e;
      delete attempt.b[col];skipped.push(col);
      console.warn((label||'Record')+' save skipped unsupported column:',col);
    }
  }
  throw new Error((label||'Record')+' could not be saved after removing unsupported columns: '+skipped.join(', '));
}

function auditTableFromPath(path){
  var clean=(path||'').split('?')[0].replace(/^\/+/,'');
  return clean.split('/')[0]||'';
}
function auditRelatedIdFromPath(path){
  var m=String(path||'').match(/[?&]id=eq\.([0-9a-fA-F-]{36})/);
  return m?m[1]:null;
}
function auditPathEq(path,key){
  var re=new RegExp('[?&]'+key+'=eq\\.([^&]+)');
  var m=String(path||'').match(re);
  return m?decodeURIComponent(m[1]):null;
}
function auditCompanyId(body,path){
  try{
    return body?.company_id || auditPathEq(path,'company_id') || (typeof ccid==='function'?ccid():null) || prof?.company_id || null;
  }catch(_){return body?.company_id || auditPathEq(path,'company_id') || prof?.company_id || null;}
}
function auditRecordLabel(body){
  body=body||{};
  var keys=['reference_no','reference','action_ref','permit_number','event_ref','incident_number','investigation_ref','ra_ref','doc_ref','course_ref','training_ref','code','chemical_name','product_name','title','name','full_name','subject','description'];
  for(var i=0;i<keys.length;i++){
    var v=body[keys[i]];
    if(v)return String(v).substring(0,90);
  }
  return '';
}
function displayRecordRef(row, keys, fallback){
  row=row||{};
  keys=Array.isArray(keys)?keys:[keys];
  for(var i=0;i<keys.length;i++){
    var v=row[keys[i]];
    if(v)return String(v);
  }
  return fallback||'DRAFT';
}
function auditIsSensitiveField(k){
  k=String(k||'').toLowerCase();
  if(!k)return false;
  if({password:1,temporary_password:1,resend_api_key:1,api_key:1,secret:1,token:1,body_html:1}[k])return true;
  return /(password|passcode|pin|secret|token|api[_-]?key|service[_-]?key|authorization|access[_-]?token|refresh[_-]?token|smtp|resend|openai)/i.test(k);
}
function auditChangedFields(body){
  return Object.keys(body||{}).filter(function(k){return !auditIsSensitiveField(k);});
}
var AUDIT_EVENT_CONTRACT={
  mandatory:['create','update','submit','approve','reject','archive','link','unlink','open_sensitive','export'],
  modules:{
    incident:{tables:['events','investigations','incident_mgmt_records']},risk:{tables:['risk_assessments']},permit:{tables:['permits']},
    documents:{tables:['documents','document_control_records']},swms:{tables:['documents']},legal:{tables:['legal_requirements','legal_assessments']},
    sop:{tables:['sop_video_projects']},training:{tables:['training_sessions','training_records','training_followup','elearning_courses','elearning_enrolments']},
    moc:{tables:['moc_change_requests']},chemical:{tables:['chemicals','chemical_sds_versions','chemical_use_approvals']},
    contractor:{tables:['contractors','contractor_documents','contractor_assurance_profiles']},tools:{tables:['tools_equipment','equipment_assurance_profiles','equipment_assurance_records','equipment_maintenance_events']},
    bbs:{tables:['safety_observations','bbs_observation_details','bbs_programmes','bbs_recognitions']},
    engagement:{tables:['engagement_programmes','engagement_team_reviews','engagement_recognitions','engagement_disputes']},
    noise:{tables:['noise_surveys','noise_mgmt_measurements','noise_mgmt_exposure_assessments','noise_mgmt_maps','noise_mgmt_reports']},
    actions:{tables:['action_tracker']}
  },
  sensitiveTables:['investigations','incident_mgmt_records','occupational_disease_records','health_surveillance','noise_mgmt_health_statuses','engagement_disputes','engagement_coaching_plans','engagement_person_results']
};
function auditModuleForRecord(table,body){
  table=String(table||'');body=body||{};
  if(table==='documents'){
    var type=String(body.doc_type||body.document_type||body.title||'').toLowerCase();
    if(/swms|safe work method|method statement/.test(type))return 'swms';
  }
  var names=Object.keys(AUDIT_EVENT_CONTRACT.modules);
  for(var i=0;i<names.length;i++)if(AUDIT_EVENT_CONTRACT.modules[names[i]].tables.indexOf(table)!==-1)return names[i];
  return table||'system';
}
function auditSemanticAction(table,method,body){
  method=String(method||'GET').toUpperCase();body=body||{};
  if(table==='record_relationships'){
    if(method==='POST')return 'link';
    if(method==='DELETE'||String(body.status||'').toLowerCase()==='archived')return 'unlink';
  }
  if(method==='DELETE')return 'delete';
  var values=Object.keys(body).filter(function(k){return /status|decision|outcome/i.test(k);}).map(function(k){return String(body[k]||'').toLowerCase();});
  if(values.some(function(v){return ['submitted','pending_review','pending_approval','in_review','under_review'].includes(v);}))return 'submit';
  if(values.some(function(v){return ['approved','accepted','validated','published','released','verified'].includes(v);}))return 'approve';
  if(values.some(function(v){return ['rejected','declined','returned','not_approved'].includes(v);}))return 'reject';
  if(values.some(function(v){return ['archived','retired','superseded'].includes(v);}))return 'archive';
  return {POST:'create',PATCH:'update',PUT:'update'}[method]||method.toLowerCase();
}
function auditSensitivity(table,body){
  if(AUDIT_EVENT_CONTRACT.sensitiveTables.indexOf(String(table||''))!==-1){
    return /health|disease|clinical/.test(String(table||''))?'clinical':'restricted';
  }
  var level=String(body?.confidentiality||body?.privacy_level||body?.classification||'').toLowerCase();
  return ['restricted','clinical','confidential'].includes(level)?level:'standard';
}
function auditUuid(){try{return crypto.randomUUID();}catch(_){return null;}}
function auditPostEntry(entry){
  var headers={'Content-Type':'application/json','apikey':KEY,'Authorization':'Bearer '+tok,'Prefer':'return=minimal'};
  fetch(SB+'/rest/v1/audit_events',{method:'POST',headers:headers,body:JSON.stringify(entry)}).then(function(r){
    if(r.ok)return;var legacy=Object.assign({},entry);['event_code','related_ref','relationship_id','correlation_id','outcome','sensitivity'].forEach(function(k){delete legacy[k];});
    return fetch(SB+'/rest/v1/audit_events',{method:'POST',headers:headers,body:JSON.stringify(legacy)});
  }).catch(function(){});
}
function auditApiMutation(path,method,o,response){
  try{
    method=(method||'GET').toUpperCase();
    var table=auditTableFromPath(path);
    if(!tok||!prof)return;
    if(method==='GET'){
      var readId=auditRelatedIdFromPath(path),readRow=Array.isArray(response)?response[0]:response,readSensitivity=auditSensitivity(table,readRow||{});
      if(readId&&readSensitivity!=='standard'&&table!=='audit_events')auditPostEntry({company_id:auditCompanyId(readRow||{},path),actor_user_id:prof?.id||null,actor_name:prof?.full_name||prof?.email||'User',actor_role:activeRole(),action:'open_sensitive',module_name:auditModuleForRecord(table,readRow||{}),related_table:table,related_id:readId,related_ref:auditRecordLabel(readRow||{})||null,event_code:auditModuleForRecord(table,readRow||{})+'.open_sensitive',correlation_id:auditUuid(),outcome:'success',sensitivity:readSensitivity,summary:'Sensitive '+auditLabel(table)+' record opened',details:{method:'GET',path:path,access_surface:'record_query'}});
      return;
    }
    if(!table||table==='audit_events'||table==='notification_events'||table==='record_relationships'||table==='rpc'||/_audit_events$/.test(table))return;
    var body=o?.b||{};
    var action=auditSemanticAction(table,method,body);
    var first=Array.isArray(response)?response[0]:response;
    var relatedId=first?.id||body?.id||auditRelatedIdFromPath(path);
    var label=auditRecordLabel(first||body);
    var entry={
      company_id:auditCompanyId(body,path),
      actor_user_id:prof?.id||null,
      actor_name:prof?.full_name||prof?.email||'User',
      actor_role:activeRole(),
      action:action,
      module_name:auditModuleForRecord(table,first||body),
      related_table:table,
      related_id:relatedId,
      related_ref:label||null,
      relationship_id:table==='record_relationships'?relatedId:null,
      correlation_id:auditUuid(),
      event_code:auditModuleForRecord(table,first||body)+'.'+action,
      outcome:'success',
      sensitivity:auditSensitivity(table,first||body),
      summary:auditLabel(action)+' '+auditLabel(table)+(label?' - '+label:''),
      details:{method:method,path:path,changed_fields:auditChangedFields(body),record_label:label}
    };
    auditPostEntry(entry);
  }catch(_){}
}
function auditLogEvent(action,moduleName,summary,details,opts){
  try{
    if(!tok||!prof)return;
    opts=opts||{};
    var table=opts.related_table||moduleName||'system';
    if(action==='open'&&auditSensitivity(table,details)!=='standard')action='open_sensitive';
    var entry={
      company_id:opts.company_id||auditCompanyId(details||{},'')||prof?.company_id||null,
      actor_user_id:prof?.id||null,
      actor_name:prof?.full_name||prof?.email||'User',
      actor_role:activeRole(),
      action:action,
      module_name:moduleName||'system',
      related_table:table,
      related_id:opts.related_id||null,
      related_ref:opts.related_ref||auditRecordLabel(details||{})||null,
      relationship_id:opts.relationship_id||null,
      correlation_id:opts.correlation_id||auditUuid(),
      event_code:(moduleName||auditModuleForRecord(table,details))+'.'+action,
      outcome:opts.outcome||'success',
      sensitivity:opts.sensitivity||auditSensitivity(table,details),
      summary:summary||auditLabel(action)+' '+auditLabel(moduleName||'system'),
      details:details||{},
      user_agent:navigator.userAgent||null
    };
    auditPostEntry(entry);
  }catch(_){}
}
