// -- kpiSaveObjective & openObjModal (KPI module) ------------------------------
// -- openObjModal - opens the add/edit objective modal ----------------
// Called with no args (or null) ? create new objective
// Called with an objective ID ? edit existing objective
var kpiEditObjId = null;  // tracks which objective is being edited (null = creating new)
function openObjModal(objId) {
  var m = document.getElementById('obj-modal');
  if (!m) return;

  // Common: get form references
  var nameEl  = document.getElementById('obj-name');
  var codeEl  = document.getElementById('obj-code');
  var yearEl  = document.getElementById('obj-year');
  var titleEl = document.getElementById('obj-modal-title');
  var delBtn  = document.getElementById('obj-delete-btn');
  var picker  = document.getElementById('kpi-color-picker');

  // Reset all colour dots to unselected state, then pick green by default
  if (picker) {
    picker.querySelectorAll('.kpi-color-dot').forEach(function(d){
      d.style.border = '2px solid transparent';
    });
  }

  if (objId && typeof kpiObjectives !== 'undefined') {
    // -- EDIT MODE -------------------------------------------------
    var obj = kpiObjectives.find(function(o){ return o.id === objId; });
    if (!obj) {
      toast('Objective not found', false);
      return;
    }

    // Pre-fill form fields with existing values
    if (nameEl) nameEl.value = obj.name || '';
    if (codeEl) codeEl.value = obj.code || '';
    if (yearEl) yearEl.value = obj.year || new Date().getFullYear();

    // Set selected colour and highlight the matching dot
    if (typeof kpiSelectedColor !== 'undefined') {
      kpiSelectedColor = obj.color || '#1D9E75';
    }
    if (picker) {
      picker.querySelectorAll('.kpi-color-dot').forEach(function(d){
        // Each dot has its hex set inline via background:#XXXXXX in the onclick
        var onclickStr = d.getAttribute('onclick') || '';
        var match = onclickStr.match(/kpiSelectColor\('([^']+)'/);
        if (match && match[1] === obj.color) {
          d.style.border = '3px solid var(--text)';
        }
      });
    }

    // Set edit mode markers
    m.dataset.editId = objId;
    if (typeof kpiEditObjId !== 'undefined' || true) { kpiEditObjId = objId; }
    if (titleEl) titleEl.textContent = 'Edit objective';
    if (delBtn) delBtn.style.display = '';  // show delete button
  } else {
    // -- CREATE MODE -----------------------------------------------
    // Clear all fields
    if (nameEl) nameEl.value = '';
    if (codeEl) codeEl.value = '';
    if (yearEl) yearEl.value = String(new Date().getFullYear());

    // Reset selected colour to default green and highlight that dot
    if (typeof kpiSelectedColor !== 'undefined') {
      kpiSelectedColor = '#1D9E75';
    }
    if (picker) {
      var firstDot = picker.querySelector('.kpi-color-dot');
      if (firstDot) firstDot.style.border = '3px solid var(--text)';
    }

    // Clear edit mode markers
    delete m.dataset.editId;
    kpiEditObjId = null;
    if (titleEl) titleEl.textContent = 'Add objective';
    if (delBtn) delBtn.style.display = 'none';
  }

  // Show the modal
  m.style.display = 'flex';
}

async function kpiSaveObjective() {
  // Read from the actual form fields (obj-name, obj-year, obj-code)
  var name = document.getElementById('obj-name')?.value?.trim();
  if (!name) { toast('Please enter an objective name', false); return; }
  var year = parseInt(document.getElementById('obj-year')?.value) || new Date().getFullYear();
  var code = document.getElementById('obj-code')?.value?.trim() || null;
  // Colour: read from the global kpiSelectedColor (set by kpiSelectColor()), fallback to green
  var color = (typeof kpiSelectedColor !== 'undefined' && kpiSelectedColor) ? kpiSelectedColor : '#1D9E75';
  // Determine if we're editing (kpiEditObjId set by openObjModal) or creating
  var editId = kpiEditObjId || null;

  try {
    // Auto-generate code if blank: look at existing objectives for this year and increment
    if (!code) {
      var lookupCompany = (isSA() && sephsCompanyContext) ? sephsCompanyContext : prof?.company_id;
      var existing = await api('/objectives?select=code&year=eq.'+year+(lookupCompany?'&company_id=eq.'+lookupCompany:''));
      var maxCode = 0;
      (existing||[]).forEach(function(o){
        var n = parseInt(o.code);
        if (!isNaN(n) && n>maxCode) maxCode = n;
      });
      code = String(maxCode + 1);
    }

    var payload = {
      // If sephs_admin has selected a specific company via the switcher, save under that.
      // Otherwise fall back to user's own company_id.
      company_id: (isSA() && sephsCompanyContext) ? sephsCompanyContext : prof?.company_id,
      name: name,
      code: code,
      year: year,
      color: color
    };

    if (editId) {
      // Update existing objective
      await api('/objectives?id=eq.'+editId, {m:'PATCH', p:'return=minimal', b: payload});
      toast('Objective updated');
    } else {
      // Create new - created_by tracks who created it
      payload.created_by = prof?.id;
      await api('/objectives', {m:'POST', p:'return=minimal', b: payload});
      toast('Objective saved');
    }

    // Close modal, clear edit-id, reset form, reload
    var m = document.getElementById('obj-modal');
    if (m) {
      m.style.display='none';
      delete m.dataset.editId;
    }
    kpiEditObjId = null;
    // Clear form fields
    var nameEl = document.getElementById('obj-name'); if(nameEl) nameEl.value = '';
    var codeEl = document.getElementById('obj-code'); if(codeEl) codeEl.value = '';

    if (typeof kpiLoadAll === 'function') kpiLoadAll();
  } catch(e) {
    toast(actionErrorMessage('Save KPI objective','Objectives & KPIs',e.message||e), false);
    console.error('kpiSaveObjective error:', e);
  }
}

// -- Print the KPI scorecard ---------------------------------------------
// Builds a clean print-only document with just the data - no sidebar, top bar,
// buttons, or coloured objective banners. The currently-active tab determines
// what gets printed (Overview = objectives & KPIs table; Monthly Follow-up =
// the matrix view).
function kpiPrint() {
  var page = document.getElementById('page-kpi');
  if (!page || page.style.display === 'none') {
    if (typeof toast === 'function') toast('Open the Objectives & KPIs page first', false);
    return;
  }

  // Decide which view is currently active
  var overviewTab = document.getElementById('kpi-tab-overview');
  var monthlyTab = document.getElementById('kpi-tab-monthly');
  var printingOverview = overviewTab && overviewTab.style.display !== 'none';

  // Build context strings: company name, year, date
  // Resolution order:
  //   1. sephs_admin with a selected company ? use that company's name
  //   2. sephs_admin with no selection ? "All companies"
  //   3. Other users ? their own company name (co.name)
  //   4. Fallback ? "AURIS360"
  var companyName = 'AURIS360';
  if (isSA()) {
    if (sephsCompanyContext && typeof saCompanyList !== 'undefined') {
      var c = saCompanyList.find(function(x){ return x.id === sephsCompanyContext; });
      companyName = c ? c.name : 'AURIS360';
    } else {
      companyName = 'All companies';
    }
  } else if (typeof co !== 'undefined' && co?.name) {
    companyName = co.name;
  }
  var year = document.getElementById('year-sel')?.value || new Date().getFullYear();
  var generatedOn = new Date().toLocaleDateString('en-GB', { day:'numeric', month:'long', year:'numeric' });

  // Build the print document body - clean HTML for paper
  var html = '';
  html += '<div class="print-doc">';
  html += '<div class="print-doc-header">';
  html += '<div class="print-doc-title">Objectives &amp; KPIs Scorecard</div>';
  html += '<div class="print-doc-sub">'+kpiPrintEsc(companyName)+' &middot; '+year+'</div>';
  html += '<div class="print-doc-meta">Generated on '+generatedOn+(printingOverview?' &middot; Overview':' &middot; Monthly Follow-up')+'</div>';
  html += '</div>';

  if (printingOverview) {
    html += kpiBuildPrintOverview();
  } else {
    html += kpiBuildPrintMonthly(year);
  }

  html += '<div class="print-doc-footer">AURIS360 &middot; '+kpiPrintEsc(companyName)+'</div>';
  html += '</div>';

  // Inject into the page (inside a print-only wrapper)
  var wrapper = document.getElementById('kpi-print-wrapper');
  if (!wrapper) {
    wrapper = document.createElement('div');
    wrapper.id = 'kpi-print-wrapper';
    document.body.appendChild(wrapper);
  }
  wrapper.innerHTML = html;

  // Temporarily override document.title so the browser's print auto-header
  // shows our scorecard title instead of whatever stale value is cached.
  // This is what the browser stamps at the top of every printed page.
  var originalTitle = document.title;
  var printTitle = 'KPI Scorecard - ' + companyName + ' - ' + year;
  document.title = printTitle;

  // Print
  document.body.classList.add('kpi-printing-clean');
  setTimeout(function(){
    window.print();
    setTimeout(function(){
      document.body.classList.remove('kpi-printing-clean');
      if (wrapper && wrapper.parentNode) wrapper.parentNode.removeChild(wrapper);
      // Restore the original title after the print dialog has been dismissed
      document.title = originalTitle;
    }, 400);
  }, 100);
}

// Lightweight HTML-escape for print fields
function kpiPrintEsc(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }

// Helper: nice label for KPI status
function kpiPrintStatusLabel(st){
  if(st==='on_track') return 'On Track';
  if(st==='at_risk') return 'At Risk';
  if(st==='off_track') return 'Off Track';
  if(st==='not_started') return 'Not Started';
  return st || '--';
}

// Helper: format target with operator + unit (re-uses kpiFmtTarget if available)
function kpiPrintFmtTarget(ind){
  if (typeof kpiFmtTarget === 'function') return kpiFmtTarget(ind);
  var op = ind?.target_operator==='lte'?'=':ind?.target_operator==='eq'?'=':'=';
  return op+' '+(ind?.target_value!=null?ind.target_value:'--')+(ind?.unit?' '+ind.unit:'');
}

// Build the overview document content
function kpiBuildPrintOverview() {
  if (!kpiObjectives || !kpiObjectives.length) {
    return '<div class="print-doc-empty">No objectives have been set up yet.</div>';
  }
  var html = '';
  kpiObjectives.forEach(function(obj){
    var objKPIs = (kpiKPIs||[]).filter(function(k){ return k.objective_id === obj.id; });
    html += '<div class="print-obj-section">';
    html += '<div class="print-obj-title">'+kpiPrintEsc(obj.code||'')+'. '+kpiPrintEsc(obj.name||'')+'</div>';
    if (!objKPIs.length) {
      html += '<div class="print-obj-empty">No KPIs defined for this objective.</div>';
    } else {
      html += '<table class="print-table"><thead><tr>';
      html += '<th style="width:46px">Code</th>';
      html += '<th>KPI</th>';
      html += '<th>Measurement Indicator</th>';
      html += '<th style="width:80px;text-align:center">Target</th>';
      html += '<th style="width:110px">Responsible</th>';
      html += '<th style="width:90px;text-align:center">Status</th>';
      html += '</tr></thead><tbody>';
      objKPIs.forEach(function(k){
        var inds = (kpiIndicators||[]).filter(function(i){return i.kpi_id===k.id;});
        if (!inds.length) {
          html += '<tr>';
          html += '<td>'+kpiPrintEsc(k.code||'')+'</td>';
          html += '<td><strong>'+kpiPrintEsc(k.name||'')+'</strong><div class="print-kpi-freq">'+kpiPrintEsc(k.frequency||'monthly')+'</div></td>';
          html += '<td style="color:#888;font-style:italic">No indicators</td>';
          html += '<td style="text-align:center">--</td>';
          html += '<td>'+kpiPrintEsc(k.responsible||'--')+'</td>';
          html += '<td style="text-align:center">'+kpiPrintStatusLabel(k.status)+'</td>';
          html += '</tr>';
        } else {
          inds.forEach(function(ind, idx){
            html += '<tr>';
            if (idx === 0) {
              html += '<td rowspan="'+inds.length+'">'+kpiPrintEsc(k.code||'')+'</td>';
              html += '<td rowspan="'+inds.length+'"><strong>'+kpiPrintEsc(k.name||'')+'</strong><div class="print-kpi-freq">'+kpiPrintEsc(k.frequency||'monthly')+'</div></td>';
            }
            html += '<td>'+kpiPrintEsc(ind.name||'')+'</td>';
            html += '<td style="text-align:center">'+kpiPrintFmtTarget(ind)+'</td>';
            if (idx === 0) {
              html += '<td rowspan="'+inds.length+'">'+kpiPrintEsc(k.responsible||'--')+'</td>';
              html += '<td rowspan="'+inds.length+'" style="text-align:center">'+kpiPrintStatusLabel(k.status)+'</td>';
            }
            html += '</tr>';
          });
        }
      });
      html += '</tbody></table>';
    }
    html += '</div>';
  });
  return html;
}

// Build the monthly follow-up table for printing
function kpiBuildPrintMonthly(year) {
  if (!kpiObjectives || !kpiObjectives.length) {
    return '<div class="print-doc-empty">No data to display.</div>';
  }
  var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  var html = '<table class="print-table print-monthly"><thead><tr>';
  html += '<th style="width:38px">No.</th>';
  html += '<th>KPI</th>';
  html += '<th>Indicator</th>';
  html += '<th style="width:55px;text-align:center">Target</th>';
  months.forEach(function(m){ html += '<th style="text-align:center;min-width:34px">'+m+'</th>'; });
  html += '<th style="text-align:center;background:#f0f9f4;width:48px"><strong>YTD</strong></th>';
  html += '<th style="width:70px;text-align:center">Status</th>';
  html += '</tr></thead><tbody>';

  kpiObjectives.forEach(function(obj){
    var objKPIs = (kpiKPIs||[]).filter(function(k){return k.objective_id===obj.id;});
    if (!objKPIs.length) return;
    // Section divider row
    html += '<tr class="print-section-row"><td colspan="'+(5+months.length+1)+'"><strong>'+kpiPrintEsc(obj.code||'')+'. '+kpiPrintEsc(obj.name||'')+'</strong></td></tr>';
    objKPIs.forEach(function(k){
      var inds = (kpiIndicators||[]).filter(function(i){return i.kpi_id===k.id;});
      if (!inds.length) return;
      inds.forEach(function(ind, idx){
        html += '<tr>';
        if (idx === 0) {
          html += '<td rowspan="'+inds.length+'">'+kpiPrintEsc(k.code||'')+'</td>';
          html += '<td rowspan="'+inds.length+'"><strong>'+kpiPrintEsc(k.name||'')+'</strong></td>';
        }
        html += '<td>'+kpiPrintEsc(ind.name||'')+'</td>';
        html += '<td style="text-align:center">'+kpiPrintFmtTarget(ind)+'</td>';
        // Monthly values for this indicator
        var data = (kpiMonthlyData && kpiMonthlyData[ind.id]) || {};
        var ytdVal = null;
        for (var m = 1; m <= 12; m++) {
          var d = data[m];
          var actual = d?.actual != null ? d.actual : null;
          if (d?.ytd != null) ytdVal = d.ytd;
          html += '<td style="text-align:center">'+(actual != null ? actual : '-')+'</td>';
        }
        html += '<td style="text-align:center;background:#f0f9f4"><strong>'+(ytdVal!=null?ytdVal:'-')+'</strong></td>';
        if (idx === 0) {
          html += '<td rowspan="'+inds.length+'" style="text-align:center">'+kpiPrintStatusLabel(k.status)+'</td>';
        }
        html += '</tr>';
      });
    });
  });
  html += '</tbody></table>';
  return html;
}



