  unsafe_condition:   { emoji:'!', label:'Unsafe Condition',   color:'#C2410C',  bg:'#FEF6E7', banner:'linear-gradient(135deg,#7C2D12,#C2410C)' },
  bbs_observation:    { emoji:'BBS', label:'BBS Observation',     color:'#185FA5',  bg:'#EFF6FF', banner:'linear-gradient(135deg,#0F6E56,#185FA5)' },
  near_miss:          { emoji:'?', label:'Near Miss',           color:'#7C3AED',  bg:'#EDE9FE', banner:'linear-gradient(135deg,#3B0764,#7C3AED)' },
