// Controlled rollout cohorts (AP-062). No saved rows means compatibility mode:
// existing companies.module_access and role rules continue to apply unchanged.
var ROLLOUT_COHORTS=[
  {key:'core_control',label:'Core Control',modules:['actions','events','inspection','risk']},
  {key:'controlled_content',label:'Controlled Content',modules:['permit','swms','documents','legal','sop']},
  {key:'people_health',label:'People & Health',modules:['training','people','ppe','ohealth']},
  {key:'specialist_operations',label:'Specialist Operations',modules:['observation','engagement','contractor','tools','emergency','esg','noise']}
];
var rolloutRuntimeRows=[];
function rolloutCompanyId(){return (isSA()&&sephsCompanyContext)?sephsCompanyContext:prof?.company_id||null;}
function rolloutCohortForModule(pageKey){return ROLLOUT_COHORTS.find(function(c){return c.modules.indexOf(pageKey)!==-1;})||null;}
function rolloutStatusAllowsModules(status){return status==='pilot'||status==='enabled';}
function rolloutModuleAllowed(pageKey){
  if(isSA())return true;
  var cohort=rolloutCohortForModule(pageKey);if(!cohort)return true;
  var row=(rolloutRuntimeRows||[]).find(function(r){return r.cohort_key===cohort.key;});
  if(!row)return true; // Compatibility read: no explicit rollout policy yet.
  return rolloutStatusAllowsModules(row.status);
}
async function loadRolloutRuntimeConfig(){
  var companyId=rolloutCompanyId();rolloutRuntimeRows=[];if(!companyId)return [];
  try{rolloutRuntimeRows=await api('/company_rollout_cohorts?select=*&company_id=eq.'+encodeURIComponent(companyId))||[];}
  catch(e){if(!/company_rollout_cohorts|schema cache|does not exist|not found/i.test(String(e.message||e)))console.warn('Rollout configuration unavailable',e);rolloutRuntimeRows=[];}
  return rolloutRuntimeRows;
}

// Returns true if the current user's role is allowed to access `pageKey`.
// THREE gates, all must pass:
//   1. Feature flag (LAUNCHED_MODULES) - is the module globally enabled?
//   2. Per-company access (companies.module_access) - does this client have it enabled?
//   3. Role allow-list (ROLE_ALLOWED) - does this user's role permit it?
// sephs_admin bypasses gate 2 (they see everything they manage).
function canAccessPage(pageKey) {
  // Admin/account pages (Users & Roles, Settings, Companies, Integrations,
  // Executive Dashboard, AI Insights) are platform functions, NOT HSE
  // modules. They bypass the launch flag (Gate 1) and the per-company
  // module list (Gate 2), and are governed by role only (Gate 3).
  var ADMIN_PAGES = ['users','settings','admin','integrations','executive','ai-insights','approvals','audit'];
  var isAdminPage = ADMIN_PAGES.indexOf(pageKey) !== -1;
  var companyModuleAccess = co && Array.isArray(co.module_access) ? co.module_access : null;
  var currentLiveModules = (typeof moduleLiveKeys === 'function') ? moduleLiveKeys() : (typeof LAUNCHED_MODULES !== 'undefined' ? LAUNCHED_MODULES : []);
  var isLegacyRolloutAccess = companyModuleAccess && companyModuleAccess.length > 0 && companyModuleAccess.length < Math.min(12, currentLiveModules.length || 12);
  if(pageKey === 'ai-insights') {
    if(typeof canUseAI === 'function' && !canUseAI()) return false;
    try {
      if(typeof AI_AVAILABLE !== 'undefined' && !AI_AVAILABLE && !isSA()) return false;
    } catch(e) {}
  }
  if(pageKey === 'audit') {
    if(['sephs_admin','admin','hse_manager','hse_officer'].indexOf(activeRole()) === -1) return false;
  }
  if(pageKey === 'approvals') {
    if(['sephs_admin','admin','hse_manager','hse_officer'].indexOf(activeRole()) === -1) return false;
  }
  if(!rolloutModuleAllowed(pageKey)) return false;

  // Legacy rollout guard: old client records may still have a short module list
  // from the early rollout. Treat those as "full production access by role" so
  // built modules do not disappear. Larger saved lists remain intentional
  // company-level restrictions.
  if(!isSA() && companyModuleAccess && !isLegacyRolloutAccess && pageKey !== 'dashboard' && !isAdminPage) {
    if(companyModuleAccess.indexOf(pageKey) === -1) return false;
  }

  // Gate 1: Feature flag. Dashboard + admin pages always pass.
  if(pageKey !== 'dashboard' && !isAdminPage && !isModuleLaunched(pageKey)) return false;

  // Gate 2: Per-company module access. sephs_admin sees everything.
  if(pageKey !== 'dashboard' && !isAdminPage && !isSA()) {
    // co is the global company object loaded with the profile.
    // If module_access is NULL/missing ? fall back to allowing access (no regression).
    // If module_access is an array ? check membership.
    if(companyModuleAccess && !isLegacyRolloutAccess) {
      if(companyModuleAccess.indexOf(pageKey) === -1) return false;
    }
  }

  // Gate 3: Role allow-list.
  var role = activeRole();
  var allowed = Object.prototype.hasOwnProperty.call(ROLE_ALLOWED, role) ? ROLE_ALLOWED[role] : (ROLE_ALLOWED.user || ['dashboard']);
  if(allowed === null) return true;  // null = sees all.
  return allowed.indexOf(pageKey) !== -1;
}

function closeTransientOverlays(){
  [
    'obj-modal',
    'kpi-edit-modal',
    'kpi-entry-modal',
    'hse-cc-detail-modal',
    'client-meeting-checklist-modal',
    'client-demo-review-modal',
    'mobile-search-overlay',
    'mobile-modules-drawer',
    'sidebar-backdrop',
    'modules-menu',
    'sa-company-menu'
  ].forEach(function(id){
    var el=document.getElementById(id);
    if(!el)return;
    el.classList.remove('open','active');
    if(id === 'modules-menu' || id === 'sa-company-menu') {
      el.style.display = '';
    } else {
      el.style.display='none';
    }
  });
  document.querySelectorAll('.modules-menu.open,.hse-cc-modal').forEach(function(el){
    el.classList.remove('open','active');
    if(el.classList && el.classList.contains('modules-menu')) {
      el.style.display = '';
    } else {
      el.style.display='none';
    }
  });
  var mobilePanel=document.getElementById('mobile-modules-panel');
  if(mobilePanel){
    mobilePanel.classList.remove('open','active');
    mobilePanel.style.transform='translateY(100%)';
  }
  if(typeof _modulesOpen!=='undefined')_modulesOpen=false;
}

