// -- Personal dashboard render -------------------------------------------
function dashRenderDemoReadiness(data){
  var panel=document.getElementById('dash-demo-readiness');
  if(!panel)return;
  var canSee=isSA();
  panel.style.display=canSee&&!isPersonalDashRole()?'block':'none';
  if(panel.style.display==='none')return;
  data=data||{};
  var checks=[
    {label:'People register', count:(data.people||[]).length, target:3, page:'people', action:'Add people'},
    {label:'Incident example', count:(data.events||[]).length, target:1, page:'events', action:'Open incidents'},
    {label:'BBS observations', count:(data.observations||[]).length, target:1, page:'observation', action:'Open BBS'},
    {label:'Master actions', count:(data.actions||[]).length, target:1, page:'actions', action:'Open MAP'},
    {label:'Risk assessments', count:(data.riskAssessments||[]).length, target:1, page:'risk', action:'Open RA'},
    {label:'Legal register', count:(data.legal||[]).length, target:5, page:'legal', action:'Open legal'},
    {label:'Chemical register', count:(data.chemicals||[]).length, target:1, page:'chemical', action:'Open chemicals'},
    {label:'Inspection records', count:(data.inspections||[]).length, target:1, page:'inspection', action:'Open audits'}
  ].filter(function(x){return canAccessPage(x.page);});
  var ready=checks.filter(function(x){return x.count>=x.target;}).length;
  var pct=checks.length?Math.round(ready/checks.length*100):0;
  var tone=pct>=80?'#1D9E75':pct>=50?'#EF9F27':'#DC2626';
  var body=document.getElementById('dash-demo-readiness-body');
  var score=document.getElementById('dash-demo-readiness-score');
  var bar=document.getElementById('dash-demo-readiness-bar');
  if(score)score.textContent=pct+'% ready';
  if(bar){bar.style.width=pct+'%';bar.style.background=tone;}
  if(body)body.innerHTML=checks.map(function(x){
    var ok=x.count>=x.target;
    return '<div style="display:grid;grid-template-columns:26px 1fr auto auto;gap:10px;align-items:center;padding:9px 0;border-top:1px solid var(--border)">'
      +'<div style="width:22px;height:22px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:'+(ok?'#E1F5EE':'#FEF9EC')+';color:'+(ok?'#0F6E56':'#854F0B')+'"><i class="ti '+(ok?'ti-check':'ti-alert-circle')+'"></i></div>'
      +'<div><div style="font-size:13px;font-weight:800">'+escH(x.label)+'</div><div style="font-size:11px;color:var(--text2)">'+x.count+' of '+x.target+' minimum readiness record'+(x.target>1?'s':'')+'</div></div>'
      +'<span class="badge '+(ok?'bg':'ba')+'">'+(ok?'Ready':'Needs data')+'</span>'
      +'<button class="btn btn-sm" data-auris-runtime-onclick="r0009" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.page]))+'">'+escH(x.action)+'</button>'
      +'</div>';
  }).join('');
}

function dashOpenMeetingChecklist(){
  if(!isSA()){toast('Internal SEPHS go-live readiness tools are not available for this role.',false);return;}
  var modal=document.getElementById('client-meeting-checklist-modal');
  if(!modal){
    modal=document.createElement('div');
    modal.id='client-meeting-checklist-modal';
    modal.style.cssText='display:none;position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:930;align-items:center;justify-content:center;padding:18px';
    modal.innerHTML='<div class="card" role="dialog" aria-modal="true" aria-labelledby="client-meeting-checklist-title" style="width:100%;max-width:760px;max-height:86vh;overflow:hidden;border-radius:12px;box-shadow:0 20px 70px rgba(15,23,42,.28);padding:0">'
      +'<div style="padding:16px 18px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:flex-start;gap:12px">'
      +'<div><div id="client-meeting-checklist-title" style="font-size:18px;font-weight:900">Go-live readiness checklist</div><div style="font-size:12px;color:var(--text2);margin-top:3px">Use this before client launch to confirm records, workflows, governance and support are ready.</div></div>'
      +'<button class="btn btn-sm" data-auris-generated-onclick="g0022"><i class="ti ti-x"></i></button>'
      +'</div>'
      +'<div style="padding:16px 18px;overflow:auto;max-height:calc(86vh - 120px)">'
      +'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px" id="client-meeting-checklist-body"></div>'
      +'<div style="margin-top:14px;padding:12px;border:1px solid #bfdbfe;background:#EFF6FF;border-radius:10px;color:#1e40af;font-size:12px;line-height:1.55"><strong>Go-live review rule:</strong> confirm the complete operating flow, not every screen. Start with Dashboard, then Incident/BBS, then Action Plan, then Audit Trail. Open advanced modules only when they match the client need.</div>'
      +'</div>'
      +'<div style="padding:12px 18px;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:8px"><button class="btn" data-auris-generated-onclick="g0023"><i class="ti ti-printer"></i>Print</button><button class="btn btn-primary" data-auris-generated-onclick="g0022">Done</button></div>'
      +'</div>';
    modal.onclick=function(e){if(e.target===modal)dashCloseMeetingChecklist();};
    document.body.appendChild(modal);
  }
  var items=[
    ['Company context','Select the correct client company or All companies before presenting. Confirm the sidebar name and dashboard context match the story.'],
    ['Minimum readiness records','Prepare at least 3 people, 1 incident with evidence, 1 BBS observation, 1 MAP action, 1 risk assessment, 1 chemical and 1 legal register import.'],
    ['Incident workflow','Show Report incident, evidence/photos, saved incident view, manager classification and action follow-up. Avoid editing submitted employee records during the review.'],
    ['BBS workflow','Show a positive observation and one unsafe condition with a corrective action link to the Master Action Plan.'],
    ['Master Action Plan','Show table filters, owner/due date, priority, source link, verification and closure concept. This is the central follow-up register.'],
    ['Permit to Work','Show the register, permit type selection, RA/method statement references, two-column controls and approval routing settings.'],
    ['Legal compliance','Show imported legislation sections, ascending references, compliance status and how gaps create actions.'],
    ['Chemical control','Show SDS/MSDS extraction, use/exposure fields, persons exposed, risk rating and control recommendations.'],
    ['Approval and audit','Show Approval Center and Audit Trail as professional governance features: who did what, when, and what changed.'],
    ['Mobile story','Explain mobile is primarily for field reporting: incident, BBS, photo evidence and quick access. Keep desktop for admin-heavy workflows.']
  ];
  var body=document.getElementById('client-meeting-checklist-body');
  if(body)body.innerHTML=items.map(function(x){
    return '<div style="border:1px solid var(--border);border-radius:10px;padding:12px;background:#fff">'
      +'<div style="font-size:13px;font-weight:900;margin-bottom:6px;display:flex;align-items:center;gap:7px"><i class="ti ti-check" style="color:var(--green)"></i>'+escH(x[0])+'</div>'
      +'<div style="font-size:12px;color:var(--text2);line-height:1.5">'+escH(x[1])+'</div>'
      +'</div>';
  }).join('');
  modal.style.display='flex';
}

function dashCloseMeetingChecklist(){
  var modal=document.getElementById('client-meeting-checklist-modal');
  if(modal)modal.style.display='none';
}

function clientDemoItems(){
  return {
    ready:[
      ['Dashboard story','Executive snapshot, live KPIs, days since LTI, open actions and risk indicators.'],
      ['Incident reporting','Mobile-friendly report flow, evidence photos, classification, investigation trigger and notifications.'],
      ['BBS observations','Positive/unsafe observations, PPE status, corrective action link and trend view.'],
      ['Master Action Plan','Single table for actions from incidents, inspections, legal gaps, BBS and manual tasks.'],
      ['Audit Trail','Chronological trace of key actions, login/logout, AI use, exports and offline sync.'],
      ['Offline field drafts','Incident/BBS reports can be saved offline with compressed photos and synced later.']
    ],
    rollout:[
      ['Permit to Work','Strong workflow direction with approval routing, gas tests, isolations and precautions. Best shown as controlled rollout.'],
      ['Legal Compliance','PDF legislation import, section sorting, register, gaps and compliance scoring. Needs client-specific legal validation.'],
      ['Chemical Control','SDS extraction and exposure/risk fields are valuable. Position as AI-assisted, not a legal SDS replacement.'],
      ['AI Insights','Good wow factor for summaries, toolbox talks, RAMS and analysis. Explain it is governed by role access and API cost.'],
      ['No-code fields','Company admins can add Incident/BBS fields without programming. Show only if client asks about customisation.']
    ],
    avoid:[
      ['Do not show every module','Use a complete safety story rather than opening 25 modules one by one.'],
      ['Do not promise legal compliance automation','Say AURIS360 helps structure and monitor obligations; expert validation remains required.'],
      ['Do not over-promise offline mode','Offline is currently for Incident/BBS field drafts, not the whole platform.'],
      ['Do not discuss unconfigured integrations as active','ERP/SIRH/LDAP/BI integrations need client-specific API access, mapping and testing before activation.']
    ],
    flow:[
      ['1','Open Dashboard','Show overall HSE cockpit and explain -one source of truth-.'],
      ['2','Report an Incident','Create or open an example with photo evidence and classification.'],
      ['3','Show BBS','Validate observation capture and links to safety behaviour culture.'],
      ['4','Open Master Action Plan','Show how findings become accountable actions.'],
      ['5','Open Audit Trail','Close with governance: who did what, when, and what changed.'],
      ['6','Finish with expansion options','Mention legal, chemicals, PTW, AI and integrations as configurable expansion areas.']
    ]
  };
}

function clientDemoModuleMatrix(){
  return [
    {page:'dashboard',module:'Dashboard',status:'show',story:'Executive cockpit: LTI days, open incidents, overdue actions, KPIs and operational signals.',caution:'Use this as the opening story, not as a data-entry screen.'},
    {page:'events',module:'Incident Management',status:'show',story:'Mobile report, evidence photos, manager classification, investigation trigger and linked actions.',caution:'Use prepared readiness data so the flow is clean.'},
    {page:'observation',module:'BBS Observations',status:'show',story:'Behaviour observation across positive behaviour, unsafe behaviour and unsafe condition with action follow-up.',caution:'Explain it supports culture and coaching, not blame.'},
    {page:'actions',module:'Master Action Plan',status:'show',story:'Single follow-up table fed by incidents, inspections, legal gaps, BBS and manual actions.',caution:'This is the close-the-loop proof; always show it.'},
    {page:'risk',module:'Risk Assessment / RAMS',status:'show',story:'Task steps, hazards, existing controls, further controls, residual risk, matrix and SWMS/RAMS linkage.',caution:'Position AI import/generation as assistant output requiring HSE review.'},
    {page:'swms',module:'SWMS / Method Statements',status:'show',story:'Work method, hazards and controls, tools/equipment, emergency arrangements and print-ready method statement.',caution:'Keep SWMS separate from RA but linked as part of RAMS pack.'},
    {page:'permit',module:'Permit to Work',status:'rollout',story:'Permit type, RA/SWMS references, controls, gas tests, isolation, approval route and closure.',caution:'Show as advanced workflow/rollout unless client already needs PTW.'},
    {page:'inspection',module:'Audits & Inspections',status:'show',story:'Inspection templates, findings, evidence, AI review, action generation and print report.',caution:'Select the correct inspection template before the review.'},
    {page:'legal',module:'Legal Compliance',status:'rollout',story:'Import legislation, split into sections, assess status, identify gaps and create actions.',caution:'Do not promise automatic legal compliance; expert validation remains required.'},
    {page:'chemical',module:'Chemical Control',status:'rollout',story:'Chemical register, SDS upload/extraction, exposure profile, persons exposed and risk rating.',caution:'AI extraction supports review; it does not replace SDS validation.'},
    {page:'ppe',module:'PPE Management',status:'show',story:'PPE catalogue, stock/inventory, issue register, inspections, replacements and expiry alerts.',caution:'Use stock vs catalogue distinction clearly.'},
    {page:'tools',module:'Tools & Equipment',status:'show',story:'Equipment register, inspections, lifting accessories, statutory verification, vehicles and RCD testing.',caution:'Use equipment-specific checklists.'},
    {page:'fire',module:'Fire Certificates / Site Layout',status:'rollout',story:'Fire equipment, certificates, inspections and interactive layout with positioned fire assets.',caution:'Use one prepared plan and a few positioned assets.'},
    {page:'contractor',module:'Contractor Management',status:'show',story:'Contractor register, pre-assessment, evaluation, authorisation to work, incidents and live safety score.',caution:'Good differentiator for clients using subcontractors.'},
    {page:'approvals',module:'Approval Center',status:'show',story:'Governance queue for approvals and controlled records.',caution:'Show after a workflow example.'},
    {page:'audit',module:'Audit Trail',status:'show',story:'Chronological proof of user actions and system events.',caution:'Use as a trust/security closing point.'},
    {page:'ai-insights',module:'AI Insights',status:'wow',story:'AI assistant, RAMS/toolbox support, predictive risk, document analysis and HSE insights.',caution:'Mention role restriction and API cost control.'}
  ].filter(function(x){return canAccessPage(x.page);});
}

function renderClientDemoModuleMatrix(){
  var rows=clientDemoModuleMatrix();
  var cfg={show:['#EAF3DE','#3B6D11','Production ready'],rollout:['#FEF9EC','#854F0B','Configuration needed'],wow:['#EDE9FE','#5B21B6','Wow factor']};
  return '<div style="margin-top:14px;border:1px solid var(--border);border-radius:10px;overflow:hidden;background:#fff">'
    +'<div style="padding:11px 12px;background:#0F172A;color:#fff;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><div style="font-weight:900">Module readiness matrix</div><div style="font-size:11px;opacity:.85">What to show, how to position it, and where to be careful</div></div>'
    +'<div style="overflow:auto"><table style="width:100%;min-width:980px;border-collapse:collapse;font-size:12px"><thead><tr style="background:#f8fafc;color:var(--text2);text-transform:uppercase;font-size:10px"><th style="padding:9px 10px;text-align:left">Module</th><th style="padding:9px 10px;text-align:left">Status</th><th style="padding:9px 10px;text-align:left">Client story</th><th style="padding:9px 10px;text-align:left">Caution / positioning</th><th style="padding:9px 10px;text-align:right">Open</th></tr></thead><tbody>'
    +rows.map(function(x,i){var s=cfg[x.status]||cfg.show;return '<tr style="border-top:1px solid var(--border);background:'+(i%2?'#fafafa':'#fff')+'"><td style="padding:10px;font-weight:900">'+escH(x.module)+'</td><td style="padding:10px"><span style="background:'+s[0]+';color:'+s[1]+';padding:3px 9px;border-radius:99px;font-size:11px;font-weight:900;white-space:nowrap">'+s[2]+'</span></td><td style="padding:10px;color:#111827;line-height:1.45">'+escH(x.story)+'</td><td style="padding:10px;color:var(--text2);line-height:1.45">'+escH(x.caution)+'</td><td style="padding:10px;text-align:right"><button class="btn btn-sm" data-auris-runtime-onclick="r0009" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.page]))+'"><i class="ti ti-arrow-right"></i></button></td></tr>';}).join('')
    +'</tbody></table></div></div>';
}
function clientDemoSummaryText(){
  var items=clientDemoItems();
  return 'AURIS360 go-live readiness summary\n\n'
    +'Positioning:\nAURIS360 is a modular HSE management platform designed to centralise incidents, BBS observations, KPIs, actions, audits, permits, legal compliance, chemicals, documents and AI-assisted safety workflows.\n\n'
    +'Recommended go-live review:\n'+items.flow.map(function(x){return x[0]+'. '+x[1]+' - '+x[2];}).join('\n')+'\n\n'
    +'Production strengths:\n'+items.ready.map(function(x){return '- '+x[0]+': '+x[1];}).join('\n')+'\n\n'
    +'Configuration points to confirm:\n'+items.rollout.map(function(x){return '- '+x[0]+': '+x[1];}).join('\n')+'\n\n'
    +'Important boundaries:\n'+items.avoid.map(function(x){return '- '+x[0]+': '+x[1];}).join('\n');
}

function clientDemoObjectionItems(){
  return [
    {q:'Is AURIS360 ready for real clients?',a:'Yes. Core workflows such as incidents, BBS, action tracking, inspections, risk assessment, documents, contractors, dashboards and operational modules are available for client rollout. Advanced workflows should be configured per client scope, approval rules and data requirements.'},
    {q:'Who is responsible for legal compliance?',a:'AURIS360 helps structure the legal register, track obligations, identify gaps and assign actions. Final legal interpretation and validation remains with the competent HSE/legal professional or the client-s appointed advisor.'},
    {q:'Does AI replace the HSE Manager?',a:'No. AI supports drafting, analysis, summaries and pattern recognition. The HSE Manager remains the approver and decision-maker. This is important for governance, cost control and professional liability.'},
    {q:'What about data security?',a:'AURIS360 uses role-based access, company scoping, audit trail, role-based module access and server-side environment secrets. For larger clients, the next step is a formal security/SLA document covering hosting, backups, retention, access control and support.'},
    {q:'Can it work offline?',a:'Offline capability is currently best positioned for field drafts such as incident and BBS reporting with evidence capture. Full offline operation for all modules is a future enterprise feature because sync conflicts and approvals must be carefully controlled.'},
    {q:'Can it integrate with ERP, HR or BI systems?',a:'The platform is being prepared for integrations such as HR lists, ERP work orders, Power BI and document systems. In practice, each integration requires client-specific API access, credentials, mapping and testing.'},
    {q:'How long does implementation take?',a:'A small client rollout can start once the company, users, roles, module access and starter records are configured. A full professional deployment should include data migration, training, workflow approval setup, notification rules and acceptance testing.'},
    {q:'How are email and WhatsApp notifications handled?',a:'Email is the default controlled channel for users with real addresses. App-generated local users need either a manager relay, in-app notification, SMS/WhatsApp integration or temporary password workflow. WhatsApp/SMS implies extra provider cost and consent/privacy controls.'},
    {q:'What makes it different from generic HSE software?',a:'AURIS360 combines HSE modules, action tracking, RAMS/SWMS, field evidence, contractor scoring, fire layout mapping, AI assistance and consultancy-style workflows in one system tailored for practical safety management.'}
  ];
}

