    {page:'ppe',label:'PPE',count:(results[9]||[]).length,target:1,why:'PPE issue/stock story'},
    {page:'permit',label:'PTW',count:(results[10]||[]).length,target:1,why:'high-risk work example'},
    {page:'audit',label:'Audit Trail',count:(results[11]||[]).length,target:1,why:'governance proof'}
