async function dashRenderPersonal(events, actions, people, permits, training) {
  if(!isPersonalDashRole()) return;  // safety: don't run if user is admin

  // 1. Update tagline based on role
  var tagline = document.getElementById('dash-personal-tagline');
  if(tagline) {
    if(prof.role === 'contractor') {
      tagline.textContent = 'Report incidents, log observations, manage your permits.';
    } else if(prof.role === 'inspector') {
      tagline.textContent = 'Log observations, complete inspections, report any issues.';
    } else {
      tagline.textContent = 'Report something, log an observation, or check your training.';
    }
  }

  // Hide permit button if role doesn't have access (canAccessPage handles this)
  var permitBtn = document.getElementById('dash-action-permit');
  if(permitBtn) permitBtn.style.display = canAccessPage('permit') ? '' : 'none';
  var trainingBtn = document.getElementById('dash-action-training');
  if(trainingBtn) trainingBtn.style.display = canAccessPage('training') ? '' : 'none';
  var incidentBtn = document.getElementById('dash-action-incident');
  if(incidentBtn) incidentBtn.style.display = canAccessPage('events') ? '' : 'none';
  var bbsBtn = document.getElementById('dash-action-bbs');
  if(bbsBtn) bbsBtn.style.display = canAccessPage('observation') ? '' : 'none';

  // Find current user's person record (matches profile by email or full_name)
  var myPerson = (people||[]).find(function(p){
    var fullName = (p.first_name+' '+p.last_name).toLowerCase().trim();
    return (p.email && p.email.toLowerCase() === (prof.email||'').toLowerCase())
        || fullName === (prof.full_name||'').toLowerCase().trim();
  });

  // 2. Site-pulse cards
  // Days Since Last Incident - at user's site, or company-wide if no site
  var mySite = myPerson?.site || myPerson?.location || null;
  var siteEvents = mySite
    ? (events||[]).filter(function(x){return x.location===mySite||x.site===mySite;})
    : events || [];
  var lastIncident = siteEvents
    .map(function(x){return new Date(x.event_date||x.created_at||0);})
    .filter(function(d){return !isNaN(d);})
    .sort(function(a,b){return b-a;})[0];
  var daysSinceEl = document.getElementById('dp-days');
  if(daysSinceEl) {
    if(!lastIncident) {
      daysSinceEl.textContent = '-';
      document.getElementById('dp-days-sub').textContent = 'no incidents on record';
    } else {
      var d = Math.floor((Date.now() - lastIncident) / 86400000);
      daysSinceEl.textContent = d;
      document.getElementById('dp-days-sub').textContent = mySite ? 'at '+mySite : 'across the company';
      var card = document.querySelector('.kpi-card[data-id="dp-days"]');
      if(card) card.setAttribute('data-tone', d>=30?'green':d>=7?'amber':'red');
    }
  }

  // Open issues at my site
  var openSite = siteEvents.filter(function(x){return x.status==='open'||x.status==='under_investigation';}).length;
  var oseEl = document.getElementById('dp-site-incidents');
  if(oseEl) {
    oseEl.textContent = openSite;
    document.getElementById('dp-site-incidents-sub').textContent = openSite===0 ? 'all clear' : (openSite===1?'1 active issue':openSite+' active issues');
    var card2 = document.querySelector('.kpi-card[data-id="dp-site-incidents"]');
    if(card2) card2.setAttribute('data-tone', openSite===0?'green':openSite<=2?'amber':'red');
  }

  // My training
  var myTraining = (training||[]).filter(function(t){
    return myPerson && (t.person_id===myPerson.id || (t.person_name||'').toLowerCase()===((myPerson.first_name+' '+myPerson.last_name).toLowerCase().trim()));
  });
  var soon60 = new Date(); soon60.setDate(soon60.getDate()+60);
  var validTraining = myTraining.filter(function(t){return !t.expiry_date||new Date(t.expiry_date)>new Date();});
  var expiringSoon = myTraining.filter(function(t){return t.expiry_date && new Date(t.expiry_date)>new Date() && new Date(t.expiry_date)<soon60;});
  var expired = myTraining.filter(function(t){return t.expiry_date && new Date(t.expiry_date)<=new Date();});
  var tEl = document.getElementById('dp-training');
  if(tEl) {
    tEl.textContent = validTraining.length;
    var sub = validTraining.length===0 ? 'no records' :
              expired.length>0 ? expired.length+' expired ?' :
              expiringSoon.length>0 ? expiringSoon.length+' expiring soon' :
              'all current ?';
    document.getElementById('dp-training-sub').textContent = sub;
    var card3 = document.querySelector('.kpi-card[data-id="dp-training"]');
    if(card3) card3.setAttribute('data-tone', expired.length>0?'red':expiringSoon.length>0?'amber':'green');
  }

  // 3. My Reports - incidents reported by me
  var myReports = (events||[]).filter(function(x){
    return x.reported_by_id === prof.id
        || (x.reported_by && (x.reported_by===prof.email || x.reported_by===prof.full_name))
        || (x.reported_by_name && x.reported_by_name===prof.full_name)
        || x.created_by === prof.id;
  }).slice(0, 5);
  renderPersonalList('dp-my-reports', myReports, function(x){
    return {
      title: x.title || x.description || x.event_type || 'Untitled incident',
      meta: (x.event_date||x.created_at||'').slice(0,10) + ' - ' + (x.event_type||'incident'),
      status: x.status==='closed' ? 'closed' : x.status==='under_investigation' ? 'review' : 'open',
      statusLabel: x.status==='closed' ? 'Closed' : x.status==='under_investigation' ? 'Reviewing' : 'Open',
    };
  }, 'No reports yet - tap "Report an incident" above to file one.');

  // 4. My Observations - BBS observations
  var myObsRaw = await (async function(){
    try {
      return await api('/safety_observations?select=*'+cf()+'&order=created_at.desc&limit=20');
    } catch(e) { return []; }
  })();
  var myObs = (myObsRaw||[]).filter(function(x){
    return x.observer_id === prof.id
        || (x.observer && (x.observer===prof.email || x.observer===prof.full_name))
        || (x.observer_name && x.observer_name===prof.full_name)
        || x.created_by === prof.id;
  }).slice(0, 5);
  renderPersonalList('dp-my-observations', myObs, function(x){
    return {
      title: x.observation_text || x.positive_points || x.unsafe_act_description || x.unsafe_condition_description || 'Observation',
      meta: (x.observation_date||x.created_at||'').slice(0,10) + ' - ' + (x.category||'general'),
      status: x.status==='closed' ? 'closed' : 'open',
      statusLabel: x.status==='closed' ? 'Closed' : 'Logged',
    };
  }, 'No observations yet - tap "Log an observation" above.');

  // 5. Actions Assigned to Me
  var meName = (prof?.full_name||'').toLowerCase();
  var meEmail = (prof?.email||'').toLowerCase();
  var myActions = (actions||[]).filter(function(a){
    return a.assigned_to_id === prof.id
        || (a.assigned_to && String(a.assigned_to).toLowerCase() === meEmail)
        || (a.assigned_to_name && String(a.assigned_to_name).toLowerCase() === meName)
        || (a.responsible && [meName,meEmail].includes(String(a.responsible).toLowerCase()));
  }).filter(function(a){return a.status!=='closed';}).slice(0, 5);
  renderPersonalList('dp-my-actions', myActions, function(x){
    var due = x.target_date || x.due_date;
    var overdue = due && new Date(due) < new Date();
    return {
      title: x.title || x.description || x.instructions || 'Action item',
      meta: (due?'Due '+due.slice(0,10):'No due date') + (x.priority?' - '+x.priority:''),
      status: overdue ? 'overdue' : 'open',
      statusLabel: overdue ? 'Overdue' : (x.priority?String(x.priority):'Open'),
    };
  }, 'No actions assigned to you right now. ?');

  // 6. My Training Records
  var trainList = myTraining
    .sort(function(a,b){return new Date(b.training_date||0)-new Date(a.training_date||0);})
    .slice(0, 5);
  renderPersonalList('dp-my-training', trainList, function(x){
    var exp = x.expiry_date ? new Date(x.expiry_date) : null;
    var nowD = new Date();
    var status, statusLabel;
    if(!exp) { status='valid'; statusLabel='Current'; }
    else if(exp <= nowD) { status='expired'; statusLabel='Expired'; }
    else if(exp < soon60) { status='expiring'; statusLabel='Expiring'; }
    else { status='valid'; statusLabel='Valid'; }
    return {
      title: x.training_type || x.course || x.topic || 'Training',
      meta: (x.training_date||'').slice(0,10) + (exp?' - expires '+exp.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):''),
      status: status,
      statusLabel: statusLabel,
    };
  }, 'No training records yet. Speak to your HSE manager.');

  // 7. My Permits (only show if role can see permits)
  var permitSection = document.getElementById('dp-permits-section');
  if(permitSection) {
    if(canAccessPage('permit')) {
      permitSection.style.display = '';
      var myPermits = (permits||[]).filter(function(p){
        return p.permit_receiver === prof.id
            || p.permit_receiver === prof.email
            || p.permit_receiver_name === prof.full_name
            || p.created_by === prof.id;
      }).slice(0, 5);
      renderPersonalList('dp-my-permits', myPermits, function(x){
        return {
          title: x.permit_type || x.work_description || 'Permit',
          meta: (x.valid_from||'').slice(0,10) + (x.valid_to?' to '+x.valid_to.slice(0,10):''),
          status: x.status==='closed' ? 'closed' : x.status==='approved' ? 'valid' : 'open',
          statusLabel: x.status || 'Draft',
        };
      }, 'No permits yet - tap "Request a permit" above if you need one.');
    } else {
      permitSection.style.display = 'none';
    }
  }
}

function renderPersonalList(elId, items, mapFn, emptyMsg) {
  var el = document.getElementById(elId);
  if(!el) return;
  if(!items || items.length === 0) {
    el.innerHTML = '<div class="dp-empty">'+emptyMsg+'</div>';
    return;
  }
  el.innerHTML = items.map(function(item){
    var m = mapFn(item);
    return '<div class="dp-item">'
      +'<div class="dp-item3main"><div class="dp-item3title">'+escapeHtml(m.title||'-')+'</div>'
      +(m.meta?'<div class="dp-item3meta">'+escapeHtml(m.meta)+'</div>':'')
      +'</div>'
      +'<span class="dp-item3status '+(m.status||'open')+'">'+escapeHtml(m.statusLabel||'')+'</span>'
      +'</div>';
  }).join('');
}

function escapeHtml(s) {
  return String(s==null?'':s).replace(/[&<>"']/g, function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}

// -- Greeting + date line ----------------------------------------------
function dashRenderGreeting() {
  var now = new Date();
  var hour = now.getHours();
  var greet = hour<5?'Good evening':hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';
  var name = (prof?.full_name||'').split(' ')[0] || prof?.email?.split('@')[0] || 'there';
  var coName = co?.name || '';
  var greetEl = document.getElementById('dash-greeting');
  if(greetEl) greetEl.textContent = greet + ', ' + name;
  var dateLine = now.toLocaleDateString('en-GB',{weekday:'long',day:'2-digit',month:'long',year:'numeric'});
  var dl = document.getElementById('dash-date-line');
  if(dl) dl.textContent = dateLine + (coName?(' - '+coName.toUpperCase()):'');
  var labelEl = document.getElementById('dash-label');
  if(labelEl) labelEl.textContent = 'Updated '+now.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})+' - live overview';
}

// -- Hero card (Days Since Last LTI) -----------------------------------
function dashRenderHero(events) {
  var daysEl = document.getElementById('dash-hero-days');
  var ctxEl  = document.getElementById('dash-hero-context');
  if(!daysEl) return;
  // Find the most recent LTI or serious injury
  var ltis = (events||[]).filter(function(x){
    return x.injury_type==='lti' || (x.lost_time_days&&x.lost_time_days>0) || x.severity==='critical';
  }).map(function(x){
    return new Date(x.event_date||x.created_at||0);
  }).filter(function(d){return !isNaN(d);}).sort(function(a,b){return b-a;});

  if(ltis.length === 0) {
    daysEl.textContent = '-';
    if(ctxEl) ctxEl.innerHTML = 'No lost-time incidents on record yet';
    return;
  }
  var lastLTI = ltis[0];
  var days = Math.floor((Date.now() - lastLTI) / 86400000);
  daysEl.textContent = days;
  if(ctxEl) {
    var msg = days >= 30 ? 'Strong safety streak' :
              days >= 7  ? 'Building back up - keep watch' :
                           'Recent incident, vigilance needed';
    ctxEl.innerHTML = msg + ' - last LTI on '+lastLTI.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
  }
}

// -- Status tone logic for KPI cards -----------------------------------
// Each KPI gets its background tone reset based on actual data thresholds.
function dashApplyTones(metrics) {
  function setTone(id, tone) {
    var card = document.querySelector('.kpi-card[data-id="'+id+'"]');
    if(card) card.setAttribute('data-tone', tone);
  }
  // Open incidents: 0=green, 1-2=amber, 3+=red
  var ev = metrics.openEvents;
  setTone('d-events', ev===0?'green':ev<=2?'amber':'red');
  // Open actions: by overdue count
  var ovd = metrics.overdueActions;
  setTone('d-actions', ovd===0?'green':ovd<=2?'amber':'red');
  // Training compliance: <70=red, 70-85=amber, >85=green
  var tp = metrics.trainPct;
  setTone('d-training-pct', tp>=85?'green':tp>=70?'amber':'red');
  // Workforce: always blue (informational)
  setTone('d-people', 'blue');
  // Active PTW: blue informational (high values mean activity, not bad)
  setTone('d-permits', metrics.permits>10?'amber':'blue');
  // Certs expiring: 0=green, 1-3=amber, 4+=red
  var ce = metrics.expCerts;
  setTone('d-certs', ce===0?'green':ce<=3?'amber':'red');
  // LTIFR: <2=green, 2-4=amber, >4=red
  var lt = parseFloat(metrics.ltifr)||0;
  setTone('d-ltifr', lt<2?'green':lt<=4?'amber':'red');
  // TRIR: <1=green, 1-3=amber, >3=red
  var tr = parseFloat(metrics.trir)||0;
  setTone('d-trir', tr<1?'green':tr<=3?'amber':'red');
  // Legal compliance: <60=red, 60-80=amber, >=80=green
  var cp = metrics.compPct;
  setTone('d-compliance', cp>=80?'green':cp>=60?'amber':'red');
  // Env incidents: 0=green, 1-2=amber, 3+=red
  var en = metrics.envInc;
  setTone('d-env', en===0?'green':en<=2?'amber':'red');
  // Audit score: <60=red, 60-80=amber, >=80=green
  var as = metrics.auditScore;
  if(as === null || as === undefined) {
    setTone('d-audit-score', 'grey');
  } else {
    setTone('d-audit-score', as>=80?'green':as>=60?'amber':'red');
  }
  // KPIs on track: by ratio
  var kt = metrics.kpiTotal||0;
  var kr = kt>0 ? metrics.kpiOK/kt : 0;
  setTone('d-kpis', kr>=0.8?'green':kr>=0.5?'amber':kt>0?'red':'blue');
}

// -- Sparklines ---------------------------------------------------------
// Build a 12-week sparkline of monthly-ish data given a list of events,
// a filter function, and a target SVG id.
function dashBuildSparkline(sparkId, dataPoints, color) {
  var svg = document.getElementById(sparkId);
  if(!svg) return;
  if(!dataPoints || dataPoints.length === 0) {
    svg.innerHTML = '';
    return;
  }
  // Normalize to 0-22 (svg viewBox is 100 x 24)
  var max = Math.max.apply(null, dataPoints), min = Math.min.apply(null, dataPoints);
  var range = max - min || 1;
  var step = 100 / Math.max(dataPoints.length - 1, 1);
  var points = dataPoints.map(function(v, i) {
    var y = 22 - ((v - min) / range) * 20;
    return (i*step).toFixed(1) + ',' + y.toFixed(1);
  }).join(' ');
  svg.innerHTML = '<polyline points="'+points+'" stroke="'+color+'" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/>';
}

// Compute month-by-month counts of events matching a filter, over the last N months
function dashMonthlyCounts(events, filterFn, months) {
  months = months || 8;
  var now = new Date();
  var buckets = [];
  for(var i=months-1; i>=0; i--) {
    var d = new Date(now.getFullYear(), now.getMonth()-i, 1);
    var dEnd = new Date(now.getFullYear(), now.getMonth()-i+1, 1);
    var count = (events||[]).filter(function(x){
      var dt = new Date(x.event_date||x.created_at||0);
      return !isNaN(dt) && dt>=d && dt<dEnd && filterFn(x);
    }).length;
    buckets.push(count);
  }
  return buckets;
}

function dashRenderSparklines(events, actions, people) {
  var sparkColors = {
    'd-events-spark':       '#DC2626',
    'd-actions-spark':      '#F59E0B',
    'd-training-pct-spark': '#10B981',
    'd-people-spark':       '#3B82F6',
    'd-permits-spark':      '#6B7280',
    'd-certs-spark':        '#F59E0B',
    'd-ltifr-spark':        '#10B981',
    'd-trir-spark':         '#10B981',
    'd-env-spark':          '#10B981',
    'd-audit-score-spark':  '#3B82F6',
    'd-kpis-spark':         '#3B82F6',
  };
  // Incidents trend
  dashBuildSparkline('d-events-spark',
    dashMonthlyCounts(events, function(x){return x.event_type!=='near_miss';}, 8),
    sparkColors['d-events-spark']);
  // Actions trend - count of actions created per month
  dashBuildSparkline('d-actions-spark',
    dashMonthlyCounts(actions, function(){return true;}, 8),
    sparkColors['d-actions-spark']);
  // LTIs over months
  dashBuildSparkline('d-ltifr-spark',
    dashMonthlyCounts(events, function(x){return x.injury_type==='lti'||x.lost_time_days>0;}, 8),
    sparkColors['d-ltifr-spark']);
  // Recordable
  dashBuildSparkline('d-trir-spark',
    dashMonthlyCounts(events, function(x){return ['injury','lti','medical_treatment','restricted_work'].includes(x.event_type)||x.injury_type;}, 8),
    sparkColors['d-trir-spark']);
  // Env incidents
  dashBuildSparkline('d-env-spark',
    dashMonthlyCounts(events, function(x){return x.event_type==='environmental';}, 8),
    sparkColors['d-env-spark']);
  // The rest get a soft placeholder line until we have real timeseries data
  ['d-training-pct-spark','d-people-spark','d-permits-spark','d-certs-spark','d-audit-score-spark','d-kpis-spark'].forEach(function(id){
    var svg = document.getElementById(id);
    if(svg && !svg.innerHTML) {
      // Subtle baseline only (no fake spikes)
      svg.innerHTML = '<line x1="0" y1="12" x2="100" y2="12" stroke="'+sparkColors[id]+'" stroke-width="1" opacity="0.25" stroke-dasharray="2,2"/>';
    }
  });
}

function dashRenderTrendChart(events) {
  var el = document.getElementById('dash-trend-chart');
  var labEl = document.getElementById('dash-trend-labels');
  if(!el) return;
  var now = new Date(); var months = [];
  for(var i=11;i>=0;i--) {
    var d2=new Date(); d2.setMonth(d2.getMonth()-i);
    var mm=d2.getMonth(); var yy=d2.getFullYear();
    var label=d2.toLocaleString('en-GB',{month:'short'});
    var inc = events.filter(function(x){var dt=x.event_date||x.created_at||'';return dt&&new Date(dt).getMonth()===mm&&new Date(dt).getFullYear()===yy&&x.event_type!=='near_miss';}).length;
    var nm  = events.filter(function(x){var dt=x.event_date||x.created_at||'';return dt&&new Date(dt).getMonth()===mm&&new Date(dt).getFullYear()===yy&&x.event_type==='near_miss';}).length;
    months.push({label:label,inc:inc,nm:nm,yy:yy,mm:mm});
  }
  var maxV = Math.max.apply(null, months.map(function(m){return m.inc+m.nm;}).concat([1]));
  el.innerHTML = months.map(function(m) {
    var hInc = Math.max(Math.round(m.inc/maxV*100), m.inc>0?6:0);
    var hNm  = Math.max(Math.round(m.nm/maxV*100),  m.nm>0?6:0);
    var monthLabel = m.label+' '+m.yy;
    var totalCount = m.inc+m.nm;
    var hasData = totalCount > 0;
    var tooltipText = monthLabel + ': ' +
      (m.inc>0?m.inc+' incident'+(m.inc>1?'s':''):'') +
      (m.inc>0 && m.nm>0?' - ':'') +
      (m.nm>0?m.nm+' near miss'+(m.nm>1?'es':''):'') +
      (totalCount===0?'No data':'') +
      (hasData?' - click to view':'');
    // Build clickable segments. Incidents bar = navigate filtered to incidents only.
    // Near miss bar = navigate filtered to near miss only.
    var incBar = m.inc>0
      ? '<div data-auris-runtime-onclick="r0019" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([m.yy,m.mm]))+'" style="width:80%;height:'+hInc+'px;background:#DC2626;border-radius:'+(m.nm?'0':'3px 3px')+' 0 0;cursor:pointer;transition:height .5s,opacity .15s" data-auris-generated-onmouseover="g0038" data-auris-generated-onmouseout="g0039" title="'+m.inc+' incident'+(m.inc>1?'s':'')+' in '+monthLabel+' - click to view"></div>'
      : '';
    var nmBar = m.nm>0
      ? '<div data-auris-runtime-onclick="r0020" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([m.yy,m.mm]))+'" style="width:80%;height:'+hNm+'px;background:#EF9F27;border-radius:3px 3px 0 0;cursor:pointer;transition:height .5s,opacity .15s" data-auris-generated-onmouseover="g0038" data-auris-generated-onmouseout="g0039" title="'+m.nm+' near miss'+(m.nm>1?'es':'')+' in '+monthLabel+' - click to view"></div>'
      : '';
    var empty = (m.inc===0 && m.nm===0)
      ? '<div data-auris-runtime-onclick="r0021" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([m.yy,m.mm]))+'" style="width:80%;height:2px;background:#E5E7EB;border-radius:2px;cursor:pointer" title="'+monthLabel+': No incidents - click to view month"></div>'
      : '';
    return '<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:1px" title="'+tooltipText+'">'
      + nmBar + incBar + empty
      +'</div>';
  }).join('');
  if(labEl) labEl.innerHTML = months.map(function(m){return '<div style="flex:1;text-align:center;font-size:9px;color:var(--text2)">'+m.label+'</div>';}).join('');
}

// Navigate to incident module with a date filter for the chosen month.
// Uses window-level filter variables that the incident module's load function can read.
function dashNavigateToMonth(year, month, typeFilter) {
  if(!canAccessPage('events')) {
    if(typeof toast === 'function') toast("You don't have access to incidents.", false);
    return;
  }
  // Build month-range dates
  var from = year + '-' + String(month+1).padStart(2,'0') + '-01';
  var lastDay = new Date(year, month+1, 0).getDate();
  var to = year + '-' + String(month+1).padStart(2,'0') + '-' + String(lastDay).padStart(2,'0');
  // Set hints that the events module can read. The module's load function
  // should check these (window.eventsFilterFromDash) and apply them.
  window.eventsFilterFromDash = {
    dateFrom: from,
    dateTo: to,
    type: typeFilter,  // 'incident' | 'near_miss' | 'all'
    source: 'dashboard-trend',
  };
  showPage('events', null);
  // Show a toast indicating the filter has been applied
  if(typeof toast === 'function') {
    var monthName = new Date(year, month, 1).toLocaleString('en-GB',{month:'long',year:'numeric'});
    var typeLabel = typeFilter==='incident'?'incidents':typeFilter==='near_miss'?'near misses':'all events';
    toast('Showing '+typeLabel+' in '+monthName, true);
  }
}

function dashRenderSeverityChart(events) {
  var el = document.getElementById('dash-severity-chart'); if(!el) return;
  var sevs = {critical:0,high:0,medium:0,low:0};
  events.forEach(function(x){if(x.severity&&sevs.hasOwnProperty(x.severity))sevs[x.severity]++;});
  var total = sevs.critical+sevs.high+sevs.medium+sevs.low;
  if(total===0) {
    el.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text2);font-size:11px">No severity data yet</div>';
    return;
  }
  var colors = {critical:'#DC2626',high:'#F97316',medium:'#EF9F27',low:'#10B981'};
  // Build a stacked donut
  var r = 38, c = 2*Math.PI*r;
  var offset = 0;
  var segments = '';
  Object.entries(sevs).forEach(function(e){
    var pct = e[1]/total;
    if(pct === 0) return;
    var dash = pct * c;
    segments += '<circle cx="50" cy="50" r="'+r+'" fill="none" stroke="'+colors[e[0]]+'" stroke-width="14" stroke-dasharray="'+dash.toFixed(1)+' '+c.toFixed(1)+'" stroke-dashoffset="'+(-offset).toFixed(1)+'" transform="rotate(-90 50 50)"/>';
    offset += dash;
  });
  var legend = Object.entries(sevs).map(function(e){
    return '<div style="display:flex;align-items:center;gap:5px;font-size:10px;justify-content:space-between"><span style="display:flex;align-items:center;gap:5px"><span style="width:8px;height:8px;background:'+colors[e[0]]+';border-radius:2px;display:inline-block"></span><span style="text-transform:capitalize;color:var(--text2)">'+e[0]+'</span></span><span style="font-weight:700">'+e[1]+'</span></div>';
  }).join('');
  el.innerHTML = '<svg width="120" height="120" viewBox="0 0 100 100" style="margin:0 auto;display:block">'
    +'<circle cx="50" cy="50" r="'+r+'" fill="none" stroke="#F3F4F6" stroke-width="14"/>'
    +segments
    +'<text x="50" y="49" text-anchor="middle" font-size="20" font-weight="800" fill="#111827">'+total+'</text>'
    +'<text x="50" y="62" text-anchor="middle" font-size="8" fill="#6B7280">total</text>'
    +'</svg>'
    +'<div style="margin-top:10px;display:flex;flex-direction:column;gap:4px;text-align:left">'+legend+'</div>';
}

function dashRenderComplianceRings(compPct, trainPct, permits) {
  var el = document.getElementById('dash-compliance-ring'); if(!el) return;
  var pct = Math.max(0, Math.min(100, compPct||0));
  var color = pct>=80?'#10B981':pct>=60?'#F59E0B':'#DC2626';
  var r = 38, c = 2*Math.PI*r;
  var dash = (pct/100) * c;
  el.innerHTML = '<svg width="120" height="120" viewBox="0 0 100 100" style="margin:0 auto;display:block">'
    +'<circle cx="50" cy="50" r="'+r+'" fill="none" stroke="#F3F4F6" stroke-width="14"/>'
    +'<circle cx="50" cy="50" r="'+r+'" fill="none" stroke="'+color+'" stroke-width="14" stroke-dasharray="'+dash.toFixed(1)+' '+c.toFixed(1)+'" stroke-linecap="round" transform="rotate(-90 50 50)"/>'
    +'<text x="50" y="49" text-anchor="middle" font-size="20" font-weight="800" fill="#111827">'+pct+'%</text>'
    +'<text x="50" y="62" text-anchor="middle" font-size="8" fill="#6B7280">legal</text>'
    +'</svg>'
    +'<div style="margin-top:10px;display:flex;flex-direction:column;gap:6px;text-align:left">'
    +'<div style="display:flex;justify-content:space-between;font-size:11px"><span style="color:var(--text2)">Training</span><span style="font-weight:700;color:'+(trainPct>=85?'#10B981':trainPct>=70?'#F59E0B':'#DC2626')+'">'+Math.min(trainPct,100)+'%</span></div>'
    +'<div style="display:flex;justify-content:space-between;font-size:11px"><span style="color:var(--text2)">Active PTW</span><span style="font-weight:700">'+permits+'</span></div>'
    +'</div>';
}

function dashRenderDeptHeatmap(events, people) {
  var el = document.getElementById('dash-dept-heatmap'); if(!el) return;
  var yr = new Date().getFullYear();
  var ytdEvents = events.filter(function(x){var d=x.event_date||x.created_at||'';return d>=yr+'-01-01';});
  var deptCount = {};
  var allDepts = [...new Set([
    ...people.map(function(p){return p.department;}).filter(Boolean),
    ...ytdEvents.map(function(x){return x.department||x.person_dept;}).filter(Boolean)
  ])].sort();
  ytdEvents.forEach(function(x){var d=x.department||x.person_dept||'Unknown';deptCount[d]=(deptCount[d]||0)+1;});
  var sorted = allDepts.filter(function(d){return deptCount[d]>0;}).sort(function(a,b){return (deptCount[b]||0)-(deptCount[a]||0);}).slice(0,8);
  if(!sorted.length) { el.innerHTML='<div style="text-align:center;padding:20px;color:var(--text2);font-size:11px">No incidents with department data yet</div>'; return; }
  var maxV = deptCount[sorted[0]] || 1;
  el.innerHTML = sorted.map(function(d) {
    var cnt = deptCount[d]||0;
    var pct = Math.round(cnt/maxV*100);
    var color = cnt>=5?'#DC2626':cnt>=3?'#F97316':cnt>=1?'#EF9F27':'#1D9E75';
    return '<div style="display:flex;align-items:center;gap:8px">'
      +'<div style="font-size:11px;font-weight:600;min-width:90px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escH(d)+'</div>'
      +'<div style="flex:1;height:14px;background:#f3f4f6;border-radius:4px;overflow:hidden">'
      +'<div style="width:'+pct+'%;height:100%;background:'+color+';border-radius:4px;transition:width .8s;display:flex;align-items:center;justify-content:flex-end;padding-right:4px">'
      +(pct>15?'<span style="font-size:9px;color:#fff;font-weight:700">'+cnt+'</span>':'')
      +'</div></div>'
      +(pct<=15?'<span style="font-size:11px;font-weight:700;color:'+color+';min-width:16px">'+cnt+'</span>':'')
      +'</div>';
  }).join('');
}

function dashRenderHighRisk(permits, events) {
  var el = document.getElementById('dash-highrisk'); if(!el) return;
  var items = [];
  // High-risk permits
  var hrPermits = (permits||[]).filter(function(p){return ['confined_space','hot_work','electrical','working_at_height','excavation'].includes(p.permit_type||p.type);});
  hrPermits.slice(0,3).forEach(function(p){items.push({emoji:'*',label:(p.title||p.permit_type||'Permit').substring(0,40),sub:p.location||'',color:'#C2410C',badge:'ACTIVE PTW'});});
  // Critical/high open incidents
  var criHigh = events.filter(function(x){return ['critical','high'].includes(x.severity)&&x.status!=='closed';});
  criHigh.slice(0,3).forEach(function(x){items.push({emoji:x.severity==='critical'?'*':'*',label:(x.description||x.event_type||'Incident').substring(0,40),sub:x.location||'',color:x.severity==='critical'?'#DC2626':'#F97316',badge:x.severity.toUpperCase()});});
  if(!items.length){el.innerHTML='<div style="text-align:center;padding:20px;color:var(--text2);font-size:11px">No active high-risk activities</div>';return;}
  el.innerHTML = items.map(function(item){
    return '<div style="display:flex;align-items:flex-start;gap:8px;padding:6px 8px;background:#FFF7ED;border-radius:6px;border-left:3px solid '+item.color+'">'
      +'<span style="font-size:16px;flex-shrink:0;line-height:1.2">'+item.emoji+'</span>'
      +'<div style="flex:1;min-width:0"><div style="font-size:12px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escH(item.label)+'</div>'
      +(item.sub?'<div style="font-size:10px;color:var(--text2)">'+escH(item.sub)+'</div>':'')+'</div>'
      +'<span style="font-size:9px;background:'+item.color+';color:#fff;padding:1px 5px;border-radius:4px;font-weight:700;white-space:nowrap;flex-shrink:0">'+item.badge+'</span>'
      +'</div>';
  }).join('');
}

function dashRenderRecentEvents(events) {
  var el = document.getElementById('dash-events'); if(!el) return;
  if(!events.length){el.innerHTML='<div style="text-align:center;padding:12px;color:var(--text2);font-size:11px">No open incidents</div>';return;}
  var sevColors={critical:'#DC2626',high:'#F97316',medium:'#EF9F27',low:'#1D9E75'};
  el.innerHTML = events.map(function(x){
    var sc=sevColors[x.severity||'medium']||sevColors.medium;
    var d=x.event_date||x.created_at||'';
    return '<div style="display:flex;align-items:flex-start;gap:6px;padding:5px 0;border-bottom:1px solid #f3f4f6">'
      +'<div style="width:3px;height:36px;background:'+sc+';border-radius:2px;flex-shrink:0;margin-top:2px"></div>'
      +'<div style="flex:1;min-width:0"><div style="font-size:11px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escH((x.description||x.event_type||'Incident').substring(0,50))+'</div>'
      +'<div style="font-size:10px;color:var(--text2)">'+(d?new Date(d).toLocaleDateString('en-GB'):'')+' - '+escH(x.location||'')+'</div></div>'
      +'<span style="background:'+sc+';color:#fff;padding:1px 5px;border-radius:3px;font-size:9px;font-weight:700;white-space:nowrap;flex-shrink:0">'+escH((x.severity||'med').substring(0,4).toUpperCase())+'</span>'
      +'</div>';
  }).join('');
}

function dashRenderPriorityActions(actions) {
  var el = document.getElementById('dash-actions'); if(!el) return;
  if(!actions.length){el.innerHTML='<div style="text-align:center;padding:12px;color:var(--text2);font-size:11px">No open actions</div>';return;}
  var now=new Date();
  var priC={critical:'#DC2626',high:'#C2410C',medium:'#185FA5',low:'#6B7280'};
  var sorted=actions.sort(function(a,b){var p={critical:4,high:3,medium:2,low:1};return(p[b.priority]||0)-(p[a.priority]||0);}).slice(0,5);
  el.innerHTML = sorted.map(function(x){
    var isOvd=(x.target_date||x.due_date)&&new Date(x.target_date||x.due_date)<now;
    var pc=priC[x.priority||'medium']||priC.medium;
    return '<div style="display:flex;align-items:flex-start;gap:6px;padding:5px 0;border-bottom:1px solid #f3f4f6">'
      +'<div style="flex:1;min-width:0"><div style="font-size:11px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escH((x.title||x.description||'Action').substring(0,50))+'</div>'
      +'<div style="font-size:10px;color:'+(isOvd?'#DC2626':'var(--text2)')+'">'+escH(x.assigned_to_name||x.responsible||'Unassigned')+(x.target_date||x.due_date?' - Due '+new Date(x.target_date||x.due_date).toLocaleDateString('en-GB'):'')+(isOvd?' - overdue':'')+'</div></div>'
      +'<span style="color:'+pc+';font-size:9px;font-weight:700;text-transform:uppercase;flex-shrink:0">'+escH(x.priority||'MED')+'</span>'
      +'</div>';
  }).join('');
}

function dashRenderTrainingCompliance(expCerts, valid, people) {
  var el = document.getElementById('dash-training-compliance'); if(!el) return;
  var pct = people.length>0 ? Math.min(Math.round(valid.length/people.length*100),100) : 0;
  var color = pct>=80?'#1D9E75':pct>=60?'#EF9F27':'#DC2626';
  el.innerHTML = '<div style="margin-bottom:8px">'
    +'<div style="display:flex;justify-content:space-between;font-size:12px;font-weight:700;margin-bottom:4px">'
    +'<span>Overall compliance</span><span style="color:'+color+'">'+pct+'%</span></div>'
    +'<div style="height:8px;background:#f3f4f6;border-radius:99px;overflow:hidden">'
    +'<div style="width:'+pct+'%;height:100%;background:'+color+';border-radius:99px;transition:width .8s"></div>'
    +'</div></div>'
    +(expCerts.length>0?
      '<div style="font-size:11px;font-weight:600;color:#C2410C;margin-bottom:4px">Due: '+expCerts.length+' certificate'+(expCerts.length>1?'s':'')+' expiring &lt; 60 days:</div>'
      +expCerts.slice(0,4).map(function(x){
        return '<div style="font-size:11px;padding:3px 0;border-bottom:1px solid #f3f4f6">'
          +escH(x.person_name||'-')+' - '+escH(x.authorisation_type||x.auth_type||'Cert')
          +(x.expiry_date?' <span style="color:#DC2626">'+new Date(x.expiry_date).toLocaleDateString('en-GB')+'</span>':'')
          +'</div>';
      }).join('')
    : '<div style="font-size:11px;color:#1D9E75;text-align:center;padding:8px">All certificates current</div>');
}


// --- EXECUTIVE DASHBOARD ------------------------------------------
var execData = {};

async function loadExecutive() {
  try {
    var safe = async function(p){try{return await p;}catch(e){console.warn('Exec:',e.message);return [];}};
    var yr = new Date().getFullYear();
    var yrFilter = document.getElementById('exec-year-filter')?.value || '';
    var useYr = yrFilter ? parseInt(yrFilter) : yr;
    var yrStart = useYr+'-01-01'; var yrEnd = useYr+'-12-31';

    // Populate year selector
    var ySel = document.getElementById('exec-year-filter');
    if(ySel && ySel.options.length<=1) {
      for(var y=yr;y>=yr-4;y--) {
        var o=document.createElement('option'); o.value=y; o.textContent=y+(y===yr?' (Current)':'');
        ySel.appendChild(o);
      }
    }

    var results = await Promise.all([
      safe(api('/events?select=*'+cf()+'&event_date=gte.'+yrStart+'&event_date=lte.'+yrEnd+'&order=event_date.asc')),
      safe(api('/action_tracker?select=*'+cf()+'&order=created_at.desc&limit=500')),
      safe(api('/people?select=id,department,status'+cf()+'&status=eq.active')),
      safe(api('/inspections?select=*'+cf()+'&order=inspection_date.desc&limit=50')),
      safe(api('/legal_requirements?select=*'+cf())),
      safe(api('/authorisations?select=*'+cf())),
      safe(api('/spill_reports?select=*'+cf())),
      safe(api('/waste_records?select=*'+cf()+'&order=created_at.desc&limit=100')),
      safe(api('/fuel_consumption?select=*'+cf()+'&order=created_at.desc&limit=100')),
    ]);

    var [events,actions,people,insps,legal,certs,spills,waste,fuel] = results;
    events=events||[]; actions=actions||[]; people=people||[];
    insps=insps||[]; legal=legal||[]; certs=certs||[];
    spills=spills||[]; waste=waste||[]; fuel=fuel||[];

    execData = {events,actions,people,insps,legal,certs,spills,waste,fuel,yr:useYr};

    var now = new Date();
    var manhours = people.length * 2000 * (useYr<yr?12:(now.getMonth()+1)) / 12;
    var ltiEvts = events.filter(function(x){return x.injury_type==='lti'||x.lost_time_days>0;});
    var recEvts = events.filter(function(x){return ['injury','lti','medical_treatment','restricted_work'].includes(x.event_type)||x.injury_type;});
    var ltifr = manhours>0?(ltiEvts.length/manhours*1000000).toFixed(2):'0.00';
    var trir = manhours>0?(recEvts.length/manhours*200000).toFixed(2):'0.00';

    function sm(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}

    // Overview metrics
    sm('exec-ltifr', ltifr); sm('exec-trir', trir);
    var lScores = legal.filter(function(x){return x.compliance_score!=null;}).map(function(x){return parseFloat(x.compliance_score)||0;});
    var compPct = lScores.length>0?Math.round(lScores.reduce(function(a,b){return a+b;},0)/lScores.length):0;
    sm('exec-compliance', compPct+'%');
    var cpInner = document.getElementById('exec-compliance-prog-inner');
    if(cpInner){cpInner.style.width=compPct+'%';}

    // Days since LTI
    var lastLTI = ltiEvts.slice(-1)[0];
    if(lastLTI&&lastLTI.event_date){
      var daysAgo = Math.floor((now-new Date(lastLTI.event_date))/86400000);
      sm('exec-days-lti', daysAgo);
    } else { sm('exec-days-lti', events.length?'365+':'N/A'); }

    // Safety tab metrics
    sm('exec-fatalities', events.filter(function(x){return x.injury_type==='fatality';}).length);
    sm('exec-ltis', ltiEvts.length);
    sm('exec-mti', events.filter(function(x){return x.injury_type==='medical_treatment'||x.event_type==='injury';}).length);
    sm('exec-nm', events.filter(function(x){return x.event_type==='near_miss';}).length);

    // Compliance tab
    sm('exec-legal-pct', compPct+'%');
    var avgAudit = insps.length>0?Math.round(insps.reduce(function(s,x){var t=(x.score_good||0)+(x.score_insuf||0);return s+(t>0?(x.score_good||0)/t*100:0);},0)/insps.length):0;
    sm('exec-audit-pct', avgAudit+'%');
    sm('exec-training-pct', people.length>0?Math.min(100,Math.round(certs.length/people.length*100))+'%':'-');

    // ESG metrics
    sm('exec-env-inc', events.filter(function(x){return x.event_type==='environmental';}).length);
    sm('exec-spills', spills.length);
    var totalWaste = waste.reduce(function(s,x){return s+(parseFloat(x.quantity_kg)||0);},0);
    sm('exec-waste', (totalWaste/1000).toFixed(1));
    var totalCO2 = fuel.reduce(function(s,x){return s+(parseFloat(x.co2_tonnes||x.co2)||0);},0);
    sm('exec-co2', totalCO2.toFixed(1));

    // Render charts
    execRenderAnnualTrend(events);
    execRenderRiskDist(events);
    execRenderDeptComparison(events, people);
    execRenderContractorComparison(events);
    execRenderIncidentTypes(events);
    execRenderLostTime(events);
    execRenderLocationRank(events);
    execRenderComplianceCategories(legal);
    execRenderCAAge(actions);
    execRenderESGScorecard(compPct, spills.length, events);
    execRenderSustainability(waste, fuel);

    // LTIFR trend indicators
    var ltEl = document.getElementById('exec-ltifr-trend');
    if(ltEl) ltEl.innerHTML = '<span style="font-size:11px;opacity:.85">'+(ltiEvts.length===0?'Zero LTIs this period':'? '+ltiEvts.length+' LTI'+(ltiEvts.length>1?'s':''))+'</span>';
    var trEl = document.getElementById('exec-trir-trend');
    if(trEl) trEl.innerHTML = '<span style="font-size:11px;opacity:.85">'+recEvts.length+' recordable incident'+(recEvts.length!==1?'s':'')+'</span>';

  } catch(e) { console.error('Executive dashboard:', e); }
}

function execTab(tab, btn) {
  document.querySelectorAll('[id^="exec-tab-"]').forEach(function(t){t.classList.remove('active');});
  if(btn) btn.classList.add('active');
  ['overview','safety','compliance','esg','reports'].forEach(function(t){
    var el=document.getElementById('exec-view-'+t);
    if(el) el.style.display=t===tab?'block':'none';
  });
}

function execRenderAnnualTrend(events) {
  var el=document.getElementById('exec-annual-trend'); var labEl=document.getElementById('exec-trend-labels');
  if(!el) return;
  var months=[]; var yr=execData.yr||new Date().getFullYear();
  for(var i=0;i<12;i++){
    var cnt=events.filter(function(x){var d=x.event_date||'';return d.startsWith(yr+'-'+String(i+1).padStart(2,'0'));}).length;
    months.push({label:['J','F','M','A','M','J','J','A','S','O','N','D'][i],cnt});
  }
  var maxV=Math.max(...months.map(function(m){return m.cnt;}),1);
  el.innerHTML=months.map(function(m){
    var h=Math.max(Math.round(m.cnt/maxV*120),m.cnt>0?4:0);
    var c=m.cnt>=5?'#DC2626':m.cnt>=3?'#F97316':m.cnt>=1?'#EF9F27':'#e5e7eb';
    return '<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:2px">'
      +'<span style="font-size:9px;font-weight:700;color:var(--text2)">'+m.cnt+'</span>'
      +'<div style="width:100%;height:'+h+'px;background:'+c+';border-radius:3px 3px 0 0;min-height:2px"></div>'
      +'</div>';
  }).join('');
  if(labEl) labEl.innerHTML=months.map(function(m){return '<div style="flex:1;text-align:center;font-size:9px;color:var(--text2)">'+m.label+'</div>';}).join('');
}

function execRenderRiskDist(events) {
  var el=document.getElementById('exec-risk-dist'); if(!el) return;
  var dist={critical:0,high:0,medium:0,low:0};
  events.forEach(function(x){if(x.severity&&dist.hasOwnProperty(x.severity))dist[x.severity]++;});
  var total=events.length||1;
  var cfg={critical:{c:'#DC2626',label:'Critical'},high:{c:'#F97316',label:'High'},medium:{c:'#EF9F27',label:'Medium'},low:{c:'#1D9E75',label:'Low'}};
  el.innerHTML='<div style="display:flex;flex-direction:column;gap:10px">'+Object.entries(dist).map(function(e){
    var pct=Math.round(e[1]/total*100); var c=cfg[e[0]];
    return '<div><div style="display:flex;justify-content:space-between;font-size:11px;font-weight:700;margin-bottom:3px">'
      +'<span style="color:'+c.c+'">'+c.label+'</span><span>'+e[1]+' ('+pct+'%)</span></div>'
      +'<div style="height:10px;background:#f3f4f6;border-radius:99px;overflow:hidden">'
      +'<div style="width:'+pct+'%;height:100%;background:'+c.c+';border-radius:99px;transition:width .8s"></div></div></div>';
  }).join('')+'</div>';
}

function execRenderDeptComparison(events, people) {
  var el=document.getElementById('exec-dept-comparison'); if(!el) return;
  var depts={};
  events.forEach(function(x){var d=x.department||x.person_dept||'Unknown';depts[d]=(depts[d]||0)+1;});
  var sorted=Object.entries(depts).sort(function(a,b){return b[1]-a[1];}).slice(0,8);
  var maxV=sorted[0]?.[1]||1;
  if(!sorted.length){el.innerHTML='<div style="color:var(--text2);font-size:11px;text-align:center;padding:10px">No department data</div>';return;}
  el.innerHTML=sorted.map(function(e){
    var pct=Math.round(e[1]/maxV*100);
    var c=e[1]>=5?'#DC2626':e[1]>=3?'#F97316':'#185FA5';
    return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'
      +'<div style="font-size:11px;min-width:80px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escH(e[0])+'</div>'
      +'<div style="flex:1;height:12px;background:#f3f4f6;border-radius:99px;overflow:hidden">'
      +'<div style="width:'+pct+'%;height:100%;background:'+c+';border-radius:99px;transition:width .8s"></div></div>'
      +'<span style="font-size:11px;font-weight:800;color:'+c+';min-width:16px">'+e[1]+'</span></div>';
  }).join('');
}

function execRenderContractorComparison(events) {
  var el=document.getElementById('exec-contractor-comparison'); if(!el) return;
  var empCount=events.filter(function(x){return x.ws1_contract_type==='employee'||(!x.ws1_contract_type&&x.person_name);}).length;
  var conCount=events.filter(function(x){return x.ws1_contract_type==='contractor';}).length;
  var visCount=events.filter(function(x){return x.ws1_contract_type==='visitor';}).length;
  var unkCount=events.length-empCount-conCount-visCount;
  var data=[{label:'Employee',cnt:empCount,c:'#185FA5'},{label:'Contractor',cnt:conCount,c:'#C2410C'},{label:'Visitor',cnt:visCount,c:'#EF9F27'},{label:'Unknown',cnt:unkCount>0?unkCount:0,c:'#9CA3AF'}].filter(function(x){return x.cnt>0;});
  var total=events.length||1;
  el.innerHTML=data.map(function(d){
    var pct=Math.round(d.cnt/total*100);
    return '<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #f3f4f6">'
      +'<span style="font-size:14px;min-width:16px">'+{Employee:'EMP',Contractor:'CON',Visitor:'VIS',Unknown:'UNK'}[d.label]+'</span>'
      +'<div style="flex:1"><div style="font-size:11px;font-weight:600;margin-bottom:2px">'+d.label+'</div>'
      +'<div style="height:6px;background:#f3f4f6;border-radius:99px;overflow:hidden">'
      +'<div style="width:'+pct+'%;height:100%;background:'+d.c+';border-radius:99px;transition:width .8s"></div></div></div>'
      +'<span style="font-size:12px;font-weight:800;color:'+d.c+'">'+d.cnt+'</span>'
      +'</div>';
  }).join('');
}

function execRenderIncidentTypes(events) {
  var el=document.getElementById('exec-incident-types'); if(!el) return;
  var types={}; events.forEach(function(x){var t=x.event_type||'other';types[t]=(types[t]||0)+1;});
  var sorted=Object.entries(types).sort(function(a,b){return b[1]-a[1];}).slice(0,8);
  var maxV=sorted[0]?.[1]||1;
  el.innerHTML=sorted.map(function(e){
    var cfg=window.IMS_TYPE_CFG?IMS_TYPE_CFG[e[0]]:{emoji:'*',label:e[0],color:'#6B7280'};
    var pct=Math.round(e[1]/maxV*100);
    return '<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px">'
      +'<span style="font-size:13px;width:18px">'+cfg.emoji+'</span>'
      +'<div style="flex:1;min-width:0"><div style="font-size:11px;font-weight:600;margin-bottom:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escH(cfg.label||e[0])+'</div>'
      +'<div style="height:5px;background:#f3f4f6;border-radius:99px;overflow:hidden">'
      +'<div style="width:'+pct+'%;height:100%;background:'+(cfg.color||'#185FA5')+';border-radius:99px"></div></div></div>'
      +'<span style="font-size:11px;font-weight:800;color:'+(cfg.color||'#185FA5')+';min-width:20px;text-align:right">'+e[1]+'</span></div>';
  }).join('');
}

function execRenderLostTime(events) {
  var el=document.getElementById('exec-lost-time'); var labEl=document.getElementById('exec-lt-labels');
  if(!el) return;
  var yr=execData.yr||new Date().getFullYear();
  var months=[];
  for(var i=0;i<12;i++){
    var mo=String(i+1).padStart(2,'0');
    var ltDays=events.filter(function(x){return (x.event_date||'').startsWith(yr+'-'+mo);}).reduce(function(s,x){return s+(parseInt(x.lost_time_days)||0);},0);
    months.push({label:['J','F','M','A','M','J','J','A','S','O','N','D'][i],d:ltDays});
  }
  var maxV=Math.max(...months.map(function(m){return m.d;}),1);
  el.innerHTML=months.map(function(m){
    var h=Math.max(Math.round(m.d/maxV*110),m.d>0?4:0);
    return '<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:1px">'
      +'<span style="font-size:9px;font-weight:700;color:var(--text2)">'+m.d+'</span>'
      +'<div style="width:100%;height:'+h+'px;background:#C2410C;border-radius:3px 3px 0 0;min-height:2px"></div>'
      +'</div>';
  }).join('');
  if(labEl) labEl.innerHTML=months.map(function(m){return '<div style="flex:1;text-align:center;font-size:9px;color:var(--text2)">'+m.label+'</div>';}).join('');
}

function execRenderLocationRank(events) {
  var el=document.getElementById('exec-location-rank'); if(!el) return;
  var locs={}; events.forEach(function(x){if(x.location){var l=x.location.trim().substring(0,30);locs[l]=(locs[l]||0)+1;}});
  var sorted=Object.entries(locs).sort(function(a,b){return b[1]-a[1];}).slice(0,8);
  if(!sorted.length){el.innerHTML='<div style="color:var(--text2);font-size:11px;text-align:center;padding:10px">No location data</div>';return;}
  var maxV=sorted[0][1];
  el.innerHTML='<div class="table-scroll"><table class="data-table" style="min-width:520px;font-size:11px"><thead><tr><th>Rank</th><th>Location</th><th>Incidents</th><th>Risk bar</th></tr></thead><tbody>'
    +sorted.map(function(e,i){
      var pct=Math.round(e[1]/maxV*100);
      var c=e[1]>=5?'#DC2626':e[1]>=3?'#F97316':'#185FA5';
      return '<tr style="border-bottom:1px solid #f3f4f6"><td style="padding:5px 8px;font-weight:700;color:'+c+'">#'+(i+1)+'</td>'
        +'<td style="padding:5px 8px;font-weight:600">'+escH(e[0])+'</td>'
        +'<td style="padding:5px 8px;text-align:center;font-weight:800;color:'+c+'">'+e[1]+'</td>'
        +'<td style="padding:5px 8px"><div style="height:6px;background:#f3f4f6;border-radius:99px;width:80px;overflow:hidden"><div style="width:'+pct+'%;height:100%;background:'+c+';border-radius:99px"></div></div></td></tr>';
    }).join('')+'</tbody></table></div>';
}

function execRenderComplianceCategories(legal) {
  var el=document.getElementById('exec-compliance-cat'); if(!el) return;
  var cats={}; var catCounts={};
  legal.forEach(function(x){var c=x.category||'General'; if(!cats[c]){cats[c]=0;catCounts[c]=0;} cats[c]+=(parseFloat(x.compliance_score)||0); catCounts[c]++;});
  var sorted=Object.entries(cats).map(function(e){return{cat:e[0],avg:Math.round(e[1]/(catCounts[e[0]]||1))};}).sort(function(a,b){return a.avg-b.avg;});
  if(!sorted.length){el.innerHTML='<div style="color:var(--text2);font-size:11px;text-align:center;padding:10px">No compliance data</div>';return;}
  el.innerHTML=sorted.map(function(d){
    var c=d.avg>=80?'#1D9E75':d.avg>=60?'#EF9F27':'#DC2626';
    return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px">'
      +'<div style="font-size:11px;min-width:100px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escH(d.cat)+'</div>'
      +'<div style="flex:1;height:8px;background:#f3f4f6;border-radius:99px;overflow:hidden">'
      +'<div style="width:'+d.avg+'%;height:100%;background:'+c+';border-radius:99px;transition:width .8s"></div></div>'
      +'<span style="font-size:11px;font-weight:800;color:'+c+';min-width:35px;text-align:right">'+d.avg+'%</span></div>';
  }).join('');
}

function execRenderCAAge(actions) {
  var el=document.getElementById('exec-ca-age'); if(!el) return;
  var now=new Date();
  var open=actions.filter(function(x){return x.status!=='closed';});
  var groups={'<7 days':0,'7-30 days':0,'30-90 days':0,'>90 days':0,'No due date':0};
  open.forEach(function(x){
    var d=x.target_date||x.due_date;
    if(!d){groups['No due date']++;return;}
    var diff=Math.floor((now-new Date(d))/86400000);
    if(diff<7)groups['<7 days']++;
    else if(diff<30)groups['7-30 days']++;
    else if(diff<90)groups['30-90 days']++;
    else groups['>90 days']++;
  });
  var total=open.length||1;
  var colors={'<7 days':'#1D9E75','7-30 days':'#EF9F27','30-90 days':'#F97316','>90 days':'#DC2626','No due date':'#9CA3AF'};
  el.innerHTML=Object.entries(groups).map(function(e){
    var pct=Math.round(e[1]/total*100);
    return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px">'
      +'<div style="font-size:11px;min-width:80px;font-weight:600">'+e[0]+'</div>'
      +'<div style="flex:1;height:10px;background:#f3f4f6;border-radius:99px;overflow:hidden">'
      +'<div style="width:'+pct+'%;height:100%;background:'+colors[e[0]]+';border-radius:99px;transition:width .8s"></div></div>'
      +'<span style="font-size:11px;font-weight:800;color:'+colors[e[0]]+';min-width:20px;text-align:right">'+e[1]+'</span></div>';
  }).join('');
}

function execRenderESGScorecard(compPct, spills, events) {
  var el=document.getElementById('exec-esg-scorecard'); if(!el) return;
  var envEvents=events.filter(function(x){return x.event_type==='environmental';});
  var scores=[
    {label:'Environmental compliance',score:Math.max(0,100-envEvents.length*10-spills*5),icon:'*'},
    {label:'Legal compliance',score:compPct,icon:'*'},
    {label:'Incident severity',score:Math.max(0,100-events.filter(function(x){return ['critical','high'].includes(x.severity);}).length*8),icon:'*'},
    {label:'Waste management',score:spills>0?Math.max(20,80-spills*15):95,icon:'*'},
  ];
  el.innerHTML=scores.map(function(s){
    var c=s.score>=80?'#1D9E75':s.score>=60?'#EF9F27':'#DC2626';
    return '<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #f3f4f6">'
      +'<span style="font-size:14px">'+s.icon+'</span>'
      +'<div style="flex:1"><div style="font-size:11px;font-weight:600;margin-bottom:2px">'+s.label+'</div>'
      +'<div style="height:6px;background:#f3f4f6;border-radius:99px;overflow:hidden">'
      +'<div style="width:'+s.score+'%;height:100%;background:'+c+';border-radius:99px;transition:width .8s"></div></div></div>'
      +'<span style="font-size:13px;font-weight:800;color:'+c+'">'+s.score+'%</span></div>';
  }).join('');
}

function execRenderSustainability(waste, fuel) {
  var el=document.getElementById('exec-sustainability'); if(!el) return;
  var totalWaste=waste.reduce(function(s,x){return s+(parseFloat(x.quantity_kg)||0);},0);
  var hazWaste=waste.filter(function(x){return x.waste_type==='hazardous';}).reduce(function(s,x){return s+(parseFloat(x.quantity_kg)||0);},0);
  var totalFuel=fuel.reduce(function(s,x){return s+(parseFloat(x.volume_litres)||0);},0);
  var totalCO2=fuel.reduce(function(s,x){return s+(parseFloat(x.co2_tonnes||x.co2)||0);},0);
  var metrics=[
    {label:'Total waste',value:(totalWaste/1000).toFixed(1)+' t',icon:'*',color:'#0891B2'},
    {label:'Hazardous waste',value:(hazWaste/1000).toFixed(1)+' t',icon:'*',color:'#DC2626'},
    {label:'Fuel consumption',value:totalFuel.toFixed(0)+' L',icon:'?',color:'#EF9F27'},
    {label:'Carbon footprint',value:totalCO2.toFixed(1)+' tCO2e',icon:'*',color:'#854F0B'},
  ];
  el.innerHTML=metrics.map(function(m){
    return '<div style="display:flex;align-items:center;justify-content:space-between;padding:6px 8px;background:#f9fafb;border-radius:6px;margin-bottom:4px">'
      +'<div style="display:flex;align-items:center;gap:6px"><span style="font-size:14px">'+m.icon+'</span><span style="font-size:11px;font-weight:600">'+m.label+'</span></div>'
      +'<span style="font-size:12px;font-weight:800;color:'+m.color+'">'+m.value+'</span></div>';
  }).join('');
}

var execLastAIReportText='';
function execAIPeriodRange(type){
  var now=new Date();
  var start=new Date(now);
  if(type==='weekly_summary'){start.setDate(now.getDate()-7);}
  else if(type==='monthly_report'){start=new Date(now.getFullYear(),now.getMonth(),1);}
  else {start=new Date((execData&&execData.yr)||now.getFullYear(),0,1);}
  return {start:start,end:now,label:type==='weekly_summary'?'last 7 days':(type==='monthly_report'?'current month':'year to date')};
}
function execBuildAIContext(type){
  var d=execData||{}; var range=execAIPeriodRange(type); var now=new Date();
  var events=d.events||[], actions=d.actions||[], people=d.people||[], insps=d.insps||[], legal=d.legal||[], spills=d.spills||[], certs=d.certs||[];
  var inRange=function(x,field){var raw=x[field]||x.event_date||x.inspection_date||x.created_at||''; if(!raw)return false; var dt=new Date(raw); return dt>=range.start&&dt<=range.end;};
  var periodEvents=events.filter(function(x){return inRange(x,'event_date');});
  var lti=events.filter(function(x){return x.injury_type==='lti'||x.lost_time_days>0;});
  var rec=events.filter(function(x){return x.injury_type||['injury','lti','medical_treatment','restricted_work'].includes(x.event_type);});
  var openActions=actions.filter(function(x){return !['closed','cancelled'].includes(x.status||'');});
  var overdue=openActions.filter(function(x){return (x.target_date||x.due_date)&&new Date(x.target_date||x.due_date)<now;});
  var lScores=legal.filter(function(x){return x.compliance_score!=null;}).map(function(x){return parseFloat(x.compliance_score)||0;});
  var compPct=lScores.length?Math.round(lScores.reduce(function(a,b){return a+b;},0)/lScores.length):0;
  var avgAudit=insps.length?Math.round(insps.reduce(function(s,x){var t=(x.score_good||0)+(x.score_insuf||0);return s+(t?((x.score_good||0)/t*100):0);},0)/insps.length):0;
  var manhours=people.length*2000; var ltifr=manhours?(lti.length/manhours*1000000).toFixed(2):'N/A'; var trir=manhours?(rec.length/manhours*200000).toFixed(2):'N/A';
  var sevCount={critical:0,high:0,medium:0,low:0}; events.forEach(function(x){if(sevCount.hasOwnProperty(x.severity))sevCount[x.severity]++;});
  var highRecent=periodEvents.filter(function(x){return ['critical','high'].includes(x.severity);}).slice(0,8).map(function(x){return {ref:x.event_ref||x.reference_no||x.id, severity:x.severity, type:x.event_type, location:x.location, date:x.event_date, description:String(x.description||x.event_description||'').slice(0,180)};});
  var overdueList=overdue.slice(0,10).map(function(x){return {ref:x.action_ref||x.id, title:x.title||x.description, priority:x.priority, responsible:x.assigned_to_name||x.responsible, due:x.target_date||x.due_date, status:x.status};});
  var badInsps=insps.filter(function(x){return (x.score_insuf||0)>0;}).slice(0,8).map(function(x){return {ref:x.reference_no||x.id, site:x.site||x.if_site, date:x.inspection_date||x.if_date, insufficient:x.score_insuf||0, type:x.inspection_type};});
  return {company:co?.name||'Current company', period:range.label, generated_at:new Date().toLocaleString('en-GB'), workforce:people.length, ytd:{incidents:events.length, lti:lti.length, recordable:rec.length, ltifr:ltifr, trir:trir, severity:sevCount, legal_compliance_pct:compPct, audit_score_pct:avgAudit, open_actions:openActions.length, overdue_actions:overdue.length, spills:spills.length, certificates_tracked:certs.length}, period_metrics:{incidents:periodEvents.length, high_or_critical:highRecent.length}, recent_high_risk_events:highRecent, overdue_actions:overdueList, inspections_with_findings:badInsps};
}
function execAIReportText(data){
  if(!data)return '';
  if(typeof data==='string')return data;
  var parts=[];
  ['executive_summary','board_summary','management_summary'].forEach(function(k){if(data[k])parts.push(String(data[k]));});
  ['red_flags','positive_notes','management_decisions','next_week_priorities','recommended_actions'].forEach(function(k){
    var arr=data[k]; if(Array.isArray(arr)&&arr.length){parts.push(k.replace(/_/g,' ').toUpperCase()+':\n'+arr.map(function(x,i){return (i+1)+'. '+(typeof x==='string'?x:(x.title||x.decision||x.action||x.description||JSON.stringify(x)));}).join('\n'));}
  });
  return parts.join('\n\n');
}
function execAIRenderList(title,items,color){
  if(!Array.isArray(items)||!items.length)return '';
  return '<div style="border:1px solid '+color+'33;background:#fff;border-radius:10px;padding:10px;margin-top:10px"><div style="font-weight:900;color:'+color+';margin-bottom:6px">'+escH(title)+'</div>'
    +items.map(function(x){var text=typeof x==='string'?x:(x.title||x.decision||x.action||x.description||JSON.stringify(x));return '<div style="padding:7px 0;border-top:1px solid #eef2f7;font-size:12px;line-height:1.45">'+escH(text)+'</div>';}).join('')+'</div>';
}
function execAIRenderReport(data,type,ctx){
  execLastAIReportText=execAIReportText(data);
  if(!data||typeof data==='string')return '<div style="white-space:pre-wrap">'+escH(execLastAIReportText||String(data||''))+'</div>';
  var summary=data.executive_summary||data.board_summary||data.management_summary||'';
  var html='<div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap;margin-bottom:10px"><div><div style="font-weight:900;color:#5B21B6;font-size:15px">'+escH(type.replace(/_/g,' ').toUpperCase())+'</div><div style="font-size:11px;color:var(--text2)">'+escH(ctx.company)+' - '+escH(ctx.period)+' - '+escH(ctx.generated_at)+'</div></div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn btn-sm" data-auris-generated-onclick="g0040"><i class="ti ti-copy"></i>Copy</button><button class="btn btn-sm" data-auris-generated-onclick="g0041"><i class="ti ti-download"></i>Download</button><button class="btn btn-sm" data-auris-generated-onclick="g0042"><i class="ti ti-printer"></i>Print</button></div></div>';
  html+='<div style="background:#fff;border:1px solid #DDD6FE;border-radius:10px;padding:12px;color:#1f2937;line-height:1.55">'+escH(summary)+'</div>';
  html+=execAIRenderList('Red flags / board attention',data.red_flags,'#DC2626');
  html+=execAIRenderList('Positive performance notes',data.positive_notes,'#1D9E75');
  html+=execAIRenderList('Management decisions required',data.management_decisions,'#5B21B6');
  html+=execAIRenderList('Next-week priorities',data.next_week_priorities,'#185FA5');
  html+=execAIRenderList('Recommended actions',data.recommended_actions,'#B45309');
  return html;
}
function execCopyAIReport(){if(!execLastAIReportText){toast('Generate an AI report first',false);return;}navigator.clipboard?.writeText(execLastAIReportText);toast('AI report copied');}
function execDownloadAIReport(){if(!execLastAIReportText){toast('Generate an AI report first',false);return;}var blob=new Blob([execLastAIReportText],{type:'text/plain'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='AURIS360_Executive_AI_Report_'+new Date().toISOString().slice(0,10)+'.txt';a.click();URL.revokeObjectURL(url);toast('AI report downloaded');}
function execPrintAIReport(){if(!execLastAIReportText){toast('Generate an AI report first',false);return;}var html='<div class="rpt"><h1>AI Executive HSE Summary</h1><pre style="white-space:pre-wrap;font-family:Arial,sans-serif;font-size:12px;line-height:1.55">'+escH(execLastAIReportText)+'</pre></div>'; if(typeof aurisPrint==='function')aurisPrint(html,'AI Executive HSE Summary');else window.print();}
async function execAIReport(type) {
  var outEl = document.getElementById('exec-ai-output');
  var phEl  = document.getElementById('exec-ai-placeholder');
  if(!outEl) return;
  if(typeof canUseAI==='function' && !canUseAI()){outEl.style.display='block'; if(phEl)phEl.style.display='none'; outEl.innerHTML=aiFriendlyErrorHtml(new Error('restricted')); return;}
  outEl.style.display='block'; if(phEl) phEl.style.display='none';
  outEl.innerHTML = '<div style="text-align:center;padding:18px;color:#5B21B6;font-weight:800">Generating AI executive report...</div>';
  var ctx = execBuildAIContext(type);
  var brief={weekly_summary:'weekly executive HSE summary',executive_summary:'board executive HSE summary',monthly_report:'monthly HSE management report',annual_stats:'annual HSE statistics review'}[type]||'executive HSE report';
  var prompt='You are AURIS360, a senior HSE executive reporting assistant. Prepare a '+brief+' from the live data below. Return STRICT JSON only with keys: executive_summary string, red_flags array of strings, positive_notes array of strings, management_decisions array of strings, next_week_priorities array of strings, recommended_actions array of strings. Be specific, use the numbers provided, avoid exaggeration, and write in a professional board-ready tone. Data: '+JSON.stringify(ctx);
  try {
    var raw=await callAI([{role:'user',content:prompt}], 'You are a senior HSE director preparing concise board-ready safety performance reports. Output valid JSON only.');
    var data=aiExtractJson(raw)||raw;
    outEl.innerHTML=execAIRenderReport(data,type,ctx);
    toast('AI executive report generated');
  } catch(e) { outEl.innerHTML = aiFriendlyErrorHtml(e); }
}
async function execGenerateReport(type) {
  var outEl=document.getElementById('exec-report-output');
  var textEl=document.getElementById('exec-report-text');
  var titleEl=document.getElementById('exec-report-title');
  if(!outEl||!textEl) return;
  outEl.style.display='block';
  var titles={monthly:'Monthly HSE Report',board:'Board Dashboard Report',annual:'Annual HSE Statistics',esg:'ESG Report',sustainability:'Sustainability Report',compliance:'Compliance Report'};
  if(titleEl) titleEl.textContent = titles[type]||'HSE Report';
  textEl.textContent = 'Generating '+titles[type]+'...';
  var d = execData;
  var yr = d.yr || new Date().getFullYear();
  var ltiCnt = (d.events||[]).filter(function(x){return x.injury_type==='lti'||x.lost_time_days>0;}).length;
  var recCnt = (d.events||[]).filter(function(x){return x.injury_type||['injury','lti','medical_treatment'].includes(x.event_type);}).length;
  var manhours = (d.people||[]).length * 2000;
  var ltifr = manhours>0?(ltiCnt/manhours*1000000).toFixed(2):'N/A';
  var trir = manhours>0?(recCnt/manhours*200000).toFixed(2):'N/A';
  var lScores=(d.legal||[]).filter(function(x){return x.compliance_score!=null;}).map(function(x){return parseFloat(x.compliance_score)||0;});
  var compPct=lScores.length>0?Math.round(lScores.reduce(function(a,b){return a+b;},0)/lScores.length):0;
  var ctx = 'Organisation HSE data for '+yr+':\n'
    +'- Total incidents: '+(d.events||[]).length+'\n'
    +'- LTIs: '+ltiCnt+', Recordable: '+recCnt+'\n'
    +'- LTIFR: '+ltifr+', TRIR: '+trir+'\n'
    +'- Workforce: '+(d.people||[]).length+' active\n'
    +'- Legal compliance: '+compPct+'%\n'
    +'- Open actions: '+(d.actions||[]).filter(function(x){return x.status!=='closed';}).length+'\n'
    +'- Environmental incidents: '+(d.events||[]).filter(function(x){return x.event_type==='environmental';}).length+'\n'
    +'- Spills: '+(d.spills||[]).length+'\n';
  var prompts = {
    monthly: ctx+'\n\nWrite a professional Monthly HSE Report for management. Include: Executive summary, Incident statistics, Compliance status, Training update, Actions update, Environmental performance, and Priorities for next month. Professional tone, ~400 words.',
    board: ctx+'\n\nWrite a Board-Level HSE Dashboard Report. Include: Safety performance vs targets, Critical incidents, Compliance headline, Key risks and mitigations, Executive decisions required. Board presentation style, ~350 words.',
    annual: ctx+'\n\nWrite an Annual HSE Statistics Report. Include: Year in review, LTIFR/TRIR with benchmark comparison, Incident trends, Top root causes, Compliance achievements, Lessons learned, Targets for next year. ~500 words.',
    esg: ctx+'\n\nWrite an ESG (Environmental, Social, Governance) Report section on Safety & Health. Cover: E - environmental incidents, spills, emissions; S - worker safety, training, wellbeing; G - compliance, governance, reporting. Aligned with GRI standards. ~400 words.',
    sustainability: ctx+'\n\nWrite a Sustainability Report HSE chapter. Cover: Health & safety performance, Environmental footprint, Social responsibility (worker welfare, training), Resource efficiency, and future sustainability targets. GRI/UN SDG aligned. ~400 words.',
    compliance: ctx+'\n\nWrite a Compliance Status Report. Cover: Legal compliance score, Gap analysis summary, Regulatory notifications, Open corrective actions by age, Audit performance, Compliance calendar outlook. ~350 words.',
  };
  try {
    textEl.textContent = await callAI([{role:'user',content:prompts[type]||ctx+'\n\nWrite a comprehensive HSE report. ~400 words.'}]) || 'No report generated.';
  } catch(e) { textEl.textContent = aiFriendlyError(e); }
}

function execExportReport() {
  var report = document.getElementById('exec-report-text')?.textContent;
  if(!report||report.includes('?')||report.includes('No report')) {
    toast('Generate a report first using the Reports tab', false); return;
  }
  var blob = new Blob([report], {type:'text/plain'});
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a'); a.href=url; a.download='HSE_Report_'+new Date().toISOString().slice(0,10)+'.txt'; a.click();
  URL.revokeObjectURL(url); toast('Report downloaded!');
}


let aiOpen=false,aiHist=[];
function toggleAI(){aiOpen=!aiOpen;document.getElementById('ai-window').className='ai-window'+(aiOpen?' open':'');}
const SYS='You are AURIS, an expert HSE AI assistant for AURIS360 by SEPHS Consulting (Mauritius). Analyse real HSE data and give specific, actionable recommendations. Be concise and professional.';
// -- AI configuration ----------------------------------------------------------
// Direct browser-to-AI-provider calls do not work safely because provider API
// keys must stay server-side. All AURIS AI calls go through /api/ai, where the
// provider is selected by Vercel environment variables.
const AI_PROXY_URL = '/api/ai';
const AI_URL = AI_PROXY_URL || '/api/ai';
const AI_AVAILABLE = !!AI_PROXY_URL;

function applyAIAvailability() {
  var allowed = AI_AVAILABLE && (typeof canUseAI !== 'function' || canUseAI());
  var selectors = [
    '#ai-panel',
    '#nav-ai',
    '[onclick*="genDashAI"]',
    '[onclick*="execGenerateReport"]',
    '[onclick*="invGenerateAISummary"]',
    '[onclick*="generateSafetyComm"]',
    '[onclick*="obsAskAI"]',
    '[onclick*="raAISuggest"]',
    '[onclick*="aiGenerate"]',
    '[onclick*="aiComplianceCheck"]',
    '[onclick*="aiPredictiveRisk"]',
    '[onclick*="aiScenarioRisk"]',
    '[onclick*="aiRiskHeatmap"]',
    '[onclick*="aiAnalyseDocument"]'
  ];
  document.querySelectorAll(selectors.join(',')).forEach(function(el) {
    if(!el.dataset.aiOriginalDisplay) el.dataset.aiOriginalDisplay = el.style.display || '__default__';
    if(allowed) el.style.display = el.dataset.aiOriginalDisplay === '__default__' ? '' : el.dataset.aiOriginalDisplay;
    else el.style.display = 'none';
  });
}
window.addEventListener('load', applyAIAvailability);

async function getCtx(){
try{
const[k,e,i,a,pe,certs]=await Promise.all([api('/kpis?select=*'+cf()),api('/events?select=*'+cf()+'&limit=20'),api('/inspections?select=*'+cf()+'&limit=10'),api('/action_tracker?select=*'+cf()),api('/people?select=*'+cf()),api('/people_certifications?select=*'+cf())]);
const soon=new Date();soon.setDate(soon.getDate()+30);
return `Company: ${co?.name||'Unknown'} | Industry: ${co?.industry||'Unknown'}
KPIs: ${(k||[]).length} total, ${(k||[]).filter(x=>x.status==='on_track').length} on track, ${(k||[]).filter(x=>x.status==='at_risk').length} at risk
Events: ${(e||[]).length} total, ${(e||[]).filter(x=>x.severity==='high'||x.severity==='critical').length} high/critical
Inspections: ${(i||[]).length}, avg good: ${i?.length?Math.round((i||[]).reduce((s,x)=>s+x.score_good,0)/(i||[]).length):0}/24
Actions: ${(a||[]).length} total, ${(a||[]).filter(x=>x.status==='open').length} open, ${(a||[]).filter(x=>x.priority==='critical').length} critical
People: ${(pe||[]).length} active (${(pe||[]).filter(x=>x.person_type==='employee').length} employees, ${(pe||[]).filter(x=>x.person_type==='contractor').length} contractors)
Expiring certs (30d): ${(certs||[]).filter(x=>x.expiry_date&&new Date(x.expiry_date)<soon).length}`;
}catch(e){return 'Unable to load data.';}
}

