// ===== SAFETY COMMUNICATION GENERATOR =====

function escH(str){
  return String(str||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// Validate untrusted URLs before placing them in href/src attributes. HTML
// escaping alone does not stop executable protocols such as javascript:.
function aurisSafeUrl(value, options){
  options=options||{};
  var raw=String(value||'').trim();
  if(!raw||/[\u0000-\u001F\u007F]/.test(raw))return '';
  if(raw.charAt(0)==='#')return options.allowHash===false?'':raw;
  try{
    var base=(window.location&&window.location.origin&&window.location.origin!=='null')?window.location.origin:'https://auris360.app';
    var parsed=new URL(raw,base);
    if(parsed.username||parsed.password)return '';
    var protocol=parsed.protocol.toLowerCase();
    if(protocol==='https:')return raw;
    if(protocol==='http:'&&(options.allowHttp||/^(?:localhost|127\.0\.0\.1|\[::1\])$/i.test(parsed.hostname)))return raw;
    if(options.allowBlob&&protocol==='blob:')return raw;
    if(options.allowContact&&(protocol==='mailto:'||protocol==='tel:'))return raw;
    if(options.allowDataImage&&protocol==='data:'&&/^data:image\/(?:png|jpe?g|gif|webp);base64,/i.test(raw))return raw;
    if(options.allowDataVideo&&protocol==='data:'&&/^data:video\/(?:mp4|webm|ogg);base64,/i.test(raw))return raw;
  }catch(_){return '';}
  return '';
}
function aurisSafeMediaUrl(value, kind){
  kind=String(kind||'document').toLowerCase();
  return aurisSafeUrl(value,{allowBlob:true,allowDataImage:kind==='image'||kind==='document',allowDataVideo:kind==='video'||kind==='document'});
}
function aurisSanitizeStoredHtml(value){
  var parser=new DOMParser();
  var doc=parser.parseFromString(String(value||''),'text/html');
  doc.querySelectorAll('script,iframe,object,embed,base,meta,link,form,input,button,select,textarea').forEach(function(el){el.remove();});
  doc.querySelectorAll('*').forEach(function(el){
    Array.from(el.attributes||[]).forEach(function(attr){
      var name=attr.name.toLowerCase();
      if(name.indexOf('on')===0||name==='srcdoc'||name==='formaction'){el.removeAttribute(attr.name);return;}
      if(name==='style'&&/(?:expression\s*\(|url\s*\(|@import|-moz-binding)/i.test(attr.value)){el.removeAttribute(attr.name);return;}
      if(name==='href'||name==='xlink:href'){
        var href=aurisSafeUrl(attr.value,{allowHash:true});
        if(href)el.setAttribute(attr.name,href);else el.removeAttribute(attr.name);
      }
      if(name==='src'){
        var src=aurisSafeMediaUrl(attr.value,el.tagName==='IMG'?'image':el.tagName==='VIDEO'||el.tagName==='SOURCE'?'video':'document');
        if(src)el.setAttribute(attr.name,src);else el.removeAttribute(attr.name);
      }
    });
    if(el.tagName==='A'&&el.getAttribute('target')==='_blank')el.setAttribute('rel','noopener noreferrer');
  });
  return doc.body.innerHTML;
}





function invShowForm(){
  document.getElementById('inv-list-view').style.display='none';
  document.getElementById('inv-form3view').style.display='block';
}


function invTypeChange(){
  var type=document.getElementById('inv-type-sel').value;
  var isFull=type==='full';
  var ws2btn=document.getElementById('inv-tab-ws2');
  var ws3btn=document.getElementById('inv-tab-ws3');
  if(ws2btn){ws2btn.className='inv-tab'+(isFull?'':' disabled');ws2btn.style.opacity=isFull?'1':'0.4';}
  if(ws3btn){ws3btn.className='inv-tab'+(isFull?'':' disabled');ws3btn.style.opacity=isFull?'1':'0.4';}
  if(!isFull){
    var active=document.querySelector('.inv-tab.active');
    if(active&&(active.id==='inv-tab-ws2'||active.id==='inv-tab-ws3'))invShowTab('ws1');
  }
}

async function invGenRef(yr){
  try{
    var cid=ccid();if(!cid)return 'INV-'+yr+'-XXX';
    var seq=await api('/inv_sequence?company_id=eq.'+cid+'&year=eq.'+yr);
    var next=1;
    if(seq&&seq.length){next=seq[0].last_seq+1;await api('/inv_sequence?company_id=eq.'+cid+'&year=eq.'+yr,{m:'PATCH',p:'return=minimal',b:{last_seq:next}});}
    else{await api('/inv_sequence',{m:'POST',p:'return=minimal',b:{company_id:cid,year:yr,last_seq:1}});}
    return 'INV-'+yr+'-'+String(next).padStart(3,'0');
  }catch(e){return 'INV-'+yr+'-'+Date.now().toString().slice(-3);}
}

