function noiseAudit(action,summary,row,details){
  try{
    row=row||{};
    auditLogEvent(action,'noise',summary,{
      reference:row.survey_ref||row.id?.slice(0,8)||'NOISE',
      site:row.site||null,
      survey_type:row.survey_type||null,
      survey_date:row.survey_date||null,
      conducted_by:row.conducted_by||null,
      measurement_points:Array.isArray(row.measurements)?row.measurements.length:null,
      details:details||{}
    },{related_table:'noise_surveys',related_id:row.id||details?.id||null,company_id:row.company_id||ccid()});
  }catch(_){}
}
async function saveNoise(){
try{
const bid=document.getElementById('nf-by').value;
var cal=document.getElementById('nf-cal').value||null;
var points=noisePointsFromForm(), hpe=noiseAssessHpe();
var base={company_id:ccid(),survey_type:document.getElementById('nf-type').value,site:document.getElementById('nf-site').value,survey_date:document.getElementById('nf-date').value||null,conducted_by:bid?pname(bid):prof?.full_name,instrument_used:document.getElementById('nf-instrument').value,calibration_date:cal,weather_conditions:document.getElementById('nf-weather').value,notes:document.getElementById('nf-notes').value,created_by:prof?.id,updated_at:new Date().toISOString()};
var body=Object.assign({},base,{layout_title:document.getElementById('nf-layout-name')?.value||null,layout_image:document.getElementById('nf-layout-data')?.value||null,measurements:points,hpe_assessment:hpe});
var saved=null;
try{
  if(window.noiseEditId){await api('/noise_surveys?id=eq.'+window.noiseEditId,{m:'PATCH',p:'return=minimal',b:body});saved=Object.assign({id:window.noiseEditId},body);}
  else{var created=await api('/noise_surveys',{m:'POST',p:'return=representation',b:body});saved=created?.[0]||body;}
}catch(e){
  if(!/schema cache|column|Could not find/i.test(e.message||''))throw e;
  if(window.noiseEditId){await api('/noise_surveys?id=eq.'+window.noiseEditId,{m:'PATCH',p:'return=minimal',b:base});saved=Object.assign({id:window.noiseEditId},base);}
  else{var createdBase=await api('/noise_surveys',{m:'POST',p:'return=representation',b:base});saved=createdBase?.[0]||base;}
  toast(isSA()
    ? 'Noise survey saved. Run auris360_production_schema_bundle_CLEAN.sql to keep plan, points and HPE assessment.'
    : 'Noise survey saved. Advanced plan/point details need admin setup before they are shared.',
    false);
}
noiseAudit(window.noiseEditId?'update':'create',window.noiseEditId?'Noise survey updated':'Noise survey created',Object.assign({},body,saved||{}),{points_count:points.length,hpe_count:hpe.length,layout_attached:!!body.layout_image});
var calBad=!cal||((new Date()-new Date(cal))/86400000>365);
if(calBad){
  try{await api('/action_tracker',{m:'POST',p:'return=minimal',b:{company_id:ccid(),source_module:'noise',source_id:(saved&&saved.id)||window.noiseEditId||null,source_ref:'Noise survey - '+(body.site||'site'),description:'Noise survey instrument calibration is missing or older than 12 months. Verify calibration before relying on results.',responsible:body.conducted_by||null,priority:'medium',status:'open',created_by:prof?.id}});noiseAudit('follow_up','Noise survey calibration action created',Object.assign({},body,saved||{}),{calibration_date:cal});}catch(ex){console.warn('Noise MAP action failed',ex);}
}
toggleForm('noise-form');toast('Noise survey saved!'+(calBad?' Calibration action added to MAP.':''));loadNoise();
}catch(e){toastActionError('Save noise survey','Noise Survey',e);}
}
function noiseCurrentSurveyDraft(){
  const bid=document.getElementById('nf-by')?.value;
  var points=noisePointsFromForm();
  return {
    id:window.noiseEditId||null,
    survey_type:document.getElementById('nf-type')?.value||'occupational',
    site:document.getElementById('nf-site')?.value||'',
    survey_date:document.getElementById('nf-date')?.value||'',
    conducted_by:bid?pname(bid):(prof?.full_name||''),
    instrument_used:document.getElementById('nf-instrument')?.value||'',
    calibration_date:document.getElementById('nf-cal')?.value||'',
    weather_conditions:document.getElementById('nf-weather')?.value||'',
    notes:document.getElementById('nf-notes')?.value||'',
    layout_title:document.getElementById('nf-layout-name')?.value||'',
    layout_image:document.getElementById('nf-layout-data')?.value||'',
    measurements:points,
    hpe_assessment:noiseAssessHpe()
  };
}
function noiseAssessRowsForPrint(points,hpe){
  points=noiseSafeJson(points,[]);
  hpe=noiseSafeJson(hpe,[]);
  if(hpe.length)return hpe;
  return points.map(function(p,i){
    var lex=noiseLex8h(p.leq,p.duration);
    var band=noiseExposureBand(lex);
    var snr=parseFloat(p.snr)||0;
    var protectedLevel=snr&&lex!=null?Math.max(0,lex-snr):null;
    var result=!(parseFloat(p.leq)||0)?'missing':(!snr?'review':(protectedLevel>85?'inadequate':protectedLevel<70?'review':'adequate'));
    return Object.assign({},p,{idx:i+1,lex8h:lex,exposure_band:band.label,exposure_action:band.action,exposure_badge:band.badge,protected_level:protectedLevel,result:result});
  });
}
function noiseReportRows(points,assessed){
  points=noiseSafeJson(points,[]);
  assessed=assessed||noiseAssessRowsForPrint(points,[]);
  return points.map(function(p,i){
    var a=assessed[i]||{};
    var status={adequate:'Adequate',inadequate:'Not adequate',review:'Review',missing:'Missing data'}[a.result]||'-';
    return '<tr><td>'+(i+1)+'</td><td><strong>'+escH(p.loc||'-')+'</strong><br><span>'+escH(p.source||'')+'</span></td><td>'+escH(p.leq||'-')+'</td><td>'+escH(p.peak||'-')+'</td><td>'+escH(p.duration||'8')+'</td><td>'+escH(p.persons||'-')+'</td><td>'+escH(p.existing_controls||'-')+'</td><td>'+escH(p.hpe||'-')+(p.snr?' / SNR '+escH(p.snr):'')+'</td><td>'+(a.lex8h!=null?a.lex8h.toFixed(1):'-')+'</td><td>'+(a.protected_level!=null?a.protected_level.toFixed(1):'-')+'</td><td>'+escH(status)+'</td><td>'+escH(p.further_controls||a.exposure_action||'-')+'<br><span>By: '+escH(p.action_by||'-')+' | Target: '+escH(p.target_date||'-')+'</span></td></tr>';
  }).join('');
}
function noisePrintSurveyData(x){
  x=x||noiseCurrentSurveyDraft();
  var points=noiseSafeJson(x.measurements,[]);
  var assessed=noiseAssessRowsForPrint(points,x.hpe_assessment);
  var maxLeq=points.reduce(function(m,p){return Math.max(m,parseFloat(p.leq)||0);},0);
  var high=points.filter(function(p){return (parseFloat(p.leq)||0)>=85;}).length;
  var company=(typeof printReportContextLabel==='function')?printReportContextLabel():'Current company';
  var plan=x.layout_image||x.layout_url||'';
  var markers=plan?points.map(function(p,i){var m=noiseLevelMeta(parseFloat(p.leq)||0);return '<span class="nm" style="left:'+(p.x||50)+'%;top:'+(p.y||50)+'%;background:'+m.color+'">'+(i+1)+'</span>';}).join(''):'';
  var html='<!doctype html><html><head><title>Noise Survey</title><style>@page{size:A4 landscape;margin:10mm}body{font-family:Arial,sans-serif;color:#0f172a}h1{font-size:22px;margin:0;color:#075985}.top{display:flex;justify-content:space-between;border-bottom:3px solid #0f766e;padding-bottom:8px;margin-bottom:10px}.meta{font-size:11px;text-align:right;color:#334155}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:10px 0}.card{border:1px solid #cbd5e1;border-radius:8px;padding:8px}.card b{display:block;font-size:18px;color:#0f766e}table{border-collapse:collapse;width:100%;font-size:9px;table-layout:fixed}th{background:#173f63;color:#fff;text-align:left;padding:5px;border:1px solid #173f63}td{vertical-align:top;padding:5px;border:1px solid #cbd5e1;white-space:normal;word-break:break-word}td span{color:#475569}.layout{position:relative;border:1px solid #cbd5e1;border-radius:8px;margin:10px 0;max-height:310px;overflow:hidden;text-align:center}.layout img{max-width:100%;max-height:300px}.nm{position:absolute;transform:translate(-50%,-50%);width:24px;height:24px;border-radius:999px;color:#fff;font-weight:800;font-size:11px;display:flex;align-items:center;justify-content:center;border:2px solid #fff;box-shadow:0 1px 5px #0005}.note{font-size:10px;color:#475569}.foot{margin-top:10px;font-size:10px;color:#475569;border-top:1px solid #cbd5e1;padding-top:6px}</style></head><body>'
    +'<div class="top"><div><h1>Noise Survey Report</h1><div class="note">'+escH(company)+' - Occupational noise assessment and HPE adequacy</div></div><div class="meta"><strong>'+escH(x.survey_ref||x.id||'NOISE-AUTO')+'</strong><br>Generated: '+new Date().toLocaleDateString('en-GB')+'<br>Survey date: '+escH(x.survey_date||'-')+'</div></div>'
    +'<div class="cards"><div class="card">Site / area<b>'+escH(x.site||'-')+'</b></div><div class="card">Survey type<b>'+escH(x.survey_type||'-')+'</b></div><div class="card">Max Leq<b>'+((maxLeq||0).toFixed(1))+' dB(A)</b></div><div class="card">Mandatory zones<b>'+high+'</b></div></div>'
    +'<table><tbody><tr><th>Conducted by</th><td>'+escH(x.conducted_by||'-')+'</td><th>Instrument</th><td>'+escH(x.instrument_used||'-')+'</td><th>Calibration date</th><td>'+escH(x.calibration_date||'-')+'</td><th>Conditions</th><td>'+escH(x.weather_conditions||'-')+'</td></tr></tbody></table>'
    +(plan?'<div class="layout"><img src="'+escH(plan)+'" alt="Noise map">'+markers+'</div>':'')
    +'<h2 style="font-size:15px;margin:12px 0 6px;color:#173f63">Measurements, Controls and HPE Assessment</h2>'
    +'<table><thead><tr><th style="width:3%">#</th><th style="width:13%">Location / source</th><th style="width:6%">Leq</th><th style="width:6%">Peak</th><th style="width:5%">Hours</th><th style="width:5%">People</th><th style="width:15%">Existing controls</th><th style="width:10%">HPE</th><th style="width:6%">LEX,8h</th><th style="width:7%">Protected</th><th style="width:8%">Status</th><th style="width:16%">Further action</th></tr></thead><tbody>'+(points.length?noiseReportRows(points,assessed):'<tr><td colspan="12">No measurement points recorded.</td></tr>')+'</tbody></table>'
    +'<h2 style="font-size:15px;margin:12px 0 6px;color:#173f63">Notes</h2><div class="card">'+escH(x.notes||'No notes recorded.')+'</div>'
    +'<div class="foot">AURIS360 noise survey report. HPE calculation is indicative and must be reviewed by a competent person where exposure is high, variable or uncertain.</div>'
    +'</body></html>';
  var w=window.open('','_blank','width=1280,height=820');
  if(!w){toast('Allow pop-ups to print the noise survey',false);return;}
  w.document.write(html);w.document.close();setTimeout(function(){try{w.focus();w.print();}catch(e){}},700);
}
