function chemSplitList(v){
  return (v||'').split(/[,;\n]+/).map(function(x){return x.trim();}).filter(Boolean);
}

function chemRiskFromForm(){
  var text=[document.getElementById('chem3hcodes')?.value,document.getElementById('chem3hazards')?.value,document.getElementById('chem3consequences')?.value].join(' ').toUpperCase();
  var severity=2;
  if(/H3(00|10|30|40|50|60|70|72)|FATAL|CARCINOGEN|MUTAGEN|REPROTOXIC|STOT|DEATH/.test(text))severity=5;
  else if(/H3(01|11|14|17|18|31|34|51)|TOXIC|CORROSIVE|SERIOUS EYE|RESPIRATORY SENSITI/.test(text))severity=4;
  else if(/H2(24|25|26|28|90)|H3(02|12|15|19|32|35|36|41)|FLAMMABLE|HARMFUL|IRRITANT/.test(text))severity=3;
  var freq=document.getElementById('chem3frequency')?.value||'occasional';
  var dur=document.getElementById('chem3duration')?.value||'short';
  var task=document.getElementById('chem3task')?.value||'closed_handling';
  var people=parseInt(document.getElementById('chem3persons')?.value)||0;
  var controls=(document.getElementById('chem3controls')?.value||'').toLowerCase();
  var likelihood={rare:1,occasional:2,weekly:3,daily:4,continuous:5}[freq]||2;
  likelihood+=({minutes:0,short:0,hours:1,shift:2}[dur]||0);
  likelihood+=({closed_handling:0,open_handling:1,mixing:1,spraying:2,heating:2,confined_space:3}[task]||0);
  if(/lev|local exhaust|closed system|fume hood|ventilation|automated|enclosed/.test(controls))likelihood-=1;
  if(/no control|none|not available/.test(controls))likelihood+=1;
  likelihood=Math.max(1,Math.min(5,likelihood));
  var peopleFactor=people>=20?4:people>=10?3:people>=5?2:people>=1?1:0;
  var score=(severity*likelihood)+peopleFactor;
  var level=score>=22?'critical':score>=15?'high':score>=8?'medium':'low';
  return {severity:severity,likelihood:likelihood,score:score,level:level};
}

function chemUpdateRiskPreview(){
  var r=chemRiskFromForm();
  var el=document.getElementById('chem3risk-preview');if(!el)return r;
  var c=CHEM_RISK_CFG[r.level]||CHEM_RISK_CFG.medium;
  el.innerHTML='<div style="background:'+c.bg+';color:'+c.tc+';border:1px solid '+(r.level==='critical'?'#fecaca':'#fcd34d')+';border-radius:10px;padding:12px"><div style="font-size:12px;font-weight:700;text-transform:uppercase;margin-bottom:4px">Calculated risk</div><div style="font-size:28px;font-weight:900">'+c.label+' <span style="font-size:14px;font-weight:700">score '+r.score+'</span></div><div style="font-size:11px;margin-top:4px">Severity '+r.severity+' x likelihood '+r.likelihood+' plus persons exposed factor.</div></div>';
  return r;
}

function chemExposureBackupPayload(g){
  return {
    location:g('chem3location'),
    department:g('chem3dept'),
    process_use:g('chem3use'),
    quantity_stored:g('chem3qty'),
    persons_exposed:parseInt(g('chem3persons'))||0,
    exposure_frequency:g('chem3frequency')||'occasional',
    exposure_duration:g('chem3duration')||'short',
    task_type:g('chem3task')||'closed_handling'
  };
}

function chemHazardPictogramPayload(g){
  var current=chemEditId?chemData.find(function(x){return x.id===chemEditId;}):null;
  var existing=Array.isArray(current?.hazard_pictograms)?current.hazard_pictograms:[];
  var visible=existing.filter(function(v){return !(typeof v==='string'&&v.indexOf(CHEM_EXPOSURE_BACKUP_PREFIX)===0);});
  visible.push(CHEM_EXPOSURE_BACKUP_PREFIX+JSON.stringify(chemExposureBackupPayload(g)));
  return visible;
}

function chemRecommend(){
  var r=chemRiskFromForm();
  var lines=[];
  if(r.level==='critical'||r.level==='high')lines.push('Stop or tightly control the task until exposure controls are confirmed adequate.');
  lines.push('Confirm SDS is current and available at the point of use.');
  lines.push('Verify suitable ventilation/LEV or closed handling where vapours, dusts or mists may be generated.');
  lines.push('Confirm PPE selection matches SDS Section 8 and task exposure route.');
  lines.push('Ensure spill response materials, eyewash/shower and first aid arrangements are available.');
  if(/H3(34|17|50|60|72)|SENSITI|CARCINOGEN|MUTAGEN|REPROTOXIC/i.test([document.getElementById('chem3hcodes')?.value,document.getElementById('chem3hazards')?.value].join(' ')))lines.push('Consider occupational health surveillance due to sensitiser/carcinogen/reprotoxic/long-term health hazard indicators.');
  document.getElementById('chem3recommendations').value=lines.join('\n');
}
