async function loadMtgs(){
  var btn=document.getElementById('mtg-new-series-btn');
  if(btn)btn.style.display=isMgr()?'inline-flex':'none';
  mtgRoadmapYear=new Date().getFullYear();
  var yl=document.getElementById('mtg-agenda-year');
  if(yl)yl.textContent=mtgRoadmapYear;
  ['schedule','minutes','tbt','alerts','bulletins'].forEach(function(t){
    var el=document.getElementById('mtg-view-'+t);if(el)el.style.display=t==='schedule'?'block':'none';
  });
  document.querySelectorAll('[id^="mtg-tab-"]').forEach(function(t){t.classList.remove('active');});
  var scheduleTab=document.getElementById('mtg-tab-schedule');if(scheduleTab)scheduleTab.classList.add('active');
  // Role-gate the toolbox-talks / safety-alert / bulletin add buttons (was in a separate override)
  ['tbt-add-btn','alert-add-btn','bull-add-btn'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.style.display=isMgr()?'inline-flex':'none';
  });
  var container=document.getElementById('mtg-roadmap-container');
  if(container)container.innerHTML='<div class="loading-msg">Loading roadmap...</div>';
  mtgKickAgendaRoadmap();
}

function mtgKickAgendaRoadmap(){
  var run=async function(){
    try{
      // The Minutes tab reliably primes the meeting dataset; do that silently before painting Agenda.
      if(typeof mtgLoadMinutes==='function')await mtgLoadMinutes();
    }catch(e){console.warn('Minutes preload for roadmap failed',e);}
    try{await mtgLoadSeries();}
    catch(e){
      console.error(e);
      var c=document.getElementById('mtg-roadmap-container');
      if(c)c.innerHTML='<div style="padding:20px;color:#A32D2D;text-align:center">Could not load roadmap: '+((e&&e.message)||e)+'</div>';
    }
  };
  setTimeout(run,50);
  [500,1500,3000].forEach(function(delay){
    setTimeout(function(){
      var c=document.getElementById('mtg-roadmap-container');
      if(c&&/Loading roadmap/i.test(c.textContent||''))run();
    },delay);
  });
}
async function mtgLoadSeries(){
  var el=document.getElementById('mtg-series-list');
  try{
    var d=await api('/meeting_series?select=*'+cf()+'&order=meeting_type,title');
    mtgSeriesData=d||[];
    try{
      var mins=await api('/hse_meetings?select=id,series_id,meeting_date,status'+cf());
      mtgMinutesData=mins||[];
    }catch(_){}
    if(!d||!d.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">'
        +'<div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div>'
        +'<div style="font-weight:600;margin-bottom:8px">No meeting schedules yet</div>'
        +(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0059"><i class="ti ti-plus"></i>Add first schedule</button>':'<div>Contact your HSE manager to set up meeting schedules</div>')
        +'</div>';
      mtgRenderRoadmap();
      return;
    }
    var h='<div class="table-scroll"><table class="data-table" style="min-width:980px">'
      +'<thead><tr>'
      +'<th style="padding:9px 12px;text-align:left;color:#fff">Type</th>'
      +'<th style="padding:9px 12px;text-align:left;color:#fff">Meeting</th>'
      +'<th style="padding:9px 12px;text-align:left;color:#fff">Frequency</th>'
      +'<th style="padding:9px 12px;text-align:left;color:#fff">Chaired by</th>'
      +'<th style="padding:9px 12px;text-align:left;color:#fff">Location</th>'
      +'<th style="padding:9px 12px;text-align:left;color:#fff">Next date</th>'
      +'<th style="padding:9px 12px;text-align:left;color:#fff">Status</th>'
      +'<th style="padding:9px 12px;text-align:right;color:#fff">Actions</th>'
      +'</tr></thead><tbody>';
    d.forEach(function(s,i){
      var nextDt=s.next_date?new Date(s.next_date).toLocaleDateString('en-GB'):'Not set';
      var isOverdue=s.next_date&&new Date(s.next_date)<new Date()&&s.active!==false;
      var active=s.active!==false;
      var statusLabel=active?(isOverdue?'Overdue':'Active'):'Inactive';
      var statusColor=active?(isOverdue?'#DC2626':'#1D9E75'):'#6B7280';
      var typeLabel=MTG_TYPES[s.meeting_type]||s.meeting_type||'Other';
      h+='<tr style="background:'+(i%2?'#f9fafb':'#fff')+';border-bottom:1px solid #e5e7eb">'
        +'<td style="padding:10px 12px;font-weight:700;color:#0F6E56">'+escH(typeLabel)+'</td>'
        +'<td style="padding:10px 12px"><div style="font-weight:800;color:#111827">'+escH(s.title||'--')+'</div>'+(s.notes?'<div style="font-size:11px;color:var(--text2);margin-top:2px">'+escH(String(s.notes).substring(0,90))+(String(s.notes).length>90?'...':'')+'</div>':'')+'</td>'
        +'<td style="padding:10px 12px">'+escH(MTG_RECURRENCE[s.recurrence]||s.recurrence||'--')+'</td>'
        +'<td style="padding:10px 12px">'+escH(s.chaired_by||'--')+'</td>'
        +'<td style="padding:10px 12px">'+escH(s.location||'--')+'</td>'
        +'<td style="padding:10px 12px;font-weight:'+(isOverdue?'800':'600')+';color:'+(isOverdue?'#DC2626':'#374151')+'">'+escH(nextDt)+(isOverdue?' <i class="ti ti-alert-triangle"></i>':'')+'</td>'
        +'<td style="padding:10px 12px"><span style="background:'+statusColor+'15;color:'+statusColor+';padding:3px 8px;border-radius:99px;font-size:10px;font-weight:800">'+statusLabel+'</span></td>'
        +'<td style="padding:10px 12px;text-align:right;white-space:nowrap"><button class="btn btn-primary btn-sm" data-id="'+s.id+'" data-auris-generated-onclick="g0060"><i class="ti ti-file-text"></i>Schedule</button>'
        +(isMgr()?'<button class="btn btn-sm" data-id="'+s.id+'" data-auris-generated-onclick="g0061" title="Edit schedule" style="margin-left:6px"><i class="ti ti-edit"></i></button>':'')
        +'</td></tr>';
    });
    h+='</tbody></table></div>';
    if(isMgr()){
      h+='<div style="padding:14px 20px;text-align:center;border-top:1px solid var(--border)">'
        +'<button class="btn btn-sm" data-auris-generated-onclick="g0059"><i class="ti ti-plus"></i> Add new meeting schedule</button>'
        +'</div>';
    }
    if(el)el.innerHTML=h;
  }catch(e){
    if(el)el.innerHTML=registerErrorHtml('register',e.message);
    var rc=document.getElementById('mtg-roadmap-container');
    if(rc)rc.innerHTML='<div style="padding:20px;color:#A32D2D;text-align:center">Could not load roadmap: '+((e&&e.message)||e)+'</div>';
    console.error(e);
  }
  // Render roadmap after series loaded
  mtgRenderRoadmap();
  setTimeout(function(){var c=document.getElementById('mtg-roadmap-container');if(c&&/Loading roadmap/i.test(c.textContent||''))mtgRenderRoadmap();},150);
  setTimeout(function(){var c=document.getElementById('mtg-roadmap-container');if(c&&/Loading roadmap/i.test(c.textContent||''))mtgRenderRoadmap();},600);
}

function mtgMissingColumnName(e){
  var msg=String((e&&e.message)||e||'');
  var m=msg.match(/Could not find the '([^']+)' column/i);
  if(m)return m[1];
  m=msg.match(/column\s+(?:"?([a-zA-Z0-9_]+)"?\.)?"?([a-zA-Z0-9_]+)"?\s+does not exist/i);
  if(m)return m[2]||m[1];
  return '';
}
function mtgIsSchemaColumnError(e){
  return /schema cache|Could not find|column .* does not exist/i.test(String((e&&e.message)||e||''));
}
async function mtgApiWithSchemaFallback(path,opts,optionalCols){
  opts=opts||{};
  optionalCols=optionalCols||[];
  var body=Object.assign({},opts.b||{});
  var removed=[];
  for(var attempt=0;attempt<=optionalCols.length+2;attempt++){
    try{
      return await api(path,Object.assign({},opts,{b:opts.b?body:undefined}));
    }catch(e){
      if(!opts.b||!mtgIsSchemaColumnError(e))throw e;
      var col=mtgMissingColumnName(e);
      if(col&&Object.prototype.hasOwnProperty.call(body,col)){
        delete body[col];
        removed.push(col);
        continue;
      }
      var next=optionalCols.find(function(c){return Object.prototype.hasOwnProperty.call(body,c)&&removed.indexOf(c)===-1;});
      if(!next)throw e;
      delete body[next];
      removed.push(next);
    }
  }
  return await api(path,Object.assign({},opts,{b:body}));
}
async function mtgReadMinuteForDelete(id){
  try{
    var rows=await api('/hse_meetings?id=eq.'+id+'&select=status,minutes');
    return rows?.[0]||{};
  }catch(e){
    if(!mtgIsSchemaColumnError(e))throw e;
    try{
      var rows2=await api('/hse_meetings?id=eq.'+id+'&select=status');
      return rows2?.[0]||{};
    }catch(e2){
      if(!mtgIsSchemaColumnError(e2))throw e2;
      return {};
    }
  }
}

