function mtgScheduleMeeting(seriesId){
  var s=mtgSeriesData.find(function(x){return x.id===seriesId;});
  mtgEditingMomId=null;
  // Clear form
  mtgClearMom();
  // Pre-fill from series
  if(s){
    var tp=document.getElementById('mom3type');if(tp)tp.value=s.meeting_type||'management_review';
    var ti=document.getElementById('mom3title');if(ti){ti.value=s.title||'';document.getElementById('mom3header-title').textContent=s.title||'HSE Meeting';}
    var loc=document.getElementById('mom3location');if(loc)loc.value=s.location||'';
    fillPersonSelect('mom3chaired-by',s.chaired_by||'');
    fillPersonSelect('mom3sign-chair',s.chaired_by||'');
    // Set date to next scheduled date or today
    var dt=document.getElementById('mom3date');
    if(dt)dt.value=(s.next_date?s.next_date+'T09:00':new Date().toISOString().slice(0,16));
    // Set next meeting date based on recurrence
    var nextDate=mtgCalcNextDate(s.next_date||new Date().toISOString().slice(0,10), s.recurrence);
    var nd=document.getElementById('mom3next-date');if(nd)nd.value=nextDate;
    // Store series id for later update
    document.getElementById('mtg-mom3form').dataset.seriesId=seriesId;
  }
  document.getElementById('mtg-view-schedule').style.display='none';
  document.getElementById('mtg-view-minutes').style.display='none';
  document.getElementById('mtg-series-form').style.display='none';
  document.getElementById('mtg-mom3form').style.display='block';
  document.getElementById('mtg-mom3title').textContent='New Minutes of Meeting';
  document.getElementById('mtg-mom3ref').textContent='';
  document.getElementById('mtg-mom3del-btn').style.display='none';
  var sendBtnN=document.getElementById('mtg-mom3send-btn');if(sendBtnN)sendBtnN.style.display='none';
  momPopulateDropdowns();
}

function mtgCalcNextDate(fromDate, recurrence){
  var d=new Date(fromDate);
  var months={'monthly':1,'bimonthly':2,'quarterly':3,'triannual':4,'biannual':6,'annual':12};
  var m=months[recurrence]||3;
  d.setMonth(d.getMonth()+m);
  return d.toISOString().slice(0,10);
}

