function mtgSendMinutes(){
  var title=document.getElementById('mom3title')?.value||'HSE Meeting';
  var dt=document.getElementById('mom3date')?.value;
  var dtStr=dt?new Date(dt).toLocaleDateString('en-GB'):'';
  var attendees=momGetAttendees();
  var agenda=[];
  document.querySelectorAll('#mom3agenda-body tr').forEach(function(tr,i){
    var item=tr.querySelector('.mom3agenda-item')?.value||'';
    var notes=tr.querySelector('.mom3agenda-notes')?.value||'';
    if(item)agenda.push((i+1)+'. '+item+(notes?' - '+notes:''));
  });
  var recs=[];
  document.querySelectorAll('#mom3rec-body tr').forEach(function(tr){
    var desc=tr.querySelector('.mom3rec-desc')?.value||'';
    var resp=tr.querySelector('.mom3rec-resp')?.value||'';
    var date=tr.querySelector('.mom3rec-date')?.value||'';
    if(desc)recs.push('- '+desc+(resp?' ('+resp+')':(date?' - '+date:'')));
  });
  var notes=document.getElementById('mom3notes')?.value||'';
  var nextDate=document.getElementById('mom3next-date')?.value;
  var nextStr=nextDate?new Date(nextDate).toLocaleDateString('en-GB'):'';

  var body='MINUTES OF MEETING\n'
    +'===========================================\n'
    +title+'\n'
    +(dtStr?'Date: '+dtStr+'\n':'')
    +(document.getElementById('mom3location')?.value?'Location: '+document.getElementById('mom3location').value+'\n':'')
    +(document.getElementById('mom3chaired-by')?.value?'Chaired by: '+document.getElementById('mom3chaired-by').value+'\n':'')
    +'\nATTENDEES:\n'+(attendees||'-')+'\n'
    +(agenda.length?'\nAGENDA & DISCUSSION:\n'+agenda.join('\n')+'\n':'')
    +(recs.length?'\nACTIONS & RECOMMENDATIONS:\n'+recs.join('\n')+'\n':'')
    +(notes?'\nOTHER NOTES:\n'+notes+'\n':'')
    +(nextStr?'\nNEXT MEETING: '+nextStr+'\n':'')
    +'\n---\nThis communication was sent from AURIS360 HSE Platform.';

  var subject=encodeURIComponent('Minutes of Meeting - '+title+(dtStr?' ('+dtStr+')':''));
  var emailBody=encodeURIComponent(body);
  window.location.href='mailto:?subject='+subject+'&body='+emailBody;
  toast('Opening email client with minutes...');
}


async function mtgSaveMom(){
  var title=document.getElementById('mom3title')?.value?.trim();
  if(!title){toast('Please enter a meeting title',false);return;}
  var recs=mtgCollectRecs();
  var agenda=mtgCollectAgenda();
  var signoff=mtgCollectSignoff();
  var meta=mtgCollectMeta();
  var body={
    company_id:ccid(),
    series_id:document.getElementById('mtg-mom3form').dataset.seriesId||null,
    meeting_type:document.getElementById('mom3type')?.value||'management_review',
    title:title,
    meeting_date:document.getElementById('mom3date')?.value||null,
    location:document.getElementById('mom3location')?.value||null,
    chaired_by:document.getElementById('mom3chaired-by')?.value||null,
    attendees:momGetAttendees()||null,
    chair_person_id:personFromValue(document.getElementById('mom3chaired-by')?.value)?.id||null,
    attendee_person_ids:personIdsFromText(momGetAttendees()),
    apologies:momGetApologies()||null,
    minutes:document.getElementById('mom3notes')?.value||null,
    next_meeting_date:document.getElementById('mom3next-date')?.value||null,
    agenda_items:mtgBuildAgendaPayload(agenda,signoff),
    recommendations:mtgBuildRecommendationPayload(recs,meta),
    status:document.getElementById('mom3status')?.value||'draft',
    updated_at:new Date().toISOString()
  };
  try{
    var savedId=mtgEditingMomId;
    var minuteOptionalCols=['series_id','apologies','next_meeting_date','agenda_items','recommendations','status','updated_at','created_by','chair_person_id','attendee_person_ids'];
    if(mtgEditingMomId){
      await mtgApiWithSchemaFallback('/hse_meetings?id=eq.'+mtgEditingMomId,{m:'PATCH',p:'return=minimal',b:body},minuteOptionalCols);
      toast('Minutes updated!');
    }else{
      body.created_by=prof?.id;
      var res=await mtgApiWithSchemaFallback('/hse_meetings',{m:'POST',p:'return=representation',b:body},minuteOptionalCols);
      savedId=res?.[0]?.id;
      toast('Minutes saved!');
    }
    // Update series next_date if series linked
    var seriesId=document.getElementById('mtg-mom3form').dataset.seriesId;
    if(seriesId){
      var nd=document.getElementById('mom3next-date')?.value;
      if(nd)await mtgApiWithSchemaFallback('/meeting_series?id=eq.'+seriesId,{m:'PATCH',p:'return=minimal',b:{next_date:nd,updated_at:new Date().toISOString()}},['updated_at']);
    }
    // Sync recommendations to MAP
    if(savedId&&recs.length){
      try{await api('/action_tracker?source_module=eq.meeting&source_id=eq.'+savedId,{m:'DELETE'});}catch(ex){}
      var ref=title+' ('+new Date(body.meeting_date||new Date()).toLocaleDateString('en-GB')+')';
      for(var i=0;i<recs.length;i++){
        var r=recs[i];
        await api('/action_tracker',{m:'POST',p:'return=minimal',b:{
          company_id:ccid(),source_module:'meeting',source_id:savedId,
          source_ref:ref,description:r.desc,responsible:r.resp||null,
          target_date:r.date||null,priority:r.prio||'medium',
          status:r.status||'open',created_by:prof?.id
        }});
      }
      toast('Minutes saved! '+recs.length+' action(s) synced to Master Action Plan.');
    }
    // Reload agenda to reflect completed status
    try{
      var mins=await api('/hse_meetings?select=id,series_id,meeting_date,status'+cf());
      mtgMinutesData=mins||[];
    }catch(ex){}
    mtgMomBack();
  }catch(e){toastActionError('Save meeting minutes','HSE Meetings',e);console.error(e);}
}

async function mtgDeleteMom(){
  if(!mtgEditingMomId)return;
  try{
    var current=await mtgReadMinuteForDelete(mtgEditingMomId);
    if(current.status!=='cancelled'&&!ohIsArchivedText(current.minutes)){
      if(!(await appConfirmAction({title:'Cancel meeting minutes',message:'Cancel/archive these minutes instead of deleting them?',detail:'Meeting minutes and linked actions remain available for audit history.',confirmText:'Cancel minutes',cancelText:'Back',variant:'danger'})))return;
      await mtgApiWithSchemaFallback('/hse_meetings?id=eq.'+mtgEditingMomId,{m:'PATCH',p:'return=minimal',b:{status:'cancelled',minutes:ohArchivedText(current.minutes),updated_at:new Date().toISOString()}},['minutes','updated_at','status']);
      toast('Minutes cancelled/archived');
      mtgMomBack();
      return;
    }
    if(!(await appConfirmDelete('cancelled meeting minutes','Permanent deletion should be used only for duplicate/test minutes. Linked meeting actions will also be removed.')))return;
    await api('/action_tracker?source_module=eq.meeting&source_id=eq.'+mtgEditingMomId,{m:'DELETE'});
    await api('/hse_meetings?id=eq.'+mtgEditingMomId,{m:'DELETE'});
    toast('Minutes deleted!');
    mtgMomBack();
  }catch(e){toastActionError('Delete meeting minutes','HSE Meetings',e);console.error(e);}
}

function mtgMomBack(){
  document.getElementById('mtg-mom3form').style.display='none';
  document.getElementById('mtg-series-form').style.display='none';
  document.getElementById('mtg-view-minutes').style.display='none';
  document.getElementById('mtg-view-schedule').style.display='block';
  // Reset active tab
  document.querySelectorAll('[id^="mtg-tab-"]').forEach(function(t){t.classList.remove('active');});
  var tab=document.getElementById('mtg-tab-schedule');if(tab)tab.classList.add('active');
  mtgLoadSeries();
}

