async function mtgOpenMom(id){
  var m=mtgMinutesData.find(function(x){return x.id===id;});
  if(!m){
    try{var d=await api('/hse_meetings?id=eq.'+id+'&select=*');m=d&&d[0];}
    catch(e){toastActionError('Open meeting minutes','HSE Meetings',e);return;}
  }
  if(!m)return;
  mtgEditingMomId=id;
  mtgClearMom();
  document.getElementById('mtg-mom3form').dataset.seriesId=m.series_id||'';
  var flds={'mom3title':'title','mom3location':'location','mom3chaired-by':'chaired_by',
    'mom3notes':'minutes','mom3sign-chair':'chaired_by'};
  Object.entries(flds).forEach(function(e){var el=document.getElementById(e[0]);if(el)el.value=m[e[1]]||'';});
  fillPersonSelect('mom3chaired-by',m.chaired_by);fillPersonSelect('mom3sign-chair',m.chaired_by);
  var hdr=document.getElementById('mom3header-title');if(hdr)hdr.textContent=m.title||'HSE Meeting';
  momPopulateDropdowns();
  if(m.attendees)momSetAttendees(m.attendees);
  if(m.apologies)momSetApologies(m.apologies);
  var sendBtn=document.getElementById('mtg-mom3send-btn');if(sendBtn)sendBtn.style.display='inline-flex';
  var tp=document.getElementById('mom3type');if(tp)tp.value=m.meeting_type||'management_review';
  var st=document.getElementById('mom3status');if(st)st.value=m.status||'draft';
  var dt=document.getElementById('mom3date');if(dt)dt.value=m.meeting_date?m.meeting_date.slice(0,16):'';
  var nd=document.getElementById('mom3next-date');if(nd)nd.value=m.next_meeting_date||'';
  var agendaPayload=mtgSplitAgendaPayload(m.agenda_items);
  var recommendationPayload=mtgSplitRecommendationPayload(m.recommendations);
  mtgApplyMeta(recommendationPayload.meta,agendaPayload.signoff);
  // Render agenda items
  var ab=document.getElementById('mom3agenda-body');
  if(ab&&agendaPayload.items&&agendaPayload.items.length){
    ab.innerHTML='';
    agendaPayload.items.forEach(function(a,i){
      var tr=document.createElement('tr');
      tr.innerHTML='<td style="padding:6px;text-align:center;border:1px solid var(--border);font-weight:700;font-size:12px;color:var(--text2)">'+(i+1)+'</td>'
        +'<td style="padding:4px;border:1px solid var(--border)"><input type="text" class="mom3agenda-item" value="'+escH2(a.item||'')+'" style="width:100%;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/></td>'
        +'<td style="padding:4px;border:1px solid var(--border)"><textarea class="mom3agenda-notes" style="width:100%;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px;min-height:50px;resize:vertical">'+escH2(a.notes||'')+'</textarea></td>'
        +'<td style="padding:4px;text-align:center;border:1px solid var(--border)"><button data-auris-generated-onclick="g0062" style="background:none;border:none;cursor:pointer;color:var(--red)"><i class="ti ti-x"></i></button></td>';
      ab.appendChild(tr);
    });
  }
  // Render recommendations
  var rb=document.getElementById('mom3rec-body');
  var re=document.getElementById('mom3rec-empty');
  var visibleRecommendations=recommendationPayload.recs||[];
  if(rb&&visibleRecommendations.length){
    if(re)re.style.display='none';
    rb.innerHTML='';
    visibleRecommendations.forEach(function(r){
      var tr=document.createElement('tr');
      tr.innerHTML='<td style="padding:6px;text-align:center;border:1px solid var(--border);font-weight:700;font-size:12px;color:var(--text2)">-</td>'
        +'<td style="padding:4px;border:1px solid var(--border)"><input type="text" class="mom3rec-desc" value="'+escH2(r.desc||'')+'" style="width:100%;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/></td>'
        +'<td style="padding:4px;border:1px solid var(--border)"><input type="text" class="mom3rec-resp" value="'+escH2(r.resp||'')+'" style="width:100%;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/></td>'
        +'<td style="padding:4px;border:1px solid var(--border)"><input type="date" class="mom3rec-date" value="'+(r.date||'')+'" style="width:100%;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/></td>'
        +'<td style="padding:4px;border:1px solid var(--border)"><select class="mom3rec-prio" style="width:100%;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"><option value="low"'+(r.prio==='low'?' selected':'')+'>Low</option><option value="medium"'+((!r.prio||r.prio==='medium')?' selected':'')+'>Medium</option><option value="high"'+(r.prio==='high'?' selected':'')+'>High</option><option value="critical"'+(r.prio==='critical'?' selected':'')+'>Critical</option></select></td>'
        +'<td style="padding:4px;border:1px solid var(--border)"><select class="mom3rec-status" style="width:100%;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"><option value="open"'+(r.status==='open'?' selected':'')+'>Open</option><option value="in_progress"'+(r.status==='in_progress'?' selected':'')+'>In progress</option><option value="closed"'+(r.status==='closed'?' selected':'')+'>Closed</option></select></td>'
        +'<td style="padding:4px;text-align:center;border:1px solid var(--border)"><button data-auris-generated-onclick="g0062" style="background:none;border:none;cursor:pointer;color:var(--red)"><i class="ti ti-x"></i></button></td>';
      rb.appendChild(tr);
    });
  }else if(re){re.style.display='block';}
  document.getElementById('mtg-mom3title').textContent='Minutes of Meeting';
  document.getElementById('mtg-mom3ref').textContent=m.title||'';
  document.getElementById('mtg-mom3del-btn').style.display=isMgr()?'inline-flex':'none';
  document.getElementById('mtg-view-schedule').style.display='none';
  document.getElementById('mtg-view-minutes').style.display='none';
  document.getElementById('mtg-series-form').style.display='none';
  document.getElementById('mtg-mom3form').style.display='block';
}

async function mtgDeleteMomFromList(id){
  try{
    var current=await mtgReadMinuteForDelete(id);
    if(current.status!=='cancelled'&&!ohIsArchivedText(current.minutes)){
      if(!(await appConfirmAction({title:'Cancel meeting minutes',message:'Cancel/archive these minutes instead of deleting them?',detail:'Meeting minutes and linked actions remain available for audit history.',confirmText:'Cancel minutes',cancelText:'Back',variant:'danger'})))return;
      await mtgApiWithSchemaFallback('/hse_meetings?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{status:'cancelled',minutes:ohArchivedText(current.minutes),updated_at:new Date().toISOString()}},['minutes','updated_at','status']);
      toast('Minutes cancelled/archived');
      mtgLoadMinutes();
      return;
    }
    if(!(await appConfirmDelete('cancelled meeting minutes','Permanent deletion should be used only for duplicate/test minutes. Linked meeting actions will also be removed.')))return;
    await api('/action_tracker?source_module=eq.meeting&source_id=eq.'+id,{m:'DELETE'});
    await api('/hse_meetings?id=eq.'+id,{m:'DELETE'});
    toast('Minutes deleted!');
    mtgLoadMinutes();
  }catch(e){toastActionError('Delete meeting minutes','HSE Meetings',e);console.error(e);}
}

function escH2(str){return String(str||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

async function saveMtg(){mtgSaveMom();}




let peAllData=[], peEditingId=null;

function peopleCanManage(){
const role=activeRole();
return isSA()||role==='admin'||role==='hse_manager'||role==='hr';
}
function peopleName(p){
return [p?.first_name,p?.last_name].filter(Boolean).join(' ').trim()||p?.email||'Person';
}
function peopleDefaultUserRole(p){
return (p?.person_type==='contractor'||p?.person_type==='subcontractor')?'contractor':'employee';
}
function peopleCompanyLoginSlug(){
var cid=ccid();
var c=(typeof adminCompaniesData!=='undefined'?adminCompaniesData:[]).find(function(x){return x.id===cid;});
var nm=c?.name||co?.name||'company';
return String(nm).toLowerCase().replace(/[^a-z0-9]/g,'').substring(0,20)||'company';
}
function peopleSyntheticEmail(p){
var name=peopleName(p).toLowerCase().replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,'.').replace(/^\.+|\.+$/g,'').substring(0,30)||'user';
return name+'@'+peopleCompanyLoginSlug()+'.local';
}
