function copySecurityClientSummary(){
var txt=securityClientSummaryText(securitySlaReadForm());
if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt).then(function(){toast('Security summary copied');}).catch(function(){toast(txt);});}
else toast(txt);
}
