async function loadSecuritySlaSettings(){
var el=document.getElementById('security-readiness-body');
if(!el)return;
el.innerHTML='<div class="loading">Loading security readiness...</div>';
var d=securitySlaDefaults();
var tableReady=true;
try{
var companyId=securitySlaCurrentCompany();
if(companyId){
var rows=await api('/security_sla_settings?company_id=eq.'+companyId+'&limit=1');
if(rows&&rows[0]&&rows[0].settings)d=Object.assign(d,rows[0].settings||{});
}
}catch(e){
tableReady=false;
console.warn('security_sla_settings unavailable:',e.message);
}
renderSecurityReadiness(d,tableReady);
}
function previewSecurityClientSummary(){
var txt=securityClientSummaryText(securitySlaReadForm());
var w=window.open('','_blank');
if(!w){toast('Popup blocked. Use Copy client summary instead.',false);return;}
w.document.write('<pre style="font-family:Arial,sans-serif;white-space:pre-wrap;line-height:1.5;padding:24px;max-width:900px;margin:auto">'+escH(txt)+'</pre>');
w.document.title='AURIS360 Security Summary';
w.document.close();
}
async function saveSecuritySlaSettings(){
if(!(isAdm()||activeRole()==='hse_manager')){toast('Only admins or HSE managers can save security settings',false);return;}
var companyId=securitySlaCurrentCompany();
if(!companyId){toast('No company selected',false);return;}
var settings=securitySlaReadForm();
try{
var existing=await api('/security_sla_settings?company_id=eq.'+companyId+'&limit=1');
var body={settings:settings,updated_at:new Date().toISOString(),updated_by:prof?.id||null};
if(existing&&existing[0])await api('/security_sla_settings?company_id=eq.'+companyId,{m:'PATCH',p:'return=minimal',b:body});
else{body.company_id=companyId;await api('/security_sla_settings',{m:'POST',p:'return=minimal',b:body});}
toast('Security/SLA settings saved');
loadSecuritySlaSettings();
}catch(e){
var msg=e.message||'Save failed';
if(msg.includes('schema cache')||msg.includes('security_sla_settings'))msg=isSA()?('Security/SLA setup required. Technical detail: '+msg):'Security/SLA settings require administrator configuration before shared use. Please contact SEPHS admin.';
toast(msg,false);
}
}

const CUSTOM_FIELD_MODULES=[
  {key:'events',label:'Incident Management',recordTable:'events'},
  {key:'observation',label:'BBS Observations',recordTable:'safety_observations'},
  {key:'inspection',label:'Audits & Inspections',recordTable:'inspections',future:true},
  {key:'permit',label:'Permit to Work',recordTable:'permits',future:true},
  {key:'risk',label:'Risk Assessment',recordTable:'risk_assessments',future:true}
];
let customFieldDefsCache={};
function customFieldsCanManage(){
  return isAdm()||activeRole()==='hse_manager';
}
function customFieldsCompanyId(){
  return (isSA()&&sephsCompanyContext)?sephsCompanyContext:prof?.company_id;
}
function customFieldMakeKey(label){
  return String(label||'field').toLowerCase().trim()
    .replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').substring(0,48)||'field';
}
function customFieldModuleLabel(key){
  var m=CUSTOM_FIELD_MODULES.find(function(x){return x.key===key;});
  return m?m.label:key;
}
async function customLoadDefinitions(moduleKey,includeInactive){
  var companyId=customFieldsCompanyId();
  if(!companyId)return [];
  var path='/custom_fields?company_id=eq.'+companyId+'&module_key=eq.'+encodeURIComponent(moduleKey)+'&order=sort_order.asc,field_label.asc';
  if(!includeInactive)path+='&active=eq.true';
  var rows=await api(path);
  customFieldDefsCache[moduleKey]=rows||[];
  return rows||[];
}
function customFieldValueFromJson(v){
  if(v===null||v===undefined)return '';
  if(typeof v==='object'&&Object.prototype.hasOwnProperty.call(v,'value'))return v.value;
  return v;
}
function customFieldOptions(field){
  var opts=field.options||[];
  if(typeof opts==='string'){
    try{opts=JSON.parse(opts);}catch(_){opts=opts.split(',');}
  }
  if(!Array.isArray(opts))opts=[];
  return opts.map(function(x){return String(x||'').trim();}).filter(Boolean);
}
function customFieldInputHtml(field,value){
  var id='cfv-'+field.id;
  var base=' id="'+id+'" data-custom3field-id="'+escH(field.id)+'" data-custom3field-key="'+escH(field.field_key)+'" data-custom3field-type="'+escH(field.field_type)+'"';
  value=customFieldValueFromJson(value);
  var required=field.required?' <span style="color:var(--red)">*</span>':'';
  var label='<label class="form3label">'+escH(field.field_label)+required+'</label>';
  if(field.field_type==='textarea'){
    return '<div class="form3group">'+label+'<textarea'+base+' style="min-height:70px">'+escH(value||'')+'</textarea></div>';
  }
  if(field.field_type==='select'){
    var opts=customFieldOptions(field);
    return '<div class="form3group">'+label+'<select'+base+'><option value="">Select...</option>'+opts.map(function(o){return '<option value="'+escH(o)+'" '+(String(value)===o?'selected':'')+'>'+escH(o)+'</option>';}).join('')+'</select></div>';
  }
  if(field.field_type==='checkbox'){
    var checked=(value===true||value==='true'||value==='yes')?'checked':'';
    return '<div class="form3group" style="display:flex;align-items:center;gap:8px;padding-top:22px"><input type="checkbox"'+base+' '+checked+' style="width:16px;height:16px;padding:0;margin:0;accent-color:var(--green)"/><label for="'+id+'" style="font-size:12px;font-weight:700;margin:0;cursor:pointer">'+escH(field.field_label)+required+'</label></div>';
  }
  var type=field.field_type==='number'?'number':(field.field_type==='date'?'date':'text');
  return '<div class="form3group">'+label+'<input type="'+type+'"'+base+' value="'+escH(value||'')+'"/></div>';
}
async function customLoadValues(recordTable,recordId){
  if(!recordId)return {};
  var rows=await api('/custom_field_values?record_table=eq.'+encodeURIComponent(recordTable)+'&record_id=eq.'+recordId);
  var map={};
  (rows||[]).forEach(function(r){map[r.field_id]=customFieldValueFromJson(r.value);});
  return map;
}
function customFieldDomIds(moduleKey){
  if(moduleKey==='observation')return {card:'obs-custom3fields-card',body:'obs-custom3fields-body'};
  return {card:'ims-custom3fields-card',body:'ims-custom3fields-body'};
}
async function customRenderRecordFields(moduleKey,recordTable,recordId){
  var ids=customFieldDomIds(moduleKey);
  var card=document.getElementById(ids.card);
  var body=document.getElementById(ids.body);
  if(!card||!body)return;
  try{
    var defs=await customLoadDefinitions(moduleKey,false);
    if(!defs.length){card.style.display='none';body.innerHTML='';return;}
    var values=recordId?await customLoadValues(recordTable,recordId):{};
    card.style.display='block';
    body.innerHTML='<div class="form3row">'+defs.map(function(f){return customFieldInputHtml(f,values[f.id]);}).join('')+'</div>';
  }catch(e){
    console.warn('custom fields unavailable:',e.message);
    card.style.display='none';
    body.innerHTML='';
  }
}
function customReadRecordFieldValue(field){
  var el=document.querySelector('[data-custom3field-id="'+field.id+'"]');
  if(!el)return null;
  if(field.field_type==='checkbox')return !!el.checked;
  var val=el.value;
  if(field.field_type==='number')return val===''?null:Number(val);
  return val===''?null:val;
}
async function customValidateRecordValues(moduleKey){
  var defs=customFieldDefsCache[moduleKey]||await customLoadDefinitions(moduleKey,false);
  if(!defs.length)return;
  for(var i=0;i<defs.length;i++){
    var f=defs[i];
    var value=customReadRecordFieldValue(f);
    if(f.required&&(value===null||value===''||value===false)){
      throw new Error('Please complete custom field: '+f.field_label);
    }
  }
}
async function customSaveRecordValues(moduleKey,recordTable,recordId,companyId){
  var defs=customFieldDefsCache[moduleKey]||await customLoadDefinitions(moduleKey,false);
  if(!defs.length||!recordId)return;
  await customValidateRecordValues(moduleKey);
  for(var i=0;i<defs.length;i++){
    var f=defs[i];
    var value=customReadRecordFieldValue(f);
    var existing=await api('/custom_field_values?record_table=eq.'+encodeURIComponent(recordTable)+'&record_id=eq.'+recordId+'&field_id=eq.'+f.id+'&limit=1');
    var body={company_id:companyId,record_table:recordTable,record_id:recordId,field_id:f.id,field_key:f.field_key,value:value,updated_at:new Date().toISOString()};
    if(existing&&existing[0])await api('/custom_field_values?id=eq.'+existing[0].id,{m:'PATCH',p:'return=minimal',b:body});
    else await api('/custom_field_values',{m:'POST',p:'return=minimal',b:body});
  }
}
async function customCollectRecordValues(moduleKey){
  var defs=customFieldDefsCache[moduleKey]||await customLoadDefinitions(moduleKey,false);
  return (defs||[]).map(function(f){return {field_id:f.id,field_key:f.field_key,value:customReadRecordFieldValue(f)};});
}
async function customSaveCollectedValues(recordTable,recordId,companyId,values){
  values=values||[];
  for(var i=0;i<values.length;i++){
    var v=values[i]; if(!v.field_id)continue;
    var existing=await api('/custom_field_values?record_table=eq.'+encodeURIComponent(recordTable)+'&record_id=eq.'+recordId+'&field_id=eq.'+v.field_id+'&limit=1');
    var body={company_id:companyId,record_table:recordTable,record_id:recordId,field_id:v.field_id,field_key:v.field_key,value:v.value,updated_at:new Date().toISOString()};
    if(existing&&existing[0])await api('/custom_field_values?id=eq.'+existing[0].id,{m:'PATCH',p:'return=minimal',b:body});
    else await api('/custom_field_values',{m:'POST',p:'return=minimal',b:body});
  }
}
function customFieldSettingsUnavailable(msg){
  return '<div style="padding:12px 14px;border:1px solid #FCD34D;background:#FFFBEB;border-radius:10px;color:#92400E;font-size:12px;line-height:1.45"><strong>Administrator setup needed:</strong> '+(isSA()?'run <code>auris360_production_schema_bundle_CLEAN.sql</code> in Supabase to enable no-code custom fields.':'no-code custom fields require administrator configuration. Please contact SEPHS admin.')+(isSA()&&msg?'<br>'+escH(msg):'')+'</div>';
}
async function loadCustomFieldSettings(){
  var card=document.getElementById('settings-custom3fields-card');
  var el=document.getElementById('custom3fields-settings-body');
  if(!card||!el)return;
  card.style.display=customFieldsCanManage()?'block':'none';
  if(!customFieldsCanManage())return;
  var moduleKey=document.getElementById('cf-module-select')?.value||'events';
  try{
    var rows=await customLoadDefinitions(moduleKey,true);
    customRenderFieldSettings(moduleKey,rows);
  }catch(e){
    el.innerHTML=customFieldSettingsUnavailable(e.message);
  }
}
function customRenderFieldSettings(moduleKey,rows){
  var el=document.getElementById('custom3fields-settings-body');
  if(!el)return;
  var moduleOptions=CUSTOM_FIELD_MODULES.map(function(m){
    return '<option value="'+escH(m.key)+'" '+(moduleKey===m.key?'selected':'')+' '+(m.future?'disabled':'')+'>'+escH(m.label)+(m.future?' - coming next':'')+'</option>';
  }).join('');
  var table='<div style="overflow:auto;border:1px solid var(--border);border-radius:10px;margin-top:12px"><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#F8FAFC"><th style="padding:9px;text-align:left">Field</th><th style="padding:9px;text-align:left">Type</th><th style="padding:9px;text-align:left">Required</th><th style="padding:9px;text-align:left">Status</th><th style="padding:9px;text-align:right">Actions</th></tr></thead><tbody>';
  if(!rows.length)table+='<tr><td colspan="5" style="padding:18px;text-align:center;color:var(--text2)">No custom fields yet for '+escH(customFieldModuleLabel(moduleKey))+'.</td></tr>';
  rows.forEach(function(f){
    table+='<tr style="border-top:1px solid var(--border)"><td style="padding:9px;font-weight:700">'+escH(f.field_label)+'<div style="font-size:10px;color:var(--text3);font-family:monospace">'+escH(f.field_key)+'</div></td><td style="padding:9px;text-transform:capitalize">'+escH(f.field_type)+'</td><td style="padding:9px">'+(f.required?'Yes':'No')+'</td><td style="padding:9px">'+(f.active?'<span style="color:var(--green);font-weight:700">Active</span>':'Inactive')+'</td><td style="padding:9px;text-align:right"><button class="btn btn-sm" data-auris-runtime-onclick="r0046" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([f.id]))+'"><i class="ti ti-edit"></i></button> <button class="btn btn-sm" style="color:var(--red);border-color:#fecaca" data-auris-runtime-onclick="r0047" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([f.id]))+'"><i class="ti ti-trash"></i></button></td></tr>';
  });
  table+='</tbody></table></div>';
  el.innerHTML='<div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:flex-end">'
    +'<div class="form3group" style="min-width:260px;margin:0"><label class="form3label">Module</label><select id="cf-module-select" data-auris-generated-onchange="g0074">'+moduleOptions+'</select></div>'
    +'<button class="btn btn-primary" data-auris-generated-onclick="g0075"><i class="ti ti-plus"></i>New field</button></div>'
    +table
    +'<div id="cf-form3panel" style="display:none;margin-top:14px;padding:14px;border:1px solid var(--border);border-radius:10px;background:#fff">'
    +'<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px"><div style="font-weight:900;color:var(--text)" id="cf-form3heading">New custom field</div><button class="btn btn-sm" data-auris-generated-onclick="g0076"><i class="ti ti-x"></i>Close</button></div>'
    +'<input type="hidden" id="cf-edit-id"/>'
    +'<div class="form3row">'
    +'<div class="form3group"><label class="form3label">Field label</label><input id="cf-label" placeholder="e.g. Contractor company, Shift, Machine number"/></div>'
    +'<div class="form3group"><label class="form3label">Field type</label><select id="cf-type" data-auris-generated-onchange="g0077"><option value="text">Text</option><option value="textarea">Long text</option><option value="number">Number</option><option value="date">Date</option><option value="select">Dropdown</option><option value="checkbox">Checkbox</option></select></div>'
    +'<div class="form3group"><label class="form3label">Order</label><input id="cf-order" type="number" value="0"/></div>'
    +'</div>'
    +'<div class="form3group"><label class="form3label">Dropdown options</label><input id="cf-options" placeholder="One option per line or separated by commas"/><div id="cf-options-help" style="font-size:10px;color:var(--text3);margin-top:3px">Used only when type is Dropdown.</div></div>'
    +'<div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-bottom:12px">'
    +'<label style="display:flex;gap:7px;align-items:center;font-size:12px;font-weight:700"><input type="checkbox" id="cf-required" style="width:16px;height:16px;margin:0;padding:0;accent-color:var(--green)"/> Required</label>'
    +'<label style="display:flex;gap:7px;align-items:center;font-size:12px;font-weight:700"><input type="checkbox" id="cf-active" checked style="width:16px;height:16px;margin:0;padding:0;accent-color:var(--green)"/> Active</label>'
    +'</div>'
    +'<button class="btn btn-primary" data-auris-generated-onclick="g0078"><i class="ti ti-device-floppy"></i>Save custom field</button>'
    +'</div>';
  customToggleOptionsHelp();
}
function customShowFieldForm(title){
  var panel=document.getElementById('cf-form3panel');
  if(panel)panel.style.display='block';
  var heading=document.getElementById('cf-form3heading');
  if(heading)heading.textContent=title||'New custom field';
  panel?.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function customHideFieldForm(){
  var panel=document.getElementById('cf-form3panel');
  if(panel)panel.style.display='none';
}
function customNewField(){
  customClearFieldForm();
  customShowFieldForm('New custom field');
  setTimeout(function(){document.getElementById('cf-label')?.focus();},50);
}
function customClearFieldForm(){
  ['cf-edit-id','cf-label','cf-options'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var t=document.getElementById('cf-type');if(t)t.value='text';
  var o=document.getElementById('cf-order');if(o)o.value='0';
  var r=document.getElementById('cf-required');if(r)r.checked=false;
  var a=document.getElementById('cf-active');if(a)a.checked=true;
  customToggleOptionsHelp();
}
function customToggleOptionsHelp(){
  var wrap=document.getElementById('cf-options')?.closest('.form3group');
  if(wrap)wrap.style.display=document.getElementById('cf-type')?.value==='select'?'block':'none';
}
function customEditField(id){
  var moduleKey=document.getElementById('cf-module-select')?.value||'events';
  var f=(customFieldDefsCache[moduleKey]||[]).find(function(x){return x.id===id;});
  if(!f)return;
  document.getElementById('cf-edit-id').value=f.id;
  document.getElementById('cf-label').value=f.field_label||'';
  document.getElementById('cf-type').value=f.field_type||'text';
  document.getElementById('cf-order').value=f.sort_order||0;
  document.getElementById('cf-required').checked=!!f.required;
  document.getElementById('cf-active').checked=f.active!==false;
  document.getElementById('cf-options').value=customFieldOptions(f).join('\n');
  customToggleOptionsHelp();
  customShowFieldForm('Edit custom field');
}
async function customSaveField(){
  if(!customFieldsCanManage()){toast('Only admins or HSE managers can manage custom fields',false);return;}
  var companyId=customFieldsCompanyId();
  if(!companyId){toast('No company selected',false);return;}
  var moduleKey=document.getElementById('cf-module-select')?.value||'events';
  var id=document.getElementById('cf-edit-id')?.value||'';
  var label=(document.getElementById('cf-label')?.value||'').trim();
  if(!label){toast('Please enter a field label',false);return;}
  var type=document.getElementById('cf-type')?.value||'text';
  var options=(document.getElementById('cf-options')?.value||'').split(/\n|,/).map(function(x){return x.trim();}).filter(Boolean);
  var body={company_id:companyId,module_key:moduleKey,field_label:label,field_type:type,options:options,required:document.getElementById('cf-required')?.checked||false,active:document.getElementById('cf-active')?.checked!==false,sort_order:parseInt(document.getElementById('cf-order')?.value)||0,updated_at:new Date().toISOString()};
  if(!id){body.field_key=customFieldMakeKey(label);body.created_by=prof?.id||null;}
  try{
    if(id)await api('/custom_fields?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:body});
    else await api('/custom_fields',{m:'POST',p:'return=minimal',b:body});
    toast('Custom field saved');
    loadCustomFieldSettings();
  }catch(e){
    var msg=e.message||'Save failed';
    if(msg.includes('schema cache')||msg.includes('custom_fields'))msg=isSA()?('Custom fields setup required. Technical detail: '+msg):'Custom fields require administrator configuration before shared use. Please contact SEPHS admin.';
    toast(msg,false);
  }
}
async function customDeleteField(id){
  if(!customFieldsCanManage()){toast('Access denied',false);return;}
  try{
    var rows=await api('/custom_fields?id=eq.'+id+'&select=active,field_label');
    var current=rows?.[0]||{};
    if(current.active!==false){
      var ok=await appConfirmAction({title:'Deactivate custom field',message:'Deactivate this custom field instead of deleting it?',detail:'Existing values are retained and the field can be reactivated later if needed.',confirmText:'Deactivate field',cancelText:'Back',variant:'danger'});
      if(!ok)return;
      await api('/custom_fields?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{active:false,updated_at:new Date().toISOString()}});
      toast('Custom field deactivated');
      loadCustomFieldSettings();
      return;
    }
    if(!(await appConfirmDelete('inactive custom field','Permanent deletion should be used only for duplicate/test fields. Existing values may also be removed by database rules.')))return;
    await api('/custom_fields?id=eq.'+id,{m:'DELETE'});
    toast('Inactive custom field permanently deleted');
    loadCustomFieldSettings();
  }
  catch(e){toastActionError('Delete custom field','Settings',e);}
}
