function ptwApproverPayload(level,id){
var p=(people||[]).find(function(x){return x.id===id;})||{};
var o={};
var email=id?(usersContactEmail(p)||''):'';
o['level'+level+'_id']=id||'';
o['level'+level+'_name']=id?([p.first_name,p.last_name].filter(Boolean).join(' ')||p.email||''):'';
o['level'+level+'_email']=email;
o['level'+level+'_phone']=id?(p.whatsapp_phone||p.mobile_phone||p.phone||''):'';
return o;
}

async function savePTWApprovalSettings(){
try{
var l1=document.getElementById('ptw-app-l1')?.value||'';
var l2=document.getElementById('ptw-app-l2')?.value||'';
var l3=document.getElementById('ptw-app-l3')?.value||'';
var selected=[l1,l2,l3].filter(Boolean);
var contactWarnings=[];
for(var i=0;i<selected.length;i++){
var p=(people||[]).find(function(x){return x.id===selected[i];});
var email=usersContactEmail(p);
if(p&&notificationRecipientIssue(email))contactWarnings.push(peopleName(p));
}
var companyId=ccid();
if(!companyId){toast('No company selected',false);return;}
var existing=await api('/notification_settings?company_id=eq.'+companyId+'&limit=1');
var row=existing&&existing[0]?existing[0]:null;
var rules=row?.event_recipients||{};
if(typeof rules==='string'){try{rules=JSON.parse(rules);}catch(_){rules={};}}
var approvers={};
Object.assign(approvers,ptwApproverPayload(1,l1),ptwApproverPayload(2,l2),ptwApproverPayload(3,l3));
rules.permit_approvers=approvers;
var updates={event_recipients:rules,updated_at:new Date().toISOString()};
if(row)await api('/notification_settings?company_id=eq.'+companyId,{m:'PATCH',p:'return=minimal',b:updates});
else{updates.company_id=companyId;await api('/notification_settings',{m:'POST',p:'return=minimal',b:updates});}
toast(contactWarnings.length?'PTW approvers saved. Add real notification contact for: '+contactWarnings.join(', '):'PTW approver settings saved');
}catch(e){toast(actionErrorMessage('Save PTW approvers','Permit to Work settings',e.message),false);}
}

async function ptwGetApprovalSettings(){
try{
var companyId=ccid();
var workflows=await api('/approval_workflows?company_id=eq.'+companyId+'&module_name=eq.permit&is_active=eq.true&order=created_at.desc&limit=1');
if(workflows&&workflows[0]){
var steps=await api('/approval_workflow_steps?workflow_id=eq.'+workflows[0].id+'&order=step_no.asc')||[];
var out={};
steps.forEach(function(s){
var n=parseInt(s.step_no)||1;
out['level'+n+'_id']=s.approver_person_id||'';
out['level'+n+'_name']=s.approver_name||s.approver_role||'';
out['level'+n+'_email']=s.approver_email||'';
out['level'+n+'_phone']='';
});
return out;
}
var rows=await api('/notification_settings?company_id=eq.'+ccid()+'&limit=1');
var rules=(rows&&rows[0]?rows[0].event_recipients:null)||{};
if(typeof rules==='string'){try{rules=JSON.parse(rules);}catch(_){rules={};}}
return rules.permit_approvers||{};
}catch(e){return{};}
}

function ptwApproverForLevel(settings,level){
settings=settings||{};
return {
id:settings['level'+level+'_id']||'',
name:settings['level'+level+'_name']||'',
email:settings['level'+level+'_email']||'',
phone:settings['level'+level+'_phone']||''
};
}

