async function loadWorkSchedule(){
  var addBtn=document.getElementById('ws-add-btn');
  if(addBtn)addBtn.style.display=isMgr()?'inline-flex':'none';
  wsWeekOffset=0;
  wsSetView('list');
}

function wsSetView(type){
  var listBtn=document.getElementById('ws-btn-list');
  var weekBtn=document.getElementById('ws-btn-week');
  if(listBtn)listBtn.style.background=type==='list'?'var(--green)':'';
  if(listBtn)listBtn.style.color=type==='list'?'#fff':'';
  if(weekBtn)weekBtn.style.background=type==='week'?'var(--green)':'';
  if(weekBtn)weekBtn.style.color=type==='week'?'#fff':'';
  ['ws-list-view','ws-week-view','ws-detail-view','ws-form3view','ws-tbt-form'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.style.display='none';
  });
  if(type==='list'){
    document.getElementById('ws-list-view').style.display='block';
    wsLoadList();
  }else{
    document.getElementById('ws-week-view').style.display='block';
    wsRenderWeek();
  }
}

function wsShowList(){wsSetView('list');}

async function wsLoadList(){
  var el=document.getElementById('ws-list');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/work_schedule?select=*'+cf()+'&order=planned_start,created_at.desc');
    wsAllData=d||[];
    var today=new Date();
    var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
    setM('ws-m3planned',wsAllData.filter(x=>x.status==='planned'||x.status==='approved').length);
    setM('ws-m3progress',wsAllData.filter(x=>x.status==='in_progress').length);
    setM('ws-m3done',wsAllData.filter(x=>x.status==='completed').length);
    setM('ws-m3overdue',wsAllData.filter(x=>['planned','approved','in_progress'].includes(x.status)&&x.planned_end&&new Date(x.planned_end)<today).length);
    setM('ws-m3hold',wsAllData.filter(x=>x.status==='on_hold').length);
    wsFilter();
  }catch(e){if(el)el.innerHTML=registerErrorHtml('Work Schedule register',e.message);console.error(e);}
}

function wsFilter(){
  var el=document.getElementById('ws-list');if(!el)return;
  var search=(document.getElementById('ws-search')?.value||'').toLowerCase();
  var status=document.getElementById('ws-filter-status')?.value||'';
  var priority=document.getElementById('ws-filter-priority')?.value||'';
  var filtered=wsAllData.filter(function(x){
    var mS=!search||(x.title||'').toLowerCase().includes(search)||(x.ref_number||'').toLowerCase().includes(search)||(x.location||'').toLowerCase().includes(search);
    var mSt=!status||x.status===status;
    var mP=!priority||x.priority===priority;
    return mS&&mSt&&mP;
  });
  if(!filtered.length){
    el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">'
      +'<div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div>'
      +'<div style="font-weight:600;margin-bottom:8px">No work orders found</div>'
      +(isMgr()&&!search&&!status&&!priority?'<button class="btn btn-primary" data-auris-generated-onclick="g0084"><i class="ti ti-plus"></i>Create first work order</button>':'')
      +'</div>';
    return;
  }
  var today=new Date();
  var html='<div style="overflow:auto;border:1px solid var(--border);border-radius:10px;background:#fff">'
    +'<table style="width:100%;min-width:1120px;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="background:#0F6E56;color:#fff">'
    +'<th style="padding:10px;color:#fff;text-align:left">Ref</th>'
    +'<th style="padding:10px;color:#fff;text-align:left">Work order</th>'
    +'<th style="padding:10px;color:#fff;text-align:left">Location</th>'
    +'<th style="padding:10px;color:#fff;text-align:left">Supervisor</th>'
    +'<th style="padding:10px;color:#fff;text-align:left">Planned dates</th>'
    +'<th style="padding:10px;color:#fff;text-align:center">Priority</th>'
    +'<th style="padding:10px;color:#fff;text-align:center">Risk</th>'
    +'<th style="padding:10px;color:#fff;text-align:center">Status</th>'
    +'<th style="padding:10px;color:#fff;width:70px"></th>'
    +'</tr></thead><tbody>';
  filtered.forEach(function(x){
    var sc=WS_STATUS_CFG[x.status]||WS_STATUS_CFG.planned;
    var pc=WS_PRIORITY_CFG[x.priority]||WS_PRIORITY_CFG.medium;
    var rc=WS_RISK_CFG[x.risk_level]||WS_RISK_CFG.medium;
    var isOverdue=['planned','approved','in_progress'].includes(x.status)&&x.planned_end&&new Date(x.planned_end)<today;
    var typeIcon=WS_TYPE_ICONS[x.work_type]||'ti-package';
    var startStr=x.planned_start?new Date(x.planned_start).toLocaleDateString('en-GB'):'-';
    var endStr=x.planned_end?new Date(x.planned_end).toLocaleDateString('en-GB'):'-';
    html+='<tr style="border-bottom:1px solid var(--border);border-left:5px solid '+(isOverdue?'var(--red)':pc[1])+';cursor:pointer" data-id="'+x.id+'" data-auris-generated-onclick="g0085">'
      +'<td style="padding:10px;font-family:monospace;font-weight:800;color:var(--green)">'+escH(x.ref_number||'DRAFT')+(isOverdue?'<div style="font-size:10px;color:#A32D2D;font-weight:800">OVERDUE</div>':'')+'</td>'
      +'<td style="padding:10px;min-width:260px"><div style="display:flex;align-items:center;gap:8px"><i class="ti '+typeIcon+'" style="color:'+pc[1]+'"></i><div><div style="font-weight:800">'+escH(x.title||'Untitled')+'</div><div style="font-size:11px;color:var(--text2);margin-top:2px">'+escH(WS_TYPE_LABELS[x.work_type]||x.work_type||'Work')+(x.estimated_duration?' - '+escH(x.estimated_duration):'')+'</div></div></div></td>'
      +'<td style="padding:10px">'+escH(x.location||'-')+'</td>'
      +'<td style="padding:10px">'+escH(x.supervisor_name||'-')+'</td>'
      +'<td style="padding:10px;white-space:nowrap">'+startStr+(x.planned_end?' to '+endStr:'')+'</td>'
      +'<td style="padding:10px;text-align:center">'+wsBadge(x.priority,WS_PRIORITY_CFG)+'</td>'
      +'<td style="padding:10px;text-align:center">'+wsBadge(x.risk_level,WS_RISK_CFG)+'</td>'
      +'<td style="padding:10px;text-align:center">'+wsBadge(x.status,WS_STATUS_CFG)+'</td>'
      +'<td style="padding:10px;text-align:center"><button class="btn btn-sm" data-auris-runtime-onclick="r0051" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id]))+'"><i class="ti ti-eye"></i></button></td>'
      +'</tr>';
  });
  html+='</tbody></table></div>';
  el.innerHTML=html;
}

// -- WEEK VIEW ----------------------------------------------------------------
function wsPrevWeek(){wsWeekOffset--;wsRenderWeek();}
function wsNextWeek(){wsWeekOffset++;wsRenderWeek();}
function wsThisWeek(){wsWeekOffset=0;wsRenderWeek();}

function wsRenderWeek(){
  var el=document.getElementById('ws-week-grid');
  if(!el)return;
  var today=new Date();
  var mon=new Date(today);
  var day=today.getDay();
  mon.setDate(today.getDate()-(day===0?6:day-1)+(wsWeekOffset*7));
  var days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
  var labelEl=document.getElementById('ws-week-label');
  var endDay=new Date(mon);endDay.setDate(mon.getDate()+6);
  if(labelEl)labelEl.textContent='Week of '+mon.toLocaleDateString('en-GB')+' - '+endDay.toLocaleDateString('en-GB');
  var html='<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:8px">';
  for(var i=0;i<7;i++){
    var d=new Date(mon);d.setDate(mon.getDate()+i);
    var isToday=d.toDateString()===today.toDateString();
    var dayStr=d.toISOString().slice(0,10);
    var dayOrders=wsAllData.filter(function(x){
      if(!x.planned_start)return false;
      var s=new Date(x.planned_start);var e=x.planned_end?new Date(x.planned_end):s;
      return d>=s&&d<=e;
    });
    html+='<div class="card" style="padding:0;overflow:hidden;min-height:120px;border:2px solid '+(isToday?'var(--green)':'var(--border)')+'">'
      +'<div style="padding:6px 10px;background:'+(isToday?'var(--green)':'#f9fafb')+';color:'+(isToday?'#fff':'var(--text2)')+';font-size:11px;font-weight:700;border-bottom:1px solid var(--border)">'
      +days[i]+' '+d.getDate()+'</div>'
      +'<div style="padding:6px 8px">';
    dayOrders.forEach(function(x){
      var pc=WS_PRIORITY_CFG[x.priority]||WS_PRIORITY_CFG.medium;
      html+='<div style="background:'+pc[0]+';color:'+pc[1]+';border-radius:6px;padding:4px 8px;font-size:11px;font-weight:600;margin-bottom:4px;cursor:pointer;overflow:hidden;white-space:nowrap;text-overflow:ellipsis" '
        +'data-id="'+x.id+'" data-auris-generated-onclick="g0085" title="'+escH(x.title)+'">'
        +escH(x.title)+'</div>';
    });
    html+='</div></div>';
  }
  html+='</div>';
  el.innerHTML=html;
}

// -- DETAIL VIEW --------------------------------------------------------------
async function wsShowDetail(id){
  var x=wsAllData.find(function(r){return r.id===id;});
  if(!x){try{var d=await api('/work_schedule?id=eq.'+id);x=d?.[0];}catch(e){return;}}
  if(!x)return;
  wsCurrentId=id;
  ['ws-list-view','ws-week-view','ws-form3view','ws-tbt-form','ws-te-form','ws-te-checklist-view'].forEach(function(i){
    var el=document.getElementById(i);if(el)el.style.display='none';
  });
  document.getElementById('ws-detail-view').style.display='block';

  // Banner
  var pc=WS_PRIORITY_CFG[x.priority]||WS_PRIORITY_CFG.medium;
  document.getElementById('ws-detail-ref').textContent=x.ref_number||'DRAFT';
  document.getElementById('ws-detail-title').textContent=x.title||'Untitled';
  document.getElementById('ws-detail-type').textContent=(WS_TYPE_LABELS[x.work_type]||x.work_type||'');
  document.getElementById('ws-detail-location').textContent=x.location?''+x.location:'';
  var startStr=x.planned_start?new Date(x.planned_start).toLocaleDateString('en-GB'):'';
  var endStr=x.planned_end?new Date(x.planned_end).toLocaleDateString('en-GB'):'';
  document.getElementById('ws-detail-dates').textContent=startStr?(startStr+(endStr?' to '+endStr:'')):'';

  // Badges
  document.getElementById('ws-detail-status-badge').innerHTML=wsBadge(x.status,WS_STATUS_CFG);
  document.getElementById('ws-detail-priority-badge').innerHTML=wsBadge(x.priority,WS_PRIORITY_CFG);
  document.getElementById('ws-detail-risk-badge').innerHTML=wsBadge(x.risk_level,WS_RISK_CFG);

  // Details grid
  document.getElementById('ws-detail-desc').textContent=x.description||'-';
  document.getElementById('ws-detail-supervisor').textContent=x.supervisor_name||'-';
  document.getElementById('ws-detail-team').textContent=x.team_members||'-';
  document.getElementById('ws-detail-duration').textContent=x.estimated_duration||'-';
  var raDetail=document.getElementById('ws-detail-ra');
  if(raDetail)raDetail.innerHTML=wsLinkedRefButton('ra',x.ra_ref,x.ra_ref||'-');
  var ptwDetail=document.getElementById('ws-detail-ptw');
  if(ptwDetail)ptwDetail.innerHTML=wsLinkedRefButton('ptw',x.permit_ref,x.permit_ref||'-');
  document.getElementById('ws-detail-notes').textContent=x.notes||'-';

  // Quick status
  var qs=document.getElementById('ws-quick-status');if(qs)qs.value=x.status||'planned';

  // Linked records
  wsRenderLinkedRecords(x);

  // Action card statuses
  wsRenderActionStatuses(x);
}


function wsRenderActionStatuses(x){
  var tbt=document.getElementById('ws-tbt-status');
  var ps=document.getElementById('ws-ps-status');
  var si=document.getElementById('ws-si-status');
  var te=document.getElementById('ws-te-status');
  if(tbt)tbt.innerHTML=x.toolbox_talk_id?'<span style="color:var(--green);font-weight:700">Completed</span>':'<span style="color:var(--text2)">Pending</span>';
  if(ps)ps.innerHTML=x.prestart_id?'<span style="color:var(--green);font-weight:700">Completed</span>':'<span style="color:var(--text2)">Pending</span>';
  if(si)si.innerHTML=x.site_inspection_id?'<span style="color:var(--green);font-weight:700">Completed</span>':'<span style="color:var(--text2)">Pending</span>';
  if(te)te.innerHTML='<span style="color:var(--text2)">Check equipment</span>';
  // RA + PTW status (was previously a separate monkey-patch wrapper)
  var ra=document.getElementById('ws-ra-status');
  var ptw=document.getElementById('ws-ptw-status');
  if(ra)ra.innerHTML=x.ra_ref?'<span style="color:var(--green);font-weight:700">Ref: '+wsLinkedRefButton('ra',x.ra_ref,x.ra_ref)+'</span>':'<span style="color:var(--text2)">No RA linked</span>';
  if(ptw)ptw.innerHTML=(x.permit_ref&&x.requires_permit)?'<span style="color:var(--green);font-weight:700">Ref: '+wsLinkedRefButton('ptw',x.permit_ref,x.permit_ref)+'</span>':x.requires_permit?'<span style="color:var(--amber);font-weight:600">Required - not issued</span>':'<span style="color:var(--text2)">Not required</span>';
}

async function wsUpdateStatus(val){
  if(!wsCurrentId)return;
  try{
    await api('/work_schedule?id=eq.'+wsCurrentId,{m:'PATCH',p:'return=minimal',b:{status:val,updated_at:new Date().toISOString()}});
    var x=wsAllData.find(function(r){return r.id===wsCurrentId;});
    if(x)x.status=val;
    var badge=document.getElementById('ws-detail-status-badge');
    if(badge)badge.innerHTML=wsBadge(val,WS_STATUS_CFG);
    toast('Status updated!');
  }catch(e){toastActionError('Update work status','Work Schedule',e);}
}

function wsEditCurrent(){
  var x=wsAllData.find(function(r){return r.id===wsCurrentId;});
  if(x)wsEdit(wsCurrentId);
}

// -- OPEN ACTION FORMS (pre-filled) --------------------------------------------
function wsGetCurrent(){return wsAllData.find(function(r){return r.id===wsCurrentId;})||{};}

function wsOpenToolboxTalk(){
  var x=wsGetCurrent();
  document.getElementById('ws-detail-view').style.display='none';
  document.getElementById('ws-tbt-form').style.display='block';

  // Pre-fill
  document.getElementById('tbt-wo-title').textContent=x.title||'Work Order';
  document.getElementById('tbt-title').value='Toolbox Talk - '+(x.title||'Work Activity');
  document.getElementById('tbt-date').value=new Date().toISOString().slice(0,10);
  document.getElementById('tbt-activity').value=x.title||'';
  document.getElementById('tbt-location').value=x.location||'';
  document.getElementById('tbt-sign-dt').value=new Date().toISOString().slice(0,16);

  // Populate conducted-by dropdown
  var byEl=document.getElementById('tbt-by');
  if(byEl){
    byEl.innerHTML='<option value="">Select...</option>';
    (people||[]).forEach(function(p){
      var o=document.createElement('option');
      o.value=p.id;o.textContent=p.last_name+', '+p.first_name;
      if(x.supervisor_id&&p.id===x.supervisor_id)o.selected=true;
      byEl.appendChild(o);
    });
  }

  // Pre-fill sign name with supervisor
  document.getElementById('tbt-sign-name').value=x.supervisor_name||'';

  // Pre-fill team as attendees
  wsTbtAttendees=[];
  if(x.team_members){
    x.team_members.split(/[,\n]/).forEach(function(name){
      var n=name.trim();if(n)wsTbtAttendees.push({name:n,signed:false});
    });
  }
  tbtRenderAttendees();
}

function wsOpenPreStart(){
  var x=wsGetCurrent();
  // Switch to inspection module, pre-start tab, new form
  showPage('inspection', document.querySelector('[onclick*="inspection"]'));
  setTimeout(function(){
    // Switch to pre-start tab
    var btn=document.getElementById('insp-tab-prestart');
    if(btn)inspSwitchTab('prestart',btn);
    setTimeout(function(){
      psNew();
      // Pre-fill
      setTimeout(function(){
        var act=document.getElementById('ps-activity');if(act)act.value=x.title||'';
        var loc=document.getElementById('ps-location');if(loc)loc.value=x.location||'';
        if(x.ra_ref)fillRiskAssessmentSelect('ps-ra-ref',x.ra_ref);
        var ptw=document.getElementById('ps-ptw-ref');if(ptw)ptw.value=x.permit_ref||'';
        var tm=document.getElementById('ps-team');if(tm)tm.value=x.team_members||'';
        if(x.supervisor_id)fillPersonSelect('ps-supervisor',pname(x.supervisor_id));
      },100);
    },150);
  },200);
}

function wsOpenSiteInspection(){
  var x=wsGetCurrent();
  showPage('inspection', document.querySelector('[onclick*="inspection"]'));
  setTimeout(function(){
    // Stay on site inspection tab, open new form
    var btn=document.getElementById('insp-tab-site');
    if(btn)inspSwitchTab('site',btn);
    setTimeout(function(){
      inspNew();
      setTimeout(function(){
        var site=document.getElementById('if-site');if(site)site.value=x.location||'';
        var dt=document.getElementById('if-date');if(dt)dt.value=x.planned_start||new Date().toISOString().slice(0,10);
        var sup=document.getElementById('if-by');if(sup&&x.supervisor_id)fillPersonSelect('if-by',pname(x.supervisor_id));
      },100);
    },150);
  },200);
}


function wsBackToDetail(){
  document.getElementById('ws-tbt-form').style.display='none';
  document.getElementById('ws-detail-view').style.display='block';
}

// -- TOOLBOX TALK FORM --------------------------------------------------------

function tbtRenderAttendees(){
  var el=document.getElementById('tbt-attendees-list');if(!el)return;
  if(!wsTbtAttendees.length){
    el.innerHTML='<div style="color:var(--text2);font-size:12px;padding:8px 0">No attendees added yet</div>';
    return;
  }
  el.innerHTML=wsTbtAttendees.map(function(a,i){
    return '<div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid #f5f5f5">'
      +'<div style="width:28px;height:28px;border-radius:50%;background:var(--green);color:#fff;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;flex-shrink:0">'+a.name.charAt(0).toUpperCase()+'</div>'
      +'<span style="flex:1;font-size:13px;font-weight:500">'+escH(a.name)+'</span>'
      +'<label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--green);cursor:pointer">'
      +'<input type="checkbox" '+(a.signed?'checked':'')+' style="accent-color:var(--green)" data-auris-runtime-onchange="r0052" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([i]))+'"> Signed</label>'
      +'<button class="btn btn-sm" style="color:var(--red);padding:2px 6px" data-auris-runtime-onclick="r0053" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([i]))+'"><i class="ti ti-x" style="font-size:11px"></i></button>'
      +'</div>';
  }).join('');
}


// -- ADD / EDIT WORK ORDER ----------------------------------------------------
async function wsLoadReferenceOptions(selectedRA,selectedPTW){
  var raSel=document.getElementById('wsf-ra-ref');
  var ptwSel=document.getElementById('wsf-ptw-ref');
  if(raSel){
    await fillRiskAssessmentSelect('wsf-ra-ref',selectedRA);
  }
  if(ptwSel){
    ptwSel.innerHTML='<option value="">Select permit...</option>';
    try{
      var permits=await api('/permits?select=id,permit_number,permit_type,permit_type_v2,status'+cf()+'&order=created_at.desc');
      (permits||[]).forEach(function(p){
        var ref=p.permit_number||p.id;
        var pType=p.permit_type_v2||p.permit_type;
        var label=(PTW_TYPE_CFG[pType]?.label||pType||'Permit');
        var o=document.createElement('option');
        o.value=ref;verifiedReferenceOption(o,p,ref,'permits');o.textContent=ref+' - '+label+(p.status?' ['+p.status+']':'');
        ptwSel.appendChild(o);
      });
    }catch(e){
      var po=document.createElement('option');po.value='';po.textContent='Unable to load permits';ptwSel.appendChild(po);
    }
    if(selectedPTW){ptwSel.value=selectedPTW;if(ptwSel.value!==selectedPTW){var savedPTW=document.createElement('option');savedPTW.value=selectedPTW;savedPTW.textContent=selectedPTW+' (saved text)';ptwSel.appendChild(savedPTW);ptwSel.value=selectedPTW;}}
  }
}

async function wsNew(){
  wsEditingId=null;
  document.getElementById('ws-form3title').textContent='New Work Order';
  document.getElementById('ws-form3ref').textContent='';
  document.getElementById('ws-del-btn').style.display='none';
  document.getElementById('wsf-ref-display').textContent='WO-AUTO';
  ['wsf-title','wsf-desc','wsf-location','wsf-dept','wsf-duration','wsf-team','wsf-notes','wsf-ra-ref','wsf-ptw-ref'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  await wsLoadReferenceOptions();
  ['wsf-start','wsf-end'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var t=document.getElementById('wsf-type');if(t)t.value='maintenance';
  var s=document.getElementById('wsf-status');if(s)s.value='planned';
  var r=document.getElementById('wsf-risk');if(r)r.value='medium';
  var p=document.getElementById('wsf-priority');if(p)p.value='medium';
  var ra=document.getElementById('wsf-requires-ra');if(ra)ra.checked=true;
  var pt=document.getElementById('wsf-requires-permit');if(pt)pt.checked=false;
  var sup=document.getElementById('wsf-supervisor');
  if(sup){sup.innerHTML='<option value="">Select supervisor...</option>';(people||[]).forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.last_name+', '+p.first_name+(p.job_title?' - '+p.job_title:'');sup.appendChild(o);});}
  ['ws-list-view','ws-week-view','ws-detail-view','ws-tbt-form'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});
  document.getElementById('ws-form3view').style.display='block';
}

async function wsEdit(id){
  var x=wsAllData.find(function(r){return r.id===id;});
  if(!x)return;
  wsEditingId=id;
  document.getElementById('ws-form3title').textContent='Edit Work Order';
  document.getElementById('ws-form3ref').textContent=x.ref_number||'';
  document.getElementById('ws-del-btn').style.display=isMgr()?'inline-flex':'none';
  document.getElementById('wsf-ref-display').textContent=x.ref_number||'WO-AUTO';
  await wsLoadReferenceOptions(x.ra_ref,x.permit_ref);
  var flds={'wsf-title':'title','wsf-desc':'description','wsf-location':'location','wsf-dept':'department','wsf-duration':'estimated_duration','wsf-team':'team_members','wsf-notes':'notes','wsf-ra-ref':'ra_ref','wsf-ptw-ref':'permit_ref'};
  Object.entries(flds).forEach(function(e){var el=document.getElementById(e[0]);if(el)el.value=x[e[1]]||'';});
  var st=document.getElementById('wsf-start');if(st)st.value=x.planned_start||'';
  var en=document.getElementById('wsf-end');if(en)en.value=x.planned_end||'';
  var t=document.getElementById('wsf-type');if(t)t.value=x.work_type||'maintenance';
  var s=document.getElementById('wsf-status');if(s)s.value=x.status||'planned';
  var r=document.getElementById('wsf-risk');if(r)r.value=x.risk_level||'medium';
  var p=document.getElementById('wsf-priority');if(p)p.value=x.priority||'medium';
  var ra=document.getElementById('wsf-requires-ra');if(ra)ra.checked=x.requires_ra!==false;
  var pt=document.getElementById('wsf-requires-permit');if(pt)pt.checked=!!x.requires_permit;
  var sup=document.getElementById('wsf-supervisor');
  if(sup){sup.innerHTML='<option value="">Select...</option>';(people||[]).forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.last_name+', '+p.first_name+(p.job_title?' - '+p.job_title:'');sup.appendChild(o);});sup.value=x.supervisor_id||'';}
  ['ws-list-view','ws-week-view','ws-detail-view','ws-tbt-form'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});
  document.getElementById('ws-form3view').style.display='block';
}

function wsFormBack(){
  document.getElementById('ws-form3view').style.display='none';
  if(wsCurrentId){
    document.getElementById('ws-detail-view').style.display='block';
  }else{
    wsSetView('list');
  }
}

async function wsSave(){
  var title=document.getElementById('wsf-title')?.value?.trim();
  if(!title){toast('Please enter a work order title',false);return;}
  var supId=document.getElementById('wsf-supervisor')?.value||null;
  var supName='';
  if(supId){var p=(people||[]).find(function(x){return x.id===supId;});supName=p?(p.last_name+', '+p.first_name):'';}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var body={
    company_id:ccid(),title:title,
    description:g('wsf-desc'),location:g('wsf-location'),department:g('wsf-dept'),
    work_type:g('wsf-type')||'maintenance',status:g('wsf-status')||'planned',
    priority:g('wsf-priority')||'medium',risk_level:g('wsf-risk')||'medium',
    planned_start:g('wsf-start'),planned_end:g('wsf-end'),
    estimated_duration:g('wsf-duration'),
    supervisor_id:supId||null,supervisor_name:supName||null,
    team_members:g('wsf-team'),
    requires_ra:document.getElementById('wsf-requires-ra')?.checked||false,
    requires_permit:document.getElementById('wsf-requires-permit')?.checked||false,
    ra_ref:g('wsf-ra-ref'),permit_ref:g('wsf-ptw-ref'),
    notes:g('wsf-notes'),updated_at:new Date().toISOString()
  };
  var wsRa=verifiedReferenceSelection('wsf-ra-ref'),wsPermit=verifiedReferenceSelection('wsf-ptw-ref');
  body.risk_assessment_id=wsRa.id;body.permit_id=wsPermit.id;
  try{
    if(wsEditingId){
      await apiWriteWithMissingColumnFallback('/work_schedule?id=eq.'+wsEditingId,{m:'PATCH',p:'return=minimal',b:body},'Work order');
      var idx=wsAllData.findIndex(function(x){return x.id===wsEditingId;});
      if(idx>=0)Object.assign(wsAllData[idx],body);
      toast('Work order updated!');
      wsCurrentId=wsEditingId;
      wsShowDetail(wsEditingId);
    }else{
      body.created_by=prof?.id;
      var res=await apiWriteWithMissingColumnFallback('/work_schedule',{m:'POST',p:'return=representation',b:body},'Work order');
      if(res?.[0]){
        // Generate ref number
        var yr=new Date().getFullYear();
        var ref=await nextCompanyRef('work_schedule','ref_number','WO-'+yr+'-');
        try{await api('/work_schedule?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{ref_number:ref}});res[0].ref_number=ref;}catch(ex){}
        res[0].ref_number=res[0].ref_number||ref;
        wsAllData.unshift(res[0]);
        wsCurrentId=res[0].id;
        toast('Work order created! Ref: '+res[0].ref_number);
        wsShowDetail(res[0].id);
      }
    }
  }catch(e){toastActionError('Save work order','Work Schedule',e);console.error(e);}
}

async function wsDelete(){
  if(!wsEditingId)return;
  try{
    var current=wsAllData.find(function(x){return x.id===wsEditingId;})||{};
    if(String(current.status||'planned')!=='cancelled'){
      if(!(await appConfirmAction({
        title:'Cancel work order',
        message:'Cancel this work order instead of deleting it?',
        detail:'The work order will stay in the schedule history so linked RA, PTW, toolbox talk, inspections and equipment checks remain traceable.',
        confirmText:'Cancel work order',
        cancelText:'Back',
        variant:'danger'
      })))return;
      await api('/work_schedule?id=eq.'+wsEditingId,{m:'PATCH',p:'return=minimal',b:{status:'cancelled',updated_at:new Date().toISOString()}});
      var idx=wsAllData.findIndex(function(x){return x.id===wsEditingId;});
      if(idx>=0)wsAllData[idx].status='cancelled';
      toast('Work order cancelled and kept for audit history');
      wsCurrentId=null;wsSetView('list');
      return;
    }
    if(!(await appConfirmDelete('cancelled work order','Permanent deletion should be used only for duplicate/test work orders. Linked records may still refer to this work order.')))return;
    await api('/work_schedule?id=eq.'+wsEditingId,{m:'DELETE',p:'return=representation'});
    wsAllData=wsAllData.filter(function(x){return x.id!==wsEditingId;});
    toast('Cancelled work order permanently deleted');wsCurrentId=null;wsSetView('list');
  }catch(e){toastActionError('Delete work order','Work Schedule',e);}
}

