async function wsTELoadItems(){
  // Check if work order has saved equipment list in notes or dedicated field
  // For now render from wsTEItems (session only) + show option to save
  wsTERenderItems();
}

function wsTESearchEquipment(){
  var q=(document.getElementById('ws-te-search')?.value||'').toLowerCase().trim();
  var el=document.getElementById('ws-te-search-results');
  if(!el)return;
  if(q.length<2){el.innerHTML='';return;}
  // Search from toolsAllData (already loaded if tools module was visited)
  var results=(toolsAllData||[]).filter(function(t){
    return (t.name||'').toLowerCase().includes(q)||(t.ref_number||'').toLowerCase().includes(q)||(t.serial_number||'').toLowerCase().includes(q);
  }).slice(0,8);
  if(!results.length){
    el.innerHTML='<div style="padding:8px 12px;font-size:12px;color:var(--text2)">No equipment found in register. <button class="btn btn-sm btn-primary" data-auris-generated-onclick="g0086"><i class="ti ti-plus"></i>Add manually</button></div>';
    return;
  }
  var h='<div style="border:1px solid var(--border);border-radius:8px;overflow:hidden;margin-bottom:8px">';
  results.forEach(function(t){
    var cat=t.category||'other';
    var col=(TOOL_CAT_COLORS||{})[cat]||'#6B7280';
    var icon=(TOOL_CAT_ICONS||{})[cat]||'ti-package';
    var alreadyAdded=wsTEItems.find(function(i){return i.tool_id===t.id;});
    h+='<div style="padding:10px 14px;border-bottom:1px solid #f5f5f5;display:flex;align-items:center;gap:12px;background:'+(alreadyAdded?'#f0fdf4':'#fff')+'">'
      +'<i class="ti '+icon+'" style="color:'+col+';font-size:16px;width:20px"></i>'
      +'<div style="flex:1">'
      +'<div style="font-weight:600;font-size:13px">'+escH(t.name)+'</div>'
      +'<div style="font-size:11px;color:var(--text2)"><span style="font-family:monospace;color:'+col+'">'+escH(t.ref_number||'-')+'</span>'+(t.location?' - '+escH(t.location):'')+'</div>'
      +'</div>'
      +(alreadyAdded
        ?'<span style="color:var(--green);font-size:11px;font-weight:700">Added</span>'
        :'<button class="btn btn-sm btn-primary" data-id="'+t.id+'" data-auris-generated-onclick="g0087"><i class="ti ti-plus"></i>Add</button>')
      +'</div>';
  });
  h+='</div>';
  el.innerHTML=h;
}

function wsTEAddFromRegister(toolId){
  var t=(toolsAllData||[]).find(function(x){return x.id===toolId;});
  if(!t)return;
  if(wsTEItems.find(function(i){return i.tool_id===toolId;})){toast('Already in list');return;}
  wsTEItems.push({tool_id:toolId,ref:t.ref_number||'',name:t.name,category:t.category||'other',source:'register',checked:false});
  wsTERenderItems();
  wsTESearchEquipment();
  toast(escH(t.name)+' added to equipment list');
}

async function wsTEAddManual(){
  var name=await appPrompt({title:'Add equipment',message:'Equipment name',placeholder:'e.g. Grinder, ladder, lifting chain'});if(!name||!name.trim())return;
  var cat=await appPrompt({title:'Equipment category',message:'Category',value:'equipment',placeholder:'hand_tool, power_tool, equipment, vehicle, lifting, electrical or other'});
  wsTEItems.push({tool_id:null,ref:'MANUAL',name:name.trim(),category:cat||'equipment',source:'manual',checked:false});
  wsTERenderItems();
}

async function wsTEAddItem(){
  var name=await appPrompt({title:'Add equipment',message:'Equipment name or search term',placeholder:'Equipment name'});
  if(!name||!name.trim())return;
  wsTEItems.push({tool_id:null,ref:'MANUAL',name:name.trim(),category:'equipment',source:'manual',checked:false});
  wsTERenderItems();
}

function wsTERenderItems(){
  var el=document.getElementById('ws-te-items-list');if(!el)return;
  if(!wsTEItems.length){
    el.innerHTML='<div style="text-align:center;padding:24px;color:var(--text2);font-size:13px">No equipment added yet. Search the register or add manually.</div>';
    return;
  }
  var h='<div style="font-weight:700;font-size:12px;color:var(--text2);text-transform:uppercase;letter-spacing:.04em;padding:8px 0;margin-bottom:6px">'+wsTEItems.length+' item'+(wsTEItems.length!==1?'s':'')+' required for this job</div>';
  h+='<div style="display:flex;flex-direction:column;gap:8px">';
  wsTEItems.forEach(function(item,i){
    var col=(TOOL_CAT_COLORS||{})[item.category]||'#6B7280';
    var icon=(TOOL_CAT_ICONS||{})[item.category]||'ti-package';
    var label=TOOL_CAT_LABELS?.[item.category]||item.category;
    h+='<div style="border:1px solid var(--border);border-radius:10px;padding:12px 16px;background:#fff;display:flex;align-items:center;gap:12px;cursor:pointer;transition:box-shadow .15s" '
      +'data-idx="'+i+'" data-auris-runtime-onclick="r0054" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([i]))+'" '
      +'onmouseover="this.style.boxShadow=\'0 2px 12px rgba(0,0,0,.08)\'" data-auris-generated-onmouseout="g0088">'
      +'<div style="width:42px;height:42px;border-radius:10px;background:'+col+'20;display:flex;align-items:center;justify-content:center;flex-shrink:0">'
      +'<i class="ti '+icon+'" style="font-size:20px;color:'+col+'"></i></div>'
      +'<div style="flex:1">'
      +'<div style="font-weight:700;font-size:13px">'+escH(item.name)+'</div>'
      +'<div style="font-size:11px;color:var(--text2);display:flex;gap:10px;margin-top:2px">'
      +'<span style="font-family:monospace;color:'+col+'">'+escH(item.ref||'MANUAL')+'</span>'
      +'<span>'+escH(label)+'</span>'
      +(item.source==='manual'?'<span style="color:#9CA3AF;font-style:italic">Manual entry</span>':'')
      +'</div></div>'
      +'<div style="display:flex;gap:8px;align-items:center">'
      +(item.inspected
        ?'<span style="background:#EAF3DE;color:#3B6D11;padding:3px 10px;border-radius:99px;font-size:11px;font-weight:700">Inspected '+(item.result==='pass'?'PASS':item.result==='fail'?'FAIL':'COND')+'</span>'
        :'<span style="background:#FEF9EC;color:#854F0B;padding:3px 10px;border-radius:99px;font-size:11px;font-weight:600">Not checked</span>')
      +'<button class="btn btn-sm" style="color:'+col+';border-color:'+col+'40" data-auris-runtime-onclick="r0055" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([i]))+'"><i class="ti ti-clipboard-check"></i>Inspect</button>'
      +'<button class="btn btn-sm" style="color:var(--red)" data-auris-runtime-onclick="r0056" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([i]))+'"><i class="ti ti-x"></i></button>'
      +'</div>'
      +'</div>';
  });
  h+='</div>';
  el.innerHTML=h;
}

function wsTERemove(idx){
  wsTEItems.splice(idx,1);
  wsTERenderItems();
}

async function wsTEOpenChecklist(idx){
  var item=wsTEItems[idx];
  if(!item)return;
  wsChkToolId=item.tool_id;
  wsChkToolName=item.name;
  wsChkToolCat=item.category;
  wsChkItemIdx=idx;

  document.getElementById('ws-te-form').style.display='none';
  document.getElementById('ws-te-checklist-view').style.display='block';
  document.getElementById('ws-chk-equip-name').textContent=item.name;
  document.getElementById('ws-chk-equip-ref').textContent=item.ref||'Manual entry';
  // Set date
  var dt=document.getElementById('ws-chk-date');if(dt)dt.value=new Date().toISOString().slice(0,10);
  // Inspector dropdown
  var insp=document.getElementById('ws-chk-inspector');
  if(insp){
    insp.innerHTML='<option value="">Select...</option>';
    (people||[]).forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.last_name+', '+p.first_name;insp.appendChild(o);});
  }
  // Load checklist
  var tbody=document.getElementById('ws-chk-body');
  if(tbody){
    try{
      var items=await api('/tool_checklist_templates?category=eq.'+item.category+'&order=sort_order');
      if(!items||!items.length)items=[{check_item:'Visual inspection - no damage'},{check_item:'Safe to use'},{check_item:'Correct for the task'},{check_item:'Clean and functional'}];
      tbody.innerHTML='';
      items.forEach(function(ci,i){
        var tr=document.createElement('tr');
        tr.style.borderBottom='1px solid #f5f5f5';
        tr.innerHTML='<td style="padding:8px 16px;font-size:12px">'+escH(ci.check_item)+'</td>'
          +'<td style="padding:6px;text-align:center"><input type="radio" name="wsc'+i+'" value="ok" id="wsc-ok-'+i+'" data-auris-generated-onchange="g0089" style="width:16px;height:16px;accent-color:#1D9E75"></td>'
          +'<td style="padding:6px;text-align:center"><input type="radio" name="wsc'+i+'" value="fail" id="wsc-fail-'+i+'" data-auris-generated-onchange="g0089" style="width:16px;height:16px;accent-color:#E24B4A"></td>'
          +'<td style="padding:6px;text-align:center"><input type="radio" name="wsc'+i+'" value="na" id="wsc-na-'+i+'" data-auris-generated-onchange="g0089" checked style="width:16px;height:16px;accent-color:#6B7280"></td>'
          +'<td style="padding:5px 12px"><input type="text" id="wsc-note-'+i+'" placeholder="Note..." style="width:100%;padding:4px 8px;border:1px solid var(--border);border-radius:6px;font-size:11px"/></td>';
        tbody.appendChild(tr);
      });
      wsChkScore();
    }catch(e){console.error(e);}
  }
}

var wsChkItemIdx=0;

function wsChkScore(){
  var rows=document.querySelectorAll('#ws-chk-body tr');
  var ok=0,fail=0,na=0;
  rows.forEach(function(tr,i){
    if(document.getElementById('wsc-ok-'+i)?.checked)ok++;
    else if(document.getElementById('wsc-fail-'+i)?.checked)fail++;
    else na++;
  });
  var el=document.getElementById('ws-chk-score');
  if(el)el.innerHTML='<span style="color:#a8f0d4;font-weight:700">'+ok+' OK</span> <span style="color:#fca5a5;font-weight:700">'+fail+' Fail</span> <span style="opacity:.7">'+na+' N/A</span>';
  var res=document.getElementById('ws-chk-result');
  if(res)res.value=fail>0?'fail':'pass';
}

async function wsChkSave(){
  var inspId=document.getElementById('ws-chk-inspector')?.value||null;
  var inspName='';
  if(inspId){var p=(people||[]).find(function(x){return x.id===inspId;});inspName=p?(p.last_name+', '+p.first_name):'';}
  var rows=document.querySelectorAll('#ws-chk-body tr');
  var results=[];
  rows.forEach(function(tr,i){
    var item=tr.querySelector('td')?.textContent||'Item '+i;
    var ok=document.getElementById('wsc-ok-'+i)?.checked;
    var fail=document.getElementById('wsc-fail-'+i)?.checked;
    var note=tr.querySelector('input[type="text"]')?.value||'';
    results.push({item:item,result:ok?'ok':fail?'fail':'na',note:note});
  });
  var resultVal=document.getElementById('ws-chk-result')?.value||'pass';
  try{
    if(wsChkToolId){
      // Save proper inspection record
      await api('/tool_inspections',{m:'POST',p:'return=minimal',b:{
        company_id:ccid(),tool_id:wsChkToolId,
        inspection_type:document.getElementById('ws-chk-type')?.value||'pre_use',
        inspection_date:document.getElementById('ws-chk-date')?.value||new Date().toISOString().slice(0,10),
        inspected_by:inspId||null,inspected_by_name:inspName||null,
        overall_result:resultVal,checklist_results:results,
        defects_found:document.getElementById('ws-chk-defects')?.value||null,
        created_by:prof?.id
      }});
    }
    // Mark item as inspected in local list
    if(wsTEItems[wsChkItemIdx]){
      wsTEItems[wsChkItemIdx].inspected=true;
      wsTEItems[wsChkItemIdx].result=resultVal;
    }
    var _lbl=resultVal==='pass'?'PASS':resultVal==='fail'?'FAIL':'Conditional';toast('Inspection saved - '+_lbl);
    wsBackToTEForm();
  }catch(e){toastActionError('Save work check','Work Schedule',e);console.error(e);}
}

function wsBackToTEForm(){
  document.getElementById('ws-te-checklist-view').style.display='none';
  document.getElementById('ws-te-form').style.display='block';
  wsTERenderItems();
}

function wsLinkedRefButton(kind,value,label){
  if(!value)return escH(label||'-');
  return '<button type="button" class="link-ref-btn" data-auris-runtime-onclick="r0057" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([kind,String(value)]))+'" title="Open linked record" style="border:0;background:transparent;color:var(--green);font-family:monospace;font-weight:800;cursor:pointer;padding:0;text-decoration:underline;text-underline-offset:2px">'+escH(label||value)+'</button>';
}

function wsSelectedLinkedValue(kind){
  var el=document.getElementById('ws-link-'+kind);
  return el?el.value:'';
}

function wsRestEqValue(value){
  return encodeURIComponent(String(value||'').trim());
}

async function wsOpenLinkedRecord(kind,value){
  value=value||wsSelectedLinkedValue(kind);
  if(!value){toast('No linked record selected',false);return;}
  try{
    if(kind==='ra'){
      showPage('risk',document.querySelector('[onclick*="\'risk\'"]'));
      var rec=(raAllData||[]).find(function(r){return r.id===value||r.ra_ref===value;});
      if(!rec){
        var rows=await api('/risk_assessments?select=*'+cf()+'&or=(id.eq.'+encodeURIComponent(value)+',ra_ref.eq.'+encodeURIComponent(value)+')&limit=1').catch(function(){return[];});
        rec=rows&&rows[0];
        if(rec&&!(raAllData||[]).some(function(r){return r.id===rec.id;}))raAllData.unshift(rec);
      }
      if(rec&&typeof raOpen==='function'){setTimeout(function(){raOpen(rec.id);},150);return;}
    }
    if(kind==='ptw'){
      showPage('permit',document.querySelector('[onclick*="\'permit\'"]'));
      var p=(ptwAllData||[]).find(function(r){return r.id===value||r.permit_number===value;});
      if(!p){
        var permits=await api('/permits?select=*'+cf()+'&or=(id.eq.'+encodeURIComponent(value)+',permit_number.eq.'+encodeURIComponent(value)+')&limit=1').catch(function(){return[];});
        p=permits&&permits[0];
        if(p&&!(ptwAllData||[]).some(function(r){return r.id===p.id;}))ptwAllData.unshift(p);
      }
      if(p&&typeof ptwShowDetail==='function'){setTimeout(function(){ptwShowDetail(p.id);},150);return;}
    }
    if(kind==='tbt'){
      showPage('meetings',document.querySelector('[onclick*="\'meetings\'"]'));
      var t=(tbtAllData||[]).find(function(r){return r.id===value||r.tbt_ref===value;});
      if(!t){
        var tbts=await api('/toolbox_talks?select=*'+cf()+'&or=(id.eq.'+wsRestEqValue(value)+',tbt_ref.eq.'+wsRestEqValue(value)+')&limit=1').catch(function(){return[];});
        t=tbts&&tbts[0];
        if(t&&!(tbtAllData||[]).some(function(r){return r.id===t.id;}))tbtAllData.unshift(t);
      }
      setTimeout(function(){if(typeof mtgSwitchTab==='function')mtgSwitchTab('tbt',document.getElementById('mtg-tab-tbt'));if(t&&typeof tbtEdit==='function')setTimeout(function(){tbtEdit(t.id);},150);},150);
      return;
    }
    if(kind==='prestart'||kind==='site'){
      showPage('inspection',document.querySelector('[onclick*="\'inspection\'"]'));
      var a=(auditAllData||[]).find(function(r){return r.id===value||r.reference_no===value;});
      if(!a){
        var audits=await api('/inspections?select=*'+cf()+'&or=(id.eq.'+wsRestEqValue(value)+',reference_no.eq.'+wsRestEqValue(value)+')&limit=1').catch(function(){return[];});
        a=audits&&audits[0];
        if(a&&!(auditAllData||[]).some(function(r){return r.id===a.id;}))auditAllData.unshift(a);
      }
      if(a&&typeof auditOpen==='function'){setTimeout(function(){auditOpen(a.id);},150);return;}
    }
    toast('Linked record not found or not accessible',false);
  }catch(e){
    toast(actionErrorMessage('Open linked record','Work Schedule',e),false);
  }
}

// wsRenderLinkedRecords - editable links to applicable HSE records/documents
async function wsRenderLinkedRecords(x){
  var el=document.getElementById('ws-linked-records');if(!el)return;
  var row=function(icon,label,kind,col){
    return '<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid #f5f5f5">'
      +'<i class="ti '+icon+'" style="color:'+col+';font-size:14px;width:18px"></i>'
      +'<span style="font-size:12px;color:var(--text2);flex:0 0 105px">'+label+'</span>'
      +'<select id="ws-link-'+kind+'" data-auris-runtime-onchange="r0058" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([kind]))+'" style="flex:1;min-width:0;padding:5px 7px;border:1px solid var(--border);border-radius:7px;font-size:11px;background:#fff">'
      +'<option value="">Loading...</option></select>'
      +'<button class="btn btn-sm" type="button" title="Open linked record" data-auris-runtime-onclick="r0059" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([kind]))+'" style="padding:5px 7px"><i class="ti ti-external-link"></i></button>'
      +'</div>';
  };
  var h='';
  h+=row('ti-speakerphone','Toolbox talk','tbt','#8B5CF6');
  h+=row('ti-shield-check','Pre-start check','prestart','#185FA5');
  h+=row('ti-clipboard-check','Site inspection','site','#1D9E75');
  h+=row('ti-alert-triangle','Risk assessment','ra','#E24B4A');
  h+=row('ti-key','Permit to work','ptw','#185FA5');
  el.innerHTML=h;
  await wsLoadLinkedRecordOptions(x);
}

function wsLinkedOptionHtml(rows,selected,blankLabel,valueFn,labelFn){
  var html='<option value="">'+escH(blankLabel||'None')+'</option>';
  (rows||[]).forEach(function(r){
    var val=valueFn(r)||'';
    html+='<option value="'+escH(val)+'" data-record-id="'+escH(r.id||'')+'" data-record-ref="'+escH(val)+'" data-record-status="'+escH(r.status||'')+'" '+(String(val)===String(selected||'')?'selected':'')+'>'+escH(labelFn(r)||val)+'</option>';
  });
  if(selected&&html.indexOf('value="'+escH(selected)+'"')<0)html+='<option value="'+escH(selected)+'" selected>'+escH(selected)+' (saved)</option>';
  return html;
}

async function wsEnsureLinkedRow(rows,selected,path,matchFn){
  if(!selected)return rows||[];
  rows=rows||[];
  if(rows.some(function(r){return matchFn(r,selected);}))return rows;
  try{
    var extra=await api(path).catch(function(){return[];});
    if(extra&&extra[0])rows=[extra[0]].concat(rows);
  }catch(_){}
  return rows;
}

async function wsLoadLinkedRecordOptions(x){
  var set=function(id,html){var el=document.getElementById(id);if(el)el.innerHTML=html;};
  try{
    var data=await Promise.all([
      api('/toolbox_talks?select=id,tbt_ref,title,talk_date'+cf()+'&order=talk_date.desc,created_at.desc&limit=120').catch(function(){return[];}),
      api('/inspections?select=id,reference_no,site,activity,inspection_date,inspection_type'+cf()+'&inspection_type=eq.prestart&order=inspection_date.desc,created_at.desc&limit=120').catch(function(){return[];}),
      api('/inspections?select=id,reference_no,site,activity,inspection_date,inspection_type'+cf()+'&inspection_type=neq.prestart&order=inspection_date.desc,created_at.desc&limit=120').catch(function(){return[];}),
      api('/risk_assessments?select=id,ra_ref,title,activity,status'+cf()+'&order=created_at.desc&limit=150').catch(function(){return[];}),
      api('/permits?select=id,permit_number,permit_type,permit_type_v2,status'+cf()+'&order=created_at.desc&limit=120').catch(function(){return[];})
    ]);
    data[0]=await wsEnsureLinkedRow(data[0],x.toolbox_talk_id,'/toolbox_talks?select=id,tbt_ref,title,talk_date'+cf()+'&id=eq.'+wsRestEqValue(x.toolbox_talk_id)+'&limit=1',function(r,v){return r.id===v||r.tbt_ref===v;});
    data[1]=await wsEnsureLinkedRow(data[1],x.prestart_id,'/inspections?select=id,reference_no,site,activity,inspection_date,inspection_type'+cf()+'&id=eq.'+wsRestEqValue(x.prestart_id)+'&limit=1',function(r,v){return r.id===v||r.reference_no===v;});
    data[2]=await wsEnsureLinkedRow(data[2],x.site_inspection_id,'/inspections?select=id,reference_no,site,activity,inspection_date,inspection_type'+cf()+'&id=eq.'+wsRestEqValue(x.site_inspection_id)+'&limit=1',function(r,v){return r.id===v||r.reference_no===v;});
    set('ws-link-tbt',wsLinkedOptionHtml(data[0],x.toolbox_talk_id,'No toolbox talk',function(r){return r.id;},function(r){return [(r.tbt_ref||'TBT'),r.title,r.talk_date].filter(Boolean).join(' - ');}));
    set('ws-link-prestart',wsLinkedOptionHtml(data[1],x.prestart_id,'No pre-start check',function(r){return r.id;},function(r){return [(r.reference_no||'Pre-start'),r.activity||r.site,r.inspection_date].filter(Boolean).join(' - ');}));
    set('ws-link-site',wsLinkedOptionHtml(data[2],x.site_inspection_id,'No site inspection',function(r){return r.id;},function(r){return [(r.reference_no||'Inspection'),r.activity||r.site,r.inspection_date].filter(Boolean).join(' - ');}));
    set('ws-link-ra',wsLinkedOptionHtml(data[3],x.ra_ref,'No risk assessment',function(r){return r.ra_ref||r.id;},function(r){return [(r.ra_ref||'RA'),r.title||r.activity,r.status].filter(Boolean).join(' - ');}));
    set('ws-link-ptw',wsLinkedOptionHtml(data[4],x.permit_ref,'No permit to work',function(r){return r.permit_number||r.id;},function(r){var type=r.permit_type_v2||r.permit_type;var cfg=(typeof PTW_TYPE_CFG!=='undefined')?PTW_TYPE_CFG[type]:null;return [(r.permit_number||'PTW'),cfg?.label||type,r.status].filter(Boolean).join(' - ');}));
  }catch(e){
    ['tbt','prestart','site','ra','ptw'].forEach(function(k){set('ws-link-'+k,'<option value="">Unable to load</option>');});
  }
}

async function wsLinkedRecordChanged(kind,value){
  if(!wsCurrentId)return;
  var patch={updated_at:new Date().toISOString()};
  if(kind==='tbt')patch.toolbox_talk_id=value||null;
  if(kind==='prestart')patch.prestart_id=value||null;
  if(kind==='site')patch.site_inspection_id=value||null;
  var selected=document.getElementById('ws-link-'+kind)?.selectedOptions?.[0],selectedId=selected?.dataset?.recordId||null;
  if(kind==='ra'){patch.ra_ref=value||null;patch.risk_assessment_id=selectedId;patch.requires_ra=!!value;}
  if(kind==='ptw'){patch.permit_ref=value||null;patch.permit_id=selectedId;patch.requires_permit=!!value;}
  try{
    await apiWriteWithMissingColumnFallback('/work_schedule?id=eq.'+wsCurrentId,{m:'PATCH',p:'return=minimal',b:patch},'Work order relationship');
    var x=wsAllData.find(function(r){return r.id===wsCurrentId;});
    if(x)Object.assign(x,patch);
    if(kind==='ra'){var ra=document.getElementById('ws-detail-ra');if(ra)ra.innerHTML=wsLinkedRefButton('ra',value,value||'-');}
    if(kind==='ptw'){var ptw=document.getElementById('ws-detail-ptw');if(ptw)ptw.innerHTML=wsLinkedRefButton('ptw',value,value||'-');}
    if(x)wsRenderActionStatuses(x);
    toast('Linked record updated');
  }catch(e){toastActionError('Link HSE record','Work Schedule',e);}
}

