  vehicle:              {emoji:'*',label:'Vehicle Incident',   color:'#1e40af',bg:'#EFF6FF',border:'#bfdbfe'},
  unsafe_act:           {emoji:'*',label:'Unsafe Act',         color:'#991B1B',bg:'#FEF2F2',border:'#fecaca'},
  unsafe_condition:     {emoji:'*',label:'Unsafe Condition',   color:'#9A3412',bg:'#FFF7ED',border:'#fed7aa'},
