  open:                {bg:'#FCEBEB',tc:'#A32D2D',label:'Open'},
  under_investigation: {bg:'#EDE9FE',tc:'#5B21B6',label:'Under Investigation'},
  action_required:     {bg:'#FEF9EC',tc:'#854F0B',label:'Action Required'},
