// -- Dynamic RA ----------------------------------------------------------------
function raDynamicAddRow(r){
  r=r||{};
  var body=document.getElementById('ra-dynamic-body');if(!body)return;
  var s=parseInt(r.rs||1);var p=parseInt(r.rop||1);var rr=s*p;
  var rlLvl=raRiskLevelFromFactors(s,p);
  var rlCfg=RL_CFG[rlLvl]||['#f3f4f6','#6B7280'];
  var tr=document.createElement('tr');tr.style.borderBottom='1px solid #f0f0f0';
  tr.innerHTML='<td style="padding:5px 8px"><textarea class="ra-condition" style="width:100%;min-height:45px;padding:4px;border:1px solid var(--border);border-radius:4px;font-size:11px;resize:vertical" placeholder="Observed condition / hazard...">'+escH(r.condition||r.hazard||'')+'</textarea></td>'
    +'<td style="padding:5px 8px"><textarea class="ra-risk-obs" style="width:100%;min-height:45px;padding:4px;border:1px solid var(--border);border-radius:4px;font-size:11px;resize:vertical" placeholder="Observed risk description...">'+escH(r.observed_risk||r.harm||'')+'</textarea></td>'
    +'<td style="padding:4px 5px;text-align:center">'+raRsSelect(s,'')+'</td>'
    +'<td style="padding:4px 5px;text-align:center">'+raRopSelect(p,'')+'</td>'
    +'<td class="rl" style="padding:4px;text-align:center" data-score="'+rr+'" data-level="'+rlLvl+'"><span style="background:'+rlCfg[0]+';color:'+rlCfg[1]+';padding:2px 5px;border-radius:4px;font-size:10px;font-weight:700;display:block;text-align:center">'+rr+'<br><span style="font-size:9px">'+rlLvl+'</span></span></td>'
    +'<td style="padding:5px 8px"><textarea class="ra-controls" style="width:100%;min-height:45px;padding:4px;border:1px solid var(--border);border-radius:4px;font-size:11px;resize:vertical" placeholder="Immediate action taken...">'+escH(r.controls||r.immediate_control||'')+'</textarea></td>'
    +'<td style="padding:5px 8px"><select class="ra-decision" style="padding:3px 4px;border:1px solid var(--border);border-radius:4px;font-size:11px;width:100px">'
    +'<option value="proceed">Proceed</option>'
    +'<option value="monitor"'+(r.decision==='monitor'?' selected':'')+'>Monitor</option>'
    +'<option value="stop_work"'+(r.decision==='stop_work'?' selected':'')+'>Stop Work</option>'
    +'</select></td>'
    +'<td style="padding:4px;text-align:center"><button class="btn btn-sm" style="color:var(--red);padding:2px 6px" data-auris-generated-onclick="g0125"><i class="ti ti-x" style="font-size:10px"></i></button></td>';
  body.appendChild(tr);
  setTimeout(raUpdateQualityPanel,0);
}

function raDynamicRender(rows){
  var body=document.getElementById('ra-dynamic-body');if(!body)return;
  body.innerHTML='';rows.forEach(function(r){raDynamicAddRow(r);});
  if(!rows.length)raDynamicAddRow();
  setTimeout(raUpdateQualityPanel,0);
}

// -- Collect Rows --------------------------------------------------------------
function raCollectRows(){
  var type=raEditingType;
  if(type==='dynamic'){
    return Array.from(document.querySelectorAll('#ra-dynamic-body tr')).map(function(tr){
      return {
        condition:tr.querySelector('.ra-condition')?.value||'',
        observed_risk:tr.querySelector('.ra-risk-obs')?.value||'',
        rs:parseInt(tr.querySelector('.rs')?.value)||1,
        rop:parseInt(tr.querySelector('.rop')?.value)||1,
        rr:(parseInt(tr.querySelector('.rs')?.value)||1)*(parseInt(tr.querySelector('.rop')?.value)||1),
        rl:raRiskLevelFromFactors(parseInt(tr.querySelector('.rs')?.value)||1,parseInt(tr.querySelector('.rop')?.value)||1),
        controls:tr.querySelector('.ra-controls')?.value||'',
        decision:tr.querySelector('.ra-decision')?.value||'proceed'
      };
    });
  }
  if(type==='task'){
    return Array.from(document.querySelectorAll('#ra-task-body tr')).map(function(tr){
      var rr=parseInt(tr.querySelector('.rs')?.value||1)*parseInt(tr.querySelector('.rop')?.value||1);
      var rrr=parseInt(tr.querySelector('.r-rs')?.value||1)*parseInt(tr.querySelector('.r-rop')?.value||1);
      return {
        task:tr.querySelector('.ra-task-step')?.value||'',
        hazard:tr.querySelector('.ra-hazard')?.value||'',
        harm:tr.querySelector('.ra-harm')?.value||'',
        rs:parseInt(tr.querySelector('.rs')?.value)||1,
        rop:parseInt(tr.querySelector('.rop')?.value)||1,
        rr:rr,rl:raRiskLevelFromFactors(parseInt(tr.querySelector('.rs')?.value)||1,parseInt(tr.querySelector('.rop')?.value)||1),
        controls:tr.querySelector('.ra-controls')?.value||'',
        further_controls:tr.querySelector('.ra-further-controls')?.value||'',
        hoc_level:tr.querySelector('.ra-hoc')?.value||'',
        legal_ref:tr.querySelector('.ra-legal')?.value||'',
        action_by:tr.querySelector('.ra-action-by')?.value||'',
        target_date:tr.querySelector('.ra-target-date')?.value||'',
        res_s:parseInt(tr.querySelector('.r-rs')?.value)||1,
        res_p:parseInt(tr.querySelector('.r-rop')?.value)||1,
        res_rr:rrr,res_rl:raRiskLevelFromFactors(parseInt(tr.querySelector('.r-rs')?.value)||1,parseInt(tr.querySelector('.r-rop')?.value)||1)
      };
    });
  }
  // Baseline / HIRA / Environmental
  var bodyId=(type==='hira')?'ra-hira-body':'ra-baseline-body';
  return Array.from(document.querySelectorAll('#'+bodyId+' tr')).map(function(tr){
    var rr=parseInt(tr.querySelector('.rs')?.value||1)*parseInt(tr.querySelector('.rop')?.value||1);
    var rrr=parseInt(tr.querySelector('.r-rs')?.value||1)*parseInt(tr.querySelector('.r-rop')?.value||1);
    return {
      category:tr.querySelector('.ra-hcat')?.value||'',
      hazard:tr.querySelector('.ra-hazard')?.value||'',
      harm:tr.querySelector('.ra-harm')?.value||'',
      who:tr.querySelector('.ra-who')?.value||'',
      rs:parseInt(tr.querySelector('.rs')?.value)||1,
      rop:parseInt(tr.querySelector('.rop')?.value)||1,
      rr:rr,rl:raRiskLevelFromFactors(parseInt(tr.querySelector('.rs')?.value)||1,parseInt(tr.querySelector('.rop')?.value)||1),
      controls:tr.querySelector('.ra-controls')?.value||'',
      further_controls:tr.querySelector('.ra-further-controls')?.value||'',
      hoc_level:tr.querySelector('.ra-hoc')?.value||'',
      action_by:tr.querySelector('.ra-action-by')?.value||'',
      target_date:tr.querySelector('.ra-target-date')?.value||'',
      res_s:parseInt(tr.querySelector('.r-rs')?.value)||1,
      res_p:parseInt(tr.querySelector('.r-rop')?.value)||1,
      res_rr:rrr,res_rl:raRiskLevelFromFactors(parseInt(tr.querySelector('.r-rs')?.value)||1,parseInt(tr.querySelector('.r-rop')?.value)||1),
      legal_ref:tr.querySelector('.ra-legal')?.value||''
    };
  });
}

function raRowHasContent(r){
  return !!((r.hazard||r.task||r.condition||'').trim()||(r.harm||r.observed_risk||'').trim()||(r.controls||'').trim()||(r.further_controls||r.further_actions||'').trim());
}

// ===== RA_JS_PART3.JS =====
// -- Save RA -------------------------------------------------------------------
async function raSave(targetStatus){
  if(!workflowCanMutate('risk','risk assessments'))return;
  var currentRa=raEditingId?(raAllData.find(function(x){return x.id===raEditingId;})||{}):null;
  if(currentRa&&!controlledRecordCanEdit(currentRa)){
    toast('This risk assessment is locked. Admin/HSE Manager must release or create a revision before changes.',false);
    return;
  }
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var rows=raCollectRows().filter(raRowHasContent);
  var status=targetStatus||g('ra-status-sel')||'draft';
  if(currentRa&&!coreWorkflowRequireDirectEdit('risk',currentRa.status||'draft',status,'Risk assessment'))return;
  if(status!=='draft'){
    if(!(g('ra-title')||g('ra-activity')))return toast('Please enter an RA title or activity before submitting',false);
    if(!g('ra-assessed-by'))return toast('Please select the assessor before submitting',false);
    if(!g('ra-date'))return toast('Please enter the assessment date before submitting',false);
    if(!g('ra-review-date'))return toast('Please enter the review date before submitting',false);
    if(!rows.length)return toast('Please add at least one hazard/control row before submitting',false);
  }
  if(g('ra-date')&&g('ra-review-date')&&new Date(g('ra-review-date'))<new Date(g('ra-date')))return toast('Review date cannot be before assessment date',false);
  // Calculate overall risk
  var maxRR=0;var maxLvl='Low';
  rows.forEach(function(r){
    var rr=parseInt(r.rr||0);
    if(rr>maxRR){maxRR=rr;maxLvl=r.rl||'Low';}
  });
  var body={
    company_id:ccid(),
    ra_type_v2:raEditingType,ra_type:raEditingType,
    title:g('ra-title')||g('ra-activity')||'Untitled RA',
    activity:g('ra-activity')||g('ra-workshop'),
    department:g('ra-dept'),location:g('ra-workshop'),
    site_name:g('ra-site-name'),scope:g('ra-scope'),
    workshop:g('ra-workshop'),
    assessed_by:g('ra-assessed-by'),ra_assessor:g('ra-assessed-by'),
    ra_date:g('ra-date'),date:g('ra-date'),assessment_date:g('ra-date'),
    review_date:g('ra-review-date'),ra_review_date:g('ra-review-date'),
    approved_by:g('ra-approved-by'),ra_approver:g('ra-approved-by'),
    reviewed_by:g('ra-reviewed-by'),
    ra_sign_assessor:g('ra-sign-assessor'),ra_sign_assessor_date:g('ra-sign-assessor-date'),
    ra_sign_reviewer:g('ra-sign-reviewer'),ra_sign_reviewer_date:g('ra-sign-reviewer-date'),
    ra_sign_approver:g('ra-sign-approver'),ra_sign_approver_date:g('ra-sign-approver-date'),
    ra_briefed:g('ra-briefed-persons'),
    rams_document_url:g('ra-rams-url'),rams_document_name:g('ra-rams-name'),
    permit_ref:g('ra-linked-permit'),job_segment:g('ra-job-seg'),
    ra_job_seg:g('ra-job-seg'),
    revision_notes:g('ra-rev-notes'),
    rejection_reason:g('ra-rejection-reason'),
    legal_refs:raLegalRefs,
    rows:rows,baseline_rows:rows,
    overall_risk_level:maxLvl,overall_risk_score:maxRR,
    status:status,
    revision:raCurrentRevision,
    updated_at:new Date().toISOString()
  };
  Object.assign(body,locationIdentityPayload(body.site_name,body.location));
  // Handle linked WO
  var woSel=document.getElementById('ra-linked-wo');
  if(woSel&&woSel.value)body.work_order_id=woSel.value;
  try{
    var saved;
    if(raEditingId){
      await apiWriteWithMissingColumnFallback('/risk_assessments?id=eq.'+raEditingId,{m:'PATCH',p:'return=minimal',b:body},'Risk assessment');
      var idx=raAllData.findIndex(x=>x.id===raEditingId);
      if(idx>=0)Object.assign(raAllData[idx],body);
      var updatedRa=Object.assign({},currentRa||{},{id:raEditingId},body);
      raRenderWorkflowBar(updatedRa);
      var submitted=['pending_review','pending_approval','review'].includes(status);
      if(submitted){
        await raQueueApprovalRequest(updatedRa);
        var route=await raGetActiveApprovalWorkflow();
        await raQueueApprovalNotice(updatedRa,(route&&route.steps&&route.steps[0])||null);
      }
      raAudit(submitted?'submit':'update',submitted?'Risk assessment submitted for approval':'Risk assessment updated',updatedRa,{old_status:currentRa?.status||null,new_status:status,row_count:rows.length});
      if(submitted&&currentRa?.status!==status)await raQueueStatusNotice(updatedRa,'submitted');
      toast('Risk assessment updated!');
      // Update linked work order if needed
      raSyncToMAP(raEditingId, rows);
    }else{
      body.created_by=prof?.id;
      var res=await apiWriteWithMissingColumnFallback('/risk_assessments',{m:'POST',p:'return=representation',b:body},'Risk assessment');
      if(res?.[0]?.id){
        var ref=await raGenRef(raEditingType);
        await api('/risk_assessments?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{ra_ref:ref}});
        res[0].ra_ref=ref;raAllData.unshift(res[0]);
        raEditingId=res[0].id;
        // Update form header
        document.getElementById('ra-form3ref').textContent=ref;
        document.getElementById('ra-form3title').textContent=body.title||'Risk Assessment';
        var createdRa=Object.assign({},body,{id:res[0].id,ra_ref:ref});
        raRenderWorkflowBar(createdRa);
        var newSubmitted=['pending_review','pending_approval','review'].includes(status);
        if(newSubmitted){
          await raQueueApprovalRequest(createdRa);
          var newRoute=await raGetActiveApprovalWorkflow();
          await raQueueApprovalNotice(createdRa,(newRoute&&newRoute.steps&&newRoute.steps[0])||null);
        }
        raAudit(newSubmitted?'submit':'create',newSubmitted?'Risk assessment created and submitted for approval':'Risk assessment created',createdRa,{new_status:status,row_count:rows.length});
        if(newSubmitted)await raQueueStatusNotice(createdRa,'submitted');
        toast('RA saved! Ref: '+ref);
        raSyncToMAP(res[0].id, rows);
      }
    }
  }catch(e){toast(actionErrorMessage('Save risk assessment','Risk Assessment',e.message),false);console.error(e);}
}

async function raGetActiveApprovalWorkflow(){
  var companyId=ccid();
  if(!companyId)return null;
  try{
    var wf=await api('/approval_workflows?company_id=eq.'+companyId+'&module_name=eq.risk&is_active=eq.true&order=created_at.desc&limit=1');
    if(!wf||!wf[0])return null;
    var steps=await api('/approval_workflow_steps?workflow_id=eq.'+wf[0].id+'&order=step_no.asc')||[];
    return {workflow:wf[0],steps:steps.filter(function(s){return s.required!==false;})};
  }catch(e){
    console.warn('[RA] Approval workflow unavailable:',e.message);
    return null;
  }
}

function raApprovalStepLabel(step){
  if(!step)return 'Admin / HSE Manager';
  return step.approver_name||auditLabel(step.approver_role||'')||'Configured approver';
}

function raApprovalStepAllows(step){
  if(!step)return canAdministerControlledRecord();
  if(isSA())return true;
  var role=activeRole();
  if(step.approver_person_id&&prof?.id&&String(step.approver_person_id)===String(prof.id))return true;
  if(step.approver_email&&prof?.email&&String(step.approver_email).toLowerCase()===String(prof.email).toLowerCase())return true;
  if(step.approver_role&&String(step.approver_role)===String(role))return true;
  return false;
}

function raRecordRef(rec){
  return rec?.ra_ref||rec?.reference_no||rec?.id?.slice(0,8)||'RA';
}

function raRecordTitle(rec){
  return rec?.title||rec?.activity||'Risk assessment';
}

function raAudit(action,summary,rec,details){
  try{
    rec=rec||{};
    auditLogEvent(action,'risk',summary,{
      ra_ref:raRecordRef(rec),
      title:raRecordTitle(rec),
      ra_type:rec.ra_type_v2||rec.ra_type||raEditingType||null,
      status:rec.status||null,
      overall_risk_level:rec.overall_risk_level||null,
      location:rec.location||rec.workshop||rec.site_name||null,
      details:details||{}
    },{related_table:'risk_assessments',related_id:rec.id||raEditingId||null,company_id:rec.company_id||ccid()});
  }catch(_){}
}

function raApprovalStepContact(step){
  step=step||{};
  var p=(people||[]).find(function(x){
    return step.approver_person_id&&String(x.id)===String(step.approver_person_id);
  });
  return {
    name:step.approver_name||peopleName(p)||auditLabel(step.approver_role||'Approver'),
    email:step.approver_email||usersContactEmail(p)||''
  };
}

async function raQueueApprovalNotice(rec,step){
  try{
    var contact=raApprovalStepContact(step);
    if(!contact.email)return;
    var ref=raRecordRef(rec), title=raRecordTitle(rec);
    var body='<div style="font-family:Arial,sans-serif;background:#f4f6f8;padding:20px"><div style="max-width:620px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb">'
      +'<div style="background:#185FA5;color:#fff;padding:18px 22px"><div style="font-size:20px;font-weight:700">AURIS360</div><div style="font-size:13px;opacity:.85">Risk assessment approval request</div></div>'
      +'<div style="padding:22px"><h2 style="margin:0 0 14px;font-size:18px">Risk assessment approval required</h2>'
      +'<table style="width:100%;border-collapse:collapse;font-size:14px">'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600;width:150px">Reference</td><td style="padding:8px">'+escH(ref)+'</td></tr>'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Title</td><td style="padding:8px">'+escH(title)+'</td></tr>'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Risk</td><td style="padding:8px">'+escH(rec.overall_risk_level||'-')+'</td></tr>'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Approver</td><td style="padding:8px">'+escH(raApprovalStepLabel(step))+'</td></tr>'
      +'</table><div style="margin-top:18px;text-align:center"><a href="https://auris360.app/?goto=risk" style="display:inline-block;background:#1D9E75;color:#fff;padding:11px 22px;border-radius:8px;text-decoration:none;font-weight:700">Open Risk Assessment</a></div></div>'
      +'<div style="padding:12px 22px;background:#f4f6f8;font-size:11px;color:#6B7280;text-align:center">Automated notification from AURIS360.</div></div></div>';
    await queueNotification({company_id:rec.company_id||ccid(),type:'risk_assessment',subject:'[AURIS360] Risk assessment approval required: '+ref,body_html:body,to_email:contact.email,to_name:contact.name||contact.email,from_name:'AURIS360 by SEPHS Consulting',related_module:'risk',related_id:rec.id||raEditingId||null,related_table:'risk_assessments',related_ref:ref,status:'pending'});
  }catch(e){}
}

async function raQueueStatusNotice(rec,event,details){
  try{
    rec=rec||{};
    var labels={submitted:'submitted for approval',approved:'approved and active',rejected:'rejected for correction',released:'released for edit',archived:'archived',deleted:'deleted'};
    var label=labels[event]||String(event||'updated').replace(/_/g,' ');
    var recipients=[], seen={};
    function addPerson(name,email){
      email=String(email||'').trim();
      if(!email||seen[email.toLowerCase()])return;
      seen[email.toLowerCase()]=true;
      recipients.push({name:name||email,email:email});
    }
    var assessor=(people||[]).find(function(p){return peopleName(p)===rec.assessed_by||ptwPersonName(p)===rec.assessed_by||p.id===rec.assessed_by;});
    addPerson(rec.assessed_by||peopleName(assessor),usersContactEmail(assessor));
    if(prof&&rec.created_by===prof.id)addPerson(prof.full_name||prof.email,prof.email);
    var ref=raRecordRef(rec), title=raRecordTitle(rec);
    var body='<div style="font-family:Arial,sans-serif;background:#f4f6f8;padding:20px"><div style="max-width:620px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb">'
      +'<div style="background:#1D9E75;color:#fff;padding:18px 22px"><div style="font-size:20px;font-weight:700">AURIS360</div><div style="font-size:13px;opacity:.85">Risk assessment update</div></div>'
      +'<div style="padding:22px"><h2 style="margin:0 0 14px;font-size:18px">Risk assessment '+escH(label)+'</h2>'
      +'<table style="width:100%;border-collapse:collapse;font-size:14px">'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600;width:150px">Reference</td><td style="padding:8px">'+escH(ref)+'</td></tr>'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Title</td><td style="padding:8px">'+escH(title)+'</td></tr>'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Status</td><td style="padding:8px">'+escH(rec.status||event||'-')+'</td></tr>'
      +(details?.reason?'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Reason</td><td style="padding:8px">'+escH(details.reason)+'</td></tr>':'')
      +'</table><div style="margin-top:18px;text-align:center"><a href="https://auris360.app/?goto=risk" style="display:inline-block;background:#1D9E75;color:#fff;padding:11px 22px;border-radius:8px;text-decoration:none;font-weight:700">Open Risk Assessment</a></div></div>'
      +'<div style="padding:12px 22px;background:#f4f6f8;font-size:11px;color:#6B7280;text-align:center">Automated notification from AURIS360.</div></div></div>';
    for(var i=0;i<recipients.length;i++){
      await queueNotification({company_id:rec.company_id||ccid(),type:'risk_assessment',subject:'[AURIS360] Risk assessment '+label+': '+ref,body_html:body,to_email:recipients[i].email,to_name:recipients[i].name,from_name:'AURIS360 by SEPHS Consulting',related_module:'risk',related_id:rec.id||raEditingId||null,related_table:'risk_assessments',related_ref:ref,status:'pending'});
    }
  }catch(e){}
}

async function raCurrentApprovalStep(){
  var route=await raGetActiveApprovalWorkflow();
  if(!route||!route.steps||!route.steps.length)return null;
  return route.steps[0]||null;
}

async function raQueueApprovalRequest(rec){
  try{
    var route=await raGetActiveApprovalWorkflow();
    if(!route||!route.workflow)return;
    var first=(route.steps||[])[0]||null;
    var id=rec?.id||raEditingId;
    if(!id)return;
    var existing=await api('/approval_requests?module_name=eq.risk&related_table=eq.risk_assessments&related_id=eq.'+id+'&status=in.(pending,pending_review,pending_approval)&limit=1');
    var body={
      company_id:ccid(),
      module_name:'risk',
      related_table:'risk_assessments',
      related_id:id,
      status:'pending',
      current_step_no:first?.step_no||1,
      workflow_id:route.workflow.id,
      requested_by:prof?.id||null,
      updated_at:new Date().toISOString()
    };
    if(existing&&existing[0])await api('/approval_requests?id=eq.'+existing[0].id,{m:'PATCH',p:'return=minimal',b:body});
    else await api('/approval_requests',{m:'POST',p:'return=minimal',b:body});
  }catch(e){
    console.warn('[RA] Could not queue approval request:',e.message);
  }
}

async function raCloseApprovalRequest(status){
  try{
    if(!raEditingId)return;
    var rows=await api('/approval_requests?module_name=eq.risk&related_table=eq.risk_assessments&related_id=eq.'+raEditingId+'&status=in.(pending,pending_review,pending_approval)&limit=5');
    for(var i=0;i<(rows||[]).length;i++){
      await api('/approval_requests?id=eq.'+rows[i].id,{m:'PATCH',p:'return=minimal',b:{status:status||'approved',updated_at:new Date().toISOString()}});
    }
  }catch(e){
    console.warn('[RA] Could not close approval request:',e.message);
  }
}

async function raApproveCurrent(){
  if(!raEditingId)return;
  if(!canAdministerControlledRecord()){toast('Only Admin or HSE Manager can approve risk assessments',false);return;}
  var currentApprovalRa=raAllData.find(function(x){return x.id===raEditingId;})||{};
  if(!coreWorkflowRequireTransition('risk',currentApprovalRa.status||'draft','active','Risk assessment'))return;
  var expected=await raCurrentApprovalStep();
  if(expected&&!raApprovalStepAllows(expected)){
    toast('This RA is waiting for '+raApprovalStepLabel(expected)+' according to the approval workflow.',false);
    return;
  }
  var reviewer=raGetFieldValue('ra-sign-reviewer')||prof?.full_name||prof?.email||'';
  var approver=raGetFieldValue('ra-sign-approver')||prof?.full_name||prof?.email||'';
  var today=new Date().toISOString().slice(0,10);
  var body={
    status:'active',
    reviewed_by:reviewer||null,
    approved_by:approver||null,
    ra_sign_reviewer:reviewer||null,
    ra_sign_approver:approver||null,
    ra_sign_reviewer_date:raGetFieldValue('ra-sign-reviewer-date')||today,
    ra_sign_approver_date:raGetFieldValue('ra-sign-approver-date')||today,
    updated_at:new Date().toISOString()
  };
  try{
    await api('/risk_assessments?id=eq.'+raEditingId,{m:'PATCH',p:'return=minimal',b:body});
    var rec=raAllData.find(function(x){return x.id===raEditingId;})||{};
    Object.assign(rec,body);
    var st=document.getElementById('ra-status-sel');if(st)st.value='active';
    fillPersonSelect('ra-reviewed-by',body.reviewed_by||'');
    fillPersonSelect('ra-approved-by',body.approved_by||'');
    fillPersonSelect('ra-sign-reviewer',body.ra_sign_reviewer||'');
    fillPersonSelect('ra-sign-approver',body.ra_sign_approver||'');
    var rd=document.getElementById('ra-sign-reviewer-date');if(rd)rd.value=body.ra_sign_reviewer_date;
    var ad=document.getElementById('ra-sign-approver-date');if(ad)ad.value=body.ra_sign_approver_date;
    controlledApplyFormLock('ra-form3view','ra-controlled-lock-note',rec,'Risk assessment');
    raRenderWorkflowBar(rec);
    await raCloseApprovalRequest('approved');
    raAudit('approve','Risk assessment approved and activated',rec,{reviewer:reviewer,approver:approver,new_status:'active'});
    await raQueueStatusNotice(rec,'approved');
    toast('Risk assessment approved and activated');
  }catch(e){toastActionError('Approve risk assessment','Risk Assessment',e);}
}

async function raRejectCurrent(){
  if(!raEditingId)return;
  if(!canAdministerControlledRecord()){toast('Only Admin or HSE Manager can reject risk assessments',false);return;}
  var currentRejectedRa=raAllData.find(function(x){return x.id===raEditingId;})||{};
  if(!coreWorkflowRequireTransition('risk',currentRejectedRa.status||'draft','rejected','Risk assessment'))return;
  var reason=await appPrompt({title:'Reject risk assessment',message:'Enter the reason for rejection or required correction.',placeholder:'e.g. Controls not specific enough, missing task step...',multiline:true});
  if(reason===null||reason===undefined)return;
  var body={status:'rejected',rejection_reason:String(reason||'Revision required'),updated_at:new Date().toISOString()};
  try{
    await api('/risk_assessments?id=eq.'+raEditingId,{m:'PATCH',p:'return=minimal',b:body});
    var rec=raAllData.find(function(x){return x.id===raEditingId;})||{};
    Object.assign(rec,body);
    var st=document.getElementById('ra-status-sel');if(st)st.value='rejected';
    var rr=document.getElementById('ra-rejection-reason');if(rr)rr.value=body.rejection_reason;
    controlledApplyFormLock('ra-form3view','ra-controlled-lock-note',rec,'Risk assessment');
    raRenderWorkflowBar(rec);
    await raCloseApprovalRequest('rejected');
    raAudit('reject','Risk assessment rejected for correction',rec,{reason:body.rejection_reason,new_status:'rejected'});
    await raQueueStatusNotice(rec,'rejected',{reason:body.rejection_reason});
    toast('Risk assessment rejected for correction');
  }catch(e){toastActionError('Reject risk assessment','Risk Assessment',e);}
}

async function raReleaseForEdit(){
  if(!raEditingId)return;
  if(!canAdministerControlledRecord()){toast('Only Admin or HSE Manager can release a risk assessment for edit',false);return;}
  var currentReleaseRa=raAllData.find(function(x){return x.id===raEditingId;})||{};
  if(!coreWorkflowRequireTransition('risk',currentReleaseRa.status||'draft','draft','Risk assessment'))return;
  var note=await appPrompt({title:'Release risk assessment',message:'Why is this RA being released for edit?',placeholder:'e.g. Update controls after site change',multiline:true});
  if(note===null||note===undefined)return;
  var current=raAllData.find(function(x){return x.id===raEditingId;})||{};
  var newRev=(parseInt(current.revision||raCurrentRevision||1)||1)+1;
  var body={
    status:'draft',
    revision:newRev,
    revision_notes:String(note||'Released for edit'),
    rejection_reason:null,
    reviewed_by:null,
    approved_by:null,
    ra_sign_reviewer:null,
    ra_sign_reviewer_date:null,
    ra_sign_approver:null,
    ra_sign_approver_date:null,
    updated_at:new Date().toISOString()
  };
  try{
    await raArchiveCurrentRevision(current,String(note||'Released for edit'));
    await api('/risk_assessments?id=eq.'+raEditingId,{m:'PATCH',p:'return=minimal',b:body});
    var rec=raAllData.find(function(x){return x.id===raEditingId;})||{};
    Object.assign(rec,body);
    raCurrentRevision=newRev;
    var st=document.getElementById('ra-status-sel');if(st)st.value='draft';
    var rn=document.getElementById('ra-rev-notes');if(rn)rn.value=body.revision_notes;
    document.getElementById('ra-rev-badge').textContent='Rev '+newRev;
    fillPersonSelect('ra-reviewed-by','');
    fillPersonSelect('ra-approved-by','');
    fillPersonSelect('ra-sign-reviewer','');
    fillPersonSelect('ra-sign-approver','');
    var rd=document.getElementById('ra-sign-reviewer-date');if(rd)rd.value='';
    var ad=document.getElementById('ra-sign-approver-date');if(ad)ad.value='';
    controlledApplyFormLock('ra-form3view','ra-controlled-lock-note',rec,'Risk assessment');
    raRenderWorkflowBar(rec);
    await raCloseApprovalRequest('released_for_edit');
    raAudit('release','Risk assessment released for edit',rec,{revision:newRev,reason:body.revision_notes,new_status:'draft'});
    await raQueueStatusNotice(rec,'released',{reason:body.revision_notes});
    raLoadRevisions();
    toast('Risk assessment released as Rev '+newRev);
  }catch(e){toastActionError('Release risk assessment for edit','Risk Assessment',e);}
}

async function raGenRef(type){
  var prefix={'baseline':'GRA','task':'TRA','dynamic':'DRA','hira':'HIRA','jsa':'JSA','environmental':'ERA'}[type]||'RA';
  var yr=new Date().getFullYear();
  var n=raAllData.filter(x=>(x.ra_type_v2||x.ra_type)===type).length+1;
  return prefix+'-'+yr+'-'+String(n).padStart(3,'0');
}

function raSyncToMAP(raId, rows){
  // Auto-create MAP actions for critical/high residual risks
  var ra=(raAllData||[]).find(function(x){return String(x.id)===String(raId);})||{};
  var sourceRef=raRecordRef(ra);
  rows.forEach(function(r){
    var rl=r.res_rl||r.rl||'';
    if(['Critical','Very High'].includes(rl)){
      api('/action_tracker',{m:'POST',p:'return=minimal',b:{
        company_id:ccid(),source_module:'risk',source_id:raId,source_ref:sourceRef,
        description:'High residual risk: '+( r.hazard||'').substring(0,100),
        priority:rl==='Critical'?'critical':'high',status:'open',created_by:prof?.id
      }}).catch(function(){});
    }
  });
}

function raClearForm(){
  ['ra-baseline-body','ra-task-body','ra-dynamic-body','ra-hira-body'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.innerHTML='';
  });
}

// -- Delete --------------------------------------------------------------------
async function raDeleteCurrent(){
  if(!workflowCanMutate('risk','risk assessments'))return;
  if(!raEditingId)return;
  var current=raAllData.find(function(x){return x.id===raEditingId;})||{};
  var st=current.status||'draft';
  if(!['draft','rejected','archived'].includes(st)){
    if(!(await appConfirmAction({title:'Archive risk assessment',message:'Archive this risk assessment instead of deleting it?',detail:'The RA will be removed from active use but retained for audit history and future reference. Create a revision if it still needs to be updated.',confirmText:'Archive RA',cancelText:'Back'})))return;
    try{
      await api('/risk_assessments?id=eq.'+raEditingId,{m:'PATCH',p:'return=minimal',b:{status:'archived',archived_at:new Date().toISOString(),updated_at:new Date().toISOString()}});
      Object.assign(current,{status:'archived',archived_at:new Date().toISOString()});
      var sel=document.getElementById('ra-status-sel');if(sel)sel.value='archived';
      raAudit('archive','Risk assessment archived',current,{old_status:st,new_status:'archived'});
      await raQueueStatusNotice(current,'archived');
      toast('Risk assessment archived and kept for audit history');
      controlledApplyFormLock('ra-form3view','ra-controlled-lock-note',current,'Risk assessment');
    }catch(e){toast(actionErrorMessage('Archive risk assessment','Risk Assessment',e.message),false);}
    return;
  }
  if(!(await appConfirmDelete('risk assessment','Permanent deletion is intended only for draft, rejected, archived or test risk assessments.')))return;
  api('/risk_assessments?id=eq.'+raEditingId,{m:'DELETE',p:'return=representation'}).then(function(deleted){
    if(!deleted||!deleted.length)throw new Error('Delete failed: record not found or permission denied');
    raAudit('delete','Risk assessment permanently deleted',current,{old_status:st});
    raAllData=raAllData.filter(x=>x.id!==raEditingId);
    toast('Risk assessment permanently deleted');raEditingId=null;raShowList();
  }).catch(function(e){toast(actionErrorMessage('Delete risk assessment','Risk Assessment',e.message),false);});
}
function raDelete(){raDeleteCurrent();}

