function raGuessRiskSeverity(text){
  text=(text||'').toLowerCase();
  if(/fatal|death|amputation|explosion|fire|electric shock|collapse|asphyxiation|confined/.test(text))return 5;
  if(/fracture|serious|burn|chemical|toxic|crush|fall from height|respiratory/.test(text))return 4;
  if(/injury|strain|sprain|cut|slip|trip|manual handling/.test(text))return 3;
  return 2;
}
function raGuessRiskProbability(text){
  text=(text||'').toLowerCase();
  if(/continuous|frequent|daily|regular|likely|high probability/.test(text))return 4;
  if(/occasional|weekly|possible|may occur/.test(text))return 3;
  if(/rare|unlikely|infrequent/.test(text))return 1;
  return 2;
}
function raExtractRowsFromText(text){
  var clean=(text||'').replace(/\r/g,'\n').replace(/[ \t]+/g,' ');
  var lines=clean.split('\n').map(function(l){return l.trim();}).filter(function(l){return l.length>3;});
  var rows=[], hazardRe=/(hazard|danger|risk|activity|task|step|control|mitigation|harm|injury|exposure)/i;
  for(var i=0;i<lines.length;i++){
    var l=lines[i]; if(!hazardRe.test(l))continue;
    var joined=[l,lines[i+1]||'',lines[i+2]||''].join(' ');
    var parts=l.split(/\s{2,}|\t+|\s\|\s|;+/).map(function(p){return p.trim();}).filter(Boolean);
    var hazard='', harm='', controls='';
    if(parts.length>=3){hazard=parts[0];harm=parts[1];controls=parts.slice(2).join('; ');}
    else{
      var hm=joined.match(/(?:hazard|risk)\s*[:\-]?\s*([^.;]{8,120})/i);
      var cm=joined.match(/(?:control|mitigation|preventive measures?)\s*[:\-]?\s*([^.;]{8,180})/i);
      var harmM=joined.match(/(?:harm|consequence|injury)\s*[:\-]?\s*([^.;]{8,120})/i);
      hazard=(hm&&hm[1])||l.replace(/^(hazard|risk|task|activity)\s*[:\-]?\s*/i,'').substring(0,120);
      harm=(harmM&&harmM[1])||'Potential injury / ill health';
      controls=(cm&&cm[1])||'Review existing controls and confirm suitability before work starts.';
    }
    if(hazard.length<6)continue;
    var key=hazard.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
    if(rows.some(function(r){return (r._key||'')===key;}))continue;
    rows.push({_key:key,task:hazard,hazard:hazard,harm:harm,who:'Workers / affected persons',rs:raGuessRiskSeverity(joined),rop:raGuessRiskProbability(joined),controls:controls,hoc_level:/guard|ventilation|isolation|barrier|interlock/i.test(controls)?'engineering':'administrative',res_s:Math.max(1,raGuessRiskSeverity(joined)-1),res_p:1});
    if(rows.length>=12)break;
  }
  var tableRe=/^(.{6,90}?)\s{2,}(.{6,120}?)\s{2,}(.{10,260})$/i;
  for(var j=0;j<lines.length&&rows.length<18;j++){
    var m=lines[j].match(tableRe);
    if(!m)continue;
    var skip=/^(ref|no\.?|hazard|activity|task|risk|control|severity|probability|score)$/i;
    if(skip.test(m[1])||skip.test(m[2]))continue;
    var hazard2=m[1].trim(), harm2=m[2].trim(), controls2=m[3].trim();
    if(!/(injury|harm|burn|fall|exposure|strain|cut|impact|ill|damage|shock|fire|spill|crush|slip|trip|control|ppe|guard|training|supervision|isolation)/i.test(harm2+' '+controls2))continue;
    var key2=hazard2.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
    if(rows.some(function(r){return (r._key||'')===key2||(r.hazard||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()===key2;}))continue;
    rows.push({_key:key2,task:hazard2,hazard:hazard2,harm:harm2,who:'Workers / affected persons',rs:raGuessRiskSeverity(hazard2+' '+harm2),rop:raGuessRiskProbability(hazard2+' '+harm2),controls:controls2,hoc_level:/guard|ventilation|isolation|barrier|interlock/i.test(controls2)?'engineering':'administrative',res_s:Math.max(1,raGuessRiskSeverity(hazard2+' '+harm2)-1),res_p:1});
  }
  return rows.map(function(r){delete r._key;return r;});
}
function raApplyImportedPdf(text,fileName){
  var rows=raExtractRowsFromText(text);
  var ramsName=document.getElementById('ra-rams-name'); if(ramsName)setSelectValueWithFallback('ra-rams-name',fileName||'Imported RA PDF');
  raRenderRamsUsed();
  var titleEl=document.getElementById('ra-title');
  if(titleEl&&!titleEl.value){
    var title=(text.match(/(?:risk assessment|rams|method statement)[^\n]{0,80}/i)||[])[0] || (fileName||'Imported risk assessment').replace(/\.pdf$/i,'').replace(/[_-]+/g,' ');
    titleEl.value=title.trim();
    var act=document.getElementById('ra-activity'); if(act)act.value=title.trim();
    var formTitle=document.getElementById('ra-form3title'); if(formTitle)formTitle.textContent=title.trim();
  }
  var scope=document.getElementById('ra-scope'); if(scope&&!scope.value)scope.value=text.replace(/\s+/g,' ').substring(0,700);
  if(rows.length){
    if(raEditingType==='dynamic')raSwitchFormType('baseline');
    if(raEditingType==='task')rows.forEach(function(r){raTaskAddRow({task:r.task||r.hazard,hazard:r.hazard,harm:r.harm,rs:r.rs,rop:r.rop,controls:r.controls,res_s:r.res_s,res_p:r.res_p});});
    else rows.forEach(function(r){raBaselineAddRow(r);});
    raFormTab('hazards', document.getElementById('ra-ftab-hazards'));
  }
  var el=document.getElementById('ra-rams-status');
  if(el)el.innerHTML='<div style="padding:10px 12px;background:#f0fdf4;border-radius:8px;font-size:12px;color:#166534;margin-bottom:8px"><strong>PDF analysed:</strong> '+escH(fileName||'document')+'<br><span style="font-size:11px;color:#166534">'+rows.length+' structured row'+(rows.length!==1?'s':'')+' extracted into the '+(raEditingType==='task'?'task-based':'hazard')+' table. Review wording, ratings and controls before saving.</span></div>';
}
async function raHandleRAMSUpload(input){
  var file=input?.files?.[0];if(!file)return;
  var ramsName=document.getElementById('ra-rams-name'); if(ramsName)setSelectValueWithFallback('ra-rams-name',file.name);
  var urlField=document.getElementById('ra-rams-url');
  await new Promise(function(resolve){
    var rd=new FileReader();
    rd.onload=function(){if(urlField)urlField.value=rd.result;resolve();};
    rd.onerror=function(){resolve();};
    rd.readAsDataURL(file);
  });
  raRenderRamsUsed();
  var el=document.getElementById('ra-rams-status');
  if(el)el.innerHTML='<div style="padding:8px 12px;background:#EFF6FF;border-radius:8px;font-size:12px;color:#185FA5;margin-bottom:8px">Attachment loaded. Reading '+escH(file.name)+'...</div>';
  if(!/\.pdf$/i.test(file.name)){
    if(el)el.innerHTML='<div style="padding:8px 12px;background:#FEF9EC;border-radius:8px;font-size:12px;color:#854F0B;margin-bottom:8px">'+escH(file.name)+' attached for preview. Automatic reading is available for PDF files; save the RA to keep this attachment.</div>';
    return;
  }
  try{
    if(!window.pdfjsLib)throw new Error('PDF reader is not loaded. Check your internet connection and try again.');
    if(window.pdfjsLib.GlobalWorkerOptions)window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    var pdf=await window.pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;
    var lines=[];
    for(var p=1;p<=pdf.numPages;p++){
      var page=await pdf.getPage(p), content=await page.getTextContent();
      var lastY=null,line='';
      content.items.forEach(function(item){
        var y=Math.round(item.transform[5]);
        if(lastY!==null&&Math.abs(y-lastY)>4){if(line.trim())lines.push(line.trim());line='';}
        line+=(line?' ':'')+item.str;lastY=y;
      });
      if(line.trim())lines.push(line.trim());
      if(el)el.innerHTML='<div style="padding:8px 12px;background:#EFF6FF;border-radius:8px;font-size:12px;color:#185FA5;margin-bottom:8px">Reading page '+p+' of '+pdf.numPages+'...</div>';
    }
    raApplyImportedPdf(lines.join('\n'),file.name);
  }catch(e){
    if(el)el.innerHTML='<div style="padding:8px 12px;background:#FCEBEB;border-radius:8px;font-size:12px;color:#A32D2D;margin-bottom:8px">PDF import failed: '+escH(e.message)+'</div>';
    toast(actionErrorMessage('Import RA PDF','Risk Assessment',e),false);
  }
}

