async function raUploadCompanyTemplate(file){
  if(!file)return;
  if(!isMgr()){toast('Only HSE managers/admins can upload RA templates',false);return;}
  if(!prof?.company_id){toast('No company linked',false);return;}
  if(file.size>50*1024*1024){toast('File too large - max 50 MB',false);return;}
  var title=await appPrompt({title:'Company RA template',message:'Template title',value:(file.name||'Company RA Template').replace(/\.[^.]+$/,''),placeholder:'e.g. Company Task Risk Assessment Template'});
  if(!title||!title.trim())return;
  var desc=await appPrompt({title:'Company RA template',message:'Short description / when to use it',placeholder:'e.g. Default template required by the client for all task RAs',multiline:true});
  try{
    var path=prof.company_id+'/ra-templates/'+Date.now()+'_'+dcSanitiseName(file.name);
    var r=await fetch(SB+'/storage/v1/object/'+DC_BUCKET+'/'+path.split('/').map(encodeURIComponent).join('/'),{
      method:'POST',
      headers:{Authorization:'Bearer '+tok,apikey:KEY,'Content-Type':file.type||dcMimeFromName(file.name),'x-upsert':'true'},
      body:file
    });
    if(!r.ok){throw new Error(await r.text()||('HTTP '+r.status));}
    var publicUrl=SB+'/storage/v1/object/public/'+DC_BUCKET+'/'+path;
    var body={
      company_id:ccid(),title:title.trim(),document_type:'risk_assessment',doc_type:'risk_assessment',
      category:'Company RA Template',description:(desc||'').trim()||'Company risk assessment template',
      tags:['RA_TEMPLATE','Risk Assessment','Template'],version:'1.0',doc_version:'1.0',
      file_url:publicUrl,file_name:file.name,file_size:file.size,file_mime:file.type||dcMimeFromName(file.name),file_path:path,
      issue_date:new Date().toISOString().slice(0,10),effective_date:new Date().toISOString().slice(0,10),review_interval_months:12,
      controlled_copy:true,is_controlled:true,approval_status:'approved',status:'approved',
      author:prof?.full_name||prof?.email||null,owner:prof?.full_name||prof?.email||null,doc_owner:prof?.full_name||prof?.email||null,
      created_by:prof?.id||null,updated_at:new Date().toISOString()
    };
    var res=await api('/documents',{m:'POST',p:'return=representation',b:body});
    if(res?.[0]?.id){
      var ref='RA-TPL-'+new Date().getFullYear()+'-'+String((raCompanyTemplates.length||0)+1).padStart(3,'0');
      await api('/documents?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{doc_ref:ref,reference_no:ref}});
      res[0].doc_ref=ref;res[0].reference_no=ref;
    }
    toast('Company RA template uploaded');
    await raLoadCompanyTemplates();
    libRenderTemplates();
    raRenderCompanyTemplateCards();
  }catch(e){toast(actionErrorMessage('Upload RA template','Risk Assessment',e),false);}
}

function raPreviewCompanyTemplate(id){
  var t=raCompanyTemplates.find(function(x){return x.id===id;});
  if(!t){toast('Template not found',false);return;}
  if(typeof dcOpenViewer==='function')dcOpenViewer(t);
  else if(t.file_url)window.open(t.file_url,'_blank');
}

async function raDeleteCompanyTemplate(id){
  if(!isMgr()){toast('Only HSE managers/admins can remove templates',false);return;}
  var t=raCompanyTemplates.find(function(x){return x.id===id;});
  if(!t)return;
  if(!(await appConfirmAction({title:'Remove RA template',message:'Remove this company RA template from active use?',detail:'The document record will be withdrawn, not permanently deleted, so audit history is retained.',confirmText:'Withdraw template',cancelText:'Cancel'})))return;
  try{
    await api('/documents?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{approval_status:'withdrawn',status:'draft',updated_at:new Date().toISOString()}});
    toast('RA template withdrawn');
    await raLoadCompanyTemplates();
    libRenderTemplates();
    raRenderCompanyTemplateCards();
  }catch(e){toast(actionErrorMessage('Withdraw RA template','Risk Assessment',e),false);}
}

