function raSpecificNew(kind){
  var cfg=RA_SPECIFIC_CFG[kind];if(!cfg)return;
  document.getElementById('ra-list-view').style.display='none';
  document.getElementById('ra-new-panel').style.display='none';
  document.getElementById('ra-form3view').style.display='none';
  var mf=document.getElementById('ra-manual-form');if(mf)mf.style.display='none';
  var panel=document.getElementById('ra-specific-form');if(panel)panel.style.display='block';
  document.getElementById('sp-kind').value=kind;
  document.getElementById('sp-title').value='';
  document.getElementById('sp-location').value='';
  document.getElementById('sp-dept').value='';
  document.getElementById('sp-context').value='';
  document.getElementById('sp-controls').value='';
  document.getElementById('sp-assessed-by').value=(typeof prof!=='undefined'&&(prof.full_name||prof.email))||'';
  document.getElementById('sp-heading').textContent=cfg.label+' Builder';
  document.getElementById('sp-icon').className='ti '+cfg.icon;
  document.getElementById('sp-hero').style.background='linear-gradient(135deg,'+cfg.accent+',#1D9E75)';
  document.getElementById('sp-accent-title').style.color=cfg.accent;
  var fields=document.getElementById('sp-factor-fields');
  fields.innerHTML=cfg.factors.map(function(f){
    return '<div class="form3group"><label class="form3label">'+escH(f[0])+'</label><select id="'+f[1]+'" data-auris-generated-onchange="g0131">'+f[2].map(function(o){return '<option value="'+o[0]+'">'+escH(o[1])+'</option>';}).join('')+'</select></div>';
  }).join('');
  raSpecificUpdatePreview();
}

function raSpecificScore(){
  var kind=document.getElementById('sp-kind')?.value||'fire';
  var cfg=RA_SPECIFIC_CFG[kind];
  var score=0;
  (cfg?.factors||[]).forEach(function(f){
    var el=document.getElementById(f[1]);var idx=el?el.selectedIndex:0;
    score+=idx===0?1:idx===1?3:5;
  });
  var severity=score>=11?5:score>=8?4:3;
  var probability=score>=11?4:score>=8?3:2;
  var level=severity*probability>=20?'Critical':severity*probability>=12?'Very High':severity*probability>=6?'High':severity*probability>=3?'Medium':'Low';
  return {severity:severity,probability:probability,residualP:Math.max(1,probability-2),level:level};
}

function raSpecificUpdatePreview(){
  var box=document.getElementById('sp-risk-preview');if(!box)return;
  var s=raSpecificScore();var cfg=RL_CFG[s.level]||['#f3f4f6','#6B7280'];
  box.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap">'
    +'<div><div style="font-size:12px;color:var(--text2);font-weight:700;text-transform:uppercase">Automatic initial risk</div>'
    +'<div style="font-size:13px;color:var(--text2)">Based on the selected specific risk factors.</div></div>'
    +'<div style="background:'+cfg[0]+';color:'+cfg[1]+';padding:8px 12px;border-radius:8px;font-weight:800">S'+s.severity+' x P'+s.probability+' = '+(s.severity*s.probability)+' '+s.level+'</div>'
    +'</div>';
}

function raSpecificCreateRA(){
  var kind=document.getElementById('sp-kind')?.value||'fire';
  var cfg=RA_SPECIFIC_CFG[kind];if(!cfg)return;
  var title=(document.getElementById('sp-title')?.value||cfg.activity).trim();
  var v=function(id){return document.getElementById(id)?.value||'';};
  var rows=cfg.rows(v,raSpecificScore());
  raNew('baseline');
  var set=function(id,val){var el=document.getElementById(id);if(el)el.value=val||'';};
  set('ra-title',cfg.label+' - '+title);
  set('ra-activity',title);
  set('ra-dept',v('sp-dept'));
  set('ra-workshop',v('sp-location'));
  set('ra-assessed-by',v('sp-assessed-by'));
  var summary=(cfg.factors||[]).map(function(f){var el=document.getElementById(f[1]);return f[0]+': '+(el?.selectedOptions[0]?.textContent||'');}).join('\n');
  set('ra-scope',(v('sp-context')?v('sp-context')+'\n\n':'')+summary);
  raBaselineRender(rows);
  var tab=document.getElementById('ra-ftab-hazards');
  if(tab)raFormTab('hazards',tab);
  toast(cfg.label+' generated. Review the table, then save or submit.');
}

