// -- Revision Control ----------------------------------------------------------
async function raArchiveCurrentRevision(snapshot, notes){
  if(!raEditingId)return;
  var snap=snapshot||raAllData.find(function(r){return r.id===raEditingId;})||{};
  try{
    await api('/ra_revisions',{m:'POST',p:'return=minimal',b:{
      company_id:ccid(),
      ra_id:raEditingId,
      revision:parseInt(snap.revision||raCurrentRevision||1)||1,
      snapshot:snap,
      changed_by:prof?.full_name||prof?.email||'User',
      change_notes:notes||'Revision created'
    }});
  }catch(e){
    console.warn('[RA] Could not archive previous revision:',e.message);
  }
}

async function raCreateRevision(){
  if(!raEditingId)return;
  if(!workflowCanMutate('risk','risk assessments'))return;
  var x=raAllData.find(r=>r.id===raEditingId)||{};
  if(controlledStatusIsLocked(x.status)&&!canAdministerControlledRecord()){
    toast('This RA is locked. Admin/HSE Manager must release it before creating a revision.',false);
    return;
  }
  var notes=document.getElementById('ra-rev-notes')?.value?.trim();
  if(!notes){toast('Please enter revision notes describing what changed',false);return;}
  var oldRev=parseInt(x.revision||raCurrentRevision||1)||1;
  var newRev=oldRev+1;
  try{
    await raArchiveCurrentRevision(x,notes);
    var body={
      revision:newRev,
      status:'draft',
      revision_notes:notes,
      rejection_reason:null,
      reviewed_by:null,
      approved_by:null,
      ra_sign_reviewer:null,
      ra_sign_reviewer_date:null,
      ra_sign_approver:null,
      ra_sign_approver_date:null,
      updated_at:new Date().toISOString()
    };
    await api('/risk_assessments?id=eq.'+raEditingId,{m:'PATCH',p:'return=minimal',b:body});
    Object.assign(x,body);
    raCurrentRevision=newRev;
    var st=document.getElementById('ra-status-sel');if(st)st.value='draft';
    document.getElementById('ra-rev-badge').textContent='Rev '+newRev;
    fillPersonSelect('ra-reviewed-by','');
    fillPersonSelect('ra-approved-by','');
    fillPersonSelect('ra-sign-reviewer','');
    fillPersonSelect('ra-sign-approver','');
    var rd=document.getElementById('ra-sign-reviewer-date');if(rd)rd.value='';
    var ad=document.getElementById('ra-sign-approver-date');if(ad)ad.value='';
    controlledApplyFormLock('ra-form3view','ra-controlled-lock-note',x,'Risk assessment');
    raRenderWorkflowBar(x);
    toast('New editable revision created - Rev '+newRev);
    raLoadRevisions();
  }catch(e){toastActionError('Create risk assessment revision','Risk Assessment',e);}
}

async function raLoadRevisions(){
  var el=document.getElementById('ra-revisions-list');if(!el)return;
  if(!raEditingId){el.innerHTML='<div style="color:var(--text2);font-size:12px;padding:10px">Save the RA first to track revisions</div>';return;}
  try{
    var d=await api('/ra_revisions?ra_id=eq.'+raEditingId+'&order=revision.desc'+cf());
    if(!d||!d.length){el.innerHTML='<div style="color:var(--text2);font-size:12px;padding:10px 0">No previous revisions - current is Rev 1 (original)</div>';return;}
    var h='<div style="padding:10px 12px;border:1px solid #BBF7D0;border-radius:8px;background:#F0FDF4;color:#166534;font-size:12px;margin-top:10px;margin-bottom:10px"><strong>Current version:</strong> Rev '+escH(raCurrentRevision||1)+' is the live editable record. Previous versions below are kept for audit traceability.</div>';
    h+='<div style="display:flex;flex-direction:column;gap:8px;margin-top:12px">';
    d.forEach(function(r){
      h+='<div style="padding:10px 14px;border:1px solid var(--border);border-radius:8px;background:#f9fafb">'
        +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:4px">'
        +'<span style="font-weight:700;font-family:monospace;color:#185FA5">Rev '+r.revision+'</span>'
        +'<span style="font-size:11px;color:var(--text2)">'+new Date(r.created_at).toLocaleDateString('en-GB')+'</span>'
        +'<span style="font-size:11px;color:var(--text2)">-</span>'
        +'<span style="font-size:11px;color:var(--text2)">'+escH(r.changed_by||'-')+'</span>'
        +'</div>'
        +'<div style="font-size:12px;color:#374151">'+escH(r.change_notes||'No notes')+'</div>'
        +'</div>';
    });
    h+='</div>';
    if(el)el.innerHTML=h;
  }catch(e){el.innerHTML='<div style="color:var(--text2);font-size:12px">Could not load revisions</div>';}
}

// -- Hazard Library Search -----------------------------------------------------
async function raSearchHazardLib(){
  var q=(document.getElementById('ra-lib-search')?.value||'').trim().toLowerCase();
  var el=document.getElementById('ra-lib-results');if(!el)return;
  if(q.length<2){el.innerHTML='';return;}
  try{
    var d=await api('/hazard_library?select=*'+raLibCompanyQuery()+'&order=hazard_type&limit=30');
    libHazardData=d||[];
    if(!libHazardData.length)libHazardData=raStandardHazards();
    var filt=libHazardData.filter(function(h){
      return (h.hazard_description||'').toLowerCase().includes(q)||(h.hazard_type||'').toLowerCase().includes(q)||(h.category||'').toLowerCase().includes(q)||(h.potential_harm||'').toLowerCase().includes(q);
    }).slice(0,8);
    if(!filt.length){el.innerHTML='<div style="font-size:12px;color:var(--text2);padding:8px">No hazards found for "'+escH(q)+'"</div>';return;}
    raRenderHazardLibResults(filt);
  }catch(e){el.innerHTML='<div style="font-size:12px;color:var(--text2);padding:8px">Search error: '+escH(e.message)+'</div>';}
}

function raRenderHazardLibResults(items){
  var el=document.getElementById('ra-lib-results');if(!el)return;
  var h='<div style="border:1px solid var(--border);border-radius:8px;overflow:hidden">';
  (items||[]).forEach(function(item){
    var rl=item.default_severity&&item.default_probability?item.default_severity*item.default_probability:0;
    var rlLvl=rl>=20?'Critical':rl>=12?'Very High':rl>=6?'High':rl>=3?'Medium':'Low';
    var rlcfg=RL_CFG[rlLvl]||['#f3f4f6','#6B7280'];
    h+='<div style="padding:8px 14px;border-bottom:1px solid #f5f5f5;display:flex;align-items:center;gap:12px;background:#fff">'
      +'<div style="flex:1">'
      +'<div style="font-weight:600;font-size:12px">'+escH(item.hazard_description||'Hazard item')+'</div>'
      +'<div style="font-size:11px;color:var(--text2)">'+escH(item.category||'General')+' - '+escH(item.potential_harm||'')+'</div>'
      +'</div>'
      +(rl?'<span style="background:'+rlcfg[0]+';color:'+rlcfg[1]+';padding:1px 7px;border-radius:4px;font-size:10px;font-weight:700">'+rl+' '+rlLvl+'</span>':'')
      +'<button class="btn btn-sm btn-primary" data-auris-runtime-onclick="r0070" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([item.id]))+'"><i class="ti ti-plus"></i>Add row</button>'
      +'</div>';
  });
  h+='</div>';
  el.innerHTML=h;
}

function raLibCompanyQuery(){
  var companyId=ccid()||prof?.company_id||'';
  return companyId?'&or=(is_global.eq.true,company_id.eq.'+companyId+')':'&is_global=eq.true';
}

