async function raShowHazardLibPicker(){
  var input=document.getElementById('ra-lib-search');
  var el=document.getElementById('ra-lib-results');if(!el)return;
  if(input)input.focus();
  var q=(input?.value||'').trim();
  if(q.length>=2){raSearchHazardLib();return;}
  el.innerHTML='<div style="font-size:12px;color:var(--text2);padding:8px">Loading hazard library...</div>';
  try{
    var d=await api('/hazard_library?select=*'+raLibCompanyQuery()+'&order=category,hazard_type&limit=12');
    libHazardData=d||[];
    if(!libHazardData.length){
      libHazardData=raStandardHazards();
    }
    raRenderHazardLibResults(libHazardData);
  }catch(e){
    libHazardData=raStandardHazards();
    raRenderHazardLibResults(libHazardData);
    toast('Using standard hazard library because company library could not be loaded',false);
  }
}

async function raAddFromLibrary(libId){
  if(!libHazardData.length){
    try{var d=await api('/hazard_library?id=eq.'+libId);libHazardData=d||[];}catch(ex){}
  }
  var item=libHazardData.find(x=>x.id===libId);if(!item)return;
  var row={
    task:item.task||item.task_step||item.activity||item.category||item.hazard_type||'General activity',
    hazard:item.hazard_description,harm:item.potential_harm||'',who:'All workers',
    rs:item.default_severity||3,rop:item.default_probability||3,
    controls:item.controls||item.control_measures||item.existing_controls||'',
    further_controls:item.further_controls||item.additional_controls||item.corrective_actions||'',
    hoc_level:item.hoc_level||item.hierarchy_level||'administrative',
    res_s:item.res_s||item.residual_severity||item.default_residual_severity||item.default_severity||3,
    res_p:item.res_p||item.residual_probability||item.default_residual_probability||1,
    legal_ref:item.legal_ref||item.legal_reference||''
  };
  var type=raEditingType;
  if(type==='task')raTaskAddRow(row);
  else raBaselineAddRow(row);
  // Also fetch suggested controls
  raGetControlSuggestionsForHazard(item.hazard_type);
  toast('Hazard added from library: '+item.hazard_description.substring(0,40));
  document.getElementById('ra-lib-search').value='';
  document.getElementById('ra-lib-results').innerHTML='';
}

// -- Control Suggestions -------------------------------------------------------
async function raGetControlSuggestions(btn){
  var row=btn.closest('tr');if(!row)return;
  var hazardEl=row.querySelector('.ra-hazard');
  var hazardText=(hazardEl?.value||'').trim();if(!hazardText)return;
  var controlsEl=row.querySelector('.ra-controls');
  var hocEl=row.querySelector('.ra-hoc');
  btn.innerHTML='<i class="ti ti-loader-2 ti-spin" style="font-size:9px"></i>';
  btn.disabled=true;
  try{
    // First try local library
    var d=await api('/control_library?select=*'+raLibCompanyQuery()+'&limit=50');
    var controls=(d||[]).filter(function(c){
      return hazardText.toLowerCase().includes((c.hazard_type||'').toLowerCase())||
             (c.hazard_type||'').toLowerCase().split(' ').some(w=>hazardText.toLowerCase().includes(w));
    }).slice(0,3);
    if(controls.length&&controlsEl){
      var existing=controlsEl.value;
      var newControls=controls.map(c=>c.control_description).join('\n');
      controlsEl.value=(existing?existing+'\n':'')+newControls;
      if(hocEl&&controls[0].hierarchy_level)hocEl.value=controls[0].hierarchy_level;
      toast(controls.length+' control measures added from library');
    }else{
      // Use AI
      var txt=await callAI([{role:'user',content:'For the hazard: "'+hazardText+'"\nProvide 3 concise, practical control measures following the hierarchy of controls.\nFormat: just the 3 control measures as numbered list. No introduction.\nAlso state the hierarchy level (elimination/substitution/engineering/administrative/ppe) for the best control.'}]);
      if(txt&&controlsEl){
        var existing2=controlsEl.value;
        controlsEl.value=(existing2?existing2+'\n':'')+txt;
        toast('AI control measures suggested');
      }
    }
  }catch(e){toast(actionErrorMessage('Fetch control suggestions','Risk Assessment',e),false);}
  btn.innerHTML='<i class="ti ti-sparkles" style="font-size:9px"></i>Suggest';
  btn.disabled=false;
}

async function raGetControlSuggestionsForHazard(hazardType){
  try{
    var d=await api('/control_library?hazard_type=eq.'+encodeURIComponent(hazardType)+raLibCompanyQuery()+'&limit=5');
    if(d&&d.length){
      var rows=document.querySelectorAll('#ra-baseline-body tr, #ra-hira-body tr, #ra-task-body tr');
      var lastRow=rows[rows.length-1];
      if(lastRow){
        var el=lastRow.querySelector('.ra-controls');
        var hocEl=lastRow.querySelector('.ra-hoc');
        if(el&&!el.value){
          el.value=d.map(c=>c.control_description).join('\n');
          if(hocEl&&d[0].hierarchy_level)hocEl.value=d[0].hierarchy_level;
        }
      }
    }
  }catch(ex){}
}

