function libTab(tab, btn){
  document.querySelectorAll('[id^="lib-tab-"]').forEach(t=>t.classList.remove('active'));
  if(btn)btn.classList.add('active');
  ['hazards','controls','templates'].forEach(function(t){
    var el=document.getElementById('lib-view-'+t);if(el)el.style.display=t===tab?'block':'none';
  });
  if(tab==='hazards')libLoadHazards();
  else if(tab==='controls')libLoadControls();
  else if(tab==='templates')raLoadCompanyTemplates().then(libRenderTemplates);
}

