async function libHazardNew(){
  if(!isMgr()){toast('Only HSE managers/admins can add library hazards',false);return;}
  try{
    var category=await appPrompt({title:'Add hazard',message:'Hazard category',placeholder:'e.g. Working at height, Electrical, Chemical'});
    if(!category||!category.trim())return;
    var hazardType=await appPrompt({title:'Add hazard',message:'Hazard type / short name',placeholder:'e.g. Falls from height'});
    if(!hazardType||!hazardType.trim())return;
    var description=await appPrompt({title:'Add hazard',message:'Hazard description',placeholder:'Describe the hazard clearly...',multiline:true});
    if(!description||!description.trim())return;
    var harm=await appPrompt({title:'Add hazard',message:'Potential harm / consequences',placeholder:'e.g. Serious injury, fatality, burns...',multiline:true});
    var severity=parseInt(await appPrompt({title:'Add hazard',message:'Default severity score (1-5)',value:'3',placeholder:'1 to 5'}),10);
    var probability=parseInt(await appPrompt({title:'Add hazard',message:'Default probability score (1-5)',value:'3',placeholder:'1 to 5'}),10);
    severity=Math.min(5,Math.max(1,isNaN(severity)?3:severity));
    probability=Math.min(5,Math.max(1,isNaN(probability)?3:probability));
    await api('/hazard_library',{m:'POST',p:'return=minimal',b:{
      company_id:prof?.company_id||ccid(),
      category:category.trim(),
      hazard_type:hazardType.trim(),
      hazard_description:description.trim(),
      potential_harm:(harm||'').trim()||null,
      default_severity:severity,
      default_probability:probability,
      is_global:false,
      created_by:prof?.id||null
    }});
    toast('Hazard added to library');
    await libLoadHazards();
  }catch(e){toast(actionErrorMessage('Add hazard','Risk Assessment',e),false);}
}

function libHazardImportFile(file){
  if(!file)return;
  if(!isMgr()){toast('Only HSE managers/admins can import library hazards',false);return;}
  var reader=new FileReader();
  reader.onload=function(){
    libHazardImportText(String(reader.result||''),file.name||'hazard list');
  };
  reader.onerror=function(){toast('Could not read hazard file',false);};
  reader.readAsText(file);
}

function libSplitDelimitedLine(line,delim){
  var out=[],cur='',quote=false;
  for(var i=0;i<String(line||'').length;i++){
    var ch=line[i],next=line[i+1];
    if(ch==='"'&&quote&&next==='"'){cur+='"';i++;continue;}
    if(ch==='"'){quote=!quote;continue;}
    if(ch===delim&&!quote){out.push(cur.trim());cur='';continue;}
    cur+=ch;
  }
  out.push(cur.trim());
  return out;
}

function libDetectDelimiter(text){
  var sample=String(text||'').split(/\r?\n/).find(function(l){return l.trim();})||'';
  var choices=[',',';','\t'];
  return choices.sort(function(a,b){return libSplitDelimitedLine(sample,b).length-libSplitDelimitedLine(sample,a).length;})[0]||',';
}

function libHazardImportRows(text){
  var delim=libDetectDelimiter(text);
  var lines=String(text||'').split(/\r?\n/).map(function(l){return l.trim();}).filter(Boolean);
  if(!lines.length)return [];
  var known={category:1,hazard_type:1,hazard:1,hazard_description:1,description:1,potential_harm:1,harm:1,default_severity:1,severity:1,default_probability:1,probability:1,controls:1,further_controls:1,hoc_level:1,hierarchy_level:1,legal_ref:1,legal_reference:1};
  var first=libSplitDelimitedLine(lines[0],delim).map(function(h){return h.toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');});
  var hasHeader=first.some(function(h){return known[h];});
  var headers=hasHeader?first:['category','hazard_type','hazard_description','potential_harm','default_severity','default_probability','controls','further_controls','hoc_level','legal_ref'];
  var dataLines=hasHeader?lines.slice(1):lines;
  return dataLines.map(function(line){
    var cells=libSplitDelimitedLine(line,delim), row={};
    headers.forEach(function(h,i){row[h]=cells[i]||'';});
    var hazardDesc=row.hazard_description||row.hazard||row.description||row.hazard_type;
    var hazardType=row.hazard_type||row.hazard||row.category||'general';
    if(!hazardDesc&&!hazardType)return null;
    var sev=Math.max(1,Math.min(5,parseInt(row.default_severity||row.severity||3)||3));
    var prob=Math.max(1,Math.min(5,parseInt(row.default_probability||row.probability||3)||3));
    return {
      category:row.category||'General',
      hazard_type:hazardType,
      hazard_description:hazardDesc||hazardType,
      potential_harm:row.potential_harm||row.harm||null,
      default_severity:sev,
      default_probability:prob,
      controls:row.controls||'',
      further_controls:row.further_controls||'',
      hoc_level:String(row.hoc_level||row.hierarchy_level||'administrative').toLowerCase(),
      legal_ref:row.legal_ref||row.legal_reference||null
    };
  }).filter(Boolean);
}

async function libHazardImportText(text,label){
  if(!isMgr()){toast('Only HSE managers/admins can import library hazards',false);return;}
  var parsed=libHazardImportRows(text);
  if(!parsed.length){toast('No valid hazard rows found. Use columns: category, hazard_type, hazard_description, potential_harm, severity, probability, controls, legal_ref.',false);return;}
  var ok=await appConfirmAction({
    title:'Import hazard library',
    message:'Import '+parsed.length+' hazard row'+(parsed.length>1?'s':'')+' from '+(label||'file')+'?',
    detail:'Accepted formats: CSV, semicolon CSV or tab-separated text. Columns can include category, hazard_type, hazard_description, potential_harm, severity, probability, controls, further_controls, hoc_level and legal_ref.',
    confirmText:'Import hazards',
    cancelText:'Cancel'
  });
  if(!ok)return;
  var companyId=prof?.company_id||ccid();
  var hazards=parsed.map(function(r){
    return {
      company_id:companyId,
      category:r.category,
      hazard_type:r.hazard_type,
      hazard_description:r.hazard_description,
      potential_harm:r.potential_harm,
      default_severity:r.default_severity,
      default_probability:r.default_probability,
      is_global:false,
      created_by:prof?.id||null
    };
  });
  try{
    for(var i=0;i<hazards.length;i+=50){
      await api('/hazard_library',{m:'POST',p:'return=minimal',b:hazards.slice(i,i+50)});
    }
    var controls=[];
    parsed.forEach(function(r){
      var txt=[r.controls,r.further_controls].filter(Boolean).join('\n');
      txt.split(/\n|\|/).map(function(s){return s.trim();}).filter(Boolean).forEach(function(c){
        controls.push({company_id:companyId,hazard_type:r.hazard_type,hierarchy_level:['elimination','substitution','engineering','administrative','ppe'].includes(r.hoc_level)?r.hoc_level:'administrative',control_description:c,effectiveness:3,legal_ref:r.legal_ref,is_global:false,created_by:prof?.id||null});
      });
    });
    for(var j=0;j<controls.length;j+=50){
      await api('/control_library',{m:'POST',p:'return=minimal',b:controls.slice(j,j+50)});
    }
    toast('Imported '+hazards.length+' hazards'+(controls.length?' and '+controls.length+' controls':''));
    await libLoadHazards();
  }catch(e){toast(actionErrorMessage('Import hazards','Risk Assessment',e),false);}
}

async function libControlNew(){
  if(!isMgr()){toast('Only HSE managers/admins can add library controls',false);return;}
  try{
    var hazardType=await appPrompt({title:'Add control',message:'Related hazard type',placeholder:'e.g. Falls from height, Chemical exposure'});
    if(!hazardType||!hazardType.trim())return;
    var level=await appPrompt({title:'Add control',message:'Hierarchy level',value:'engineering',placeholder:'elimination, substitution, engineering, administrative or ppe'});
    level=String(level||'engineering').toLowerCase().trim();
    if(!['elimination','substitution','engineering','administrative','ppe'].includes(level))level='engineering';
    var description=await appPrompt({title:'Add control',message:'Control measure',placeholder:'Describe the practical control measure...',multiline:true});
    if(!description||!description.trim())return;
    var effectiveness=parseInt(await appPrompt({title:'Add control',message:'Effectiveness score (1-5)',value:'3',placeholder:'1 to 5'}),10);
    effectiveness=Math.min(5,Math.max(1,isNaN(effectiveness)?3:effectiveness));
    var legalRef=await appPrompt({title:'Add control',message:'Legal / standard reference (optional)',placeholder:'e.g. OSH Act 2005, ISO 45001'});
    await api('/control_library',{m:'POST',p:'return=minimal',b:{
      company_id:prof?.company_id||ccid(),
      hazard_type:hazardType.trim(),
      hierarchy_level:level,
      control_description:description.trim(),
      effectiveness:effectiveness,
      legal_ref:(legalRef||'').trim()||null,
      is_global:false,
      created_by:prof?.id||null
    }});
    toast('Control measure added to library');
    await libLoadControls();
  }catch(e){toast(actionErrorMessage('Add control','Risk Assessment',e),false);}
}

