// -- AI-Assisted RA Generation -------------------------------------------------
function raRenderAISuggestions(rows){
  var el=document.getElementById('ra-ai-output');if(!el)return;
  var h='<div style="margin-top:10px;border:2px solid #8B5CF6;border-radius:10px;overflow:hidden">'
    +'<div style="padding:8px 14px;background:#8B5CF6;color:#fff;display:flex;justify-content:space-between;align-items:center">'
    +'<span style="font-size:12px;font-weight:700">AI Generated '+rows.length+' Hazard Rows</span>'
    +'<button class="btn btn-sm" style="background:rgba(255,255,255,.2);color:#fff;border-color:rgba(255,255,255,.3)" data-auris-named-action="ra-add-all-suggestions">Add all to RA</button>'
    +'</div>';
  rows.forEach(function(r,i){
    var rr=(r.rs||1)*(r.rop||1);
    var rl=raRiskLevelFromFactors(r.rs||1,r.rop||1);
    var rlcfg=RL_CFG[rl]||['#f3f4f6','#6B7280'];
    var hocCfg={elimination:'#065F46',substitution:'#1D9E75',engineering:'#185FA5',administrative:'#EF9F27',ppe:'#E24B4A'};
    h+='<div style="padding:10px 14px;border-bottom:1px solid #f3e8ff;background:'+(i%2===0?'#fff':'#fdf4ff')+'">'
      +'<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap;margin-bottom:6px">'
      +'<div><div style="font-weight:700;font-size:13px">'+escH(r.hazard||'-')+'</div>'
      +'<div style="font-size:12px;color:var(--text2)">'+escH(r.harm||'')+(r.who?' - '+escH(r.who):'')+'</div></div>'
      +'<div style="display:flex;gap:6px;align-items:center">'
      +'<span style="background:'+rlcfg[0]+';color:'+rlcfg[1]+';padding:2px 8px;border-radius:4px;font-size:11px;font-weight:700">'+rr+' '+rl+'</span>'
      +(r.hoc_level?'<span style="background:'+( hocCfg[r.hoc_level]||'#6B7280')+'20;color:'+(hocCfg[r.hoc_level]||'#6B7280')+';padding:2px 8px;border-radius:4px;font-size:10px;font-weight:600;text-transform:capitalize">'+r.hoc_level+'</span>':'')
      +'<button class="btn btn-sm" style="background:#8B5CF6;color:#fff;border-color:#8B5CF6;font-size:10px;padding:2px 8px" data-auris-runtime-onclick="r0071" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([i]))+'"><i class="ti ti-plus"></i>Add</button>'
      +'</div></div>'
      +'<div style="font-size:11px;color:#374151;background:#faf5ff;padding:6px 8px;border-radius:6px">'+escH(r.controls||'')+'</div>'
      +(r.further_controls?'<div style="font-size:11px;color:#374151;background:#fff7ed;padding:6px 8px;border-radius:6px;margin-top:5px"><b>Further controls:</b> '+escH(r.further_controls)+'</div>':'')
      +((r.action_by||r.target_date)?'<div style="font-size:11px;color:#334155;background:#eff6ff;padding:6px 8px;border-radius:6px;margin-top:5px"><b>Action:</b> '+escH(r.action_by||'To assign')+(r.target_date?' &middot; Target '+escH(r.target_date):'')+'</div>':'')
      +(r.legal_ref?'<div style="font-size:10px;color:#185FA5;margin-top:4px"><i class="ti ti-book" style="font-size:9px"></i> '+escH(r.legal_ref)+'</div>':'')
      +'</div>';
  });
  h+='</div>';
  el.innerHTML=h;
  // Store suggestions globally for single-add
  window._raAISuggestions=rows;
}

function raAddAllAISuggestions(rows){
  rows.forEach(function(r){
    if(raEditingType==='task')raTaskAddRow(r);else raBaselineAddRow(r);
  });
  toast('All '+rows.length+' AI rows added to RA - review and customise');
  raFormTab('hazards', document.getElementById('ra-ftab-hazards'));
}

function raAddSingleAISuggestion(idx){
  var rows=window._raAISuggestions||[];
  var r=rows[idx];if(!r)return;
  if(raEditingType==='task')raTaskAddRow(r);else raBaselineAddRow(r);
  toast('Row added: '+( r.hazard||'').substring(0,40));
  raFormTab('hazards', document.getElementById('ra-ftab-hazards'));
}

// Override legacy RA AI generator to use the secure AURIS AI proxy.
function raParseAIRows(text){
  var raw=String(text||'').trim();
  if(!raw)return [];
  raw=raw.replace(/```json\s*/gi,'').replace(/```\s*/g,'').trim();
  var candidates=[raw];
  var arrStart=raw.indexOf('['), arrEnd=raw.lastIndexOf(']');
  if(arrStart!==-1&&arrEnd>arrStart)candidates.push(raw.slice(arrStart,arrEnd+1));
  var objStart=raw.indexOf('{'), objEnd=raw.lastIndexOf('}');
  if(objStart!==-1&&objEnd>objStart)candidates.push(raw.slice(objStart,objEnd+1));
  for(var i=0;i<candidates.length;i++){
    try{
      var parsed=JSON.parse(candidates[i]);
      var rows=Array.isArray(parsed)?parsed:
        (Array.isArray(parsed.rows)?parsed.rows:
        (Array.isArray(parsed.hazards)?parsed.hazards:
        (Array.isArray(parsed.risk_assessment)?parsed.risk_assessment:
        (Array.isArray(parsed.riskAssessment)?parsed.riskAssessment:
        (Array.isArray(parsed.items)?parsed.items:
        (Array.isArray(parsed.data)?parsed.data:[]))))));
      if(rows.length)return rows.map(raNormalizeAIRow).filter(function(r){return r.hazard||r.harm||r.controls||r.further_controls;});
    }catch(_){}
  }
  return [];
}
function raAIDueDate(days){
  var d=new Date();
  d.setDate(d.getDate()+(parseInt(days,10)||0));
  return d.toISOString().slice(0,10);
}
function raAIResolveTargetDate(value, urgency){
  var v=String(value||'').trim();
  if(/^\d{4}-\d{2}-\d{2}$/.test(v))return v;
  var u=String(urgency||v||'').toLowerCase().replace(/[^a-z0-9]+/g,'_');
  if(u.includes('before')||u.includes('start')||u.includes('immediate')||u.includes('today'))return raAIDueDate(0);
  if(u.includes('7')||u.includes('week'))return raAIDueDate(7);
  if(u.includes('14')||u.includes('fortnight')||u.includes('two_week'))return raAIDueDate(14);
  if(u.includes('30')||u.includes('month'))return raAIDueDate(30);
  return '';
}
function raNormalizeAIRow(r){
  r=r||{};
  var rs=parseInt(r.rs??r.severity??r.initial_severity??3)||3;
  var rop=parseInt(r.rop??r.probability??r.likelihood??r.initial_probability??3)||3;
  var resS=parseInt(r.res_s??r.residual_severity??r.residual_s??rs)||rs;
  var resP=parseInt(r.res_p??r.residual_probability??r.residual_likelihood??r.residual_p??1)||1;
  function clamp(n){return Math.max(1,Math.min(5,parseInt(n)||1));}
  return {
    task:r.task||r.activity||r.task_step||r.step||'',
    hazard:r.hazard||r.hazard_description||r.task_step||'',
    harm:r.harm||r.consequence||r.potential_harm||'',
    who:r.who||r.persons_at_risk||r.exposed_persons||'',
    rs:clamp(rs),
    rop:clamp(rop),
    controls:Array.isArray(r.controls)?r.controls.join('; '):(r.controls||r.control_measures||r.existing_controls||''),
    further_controls:Array.isArray(r.further_controls||r.further_actions||r.additional_controls)?(r.further_controls||r.further_actions||r.additional_controls).join('; '):(r.further_controls||r.further_actions||r.additional_controls||r.action_required||''),
    hoc_level:String(r.hoc_level||r.hierarchy||r.control_type||'administrative').toLowerCase().replace(/\s+/g,'_'),
    res_s:clamp(resS),
    res_p:clamp(resP),
    action_by:r.action_by||r.responsible||r.owner||r.assigned_to||r.accountable_person||'',
    target_date:raAIResolveTargetDate(r.target_date||r.due_date||r.action_due_date,r.target_date_urgency||r.due_urgency||r.timescale),
    legal_ref:r.legal_ref||r.legal_reference||r.standard||''
  };
}
function raFallbackAIRows(prompt){
  var activity=String(prompt||'the work activity').trim()||'the work activity';
  return [
    {task:'Planning and preparation for '+activity,hazard:'Work scope, location, interfaces or SIMOPS not clearly defined',harm:'Uncontrolled work, conflicting activities, injury to workers or third parties',who:'Workers, contractors, supervisors and nearby persons',rs:4,rop:3,controls:'Confirm scope, work area, affected services, interfaces and site-specific restrictions before work starts.',further_controls:'Supervisor to complete pre-job review and communicate hold points, exclusion zones and change triggers.',hoc_level:'administrative',res_s:3,res_p:1,action_by:'Supervisor / HSE Officer',target_date:raAIDueDate(0),legal_ref:'OSH Act / safe system of work'},
    {task:'Access to work area',hazard:'Unsafe access, poor lighting, uneven ground or inadequate edge protection',harm:'Falls, slips, trips, sprains, fractures or struck-by injuries',who:'Workers and persons accessing the area',rs:4,rop:3,controls:'Use safe access routes, maintain lighting, remove trip hazards and barricade unsafe areas.',further_controls:'Inspect access before start and after changes in weather, housekeeping or site conditions.',hoc_level:'engineering',res_s:3,res_p:1,action_by:'Supervisor',target_date:raAIDueDate(0),legal_ref:'OSH Act / workplace access'},
    {task:'Set up work area for '+activity,hazard:'Work area not segregated from pedestrians, vehicles or other operations',harm:'Struck-by incident, unauthorised entry, collision or interruption to critical controls',who:'Work team, visitors and adjacent workers',rs:4,rop:3,controls:'Install barriers, signage, spotter where needed and maintain clear emergency access.',further_controls:'Use permit or site coordination meeting for high-risk or shared work areas.',hoc_level:'administrative',res_s:3,res_p:1,action_by:'Supervisor / Site Manager',target_date:raAIDueDate(0),legal_ref:'ISO 45001 cl.8.1 operational control'},
    {task:'Pre-use inspection of tools and equipment',hazard:'Defective, unsuitable or unguarded tools/equipment used for the task',harm:'Cuts, entanglement, electric shock, crush injury or equipment failure',who:'Operators and nearby persons',rs:4,rop:2,controls:'Use inspected equipment only, confirm guards, cables, accessories and ratings before use.',further_controls:'Tag out defective items and keep inspection evidence for critical equipment.',hoc_level:'engineering',res_s:3,res_p:1,action_by:'Competent person / Supervisor',target_date:raAIDueDate(0),legal_ref:'OSH Act / plant and equipment safety'},
    {task:'Manual handling during '+activity,hazard:'Heavy, awkward or repetitive lifting and carrying',harm:'Back injury, musculoskeletal strain, trapped fingers or dropped loads',who:'Workers handling materials',rs:3,rop:3,controls:'Assess load weight, use team lifts/mechanical aids, keep loads close and avoid twisting.',further_controls:'Split loads, improve storage height and brief correct handling method.',hoc_level:'engineering',res_s:2,res_p:1,action_by:'Supervisor',target_date:raAIDueDate(7),legal_ref:'Manual handling good practice'},
    {task:'Energy isolation and services check',hazard:'Unexpected energisation or contact with live electrical/mechanical services',harm:'Electric shock, burns, crush injury, fatality or asset damage',who:'Workers and maintenance personnel',rs:5,rop:2,controls:'Identify energy sources, isolate, lock/tag where applicable and verify zero energy before work.',further_controls:'Competent person to confirm isolation and record verification for high-risk work.',hoc_level:'engineering',res_s:4,res_p:1,action_by:'Competent technician',target_date:raAIDueDate(0),legal_ref:'OSH Act / control of hazardous energy'},
    {task:'Exposure control during '+activity,hazard:'Dust, fumes, chemicals, noise, vibration, heat or poor ventilation',harm:'Respiratory irritation, burns, hearing loss, heat stress or occupational illness',who:'Workers and nearby persons',rs:4,rop:3,controls:'Review SDS/task conditions, ventilate, suppress dust, limit exposure and use suitable PPE.',further_controls:'Conduct monitoring where exposure may exceed limits and substitute lower-hazard materials where practicable.',hoc_level:'substitution',res_s:3,res_p:1,action_by:'HSE Officer / Supervisor',target_date:raAIDueDate(7),legal_ref:'OSH Act / occupational health controls'},
    {task:'Working at height or near openings if applicable',hazard:'Falls from height, fragile surfaces, falling objects or dropped materials',harm:'Serious injury, fatality or injury to persons below',who:'Workers and persons below work area',rs:5,rop:2,controls:'Use suitable access equipment, edge protection, fall prevention and tool/material control.',further_controls:'Permit and rescue plan required where fall arrest or high-risk access is used.',hoc_level:'engineering',res_s:4,res_p:1,action_by:'Supervisor / HSE Manager',target_date:raAIDueDate(0),legal_ref:'Work at height requirements'},
    {task:'Performing '+activity,hazard:'Incorrect method, rushing, fatigue or deviation from agreed controls',harm:'Injury, poor workmanship, uncontrolled release of energy or unsafe condition created',who:'Work team and affected workers',rs:4,rop:3,controls:'Follow SWMS/SOP, maintain supervision, stop work if conditions change and keep communication clear.',further_controls:'Add task hold points and supervisor checks for critical steps.',hoc_level:'administrative',res_s:3,res_p:1,action_by:'Supervisor',target_date:raAIDueDate(0),legal_ref:'ISO 45001 cl.8.1 operational planning'},
    {task:'Housekeeping during and after '+activity,hazard:'Waste, tools, trailing leads or materials left in walkways',harm:'Slips, trips, fire load, blocked access or secondary incidents',who:'Work team and other site users',rs:3,rop:3,controls:'Keep work area tidy, route leads safely, remove waste progressively and protect access routes.',further_controls:'Final housekeeping check before handover and close-out.',hoc_level:'administrative',res_s:2,res_p:1,action_by:'Work team leader',target_date:raAIDueDate(0),legal_ref:'OSH housekeeping requirements'},
    {task:'Emergency arrangements for '+activity,hazard:'Emergency response, first aid, spill/fire response or rescue arrangements not confirmed',harm:'Delayed treatment, escalation of incident or environmental damage',who:'All persons affected by the task',rs:5,rop:2,controls:'Confirm first aid, emergency contacts, evacuation route, spill/fire equipment and stop-work authority.',further_controls:'Brief emergency actions during toolbox talk and assign a competent standby person for higher-risk work.',hoc_level:'administrative',res_s:4,res_p:1,action_by:'HSE Officer / Supervisor',target_date:raAIDueDate(0),legal_ref:'Emergency preparedness requirements'},
    {task:'Close-out and handover',hazard:'Area left unsafe, incomplete reinstatement or poor communication after work',harm:'Follow-on incident, exposure to residual hazards or operational disruption',who:'Client, operators and next work team',rs:3,rop:2,controls:'Inspect completed work, remove temporary controls only when safe, reinstate services and communicate residual risks.',further_controls:'Document close-out evidence, photos and outstanding actions in the action tracker.',hoc_level:'administrative',res_s:2,res_p:1,action_by:'Supervisor / Client representative',target_date:raAIDueDate(0),legal_ref:'ISO 45001 monitoring and communication'}
  ];
}
async function raAISuggest(){
  var prompt=(document.getElementById('ra-ai-prompt')?.value||'').trim();
  if(!prompt){toast('Please describe the work activity first',false);return;}
  var el=document.getElementById('ra-ai-output');
  if(el)el.innerHTML='<div style="padding:12px;background:#f3e8ff;border-radius:8px;display:flex;align-items:center;gap:10px;font-size:13px"><i class="ti ti-loader-2 ti-spin" style="color:#8B5CF6"></i>AI is generating risk assessment...</div>';
  try{
    var txt=await callAI([{role:'user',content:`For the following work activity, generate a thorough task-based risk assessment with 10-14 hazard rows.

Activity: ${prompt}

Return ONLY valid JSON array. Do not use markdown and do not add explanation.
[{"task":"...","hazard":"...","harm":"...","who":"...","controls":"...","rs":3,"rop":3,"further_controls":"...","hoc_level":"engineering","res_s":3,"res_p":1,"action_by":"Supervisor / HSE Officer","target_date_urgency":"before_work_starts","legal_ref":"..."}]

Rules:
- Cover the full job sequence: planning, access, setup, energy isolation/services, tools/equipment, materials/chemicals, manual handling, work at height if relevant, the work activity itself, environmental exposure, housekeeping, emergency arrangements and close-out.
- Include activity-specific hazards, not only generic safety phrases.
- Use separate rows for different hazards; do not combine unrelated hazards in one row.
- rs and rop are 1-5 integers (severity x probability = risk rating)
- hoc_level: elimination|substitution|engineering|administrative|ppe
- legal_ref: relevant OSH legislation or ISO standard
- controls: existing controls already in place before calculating initial risk
- further_controls: additional measures/actions needed to reduce the residual risk
- action_by: role responsible for implementing further controls, not a random personal name
- target_date_urgency: before_work_starts|same_day|within_7_days|within_14_days|within_30_days
- res_s and res_p are residual severity/probability after controls`}],
      'You are a senior HSE risk assessor preparing a professional RAMS-quality task risk assessment. Be specific, practical, conservative and complete. Return only JSON.');
    var rows=raParseAIRows(txt);
    var usedFallback=false;
    if(!Array.isArray(rows)||!rows.length){
      rows=raFallbackAIRows(prompt);
      usedFallback=true;
    }
    raRenderAISuggestions(rows);
    if(raEditingId){
      await api('/risk_assessments?id=eq.'+raEditingId,{m:'PATCH',p:'return=minimal',b:{ai_suggestions:rows,ai_generated:true,updated_at:new Date().toISOString()}});
    }
    toast((usedFallback?'AURIS generated a standard starter RA because the AI response could not be parsed. ':'AI generated ')+rows.length+' hazard rows - review and add to RA');
  }catch(e){
    var el2=document.getElementById('ra-ai-output');
    var rows=raFallbackAIRows(prompt);
    raRenderAISuggestions(rows);
    if(el2){
      el2.insertAdjacentHTML('afterbegin',
        '<div style="margin-bottom:10px;padding:10px 12px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;font-size:12px">'
        +'<b>AI unavailable.</b> AURIS created standard starter rows for review. Details: '+escH(e.message||e)+'</div>');
    }
    toast('AI unavailable - AURIS created starter RA rows for review', false);
    console.error(e);
  }
}

// Full AI RA generation from new panel
async function raAIGenerate(){
  var activity=await appPrompt({title:'Generate risk assessment',message:'Describe the work activity for AI to generate a complete risk assessment.',placeholder:'e.g. Hot work on roof structure',multiline:true});
  if(!activity||!activity.trim())return;
  raNew('baseline');
  document.getElementById('ra-activity').value=activity;
  document.getElementById('ra-title').value=activity;
  document.getElementById('ra-ai-prompt').value=activity;
  document.getElementById('ra-form3view').style.display='block';
  document.getElementById('ra-new-panel').style.display='none';
  // Switch to info tab first then run AI
  raFormTab('info', document.getElementById('ra-ftab-info'));
  setTimeout(function(){
    raFormTab('info', document.getElementById('ra-ftab-info'));
    raAISuggest();
  },300);
}

// -- Bowtie Visualisation ------------------------------------------------------
function raShowBowtie(){
  var rows=raCollectRows();
  if(!rows.length){toast('Add hazard rows first',false);return;}
  var title=document.getElementById('ra-title')?.value||document.getElementById('ra-activity')?.value||'Risk Assessment';
  // Build bowtie data
  var topEvent=rows.length?rows[0].harm||'Top Event':'Top Event';
  var threats=rows.map(r=>r.hazard||'Hazard').slice(0,5);
  var consequences=rows.map(r=>r.harm||'Harm').slice(0,5);
  var barriers=rows.map(r=>(r.controls||'').split('\n')[0]||'Control').slice(0,5);
  // Simple SVG bowtie
  var svgWidth=900;var svgH=500;
  var cx=svgWidth/2;var cy=svgH/2;
  var leftX=80;var rightX=svgWidth-80;
  var svg='<svg viewBox="0 0 '+svgWidth+' '+svgH+'" xmlns="http://www.w3.org/2000/svg" style="width:100%;border-radius:8px;background:#1a2744">';
  // Title
  svg+='<text x="'+cx+'" y="30" text-anchor="middle" fill="#fff" font-size="14" font-weight="700">'+escH(title)+' - Bowtie Diagram</text>';
  // Central top event
  svg+='<ellipse cx="'+cx+'" cy="'+cy+'" rx="70" ry="35" fill="#E24B4A" stroke="#fff" stroke-width="2"/>';
  svg+='<text x="'+cx+'" y="'+(cy-5)+'" text-anchor="middle" fill="#fff" font-size="11" font-weight="700">TOP EVENT</text>';
  svg+='<text x="'+cx+'" y="'+(cy+10)+'" text-anchor="middle" fill="#fff" font-size="9">'+escH(topEvent.substring(0,25))+'</text>';
  // Left: threats (causes)
  threats.forEach(function(t,i){
    var y=svgH*0.2+i*(svgH*0.6/(threats.length||1));
    svg+='<line x1="'+leftX+'" y1="'+y+'" x2="'+(cx-70)+'" y2="'+cy+'" stroke="#EF9F27" stroke-width="2" stroke-opacity="0.7"/>';
    svg+='<rect x="'+( leftX-60)+'" y="'+(y-14)+'" width="120" height="28" rx="4" fill="#EF9F27" opacity="0.9"/>';
    svg+='<text x="'+leftX+'" y="'+(y-2)+'" text-anchor="middle" fill="#fff" font-size="9" font-weight="600">THREAT</text>';
    svg+='<text x="'+leftX+'" y="'+(y+10)+'" text-anchor="middle" fill="#fff" font-size="8">'+escH(t.substring(0,20))+'</text>';
    // Barrier
    var bx=(leftX+(cx-70))/2;
    if(barriers[i]){
      svg+='<rect x="'+(bx-35)+'" y="'+(cy+(y-cy)*0.5-12)+'" width="70" height="24" rx="4" fill="#185FA5" opacity="0.9"/>';
      svg+='<text x="'+bx+'" y="'+(cy+(y-cy)*0.5-2)+'" text-anchor="middle" fill="#fff" font-size="8">'+escH(barriers[i].substring(0,15))+'</text>';
    }
  });
  // Right: consequences
  consequences.forEach(function(c,i){
    var y=svgH*0.2+i*(svgH*0.6/(consequences.length||1));
    svg+='<line x1="'+(cx+70)+'" y1="'+cy+'" x2="'+rightX+'" y2="'+y+'" stroke="#DC2626" stroke-width="2" stroke-opacity="0.7"/>';
    svg+='<rect x="'+(rightX-60)+'" y="'+(y-14)+'" width="120" height="28" rx="4" fill="#DC2626" opacity="0.9"/>';
    svg+='<text x="'+rightX+'" y="'+(y-2)+'" text-anchor="middle" fill="#fff" font-size="9" font-weight="600">CONSEQUENCE</text>';
    svg+='<text x="'+rightX+'" y="'+(y+10)+'" text-anchor="middle" fill="#fff" font-size="8">'+escH(c.substring(0,20))+'</text>';
    // Recovery barrier
    var rx2=(rightX+(cx+70))/2;
    if(barriers[i]){
      svg+='<rect x="'+(rx2-35)+'" y="'+(cy+(y-cy)*0.5-12)+'" width="70" height="24" rx="4" fill="#1D9E75" opacity="0.9"/>';
      svg+='<text x="'+rx2+'" y="'+(cy+(y-cy)*0.5+2)+'" text-anchor="middle" fill="#fff" font-size="8">RECOVERY</text>';
    }
  });
  // Legend
  svg+='<rect x="20" y="'+( svgH-60)+'" width="100" height="20" rx="4" fill="#EF9F27"/><text x="70" y="'+(svgH-46)+'" text-anchor="middle" fill="#fff" font-size="10">Threats (causes)</text>';
  svg+='<rect x="20" y="'+(svgH-35)+'" width="100" height="20" rx="4" fill="#185FA5"/><text x="70" y="'+(svgH-21)+'" text-anchor="middle" fill="#fff" font-size="10">Prevention barriers</text>';
  svg+='<rect x="'+(svgWidth-120)+'" y="'+(svgH-60)+'" width="100" height="20" rx="4" fill="#DC2626"/><text x="'+(svgWidth-70)+'" y="'+(svgH-46)+'" text-anchor="middle" fill="#fff" font-size="10">Consequences</text>';
  svg+='<rect x="'+(svgWidth-120)+'" y="'+(svgH-35)+'" width="100" height="20" rx="4" fill="#1D9E75"/><text x="'+(svgWidth-70)+'" y="'+(svgH-21)+'" text-anchor="middle" fill="#fff" font-size="10">Recovery barriers</text>';
  svg+='</svg>';
  // Show in modal
  var modal=document.createElement('div');
  modal.style.cssText='position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,.8);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
  modal.onclick=function(e){if(e.target===modal)document.body.removeChild(modal);};
  var inner=document.createElement('div');
  inner.style.cssText='background:#fff;border-radius:12px;padding:20px;max-width:960px;width:100%;max-height:90vh;overflow:auto';
  inner.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><div style="font-size:16px;font-weight:700">Bowtie Visualisation</div><button class="btn" data-auris-generated-onclick="g0132"><i class="ti ti-x"></i>Close</button></div>'+svg;
  modal.appendChild(inner);document.body.appendChild(modal);
}

