async function jsaLoadWorkOrderOptions(selectedWO){
  var sel=document.getElementById('jsa-wo-ref');if(!sel)return;
  sel.innerHTML='<option value="">Select work order...</option>';
  try{
    var work=await api('/work_schedule?select=id,ref_number,title,status'+cf()+'&order=created_at.desc');
    (work||[]).forEach(function(w){
      var ref=w.ref_number||w.id;
      var o=document.createElement('option');
      o.value=ref;o.textContent=ref+' - '+(w.title||'Work order')+(w.status?' ['+w.status+']':'');
      sel.appendChild(o);
    });
  }catch(e){
    var fail=document.createElement('option');fail.value='';fail.textContent='Unable to load work orders';sel.appendChild(fail);
  }
  if(selectedWO){setSelectValueWithFallback('jsa-wo-ref',selectedWO);}
}
function jsaNew(){
  jsaEditingId=null;jsaSteps=[];
  ['jsa-title','jsa-location','jsa-wo-ref','jsa-job-desc','jsa-prepared-by','jsa-reviewed-by','jsa-approved-by'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.value='';
  });
  fillPersonSelect('jsa-prepared-by',prof?.full_name||personFullName(prof));fillPersonSelect('jsa-reviewed-by');fillPersonSelect('jsa-approved-by');jsaLoadWorkOrderOptions();
  var dt=document.getElementById('jsa-date');if(dt)dt.value=new Date().toISOString().slice(0,10);
  var st=document.getElementById('jsa-status');if(st)st.value='draft';
  document.getElementById('jsa-form3title').textContent='New JSA / JHA';
  document.getElementById('jsa-form3ref').textContent='JSA-AUTO';
  document.getElementById('jsa-steps-container').innerHTML='';
  document.getElementById('ra-list-view').style.display='none';
  document.getElementById('ra-new-panel').style.display='none';
  document.getElementById('ra-jsa-form').style.display='block';
  // Add first step
  jsaAddStep();
}

function jsaEdit(id){
  var x=raAllJSA.find(r=>r.id===id);if(!x)return;
  jsaEditingId=id;jsaSteps=[];
  ['jsa-title','jsa-location','jsa-wo-ref','jsa-job-desc','jsa-prepared-by','jsa-reviewed-by','jsa-approved-by'].forEach(function(fid){
    var key=fid.replace('jsa-','').replace(/-/g,'_');
    var el=document.getElementById(fid);if(el)el.value=x[key]||x[fid.replace('jsa-','')]||'';
  });
  document.getElementById('jsa-title').value=x.title||'';
  document.getElementById('jsa-location').value=x.location||'';
  document.getElementById('jsa-date').value=x.date||'';
  fillPersonSelect('jsa-prepared-by',x.prepared_by||'');
  fillPersonSelect('jsa-reviewed-by',x.reviewed_by||'');
  fillPersonSelect('jsa-approved-by',x.approved_by||'');
  document.getElementById('jsa-status').value=x.status||'draft';
  document.getElementById('jsa-job-desc').value=x.job_description||'';
  jsaLoadWorkOrderOptions(x.work_order_ref||'');
  document.getElementById('jsa-form3title').textContent='Edit JSA';
  document.getElementById('jsa-form3ref').textContent=x.jsa_ref||'-';
  document.getElementById('jsa-steps-container').innerHTML='';
  document.getElementById('ra-list-view').style.display='none';
  document.getElementById('ra-jsa-form').style.display='block';
  (x.steps||[]).forEach(function(s){jsaAddStep(s);});
}

function jsaAddStep(s){
  s=s||{};
  var container=document.getElementById('jsa-steps-container');if(!container)return;
  var idx=container.querySelectorAll('.jsa-step-card').length;
  var stepNum=idx+1;
  var card=document.createElement('div');
  card.className='jsa-step-card';
  card.style.cssText='border-bottom:1px solid #f0f0f0;padding:16px 20px;background:'+(idx%2===0?'#fff':'#fafafa');
  card.innerHTML='<div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:10px">'
    +'<div style="width:28px;height:28px;border-radius:50%;background:#6D28D9;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:12px;flex-shrink:0">'+stepNum+'</div>'
    +'<div style="flex:1"><label style="font-size:11px;font-weight:700;color:var(--text2);text-transform:uppercase;display:block;margin-bottom:4px">Task / Step '+stepNum+'</label>'
    +'<input type="text" class="jsa-task" value="'+escH2(s.task||'')+'" placeholder="Describe this task step..." style="width:100%;padding:7px 10px;border:1px solid var(--border);border-radius:8px;font-size:13px"/></div>'
    +'<button class="btn btn-sm" style="color:var(--red);flex-shrink:0" data-auris-generated-onclick="g0133"><i class="ti ti-trash"></i></button>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-left:40px">'
    +'<div><label style="font-size:11px;font-weight:700;color:#E24B4A;display:block;margin-bottom:4px"><i class="ti ti-alert-triangle" style="font-size:10px"></i> Hazards</label>'
    +'<textarea class="jsa-hazards" style="width:100%;min-height:70px;padding:6px 8px;border:1px solid var(--border);border-radius:8px;font-size:12px;resize:vertical" placeholder="What can go wrong?">'+escH(Array.isArray(s.hazards)?s.hazards.join('\n'):(s.hazards||''))+'</textarea></div>'
    +'<div><label style="font-size:11px;font-weight:700;color:#1D9E75;display:block;margin-bottom:4px"><i class="ti ti-shield" style="font-size:10px"></i> Control Measures</label>'
    +'<textarea class="jsa-controls" style="width:100%;min-height:70px;padding:6px 8px;border:1px solid var(--border);border-radius:8px;font-size:12px;resize:vertical" placeholder="How will we manage the hazards?">'+escH(Array.isArray(s.controls)?s.controls.join('\n'):(s.controls||''))+'</textarea></div>'
    +'<div><label style="font-size:11px;font-weight:700;color:#EF9F27;display:block;margin-bottom:4px"><i class="ti ti-shield-check" style="font-size:10px"></i> PPE Required</label>'
    +'<textarea class="jsa-ppe" style="width:100%;min-height:70px;padding:6px 8px;border:1px solid var(--border);border-radius:8px;font-size:12px;resize:vertical" placeholder="PPE for this step...">'+escH(Array.isArray(s.ppe)?s.ppe.join('\n'):(s.ppe||''))+'</textarea></div>'
    +'</div>';
  container.appendChild(card);
}

async function jsaAISuggestSteps(){
  var title=document.getElementById('jsa-title')?.value?.trim()||document.getElementById('jsa-job-desc')?.value?.trim();
  if(!title){toast('Please enter the job title/description first',false);return;}
  toast('AI generating JSA steps...');
  try{
    var txt=await callAI([{role:'user',content:`Generate a JSA (Job Safety Analysis) for: "${title}"
Return ONLY JSON array (no markdown):
[{"task":"step description","hazards":["hazard1","hazard2"],"controls":["control1","control2"],"ppe":["item1"]}]
Generate 4-6 logical sequential steps.`}]);
    var clean=txt.replace(/```json\n?|```\n?/g,'').trim();
    var steps=JSON.parse(clean);
    if(!Array.isArray(steps)||!steps.length)throw new Error('No steps generated');
    document.getElementById('jsa-steps-container').innerHTML='';
    steps.forEach(function(s){jsaAddStep(s);});
    toast('AI generated '+steps.length+' JSA steps - review and customise');
  }catch(e){toast(aiFriendlyError(e),false);console.error(e);}
}

async function jsaSave(){
  var title=document.getElementById('jsa-title')?.value?.trim();
  if(!title){toast('Please enter JSA title',false);return;}
  var steps=Array.from(document.querySelectorAll('.jsa-step-card')).map(function(card,i){
    return {
      step_no:i+1,
      task:card.querySelector('.jsa-task')?.value||'',
      hazards:(card.querySelector('.jsa-hazards')?.value||'').split('\n').filter(Boolean),
      controls:(card.querySelector('.jsa-controls')?.value||'').split('\n').filter(Boolean),
      ppe:(card.querySelector('.jsa-ppe')?.value||'').split('\n').filter(Boolean)
    };
  });
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var body={
    company_id:ccid(),title:title,
    job_description:g('jsa-job-desc'),location:g('jsa-location'),
    work_order_ref:g('jsa-wo-ref'),date:g('jsa-date'),
    prepared_by:g('jsa-prepared-by'),reviewed_by:g('jsa-reviewed-by'),
    approved_by:g('jsa-approved-by'),status:g('jsa-status')||'draft',
    steps:steps,revision:1,updated_at:new Date().toISOString()
  };
  try{
    if(jsaEditingId){
      await api('/jsa_records?id=eq.'+jsaEditingId,{m:'PATCH',p:'return=minimal',b:body});
      var idx=raAllJSA.findIndex(x=>x.id===jsaEditingId);
      if(idx>=0)Object.assign(raAllJSA[idx],body);
      toast('JSA updated!');
    }else{
      body.created_by=prof?.id;
      var res=await api('/jsa_records',{m:'POST',p:'return=representation',b:body});
      if(res?.[0]?.id){
        var yr=new Date().getFullYear();
        var ref=await nextCompanyRef('jsa_records','jsa_ref','JSA-'+yr+'-');
        await api('/jsa_records?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{jsa_ref:ref}});
        res[0].jsa_ref=ref;raAllJSA.unshift(res[0]);jsaEditingId=res[0].id;
        document.getElementById('jsa-form3ref').textContent=ref;
        toast('JSA saved! Ref: '+ref);
      }
    }
  }catch(e){toastActionError('Save risk assessment','Risk Assessment',e);console.error(e);}
}

function jsaFormBack(){
  document.getElementById('ra-jsa-form').style.display='none';
  document.getElementById('ra-list-view').style.display='block';
  raListTab('jsa', document.getElementById('ra-ltab-jsa'));
}

