// Add a bowtie button to the form actions when hazards tab is active
function raFormTab_withBowtie(tab, btn){
  raFormTab(tab, btn);
  var existBtn=document.getElementById('ra-bowtie-btn');
  if(tab==='hazards'&&!existBtn){
    var headerBtns=document.querySelector('#ra-form3view .card:first-child div:last-child');
    if(headerBtns){
      var bwBtn=document.createElement('button');
      bwBtn.id='ra-bowtie-btn';
      bwBtn.className='btn';
      bwBtn.style.cssText='background:rgba(255,255,255,.2);color:#fff;border-color:rgba(255,255,255,.3)';
      bwBtn.innerHTML='<i class="ti ti-arrows-split"></i>Bowtie';
      bwBtn.onclick=raShowBowtie;
      headerBtns.insertBefore(bwBtn, headerBtns.querySelector('[onclick*="raSave"]'));
    }
  }
}

