function ptwCanRecordControls(x){
  if(isMgr())return true;
  var uid=prof?.id||'';
  var uname=ptwCurrentUserName();
  return !!x&&(x.permit_issuer_id===uid||x.permit_receiver===uid||x.permit_receiver_name===uname||x.issued_by===uname);
}

function ptwValidateBeforeSave(targetStatus, body, precautions){
  if(targetStatus!=='pending_approval')return null;
  if(!body.work_description)return 'Please enter the work description before submitting.';
  if(!body.work_location)return 'Please enter the exact work location before submitting.';
  if(!body.permit_receiver_name&&!body.permit_receiver)return 'Please select the permit receiver / site supervisor.';
  if(!body.planned_start||!body.planned_end)return 'Please enter planned start and planned end dates.';
  if(new Date(body.planned_end)<=new Date(body.planned_start))return 'Planned end must be after planned start.';
  if(!body.ra_ref)return 'Please select the Risk Assessment reference before submitting.';
  var raLink=verifiedReferenceSelection('pf-ra-ref');
  if(!raLink.verified)return 'Please select a verified Risk Assessment record before submitting.';
  if(!verifiedReferenceStatusOk(raLink,['approved','active','current','completed']))return 'The selected Risk Assessment must be approved/current before permit submission.';
  var msLink=verifiedReferenceSelection('pf-ms-ref');
  if(body.method_statement_ref&&(!msLink.verified||!verifiedReferenceStatusOk(msLink,['approved','active','current','effective','published'])))return 'The selected method statement must be a verified approved/current Document Control record.';
  var unchecked=(precautions||[]).filter(function(p){return !p.checked;});
  if(unchecked.length)return 'Please confirm all required precautions before submitting for approval.';
  return null;
}

function ptwAIValue(id){
  var el=document.getElementById(id);
  return el?String(el.value||'').trim():'';
}

function ptwAISet(id,val){
  var el=document.getElementById(id);
  if(el&&val)el.value=val;
}

function ptwAISelectPPE(items){
  if(!Array.isArray(items))return;
  var known=[];
  document.querySelectorAll('#ptw-ppe-checks input[type="checkbox"]').forEach(function(cb){
    var wanted=items.some(function(p){return String(p||'').toLowerCase().includes(String(cb.value||'').toLowerCase())||String(cb.value||'').toLowerCase().includes(String(p||'').toLowerCase());});
    if(wanted){cb.checked=true;known.push(cb.value.toLowerCase());}
  });
  var extra=items.filter(function(p){return p&&!known.some(function(k){return String(p).toLowerCase().includes(k)||k.includes(String(p).toLowerCase());});});
  if(extra.length){
    var el=document.getElementById('pf-ppe-extra');
    if(el){
      var existing=String(el.value||'').trim();
      el.value=[existing,extra.join(', ')].filter(Boolean).join(existing?', ':'');
    }
  }
}

function ptwAISmartPanel(out){
  var el=document.getElementById('ptw-smart-check-panel');if(!el)return;
  var items=[];
  if(out.approval_level_required)items.push('Recommended approval level: '+out.approval_level_required);
  if(out.gas_testing_required)items.push('Gas testing required: '+(out.gas_testing_reason||'confirm atmosphere before and during the work.'));
  if(out.isolation_required)items.push('Isolation required: '+((out.isolation_points||[]).join(', ')||'define isolation points before work starts.'));
  if(out.simops_concerns&&out.simops_concerns.length)items.push('SIMOPS concerns: '+out.simops_concerns.join('; '));
  if(out.permit_conditions&&out.permit_conditions.length)items.push('Permit conditions: '+out.permit_conditions.join('; '));
  if(!items.length)return;
  el.innerHTML='<div style="padding:12px 14px;background:#F5F3FF;border:1px solid #DDD6FE;border-radius:10px;color:#4C1D95;font-size:12px">'
    +'<div style="font-weight:800;margin-bottom:8px;display:flex;align-items:center;gap:6px"><i class="ti ti-robot"></i>AURIS AI permit recommendations</div>'
    +'<ul style="margin:0;padding-left:18px;line-height:1.5">'+items.map(function(x){return '<li>'+escH(x)+'</li>';}).join('')+'</ul>'
    +'</div>';
}

async function ptwAIAssist(){
  if(typeof canUseAI==='function'&&!canUseAI()){toast('AURIS AI is restricted to authorised HSE/admin roles.',false);return;}
  var type=ptwAIValue('pf-type');
  if(!type){toast('Select a permit type first, then run AI permit assist.',false);return;}
  toast('AURIS is reviewing the permit controls...');
  var cfg=PTW_TYPE_CFG[type]||{};
  var checkedPrecautions=[];
  document.querySelectorAll('#ptw-precautions-list input[type="checkbox"]').forEach(function(cb){
    var txt=cb.closest('label')?.querySelector('span')?.textContent||cb.closest('label')?.textContent||'';
    checkedPrecautions.push({item:txt.trim(),checked:cb.checked});
  });
  var selectedPpe=[];
  document.querySelectorAll('#ptw-ppe-checks input[type="checkbox"]:checked').forEach(function(cb){selectedPpe.push(cb.value);});
  var context={
    permit_type:cfg.label||type,
    work_description:ptwAIValue('pf-desc'),
    location:ptwAIValue('pf-loc'),
    department:ptwAIValue('pf-dept'),
    priority:ptwAIValue('pf-priority'),
    risk_level:ptwAIValue('pf-risk'),
    planned_start:ptwAIValue('pf-start'),
    planned_end:ptwAIValue('pf-end'),
    ra_ref:ptwAIValue('pf-ra-ref'),
    method_statement_ref:ptwAIValue('pf-ms-ref'),
    work_order_ref:ptwAIValue('pf-wo'),
    ppe_selected:selectedPpe,
    extra_ppe:ptwAIValue('pf-ppe-extra'),
    extra_precautions:ptwAIValue('pf-precautions'),
    current_precautions:checkedPrecautions
  };
  var prompt='Review this permit-to-work draft and improve it for practical HSE control. Return strict JSON only with keys: improved_work_description string, risk_level one of low/medium/high/critical, priority one of low/medium/high/critical, ppe_required array, additional_precautions array, gas_testing_required boolean, gas_testing_reason string, isolation_required boolean, isolation_points array, approval_level_required number 1-3, simops_concerns array, permit_conditions array. Do not include markdown. Context: '+JSON.stringify(context);
  try{
    var raw=await callAI([{role:'user',content:prompt}],'You are an experienced Permit to Work controller and HSE manager. Be concise, operational, and conservative. Recommend only controls that are relevant to the described work.');
    var out=aiExtractJson(raw)||{};
    aiSetIfEmpty('pf-desc',out.improved_work_description);
    if(out.risk_level)ptwAISet('pf-risk',out.risk_level);
    if(out.priority)ptwAISet('pf-priority',out.priority);
    if(out.approval_level_required)ptwAISet('pf-approval-levels',String(Math.max(1,Math.min(3,parseInt(out.approval_level_required,10)||3))));
    ptwAISelectPPE(out.ppe_required);
    if(Array.isArray(out.additional_precautions)&&out.additional_precautions.length){
      var list=document.getElementById('ptw-precautions-list');
      if(list)list.insertAdjacentHTML('beforeend',out.additional_precautions.map(function(p){return ptwPrecautionRow(String(p||''),false);}).join(''));
      var extra=document.getElementById('pf-precautions');
      if(extra&&!String(extra.value||'').trim())extra.value=out.additional_precautions.join('\n');
    }
    ptwAISmartPanel(out);
    toast('AI permit assist completed. Review the recommendations before submitting.');
  }catch(e){
    toast('AI error: '+aiFriendlyError(e),false);
  }
}

const PTW_TYPE_CFG={
  hot_work:        {label:'Hot Work',        emoji:'*', color:'#DC2626', bg:'#FEF2F2', precautions:['Fire system confirmed functional before work starts','Protect or remove combustible materials within 10m','Fire blanket or welding screen provided where sparks or heat may spread','Suitable extinguisher placed close to the job','Gas bottles and pipework removed or protected from hot work area','Fire alarm call points and emergency routes identified','Area isolated or controlled to prevent unauthorised access','Forced ventilation provided where fumes may be generated','Permanent fire watch appointed during hot work','Continuous fire watch maintained for at least 1 hour after work','Periodic fire watch continued for up to 3 hours based on risk','Adjoining areas, voids and false floors checked for smouldering fire','Final inspection completed before permit closure']},
  confined_space:  {label:'Confined Space',  emoji:'*', color:'#7C3AED', bg:'#F5F3FF', precautions:['Space isolated from all energy and material sources','Contents drained, cleaned and residues tested where applicable','Initial atmosphere test completed by authorised gas tester','Atmosphere within safe limits before entry','Forced ventilation established where required','Continuous gas monitoring maintained during entry','Standby person remains at entry point throughout work','Standby person has reliable communication with entrants and rescue support','Rescue plan, tripod and retrieval equipment available and checked','Suitable access and egress provided and kept clear','Additional lighting suitable for the space provided','Harness and lifeline used where retrieval may be required','Maximum number of entrants defined and controlled','Maximum single-entry duration and minimum break period defined','Entry and exit times recorded for every entrant']},
  excavation:      {label:'Excavation',      emoji:'*',  color:'#92400E', bg:'#FFFBEB', precautions:['Underground services identified using drawings, scan and site checks','Buried services clearly marked before excavation starts','Rollout holes used to verify service location where required','Hand digging only within the defined service exclusion zone','Plant and equipment kept at least 600mm from known services unless authorised','Shoring, battering or benching provided where collapse risk exists','Spoil stored at a safe distance from excavation edge','Excavation fenced or barricaded to prevent falls and unauthorised access','Warning lighting provided when excavation remains open in low light','Safe access and egress provided','Exposed services supported and protected','Excavation covered or made safe if left unattended','Vehicle exclusion zone established around excavation','Utility company contacted where live services may be affected']},
  electrical_isolation:{label:'Electrical Isolation',emoji:'?',color:'#1D4ED8',bg:'#EFF6FF', precautions:['Isolation identified and confirmed at source','LOTO applied - lock AND tag on isolator','Zero voltage confirmed with calibrated meter','Stored energy released (capacitors/springs/gravity)','Permit receiver responsible for their own lock','No re-energisation until all locks removed','Electrical diagram reviewed and isolation verified']},
  loto:            {label:'LOTO',            emoji:'*', color:'#B45309', bg:'#FFFBEB', precautions:['Plant and equipment to be isolated clearly identified','All other equipment treated as live unless positively isolated','All energy sources identified including electrical, mechanical, hydraulic, pneumatic, thermal, chemical and stored energy','Each isolation point locked and tagged','Warning notices affixed to every isolation point','Stored energy released, blocked or restrained','Try-out test completed to prove zero energy','Each worker applies their own personal lock where applicable','Isolation register completed with location and method','Approval obtained before any de-isolation','Exceptions to de-isolation clearly recorded before restoring equipment']},
  work_at_height:  {label:'Work at Height',  emoji:'*', color:'#065F46', bg:'#F0FDF4', precautions:['Fragile roof, skylights and unsafe surfaces identified before access','Safe access and egress route confirmed','Edge protection installed where fall risk exists','Skylights and fragile areas secured or physically protected','Work restraint or fall arrest system selected and inspected','Fall nets, crash mats or cushions provided where required','Harness and anchor point inspected before use','Exclusion zone established below work area','Tools and materials tethered or otherwise secured','Communication method agreed between workers and standby/support persons','Weather conditions checked and work stopped in unsafe wind, rain or lightning','Rescue plan in place for fallen or stranded worker','Issuer periodic checks completed for unsafe roof or high-risk height work']},
  lifting_operation:{label:'Lifting Operation',emoji:'*',color:'#5B21B6',bg:'#F5F3FF', precautions:['Competent lifting supervisor appointed','All lifting equipment certified and in date','Slinging arrangements checked by competent person','Exclusion zone established under and around load','Load weight confirmed and within SWL','Crane/hoist daily inspection completed','Hand signals or radio communication agreed','No persons under suspended load at any time']},
  line_breaking:   {label:'Line Breaking',   emoji:'*', color:'#9F1239', bg:'#FFF1F2', precautions:['Line contents identified (substance, pressure, temperature)','Line fully depressurised and drained','Isolation verified upstream and downstream','Chemical/gas test of residual contents','PPE appropriate for line contents','Spill containment in place during breaking','Written procedure for re-connection reviewed']},
  radiation:       {label:'Radiation',       emoji:'*',  color:'#064E3B', bg:'#F0FDF4', precautions:['Radiation Protection Supervisor (RPS) notified','Controlled/supervised area boundaries established','Dosimeters worn by all personnel in area','Source activity and dose rate confirmed','No pregnant workers in controlled area','Radiation warning signs and barriers in place','Source return/storage confirmed after work']},
  chemical_handling:{label:'Chemical Handling',emoji:'*',color:'#1E3A5F',bg:'#EFF6FF', precautions:['SDS reviewed for all chemicals involved','Appropriate PPE selected based on SDS requirements','Spill containment and neutralisation materials available','Storage compatibility checked','Ventilation adequate for chemical vapours','Incompatible chemicals segregated','Emergency shower/eyewash location confirmed','Waste disposal method identified']}
};

const PTW_STATUS_CFG={
  draft:            ['#f3f4f6','#6B7280','Draft'],
  pending_approval: ['#FEF9EC','#854F0B','Pending Approval'],
  approved:         ['#EAF3DE','#3B6D11','Approved'],
  active:           ['#E6F1FB','#185FA5','Active'],
  suspended:        ['#FEF6E7','#C2410C','Suspended'],
  completed:        ['#EAF3DE','#3B6D11','Completed'],
  cancelled:        ['#f3f4f6','#6B7280','Cancelled'],
  rejected:         ['#FCEBEB','#A32D2D','Rejected']
};

// -- ENTRY POINT ---------------------------------------------------------------
async function loadPermits(){
  var addBtn=document.getElementById('ptw-new-btn');
  if(addBtn)addBtn.style.display=isMgr()?'inline-flex':'none';
  ptwSetView('list');
  await ptwLoadList();
}

function ptwSetView(view){
  ['ptw-list-view','ptw-detail-view','ptw-form3view',
   'ptw-gas-panel','ptw-isolation-panel','ptw-approval-panel',
   'ptw-closure-panel','ptw-suspension-panel'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.style.display='none';
  });
  var el=document.getElementById('ptw-'+view+'-view')||document.getElementById('ptw-'+view+'-panel');
  if(el){
    el.style.display='block';
    if(view!=='list')setTimeout(function(){try{el.scrollIntoView({block:'start',behavior:'smooth'});}catch(e){}},50);
  }
}

function ptwFilterSet(filter, btn){
  ptwActiveFilter=filter;
  document.querySelectorAll('[id^="ptw-btn-"]').forEach(function(b){
    b.style.background='';b.style.color='';b.style.borderColor='';
  });
  if(btn){btn.style.background='var(--green)';btn.style.color='#fff';btn.style.borderColor='var(--green)';}
  ptwRenderList();
}

async function ptwLoadList(){
  try{
    var d=await api('/permits?select=*'+cf()+'&order=created_at.desc');
    ptwAllData=d||[];
    // Update metrics
    var now=new Date();
    var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
    setM('ptw-m3active',ptwAllData.filter(x=>x.status==='active').length);
    setM('ptw-m3pending',ptwAllData.filter(x=>x.status==='pending_approval').length);
    setM('ptw-m3suspended',ptwAllData.filter(x=>x.status==='suspended').length);
    setM('ptw-m3completed',ptwAllData.filter(x=>x.status==='completed').length);
    setM('ptw-m3total',ptwAllData.length);
    var overdue=ptwAllData.filter(x=>['active','approved'].includes(x.status)&&x.planned_end&&new Date(x.planned_end)<now).length;
    setM('ptw-m3overdue',overdue);
    // SIMOPS check
    ptwCheckSimops();
    ptwRenderList();
  }catch(e){
    var el=document.getElementById('ptw-list');
    if(el)el.innerHTML=registerErrorHtml('register',e.message);
    console.error(e);
  }
}

function ptwRenderList(){
  var el=document.getElementById('ptw-list');if(!el)return;
  var search=(document.getElementById('ptw-search')?.value||'').toLowerCase();
  var ftype=document.getElementById('ptw-filter-type')?.value||'';
  var fstatus=document.getElementById('ptw-filter-status')?.value||'';
  var now=new Date();

  var filtered=ptwAllData.filter(function(x){
    var mFilter=ptwActiveFilter==='active'?['active','pending_approval','approved','suspended'].includes(x.status):true;
    var mSearch=!search||(x.permit_number||'').toLowerCase().includes(search)||(x.location||'').toLowerCase().includes(search)||(x.work_location||'').toLowerCase().includes(search)||(x.permit_type||'').toLowerCase().includes(search)||(x.work_description||'').toLowerCase().includes(search);
    var mType=!ftype||(x.permit_type===ftype||x.permit_type_v2===ftype);
    var mStatus=!fstatus||x.status===fstatus;
    return mFilter&&mSearch&&mType&&mStatus;
  });

  if(!filtered.length){
    el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">'
      +'<div style="font-size:40px;margin-bottom:12px">-</div>'
      +'<div style="font-weight:600;margin-bottom:8px">No permits found</div>'
      +(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0134"><i class="ti ti-plus"></i>Issue first permit</button>':'')
      +'</div>';
    return;
  }

  var h='<div class="table-scroll"><table class="data-table" style="min-width:1180px">'
    +'<thead><tr>'
    +'<th>Permit No.</th>'
    +'<th>Type</th>'
    +'<th>Work / Location</th>'
    +'<th>Issuer</th>'
    +'<th>Receiver</th>'
    +'<th>Start</th>'
    +'<th>End</th>'
    +'<th style="text-align:center">Risk</th>'
    +'<th style="text-align:center">Status</th>'
    +'<th style="text-align:center">Action</th>'
    +'</tr></thead><tbody>';
  filtered.forEach(function(x,i){
    var type=x.permit_type_v2||x.permit_type||'hot_work';
    var cfg=PTW_TYPE_CFG[type]||PTW_TYPE_CFG.hot_work;
    var sc=PTW_STATUS_CFG[x.status]||PTW_STATUS_CFG.draft;
    var isOverdue=['active','approved'].includes(x.status)&&x.planned_end&&new Date(x.planned_end)<now;
    var startStr=x.planned_start?new Date(x.planned_start).toLocaleString('en-GB'):'-';
    var endStr=x.planned_end?new Date(x.planned_end).toLocaleString('en-GB'):'-';
    var risk=x.risk_level||x.priority||'medium';
    var riskCfg={low:['#EAF3DE','#3B6D11'],medium:['#FEF9EC','#854F0B'],high:['#FEF6E7','#C2410C'],critical:['#FCEBEB','#A32D2D']}[risk]||['#f3f4f6','#6B7280'];
    h+='<tr style="background:'+(i%2?'#f9fafb':'#fff')+';border-bottom:1px solid #eef2f7;border-left:5px solid '+(isOverdue?'#A32D2D':cfg.color)+';cursor:pointer" data-id="'+x.id+'" data-auris-generated-onclick="g0135">'
      +'<td style="padding:9px 10px;font-family:monospace;font-weight:800;color:'+cfg.color+'">'+escH(x.permit_number||'DRAFT')+(isOverdue?'<div style="font-size:10px;color:#A32D2D;font-weight:800">OVERDUE</div>':'')+'</td>'
      +'<td style="padding:9px 10px"><span style="background:'+cfg.bg+';color:'+cfg.color+';padding:3px 8px;border-radius:99px;font-size:10px;font-weight:800">'+escH(cfg.label)+'</span></td>'
      +'<td style="padding:9px 10px;min-width:280px"><div style="font-weight:700;line-height:1.25">'+escH((x.work_description||'Permit work').substring(0,110))+(x.work_description&&x.work_description.length>110?'...':'')+'</div><div style="font-size:11px;color:var(--text2);margin-top:2px">'+escH(x.work_location||x.location||'-')+'</div></td>'
      +'<td style="padding:9px 10px">'+escH(x.permit_issuer_name||x.issued_by||'-')+'</td>'
      +'<td style="padding:9px 10px">'+escH(x.permit_receiver_name||x.permit_receiver||'-')+'</td>'
      +'<td style="padding:9px 10px;white-space:nowrap">'+escH(startStr)+'</td>'
      +'<td style="padding:9px 10px;white-space:nowrap">'+escH(endStr)+'</td>'
      +'<td style="padding:9px 10px;text-align:center"><span style="background:'+riskCfg[0]+';color:'+riskCfg[1]+';padding:3px 8px;border-radius:99px;font-size:10px;font-weight:800;text-transform:capitalize">'+escH(risk)+'</span></td>'
      +'<td style="padding:9px 10px;text-align:center"><span style="background:'+sc[0]+';color:'+sc[1]+';padding:3px 8px;border-radius:99px;font-size:10px;font-weight:800">'+escH(sc[2])+'</span></td>'
      +'<td style="padding:9px 10px;text-align:center"><button class="btn btn-sm" data-auris-runtime-onclick="r0072" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id]))+'"><i class="ti ti-eye"></i></button></td>'
      +'</tr>';
  });
  el.innerHTML=h+'</tbody></table></div>';
}
function ptwShowList(){
  ptwSetView('list');
  ptwRenderList();
}

// -- DETAIL VIEW ---------------------------------------------------------------
async function ptwShowDetail(id){
  var x=ptwAllData.find(function(r){return r.id===id;});
  if(!x){try{var d=await api('/permits?id=eq.'+id+cf());x=d?.[0];}catch(e){return;}}
  if(!x)return;
  ptwCurrentId=id;
  ptwSetView('detail');

  var type=x.permit_type_v2||x.permit_type||'hot_work';
  var cfg=PTW_TYPE_CFG[type]||PTW_TYPE_CFG.hot_work;
  var sc=PTW_STATUS_CFG[x.status]||PTW_STATUS_CFG.draft;

  // Banner
  var banner=document.getElementById('ptw-detail-banner');
  if(banner)banner.style.background='linear-gradient(135deg,'+cfg.color+'dd,'+cfg.color+')';
  var typeLabel=document.getElementById('ptw-detail-type-label');
  if(typeLabel)typeLabel.textContent=cfg.emoji+' '+cfg.label;
  var refEl=document.getElementById('ptw-detail-ref');
  if(refEl)refEl.textContent=displayRecordRef(x,['permit_number','permit_ref'],'PTW-DRAFT');
  var metaEl=document.getElementById('ptw-detail-meta');
  if(metaEl){
    var s=[];
    if(x.work_location||x.location)s.push('<span>'+escH(x.work_location||x.location||'')+'</span>');
    if(x.planned_start)s.push('<span>'+new Date(x.planned_start).toLocaleDateString('en-GB')+'</span>');
    if(x.planned_end)s.push('<span>To '+new Date(x.planned_end).toLocaleDateString('en-GB')+'</span>');
    metaEl.innerHTML=s.join('');
  }
  var statusBadge=document.getElementById('ptw-detail-status-badge');
  if(statusBadge)statusBadge.innerHTML='<span style="background:rgba(255,255,255,.25);color:#fff;padding:4px 12px;border-radius:99px;font-size:12px;font-weight:700">'+sc[2]+'</span>';

  // Workflow bar
  ptwRenderWorkflowBar(x);

  // Smart blocks
  ptwRenderBlocks(x);

  // Action buttons
  ptwRenderActionButtons(x);

  // Load details tab by default
  ptwDetailTab('details', document.getElementById('ptw-dtab-details'));

  // Load activity log
  ptwLoadLog(id);
}

function ptwRenderWorkflowBar(x){
  var el=document.getElementById('ptw-workflow-bar');if(!el)return;
  var steps=[
    {key:'draft',label:'Draft'},
    {key:'pending_approval',label:'Submitted'},
    {key:'approved',label:'Approved'},
    {key:'active',label:'Active'},
    {key:'completed',label:'Closed'}
  ];
  var currentIdx=steps.findIndex(function(s){return s.key===x.status;});
  if(x.status==='cancelled'||x.status==='rejected'||x.status==='suspended'){
    el.innerHTML='<span style="font-size:12px;font-weight:700;color:#C2410C">Permit is '+x.status.toUpperCase()+'</span>';
    return;
  }
  var h='<div style="display:flex;align-items:center;gap:4px;flex:1">';
  steps.forEach(function(s,i){
    var done=i<=currentIdx;
    var active=s.key===x.status;
    h+='<div style="display:flex;align-items:center;gap:4px">'
      +'<div style="padding:4px 10px;border-radius:99px;font-size:11px;font-weight:700;background:'+(active?'#185FA5':done?'#1D9E75':'#f3f4f6')+';color:'+(done?'#fff':'#9CA3AF')+'">'+s.label+'</div>'
      +(i<steps.length-1?'<div style="width:20px;height:2px;background:'+(i<currentIdx?'#1D9E75':'#e5e7eb')+';flex-shrink:0"></div>':'')
      +'</div>';
  });
  h+='</div>';
  el.innerHTML=h;
}

function ptwRenderBlocks(x){
  var el=document.getElementById('ptw-blocks-panel');if(!el)return;
  var blocks=x.blocked_reasons||[];
  if(!blocks.length){el.style.display='none';return;}
  el.style.display='block';
  var h='<div style="background:#FEF6E7;border:2px solid #EF9F27;border-radius:10px;padding:14px 18px">'
    +'<div style="font-weight:700;color:#854F0B;margin-bottom:8px"><i class="ti ti-lock"></i> Smart Blocks - Action required before permit can proceed</div>'
    +'<div style="display:flex;flex-direction:column;gap:6px">';
  blocks.forEach(function(b){
    h+='<div style="display:flex;align-items:center;gap:8px;font-size:12px;color:#78350F">'
      +'<i class="ti ti-alert-circle" style="color:#EF9F27"></i>'+escH(b)+'</div>';
  });
  h+='</div></div>';
  el.innerHTML=h;
}

function ptwRenderActionButtons(x){
  var el=document.getElementById('ptw-action-btns');if(!el)return;
  var h='';
  var btn=function(icon,label,action,col){
    return '<button class="btn" style="background:'+col+';color:#fff;border-color:'+col+'" data-auris-named-action="'+escH(action)+'"><i class="ti '+icon+'"></i>'+label+'</button>';
  };
  var canRecord=ptwCanRecordControls(x);
  var canControl=isMgr();
  if(canRecord&&['active','approved','pending_approval'].includes(x.status)){
    h+=btn('ti-flask','Gas Tests','ptw-open-gas','#065F46');
    h+=btn('ti-lock','Isolations','ptw-open-isolation','#B45309');
  }
  if(canControl&&x.status==='pending_approval')h+=btn('ti-certificate','Approve/Reject','ptw-open-approval','#185FA5');
  if(canControl&&x.status==='approved')h+=btn('ti-player-play','Activate Permit','ptw-activate','#185FA5');
  if(canControl&&x.status==='active')h+=btn('ti-circle-check','Close Permit','ptw-open-closure','#1D9E75');
  if(canControl&&['active','approved'].includes(x.status))h+=btn('ti-player-pause','Suspend/Cancel','ptw-open-suspension','#C2410C');
  if(canControl&&x.status==='suspended')h+=btn('ti-player-play','Resume Permit','ptw-resume','#185FA5');
  el.innerHTML=h;
}

function ptwDetailTab(tab, btn){
  document.querySelectorAll('[id^="ptw-dtab-"]').forEach(function(b){b.classList.remove('active');});
  if(btn)btn.classList.add('active');
  ['details','checks','gas','isolation','approval','log'].forEach(function(t){
    var el=document.getElementById('ptw-dtab-view-'+t);if(el)el.style.display=t===tab?'block':'none';
  });
  var x=ptwAllData.find(function(r){return r.id===ptwCurrentId;})||{};
  if(tab==='details')ptwRenderDetails(x);
  else if(tab==='checks')ptwRenderChecks(x);
  else if(tab==='gas')ptwRenderGasHistory(x);
  else if(tab==='isolation')ptwRenderIsolationList(x);
  else if(tab==='approval')ptwRenderApprovalStatus(x);
  else if(tab==='log')ptwLoadLog(ptwCurrentId);
}

function ptwRenderDetails(x){
  var el=document.getElementById('ptw-detail-content');if(!el)return;
  var type=x.permit_type_v2||x.permit_type||'hot_work';
  var cfg=PTW_TYPE_CFG[type]||PTW_TYPE_CFG.hot_work;
  var row=function(label,val){return '<div style="display:grid;grid-template-columns:160px 1fr;gap:4px 12px;padding:6px 0;border-bottom:1px solid #f5f5f5"><span style="font-size:12px;color:var(--text2);font-weight:500">'+escH(label)+'</span><span style="font-size:13px">'+escH(val||'-')+'</span></div>';};
  var h='<div style="display:grid;grid-template-columns:2fr 1fr;gap:14px">'
    +'<div class="card">'
    +'<div class="card-title" style="color:'+cfg.color+'">'+cfg.emoji+' '+cfg.label+' - Work Details</div>'
    +row('Description',x.work_description||x.description||x.precautions)
    +row('Location',x.work_location||x.location)
    +row('Department',x.department)
    +row('Planned start',x.planned_start?new Date(x.planned_start).toLocaleString('en-GB'):'')
    +row('Planned end',x.planned_end?new Date(x.planned_end).toLocaleString('en-GB'):'')
    +row('Permit issuer',x.permit_issuer_name||x.issued_by)
    +row('Permit receiver',x.permit_receiver_name||x.permit_receiver)
    +row('Contractor',x.contractor_name||x.contractor)
    +row('Work team',x.team_members||(Array.isArray(x.work_team)?x.work_team.join(', '):x.work_team))
    +'</div>'
    +'<div>'
    +'<div class="card" style="margin-bottom:12px;border:2px solid '+cfg.color+'">'
    +'<div class="card-title" style="color:'+cfg.color+'">Linked Refs</div>'
    +row('RA ref',x.ra_ref)
    +row('Method Statement',x.method_statement_ref||x.ms_ref)
    +row('Work Order',x.work_order_ref)
    +'</div>'
    +'<div class="card">'
    +'<div class="card-title">PPE Required</div>'
    +'<div style="font-size:13px">'+(Array.isArray(x.ppe_required)&&x.ppe_required.length?x.ppe_required.join(', '):(x.ppe||'-'))+'</div>'
    +(x.requires_weather_check?'<div style="margin-top:10px;padding:8px;background:#FEF9EC;border-radius:6px;font-size:12px;color:#854F0B"><i class="ti ti-cloud-rain"></i> Weather check required before work starts</div>':'')
    +'</div>'
    +'</div>'
    +'</div>';
  el.innerHTML=h;
}

function ptwRenderChecks(x){
  var el=document.getElementById('ptw-checks-content');if(!el)return;
  var type=x.permit_type_v2||x.permit_type||'hot_work';
  var cfg=PTW_TYPE_CFG[type]||PTW_TYPE_CFG.hot_work;
  var checks=Array.isArray(x.precautions_checklist)&&x.precautions_checklist.length?x.precautions_checklist:cfg.precautions.map(function(p){return{item:p,checked:false};});
  var h='<div class="card"><div class="card-title" style="color:'+cfg.color+'">'+cfg.emoji+' Precautions Checklist for '+cfg.label+'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:8px 12px">';
  checks.forEach(function(c,i){
    var item=typeof c==='string'?c:(c.item||c);
    var checked=typeof c==='object'&&c.checked;
    h+='<div style="display:grid;grid-template-columns:28px minmax(0,1fr);align-items:start;gap:10px;padding:10px 12px;border:1px solid '+(checked?'#BBF7D0':'var(--border)')+';border-radius:10px;background:'+(checked?'#F0FDF4':'#fff')+';min-height:54px">'
      +'<div style="width:22px;height:22px;border-radius:50%;border:2px solid '+(checked?'var(--green)':'#d1d5db')+';background:'+(checked?'var(--green)':'#fff')+';display:flex;align-items:center;justify-content:center;margin-top:1px">'
      +(checked?'<i class="ti ti-check" style="font-size:12px;color:#fff"></i>':'')+'</div>'
      +'<span style="font-size:13px;line-height:1.35;color:'+(checked?'#166534':'#1a1a1a')+';white-space:normal;overflow-wrap:anywhere">'+escH(item)+'</span>'
      +'</div>';
  });
  h+='</div></div>';
  // Suspension notes
  if(x.suspended_at)h+='<div class="card" style="margin-top:12px;border:2px solid #C2410C">'
    +'<div class="card-title" style="color:#C2410C">Suspended</div>'
    +'<div style="font-size:13px"><strong>By:</strong> '+escH(x.suspended_by||'-')+'<br><strong>Reason:</strong> '+escH(x.suspension_reason||'-')+'</div></div>';
  el.innerHTML=h;
}

function ptwRenderGasHistory(x){
  var el=document.getElementById('ptw-gas-content');if(!el)return;
  var tests=x.gas_tests||[];
  if(!tests.length){
    el.innerHTML='<div class="card"><div style="text-align:center;padding:24px;color:var(--text2)">No gas tests recorded yet.<br><button class="btn btn-primary btn-sm" style="margin-top:12px" data-auris-generated-onclick="g0136"><i class="ti ti-plus"></i>Add gas test</button></div></div>';
    return;
  }
  var h='<div class="card" style="padding:0;overflow:hidden">'
    +'<div style="padding:10px 16px;background:#065F46;color:#fff;font-weight:700;display:flex;justify-content:space-between;align-items:center">'
    +'<span>Gas Test Records</span><button class="btn btn-sm" style="background:rgba(255,255,255,.2);color:#fff;border-color:rgba(255,255,255,.3)" data-auris-generated-onclick="g0136"><i class="ti ti-plus"></i>Add test</button></div>'
    +'<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="background:#f0fdf4"><th style="padding:8px 14px;text-align:left">Date/Time</th><th style="padding:8px;text-align:center">O2%</th><th style="padding:8px;text-align:center">LEL%</th><th style="padding:8px;text-align:center">H2S ppm</th><th style="padding:8px;text-align:center">CO ppm</th><th style="padding:8px;text-align:left">Tester</th><th style="padding:8px;text-align:center">Result</th></tr></thead><tbody>';
  tests.forEach(function(t,i){
    var bg=i%2===0?'#fff':'#f9fafb';
    var result=t.result||'pass';
    var rc=result==='pass'?['#EAF3DE','#3B6D11','PASS']:result==='fail'?['#FCEBEB','#A32D2D','FAIL']:['#FEF9EC','#854F0B','BORDERLINE'];
    var o2Check=t.o2?parseFloat(t.o2):null;
    var o2Ok=!o2Check||(o2Check>=19.5&&o2Check<=23.5);
    var lelCheck=t.lel?parseFloat(t.lel):null;
    var lelOk=!lelCheck||lelCheck<10;
    h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
      +'<td style="padding:8px 14px">'+escH(t.datetime?new Date(t.datetime).toLocaleString('en-GB'):(t.date||'-'))+'</td>'
      +'<td style="padding:8px;text-align:center;font-weight:700;color:'+(o2Ok?'var(--green)':'var(--red)')+'">'+( t.o2||'-')+'</td>'
      +'<td style="padding:8px;text-align:center;font-weight:700;color:'+(lelOk?'var(--green)':'var(--red)')+'">'+( t.lel||'-')+'</td>'
      +'<td style="padding:8px;text-align:center">'+( t.h2s||'-')+'</td>'
      +'<td style="padding:8px;text-align:center">'+( t.co||'-')+'</td>'
      +'<td style="padding:8px">'+escH(t.tester||'-')+'</td>'
      +'<td style="padding:8px;text-align:center"><span style="background:'+rc[0]+';color:'+rc[1]+';padding:2px 8px;border-radius:4px;font-size:11px;font-weight:700">'+rc[2]+'</span></td>'
      +'</tr>';
  });
  h+='</tbody></table></div>';
  el.innerHTML=h;
}

function ptwRenderIsolationList(x){
  var el=document.getElementById('ptw-isolation-content');if(!el)return;
  var isos=x.isolations||[];
  if(!isos.length){
    el.innerHTML='<div class="card"><div style="text-align:center;padding:24px;color:var(--text2)">No isolation points recorded.<br><button class="btn btn-primary btn-sm" style="margin-top:12px" data-auris-generated-onclick="g0137"><i class="ti ti-lock"></i>Add isolation</button></div></div>';
    return;
  }
  var stCfg={isolated:['#EAF3DE','#3B6D11','Isolated'],'pending':['#FEF9EC','#854F0B','Pending'],'de-isolated':['#FCEBEB','#A32D2D','De-isolated']};
  var h='<div class="card" style="padding:0;overflow:hidden">'
    +'<div style="padding:10px 16px;background:#1E3A5F;color:#fff;font-weight:700;display:flex;justify-content:space-between;align-items:center">'
    +'<span>Isolation Points</span><button class="btn btn-sm" style="background:rgba(255,255,255,.2);color:#fff;border-color:rgba(255,255,255,.3)" data-auris-generated-onclick="g0137"><i class="ti ti-plus"></i>Add isolation</button></div>'
    +'<table style="width:100%;border-collapse:collapse;font-size:12px">'
    +'<thead><tr style="background:#f0f4ff"><th style="padding:8px 14px;text-align:left">Tag/ID</th><th style="padding:8px 10px;text-align:left">Description</th><th style="padding:8px 10px;text-align:left">Type</th><th style="padding:8px 10px;text-align:left">Isolated by</th><th style="padding:8px 10px;text-align:left">Verified by</th><th style="padding:8px 10px;text-align:left">Status</th></tr></thead><tbody>';
  isos.forEach(function(iso,i){
    var bg=i%2===0?'#fff':'#f9fafb';
    var sc=stCfg[iso.status]||stCfg['pending'];
    h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
      +'<td style="padding:8px 14px;font-family:monospace;font-weight:700;color:#B45309">'+escH(iso.tag||'-')+'</td>'
      +'<td style="padding:8px 10px">'+escH(iso.description||'-')+'</td>'
      +'<td style="padding:8px 10px;font-size:11px;text-transform:capitalize">'+escH((iso.type||'-').replace(/_/g,' '))+'</td>'
      +'<td style="padding:8px 10px">'+escH(iso.by||'-')+'</td>'
      +'<td style="padding:8px 10px">'+escH(iso.verified_by||'-')+'</td>'
      +'<td style="padding:8px 10px"><span style="background:'+sc[0]+';color:'+sc[1]+';padding:2px 8px;border-radius:99px;font-size:11px;font-weight:700">'+sc[2]+'</span></td>'
      +'</tr>';
  });
  h+='</tbody></table></div>';
  el.innerHTML=h;
}

function ptwRenderApprovalStatus(x){
  var el=document.getElementById('ptw-approval-content');if(!el)return;
  var levels=parseInt(x.approval_level_required)||3;
  var h='<div class="card"><div class="card-title" style="color:#185FA5">Approval Workflow - '+levels+' Level'+(levels>1?'s':'')+' Required</div>';
  var lvls=[
    {n:1,label:'Level 1 - Area Supervisor',by:x.approval_l1_by,at:x.approval_l1_at,status:x.approval_l1_status||'pending'},
    {n:2,label:'Level 2 - Department Manager',by:x.approval_l2_by,at:x.approval_l2_at,status:x.approval_l2_status||'pending'},
    {n:3,label:'Level 3 - HSE Manager',by:x.approval_l3_by,at:x.approval_l3_at,status:x.approval_l3_status||'pending'}
  ];
  h+='<div style="display:flex;flex-direction:column;gap:10px">';
  for(var i=0;i<levels;i++){
    var lv=lvls[i];
    var sc=lv.status==='approved'?['#EAF3DE','#3B6D11','Approved']:lv.status==='rejected'?['#FCEBEB','#A32D2D','Rejected']:['#FEF9EC','#854F0B','Pending'];
    h+='<div style="padding:14px;border:1px solid var(--border);border-radius:10px;background:'+(lv.status==='approved'?'#f0fdf4':lv.status==='rejected'?'#fff1f1':'#fffbf2')+'">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">'
      +'<div><div style="font-weight:700;font-size:14px">'+escH(lv.label)+'</div>'
      +(lv.by?'<div style="font-size:12px;color:var(--text2)">By: '+escH(lv.by)+(lv.at?' - '+new Date(lv.at).toLocaleDateString('en-GB'):'')+'</div>':'')+'</div>'
      +'<div style="display:flex;gap:8px;align-items:center">'
      +'<span style="background:'+sc[0]+';color:'+sc[1]+';padding:3px 10px;border-radius:99px;font-size:11px;font-weight:700">'+sc[2]+'</span>'
      +(isMgr()&&lv.status==='pending'&&x.status==='pending_approval'
        ?'<button class="btn btn-sm" style="background:var(--green);color:#fff;border-color:var(--green)" data-auris-runtime-onclick="r0073" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([lv.n]))+'"><i class="ti ti-check"></i>Approve</button><button class="btn btn-sm" style="color:var(--red);border-color:var(--red)" data-auris-runtime-onclick="r0074" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([lv.n]))+'"><i class="ti ti-x"></i>Reject</button>':'')
      +'</div></div></div>';
  }
  h+='</div></div>';
  el.innerHTML=h;
}

async function ptwLoadLog(id){
  var el=document.getElementById('ptw-log-content');if(!el)return;
  try{
    var d=await api('/permit_activity_log?permit_id=eq.'+id+'&order=performed_at.desc');
    if(!d||!d.length){el.innerHTML='<div class="card"><div style="text-align:center;padding:20px;color:var(--text2)">No activity recorded yet</div></div>';return;}
    var h='<div class="card" style="padding:0;overflow:hidden">'
      +'<div style="padding:10px 16px;background:#1a3a5c;color:#fff;font-weight:700">Activity Log</div>';
    d.forEach(function(a,i){
      var bg=i%2===0?'#fff':'#f9fafb';
      h+='<div style="padding:10px 16px;border-bottom:1px solid #f0f0f0;display:flex;gap:12px;background:'+bg+'">'
        +'<div style="font-size:11px;color:var(--text2);min-width:130px">'+new Date(a.performed_at).toLocaleString('en-GB')+'</div>'
        +'<div style="font-size:12px;font-weight:600;flex:1">'+escH(a.action||'-')+'</div>'
        +'<div style="font-size:11px;color:var(--text2)">'+escH(a.performed_by||'-')+'</div>'
        +'</div>';
    });
    h+='</div>';
    if(el)el.innerHTML=h;
  }catch(e){el.innerHTML='<div class="card"><div style="color:var(--text2);padding:12px">No activity log available</div></div>';}
}

// -- FORM - NEW/EDIT -----------------------------------------------------------
function ptwNew(){
  ptwEditingId=null;
  document.getElementById('ptw-form3title').textContent='New Permit to Work';
  document.getElementById('ptw-form3ref-display').textContent='';
  document.getElementById('ptw-del-btn').style.display='none';
  document.getElementById('ptw-type-selector').style.display='block';
  document.getElementById('ptw-form3body').style.display='none';
  document.getElementById('ptw-type-specific-form').innerHTML='';
  document.getElementById('ptw-precautions-list').innerHTML='';
  document.getElementById('ptw-smart-check-panel').innerHTML='';
  // Clear fields
  ['pf-no','pf-loc','pf-dept','pf-desc','pf-receiver','pf-receiver-manual','pf-team','pf-team3extra','pf-ra-ref','pf-ms-ref','pf-wo','pf-ppe-extra','pf-precautions'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['pf-start','pf-end'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var priority=document.getElementById('pf-priority');if(priority)priority.value='medium';
  var risk=document.getElementById('pf-risk');if(risk)risk.value='medium';
  var lvls=document.getElementById('pf-approval-levels');if(lvls)lvls.value='3';
  var weather=document.getElementById('pf-weather-check');if(weather)weather.checked=false;
  // Uncheck all PPE
  document.querySelectorAll('#ptw-ppe-checks input[type="checkbox"]').forEach(function(cb){cb.checked=false;});
  // Permit issuer is automatically captured from the logged-in user.
  ptwFillIssuerDisplay();
  ptwPopulatePeopleFields();
  var conSel=document.getElementById('pf-contractor');
  if(conSel){conSel.innerHTML='<option value="">Internal / No contractor</option>';try{api('/contractors?select=id,contractor_name&status=eq.approved'+cf()).then(function(d){(d||[]).forEach(function(c){var o=document.createElement('option');o.value=c.id;o.textContent=c.contractor_name;conSel.appendChild(o);});});}catch(ex){}}
  var woSel=document.getElementById('pf-wo');
  if(woSel){woSel.innerHTML='<option value="">None</option>';try{api('/work_schedule?select=id,title,ref_number'+cf()+'&order=planned_start.desc&limit=30').then(function(d){(d||[]).forEach(function(w){var o=document.createElement('option');o.value=w.id;o.textContent=(w.ref_number||'WO')+' - '+w.title;woSel.appendChild(o);});});}catch(ex){}}
  ptwLoadReferenceOptions();
  ptwSetView('form');
  controlledApplyFormLock('ptw-form3view','ptw-controlled-lock-note',null,'Permit');
}

function ptwSelectType(type){
  var cfg=PTW_TYPE_CFG[type];if(!cfg)return;
  document.getElementById('ptw-type-selector').style.display='none';
  document.getElementById('ptw-form3body').style.display='block';
  document.getElementById('pf-type').value=type;
  document.getElementById('pf-type-display').textContent=cfg.emoji+' '+cfg.label;
  // Build precautions
  var el=document.getElementById('ptw-precautions-list');
  ptwPreparePrecautionGrid(el);
  el.innerHTML=cfg.precautions.map(function(p){
    return ptwPrecautionRow(p,true);
  }).join('');
  // Type-specific form
  ptwBuildTypeForm(type);
  // Run smart checks
  ptwRunSmartChecks();
  // Set weather check for outdoor types
  var outdoor=['excavation','work_at_height','lifting_operation'];
  var wc=document.getElementById('pf-weather-check');if(wc)wc.checked=outdoor.includes(type);
}

function ptwTypeCardHover(el){
  var type=el.getAttribute('data-type');
  var cfg=PTW_TYPE_CFG[type];if(!cfg)return;
  el.style.background='#fff';
}

function ptwBuildTypeForm(type){
  var el=document.getElementById('ptw-type-specific-form');if(!el)return;
  var cfg=PTW_TYPE_CFG[type];if(!cfg)return;
  var formHtml='';
  if(type==='hot_work'){
    formHtml='<div class="card" style="margin-bottom:14px;border-left:4px solid #DC2626"><div class="card-title" style="color:#DC2626">Hot Work Details</div>'
      +'<div class="form3row"><div class="form3group"><label class="form3label">Type of hot work</label><select id="pf-hw-type"><option value="welding">Welding</option><option value="cutting">Cutting/grinding</option><option value="brazing">Brazing/soldering</option><option value="torch">Torch/open flame</option><option value="other">Other</option></select></div>'
      +'<div class="form3group"><label class="form3label">Fire watch duration after work</label><input type="text" id="pf-hw-firewatch" placeholder="e.g. 30 minutes after work ceases"/></div></div>'
      +'<div class="form3group"><label class="form3label">Combustible materials within 10m</label><input type="text" id="pf-hw-combustibles" placeholder="List any combustibles and control measures applied..."/></div></div>';
  } else if(type==='confined_space'){
    formHtml='<div class="card" style="margin-bottom:14px;border-left:4px solid #7C3AED"><div class="card-title" style="color:#7C3AED">Confined Space Details</div>'
      +'<div class="form3row"><div class="form3group"><label class="form3label">Space name / ID</label><input type="text" id="pf-cs-name" placeholder="e.g. Tank T-01, Sewer manhole 4"/></div>'
      +'<div class="form3group"><label class="form3label">Classification</label><select id="pf-cs-class"><option value="permit_required">Permit-required confined space</option><option value="non_permit">Non-permit confined space</option></select></div>'
      +'<div class="form3group"><label class="form3label">Standby person</label><select id="pf-cs-standby"><option value="">Select standby person...</option></select></div>'
      +'<div class="form3group"><label class="form3label">Rescue equipment</label><input type="text" id="pf-cs-rescue" placeholder="Retrieval tripod, harness, comms..."/></div></div></div>';
  } else if(type==='electrical_isolation'){
    formHtml='<div class="card" style="margin-bottom:14px;border-left:4px solid #1D4ED8"><div class="card-title" style="color:#1D4ED8">Electrical Details</div>'
      +'<div class="form3row"><div class="form3group"><label class="form3label">Voltage level</label><select id="pf-el-voltage"><option value="lv">LV (&lt;1000V)</option><option value="mv">MV (1-36kV)</option><option value="hv">HV (&gt;36kV)</option></select></div>'
      +'<div class="form3group"><label class="form3label">Circuit/Equipment ID</label><input type="text" id="pf-el-circuit" placeholder="e.g. Panel MCC-01, CB-15"/></div>'
      +'<div class="form3group"><label class="form3label">Competent electrician</label><select id="pf-el-competent"><option value="">Select competent electrician...</option></select></div></div></div>';
  } else if(type==='work_at_height'){
    formHtml='<div class="card" style="margin-bottom:14px;border-left:4px solid #065F46"><div class="card-title" style="color:#065F46">Work at Height Details</div>'
      +'<div class="form3row"><div class="form3group"><label class="form3label">Height above ground</label><input type="text" id="pf-wah-height" placeholder="e.g. 5m, 12m"/></div>'
      +'<div class="form3group"><label class="form3label">Access method</label><select id="pf-wah-access"><option value="ladder">Ladder</option><option value="scaffold">Scaffolding</option><option value="mewp">MEWP/Cherry picker</option><option value="rope">Rope access</option><option value="other">Other</option></select></div>'
      +'<div class="form3group"><label class="form3label">Fall protection</label><select id="pf-wah-fall"><option value="harness">Full body harness + lanyard</option><option value="guardrail">Guard rails</option><option value="net">Safety net</option><option value="airbag">Air bag</option></select></div></div>'
      +'<div class="form3group"><label class="form3label">Rescue plan</label><textarea id="pf-wah-rescue" style="min-height:50px" placeholder="Describe rescue plan for fallen or stranded worker..."></textarea></div></div>';
  } else if(type==='lifting_operation'){
    formHtml='<div class="card" style="margin-bottom:14px;border-left:4px solid #5B21B6"><div class="card-title" style="color:#5B21B6">Lifting Operation Details</div>'
      +'<div class="form3row"><div class="form3group"><label class="form3label">Load description</label><input type="text" id="pf-lift-load" placeholder="What is being lifted?"/></div>'
      +'<div class="form3group"><label class="form3label">Load weight (tonnes)</label><input type="number" id="pf-lift-weight" step="0.1" min="0"/></div>'
      +'<div class="form3group"><label class="form3label">Lifting equipment</label><input type="text" id="pf-lift-equip" placeholder="e.g. 50T mobile crane, chain block..."/></div>'
      +'<div class="form3group"><label class="form3label">Slinging method</label><input type="text" id="pf-lift-sling" placeholder="e.g. 4-leg chain sling, spreader bar..."/></div></div>'
      +'<div class="form3row"><div class="form3group"><label class="form3label">Appointed person / Lifting supervisor</label><input type="text" id="pf-lift-super"/></div><div class="form3group"><label class="form3label">Crane certificate in date?</label><select id="pf-lift-cert"><option value="yes">Yes</option><option value="no">No - STOP</option></select></div></div></div>';
  }
  // Default for other types
  if(!formHtml){
    var cfg2=PTW_TYPE_CFG[type];
    formHtml='<div class="card" style="margin-bottom:14px;border-left:4px solid '+cfg2.color+'"><div class="card-title" style="color:'+cfg2.color+'">'+cfg2.emoji+' '+cfg2.label+' Additional Details</div>'
      +'<div class="form3group"><label class="form3label">Additional details specific to this work</label><textarea id="pf-type-extra" style="min-height:80px" placeholder="Provide any additional technical details specific to this '+cfg2.label+' operation..."></textarea></div></div>';
  }
  el.innerHTML=formHtml;
  ['pf-cs-standby','pf-el-competent','pf-lift-super'].forEach(function(id){fillPersonSelect(id);});
}

async function ptwRunSmartChecks(){
  var el=document.getElementById('ptw-smart-check-panel');if(!el)return;
  var raRef=document.getElementById('pf-ra-ref')?.value?.trim();
  var contractorId=document.getElementById('pf-contractor')?.value;
  var blocks=[];
  var warnings=[];
  // Check RA
  if(!raRef){blocks.push({icon:'ti-alert-triangle',color:'#E24B4A',msg:'Risk Assessment reference is required - permit cannot be issued without RA'});}
  else{
    // Check RA exists
    try{
      var ras=await api('/risk_assessments?ra_ref=eq.'+encodeURIComponent(raRef)+cf()+'&select=id,status&limit=1');
      if(!ras||!ras.length)warnings.push({icon:'ti-info-circle',color:'#EF9F27',msg:'RA reference "'+raRef+'" not found in system - verify it exists'});
      else if(ras[0].status!=='active')warnings.push({icon:'ti-refresh',color:'#EF9F27',msg:'Linked RA status is "'+ras[0].status+'" - ensure it is current and active'});
    }catch(ex){}
  }
  // Check contractor competency
  if(contractorId){
    try{
      var con=await api('/contractors?id=eq.'+contractorId+cf()+'&select=status,expiry_date,contractor_name&limit=1');
      if(con?.[0]){
        var c=con[0];
        if(c.status!=='approved')blocks.push({icon:'ti-helmet',color:'#E24B4A',msg:'Contractor status is "'+c.status+'" - must be "approved" before work can proceed'});
        else if(c.expiry_date&&new Date(c.expiry_date)<new Date())blocks.push({icon:'ti-calendar-x',color:'#E24B4A',msg:'Contractor approval has expired ('+new Date(c.expiry_date).toLocaleDateString('en-GB')+') - renewal required'});
        else if(c.expiry_date&&new Date(c.expiry_date)<new Date(Date.now()+30*86400000))warnings.push({icon:'ti-calendar-event',color:'#EF9F27',msg:'Contractor approval expires within 30 days ('+new Date(c.expiry_date).toLocaleDateString('en-GB')+')'});
      }
    }catch(ex){}
  }
  if(!blocks.length&&!warnings.length){
    el.innerHTML='<div style="display:flex;align-items:center;gap:8px;padding:10px 14px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;font-size:12px;color:#166534;font-weight:600"><i class="ti ti-circle-check" style="font-size:16px"></i>Smart checks passed - no blocks detected</div>';
    return;
  }
  var h='<div style="display:flex;flex-direction:column;gap:6px">';
  blocks.forEach(function(b){h+='<div style="display:flex;align-items:flex-start;gap:8px;padding:10px 14px;background:#FEF2F2;border:1px solid #fecaca;border-radius:8px;font-size:12px;color:#991B1B"><i class="ti '+b.icon+'" style="font-size:15px;flex-shrink:0;margin-top:1px;color:'+b.color+'"></i><span><strong>BLOCK:</strong> '+escH(b.msg)+'</span></div>';});
  warnings.forEach(function(w){h+='<div style="display:flex;align-items:flex-start;gap:8px;padding:10px 14px;background:#FFFBEB;border:1px solid #fcd34d;border-radius:8px;font-size:12px;color:#92400E"><i class="ti '+w.icon+'" style="font-size:15px;flex-shrink:0;margin-top:1px;color:'+w.color+'"></i><span><strong>WARNING:</strong> '+escH(w.msg)+'</span></div>';});
  h+='</div>';
  el.innerHTML=h;
}

// -- SAVE PERMIT ---------------------------------------------------------------
async function ptwSave(targetStatus){
  if(!workflowCanMutate('permit','permits'))return;
  var currentPermit=ptwEditingId?(ptwAllData.find(function(x){return x.id===ptwEditingId;})||{}):null;
  if(currentPermit&&!controlledRecordCanEdit(currentPermit)){
    toast('This permit is controlled and locked. Use the approval, suspension, cancellation or closure workflow.',false);
    return;
  }
  var type=document.getElementById('pf-type')?.value;
  if(!type){toast('Please select a permit type',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  // Collect PPE
  var ppe=[];
  document.querySelectorAll('#ptw-ppe-checks input[type="checkbox"]:checked').forEach(function(cb){ppe.push(cb.value);});
  var extra=g('pf-ppe-extra');if(extra)ppe.push(extra);
  // Collect precautions checklist
  var precautions=[];
  var cfg=PTW_TYPE_CFG[type]||PTW_TYPE_CFG.hot_work;
  document.querySelectorAll('#ptw-precautions-list input[type="checkbox"]').forEach(function(cb,i){
    var label=cb.closest('label');
    var txt=(label?.querySelector('span')?.textContent||label?.textContent||cfg.precautions[i]||('Item '+(i+1))).trim();
    precautions.push({item:txt,checked:cb.checked});
  });
  // Blocked if no RA ref
  var blocks=[];
  if(!g('pf-ra-ref'))blocks.push('Risk Assessment reference missing');
  // Issuer is automatically captured from the logged-in user.
  var issuer=ptwCurrentIssuer();
  var issuerId=issuer.id;
  var issuerName=issuer.name;
  var receiver=ptwReceiverValue();
  var body={
    company_id:ccid(),
    permit_type_v2:type,permit_type:type,
    work_description:g('pf-desc'),work_location:g('pf-loc'),location:g('pf-loc'),
    department:g('pf-dept'),priority:g('pf-priority')||'medium',risk_level:g('pf-risk')||'medium',
    planned_start:g('pf-start'),planned_end:g('pf-end'),
    permit_issuer_id:issuerId||null,permit_issuer_name:issuerName||null,
    issued_by:issuerName||null,
    permit_receiver_name:receiver.name,permit_receiver:receiver.id||receiver.name,
    contractor_id:g('pf-contractor')||null,
    work_order_ref:null,
    team_members:ptwTeamValue(),
    ra_ref:g('pf-ra-ref'),method_statement_ref:g('pf-ms-ref'),
    ppe_required:ppe,precautions_checklist:precautions,
    approval_level_required:parseInt(g('pf-approval-levels'))||3,
    requires_weather_check:document.getElementById('pf-weather-check')?.checked||false,
    blocked_reasons:blocks,
    status:blocks.length&&targetStatus!=='draft'?'draft':targetStatus,
    updated_at:new Date().toISOString()
  };
  var permitRa=verifiedReferenceSelection('pf-ra-ref'),permitMs=verifiedReferenceSelection('pf-ms-ref'),permitWo=verifiedReferenceSelection('pf-wo');
  body.risk_assessment_id=permitRa.id;body.method_statement_id=permitMs.id;body.work_order_id=permitWo.id;body.work_order_ref=permitWo.ref;
  Object.assign(body,locationIdentityPayload(body.location,null));
  var validation=ptwValidateBeforeSave(targetStatus,body,precautions);
  if(validation){toast(validation,false);return;}
  if(blocks.length&&targetStatus!=='draft')toast('Saved as draft - RA reference is missing',false);
  try{
    if(ptwEditingId){
      var prev=ptwAllData.find(function(x){return x.id===ptwEditingId;})||{};
      var shouldNotifyL1=body.status==='pending_approval'&&prev.status!=='pending_approval';
      await apiWriteWithMissingColumnFallback('/permits?id=eq.'+ptwEditingId,{m:'PATCH',p:'return=minimal',b:body},'Permit');
      // Log
      try{await api('/permit_activity_log',{m:'POST',p:'return=minimal',b:{company_id:ccid(),permit_id:ptwEditingId,action:'Permit edited',performed_by:prof?.full_name||'User',details:'Status: '+body.status}});}catch(ex){}
      var updatedPermit=Object.assign({},prev,{id:ptwEditingId},body);
      ptwAudit(shouldNotifyL1?'submit':'update',shouldNotifyL1?'Permit submitted for approval':'Permit updated',updatedPermit,{old_status:prev.status||null,new_status:body.status||null});
      if(shouldNotifyL1){
        await ptwQueueApprovalEmail(updatedPermit,1);
        await ptwQueueStatusNotice(updatedPermit,'submitted',{level:1});
      }
      toast('Permit updated!');
      var idx=ptwAllData.findIndex(function(x){return x.id===ptwEditingId;});
      if(idx>=0)Object.assign(ptwAllData[idx],body);
      ptwShowDetail(ptwEditingId);
    }else{
      body.created_by=prof?.id;
      var res=await apiWriteWithMissingColumnFallback('/permits',{m:'POST',p:'return=representation',b:body},'Permit');
      if(res?.[0]?.id){
        var yr=new Date().getFullYear();
        var typeCode={hot_work:'HW',confined_space:'CS',excavation:'EX',electrical_isolation:'EI',loto:'LO',work_at_height:'WH',lifting_operation:'LF',line_breaking:'LB',radiation:'RA',chemical_handling:'CH'}[type]||'PTW';
        var seq=1;
        try{
          var prefix='PTW-'+typeCode+'-'+yr+'-';
          var existing=await api('/permits?select=permit_number&company_id=eq.'+ccid()+'&permit_number=like.'+encodeURIComponent(prefix+'*')+'&order=permit_number.desc&limit=1');
          var last=(existing&&existing[0]&&existing[0].permit_number)||'';
          var m=String(last).match(/-(\d+)$/);
          seq=m?parseInt(m[1],10)+1:1;
        }catch(refErr){
          seq=(ptwAllData||[]).filter(function(p){return String(p.permit_number||'').indexOf('PTW-'+typeCode+'-'+yr+'-')===0;}).length+1;
        }
        var ref='PTW-'+typeCode+'-'+yr+'-'+String(seq).padStart(3,'0');
        await api('/permits?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{permit_number:ref}});
        res[0].permit_number=ref;res[0].permit_type_v2=type;
        ptwAllData.unshift(res[0]);
        try{await api('/permit_activity_log',{m:'POST',p:'return=minimal',b:{company_id:ccid(),permit_id:res[0].id,action:'Permit created',performed_by:prof?.full_name||'User',new_status:body.status}});}catch(ex){}
        ptwAudit(body.status==='pending_approval'?'submit':'create',body.status==='pending_approval'?'Permit created and submitted for approval':'Permit created',res[0],{new_status:body.status||null});
        if(body.status==='pending_approval'){
          await ptwQueueApprovalEmail(res[0],1);
          await ptwQueueStatusNotice(res[0],'submitted',{level:1});
        }
        toast('Permit created! Ref: '+ref);
        ptwCurrentId=res[0].id;
        await ptwShowDetail(res[0].id);
      }
    }
  }catch(e){toast(actionErrorMessage('Save permit','Permit to Work',e.message),false);console.error(e);}
}

function ptwEditCurrent(){
  var x=ptwAllData.find(function(r){return r.id===ptwCurrentId;});if(!x)return;
  ptwEditingId=ptwCurrentId;
  document.getElementById('ptw-form3title').textContent='Edit Permit';
  document.getElementById('ptw-form3ref-display').textContent=x.permit_number||'';
  document.getElementById('ptw-del-btn').style.display=isMgr()?'inline-flex':'none';
  document.getElementById('ptw-type-selector').style.display='none';
  document.getElementById('ptw-form3body').style.display='block';
  var type=x.permit_type_v2||x.permit_type||'hot_work';
  var cfg=PTW_TYPE_CFG[type]||PTW_TYPE_CFG.hot_work;
  document.getElementById('pf-type').value=type;
  document.getElementById('pf-type-display').textContent=cfg.emoji+' '+cfg.label;
  var g=function(id,val){var el=document.getElementById(id);if(el)el.value=val||'';};
  g('pf-desc',x.work_description||x.precautions||x.description);
  g('pf-loc',x.work_location||x.location);
  g('pf-dept',x.department);
  ptwPopulatePeopleFields();
  ptwSetReceiverValue(x.permit_receiver,x.permit_receiver_name||x.permit_receiver);
  g('pf-team3extra',x.team_members);
  ptwLoadReferenceOptions(x.ra_ref,x.method_statement_ref);
  ptwLoadContractorOptions(x.contractor_id);
  ptwLoadWorkOrderOptions(x.work_order_id||x.work_order_ref);
  g('pf-priority',x.priority||'medium');
  g('pf-risk',x.risk_level||'medium');
  g('pf-approval-levels',String(x.approval_level_required||3));
  if(x.planned_start){var el=document.getElementById('pf-start');if(el)el.value=x.planned_start.slice(0,16);}
  if(x.planned_end){var el2=document.getElementById('pf-end');if(el2)el2.value=x.planned_end.slice(0,16);}
  var wc=document.getElementById('pf-weather-check');if(wc)wc.checked=!!x.requires_weather_check;
  ptwFillIssuerDisplay({id:x.permit_issuer_id||prof?.id||'',name:x.permit_issuer_name||x.issued_by||prof?.full_name||prof?.email||'Current user'});
  // PPE
  if(Array.isArray(x.ppe_required)){document.querySelectorAll('#ptw-ppe-checks input[type="checkbox"]').forEach(function(cb){cb.checked=x.ppe_required.includes(cb.value);});}
  ptwBuildTypeForm(type);
  var el3=document.getElementById('ptw-precautions-list');
  if(el3&&Array.isArray(x.precautions_checklist)&&x.precautions_checklist.length){
    ptwPreparePrecautionGrid(el3);
    el3.innerHTML=x.precautions_checklist.map(function(p){
      var item=typeof p==='string'?p:(p.item||p);var checked=typeof p==='object'&&p.checked;
      return ptwPrecautionRow(item,checked);
    }).join('');
  }else if(el3)ptwSelectType(type);
  ptwSetView('form');
  controlledApplyFormLock('ptw-form3view','ptw-controlled-lock-note',x,'Permit');
}

function ptwFormBack(){
  document.getElementById('ptw-form3view').style.display='none';
  if(ptwCurrentId&&ptwEditingId){document.getElementById('ptw-detail-view').style.display='block';}
  else{ptwSetView('list');ptwRenderList();}
}

async function ptwDelete(){
  if(!workflowCanMutate('permit','permits'))return;
  if(!ptwEditingId)return;
  var current=ptwAllData.find(function(x){return x.id===ptwEditingId;})||{};
  if(!isSA()&&!['draft','cancelled','rejected'].includes(current.status||'draft')){
    toast('Issued permits must be cancelled or closed for audit trail. Only draft, cancelled or rejected permits can be deleted.',false);
    return;
  }
  var ok=await appConfirm({
    title:'Delete permit',
    message:'Delete this permit?',
    detail:'This will remove the permit from the permit register. Approved or issued permits should normally be closed or cancelled instead.',
    confirmText:'Delete permit',
    cancelText:'Keep permit',
    danger:true
  });
  if(!ok)return;
  try{
    var deleted=await api('/permits?id=eq.'+ptwEditingId,{m:'DELETE',p:'return=representation'});
    if(!deleted||!deleted.length)throw new Error('Delete failed: record not found or permission denied');
    ptwAllData=ptwAllData.filter(function(x){return x.id!==ptwEditingId;});
    toast('Permit deleted!');ptwEditingId=null;ptwCurrentId=null;
    ptwSetView('list');ptwRenderList();
  }catch(e){toast(actionErrorMessage('Delete permit','Permit to Work',e.message),false);}
}

// -- GAS TEST PANEL ------------------------------------------------------------
function ptwOpenGasPanel(){
  ptwSetView('gas');
  ptwGasTests=[];
  var x=ptwAllData.find(function(r){return r.id===ptwCurrentId;})||{};
  ptwGasTests=Array.isArray(x.gas_tests)?JSON.parse(JSON.stringify(x.gas_tests)):[];
  document.getElementById('gas-datetime').value=new Date().toISOString().slice(0,16);
  ['gas-tester','gas-equipment','gas-cal-date','gas-o2','gas-lel','gas-h2s','gas-co','gas-location','gas-notes'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var gt=document.getElementById('gas-tester');if(gt)gt.value=ptwCurrentUserName();
  var gr=document.getElementById('gas-result');if(gr)gr.value='pass';
  ptwRenderGasHistoryPanel();
}

function ptwRenderGasHistoryPanel(){
  var el=document.getElementById('gas-tests-history');if(!el)return;
  if(!ptwGasTests.length){el.innerHTML='';return;}
  el.innerHTML='<div class="card" style="padding:0;overflow:hidden"><div style="padding:8px 14px;background:#065F46;color:#fff;font-size:12px;font-weight:700">Tests recorded in this session</div>'
    +ptwGasTests.map(function(t,i){
      var rc=t.result==='pass'?'#1D9E75':t.result==='fail'?'#E24B4A':'#EF9F27';
      return '<div style="padding:8px 14px;border-bottom:1px solid #f0f0f0;display:flex;gap:12px;font-size:12px;align-items:center">'
        +'<span style="flex:1">'+escH(t.tester||'-')+' - '+escH(new Date(t.datetime||t.date||'').toLocaleTimeString('en-GB'))+'</span>'
        +'<span>O2:'+t.o2+' LEL:'+t.lel+' H2S:'+t.h2s+' CO:'+t.co+'</span>'
        +'<span style="font-weight:700;color:'+rc+'">'+(t.result||'-').toUpperCase()+'</span>'
        +'</div>';
    }).join('')+'</div>';
}

function ptwClassifyGasTest(test){
  var o2=parseFloat(test.o2),lel=parseFloat(test.lel),h2s=parseFloat(test.h2s),co=parseFloat(test.co);
  if(isNaN(o2)||isNaN(lel))return 'borderline';
  if(o2<19.5||o2>23.5||lel>=10||(!isNaN(h2s)&&h2s>=5)||(!isNaN(co)&&co>=25))return 'fail';
  if(o2<20||o2>23||lel>=5||(!isNaN(h2s)&&h2s>0)||(!isNaN(co)&&co>=10))return 'borderline';
  return 'pass';
}

function ptwUpdateGasResultPreview(){
  var g=function(id){var el=document.getElementById(id);return el?el.value||'':null;};
  var result=document.getElementById('gas-result');
  if(result)result.value=ptwClassifyGasTest({o2:g('gas-o2'),lel:g('gas-lel'),h2s:g('gas-h2s'),co:g('gas-co')});
}

async function ptwAddGasTest(){
  if(!workflowCanMutate('permit','permits'))return;
  var g=function(id){var el=document.getElementById(id);return el?el.value||'':null;};
  var test={datetime:g('gas-datetime'),tester:ptwCurrentUserName(),equipment:g('gas-equipment'),cal_date:g('gas-cal-date'),o2:g('gas-o2'),lel:g('gas-lel'),h2s:g('gas-h2s'),co:g('gas-co'),location:g('gas-location'),result:g('gas-result'),notes:g('gas-notes')};
  if(!test.equipment)return toast('Please enter the gas detector / equipment used',false);
  if(!test.cal_date)return toast('Please enter the gas detector calibration date',false);
  if(new Date(test.cal_date)>new Date())return toast('Calibration date cannot be in the future',false);
  if(!test.o2||!test.lel)return toast('Please enter both O2 and LEL readings',false);
  var calculated=ptwClassifyGasTest(test);
  if(test.result==='pass'&&calculated!=='pass')test.result=calculated;
  ptwGasTests.push(test);
  ptwRenderGasHistoryPanel();
  // Save to DB
  try{
    var permit=ptwAllData.find(function(x){return x.id===ptwCurrentId;})||{};
    var body={gas_tests:ptwGasTests,updated_at:new Date().toISOString()};
    var clearedGasBlock=false;
    if(test.result==='fail'){
      var reason=PTW_FAILED_GAS_BLOCK;
      var blocks=Array.isArray(permit.blocked_reasons)?permit.blocked_reasons.slice():[];
      if(!blocks.includes(reason))blocks.push(reason);
      body.blocked_reasons=blocks;
      if(permit.status==='active'){
        body.status='suspended';
        body.suspended_at=new Date().toISOString();
        body.suspended_by=test.tester;
        body.suspension_reason=reason;
      }
    }else if(test.result==='pass'){
      var existingBlocks=Array.isArray(permit.blocked_reasons)?permit.blocked_reasons:[];
      if(existingBlocks.includes(PTW_FAILED_GAS_BLOCK)){
        body.blocked_reasons=existingBlocks.filter(function(b){return b!==PTW_FAILED_GAS_BLOCK;});
        clearedGasBlock=true;
      }
    }
    await api('/permits?id=eq.'+ptwCurrentId,{m:'PATCH',p:'return=minimal',b:body});
    var idx=ptwAllData.findIndex(function(x){return x.id===ptwCurrentId;});
    if(idx>=0)Object.assign(ptwAllData[idx],body);
    try{await api('/permit_activity_log',{m:'POST',p:'return=minimal',b:{company_id:ccid(),permit_id:ptwCurrentId,action:'Gas test recorded',performed_by:test.tester,details:'Equipment '+(test.equipment||'-')+', calibrated '+(test.cal_date||'-')+'. O2 '+(test.o2||'-')+'%, LEL '+(test.lel||'-')+'%, H2S '+(test.h2s||'-')+' ppm, CO '+(test.co||'-')+' ppm, result '+(test.result||'-')}});}catch(ex){}
    if(test.result==='fail')try{await api('/permit_activity_log',{m:'POST',p:'return=minimal',b:{company_id:ccid(),permit_id:ptwCurrentId,action:'Failed gas test - work stopped',performed_by:test.tester,details:'Permit '+(body.status==='suspended'?'suspended':'blocked')+' due to unsafe atmosphere',new_status:body.status||permit.status}});}catch(ex){}
    if(clearedGasBlock)try{await api('/permit_activity_log',{m:'POST',p:'return=minimal',b:{company_id:ccid(),permit_id:ptwCurrentId,action:'Gas test block cleared',performed_by:test.tester,details:'Passing gas test recorded. Permit may be resumed after supervisor review.',new_status:permit.status}});}catch(ex){}
    toast(test.result==='fail'?'FAILED gas test - work must stop and permit is blocked':'Gas test recorded! O2: '+test.o2+'% LEL: '+test.lel+'%',test.result!=='fail');
    ['gas-o2','gas-lel','gas-h2s','gas-co','gas-notes','gas-location'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  }catch(e){toastActionError('Add gas test','Permit to Work',e);}
}

function ptwGasBack(){ptwShowDetail(ptwCurrentId);}

