async function ptwRenderApprovalLevelsPanel(x){
  var el=document.getElementById('ptw-approval-levels-display');if(!el)return;
  el.innerHTML='';
  var levels=parseInt(x.approval_level_required)||3;
  var settings=await ptwGetApprovalSettings();
  var firstPending=ptwFirstPendingApprovalLevel(x);
  var lvls=[
    {n:1,label:'Level 1 - Area Supervisor',by_field:'approval_l1_by',at_field:'approval_l1_at',status_field:'approval_l1_status'},
    {n:2,label:'Level 2 - Department Manager',by_field:'approval_l2_by',at_field:'approval_l2_at',status_field:'approval_l2_status'},
    {n:3,label:'Level 3 - HSE Manager',by_field:'approval_l3_by',at_field:'approval_l3_at',status_field:'approval_l3_status'}
  ];
  for(var i=0;i<levels;i++){
    var lv=lvls[i];
    var status=x[lv.status_field]||'pending';
    var approver=ptwApproverForLevel(settings,lv.n);
    var canAct=status==='pending'&&isMgr()&&x.status==='pending_approval'&&lv.n===firstPending;
    var card=document.createElement('div');
    card.className='card';card.style.marginBottom='12px';
    var sc=status==='approved'?['#EAF3DE','#3B6D11']:status==='rejected'?['#FCEBEB','#A32D2D']:['#FEF9EC','#854F0B'];
    card.innerHTML='<div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:10px">'
      +'<div><div style="font-weight:700;font-size:14px">'+escH(lv.label)+'</div>'
      +(x[lv.by_field]?'<div style="font-size:12px;color:var(--text2)">'+escH(x[lv.by_field])+(x[lv.at_field]?' - '+new Date(x[lv.at_field]).toLocaleDateString('en-GB'):'')+'</div>':'')
      +'<div style="font-size:12px;color:var(--text2);margin-top:3px">Expected approver: <strong>'+escH(approver.name||approver.email||'Not configured')+'</strong></div>'
      +'</div>'
      +'<span style="background:'+sc[0]+';color:'+sc[1]+';padding:4px 12px;border-radius:99px;font-weight:700;font-size:12px;text-transform:capitalize">'+status+'</span>'
      +'</div>'
      +(canAct
        ?'<div style="margin-top:12px"><div style="font-size:12px;color:var(--text2);margin-bottom:8px">This is the current approval step. The audit trail will use the configured approver name, or your logged-in name if no approver is configured.</div>'
        +'<div style="display:flex;gap:8px;margin-top:8px;flex-wrap:wrap">'
        +'<button class="btn btn-primary" style="background:var(--green);border-color:var(--green)" data-auris-runtime-onclick="r0073" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([lv.n]))+'"><i class="ti ti-check"></i>Approve Level '+lv.n+'</button>'
        +'<button class="btn" style="color:var(--red);border-color:var(--red)" data-auris-runtime-onclick="r0074" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([lv.n]))+'"><i class="ti ti-x"></i>Reject</button>'
        +'</div></div>':(status==='pending'&&x.status==='pending_approval'?'<div style="margin-top:10px;font-size:12px;color:var(--text2)">Waiting for previous approval level.</div>':''));
    el.appendChild(card);
  }
}

function ptwFirstPendingApprovalLevel(x){
  var levels=parseInt(x.approval_level_required)||3;
  for(var i=1;i<=levels;i++){
    if((x['approval_l'+i+'_status']||'pending')!=='approved')return i;
  }
  return null;
}

async function ptwApprove(level, action){
  if(!workflowCanMutate('permit','permits'))return;
  var x=ptwAllData.find(function(r){return r.id===ptwCurrentId;});if(!x)return;
  var firstPending=ptwFirstPendingApprovalLevel(x);
  if(action==='approved'&&firstPending&&level!==firstPending){toast('Approval must follow the Level 1, Level 2, Level 3 sequence.',false);return;}
  var settings=await ptwGetApprovalSettings();
  var approver=ptwApproverForLevel(settings,level);
  var name=approver.name||prof?.full_name||prof?.email||'Approver';
  var update={updated_at:new Date().toISOString()};
  update['approval_l'+level+'_by']=name;
  update['approval_l'+level+'_at']=new Date().toISOString();
  update['approval_l'+level+'_status']=action;
  // Check if all required levels approved
  var levels=parseInt(x.approval_level_required)||3;
  if(action==='approved'){
    var allApproved=true;
    for(var i=1;i<=levels;i++){
      if(i===level)continue;
      if((x['approval_l'+i+'_status']||'pending')!=='approved'){allApproved=false;break;}
    }
    if(allApproved)update.status='approved';
  }else{update.status='rejected';}
  try{
    await api('/permits?id=eq.'+ptwCurrentId,{m:'PATCH',p:'return=minimal',b:update});
    Object.assign(x,update);
    try{await api('/permit_activity_log',{m:'POST',p:'return=minimal',b:{company_id:ccid(),permit_id:ptwCurrentId,action:'Level '+level+' approval: '+action,performed_by:name,new_status:update.status||x.status}});}catch(ex){}
    ptwAudit(action==='approved'?'approve':'reject','Permit Level '+level+' '+action,x,{approval_level:level,approver:name,new_status:update.status||x.status});
    if(action==='approved'&&!update.status&&level<levels)await ptwQueueApprovalEmail(x,level+1);
    if(action==='approved'&&update.status==='approved')await ptwQueueStatusNotice(x,'approved',{approval_level:level,approver:name});
    if(action==='rejected')await ptwQueueStatusNotice(x,'rejected',{approval_level:level,approver:name});
    toast('Level '+level+' '+action+'!');
    ptwOpenApprovalPanel();
    ptwRenderWorkflowBar(x);
    ptwRenderActionButtons(x);
  }catch(e){toastActionError('Approve permit','Permit to Work',e);}
}

function ptwApprovalBack(){ptwShowDetail(ptwCurrentId);}

// -- ACTIVATE ------------------------------------------------------------------
async function ptwActivate(){
  if(!workflowCanMutate('permit','permits'))return;
  var x=ptwAllData.find(function(r){return r.id===ptwCurrentId;});if(!x)return;
  if(Array.isArray(x.blocked_reasons)&&x.blocked_reasons.length){toast('Permit cannot be activated until all smart blocks are cleared.',false);return;}
  var type=x.permit_type_v2||x.permit_type||'';
  var tests=Array.isArray(x.gas_tests)?x.gas_tests:[];
  var hasPassingGas=tests.some(function(t){return t.result==='pass';});
  if(['confined_space','line_breaking'].includes(type)&&!hasPassingGas){toast('A passing gas test is required before activating this permit.',false);return;}
  var isos=Array.isArray(x.isolations)?x.isolations:[];
  if(['electrical_isolation','loto'].includes(type)&&!isos.length){toast('At least one isolation point must be recorded before activating this permit.',false);return;}
  if(x.planned_end&&new Date(x.planned_end)<new Date()){toast('Permit planned end date has passed. Please amend the permit before activation.',false);return;}
  if(x.requires_weather_check&&!x.weather_conditions){
    var weather=await appPrompt({title:'Weather check',message:'Weather conditions are required for outdoor work.',value:'Sunny, wind <5m/s',placeholder:'Weather conditions'});
    if(!weather)return;
    await api('/permits?id=eq.'+ptwCurrentId,{m:'PATCH',p:'return=minimal',b:{weather_conditions:weather,weather_checked_at:new Date().toISOString()}});
  }
  try{
    await api('/permits?id=eq.'+ptwCurrentId,{m:'PATCH',p:'return=minimal',b:{status:'active',actual_start:new Date().toISOString(),updated_at:new Date().toISOString()}});
    x.status='active';x.actual_start=new Date().toISOString();
    try{await api('/permit_activity_log',{m:'POST',p:'return=minimal',b:{company_id:ccid(),permit_id:ptwCurrentId,action:'Permit activated - work commenced',performed_by:prof?.full_name||'User',old_status:'approved',new_status:'active'}});}catch(ex){}
    ptwAudit('activate','Permit activated - work may commence',x,{old_status:'approved',new_status:'active'});
    await ptwQueueStatusNotice(x,'active');
    toast('Permit is now ACTIVE - work may commence');
    ptwShowDetail(ptwCurrentId);
  }catch(e){toastActionError('Activate permit','Permit to Work',e);}
}

