      var ratingCfg={excellent:['#EAF3DE','#3B6D11'],good:['#E6F1FB','#185FA5'],satisfactory:['#FEF9EC','#854F0B'],poor:['#FEF6E7','#C2410C'],unacceptable:['#FCEBEB','#A32D2D']};
      var rc=ratingCfg[x.overall_rating||'satisfactory']||ratingCfg.satisfactory;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +'<td style="padding:9px 14px;font-weight:600">'+escH(x.contractors?.contractor_name||'-')+'</td>'
        +'<td style="padding:9px 10px">'+dt+'</td>'
