  explosion:        {emoji:'*',label:'Explosion',               color:'#B45309'},
  medical:          {emoji:'*',label:'Medical Emergency',       color:'#185FA5'},
  earthquake:       {emoji:'*', label:'Earthquake',              color:'#854F0B'},
  flood:            {emoji:'*',label:'Flood',                   color:'#0891B2'},
  power_failure:    {emoji:'?',label:'Power Failure',           color:'#1D9E75'},
  cyber:            {emoji:'*',label:'Cyber Incident',          color:'#6D28D9'},
  workplace_violence:{emoji:'*',label:'Workplace Violence',     color:'#9F1239'},
  bomb_threat:      {emoji:'*',label:'Bomb Threat',             color:'#7F1D1D'},
  gas_leak:         {emoji:'*',label:'Gas Leak',                color:'#065F46'},
  structural:       {emoji:'*', label:'Structural Failure',      color:'#92400E'},
  environmental:    {emoji:'*',label:'Environmental',           color:'#166534'},
  pandemic:         {emoji:'*',label:'Pandemic',                color:'#5B21B6'},
