function ertShowForm(){['em3view-ert'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});document.getElementById('em3ert-form').style.display='block';}
function ertBack(){document.getElementById('em3ert-form').style.display='none';document.getElementById('em3view-ert').style.display='block';document.querySelectorAll('#page-emergency [id^="em3tab-"]').forEach(t=>t.classList.remove('active'));var tab=document.getElementById('em3tab-ert');if(tab)tab.classList.add('active');ertLoad();}

function ertNew(){
  emErtEditId=null;
  document.getElementById('em3ert-form3title').textContent='New ERT Member';
  document.getElementById('em3ert-del-btn').style.display='none';
  ['ertf-name','ertf-title','ertf-dept','ertf-phone1','ertf-phone2','ertf-email','ertf-team','ertf-area','ertf-notes'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['ertf-fa-expiry','ertf-fw-expiry','ertf-ert-date'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['ertf-fa-cert','ertf-fw-cert','ertf-ert-trained'].forEach(function(id){var el=document.getElementById(id);if(el)el.checked=false;});
  document.getElementById('ertf-role').value='ert_member';
  document.getElementById('ertf-status').value='active';
  fillPersonSelect('ertf-name');
  ertShowForm();
}

function ertEdit(id){
  var m=emErtData.find(x=>x.id===id);if(!m)return;
  emErtEditId=id;
  document.getElementById('em3ert-form3title').textContent='Edit ERT Member';
  document.getElementById('em3ert-del-btn').style.display=isMgr()?'inline-flex':'none';
  var gf=function(id,val){var el=document.getElementById(id);if(el)el.value=val||'';};
  fillPersonSelect('ertf-name',m.name);gf('ertf-title',m.job_title);gf('ertf-dept',m.department);
  gf('ertf-phone1',m.phone_primary);gf('ertf-phone2',m.phone_secondary);gf('ertf-email',m.email);
  gf('ertf-team',m.ert_team);gf('ertf-area',m.coverage_area);gf('ertf-notes',m.notes);
  gf('ertf-fa-expiry',m.first_aid_expiry);gf('ertf-fw-expiry',m.fire_warden_expiry);gf('ertf-ert-date',m.ert_trained_date);
  var r=document.getElementById('ertf-role');if(r)r.value=m.ert_role||'ert_member';
  var s=document.getElementById('ertf-status');if(s)s.value=m.status||'active';
  document.getElementById('ertf-fa-cert').checked=!!m.first_aid_certified;
  document.getElementById('ertf-fw-cert').checked=!!m.fire_warden_certified;
  document.getElementById('ertf-ert-trained').checked=!!m.ert_trained;
  ertShowForm();
}

async function ertSave(){
  var name=document.getElementById('ertf-name')?.value?.trim();if(!name){toast('Please enter member name',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var body={company_id:ccid(),name:name,job_title:g('ertf-title'),department:g('ertf-dept'),phone_primary:g('ertf-phone1'),phone_secondary:g('ertf-phone2'),email:g('ertf-email'),ert_role:g('ertf-role')||'ert_member',ert_team:g('ertf-team'),coverage_area:g('ertf-area'),first_aid_certified:document.getElementById('ertf-fa-cert')?.checked||false,first_aid_expiry:g('ertf-fa-expiry'),fire_warden_certified:document.getElementById('ertf-fw-cert')?.checked||false,fire_warden_expiry:g('ertf-fw-expiry'),ert_trained:document.getElementById('ertf-ert-trained')?.checked||false,ert_trained_date:g('ertf-ert-date'),status:g('ertf-status')||'active',notes:g('ertf-notes'),updated_at:new Date().toISOString()};
  try{if(emErtEditId){var oldErt=emErtData.find(function(x){return x.id===emErtEditId;})||{};await api('/ert_members?id=eq.'+emErtEditId,{m:'PATCH',p:'return=minimal',b:body});emAudit('update','Emergency response team member updated','ert_members',Object.assign({},oldErt,body,{id:emErtEditId}),{previous_status:oldErt.status||null,new_status:body.status});toast('Updated!');}else{body.created_by=prof?.id;var savedErt=await api('/ert_members',{m:'POST',p:'return=representation',b:body});emAudit('create','Emergency response team member added','ert_members',savedErt?.[0]||body,{role:body.ert_role});toast('ERT member added!');}ertBack();}catch(e){toastActionError('Save ERT member','Emergency Management',e);}
}
async function ertDelete(){if(!emErtEditId)return;try{var rows=await api('/ert_members?id=eq.'+emErtEditId+'&select=*');var currentErt=rows?.[0]||{};var status=String(currentErt.status||'').toLowerCase();if(status!=='inactive'){if(!(await appConfirmAction({title:'Deactivate ERT member',message:'Deactivate this ERT member instead of deleting the record?',detail:'The person is removed from active ERT coverage while keeping training and role history.',confirmText:'Deactivate',cancelText:'Back'})))return;await api('/ert_members?id=eq.'+emErtEditId,{m:'PATCH',p:'return=minimal',b:{status:'inactive',updated_at:new Date().toISOString()}});emAudit('deactivate','Emergency response team member deactivated','ert_members',Object.assign({},currentErt,{status:'inactive'}),{previous_status:currentErt.status||null});toast('ERT member deactivated');ertBack();return;}if(!(await appConfirmDelete('ERT member','This ERT member is already inactive. Permanent deletion should be used only for duplicate/test records.')))return;await api('/ert_members?id=eq.'+emErtEditId,{m:'DELETE'});emAudit('delete','Emergency response team member permanently deleted','ert_members',currentErt,{reason:'duplicate_or_test_record'});toast('Removed!');ertBack();}catch(e){toastActionError('Delete ERT member','Emergency Management',e);}}

