let ohMsData=[], ohAudData=[], ohSpiData=[], ohVaxData=[];
let ohExpData=[], ohOdData=[];
let ohMsEditId=null, ohAudEditId=null, ohSpiEditId=null;
let ohVaxEditId=null, ohExpEditId=null, ohOdEditId=null;

// -- Entry & tab switching -----------------------------------------------------
async function loadOHealth(){
  ['oh-ms-add-btn','oh-aud-add-btn','oh-spi-add-btn','oh-vax-add-btn',
   'oh-exp-add-btn','oh-od-add-btn'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.style.display=isMgr()?'inline-flex':'none';
  });
  ohLoadDash();
}

function ohSwitchTab(tab,btn){
  document.querySelectorAll('[id^="oh-tab-"]').forEach(t=>t.classList.remove('active'));
  btn.classList.add('active');
  ['dash','surveillance','audiometry','spirometry','vaccination','exposure','disease'].forEach(function(t){
    var el=document.getElementById('oh-view-'+t);if(el)el.style.display=t===tab?'block':'none';
  });
  ['oh-ms-form','oh-aud-form','oh-spi-form','oh-vax-form','oh-exp-form','oh-od-form'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.style.display='none';
  });
  if(tab==='dash')ohLoadDash();
  else if(tab==='surveillance')ohMsLoad();
  else if(tab==='audiometry')ohAudLoad();
  else if(tab==='spirometry')ohSpiLoad();
  else if(tab==='vaccination')vaxLoad();
  else if(tab==='exposure')expLoad();
  else if(tab==='disease')ohOdLoad();
}

// -- DASHBOARD -----------------------------------------------------------------
async function ohLoadDash(){
  var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
  try{
    var yr=new Date().getFullYear();
    var [ms,aud,exp,od,vax]=await Promise.all([
      api('/medical_surveillance?select=id,employee_name,department,exam_date,next_exam_date,fitness_status'+cf()),
      api('/audiometry_records?select=id,sts_right,sts_left'+cf()),
      api('/exposure_monitoring?select=id,exceeded_oel,risk_level,status'+cf()),
      api('/occupational_diseases?select=id,status'+cf()),
      api('/vaccination_records?select=id,status,expiry_date'+cf())
    ]);
    var now=new Date();var soon=new Date();soon.setDate(soon.getDate()+60);
    // Metrics
    setM('oh-m3ms',(ms||[]).filter(x=>x.exam_date&&new Date(x.exam_date).getFullYear()===yr).length);
    setM('oh-m3fit',(ms||[]).filter(x=>x.fitness_status==='fit').length);
    setM('oh-m3due',(ms||[]).filter(x=>x.next_exam_date&&new Date(x.next_exam_date)<=soon).length);
    setM('oh-m3oel',(exp||[]).filter(x=>x.exceeded_oel&&x.status==='open').length);
    setM('oh-m3sts',(aud||[]).filter(x=>x.sts_right||x.sts_left).length);
    setM('oh-m3od',(od||[]).filter(x=>x.status==='active').length);
    // Fitness summary
    var fitEl=document.getElementById('oh-dash-fitness');
    if(fitEl&&ms){
      var fit=(ms||[]).filter(x=>x.fitness_status==='fit').length;
      var restr=(ms||[]).filter(x=>x.fitness_status==='fit_with_restrictions').length;
      var unfit=(ms||[]).filter(x=>['temporarily_unfit','permanently_unfit'].includes(x.fitness_status)).length;
      var total=(ms||[]).length||1;
      fitEl.innerHTML='<div style="display:flex;flex-direction:column;gap:8px">'
        +ohBarRow('Fit for work',fit,total,'#1D9E75')
        +ohBarRow('Fit with restrictions',restr,total,'#EF9F27')
        +ohBarRow('Unfit',unfit,total,'#E24B4A')
        +'</div>';
    }
    // Audiometry risk
    var audEl=document.getElementById('oh-dash-audio');
    if(audEl&&aud){
      var sts=(aud||[]).filter(x=>x.sts_right||x.sts_left).length;
      var normal=(aud||[]).length-sts;
      audEl.innerHTML='<div style="display:flex;flex-direction:column;gap:8px">'
        +ohBarRow('Normal hearing',(aud||[]).length-sts,(aud||[]).length||1,'#1D9E75')
        +ohBarRow('STS detected',sts,(aud||[]).length||1,'#8B5CF6')
        +'</div>'
        +(sts>0?'<div style="margin-top:10px;padding:8px 12px;background:#F5F3FF;border-radius:8px;font-size:12px;color:#6D28D9"><i class="ti ti-ear"></i> <strong>'+sts+' worker'+(sts>1?'s':'')+' with Standard Threshold Shift</strong> - review hearing protection programme</div>':'');
    }
    // Top exposure risks
    var expEl=document.getElementById('oh-dash-exposure');
    if(expEl&&exp){
      var exceeded=(exp||[]).filter(x=>x.exceeded_oel);
      var high=(exp||[]).filter(x=>['high','critical'].includes(x.risk_level));
      var types={};
      exceeded.forEach(function(x){types[x.risk_level]=(types[x.risk_level]||0)+1;});
      expEl.innerHTML='<div style="display:flex;flex-direction:column;gap:8px">'
        +(exceeded.length?'<div style="padding:8px 12px;background:#FEF2F2;border:1px solid #fecaca;border-radius:8px;font-size:12px;color:#A32D2D;font-weight:600"><i class="ti ti-alert-triangle"></i> '+exceeded.length+' measurement'+(exceeded.length>1?'s':'')+' exceeding OEL</div>':'')
        +(high.length?'<div style="padding:8px 12px;background:#FEF6E7;border:1px solid #fcd34d;border-radius:8px;font-size:12px;color:#854F0B;font-weight:600"><i class="ti ti-flame"></i> '+high.length+' high-risk exposure'+(high.length>1?'s':'')+' requiring action</div>':'')
        +(!exceeded.length&&!high.length?'<div style="text-align:center;padding:16px;color:var(--text2)"><div style="font-size:28px;margin-bottom:8px"><i class="ti ti-circle-check"></i></div>No OEL exceedances recorded</div>':'')
        +'</div>';
    }
    // Upcoming exams
    var upcoming=(ms||[]).filter(x=>x.next_exam_date&&new Date(x.next_exam_date)>=now&&new Date(x.next_exam_date)<=soon)
      .sort((a,b)=>new Date(a.next_exam_date)-new Date(b.next_exam_date)).slice(0,5);
    var upEl=document.getElementById('oh-dash-upcoming');
    if(upEl){
      if(!upcoming.length){upEl.innerHTML='<div style="color:var(--text2);font-size:13px;padding:8px">No medical examinations due in the next 60 days</div>';return;}
      upEl.innerHTML='<div style="display:flex;flex-direction:column;gap:6px">'
        +upcoming.map(function(x){
          var dt=new Date(x.next_exam_date);
          var days=Math.floor((dt-now)/86400000);
          return '<div style="display:flex;align-items:center;gap:12px;padding:8px 12px;border:1px solid var(--border);border-radius:8px">'
            +'<div style="min-width:50px;text-align:center;background:#EFF6FF;border-radius:6px;padding:4px"><div style="font-size:14px;font-weight:800;color:#185FA5">'+dt.getDate()+'</div><div style="font-size:9px;font-weight:600;color:#6B7280">'+dt.toLocaleString('en-GB',{month:'short'})+'</div></div>'
            +'<div style="flex:1"><div style="font-weight:600;font-size:13px">'+escH(x.employee_name||'-')+'</div>'
            +'<div style="font-size:11px;color:var(--text2)">'+escH(x.department||'')+'</div></div>'
            +'<span style="font-size:11px;font-weight:700;color:'+(days<=14?'#E24B4A':'#185FA5')+'">'+days+'d</span>'
            +'</div>';
        }).join('')+'</div>';
    }
  }catch(e){console.error(e);}
}

function ohBarRow(label,val,total,color){
  var pct=total?Math.round(val/total*100):0;
  return '<div style="display:flex;align-items:center;gap:10px">'
    +'<div style="font-size:12px;min-width:130px;color:var(--text2)">'+escH(label)+'</div>'
    +'<div style="flex:1;background:#f3f4f6;border-radius:4px;height:8px;overflow:hidden">'
    +'<div style="width:'+pct+'%;background:'+color+';height:100%;border-radius:4px;transition:width .3s"></div>'
    +'</div>'
    +'<div style="font-size:12px;font-weight:700;color:'+color+';min-width:40px;text-align:right">'+val+'</div>'
    +'</div>';
}

// -- MEDICAL SURVEILLANCE ------------------------------------------------------
async function ohMsLoad(){
  var el=document.getElementById('oh-ms-list');if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  var ft=document.getElementById('oh-ms-filter')?.value||'';
  try{
    var q='/medical_surveillance?select=*'+cf()+'&order=exam_date.desc';
    if(ft&&ft!=='due_60'&&ft!=='overdue')q+='&exam_type=eq.'+ft;
    var d=await api(q);ohMsData=d||[];
    if(ft==='due_60'||ft==='overdue'){
      var today=new Date();today.setHours(0,0,0,0);
      var soon=new Date(today);soon.setDate(soon.getDate()+60);
      d=(d||[]).filter(function(x){var nd=x.next_exam_date?new Date(x.next_exam_date):null;return nd&&(ft==='overdue'?nd<today:nd<=soon);});
    }
    if(!d||!d.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600;margin-bottom:8px">No medical examinations recorded</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0193"><i class="ti ti-plus"></i>New examination</button>':'')+'</div>';
      return;
    }
    var fitCfg={fit:['#EAF3DE','#3B6D11','Fit'],fit_with_restrictions:['#FEF9EC','#854F0B','Fit w/ restrictions'],temporarily_unfit:['#FEF6E7','#C2410C','Temp. unfit'],permanently_unfit:['#FCEBEB','#A32D2D','Perm. unfit'],pending:['#f3f4f6','#6B7280','Pending']};
    var typeColor={pre_employment:'#185FA5',periodic:'#1D9E75',return_to_work:'#EF9F27',exit:'#6B7280',fitness_for_duty:'#7C3AED',special:'#8B5CF6'};
    var h='<div class="table-scroll"><table class="data-table" style="min-width:980px"><thead><tr><th>Employee</th><th>Dept</th><th>Exam type</th><th>Date</th><th>Next due</th><th>BMI</th><th>Fitness</th><th style="width:50px"></th></tr></thead><tbody>';
    var now=new Date();
    d.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';
      var fc=fitCfg[x.fitness_status]||fitCfg.pending;
      var tc=typeColor[x.exam_type]||'#6B7280';
      var isOverdue=x.next_exam_date&&new Date(x.next_exam_date)<now;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +'<td style="padding:8px 14px"><div style="font-weight:700">'+escH(x.employee_name||'-')+'</div>'
        +(x.job_title?'<div style="font-size:10px;color:var(--text2)">'+escH(x.job_title)+'</div>':'')+'</td>'
        +'<td style="padding:8px;font-size:11px">'+escH(x.department||'-')+'</td>'
        +'<td style="padding:8px"><span style="background:'+tc+'20;color:'+tc+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;text-transform:capitalize">'+escH((x.exam_type||'').replace(/_/g,' '))+'</span></td>'
        +'<td style="padding:8px">'+(x.exam_date?new Date(x.exam_date).toLocaleDateString('en-GB'):'-')+'</td>'
        +'<td style="padding:8px;font-weight:'+(isOverdue?'700':'400')+';color:'+(isOverdue?'var(--red)':'inherit')+'">'+(x.next_exam_date?new Date(x.next_exam_date).toLocaleDateString('en-GB')+(isOverdue?' - overdue':''):'-')+'</td>'
        +'<td style="padding:8px;text-align:center;font-weight:700;color:'+(x.bmi?x.bmi<18.5?'#0891B2':x.bmi<25?'#1D9E75':x.bmi<30?'#EF9F27':'#E24B4A':'#6B7280')+'">'+(x.bmi?parseFloat(x.bmi).toFixed(1):'-')+'</td>'
        +'<td style="padding:8px"><span style="background:'+fc[0]+';color:'+fc[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+fc[2]+'</span></td>'
        +'<td style="padding:8px"><div style="display:flex;gap:4px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0194"><i class="ti ti-edit"></i></button>'+(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0195"><i class="ti ti-trash"></i></button>':'')+'</div></td></tr>';
    });
    h+='</tbody></table></div>';el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

function msShowForm(){document.getElementById('oh-view-surveillance').style.display='none';document.getElementById('oh-ms-form').style.display='block';}
function msBack(){document.getElementById('oh-ms-form').style.display='none';document.getElementById('oh-view-surveillance').style.display='block';document.querySelectorAll('[id^="oh-tab-"]').forEach(t=>t.classList.remove('active'));document.getElementById('oh-tab-surveillance')?.classList.add('active');ohMsLoad();}

function msNew(){
  ohMsEditId=null;
  document.getElementById('oh-ms-form3title').textContent='New Medical Examination';
  document.getElementById('oh-ms-del-btn').style.display='none';
  ['msf-name','msf-eid','msf-dept','msf-title','msf-doctor','msf-clinic','msf-notes',
   'msf-restrictions','msf-referral-details','msf-report-ref'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['msf-dob','msf-date','msf-next-date','msf-followup-date'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['msf-height','msf-weight','msf-bp-sys','msf-bp-dia','msf-hr','msf-glucose'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  document.getElementById('msf-bmi-display').textContent='-';
  document.getElementById('msf-date').value=new Date().toISOString().slice(0,10);
  document.getElementById('msf-type').value='periodic';document.getElementById('msf-gender').value='male';
  document.getElementById('msf-fitness').value='fit';
  document.querySelectorAll('[name="ms-fitness"]').forEach(r=>{r.checked=r.value==='fit';});
  ['msf-followup','msf-referral','msf-exp-noise','msf-exp-chem','msf-exp-dust','msf-exp-vib',
   'msf-htn','msf-dm','msf-resp','msf-cardiac','msf-msk','msf-skin'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.checked=false;
  });
  fillPersonSelect('msf-name');
  msShowForm();
}

function msEdit(id){
  var x=ohMsData.find(r=>r.id===id);if(!x)return;
  ohMsEditId=id;
  document.getElementById('oh-ms-form3title').textContent='Edit Medical Examination';
  document.getElementById('oh-ms-del-btn').style.display=isMgr()?'inline-flex':'none';
  var gf=function(fid,val){var el=document.getElementById(fid);if(el)el.value=val||'';};
  fillPersonSelect('msf-name',x.employee_name);gf('msf-eid',x.employee_id);gf('msf-dept',x.department);
  gf('msf-title',x.job_title);gf('msf-dob',x.date_of_birth);gf('msf-doctor',x.examining_doctor);
  gf('msf-clinic',x.clinic_hospital);gf('msf-notes',x.medical_notes);
  gf('msf-restrictions',x.restrictions);gf('msf-referral-details',x.referral_details);
  gf('msf-report-ref',x.report_ref);gf('msf-date',x.exam_date);gf('msf-next-date',x.next_exam_date);
  gf('msf-followup-date',x.follow_up_date);
  gf('msf-height',x.height_cm||'');gf('msf-weight',x.weight_kg||'');
  gf('msf-bp-sys',x.blood_pressure_systolic||'');gf('msf-bp-dia',x.blood_pressure_diastolic||'');
  gf('msf-hr',x.heart_rate||'');gf('msf-glucose',x.blood_glucose||'');
  if(x.bmi)document.getElementById('msf-bmi-display').textContent=parseFloat(x.bmi).toFixed(1);
  document.getElementById('msf-gender').value=x.gender||'male';
  document.getElementById('msf-type').value=x.exam_type||'periodic';
  document.getElementById('msf-fitness').value=x.fitness_status||'fit';
  document.querySelectorAll('[name="ms-fitness"]').forEach(r=>{r.checked=r.value===(x.fitness_status||'fit');});
  var cb=function(id,val){var el=document.getElementById(id);if(el)el.checked=!!val;};
  cb('msf-followup',x.follow_up_required);cb('msf-referral',x.referral_required);
  cb('msf-exp-noise',x.noise_exposed);cb('msf-exp-chem',x.chemical_exposed);
  cb('msf-exp-dust',x.dust_exposed);cb('msf-exp-vib',x.vibration_exposed);
  cb('msf-htn',x.hypertension);cb('msf-dm',x.diabetes);cb('msf-resp',x.respiratory_condition);
  cb('msf-cardiac',x.cardiac_condition);cb('msf-msk',x.musculoskeletal_condition);cb('msf-skin',x.skin_condition);
  msShowForm();
}

function msCalcBMI(){
  var h=parseFloat(document.getElementById('msf-height')?.value)||0;
  var w=parseFloat(document.getElementById('msf-weight')?.value)||0;
  var el=document.getElementById('msf-bmi-display');if(!el)return;
  if(!h||!w){el.textContent='-';el.style.color='';return;}
  var bmi=w/((h/100)*(h/100));
  var color=bmi<18.5?'#0891B2':bmi<25?'#1D9E75':bmi<30?'#EF9F27':'#E24B4A';
  var label=bmi<18.5?'Underweight':bmi<25?'Normal':bmi<30?'Overweight':'Obese';
  el.innerHTML=bmi.toFixed(1)+'<span style="font-size:10px;margin-left:4px;color:'+color+'">'+label+'</span>';
  el.style.color=color;
}

async function msSave(){
  var name=document.getElementById('msf-name')?.value?.trim();if(!name){toast('Please enter employee name',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var h=parseFloat(g('msf-height'))||null;var w=parseFloat(g('msf-weight'))||null;
  var bmi=h&&w?parseFloat((w/((h/100)*(h/100))).toFixed(2)):null;
  var body={company_id:ccid(),employee_name:name,employee_id:g('msf-eid'),
    department:g('msf-dept'),job_title:g('msf-title'),date_of_birth:g('msf-dob')||null,
    gender:g('msf-gender')||'male',exam_type:g('msf-type')||'periodic',
    exam_date:g('msf-date'),next_exam_date:g('msf-next-date')||null,
    examining_doctor:g('msf-doctor'),clinic_hospital:g('msf-clinic'),
    fitness_status:document.getElementById('msf-fitness')?.value||'fit',
    restrictions:g('msf-restrictions'),referral_required:document.getElementById('msf-referral')?.checked||false,
    referral_details:g('msf-referral-details'),
    height_cm:h,weight_kg:w,bmi:bmi,
    blood_pressure_systolic:parseInt(g('msf-bp-sys'))||null,
    blood_pressure_diastolic:parseInt(g('msf-bp-dia'))||null,
    heart_rate:parseInt(g('msf-hr'))||null,blood_glucose:parseFloat(g('msf-glucose'))||null,
    noise_exposed:document.getElementById('msf-exp-noise')?.checked||false,
    chemical_exposed:document.getElementById('msf-exp-chem')?.checked||false,
    dust_exposed:document.getElementById('msf-exp-dust')?.checked||false,
    vibration_exposed:document.getElementById('msf-exp-vib')?.checked||false,
    hypertension:document.getElementById('msf-htn')?.checked||false,
    diabetes:document.getElementById('msf-dm')?.checked||false,
    respiratory_condition:document.getElementById('msf-resp')?.checked||false,
    cardiac_condition:document.getElementById('msf-cardiac')?.checked||false,
    musculoskeletal_condition:document.getElementById('msf-msk')?.checked||false,
    skin_condition:document.getElementById('msf-skin')?.checked||false,
    medical_notes:g('msf-notes'),follow_up_required:document.getElementById('msf-followup')?.checked||false,
    follow_up_date:g('msf-followup-date')||null,report_ref:g('msf-report-ref'),
    status:'completed',updated_at:new Date().toISOString()};Object.assign(body,personIdentityPayload(name,{snapshots:false}));
  try{
    if(ohMsEditId){var current=ohMsData.find(x=>x.id===ohMsEditId)||{};await apiWriteWithMissingColumnFallback('/medical_surveillance?id=eq.'+ohMsEditId,{m:'PATCH',p:'return=minimal',b:body},'Medical surveillance');ohAudit('update','Medical surveillance record updated','medical_surveillance',Object.assign({},current,body,{id:ohMsEditId}),{old_fitness:current.fitness_status||null,new_fitness:body.fitness_status});toast('Updated!');}
    else{body.created_by=prof?.id;var created=await apiWriteWithMissingColumnFallback('/medical_surveillance',{m:'POST',p:'return=representation',b:body},'Medical surveillance');var saved=created?.[0]||body;ohAudit('create','Medical surveillance record created','medical_surveillance',saved,{fitness_status:body.fitness_status});var needsAction=body.fitness_status!=='fit'||body.follow_up_required||body.referral_required;if(needsAction){try{await api('/action_tracker',{m:'POST',p:'return=minimal',b:{company_id:ccid(),source_module:'ohealth',source_id:saved.id||null,source_ref:'Medical surveillance - '+name,description:'Occupational health follow-up required for '+name+': '+(body.restrictions||body.referral_details||body.fitness_status),responsible:body.examining_doctor||null,target_date:body.follow_up_date||null,priority:['temporarily_unfit','permanently_unfit'].includes(body.fitness_status)?'high':'medium',status:'open',created_by:prof?.id}});ohAudit('follow_up','Medical surveillance follow-up action created','medical_surveillance',saved,{fitness_status:body.fitness_status});}catch(ex){console.warn('Medical surveillance MAP action failed',ex);}}toast('Examination saved!'+(needsAction?' Action added to MAP.':''));}
    msBack();
  }catch(e){toastActionError('Save medical surveillance record','Occupational Health',e);}
}
function ohArchivedText(v){return ('[Archived '+new Date().toISOString().slice(0,10)+'] '+(v||'')).trim();}
function ohIsArchivedText(v){return /\[Archived/i.test(String(v||''));}
function ohRecordRef(row,fallback){
  return row?.monitoring_ref||row?.report_ref||row?.notification_ref||row?.compensation_ref||row?.id?.slice(0,8)||fallback||'OH';
}
function ohRecordLabel(row){
  return row?.employee_name||row?.person_name||row?.department||row?.location||'Occupational health record';
}
function ohAudit(action,summary,table,row,details){
  try{
    row=row||{};
    auditLogEvent(action,'ohealth',summary,{
      employee_name:ohRecordLabel(row),
      reference:ohRecordRef(row),
      record_type:row.exam_type||row.vaccine_type||row.monitoring_type||row.disease_type||table,
      status:row.status||row.fitness_status||row.risk_level||null,
      date:row.exam_date||row.test_date||row.vaccination_date||row.monitoring_date||row.diagnosis_date||null,
      next_due:row.next_exam_date||row.next_test_date||row.next_dose_date||row.expiry_date||null,
      details:details||{}
    },{related_table:table||'occupational_health',related_id:row.id||details?.id||null,company_id:row.company_id||ccid()});
  }catch(_){}
}
