// -- AUDIOMETRY ----------------------------------------------------------------
async function ohAudLoad(){
  var el=document.getElementById('oh-aud-list');if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/audiometry_records?select=*'+cf()+'&order=test_date.desc');
    ohAudData=d||[];
    // STS alert
    var sts=(d||[]).filter(x=>x.sts_right||x.sts_left);
    var alertEl=document.getElementById('oh-aud-alerts');
    if(alertEl)alertEl.innerHTML=sts.length?'<div style="background:#F5F3FF;border:1px solid #c4b5fd;border-radius:8px;padding:10px 14px;font-size:12px;margin-bottom:8px;color:#6D28D9"><strong>STS: '+sts.length+' employee'+(sts.length>1?'s with':' with')+' Standard Threshold Shift detected:</strong> '+sts.map(x=>escH(x.employee_name)).join(', ')+'</div>':'';
    if(!d||!d.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600;margin-bottom:8px">No audiometry records</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0196"><i class="ti ti-plus"></i>New audiogram</button>':'')+'</div>';
      return;
    }
    var resCfg={normal:['#EAF3DE','#3B6D11'],mild_loss:['#FEF9EC','#854F0B'],moderate_loss:['#FEF6E7','#C2410C'],severe_loss:['#FCEBEB','#A32D2D'],profound_loss:['#4C0519','#fff']};
    var h='<div class="table-scroll"><table class="data-table" style="min-width:980px"><thead><tr><th>Employee</th><th>Dept</th><th>Date</th><th>Right ear</th><th>Left ear</th><th>STS</th><th>Baseline</th><th>Next test</th><th style="width:50px"></th></tr></thead><tbody>';
    d.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';
      var rc=resCfg[x.right_ear_result]||resCfg.normal;var lc=resCfg[x.left_ear_result]||resCfg.normal;
      var stsBadge=(x.sts_right||x.sts_left)?'<span style="background:#F5F3FF;color:#6D28D9;padding:2px 7px;border-radius:99px;font-size:10px;font-weight:700">STS</span>':'-';
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +'<td style="padding:8px 14px"><div style="font-weight:700">'+escH(x.employee_name||'-')+'</div>'
        +(x.noise_exposure_level_dba?'<div style="font-size:10px;color:var(--text2)">'+x.noise_exposure_level_dba+' dB(A)</div>':'')+'</td>'
        +'<td style="padding:8px;font-size:11px">'+escH(x.department||'-')+'</td>'
        +'<td style="padding:8px">'+(x.test_date?new Date(x.test_date).toLocaleDateString('en-GB'):'-')+'</td>'
        +'<td style="padding:8px;text-align:center"><span style="background:'+rc[0]+';color:'+rc[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+escH((x.right_ear_result||'normal').replace(/_/g,' '))+'</span></td>'
        +'<td style="padding:8px;text-align:center"><span style="background:'+lc[0]+';color:'+lc[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+escH((x.left_ear_result||'normal').replace(/_/g,' '))+'</span></td>'
        +'<td style="padding:8px;text-align:center">'+stsBadge+'</td>'
        +'<td style="padding:8px;text-align:center">'+(x.is_baseline?'<span style="background:#E6F1FB;color:#185FA5;padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">Baseline</span>':'-')+'</td>'
        +'<td style="padding:8px;font-size:11px">'+(x.next_test_date?new Date(x.next_test_date).toLocaleDateString('en-GB'):'-')+'</td>'
        +'<td style="padding:8px"><div style="display:flex;gap:4px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0197"><i class="ti ti-edit"></i></button>'+(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0198"><i class="ti ti-trash"></i></button>':'')+'</div></td></tr>';
    });
    h+='</tbody></table></div>';el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

function audCalcResult(ear){
  var freqs=[500,1000,2000,3000,4000,6000,8000];
  var vals=freqs.map(function(f){return parseFloat(document.getElementById('aud-'+ear+'-'+f)?.value||'');}).filter(v=>!isNaN(v));
  if(!vals.length)return;
  var avg=vals.reduce((s,v)=>s+v,0)/vals.length;
  var avgEl=document.getElementById('aud-'+ear+'-avg');if(avgEl)avgEl.textContent=avg.toFixed(1)+' dB';
  var result=avg<=25?'normal':avg<=40?'mild_loss':avg<=55?'moderate_loss':avg<=70?'severe_loss':'profound_loss';
  var label={'normal':'Normal','mild_loss':'Mild loss','moderate_loss':'Moderate loss','severe_loss':'Severe loss','profound_loss':'Profound loss'};
  var color={'normal':'#1D9E75','mild_loss':'#EF9F27','moderate_loss':'#C2410C','severe_loss':'#A32D2D','profound_loss':'#4C0519'};
  var resEl=document.getElementById('aud-'+ear+'-result');
  if(resEl)resEl.innerHTML='<span style="background:'+color[result]+'20;color:'+color[result]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+label[result]+'</span>';
  // Update overall
  var rAvg=parseFloat(document.getElementById('aud-r-avg')?.textContent)||0;
  var lAvg=parseFloat(document.getElementById('aud-l-avg')?.textContent)||0;
  var overallAvg=Math.max(rAvg,lAvg);
  var overallResult=overallAvg<=25?'normal':overallAvg<=40?'mild':overallAvg<=55?'moderate':overallAvg<=70?'severe':'profound';
  var overall=document.getElementById('aud-overall-result');
  if(overall){
    var icons={'normal':'?','mild':'*','moderate':'*','severe':'*','profound':'*'};
    var msgs={'normal':'Hearing within normal limits','mild':'Mild hearing loss detected - review HPP','moderate':'Moderate hearing loss - audiologist referral recommended','severe':'Severe hearing loss - urgent audiologist referral required','profound':'Profound hearing loss - urgent specialist referral'};
    var overallColor=color[overallResult+'_loss']||color.normal||'#1D9E75';
    overall.innerHTML='<div style="font-size:32px;margin-bottom:8px">'+icons[overallResult]+'</div>'
      +'<div style="font-weight:700;font-size:14px;margin-bottom:6px;color:'+overallColor+'">'+msgs[overallResult]+'</div>'
      +'<div style="font-size:12px;color:var(--text2)">Best average: R '+rAvg.toFixed(1)+' dB | L '+lAvg.toFixed(1)+' dB</div>';
  }
}

function audShowForm(){document.getElementById('oh-view-audiometry').style.display='none';document.getElementById('oh-aud-form').style.display='block';}
function audBack(){document.getElementById('oh-aud-form').style.display='none';document.getElementById('oh-view-audiometry').style.display='block';document.querySelectorAll('[id^="oh-tab-"]').forEach(t=>t.classList.remove('active'));document.getElementById('oh-tab-audiometry')?.classList.add('active');ohAudLoad();}

function audNew(){
  ohAudEditId=null;document.getElementById('oh-aud-form3title').textContent='New Audiogram';document.getElementById('oh-aud-del-btn').style.display='none';
  ['audf-name','audf-dept','audf-title','audf-examiner','audf-ppe','audf-notes'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['audf-date','audf-next-date','audf-cal-date'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['audf-noise-level','audf-noise-years'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['aud-r-500','aud-r-1000','aud-r-2000','aud-r-3000','aud-r-4000','aud-r-6000','aud-r-8000',
   'aud-l-500','aud-l-1000','aud-l-2000','aud-l-3000','aud-l-4000','aud-l-6000','aud-l-8000'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['aud-r-avg','aud-l-avg'].forEach(function(id){var el=document.getElementById(id);if(el)el.textContent='-';});
  ['aud-r-result','aud-l-result'].forEach(function(id){var el=document.getElementById(id);if(el)el.textContent='-';});
  document.getElementById('audf-date').value=new Date().toISOString().slice(0,10);
  ['audf-sts-r','audf-sts-l','audf-age-corr','audf-referral'].forEach(function(id){var el=document.getElementById(id);if(el)el.checked=false;});
  document.getElementById('audf-hp-worn').checked=true;document.getElementById('audf-baseline').checked=false;
  document.getElementById('aud-overall-result').innerHTML='<div style="font-size:40px;margin-bottom:8px"><i class="ti ti-circle-dot"></i></div><div style="font-size:13px;color:var(--text2)">Enter threshold values to see assessment</div>';
  fillPersonSelect('audf-name');
  audShowForm();
}

function audEdit(id){
  var x=ohAudData.find(r=>r.id===id);if(!x)return;
  ohAudEditId=id;document.getElementById('oh-aud-form3title').textContent='Edit Audiogram';document.getElementById('oh-aud-del-btn').style.display=isMgr()?'inline-flex':'none';
  var gf=function(fid,val){var el=document.getElementById(fid);if(el)el.value=val||'';};
  fillPersonSelect('audf-name',x.employee_name);gf('audf-dept',x.department);gf('audf-title',x.job_title);
  gf('audf-examiner',x.examiner);gf('audf-ppe',x.ppe_recommendation);gf('audf-notes',x.notes);
  gf('audf-date',x.test_date);gf('audf-next-date',x.next_test_date);gf('audf-cal-date',x.audiometer_calibration_date);
  gf('audf-noise-level',x.noise_exposure_level_dba||'');gf('audf-noise-years',x.years_noise_exposure||'');
  var freqPairs=[['r_500hz','aud-r-500'],['r_1000hz','aud-r-1000'],['r_2000hz','aud-r-2000'],['r_3000hz','aud-r-3000'],['r_4000hz','aud-r-4000'],['r_6000hz','aud-r-6000'],['r_8000hz','aud-r-8000'],['l_500hz','aud-l-500'],['l_1000hz','aud-l-1000'],['l_2000hz','aud-l-2000'],['l_3000hz','aud-l-3000'],['l_4000hz','aud-l-4000'],['l_6000hz','aud-l-6000'],['l_8000hz','aud-l-8000']];
  freqPairs.forEach(function(p){gf(p[1],x[p[0]]!=null?x[p[0]]:'');});
  var cb=function(id,val){var el=document.getElementById(id);if(el)el.checked=!!val;};
  cb('audf-sts-r',x.sts_right);cb('audf-sts-l',x.sts_left);cb('audf-age-corr',x.age_correction_applied);
  cb('audf-referral',x.referral_required);cb('audf-hp-worn',x.hearing_protection_worn);cb('audf-baseline',x.is_baseline);
  audCalcResult('r');audCalcResult('l');
  audShowForm();
}

