// -- EXPOSURE MONITORING -------------------------------------------------------
async function expLoad(){
  var el=document.getElementById('oh-exp-list');if(!el)return;el.innerHTML='<div class="loading-msg">Loading...</div>';
  var ft=document.getElementById('oh-exp-filter')?.value||'';
  try{
    var q='/exposure_monitoring?select=*'+cf()+'&order=monitoring_date.desc';if(ft)q+='&monitoring_type=eq.'+ft;
    var d=await api(q);ohExpData=d||[];
    var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
    setM('oh-exp-exceeded',(d||[]).filter(x=>x.exceeded_oel).length);
    setM('oh-exp-high',(d||[]).filter(x=>['high','critical'].includes(x.risk_level)).length);
    setM('oh-exp-total',(d||[]).length);
    if(!d||!d.length){el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600;margin-bottom:8px">No exposure monitoring records</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0205"><i class="ti ti-plus"></i>New measurement</button>':'')+'</div>';return;}
    var rlCfg={negligible:['#EAF3DE','#3B6D11'],low:['#EAF3DE','#3B6D11'],medium:['#FEF9EC','#854F0B'],high:['#FEF6E7','#C2410C'],critical:['#FCEBEB','#A32D2D']};
    var typeEmoji={noise:'*',dust:'*',silica:'*',chemical:'*',heat_stress:'*',vibration:'*',biological:'*',radiation:'*',other:'*'};
    var h='<div class="table-scroll"><table class="data-table" style="min-width:1120px"><thead><tr><th>Ref / Date</th><th>Type</th><th>Location / Dept</th><th>Agent</th><th>TWA</th><th>OEL</th><th>% OEL</th><th>Risk</th><th>Status</th><th style="width:50px"></th></tr></thead><tbody>';
    d.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';var rl=rlCfg[x.risk_level]||rlCfg.low;
      var pctOel=x.twa_8hr&&x.oel_twa?Math.round(x.twa_8hr/x.oel_twa*100):x.exceedance_pct?Math.round(x.exceedance_pct):null;
      var pctColor=pctOel?pctOel>=100?'#A32D2D':pctOel>=75?'#C2410C':pctOel>=50?'#EF9F27':'#1D9E75':'#6B7280';
      var stCfg2={open:['#FEF9EC','#854F0B'],actions_taken:['#EAF3DE','#3B6D11'],closed:['#f3f4f6','#6B7280'],requires_reassessment:['#FEF6E7','#C2410C']};
      var sc=stCfg2[x.status]||stCfg2.open;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +'<td style="padding:8px 14px"><div style="font-family:monospace;font-weight:700;color:#854F0B;font-size:11px">'+escH(x.monitoring_ref||'-')+'</div>'
        +(x.monitoring_date?'<div style="font-size:11px;color:var(--text2)">'+new Date(x.monitoring_date).toLocaleDateString('en-GB')+'</div>':'')+'</td>'
        +'<td style="padding:8px">'+(typeEmoji[x.monitoring_type]||'*')+' <span style="font-size:11px">'+escH(x.monitoring_type?.replace('_',' ')||'-')+'</span></td>'
        +'<td style="padding:8px;font-size:11px"><div>'+escH(x.location||'-')+'</div><div style="color:var(--text2)">'+escH(x.department||'')+'</div></td>'
        +'<td style="padding:8px;font-size:11px">'+escH(x.agent||'-')+'</td>'
        +'<td style="padding:8px;text-align:center;font-weight:700">'+(x.twa_8hr?x.twa_8hr+' '+(x.measurement_unit||''):'-')+'</td>'
        +'<td style="padding:8px;text-align:center;color:var(--text2);font-size:11px">'+(x.oel_twa?x.oel_twa:'-')+'</td>'
        +'<td style="padding:8px;text-align:center;font-weight:800;color:'+pctColor+'">'+(pctOel?pctOel+'%':'-')+(x.exceeded_oel?'<div style="font-size:9px;color:#A32D2D">EXCEEDED</div>':'')+'</td>'
        +'<td style="padding:8px"><span style="background:'+rl[0]+';color:'+rl[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;text-transform:capitalize">'+escH(x.risk_level||'low')+'</span></td>'
        +'<td style="padding:8px"><span style="background:'+sc[0]+';color:'+sc[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+escH(x.status?.replace(/_/g,' ')||'open')+'</span></td>'
        +'<td style="padding:8px"><div style="display:flex;gap:4px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0206"><i class="ti ti-edit"></i></button>'+(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0207"><i class="ti ti-trash"></i></button>':'')+'</div></td></tr>';
    });
    h+='</tbody></table></div>';el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

function expUpdateTypeForm(){
  var type=document.getElementById('expf-type')?.value||'noise';
  var el=document.getElementById('expf-type-specific');if(!el)return;
  var unitDefaults={noise:{unit:'dB(A)',oel:'85',method:'Personal dosimetry / sound level meter'},dust:{unit:'mg/m3',oel:'10',method:'Gravimetric sampling (IOM sampler)'},silica:{unit:'mg/m3',oel:'0.1',method:'Gravimetric sampling + XRD analysis'},chemical:{unit:'ppm or mg/m3',oel:'',method:'Personal air sampling'},heat_stress:{unit:'-C WBGT',oel:'28',method:'WBGT meter (ISO 7243)'},vibration:{unit:'m/s-',oel:'5.0',method:'Accelerometer (ISO 5349 / ISO 2631'}};
  var df=unitDefaults[type]||{unit:'',oel:'',method:''};
  var unitEl=document.getElementById('expf-unit');if(unitEl&&!unitEl.value)unitEl.value=df.unit;
  var oelEl=document.getElementById('expf-oel-twa');if(oelEl&&!oelEl.value)oelEl.value=df.oel;
  var methodEl=document.getElementById('expf-method');if(methodEl&&!methodEl.value)methodEl.value=df.method;
  var typeHtml={
    noise:'<div class="card" style="margin-bottom:14px;border-left:4px solid #185FA5"><div class="card-title" style="color:#185FA5">Noise-Specific Fields</div><div class="form3row"><div class="form3group"><label class="form3label">LEX,8h (daily noise exposure, dB(A))</label><input type="number" id="expf-lex8h" step="0.1" min="50" max="140"/></div><div class="form3group"><label class="form3label">Peak noise level (dB(C))</label><input type="number" id="expf-peak-dbc" step="0.1" min="50" max="200"/></div></div><div style="font-size:11px;background:#EFF6FF;padding:8px 12px;border-radius:8px;color:#185FA5"><strong>Action level:</strong> 80 dB(A) - provide HPE, training, audiometry | <strong>OEL:</strong> 85 dB(A) - mandatory hearing protection</div></div>',
    silica:'<div class="card" style="margin-bottom:14px;border-left:4px solid #854F0B"><div class="card-title" style="color:#854F0B">Silica-Specific Fields</div><div class="form3row"><div class="form3group"><label class="form3label">Sample type</label><select id="expf-silica-type"><option value="respirable">Respirable fraction</option><option value="inhalable">Inhalable fraction</option></select></div><div class="form3group"><label class="form3label">% SiO2 in bulk sample</label><input type="number" id="expf-silica-pct" step="0.1" min="0" max="100"/></div></div><div style="font-size:11px;background:#FEF9EC;padding:8px 12px;border-radius:8px;color:#854F0B"><strong>ACGIH TLV:</strong> 0.025 mg/m3 (respirable) | <strong>NIOSH REL:</strong> 0.05 mg/m3 | Silicosis risk even at lower levels</div></div>',
    heat_stress:'<div class="card" style="margin-bottom:14px;border-left:4px solid #DC2626"><div class="card-title" style="color:#DC2626">Heat Stress-Specific Fields</div><div class="form3row"><div class="form3group"><label class="form3label">WBGT value (-C)</label><input type="number" id="expf-wbgt" step="0.1" min="10" max="50" data-auris-generated-oninput="g0208"/></div><div class="form3group"><label class="form3label">Work intensity</label><select id="expf-heat-intensity"><option value="light">Light (&lt;200W) - WBGT limit 28-C</option><option value="moderate">Moderate (200-350W) - limit 25-C</option><option value="heavy">Heavy (350-500W) - limit 22-C</option><option value="very_heavy">Very heavy (&gt;500W) - limit 18-C</option></select></div></div><div style="font-size:11px;background:#FEF2F2;padding:8px 12px;border-radius:8px;color:#A32D2D"><strong>Heat stroke risk factors:</strong> high humidity, direct sunlight, dehydration, physical exertion, no acclimatisation</div></div>',
    vibration:'<div class="card" style="margin-bottom:14px;border-left:4px solid #8B5CF6"><div class="card-title" style="color:#8B5CF6">Vibration-Specific Fields</div><div class="form3row"><div class="form3group"><label class="form3label">Vibration type</label><select id="expf-vib-type"><option value="hav">Hand-arm (HAV) - ISO 5349</option><option value="wbv">Whole-body (WBV) - ISO 2631</option></select></div><div class="form3group"><label class="form3label">A(8) value (m/s-)</label><input type="number" id="expf-ahv" step="0.01" min="0" data-auris-generated-oninput="g0208"/></div><div class="form3group"><label class="form3label">Exposure points</label><input type="number" id="expf-vib-points" step="1" min="0"/></div></div><div style="font-size:11px;background:#F5F3FF;padding:8px 12px;border-radius:8px;color:#7C3AED"><strong>HAV action value:</strong> 2.5 m/s- A(8) | <strong>Limit value:</strong> 5 m/s- A(8)<br><strong>WBV action value:</strong> 0.5 m/s- A(8) | <strong>Limit value:</strong> 1.15 m/s- A(8)</div></div>'
  };
  el.innerHTML=typeHtml[type]||'';
  expCalcRisk();
}

function expCalcRisk(){
  var twa=parseFloat(document.getElementById('expf-twa')?.value)||0;
  var oel=parseFloat(document.getElementById('expf-oel-twa')?.value)||0;
  var el=document.getElementById('exp-risk-panel');if(!el)return;
  if(!twa&&!oel){el.innerHTML='<div style="font-size:40px;margin-bottom:8px"><i class="ti ti-circle-dot"></i></div><div style="font-size:13px;color:var(--text2)">Enter TWA and OEL to calculate % of limit</div>';return;}
  if(!oel){el.innerHTML='<div style="font-size:13px;color:var(--text2);padding:10px">Enter the OEL (legal limit) to calculate % exceedance</div>';return;}
  var pct=Math.round(twa/oel*100);
  var exceeded=pct>=100;
  var risk=pct>=100?'critical':pct>=75?'high':pct>=50?'medium':pct>=25?'low':'negligible';
  var riskColor={critical:'#A32D2D',high:'#C2410C',medium:'#854F0B',low:'#3B6D11',negligible:'#3B6D11'};
  var riskBg={critical:'#FCEBEB',high:'#FEF6E7',medium:'#FEF9EC',low:'#EAF3DE',negligible:'#EAF3DE'};
  el.innerHTML='<div style="padding:12px;background:'+riskBg[risk]+';border:2px solid '+riskColor[risk]+';border-radius:10px;text-align:center">'
    +'<div style="font-size:36px;font-weight:900;color:'+riskColor[risk]+'">'+pct+'%</div>'
    +'<div style="font-size:12px;font-weight:700;color:'+riskColor[risk]+';text-transform:uppercase;letter-spacing:.04em">of OEL</div>'
    +'<div style="font-size:13px;font-weight:700;color:'+riskColor[risk]+';margin-top:6px;text-transform:capitalize">'+risk+' risk</div>'
    +(exceeded?'<div style="margin-top:8px;background:'+riskColor[risk]+';color:#fff;padding:4px 10px;border-radius:6px;font-size:11px;font-weight:700">OEL EXCEEDED - IMMEDIATE ACTION REQUIRED</div>':'')
    +'</div>'
    +'<div style="margin-top:10px;font-size:11px;color:var(--text2)">TWA: '+twa+' | OEL: '+oel+' | Ratio: '+twa+'/'+oel+'</div>';
  // Auto-update risk level and exceeded
  var riskSel=document.getElementById('expf-status');
  if(riskSel&&exceeded&&riskSel.value==='open'){}
}

function expShowForm(){document.getElementById('oh-view-exposure').style.display='none';document.getElementById('oh-exp-form').style.display='block';}
function expBack(){document.getElementById('oh-exp-form').style.display='none';document.getElementById('oh-view-exposure').style.display='block';document.querySelectorAll('[id^="oh-tab-"]').forEach(t=>t.classList.remove('active'));document.getElementById('oh-tab-exposure')?.classList.add('active');expLoad();}

function expNew(){
  ohExpEditId=null;document.getElementById('oh-exp-form3title').textContent='New Exposure Measurement';document.getElementById('oh-exp-form3ref').textContent='EXP-AUTO';document.getElementById('oh-exp-del-btn').style.display='none';
  ['expf-location','expf-dept','expf-role','expf-agent','expf-value','expf-unit','expf-duration',
   'expf-twa','expf-stel','expf-oel-twa','expf-oel-stel','expf-oel-source',
   'expf-method','expf-instrument','expf-cal-ref','expf-sampler','expf-controls','expf-add-controls','expf-actions'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['expf-date','expf-reassess'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  document.getElementById('expf-date').value=new Date().toISOString().slice(0,10);
  document.getElementById('expf-type').value='noise';document.getElementById('expf-status').value='open';
  document.getElementById('expf-controls-ok').checked=true;
  document.getElementById('exp-risk-panel').innerHTML='<div style="font-size:40px;margin-bottom:8px"><i class="ti ti-circle-dot"></i></div><div style="font-size:13px;color:var(--text2)">Enter TWA and OEL to calculate % of limit</div>';
  expUpdateTypeForm();
  expShowForm();
}

async function expEdit(id){
  var x=ohExpData.find(r=>r.id===id);if(!x)return;
  ohExpEditId=id;document.getElementById('oh-exp-form3title').textContent='Edit Exposure Record';document.getElementById('oh-exp-form3ref').textContent=x.monitoring_ref||'-';document.getElementById('oh-exp-del-btn').style.display=isMgr()?'inline-flex':'none';
  var gf=function(fid,val){var el=document.getElementById(fid);if(el)el.value=val||'';};
  gf('expf-location',x.location);gf('expf-dept',x.department);gf('expf-role',x.job_role);gf('expf-agent',x.agent);
  gf('expf-value',x.measurement_value||'');gf('expf-unit',x.measurement_unit);gf('expf-duration',x.exposure_duration_hrs||'');
  gf('expf-twa',x.twa_8hr||'');gf('expf-stel',x.stel||'');gf('expf-oel-twa',x.oel_twa||'');gf('expf-oel-stel',x.oel_stel||'');gf('expf-oel-source',x.oel_source);
  gf('expf-method',x.monitoring_method);gf('expf-instrument',x.instrument_used);gf('expf-cal-ref',x.calibration_ref);gf('expf-sampler',x.sampler_name);
  gf('expf-controls',x.existing_controls);gf('expf-add-controls',x.additional_controls_required);gf('expf-actions',x.recommended_actions);
  gf('expf-date',x.monitoring_date);gf('expf-reassess',x.reassessment_date);
  document.getElementById('expf-type').value=x.monitoring_type||'noise';
  document.getElementById('expf-status').value=x.status||'open';
  document.getElementById('expf-controls-ok').checked=x.controls_adequate!==false;
  expUpdateTypeForm();expCalcRisk();
  expShowForm();
}

async function expSave(){
  var loc=document.getElementById('expf-location')?.value?.trim();if(!loc){toast('Please enter monitoring location',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var gn=function(id){var v=parseFloat(g(id));return isNaN(v)?null:v;};
  var twa=gn('expf-twa');var oel=gn('expf-oel-twa');
  var pctOel=twa&&oel?parseFloat((twa/oel*100).toFixed(1)):null;
  var exceeded=pctOel?pctOel>=100:false;
  var risk=pctOel?pctOel>=100?'critical':pctOel>=75?'high':pctOel>=50?'medium':pctOel>=25?'low':'negligible':'low';
  var body={company_id:ccid(),monitoring_type:g('expf-type')||'noise',monitoring_date:g('expf-date'),location:loc,department:g('expf-dept'),job_role:g('expf-role'),agent:g('expf-agent'),measurement_value:gn('expf-value'),measurement_unit:g('expf-unit'),exposure_duration_hrs:gn('expf-duration'),twa_8hr:twa,stel:gn('expf-stel'),oel_twa:oel,oel_stel:gn('expf-oel-stel'),oel_source:g('expf-oel-source'),exceedance_pct:pctOel,risk_level:risk,exceeded_oel:exceeded,monitoring_method:g('expf-method'),instrument_used:g('expf-instrument'),calibration_ref:g('expf-cal-ref'),sampler_name:g('expf-sampler'),existing_controls:g('expf-controls'),controls_adequate:document.getElementById('expf-controls-ok')?.checked||false,additional_controls_required:g('expf-add-controls'),recommended_actions:g('expf-actions'),reassessment_date:g('expf-reassess')||null,status:g('expf-status')||'open',updated_at:new Date().toISOString()};
  // type-specific
  if(g('expf-type')==='noise'){body.noise_lex8h=gn('expf-lex8h');body.noise_peak_dbc=gn('expf-peak-dbc');}
  if(g('expf-type')==='heat_stress'){body.wbgt_value=gn('expf-wbgt');}
  if(g('expf-type')==='vibration'){body.vibration_ahv=gn('expf-ahv');body.vibration_exposure_points=parseInt(g('expf-vib-points'))||null;}
  try{
    if(ohExpEditId){var current=ohExpData.find(x=>x.id===ohExpEditId)||{};await api('/exposure_monitoring?id=eq.'+ohExpEditId,{m:'PATCH',p:'return=minimal',b:body});ohAudit('update','Exposure monitoring record updated','exposure_monitoring',Object.assign({},current,body,{id:ohExpEditId}),{old_risk:current.risk_level||null,new_risk:body.risk_level,exceeded_oel:body.exceeded_oel});toast('Updated!');}
    else{
      body.created_by=prof?.id;var res=await api('/exposure_monitoring',{m:'POST',p:'return=representation',b:body});var saved=res?.[0]||body;ohAudit('create','Exposure monitoring record created','exposure_monitoring',saved,{risk_level:body.risk_level,exceeded_oel:body.exceeded_oel});
      if(res?.[0]?.id){
        var yr=new Date().getFullYear();var ref=await nextCompanyRef('exposure_monitoring','monitoring_ref','EXP-'+yr+'-');
        await api('/exposure_monitoring?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{monitoring_ref:ref}});
        toast('Saved! Ref: '+ref);
        // Auto MAP if exceeded
        if(exceeded){try{await api('/action_tracker',{m:'POST',p:'return=minimal',b:{company_id:ccid(),source_module:'ohealth',source_id:res[0].id,source_ref:ref+' - Exposure monitoring',description:'OEL exceeded: '+(g('expf-agent')||g('expf-type'))+' at '+loc+' ('+pctOel+'% of OEL)',priority:risk==='critical'?'critical':'high',status:'open',created_by:prof?.id}});ohAudit('follow_up','Exposure monitoring follow-up action created','exposure_monitoring',Object.assign({},saved,{monitoring_ref:ref}),{risk_level:risk,exceedance_pct:pctOel});}catch(ex){console.warn('Exposure monitoring MAP action failed',ex);}}
      }
    }
    expBack();
  }catch(e){toastActionError('Save exposure monitoring record','Occupational Health',e);}
}
async function expDelete(){if(!ohExpEditId)return;try{var rows=await api('/exposure_monitoring?id=eq.'+ohExpEditId+'&select=*');var current=rows?.[0]||{};if(current.status!=='closed'&&!ohIsArchivedText(current.recommended_actions)){if(!(await appConfirmAction({title:'Close exposure monitoring record',message:'Close this exposure monitoring record instead of deleting it?',detail:'Exposure monitoring supports legal and health trend evidence and should remain traceable.',confirmText:'Close record',cancelText:'Back'})))return;await api('/exposure_monitoring?id=eq.'+ohExpEditId,{m:'PATCH',p:'return=minimal',b:{status:'closed',recommended_actions:ohArchivedText(current.recommended_actions),updated_at:new Date().toISOString()}});ohAudit('close','Exposure monitoring record closed','exposure_monitoring',Object.assign({id:ohExpEditId},current),{});toast('Exposure monitoring record closed');expBack();return;}if(!(await appConfirmDelete('exposure monitoring record','This record is already closed/archived. Permanent deletion should be used only for duplicate/test records.')))return;await api('/exposure_monitoring?id=eq.'+ohExpEditId,{m:'DELETE'});ohAudit('delete','Exposure monitoring record permanently deleted','exposure_monitoring',Object.assign({id:ohExpEditId},current),{});toast('Deleted!');expBack();}catch(e){toastActionError('Delete exposure monitoring record','Occupational Health',e);}}
async function expDeleteRow(id){try{var current=ohExpData.find(x=>x.id===id)||{};if(current.status!=='closed'&&!ohIsArchivedText(current.recommended_actions)){if(!(await appConfirmAction({title:'Close exposure monitoring record',message:'Close this exposure monitoring record instead of deleting it?',detail:'Exposure monitoring supports legal and health trend evidence and should remain traceable.',confirmText:'Close record',cancelText:'Back'})))return;await api('/exposure_monitoring?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{status:'closed',recommended_actions:ohArchivedText(current.recommended_actions),updated_at:new Date().toISOString()}});ohAudit('close','Exposure monitoring record closed','exposure_monitoring',Object.assign({id:id},current),{});toast('Exposure monitoring record closed');expLoad();return;}if(!(await appConfirmDelete('exposure monitoring record','This record is already closed/archived. Permanent deletion should be used only for duplicate/test records.')))return;await api('/exposure_monitoring?id=eq.'+id,{m:'DELETE'});ohAudit('delete','Exposure monitoring record permanently deleted','exposure_monitoring',Object.assign({id:id},current),{});ohExpData=ohExpData.filter(x=>x.id!==id);toast('Deleted!');expLoad();}catch(e){toastActionError('Delete exposure monitoring record','Occupational Health',e);}}

// -- OCCUPATIONAL DISEASE ------------------------------------------------------
async function ohOdLoad(){
  var el=document.getElementById('oh-od-list');if(!el)return;el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/occupational_diseases?select=*'+cf()+'&order=created_at.desc');ohOdData=d||[];
    if(!d||!d.length){el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600;margin-bottom:8px">No occupational disease records</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0209"><i class="ti ti-plus"></i>Record disease</button>':'')+'</div>';return;}
    var outCfg={ongoing:['#FEF9EC','#854F0B'],recovered:['#EAF3DE','#3B6D11'],permanent_disability:['#FEF6E7','#C2410C'],under_treatment:['#EDE9FE','#7C3AED'],fatal:['#4C0519','#fff']};
    var expEmoji={noise:'*',dust:'*',silica:'*',chemical:'*',vibration:'*',heat:'*',biological:'*',ergonomic:'*',psychological:'*',radiation:'*',other:'*'};
    var h='<div class="table-scroll"><table class="data-table" style="min-width:1080px"><thead><tr><th>Employee</th><th>Ref</th><th>Disease / Condition</th><th>ICD-10</th><th>Exposure</th><th>Diagnosed</th><th>Days lost</th><th>Outcome</th><th style="width:50px"></th></tr></thead><tbody>';
    d.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';var oc=outCfg[x.outcome]||outCfg.ongoing;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +'<td style="padding:8px 14px"><div style="font-weight:700">'+escH(x.employee_name||'-')+'</div><div style="font-size:10px;color:var(--text2)">'+escH(x.department||x.job_title||'')+'</div></td>'
        +'<td style="padding:8px;font-family:monospace;color:#DC2626;font-size:11px;font-weight:700">'+escH(x.disease_ref||'-')+'</td>'
        +'<td style="padding:8px;font-weight:600;max-width:200px">'+escH(x.disease_type||'-')+'</td>'
        +'<td style="padding:8px;font-family:monospace;font-size:11px">'+escH(x.icd_code||'-')+'</td>'
        +'<td style="padding:8px;text-align:center">'+(expEmoji[x.exposure_type]||'*')+' <span style="font-size:11px">'+escH(x.causative_agent||x.exposure_type||'-')+'</span></td>'
        +'<td style="padding:8px;font-size:11px">'+(x.diagnosis_date?new Date(x.diagnosis_date).toLocaleDateString('en-GB'):'-')+'</td>'
        +'<td style="padding:8px;text-align:center;font-weight:700;color:'+(x.days_lost>30?'var(--red)':'inherit')+'">'+( x.days_lost||0)+'</td>'
        +'<td style="padding:8px"><span style="background:'+oc[0]+';color:'+oc[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;text-transform:capitalize">'+escH((x.outcome||'ongoing').replace(/_/g,' '))+'</span></td>'
        +'<td style="padding:8px"><div style="display:flex;gap:4px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0210"><i class="ti ti-edit"></i></button>'+(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0211"><i class="ti ti-trash"></i></button>':'')+'</div></td></tr>';
    });
    h+='</tbody></table></div>';el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

