async function ppeIssLoadReferenceOptions(selectedWO,selectedRA){
  var woSel=document.getElementById('pif-wo-ref');
  var raSel=document.getElementById('pif-ra-ref');
  if(woSel){
    woSel.innerHTML='<option value="">Select work order...</option>';
    try{
      var work=await api('/work_schedule?select=id,ref_number,title,status'+cf()+'&order=created_at.desc');
      (work||[]).forEach(function(w){
        var ref=w.ref_number||w.id;
        var o=document.createElement('option');
        o.value=ref;verifiedReferenceOption(o,w,ref,'work_schedule');o.textContent=ref+' - '+(w.title||'Work order')+(w.status?' ['+w.status+']':'');
        woSel.appendChild(o);
      });
    }catch(e){
      var wo=document.createElement('option');wo.value='';wo.textContent='Unable to load work orders';woSel.appendChild(wo);
    }
    if(selectedWO){woSel.value=selectedWO;if(woSel.value!==selectedWO){var savedWO=document.createElement('option');savedWO.value=selectedWO;savedWO.textContent=selectedWO+' (saved text)';woSel.appendChild(savedWO);woSel.value=selectedWO;}}
  }
  if(raSel){
    await fillRiskAssessmentSelect('pif-ra-ref',selectedRA);
  }
}

