async function ppeIssSave(){
  var emp=document.getElementById('pif-emp-name')?.value?.trim();if(!emp){toast('Please enter employee name',false);return;}
  var ppeSel=document.getElementById('pif-ppe-id');var ppeId=ppeSel?.value||null;
  var ppeName=ppeSel?.selectedOptions[0]?.text?.replace(/^[^ ]+ /,'')||document.getElementById('pif-ppe-name')?.value||'PPE';
  if(ppeId&&ppeSel?.selectedOptions[0]?.text?.includes('Select'))ppeName='PPE';
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var ppe=ppeCatData.find(x=>x.id===ppeId);
  var body={company_id:ccid(),ppe_id:ppeId||null,ppe_name:ppe?.name||ppeName,ppe_category:ppe?.category||null,employee_name:emp,employee_id:g('pif-emp-id'),department:g('pif-dept'),job_title:g('pif-title'),issued_date:g('pif-issued-date'),issued_by:g('pif-issued-by'),quantity:parseInt(g('pif-qty'))||1,size:g('pif-size'),serial_number:g('pif-serial'),batch_number:g('pif-batch'),condition_on_issue:g('pif-condition')||'new',manufacture_date:g('pif-mfg-date')||null,expiry_date:g('pif-expiry-date')||null,expected_replacement_date:g('pif-replace-date')||null,work_order_ref:g('pif-wo-ref'),ra_ref:g('pif-ra-ref'),hazard_ref:g('pif-hazard'),employee_signature:document.getElementById('pif-ack')?.checked||false,acknowledgement_date:g('pif-ack-date')||null,returned:document.getElementById('pif-returned')?.checked||false,return_date:g('pif-return-date')||null,return_condition:g('pif-return-condition')||null,return_reason:g('pif-return-reason'),notes:g('pif-notes'),status:g('pif-status')||'active',updated_at:new Date().toISOString()};Object.assign(body,personIdentityPayload(emp));body.issued_by_person_id=personFromValue(body.issued_by)?.id||null;body.work_order_id=verifiedReferenceSelection('pif-wo-ref').id;body.risk_assessment_id=verifiedReferenceSelection('pif-ra-ref').id;
  try{
    if(ppeIssEditId){await apiWriteWithMissingColumnFallback('/ppe_issuance?id=eq.'+ppeIssEditId,{m:'PATCH',p:'return=minimal',b:body},'PPE issuance');toast('Updated!');}
    else{
      body.created_by=prof?.id;var res=await apiWriteWithMissingColumnFallback('/ppe_issuance',{m:'POST',p:'return=representation',b:body},'PPE issuance');
      if(res?.[0]?.id){var yr=new Date().getFullYear();var ref=await ppeNextRef('ppe_issuance','issuance_ref','ISS-'+yr+'-');await api('/ppe_issuance?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{issuance_ref:ref}});toast('PPE issued! Ref: '+ref);
        // Update catalogue stock
        if(ppeId&&ppe){try{await api('/ppe_catalogue?id=eq.'+ppeId,{m:'PATCH',p:'return=minimal',b:{quantity_available:Math.max(0,(ppe.quantity_available||0)-1),quantity_issued:(ppe.quantity_issued||0)+1,updated_at:new Date().toISOString()}});}catch(ex){}}
      }
    }
    ppeIssBack();
  }catch(e){toastActionError('Save PPE issuance','PPE Management',e);}
}
function ppeIssRetired(x){return ['returned','expired','lost','condemned','archived'].includes(String(x?.status||'').toLowerCase())&&ohIsArchivedText(x?.notes);}
function ppeIssArchiveBody(x){var status=String(x?.status||'active').toLowerCase();return {status:status==='active'?'returned':(x?.status||'returned'),returned:true,return_date:x?.return_date||new Date().toISOString().slice(0,10),return_reason:x?.return_reason||'Archived instead of deleted',notes:ohArchivedText(x?.notes),updated_at:new Date().toISOString()};}
async function ppeIssDelete(){if(!ppeIssEditId)return;try{var rows=await api('/ppe_issuance?id=eq.'+ppeIssEditId+'&select=status,returned,return_date,return_reason,notes');var current=rows?.[0]||{};if(!ppeIssRetired(current)){if(!(await appConfirmAction({title:'Archive PPE issuance?',message:'This issuance will be marked returned/archived first so the PPE history remains available.',confirmText:'Archive',variant:'danger'})))return;await api('/ppe_issuance?id=eq.'+ppeIssEditId,{m:'PATCH',p:'return=minimal',b:ppeIssArchiveBody(current)});toast('PPE issuance archived. Use delete again if permanent removal is required.');ppeIssBack();return;}if(!(await appConfirmDelete('archived PPE issuance record permanently')))return;await api('/ppe_issuance?id=eq.'+ppeIssEditId,{m:'DELETE'});toast('Deleted!');ppeIssBack();}catch(e){toastActionError('Delete PPE issuance record','PPE Management',e);}}
async function ppeIssDeleteRow(id){try{var rows=await api('/ppe_issuance?id=eq.'+id+'&select=status,returned,return_date,return_reason,notes');var current=rows?.[0]||{};if(!ppeIssRetired(current)){if(!(await appConfirmAction({title:'Archive PPE issuance?',message:'This issuance will be marked returned/archived first so the PPE history remains available.',confirmText:'Archive',variant:'danger'})))return;await api('/ppe_issuance?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:ppeIssArchiveBody(current)});toast('PPE issuance archived. Use delete again if permanent removal is required.');ppeLoadIssuance();return;}if(!(await appConfirmDelete('archived PPE issuance record permanently')))return;await api('/ppe_issuance?id=eq.'+id,{m:'DELETE'});ppeIssData=ppeIssData.filter(x=>x.id!==id);toast('Deleted!');ppeLoadIssuance();}catch(e){toastActionError('Delete PPE issuance record','PPE Management',e);}}

