async function ppeLoadInspections(){
  var el=document.getElementById('ppe-insp-list');if(!el)return;el.innerHTML='<div class="loading-msg">Loading...</div>';
  var now=new Date();var d30=new Date();d30.setDate(d30.getDate()+30);
  try{
    var d=await api('/ppe_inspections?select=*'+cf()+'&order=inspection_date.desc');ppeInspData=d||[];
    var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
    setM('ppe-insp-pass',(d||[]).filter(x=>x.overall_result==='pass').length);
    setM('ppe-insp-fail',(d||[]).filter(x=>x.overall_result==='fail').length);
    setM('ppe-insp-cond',(d||[]).filter(x=>x.overall_result==='condemn').length);
    setM('ppe-insp-due',(d||[]).filter(x=>x.next_inspection_date&&new Date(x.next_inspection_date)<=d30).length);
    if(!d||!d.length){el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600;margin-bottom:8px">No PPE inspections recorded</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0218"><i class="ti ti-plus"></i>New inspection</button>':'')+'</div>';return;}
    var resCfg={pass:['#EAF3DE','#3B6D11','Pass'],fail:['#FCEBEB','#A32D2D','Fail'],condemn:['#4C0519','#fff','Condemn'],monitor:['#FEF9EC','#854F0B','Monitor']};
    var h='<div class="table-scroll"><table class="data-table" style="min-width:1080px"><thead><tr><th>Ref</th><th>PPE Item</th><th>Employee</th><th>Inspector</th><th>Date</th><th>Result</th><th>Action taken</th><th>Next insp.</th><th style="width:60px"></th></tr></thead><tbody>';
    d.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';var rc=resCfg[x.overall_result]||resCfg.pass;
      var isDue=x.next_inspection_date&&new Date(x.next_inspection_date)<=d30;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +'<td style="padding:8px 14px;font-family:monospace;font-size:11px;font-weight:700;color:#8B5CF6">'+escH(x.inspection_ref||'-')+'</td>'
        +'<td style="padding:8px;font-weight:600">'+escH(x.ppe_name||'-')+'</td>'
        +'<td style="padding:8px;font-size:11px">'+escH(x.employee_name||'-')+'</td>'
        +'<td style="padding:8px;font-size:11px">'+escH(x.inspector||'-')+'</td>'
        +'<td style="padding:8px;font-size:11px">'+(x.inspection_date?new Date(x.inspection_date).toLocaleDateString('en-GB'):'-')+'</td>'
        +'<td style="padding:8px"><span style="background:'+rc[0]+';color:'+rc[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+rc[2]+'</span></td>'
        +'<td style="padding:8px;font-size:11px;text-transform:capitalize">'+escH((x.action_taken||'-').replace(/_/g,' '))+'</td>'
        +'<td style="padding:8px;font-size:11px;font-weight:'+(isDue?'700':'400')+';color:'+(isDue?'var(--red)':'inherit')+'">'+(x.next_inspection_date?new Date(x.next_inspection_date).toLocaleDateString('en-GB')+(isDue?' ?':''):'-')+'</td>'
        +'<td style="padding:8px"><div style="display:flex;gap:4px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0219"><i class="ti ti-edit"></i></button>'+(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0220"><i class="ti ti-trash"></i></button>':'')+'</div></td></tr>';
    });
    h+='</tbody></table></div>';el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

function ppeInspSelectItem(){
  var sel=document.getElementById('piif-ppe-id');if(!sel)return;
  var ppeId=sel.value;var ppe=ppeCatData.find(x=>x.id===ppeId);if(!ppe)return;
  // Build category-specific checklist
  var checklistItems=PPE_INSP_CHECKLISTS[ppe.category]||PPE_INSP_CHECKLISTS.other;
  var el=document.getElementById('piif-checklist');if(!el)return;
  el.innerHTML=checklistItems.map(function(item,i){
    return '<div style="display:flex;align-items:flex-start;gap:10px;padding:8px 6px;border-bottom:1px solid #f5f5f5">'
      +'<div style="display:flex;gap:8px;flex-shrink:0;margin-top:2px">'
      +'<label style="cursor:pointer;display:inline-flex;align-items:center;gap:4px"><input type="radio" name="chk-'+i+'" value="pass" style="width:auto;accent-color:var(--green)" checked> <span style="font-size:11px;color:#1D9E75;font-weight:600">Pass</span></label>'
      +'<label style="cursor:pointer;display:inline-flex;align-items:center;gap:4px"><input type="radio" name="chk-'+i+'" value="fail" style="width:auto;accent-color:var(--red)"> <span style="font-size:11px;color:var(--red);font-weight:600">Fail</span></label>'
      +'<label style="cursor:pointer;display:inline-flex;align-items:center;gap:4px"><input type="radio" name="chk-'+i+'" value="na" style="width:auto"> <span style="font-size:11px;color:var(--text2);font-weight:600">N/A</span></label>'
      +'</div>'
      +'<div style="flex:1"><div style="font-size:12px">'+escH(item)+'</div></div>'
      +'</div>';
  }).join('');
  // Auto set next inspection date
  var interval=ppe.inspection_interval_days||90;
  var nd=document.getElementById('piif-next-date');if(nd){var d=new Date();d.setDate(d.getDate()+interval);nd.value=d.toISOString().slice(0,10);}
}

function ppeInspShowForm(){document.getElementById('ppe-view-inspections').style.display='none';document.getElementById('ppe-insp-form').style.display='block';}
function ppeInspBack(){document.getElementById('ppe-insp-form').style.display='none';document.getElementById('ppe-view-inspections').style.display='block';document.querySelectorAll('[id^="ppe-tab-"]').forEach(t=>t.classList.remove('active'));document.getElementById('ppe-tab-inspections')?.classList.add('active');ppeLoadInspections();}

