// -- EXPIRY ALERTS -------------------------------------------------------------
function ppeExpiryFilter(days,btn){
  ppeExpiryDays=days;
  document.querySelectorAll('[id^="ppe-exp-btn-"]').forEach(b=>{b.style.background='';b.style.color='';b.style.borderColor='';});
  if(btn){btn.style.background='#DC2626';btn.style.color='#fff';btn.style.borderColor='#DC2626';}
  ppeLoadExpiry();
}

async function ppeLoadExpiry(){
  var el=document.getElementById('ppe-expiry-list');if(!el)return;el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/ppe_issuance?select=*'+cf()+'&order=expiry_date.asc');
    var now=new Date();var cutoff=new Date();if(ppeExpiryDays>0)cutoff.setDate(cutoff.getDate()+ppeExpiryDays);
    var filtered;
    if(ppeExpiryDays===0){filtered=(d||[]).filter(x=>x.status==='active');}
    else{filtered=(d||[]).filter(function(x){
      var expDate=x.expiry_date?new Date(x.expiry_date):null;
      var repDate=x.expected_replacement_date?new Date(x.expected_replacement_date):null;
      return x.status==='active'&&((expDate&&expDate<=cutoff)||(repDate&&repDate<=cutoff));
    });}
    if(!filtered.length){el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-check"></i></div><div style="font-weight:600;margin-bottom:8px">No PPE expiring in this window</div><div style="font-size:13px;color:var(--text2)">All active PPE is within its service life</div></div>';return;}
    var h='<div class="table-scroll"><table class="data-table" style="min-width:1080px"><thead><tr><th>Priority</th><th>Ref</th><th>PPE Item</th><th>Employee</th><th>Dept</th><th>Issued</th><th>Expiry date</th><th>Replace by</th><th>Action</th></tr></thead><tbody>';
    filtered.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';
      var expDate=x.expiry_date?new Date(x.expiry_date):null;var repDate=x.expected_replacement_date?new Date(x.expected_replacement_date):null;
      var earliest=expDate&&repDate?new Date(Math.min(expDate,repDate)):expDate||repDate||new Date(9999,0,1);
      var daysLeft=Math.ceil((earliest-now)/86400000);
      var urgency=daysLeft<0?'EXPIRED':daysLeft<=7?'CRITICAL':daysLeft<=30?'URGENT':daysLeft<=60?'HIGH':'PLANNED';
      var urgColor={EXPIRED:'#4C0519',CRITICAL:'#A32D2D',URGENT:'#C2410C',HIGH:'#854F0B',PLANNED:'#3B6D11'};
      var urgBg={EXPIRED:'#4C0519',CRITICAL:'#FCEBEB',URGENT:'#FEF6E7',HIGH:'#FEF9EC',PLANNED:'#EAF3DE'};
      var urgText={EXPIRED:'#fff',CRITICAL:'#A32D2D',URGENT:'#C2410C',HIGH:'#854F0B',PLANNED:'#3B6D11'};
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +'<td style="padding:8px 14px"><div style="background:'+urgBg[urgency]+';color:'+urgText[urgency]+';padding:3px 10px;border-radius:99px;font-size:10px;font-weight:700;text-align:center">'+urgency+'</div>'
        +(daysLeft<0?'<div style="font-size:10px;color:#A32D2D;font-weight:700;text-align:center">'+Math.abs(daysLeft)+'d ago</div>':'<div style="font-size:10px;color:var(--text2);text-align:center">'+daysLeft+'d left</div>')
        +'</td>'
        +'<td style="padding:8px;font-family:monospace;font-size:11px;font-weight:700;color:#DC2626">'+escH(x.issuance_ref||'-')+'</td>'
        +'<td style="padding:8px;font-weight:600">'+escH(x.ppe_name||'-')+'</td>'
        +'<td style="padding:8px"><div style="font-weight:600">'+escH(x.employee_name||'-')+'</div><div style="font-size:10px;color:var(--text2)">'+escH(x.employee_id||'')+'</div></td>'
        +'<td style="padding:8px;font-size:11px">'+escH(x.department||'-')+'</td>'
        +'<td style="padding:8px;font-size:11px">'+(x.issued_date?new Date(x.issued_date).toLocaleDateString('en-GB'):'-')+'</td>'
        +'<td style="padding:8px;font-size:11px;font-weight:700;color:'+( expDate&&expDate<=now?'#A32D2D':'inherit')+'">'+(expDate?expDate.toLocaleDateString('en-GB')+(expDate<=now?' EXPIRED':''):'-')+'</td>'
        +'<td style="padding:8px;font-size:11px;font-weight:700;color:'+(repDate&&repDate<=now?'#C2410C':'inherit')+'">'+(repDate?repDate.toLocaleDateString('en-GB')+(repDate<=now?' DUE':''):'-')+'</td>'
        +'<td style="padding:8px"><button class="btn btn-sm btn-primary" style="font-size:10px;padding:3px 8px" data-auris-runtime-onclick="r0086" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id,x.employee_name,x.ppe_name]))+'"><i class="ti ti-refresh"></i>Replace</button></td>'
        +'</tr>';
    });
    h+='</tbody></table></div>';el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

async function ppeQuickReplace(issId,empName,ppeName){
  // Pre-fill a replacement request and jump to the replacements tab
  await ppePopulatePPESelects();
  var iss=ppeIssData.find(x=>x.id===issId);
  var tab=document.getElementById('ppe-tab-replacements');
  ppeSwitchTab('replacements',tab);
  setTimeout(function(){
    ppeRepNew().then(function(){
      fillPersonSelect('prf-emp-name',empName||'');
      document.getElementById('prf-dept').value=iss?.department||'';
      document.getElementById('prf-reason').value='expiry';
      document.getElementById('prf-urgency').value='urgent';
      if(iss?.ppe_id){document.getElementById('prf-ppe-id').value=iss.ppe_id;}
      toast('Replacement request pre-filled for '+ppeName+' - '+empName+'. Review and save.');
    });
  },300);
}

