function toolsChecklistKey(tool,category){
  var text=[tool?.name,tool?.ref_number,tool?.model,tool?.notes,category].join(' ').toLowerCase();
  if(/ladder|step\s*ladder|stepladder|extension\s*ladder|platform\s*ladder|portable\s*ladder/.test(text))return 'ladder';
  if(category==='lifting'||/sling|shackle|chain block|chainblock|lifting|hoist|crane|eyebolt|webbing/.test(text))return 'lifting';
  if(category==='electrical'||/rcd|extension lead|generator|electrical|cable|plug/.test(text))return 'electrical';
  if(category==='power_tool'||/grinder|drill|saw|breaker|sander|cutting tool/.test(text))return 'power_tool';
  if(category==='vehicle'||/vehicle|forklift|truck|van|car/.test(text))return 'vehicle';
  if(category==='hand_tool')return 'hand_tool';
  return '';
}

function toolsInspectionIntervalDays(freq){
  return {daily:1,weekly:7,monthly:31,quarterly:92,six_monthly:183,annual:366,yearly:366}[freq||'']||30;
}

function toolsInspectionState(x,today){
  var last=toolsLastInspectionByTool[x.id];
  var dt=last&&last.inspection_date?new Date(last.inspection_date):null;
  var interval=toolsInspectionIntervalDays(x.inspection_frequency||'monthly');
  if(!dt)return {last:null,days:999,due:true,soon:false,label:'Never inspected'};
  var days=Math.floor((today-dt)/(1000*60*60*24));
  return {last:dt,days:days,due:days>interval,soon:days>Math.max(1,interval-7)&&days<=interval,label:days+' days ago'};
}

function toolsSwitchTab(tab,btn){
  document.querySelectorAll('[id^="tools-tab-"]').forEach(function(t){t.classList.remove('active');});
  if(btn)btn.classList.add('active');
  ['register','personal','inspection','lifting','statutory','vehicles','rcd'].forEach(function(t){
    var el=document.getElementById('tools-view-'+t);if(el)el.style.display=t===tab?'block':'none';
  });
  ['tools-form','tools-insp-form','tools-rcd-form'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});
  if(tab==='register')toolsLoadRegister();
  else if(tab==='personal')toolsLoadPersonal();
  else if(tab==='inspection')toolsLoadInspections();
  else if(tab==='lifting')toolsLoadLiftingAccessories();
  else if(tab==='statutory')toolsLoadStatutory();
  else if(tab==='vehicles')toolsLoadVehicles();
  else if(tab==='rcd')toolsLoadRCD();
}

