function toolsNew(){
  toolsEditingId=null;
  document.getElementById('tools-form3title').textContent='New Equipment';
  document.getElementById('tools-form3ref').textContent='';
  document.getElementById('tools-del-btn').style.display='none';
  document.getElementById('teq-ref-display').textContent='AUTO';
  ['teq-name','teq-brand','teq-model','teq-serial','teq-location','teq-notes','teq-reg','teq-stat-type','teq-stat-body'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['teq-purchase-date','teq-insurance','teq-roadworthy','teq-stat-last','teq-stat-next'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var cat=document.getElementById('teq-cat');if(cat)cat.value='hand_tool';
  var st=document.getElementById('teq-status');if(st)st.value='active';
  var fr=document.getElementById('teq-freq');if(fr)fr.value='weekly';
  var as=document.getElementById('teq-assigned');if(as){as.innerHTML='<option value="">General use</option>';(people||[]).forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.last_name+', '+p.first_name+(p.job_title?' - '+p.job_title:'');as.appendChild(o);});}
  var stc=document.getElementById('teq-statutory');if(stc)stc.checked=false;
  document.getElementById('teq-statutory-fields').style.display='none';
  document.getElementById('teq-vehicle-section').style.display='none';
  toolsShowForm();
}

function toolsEdit(id){
  var x=toolsAllData.find(function(r){return r.id===id;});
  if(!x)return;
  toolsEditingId=id;
  document.getElementById('tools-form3title').textContent='Edit Equipment';
  document.getElementById('tools-form3ref').textContent=x.ref_number||'';
  document.getElementById('tools-del-btn').style.display=isMgr()?'inline-flex':'none';
  document.getElementById('teq-ref-display').textContent=x.ref_number||'AUTO';
  var flds={'teq-name':'name','teq-brand':'brand','teq-model':'model','teq-serial':'serial_number','teq-location':'location','teq-notes':'notes','teq-reg':'registration_number','teq-stat-type':'statutory_type','teq-stat-body':'statutory_body'};
  Object.entries(flds).forEach(function(e){var el=document.getElementById(e[0]);if(el)el.value=x[e[1]]||'';});
  ['teq-purchase-date','teq-stat-last','teq-stat-next'].forEach(function(id){
    var key={'teq-purchase-date':'purchase_date','teq-stat-last':'last_statutory_date','teq-stat-next':'next_statutory_date'}[id];
    var el=document.getElementById(id);if(el)el.value=x[key]||'';
  });
  var cat=document.getElementById('teq-cat');if(cat)cat.value=x.category||'hand_tool';
  var st=document.getElementById('teq-status');if(st)st.value=x.status||'active';
  var fr=document.getElementById('teq-freq');if(fr)fr.value=x.inspection_frequency||'weekly';
  var as=document.getElementById('teq-assigned');
  if(as){as.innerHTML='<option value="">General use</option>';(people||[]).forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.last_name+', '+p.first_name+(p.job_title?' - '+p.job_title:'');as.appendChild(o);});as.value=x.assigned_to||'';}
  var stc=document.getElementById('teq-statutory');if(stc)stc.checked=!!x.requires_statutory;
  document.getElementById('teq-statutory-fields').style.display=x.requires_statutory?'block':'none';
  document.getElementById('teq-vehicle-section').style.display=x.category==='vehicle'?'block':'none';
  toolsShowForm();
}

function toolsCatChange(){
  var cat=document.getElementById('teq-cat')?.value;
  document.getElementById('teq-vehicle-section').style.display=cat==='vehicle'?'block':'none';
  if(cat==='vehicle'||cat==='lifting'){
    var stc=document.getElementById('teq-statutory');
    if(stc&&!stc.checked){stc.checked=true;document.getElementById('teq-statutory-fields').style.display='block';}
  }
  var freq=document.getElementById('teq-freq');
  if(freq&&cat==='vehicle')freq.value='monthly';
}

function toolsStatutoryChange(){
  var checked=document.getElementById('teq-statutory')?.checked;
  document.getElementById('teq-statutory-fields').style.display=checked?'block':'none';
}

function toolsShowForm(){
  ['tools-view-register','tools-view-personal','tools-view-inspection','tools-view-lifting','tools-view-statutory','tools-view-vehicles','tools-view-rcd'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});
  document.getElementById('tools-insp-form').style.display='none';
  var rcdForm=document.getElementById('tools-rcd-form');if(rcdForm)rcdForm.style.display='none';
  document.getElementById('tools-form').style.display='block';
}

function toolsFormBack(){
  document.getElementById('tools-form').style.display='none';
  document.getElementById('tools-view-register').style.display='block';
  document.querySelectorAll('[id^="tools-tab-"]').forEach(function(t){t.classList.remove('active');});
  var tab=document.getElementById('tools-tab-register');if(tab)tab.classList.add('active');
  toolsLoadRegister();
}

async function toolsSaveEquipment(){
  var name=document.getElementById('teq-name')?.value?.trim();
  if(!name){toast('Please enter a name',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var cat=g('teq-cat')||'hand_tool';
  var personId=g('teq-assigned');
  var personName='';
  if(personId){var p=(people||[]).find(function(x){return x.id===personId;});personName=p?(p.last_name+', '+p.first_name):'';}
  var body={
    company_id:ccid(),category:cat,name:name,
    brand:g('teq-brand'),model:g('teq-model'),serial_number:g('teq-serial'),
    location:g('teq-location'),assigned_to:personId||null,assigned_to_name:personName||null,
    status:g('teq-status')||'active',inspection_frequency:g('teq-freq')||'weekly',
    purchase_date:g('teq-purchase-date'),
    is_vehicle:cat==='vehicle',registration_number:g('teq-reg'),
    requires_statutory:document.getElementById('teq-statutory')?.checked||false,
    statutory_type:g('teq-stat-type'),last_statutory_date:g('teq-stat-last'),
    next_statutory_date:g('teq-stat-next'),statutory_body:g('teq-stat-body'),
    notes:g('teq-notes'),updated_at:new Date().toISOString()
  };
  try{
    if(toolsEditingId){
      await api('/tools_register?id=eq.'+toolsEditingId,{m:'PATCH',p:'return=minimal',b:body});
      toast('Equipment updated!');
    }else{
      // Generate ref number via Supabase function
      body.created_by=prof?.id;
      var res=await api('/tools_register',{m:'POST',p:'return=representation',b:body});
      if(res?.[0]?.id){
        // Update with generated ref
        try{
          var refRes=await api('/rpc/generate_tool_ref',{m:'POST',b:{cat:cat}});
          if(refRes){await api('/tools_register?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{ref_number:refRes}});}
        }catch(ex){console.warn('Ref gen failed',ex);}
        toast('Equipment added! Ref: '+(refRes||res[0].ref_number||''));
      }
    }
    toolsFormBack();
  }catch(e){toastActionError('Save equipment','Tools & Equipment',e);console.error(e);}
}

async function toolsDelete(){
  if(!toolsEditingId)return;
  try{var rows=await api('/tools_register?id=eq.'+toolsEditingId+'&select=status,notes');var current=rows?.[0]||{};var status=String(current.status||'active').toLowerCase();if(status!=='out_of_service'&&!ohIsArchivedText(current.notes)){if(!(await appConfirmAction({title:'Take equipment out of service?',message:'Take this equipment out of service instead of deleting it?',detail:'Equipment history should remain available for inspection, assignment and maintenance traceability.',confirmText:'Out of service',cancelText:'Back',variant:'danger'})))return;await api('/tools_register?id=eq.'+toolsEditingId,{m:'PATCH',p:'return=minimal',b:{status:'out_of_service',notes:ohArchivedText(current.notes),updated_at:new Date().toISOString()}});toast('Equipment marked out of service. Use delete again if permanent removal is required.');toolsFormBack();return;}if(!(await appConfirmDelete('equipment','This equipment is already out of service/archived. Permanent deletion should be used only for duplicate/test records.')))return;await api('/tools_register?id=eq.'+toolsEditingId,{m:'DELETE'});toast('Deleted!');toolsFormBack();}
  catch(e){toastActionError('Delete equipment','Tools & Equipment',e);}
}

async function toolsDeleteFromList(id){
  try{
    var current=toolsAllData.find(x=>x.id===id)||{};var status=String(current.status||'active').toLowerCase();if(status!=='out_of_service'&&!ohIsArchivedText(current.notes)){if(!(await appConfirmAction({title:'Take equipment out of service?',message:'Take this equipment out of service instead of deleting it?',detail:'Equipment history should remain available for inspection, assignment and maintenance traceability.',confirmText:'Out of service',cancelText:'Back',variant:'danger'})))return;await api('/tools_register?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{status:'out_of_service',notes:ohArchivedText(current.notes),updated_at:new Date().toISOString()}});toast('Equipment marked out of service. Use delete again if permanent removal is required.');toolsLoadRegister();return;}
    if(!(await appConfirmDelete('equipment','This equipment is already out of service/archived. Permanent deletion should be used only for duplicate/test records.')))return;
    await api('/tools_register?id=eq.'+id,{m:'DELETE'});
    toolsAllData=toolsAllData.filter(x=>x.id!==id);
    toast('Deleted!');toolsFilterRegister();
  }catch(e){toastActionError('Delete equipment','Tools & Equipment',e);}
}

// -- PERSONAL TOOLS -----------------------------------------------------------
async function toolsLoadPersonal(){
  var el=document.getElementById('tools-personal-list');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  // Populate filter dropdown
  var sel=document.getElementById('tools-personal-filter');
  if(sel&&sel.options.length<=1){
    sel.innerHTML='<option value="">All employees</option>';
    (people||[]).forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.last_name+', '+p.first_name;sel.appendChild(o);});
  }
  var personFilter=document.getElementById('tools-personal-filter')?.value||'';
  try{
    var q='/tools_register?select=*'+cf()+'&order=assigned_to_name,name';
    if(personFilter)q+='&assigned_to=eq.'+personFilter;
    else q+='&assigned_to=not.is.null';
    var d=await api(q);
    var assigned=d||[];
    if(!assigned.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">No personal tool assignments found.<br><br>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0224"><i class="ti ti-plus"></i>Add equipment and assign to a person</button>':'')+'</div>';
      return;
    }
    // Group by person
    var byPerson={};
    assigned.forEach(function(x){var k=x.assigned_to_name||'Unknown';if(!byPerson[k])byPerson[k]=[];byPerson[k].push(x);});
    var html='';
    Object.entries(byPerson).forEach(function(e){
      var person=e[0],tools=e[1];
      html+='<div class="card" style="margin:0 0 12px 0">';
      html+='<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">'
        +'<div style="display:flex;align-items:center;gap:10px">'
        +'<div style="width:40px;height:40px;border-radius:50%;background:var(--green);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:14px">'+person.charAt(0)+'</div>'
        +'<div><div style="font-weight:700;font-size:14px">'+escH(person)+'</div>'
        +'<div style="font-size:11px;color:var(--text2)">'+tools.length+' tool'+(tools.length!==1?'s':'')+' assigned - weekly self-check required</div>'
        +'</div></div>'
        +'<button class="btn btn-sm btn-primary" style="font-size:11px" data-auris-runtime-onclick="r0087" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([person]))+'"><i class="ti ti-clipboard-check"></i>Weekly check</button>'
        +'</div>';
      html+='<table style="width:100%;border-collapse:collapse;font-size:12px">'
        +'<thead><tr style="background:#f9fafb"><th style="'+TOOLS_TH_STYLE_LIGHT+'">Ref</th>'
        +'<th style="'+TOOLS_TH_STYLE_LIGHT+'">Equipment</th>'
        +'<th style="'+TOOLS_TH_STYLE_LIGHT+'">Category</th>'
        +'<th style="'+TOOLS_TH_STYLE_LIGHT+'">Frequency</th>'
        +'<th style="'+TOOLS_TH_STYLE_LIGHT+'">Status</th>'
        +'</tr></thead><tbody>';
      tools.forEach(function(t,ti){
        var bg=ti%2===0?'#fff':'#fafafa';
        html+='<tr style="border-bottom:1px solid #f5f5f5;background:'+bg+'">'
          +'<td style="padding:7px 12px;font-family:monospace;font-weight:700;color:var(--green)">'+escH(t.ref_number||'-')+'</td>'
          +'<td style="padding:7px 12px;font-weight:600">'+escH(t.name||'-')+'</td>'
          +'<td style="padding:7px 12px">'+escH(TOOL_CAT_LABELS[t.category]||t.category)+'</td>'
          +'<td style="padding:7px 12px;text-transform:capitalize">'+escH(t.inspection_frequency||'weekly')+'</td>'
          +'<td style="padding:7px 12px"><span style="background:'+(t.status==='active'?'#EAF3DE':'#FCEBEB')+';color:'+(t.status==='active'?'#3B6D11':'#A32D2D')+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+escH(t.status||'active')+'</span></td>'
          +'</tr>';
      });
      html+='</tbody></table></div>';
    });
    el.innerHTML=html;
  }catch(err){el.innerHTML=registerErrorHtml('register',err.message);}
}

function toolsStartPersonalCheck(personName){
  // Switch to inspection tab and filter by person
  document.querySelectorAll('[id^="tools-tab-"]').forEach(function(t){t.classList.remove('active');});
  var btn=document.getElementById('tools-tab-inspection');if(btn)btn.classList.add('active');
  ['register','personal','lifting','statutory','vehicles','rcd'].forEach(function(t){var el=document.getElementById('tools-view-'+t);if(el)el.style.display='none';});
  var insp=document.getElementById('tools-view-inspection');if(insp)insp.style.display='block';
  toolsLoadInspections();
}

// -- INSPECTIONS --------------------------------------------------------------
async function toolsLoadInspections(){
  var el=document.getElementById('tools-insp-list');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/tool_inspections?select=*,tools_register(name,ref_number,category)'+cf()+'&order=inspection_date.desc&limit=100');
    if(!d||!d.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">No inspections recorded yet.'+(isMgr()?' <button class="btn btn-primary btn-sm" data-auris-generated-onclick="g0228"><i class="ti ti-plus"></i>New inspection</button>':'')+'</div>';
      return;
    }
    var h='<div class="table-scroll"><table class="data-table" style="min-width:860px"><thead><tr>'
      +'<th>Date</th>'
      +'<th>Equipment</th>'
      +'<th>Ref</th>'
      +'<th>Type</th>'
      +'<th>Inspector</th>'
      +'<th>Result</th>'
      +'<th style="width:60px"></th>'
      +'</tr></thead><tbody>';
    d.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';
      var dt=x.inspection_date?new Date(x.inspection_date).toLocaleDateString('en-GB'):'-';
      var res=x.overall_result;
      var resCfg={pass:['#EAF3DE','#3B6D11','Pass'],conditional:['#FEF9EC','#854F0B','Conditional'],fail:['#FCEBEB','#A32D2D','Fail']};
      var rc=resCfg[res]||resCfg.pass;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +'<td style="padding:8px 12px;font-weight:600">'+dt+'</td>'
        +'<td style="padding:8px 10px">'+escH(x.tools_register?.name||'-')+'</td>'
        +'<td style="padding:8px 10px;font-family:monospace;font-size:11px;color:var(--green);font-weight:700">'+escH(x.tools_register?.ref_number||'-')+'</td>'
        +'<td style="padding:8px 10px;text-transform:capitalize;font-size:11px">'+escH((x.inspection_type||'').replace(/_/g,' '))+'</td>'
        +'<td style="padding:8px 10px">'+escH(x.inspected_by_name||'-')+'</td>'
        +'<td style="padding:8px 10px;text-align:center"><span style="background:'+rc[0]+';color:'+rc[1]+';padding:3px 10px;border-radius:99px;font-size:11px;font-weight:700">'+rc[2]+'</span></td>'
        +'<td style="padding:8px 10px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0229"><i class="ti ti-eye"></i></button></td>'
        +'</tr>';
    });
    h+='</tbody></table></div>';
    if(el)el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

async function toolsLoadLiftingAccessories(){
  var el=document.getElementById('tools-lifting-list');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading lifting accessories...</div>';
  try{
    var res=await Promise.all([
      api('/tools_register?category=eq.lifting'+cf()+'&order=name&select=*'),
      api('/tool_inspections?select=*'+cf()+'&order=inspection_date.desc&limit=500')
    ]);
    toolsLiftingData=res[0]||[];
    var inspections=res[1]||[];
    var lastByTool={};
    inspections.forEach(function(x){if(x.tool_id&&!lastByTool[x.tool_id])lastByTool[x.tool_id]=x;});
    if(!toolsLiftingData.length){
      el.innerHTML='<div style="text-align:center;padding:42px;color:var(--text2)">'
        +'<div style="font-size:42px;margin-bottom:10px"><i class="ti ti-crane"></i></div>'
        +'<div style="font-weight:800;color:var(--text);margin-bottom:6px">No lifting accessories registered</div>'
        +'<div style="font-size:12px;margin-bottom:14px">Add slings, shackles, chain blocks, lifting beams, hooks or other lifting accessories, then inspect them here.</div>'
        +(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0230"><i class="ti ti-plus"></i>Add lifting accessory</button>':'')
        +'</div>';
      return;
    }
    var today=new Date();today.setHours(0,0,0,0);
    var soon=new Date(today);soon.setDate(soon.getDate()+14);
    var total=toolsLiftingData.length, due=0, failed=0, ok=0;
    toolsLiftingData.forEach(function(x){
      var last=lastByTool[x.id];
      var result=last?.overall_result||'not_inspected';
      if(result==='fail')failed++;
      else if(result==='pass')ok++;
      var next=last?.next_inspection_date?new Date(last.next_inspection_date):null;
      if(!next||next<=soon)due++;
    });
    var h='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px">'
      +toolsMiniMetric('Accessories',total,'#8B5CF6')
      +toolsMiniMetric('Passed',ok,'#1D9E75')
      +toolsMiniMetric('Due soon',due,'#EF9F27')
      +toolsMiniMetric('Failed',failed,'#E24B4A')
      +'</div>';
    h+='<div class="table-scroll"><table class="data-table" style="min-width:1120px">'
      +'<thead><tr>'
      +'<th>Ref</th>'
      +'<th>Lifting accessory</th>'
      +'<th>SWL / model</th>'
      +'<th>Serial no.</th>'
      +'<th>Location</th>'
      +'<th>Last inspection</th>'
      +'<th>Next due</th>'
      +'<th>Result</th>'
      +'<th style="text-align:right">Actions</th>'
      +'</tr></thead><tbody>';
    toolsLiftingData.forEach(function(x,i){
      var last=lastByTool[x.id];
      var next=last?.next_inspection_date?new Date(last.next_inspection_date):null;
      var lastDt=last?.inspection_date?new Date(last.inspection_date):null;
      var overdue=!next||next<today;
      var dueSoon=next&&next>=today&&next<=soon;
      var result=last?.overall_result||'not_inspected';
      var cfg={pass:['#EAF3DE','#3B6D11','Pass'],conditional:['#FEF9EC','#854F0B','Conditional'],fail:['#FCEBEB','#A32D2D','Fail'],not_inspected:['#f3f4f6','#6B7280','No inspection']};
      var rc=cfg[result]||cfg.not_inspected;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+(i%2?'#fafafa':'#fff')+(result==='fail'?';border-left:4px solid var(--red)':overdue?';border-left:4px solid #C2410C':dueSoon?';border-left:4px solid #EF9F27':'')+'">'
        +'<td style="padding:10px 12px;font-family:monospace;font-weight:800;color:#8B5CF6">'+escH(x.ref_number||'--')+'</td>'
        +'<td style="padding:10px 12px"><div style="font-weight:900">'+escH(x.name||'--')+'</div><div style="font-size:11px;color:var(--text2)">'+escH(x.brand||'')+'</div></td>'
        +'<td style="padding:10px 12px">'+escH(x.model||x.statutory_type||'--')+'</td>'
        +'<td style="padding:10px 12px">'+escH(x.serial_number||'--')+'</td>'
        +'<td style="padding:10px 12px">'+escH(x.location||'--')+'</td>'
        +'<td style="padding:10px 12px">'+(lastDt?lastDt.toLocaleDateString('en-GB'):'Never')+'</td>'
        +'<td style="padding:10px 12px;'+(overdue?'color:#C2410C;font-weight:800':dueSoon?'color:#854F0B;font-weight:800':'')+'">'+(next?next.toLocaleDateString('en-GB'):'Due now')+(overdue?' overdue':dueSoon?' due soon':'')+'</td>'
        +'<td style="padding:10px 12px;text-align:center"><span style="background:'+rc[0]+';color:'+rc[1]+';padding:3px 10px;border-radius:99px;font-size:11px;font-weight:800">'+rc[2]+'</span></td>'
        +'<td style="padding:10px 12px;text-align:right;white-space:nowrap">'+(isMgr()?'<button class="btn btn-sm btn-primary" data-id="'+x.id+'" data-auris-generated-onclick="g0231"><i class="ti ti-clipboard-check"></i>Inspect</button> ':'')+'<button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0232"><i class="ti ti-edit"></i></button></td>'
        +'</tr>';
    });
    h+='</tbody></table></div>';
    el.innerHTML=h;
  }catch(e){
    el.innerHTML=registerErrorHtml('register',e.message);
  }
}

function toolsMiniMetric(label,value,color){
  return '<div class="card" style="padding:12px 14px;border-left:4px solid '+color+'"><div style="font-size:10px;color:var(--text2);font-weight:800;text-transform:uppercase;margin-bottom:2px">'+escH(label)+'</div><div style="font-size:24px;font-weight:900;color:'+color+'">'+escH(value)+'</div></div>';
}

function toolsNewLiftingAccessory(){
  toolsNew();
  var cat=document.getElementById('teq-cat');if(cat){cat.value='lifting';toolsCatChange();}
  var freq=document.getElementById('teq-freq');if(freq)freq.value='monthly';
  var name=document.getElementById('teq-name');if(name&&!name.value)name.placeholder='e.g. Web sling 2T, shackle, chain block';
  var model=document.getElementById('teq-model');if(model&&!model.value)model.placeholder='SWL / WLL, size or model';
  var stat=document.getElementById('teq-statutory');if(stat){stat.checked=true;toolsStatutoryChange();}
  var statType=document.getElementById('teq-stat-type');if(statType&&!statType.value)statType.value='Lifting accessory thorough examination';
}

async function toolsStartLiftingInspection(toolId){
  await toolsStartInspection(toolId,'lifting');
  var type=document.getElementById('insp-type');if(type)type.value='lifting_accessory';
}

async function toolsNewInspection(){
  // Show equipment picker first
  var id=await appPrompt({title:'Start inspection',message:'Enter equipment Ref No. or name to inspect.',placeholder:'Ref No. or equipment name'});
  if(!id)return;
  var found=toolsAllData.find(function(x){return (x.ref_number||'').toLowerCase()===id.toLowerCase()||(x.name||'').toLowerCase().includes(id.toLowerCase());});
  if(!found){toast('Equipment not found. Please check the register.',false);return;}
  toolsStartInspection(found.id);
}

async function toolsStartInspection(toolId,returnTab){
  toolsInspectionReturnTab=returnTab||'inspection';
  var tool=toolsAllData.find(x=>x.id===toolId)||toolsLiftingData.find(x=>x.id===toolId);
  if(!tool&&toolId){try{var d=await api('/tools_register?id=eq.'+toolId+'&select=*');tool=d?.[0];}catch(e){}}
  if(!tool){toast('Equipment not found',false);return;}
  toolsInspEquipId=toolId;
  toolsInspEditingId=null;
  // Set header info
  document.getElementById('insp-equip-name').textContent=tool.name||'-';
  document.getElementById('insp-equip-ref').textContent=tool.ref_number||'';
  document.getElementById('tools-insp-form3title').textContent='Inspection - '+escH(tool.name||'');
  document.getElementById('tools-insp-form3sub').textContent=(tool.ref_number||'')+(tool.location?' - '+tool.location:'');
  // Set date to today
  var dt=document.getElementById('insp-date');if(dt)dt.value=new Date().toISOString().slice(0,10);
  // Inspector dropdown
  var insp=document.getElementById('insp-inspector');
  if(insp){insp.innerHTML='<option value="">Select inspector...</option>';(people||[]).forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.last_name+', '+p.first_name;insp.appendChild(o);});}
  // Set next inspection based on frequency
  var nextDate=new Date();
  var freqDays={daily:1,weekly:7,monthly:30,quarterly:90,annual:365};
  var days=freqDays[tool.inspection_frequency]||7;
  nextDate.setDate(nextDate.getDate()+days);
  var nd=document.getElementById('insp-next-date');if(nd)nd.value=nextDate.toISOString().slice(0,10);
  // Load checklist
  await toolsLoadChecklist(tool.category,tool);
  // Show form
  ['tools-view-register','tools-view-personal','tools-view-inspection','tools-view-lifting','tools-view-statutory','tools-view-vehicles','tools-view-rcd'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});
  document.getElementById('tools-form').style.display='none';
  document.getElementById('tools-insp-form').style.display='block';
}

async function toolsLoadChecklist(category,tool){
  var tbody=document.getElementById('insp-checklist-body');
  if(!tbody)return;
  try{
    var checklistKey=toolsChecklistKey(tool,category);
    var items=(checklistKey&&TOOL_INSPECTION_CHECKLISTS[checklistKey])
      ? TOOL_INSPECTION_CHECKLISTS[checklistKey].map(function(x){return {check_item:x};})
      : [];
    if(!items||!items.length){
      try{
        items=await api('/tool_checklist_templates?category=eq.'+encodeURIComponent(category||'other')+'&order=sort_order');
      }catch(ex){
        console.warn('Tool checklist template unavailable:',ex.message);
        items=[];
      }
    }
    if(!items||!items.length){
      var fallback=TOOL_INSPECTION_CHECKLISTS[category]||TOOL_INSPECTION_CHECKLISTS.default;
      items=fallback.map(function(x){return {check_item:x};});
    }
    tbody.innerHTML='';
    items.forEach(function(item,i){
      var tr=document.createElement('tr');
      tr.style.cssText='border-bottom:1px solid #f5f5f5';
      tr.innerHTML='<td style="padding:8px 16px;font-size:12px">'+escH(item.check_item||item.item||'')+'</td>'
        +'<td style="padding:6px;text-align:center"><input type="radio" name="chk'+i+'" value="ok" id="ci-ok-'+i+'" data-auris-generated-onchange="g0233" style="width:16px;height:16px;accent-color:#1D9E75"></td>'
        +'<td style="padding:6px;text-align:center"><input type="radio" name="chk'+i+'" value="fail" id="ci-fail-'+i+'" data-auris-generated-onchange="g0233" style="width:16px;height:16px;accent-color:#E24B4A"></td>'
        +'<td style="padding:6px;text-align:center"><input type="radio" name="chk'+i+'" value="na" id="ci-na-'+i+'" data-auris-generated-onchange="g0233" style="width:16px;height:16px;accent-color:#6B7280" checked></td>'
        +'<td style="padding:4px 12px"><input type="text" class="insp-note-'+i+'" placeholder="Notes..." style="width:100%;padding:4px 8px;border:1px solid var(--border);border-radius:6px;font-size:11px"/></td>';
      tbody.appendChild(tr);
    });
    toolsInspScore();
  }catch(e){console.error(e);}
}

function toolsInspScore(){
  var rows=document.querySelectorAll('#insp-checklist-body tr');
  var ok=0,fail=0,na=0;
  rows.forEach(function(tr,i){
    var okR=document.getElementById('ci-ok-'+i);
    var failR=document.getElementById('ci-fail-'+i);
    var naR=document.getElementById('ci-na-'+i);
    if(okR?.checked)ok++;
    else if(failR?.checked)fail++;
    else if(naR?.checked)na++;
  });
  var el=document.getElementById('insp-score-display');
  if(el)el.textContent=ok+' OK - '+fail+' Fail - '+na+' N/A';
  // Auto-set result
  var res=document.getElementById('insp-result');
  if(res&&fail>0)res.value='fail';
  else if(res)res.value='pass';
}

function toolsInspFormBack(){
  document.getElementById('tools-insp-form').style.display='none';
  var target=toolsInspectionReturnTab||'inspection';
  var view=document.getElementById('tools-view-'+target)||document.getElementById('tools-view-inspection');
  if(view)view.style.display='block';
  document.querySelectorAll('[id^="tools-tab-"]').forEach(function(t){t.classList.remove('active');});
  var tab=document.getElementById('tools-tab-'+target)||document.getElementById('tools-tab-inspection');if(tab)tab.classList.add('active');
  if(target==='lifting')toolsLoadLiftingAccessories();
  else toolsLoadInspections();
}

async function toolsSaveInspection(){
  var date=document.getElementById('insp-date')?.value;
  if(!date){toast('Please set inspection date',false);return;}
  var inspId=document.getElementById('insp-inspector')?.value;
  var inspName='';
  if(inspId){var p=(people||[]).find(x=>x.id===inspId);inspName=p?(p.last_name+', '+p.first_name):'';}
  // Collect checklist
  var rows=document.querySelectorAll('#insp-checklist-body tr');
  var results=[];
  rows.forEach(function(tr,i){
    var item=tr.querySelector('td')?.textContent||'';
    var ok=document.getElementById('ci-ok-'+i)?.checked;
    var fail=document.getElementById('ci-fail-'+i)?.checked;
    var note=tr.querySelector('input[type="text"]')?.value||'';
    results.push({item:item,result:ok?'ok':fail?'fail':'na',note:note});
  });
  var body={
    company_id:ccid(),tool_id:toolsInspEquipId,
    inspection_type:document.getElementById('insp-type')?.value||'periodic',
    inspection_date:date,inspected_by:inspId||null,inspected_by_name:inspName||null,
    overall_result:document.getElementById('insp-result')?.value||'pass',
    checklist_results:results,
    defects_found:document.getElementById('insp-defects')?.value||null,
    actions_taken:document.getElementById('insp-actions')?.value||null,
    next_inspection_date:document.getElementById('insp-next-date')?.value||null,
    created_by:prof?.id
  };
  try{
    await api('/tool_inspections',{m:'POST',p:'return=minimal',b:body});
    // If fail, add to MAP
    if(body.overall_result==='fail'&&body.defects_found){
      var tool=toolsAllData.find(x=>x.id===toolsInspEquipId);
      await api('/action_tracker',{m:'POST',p:'return=minimal',b:{
        company_id:ccid(),source_module:'tools',source_id:toolsInspEquipId,
        source_ref:(tool?.ref_number||'Equipment')+' - Failed inspection',
        description:'Equipment failed inspection: '+body.defects_found,
        responsible:inspName||null,priority:'high',status:'open',created_by:prof?.id
      }});
      toast('Inspection saved - FAIL recorded and action added to MAP.');
    }else{
      toast('Inspection saved!');
    }
    toolsInspFormBack();
    return true;
  }catch(e){toastActionError('Save equipment inspection','Tools & Equipment',e);console.error(e);return false;}
}

// -- STATUTORY VERIFICATION ---------------------------------------------------
async function toolsLoadRCD(){
  var el=document.getElementById('tools-rcd-list');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var tools=await api('/tools_register?category=eq.electrical'+cf()+'&order=name&select=*');
    var tests=await api('/tool_inspections?inspection_type=in.(rcd_monthly,periodic)'+cf()+'&order=inspection_date.desc&limit=300&select=*');
    toolsRcdData=(tools||[]).filter(function(x){
      var txt=((x.name||'')+' '+(x.ref_number||'')+' '+(x.model||'')+' '+(x.notes||'')+' '+(x.statutory_type||'')).toLowerCase();
      return txt.indexOf('rcd')!==-1 || txt.indexOf('residual current')!==-1 || x.inspection_frequency==='monthly';
    });
    var lastByTool={};
    (tests||[]).forEach(function(t){if(t.tool_id&&!lastByTool[t.tool_id])lastByTool[t.tool_id]=t;});
    if(!toolsRcdData.length){
      el.innerHTML='<div style="text-align:center;padding:42px;color:var(--text2)">'
        +'<div style="font-size:38px;margin-bottom:10px"><i class="ti ti-plug-connected"></i></div>'
        +'<div style="font-weight:700;margin-bottom:8px;color:var(--text)">No RCDs registered yet</div>'
        +'<div style="font-size:12px;margin-bottom:14px">Add distribution boards or RCD devices, then record monthly push-button tests.</div>'
        +(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0234"><i class="ti ti-plus"></i>Add RCD / DB</button>':'')
        +'</div>';
      return;
    }
    var today=new Date();today.setHours(0,0,0,0);
    var h='<div class="table-scroll"><table class="data-table" style="min-width:980px">'
      +'<thead><tr>'
      +'<th>Ref</th>'
      +'<th>RCD / Distribution board</th>'
      +'<th>Location</th>'
      +'<th>Rating / type</th>'
      +'<th>Last test</th>'
      +'<th>Next due</th>'
      +'<th>Result</th>'
      +'<th style="text-align:right">Actions</th>'
      +'</tr></thead><tbody>';
    toolsRcdData.forEach(function(x,i){
      var last=lastByTool[x.id];
      var next=last&&last.next_inspection_date?new Date(last.next_inspection_date):null;
      var soon=new Date(today);soon.setDate(soon.getDate()+7);
      var overdue=!next||next<today;
      var dueSoon=next&&next>=today&&next<=soon;
      var result=last?.overall_result||'not_tested';
      var cfg={pass:['#EAF3DE','#3B6D11','Pass'],conditional:['#FEF9EC','#854F0B','Conditional'],fail:['#FCEBEB','#A32D2D','Fail'],not_tested:['#f3f4f6','#6B7280','No test']};
      var rc=cfg[result]||cfg.not_tested;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+(i%2?'#fafafa':'#fff')+(overdue?';border-left:4px solid var(--red)':dueSoon?';border-left:4px solid #C2410C':'')+'">'
        +'<td style="padding:9px 12px;font-family:monospace;font-weight:700;color:var(--green)">'+escH(x.ref_number||'AUTO')+'</td>'
        +'<td style="padding:9px 12px;font-weight:700">'+escH(x.name||'RCD')+'</td>'
        +'<td style="padding:9px 12px">'+escH(x.location||'--')+'</td>'
        +'<td style="padding:9px 12px">'+escH(x.model||x.brand||'--')+'</td>'
        +'<td style="padding:9px 12px">'+(last?.inspection_date?new Date(last.inspection_date).toLocaleDateString('en-GB'):'--')+'</td>'
        +'<td style="padding:9px 12px;'+(overdue?'color:var(--red);font-weight:700':dueSoon?'color:#C2410C;font-weight:700':'')+'">'+(next?next.toLocaleDateString('en-GB'):'No test recorded')+(next&&overdue?' overdue':dueSoon?' due soon':'')+'</td>'
        +'<td style="padding:9px 12px;text-align:center"><span style="background:'+rc[0]+';color:'+rc[1]+';padding:3px 10px;border-radius:99px;font-size:11px;font-weight:700">'+rc[2]+'</span></td>'
        +'<td style="padding:9px 12px;text-align:right;white-space:nowrap">'
        +(isMgr()?'<button class="btn btn-sm btn-primary" data-id="'+x.id+'" data-auris-generated-onclick="g0235"><i class="ti ti-clipboard-check"></i>Test</button> ':'')
        +(isMgr()?'<button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0226"><i class="ti ti-edit"></i></button>':'')
        +'</td></tr>';
    });
    h+='</tbody></table></div>';
    el.innerHTML=h;
  }catch(e){
    el.innerHTML=setupFriendlyMessage('RCD register',e.message);
  }
}

function toolsNewRCD(){
  toolsNew();
  var cat=document.getElementById('teq-cat');if(cat){cat.value='electrical';toolsCatChange();}
  var name=document.getElementById('teq-name');if(name&&!name.value)name.value='RCD / Distribution board';
  var freq=document.getElementById('teq-freq');if(freq)freq.value='monthly';
  var stat=document.getElementById('teq-statutory');if(stat)stat.checked=false;
  var notes=document.getElementById('teq-notes');if(notes&&!notes.value)notes.value='RCD monthly push-button testing required.';
}

function toolsStartRCDTest(toolId){
  if(!isMgr()){toast('Only supervisors, HSE managers and admins can record RCD tests.',false);return;}
  var tool=toolsRcdData.find(function(x){return x.id===toolId;})||toolsAllData.find(function(x){return x.id===toolId;});
  if(!tool){toast('RCD not found',false);return;}
  toolsInspEquipId=toolId;
  document.getElementById('rcd-equip-name').textContent=tool.name||'RCD';
  document.getElementById('rcd-equip-ref').textContent=(tool.ref_number||'')+(tool.location?' - '+tool.location:'');
  var dt=document.getElementById('rcd-date');if(dt)dt.value=new Date().toISOString().slice(0,10);
  var nd=new Date();nd.setMonth(nd.getMonth()+1);
  var next=document.getElementById('rcd-next-date');if(next)next.value=nd.toISOString().slice(0,10);
  var tester=document.getElementById('rcd-tester');
  if(tester){tester.innerHTML='<option value="">Select tester...</option>';(people||[]).forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.last_name+', '+p.first_name;tester.appendChild(o);});}
  var currentPersonId=prof?.person_id||prof?.id||'';
  if(tester&&currentPersonId&&Array.from(tester.options).some(function(o){return o.value===currentPersonId;}))tester.value=currentPersonId;
  [['rcd-visual','ok'],['rcd-button','pass'],['rcd-label','ok']].forEach(function(x){var el=document.getElementById(x[0]);if(el)el.value=x[1];});
  ['rcd-trip-time','rcd-visual-note','rcd-label-note','rcd-defects','rcd-actions'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['tools-view-register','tools-view-personal','tools-view-inspection','tools-view-lifting','tools-view-statutory','tools-view-vehicles','tools-view-rcd'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});
  document.getElementById('tools-form').style.display='none';
  document.getElementById('tools-insp-form').style.display='none';
  document.getElementById('tools-rcd-form').style.display='block';
}

function toolsRCDBack(){
  document.getElementById('tools-rcd-form').style.display='none';
  document.getElementById('tools-view-rcd').style.display='block';
  document.querySelectorAll('[id^="tools-tab-"]').forEach(function(t){t.classList.remove('active');});
  var tab=document.getElementById('tools-tab-rcd');if(tab)tab.classList.add('active');
  toolsLoadRCD();
}

async function toolsSaveRCDTest(){
  if(!isMgr()){toast('Only supervisors, HSE managers and admins can record RCD tests.',false);return;}
  var date=document.getElementById('rcd-date')?.value;
  if(!date){toast('Please set test date',false);return;}
  var testerId=document.getElementById('rcd-tester')?.value;
  if(!testerId){toast('Please select the tester',false);return;}
  var testerName='';
  if(testerId){var p=(people||[]).find(function(x){return x.id===testerId;});testerName=p?(p.last_name+', '+p.first_name):'';}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var visual=g('rcd-visual')||'ok', button=g('rcd-button')||'pass', label=g('rcd-label')||'ok';
  var tripMs=parseFloat(g('rcd-trip-time')||'');
  var fail=visual==='fail'||button==='fail'||label==='fail'||(!isNaN(tripMs)&&tripMs>300);
  if(!g('rcd-next-date')){
    var nd=new Date(date);nd.setMonth(nd.getMonth()+1);
    var next=document.getElementById('rcd-next-date');if(next)next.value=nd.toISOString().slice(0,10);
  }
  if(fail&&(!g('rcd-defects')||!g('rcd-actions'))){toast('Failed RCD tests need defects and corrective actions before saving.',false);return;}
  var body={
    company_id:ccid(),tool_id:toolsInspEquipId,inspection_type:'periodic',
    inspection_date:date,inspected_by:testerId||null,inspected_by_name:testerName||null,
    overall_result:fail?'fail':'pass',
    checklist_results:[
      {item:'Visual condition',result:visual,note:g('rcd-visual-note')||''},
      {item:'Test button operates and trips correctly',result:button==='pass'?'ok':'fail',note:g('rcd-trip-time')?('Trip time: '+g('rcd-trip-time')+' ms'):''},
      {item:'RCD/DB labelled and accessible',result:label,note:g('rcd-label-note')||''}
    ],
    defects_found:g('rcd-defects'),actions_taken:g('rcd-actions'),
    next_inspection_date:g('rcd-next-date'),created_by:prof?.id
  };
  try{
    await api('/tool_inspections',{m:'POST',p:'return=minimal',b:body});
    if(fail&&body.defects_found){
      var tool=toolsRcdData.find(function(x){return x.id===toolsInspEquipId;});
      await api('/tools_register?id=eq.'+toolsInspEquipId,{m:'PATCH',p:'return=minimal',b:{status:'out_of_service'}});
      await api('/action_tracker',{m:'POST',p:'return=minimal',b:{
        company_id:ccid(),source_module:'tools',source_id:toolsInspEquipId,
        source_ref:(tool?.ref_number||'RCD')+' - Failed RCD test',
        description:'RCD monthly test failed: '+body.defects_found,
        responsible:testerName||null,priority:'high',status:'open',created_by:prof?.id
      }});
      toast('RCD test saved - failure added to MAP.');
    }else toast('RCD test saved!');
    toolsRCDBack();
  }catch(e){toastActionError('Save RCD test','Tools & Equipment',e);console.error(e);}
}

async function toolsLoadStatutory(){
  var el=document.getElementById('tools-stat-list');
  var alertEl=document.getElementById('tools-stat-alerts');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/tools_register?requires_statutory=eq.true'+cf()+'&order=next_statutory_date&select=*');
    if(!d||!d.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">No equipment requiring statutory examination registered.<br><br>'+(isMgr()?'<button class="btn btn-primary btn-sm" data-auris-generated-onclick="g0224">Add statutory equipment</button>':'')+'</div>';
      if(alertEl)alertEl.innerHTML='';
      return;
    }
    var today=new Date(); var soon=new Date(); soon.setDate(soon.getDate()+60);
    var overdue=d.filter(x=>x.next_statutory_date&&new Date(x.next_statutory_date)<today);
    var dueSoon=d.filter(x=>x.next_statutory_date&&new Date(x.next_statutory_date)>=today&&new Date(x.next_statutory_date)<=soon);
    if(alertEl){
      var ah='';
      if(overdue.length)ah+='<div style="background:#FCEBEB;border:1px solid #fca5a5;border-radius:8px;padding:10px 14px;margin-bottom:8px;font-size:12px"><strong style="color:var(--red)">OVERDUE: '+overdue.length+' statutory examination'+(overdue.length!==1?'s':'')+' overdue:</strong> '+overdue.map(x=>escH(x.name+(x.ref_number?' ('+x.ref_number+')':''))).join(', ')+'</div>';
      if(dueSoon.length)ah+='<div style="background:#FEF9EC;border:1px solid #fcd34d;border-radius:8px;padding:10px 14px;margin-bottom:8px;font-size:12px"><strong style="color:var(--amber)">Due within 60 days: '+dueSoon.length+' examination'+(dueSoon.length!==1?'s':'')+' due soon</strong></div>';
      alertEl.innerHTML=ah;
    }
    var h='<div class="table-scroll"><table class="data-table" style="min-width:980px"><thead><tr>'
      +'<th>Ref</th>'
      +'<th style="'+TOOLS_TH_STYLE_COMPACT+'">Equipment</th>'
      +'<th style="'+TOOLS_TH_STYLE_COMPACT+'">Examination type</th>'
      +'<th style="'+TOOLS_TH_STYLE_COMPACT+';width:110px">Last exam</th>'
      +'<th style="'+TOOLS_TH_STYLE_COMPACT+';width:110px">Next exam due</th>'
      +'<th style="'+TOOLS_TH_STYLE_COMPACT+'">Examining body</th>'
      +'<th style="'+TOOLS_TH_STYLE_COMPACT+';text-align:center;width:100px">Status</th>'
      +'<th style="width:60px"></th>'
      +'</tr></thead><tbody>';
    d.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';
      var nextDate=x.next_statutory_date?new Date(x.next_statutory_date):null;
      var isOverdue=nextDate&&nextDate<today;
      var isDueSoon=nextDate&&nextDate>=today&&nextDate<=soon;
      var statColor=isOverdue?'var(--red)':isDueSoon?'var(--amber)':'var(--green)';
      var statLabel=isOverdue?'OVERDUE':isDueSoon?'Due soon':'OK';
      var statBg=isOverdue?'#FCEBEB':isDueSoon?'#FEF9EC':'#EAF3DE';
      var statTxt=isOverdue?'#A32D2D':isDueSoon?'#854F0B':'#3B6D11';
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+(isOverdue?';border-left:3px solid var(--red)':isDueSoon?';border-left:3px solid var(--amber)':'')+'">'
        +'<td style="padding:8px 12px;font-family:monospace;font-weight:700;color:var(--green)">'+escH(x.ref_number||'-')+'</td>'
        +'<td style="padding:8px 10px;font-weight:600">'+escH(x.name||'-')+'</td>'
        +'<td style="padding:8px 10px">'+escH(x.statutory_type||'-')+'</td>'
        +'<td style="padding:8px 10px">'+( x.last_statutory_date?new Date(x.last_statutory_date).toLocaleDateString('en-GB'):'-')+'</td>'
        +'<td style="padding:8px 10px;color:'+statColor+';font-weight:600">'+( nextDate?nextDate.toLocaleDateString('en-GB'):'-')+'</td>'
        +'<td style="padding:8px 10px">'+escH(x.statutory_body||'-')+'</td>'
        +'<td style="padding:8px 10px;text-align:center"><span style="background:'+statBg+';color:'+statTxt+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+statLabel+'</span></td>'
        +'<td style="padding:8px 10px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0232"><i class="ti ti-edit"></i></button></td>'
        +'</tr>';
    });
    h+='</tbody></table></div>';
    if(el)el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

// -- VEHICLES -----------------------------------------------------------------
async function toolsLoadVehicles(){
  var el=document.getElementById('tools-vehicles-list');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var vehicles=await api('/tools_register?is_vehicle=eq.true'+cf()+'&order=name&select=*');
    if(!vehicles||!vehicles.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">'
        +'<div style="font-size:48px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div>'
        +'<div style="font-weight:600;margin-bottom:8px">No vehicles registered</div>'
        +(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0236"><i class="ti ti-plus"></i>Add vehicle</button>':'')
        +'</div>';
      return;
    }
    var today=new Date();
    var html='<div class="table-scroll"><table class="data-table" style="min-width:980px"><thead><tr><th>Vehicle</th><th>Reference</th><th>Location</th><th>Last inspection</th><th>Check status</th><th>Last result</th><th style="text-align:right">Actions</th></tr></thead><tbody>';
    for(var i=0;i<vehicles.length;i++){
      var v=vehicles[i];
      var lastInsp=null;
      try{var ins=await api('/tool_inspections?tool_id=eq.'+v.id+'&order=inspection_date.desc&limit=1'+cf());lastInsp=ins?.[0];}catch(ex){}
      var lastDt=lastInsp?new Date(lastInsp.inspection_date):null;
      var daysSince=lastDt?Math.floor((today-lastDt)/(1000*60*60*24)):999;
      var isOverdue=daysSince>35;
      var isDueSoon=daysSince>21&&daysSince<=35;
      var inspStatus=isOverdue?['#FCEBEB','#A32D2D','Monthly check OVERDUE']:isDueSoon?['#FEF9EC','#854F0B','Due for monthly check']:['#EAF3DE','#3B6D11','Monthly check up to date'];
      html+='<tr style="border-bottom:1px solid #f0f0f0;background:'+(i%2?'#fafafa':'#fff')+(isOverdue?';border-left:4px solid var(--red)':isDueSoon?';border-left:4px solid var(--amber)':'')+'">'
        +'<td style="padding:10px 12px"><div style="font-family:monospace;font-weight:900;color:#185FA5">'+escH(v.registration_number||v.name||'--')+'</div><div style="font-size:11px;color:var(--text2)">'+escH((v.name||'')+(v.brand?' - '+v.brand:'')+(v.model?' '+v.model:''))+'</div></td>'
        +'<td style="padding:10px 12px;font-family:monospace;font-weight:700">'+escH(v.ref_number||'--')+'</td>'
        +'<td style="padding:10px 12px">'+escH(v.location||'--')+'</td>'
        +'<td style="padding:10px 12px">'+(lastDt?lastDt.toLocaleDateString('en-GB'):'Never')+'<div style="font-size:11px;color:'+(isOverdue?'var(--red)':isDueSoon?'#C2410C':'var(--text2)')+'">'+(daysSince<999?daysSince+' days ago':'Check due')+'</div></td>'
        +'<td style="padding:10px 12px"><span style="background:'+inspStatus[0]+';color:'+inspStatus[1]+';padding:3px 9px;border-radius:99px;font-size:11px;font-weight:800">'+inspStatus[2]+'</span></td>'
        +'<td style="padding:10px 12px">'+escH(lastInsp?.overall_result||'--')+'</td>'
        +'<td style="padding:10px 12px;text-align:right;white-space:nowrap"><button class="btn btn-sm btn-primary" data-id="'+v.id+'" data-auris-generated-onclick="g0237"><i class="ti ti-clipboard-check"></i>Check</button> <button class="btn btn-sm" data-id="'+v.id+'" data-auris-generated-onclick="g0232"><i class="ti ti-edit"></i></button></td>'
        +'</tr>';
    }
    html+='</tbody></table></div>';
    if(isMgr())html+='<div style="padding:12px 16px;border-top:1px solid var(--border);text-align:center"><button class="btn btn-sm btn-primary" data-auris-generated-onclick="g0236"><i class="ti ti-plus"></i>Add vehicle</button></div>';
    el.innerHTML=html;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

