async function toolsViewInspection(id){
  if(!id)return;
  try{
    var rows=await api('/tool_inspections?id=eq.'+id+'&select=*,tools_register(name,ref_number,category,location,serial_number)');
    var x=rows?.[0];
    if(!x){toast('Inspection record not found',false);return;}
    var tool=x.tools_register||{};
    var result=x.overall_result||'pass';
    var resCfg={pass:['#EAF3DE','#3B6D11','Pass'],conditional:['#FEF9EC','#854F0B','Conditional'],fail:['#FCEBEB','#A32D2D','Fail']};
    var rc=resCfg[result]||resCfg.pass;
    var checklist=Array.isArray(x.checklist_results)?x.checklist_results:[];
    var rowsHtml=checklist.length?checklist.map(function(c,i){
      var r=String(c.result||'na').toLowerCase();
      var cfg=r==='ok'?['#EAF3DE','#3B6D11','OK']:r==='fail'?['#FCEBEB','#A32D2D','Fail']:['#f3f4f6','#6B7280','N/A'];
      return '<tr>'
        +'<td style="padding:8px 10px;border-bottom:1px solid var(--border);font-size:12px">'+escH(c.item||('Check '+(i+1)))+'</td>'
        +'<td style="padding:8px 10px;border-bottom:1px solid var(--border);text-align:center"><span style="background:'+cfg[0]+';color:'+cfg[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:800">'+cfg[2]+'</span></td>'
        +'<td style="padding:8px 10px;border-bottom:1px solid var(--border);font-size:12px;color:var(--text2)">'+escH(c.note||'')+'</td>'
        +'</tr>';
    }).join(''):'<tr><td colspan="3" style="padding:16px;text-align:center;color:var(--text2)">No checklist details recorded.</td></tr>';
    var modal=document.createElement('div');
    modal.id='tools-inspection-detail-modal';
    modal.style.cssText='position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px';
    modal.innerHTML='<div class="card" role="dialog" aria-modal="true" style="width:100%;max-width:820px;max-height:88vh;overflow:auto;border-radius:12px;padding:0;box-shadow:0 24px 80px rgba(0,0,0,.35)">'
      +'<div style="padding:16px 20px;background:linear-gradient(135deg,#1a3a5c,#185FA5);color:#fff;display:flex;justify-content:space-between;align-items:center;gap:12px">'
      +'<div><div style="font-size:11px;text-transform:uppercase;letter-spacing:.08em;opacity:.8">Equipment inspection report</div><div style="font-size:18px;font-weight:900;margin-top:3px">'+escH(tool.name||'Equipment')+'</div><div style="font-family:monospace;font-size:12px;opacity:.8">'+escH(tool.ref_number||'')+'</div></div>'
      +'<button class="btn btn-sm" style="background:rgba(255,255,255,.16);color:#fff;border-color:rgba(255,255,255,.25)" data-auris-generated-onclick="g0238"><i class="ti ti-x"></i></button>'
      +'</div>'
      +'<div style="padding:18px 20px">'
      +'<div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:16px">'
      +toolsInspectionDetailMetric('Date',x.inspection_date?new Date(x.inspection_date).toLocaleDateString('en-GB'):'-')
      +toolsInspectionDetailMetric('Type',String(x.inspection_type||'periodic').replace(/_/g,' '))
      +toolsInspectionDetailMetric('Inspector',x.inspected_by_name||'-')
      +'<div style="border:1px solid var(--border);border-radius:10px;padding:10px 12px;background:#fff"><div style="font-size:10px;color:var(--text2);font-weight:800;text-transform:uppercase;margin-bottom:5px">Result</div><span style="background:'+rc[0]+';color:'+rc[1]+';padding:4px 10px;border-radius:99px;font-size:12px;font-weight:900">'+rc[2]+'</span></div>'
      +'</div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px">'
      +'<div style="border:1px solid var(--border);border-radius:10px;padding:12px;background:#fff"><div style="font-size:12px;font-weight:900;margin-bottom:8px">Equipment details</div>'
      +toolsInspectionDetailLine('Category',TOOL_CAT_LABELS[tool.category]||tool.category||'-')
      +toolsInspectionDetailLine('Location',tool.location||'-')
      +toolsInspectionDetailLine('Serial no.',tool.serial_number||'-')
      +toolsInspectionDetailLine('Next inspection',x.next_inspection_date?new Date(x.next_inspection_date).toLocaleDateString('en-GB'):'-')
      +'</div>'
      +'<div style="border:1px solid var(--border);border-radius:10px;padding:12px;background:#fff"><div style="font-size:12px;font-weight:900;margin-bottom:8px">Findings and action</div>'
      +toolsInspectionDetailLine('Defects found',x.defects_found||'-')
      +toolsInspectionDetailLine('Actions taken',x.actions_taken||'-')
      +'</div>'
      +'</div>'
      +'<div style="border:1px solid var(--border);border-radius:10px;overflow:hidden;background:#fff"><div style="padding:10px 12px;font-size:12px;font-weight:900;background:#f9fafb;border-bottom:1px solid var(--border)">Checklist results</div>'
      +'<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr><th style="padding:8px 10px;text-align:left">Check item</th><th style="padding:8px 10px;text-align:center;width:90px">Result</th><th style="padding:8px 10px;text-align:left">Notes</th></tr></thead><tbody>'+rowsHtml+'</tbody></table></div>'
      +'<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px"><button class="btn" data-auris-generated-onclick="g0023"><i class="ti ti-printer"></i>Print</button><button class="btn btn-primary" data-auris-generated-onclick="g0238">Close</button></div>'
      +'</div></div>';
    document.body.appendChild(modal);
    modal.addEventListener('click',function(e){if(e.target===modal)modal.remove();});
  }catch(e){toast(actionErrorMessage('Open inspection details','Tools & Equipment',e),false);}
}

function toolsInspectionDetailMetric(label,value){
  return '<div style="border:1px solid var(--border);border-radius:10px;padding:10px 12px;background:#fff"><div style="font-size:10px;color:var(--text2);font-weight:800;text-transform:uppercase;margin-bottom:5px">'+escH(label)+'</div><div style="font-size:13px;font-weight:800;text-transform:capitalize">'+escH(value||'-')+'</div></div>';
}

function toolsInspectionDetailLine(label,value){
  return '<div style="display:grid;grid-template-columns:120px 1fr;gap:8px;padding:5px 0;border-bottom:1px solid #f3f4f6"><div style="font-size:11px;color:var(--text2);font-weight:700">'+escH(label)+'</div><div style="font-size:12px;line-height:1.4">'+escH(value||'-')+'</div></div>';
}

// ===== FLEET MANAGEMENT MODULE =====
let fleetVehicles=[], fleetFuel=[], fleetInspections=[], fleetIncidents=[];

function fleetLabel(v){
  return (v.registration_number||v.ref_number||v.name||'Vehicle').trim();
}

function fleetKey(v){
  return String(v||'').toLowerCase().replace(/[^a-z0-9]/g,'');
}

function fleetFuelMatchesVehicle(f,v){
  var hay=fleetKey(f.vehicle_equipment||'');
  if(!hay)return false;
  return [v.registration_number,v.ref_number,v.name].some(function(x){
    var key=fleetKey(x);
    return key&&(hay.indexOf(key)!==-1||key.indexOf(hay)!==-1);
  });
}

function fleetIncidentMatchesVehicle(ev,v){
  var type=String(ev.event_type||ev.type||'').toLowerCase();
  if(type&&type.indexOf('vehicle')===-1&&type.indexOf('traffic')===-1&&type.indexOf('transport')===-1)return false;
  var reg=fleetKey(ev.vehicle_reg||ev.vehicle_registration||ev.registration||''), label=fleetKey(fleetLabel(v));
  var text=fleetKey([ev.description,ev.location,ev.title,ev.event_ref].join(' '));
  if(reg&&label&&(reg===label||label.indexOf(reg)!==-1||reg.indexOf(label)!==-1))return true;
  return !!(label&&text&&text.indexOf(label)!==-1);
}

async function loadFleet(){
  var addBtn=document.getElementById('fleet-add-vehicle-btn');
  if(addBtn)addBtn.style.display=isMgr()?'inline-flex':'none';
  var printBtn=document.getElementById('fleet-print-btn');
  if(printBtn)printBtn.style.display='inline-flex';
  var fuelBtn=document.getElementById('fleet-fuel-log-btn');if(fuelBtn)fuelBtn.style.display=isMgr()?'inline-flex':'none';
  var el=document.getElementById('fleet-list');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading fleet...</div>';
  try{
    var optional=function(p,label){return p.catch(function(e){console.warn('Fleet optional data unavailable: '+label,e);return[];});};
    var res=await Promise.all([
      api('/tools_register?is_vehicle=eq.true'+cf()+'&order=name&select=*'),
      optional(api('/tool_inspections?select=*'+cf()+'&order=inspection_date.desc&limit=500'),'vehicle inspections'),
      optional(api('/fuel_consumption?select=*'+cf()+'&order=record_date.desc&limit=500'),'fuel log'),
      optional(api('/events?select=id,event_type,vehicle_reg,created_at,event_date,description,location'+cf()+'&order=created_at.desc&limit=200'),'vehicle incidents')
    ]);
    fleetVehicles=res[0]||[]; fleetInspections=res[1]||[]; fleetFuel=res[2]||[]; fleetIncidents=res[3]||[];
    fleetRender();
  }catch(e){
    el.innerHTML=setupFriendlyMessage('Fleet module',e.message);
  }
}

function fleetRender(){
  var el=document.getElementById('fleet-list');
  if(!el)return;
  var q=(document.getElementById('fleet-search')?.value||'').toLowerCase();
  var statusFilter=document.getElementById('fleet-filter-status')?.value||'';
  var checkFilter=document.getElementById('fleet-filter-check')?.value||'';
  var today=new Date();today.setHours(0,0,0,0);
  var lastInsp={};
  fleetInspections.forEach(function(x){if(x.tool_id&&!lastInsp[x.tool_id])lastInsp[x.tool_id]=x;});
  var active=fleetVehicles.filter(function(v){return (v.status||'active')==='active';}).length;
  var overdue=0,totalFuel=0,totalCo2=0;
  fleetVehicles.forEach(function(v){
    var li=lastInsp[v.id], dt=li&&li.inspection_date?new Date(li.inspection_date):null;
    if(!dt || Math.floor((today-dt)/(1000*60*60*24))>35)overdue++;
    fleetFuel.filter(function(f){return fleetFuelMatchesVehicle(f,v);}).forEach(function(f){
      totalFuel+=parseFloat(f.quantity)||0; totalCo2+=parseFloat(f.carbon_kg)||0;
    });
  });
  var setM=function(id,v){var m=document.getElementById(id);if(m)m.textContent=v;};
  setM('fleet-m3total',fleetVehicles.length);
  setM('fleet-m3active',active);
  setM('fleet-m3overdue',overdue);
  setM('fleet-m3fuel',Math.round(totalFuel));
  setM('fleet-m3co2',Math.round(totalCo2));
  var rows=fleetVehicles.filter(function(v){
    var li=lastInsp[v.id], lastDt=li&&li.inspection_date?new Date(li.inspection_date):null;
    var days=lastDt?Math.floor((today-lastDt)/(1000*60*60*24)):999;
    var due=days>35, soon=days>21&&days<=35;
    var incCount=fleetIncidents.filter(function(ev){return fleetIncidentMatchesVehicle(ev,v);}).length;
    var text=[fleetLabel(v),v.name,v.brand,v.model,v.location,v.assigned_to_name,v.status].join(' ').toLowerCase();
    if(q&&text.indexOf(q)===-1)return false;
    if(statusFilter&&(v.status||'active')!==statusFilter)return false;
    if(checkFilter==='overdue'&&!due)return false;
    if(checkFilter==='due_soon'&&!soon)return false;
    if(checkFilter==='with_incidents'&&!incCount)return false;
    return true;
  });
  if(!fleetVehicles.length){
    el.innerHTML='<div class="card" style="text-align:center;padding:42px;color:var(--text2)"><div style="font-size:40px;margin-bottom:10px"><i class="ti ti-car"></i></div><div style="font-weight:700;color:var(--text);margin-bottom:8px">No vehicles registered yet</div><div style="font-size:12px;margin-bottom:14px">Add company vehicles from here, then track inspections, fuel and incidents.</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0239"><i class="ti ti-plus"></i>Add vehicle</button>':'')+'</div>';
    return;
  }
  if(!rows.length){
    el.innerHTML='<div class="card" style="text-align:center;padding:34px;color:var(--text2)"><div style="font-weight:800;color:var(--text);margin-bottom:6px">No vehicles match the current filters</div><button class="btn btn-sm" data-auris-generated-onclick="g0240">Clear filters</button></div>';
    return;
  }
  var h='<div class="table-scroll"><table class="data-table" style="min-width:1180px">'
    +'<thead><tr>'
    +'<th>Vehicle</th>'
    +'<th>Assigned / location</th>'
    +'<th>Status</th>'
    +'<th>Last monthly check</th>'
    +'<th>Fuel logged</th>'
    +'<th style="text-align:center">Vehicle incidents</th>'
    +'<th style="text-align:right">Actions</th>'
    +'</tr></thead><tbody>';
  rows.forEach(function(v,i){
    var li=lastInsp[v.id], lastDt=li&&li.inspection_date?new Date(li.inspection_date):null;
    var days=lastDt?Math.floor((today-lastDt)/(1000*60*60*24)):999;
    var due=days>35, soon=days>21&&days<=35;
    var fList=fleetFuel.filter(function(f){return fleetFuelMatchesVehicle(f,v);});
    var fuelSum=fList.reduce(function(s,f){return s+(parseFloat(f.quantity)||0);},0);
    var incCount=fleetIncidents.filter(function(ev){return fleetIncidentMatchesVehicle(ev,v);}).length;
    var status=(v.status||'active').replace(/_/g,' ');
    var stCfg=(v.status||'active')==='active'?['#EAF3DE','#3B6D11']:(v.status==='out_of_service'?['#FCEBEB','#A32D2D']:['#FEF9EC','#854F0B']);
    h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+(i%2?'#fafafa':'#fff')+(due?';border-left:4px solid var(--red)':soon?';border-left:4px solid var(--amber)':'')+'">'
      +'<td style="padding:10px 12px"><div style="font-weight:800;font-size:13px">'+escH(fleetLabel(v))+'</div><div style="font-size:11px;color:var(--text2)">'+escH((v.name||'')+(v.brand?' - '+v.brand:'')+(v.model?' '+v.model:''))+'</div></td>'
      +'<td style="padding:10px 12px"><div>'+escH(v.assigned_to_name||'General use')+'</div><div style="font-size:11px;color:var(--text2)">'+escH(v.location||'--')+'</div></td>'
      +'<td style="padding:10px 12px"><span style="background:'+stCfg[0]+';color:'+stCfg[1]+';padding:3px 9px;border-radius:99px;font-size:11px;font-weight:700;text-transform:capitalize">'+escH(status)+'</span></td>'
      +'<td style="padding:10px 12px;'+(due?'color:var(--red);font-weight:700':'')+'">'+(lastDt?lastDt.toLocaleDateString('en-GB'):'Never')+'<div style="font-size:11px;color:'+(due?'var(--red)':soon?'#C2410C':'var(--text2)')+'">'+(lastDt?(days+' days ago'):'Check due')+(due?'<br><strong>OVERDUE</strong>':soon?'<br><strong>DUE SOON</strong>':'')+'</div></td>'
      +'<td style="padding:10px 12px;font-weight:700">'+(fuelSum?fuelSum.toFixed(1):'0')+' L<div style="font-size:11px;color:var(--text2);font-weight:400">'+fList.length+' entries</div></td>'
      +'<td style="padding:10px 12px;text-align:center;font-weight:800;color:'+(incCount?'var(--red)':'var(--text2)')+'">'+incCount+'</td>'
      +'<td style="padding:10px 12px;text-align:right;white-space:nowrap">'
      +(isMgr()?'<button class="btn btn-sm" data-id="'+v.id+'" data-auris-generated-onclick="g0241"><i class="ti ti-clipboard-check"></i>Check</button> ':'')
      +(isMgr()?'<button class="btn btn-sm" data-label="'+escH(fleetLabel(v))+'" data-auris-generated-onclick="g0242"><i class="ti ti-gas-station"></i>Fuel</button> ':'')
      +(isMgr()?'<button class="btn btn-sm" data-id="'+v.id+'" data-auris-generated-onclick="g0243"><i class="ti ti-edit"></i></button>':'')
      +'</td></tr>';
  });
  h+='</tbody></table></div>';
  el.innerHTML=h;
}

function fleetNewVehicle(){showPage('tools',null);setTimeout(function(){if(typeof toolsNewVehicle==='function')toolsNewVehicle();},120);}
function fleetEditVehicle(id){showPage('tools',null);setTimeout(function(){if(typeof toolsEdit==='function')toolsEdit(id);},160);}
function fleetMonthlyCheck(id){showPage('tools',null);setTimeout(function(){if(typeof toolsStartInspection==='function')toolsStartInspection(id);},160);}
function fleetFuelNew(label){showPage('esg',null);setTimeout(function(){if(typeof esgFuelNew==='function'){esgFuelNew();var el=document.getElementById('ff-vehicle');if(el)el.value=label||'';}},180);}

// ===== ATEX / HAZARDOUS AREA MODULE =====
let atexAreas=[], atexEditId=null;
const ATEX_ZONE_LABELS={zone_0:'Zone 0',zone_1:'Zone 1',zone_2:'Zone 2',zone_20:'Zone 20',zone_21:'Zone 21',zone_22:'Zone 22'};
const ATEX_STATUS_CFG={controlled:['#EAF3DE','#3B6D11','Controlled'],action_required:['#FEF9EC','#854F0B','Action required'],out_of_service:['#FCEBEB','#A32D2D','Out of service'],archived:['#f3f4f6','#6B7280','Archived']};

async function loadATEX(){
  var add=document.getElementById('atex-add-btn');
  if(add)add.style.display=isMgr()?'inline-flex':'none';
  var print=document.getElementById('atex-print-btn');
  if(print)print.style.display='inline-flex';
  var sf=document.getElementById('atex-filter-status');if(sf&&!sf.value)sf.value='active';
  await atexLoadRegister();
}

async function atexLoadRegister(){
  var el=document.getElementById('atex-list');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading ATEX areas...</div>';
  try{
    var d=await api('/atex_areas?select=*'+cf()+'&order=zone_type,area_name');
    atexAreas=d||[];
    atexRender();
  }catch(e){
    el.innerHTML=setupFriendlyMessage('ATEX area register',e.message);
  }
}

function atexRender(){
  var el=document.getElementById('atex-list');
  if(!el)return;
  var q=(document.getElementById('atex-search')?.value||'').toLowerCase();
  var zone=document.getElementById('atex-filter-zone')?.value||'';
  var status=document.getElementById('atex-filter-status')?.value||'';
  var today=new Date();today.setHours(0,0,0,0);
  var filtered=atexAreas.filter(function(x){
    var text=((x.area_ref||'')+' '+(x.area_name||'')+' '+(x.location||'')+' '+(x.substance||'')).toLowerCase();
    var statusOk=status==='active'?x.status!=='archived':(!status||x.status===status);
    return (!q||text.indexOf(q)!==-1)&&(!zone||x.zone_type===zone)&&statusOk;
  });
  var setM=function(id,v){var m=document.getElementById(id);if(m)m.textContent=v;};
  setM('atex-m3total',atexAreas.filter(x=>x.status!=='archived').length);
  setM('atex-m3action',atexAreas.filter(x=>x.status==='action_required').length);
  setM('atex-m3oos',atexAreas.filter(x=>x.status==='out_of_service').length);
  setM('atex-m3due',atexAreas.filter(x=>x.status!=='archived'&&x.next_inspection_date&&new Date(x.next_inspection_date)<=today).length);
  if(!filtered.length){
    el.innerHTML='<div class="card" style="text-align:center;padding:42px;color:var(--text2)"><div style="font-size:38px;margin-bottom:10px"><i class="ti ti-flame"></i></div><div style="font-weight:700;color:var(--text);margin-bottom:8px">No ATEX areas found</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0244"><i class="ti ti-plus"></i>Add ATEX area</button>':'')+'</div>';
    return;
  }
  var h='<div class="table-scroll"><table class="data-table" style="min-width:1180px">'
    +'<thead><tr>'
    +'<th>Ref</th><th>Area / location</th>'
    +'<th>Zone</th><th>Substance</th>'
    +'<th>Main controls</th><th>Next inspection</th>'
    +'<th style="text-align:center">Status</th><th style="text-align:right">Actions</th>'
    +'</tr></thead><tbody>';
  filtered.forEach(function(x,i){
    var cfg=ATEX_STATUS_CFG[x.status]||ATEX_STATUS_CFG.controlled;
    var due=x.next_inspection_date&&new Date(x.next_inspection_date)<=today;
    var soon=x.next_inspection_date&&new Date(x.next_inspection_date)<=new Date(Date.now()+30*86400000)&&!due;
    h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+(i%2?'#fafafa':'#fff')+(due?';border-left:4px solid var(--red)':'')+'">'
      +'<td style="padding:10px 12px;font-family:monospace;font-weight:800;color:#C2410C">'+escH(x.area_ref||'ATEX')+'</td>'
      +'<td style="padding:10px 12px"><div style="font-weight:800">'+escH(x.area_name||'--')+'</div><div style="font-size:11px;color:var(--text2)">'+escH((x.location||'')+(x.plant_area?' - '+x.plant_area:''))+'</div></td>'
      +'<td style="padding:10px 12px"><span style="background:#FEE2E2;color:#991B1B;padding:3px 9px;border-radius:99px;font-weight:800;font-size:11px">'+escH(ATEX_ZONE_LABELS[x.zone_type]||x.zone_type||'--')+'</span><div style="font-size:11px;color:var(--text2);margin-top:3px">'+escH((x.material_type||'').replace(/_/g,' '))+'</div></td>'
      +'<td style="padding:10px 12px">'+escH(x.substance||'--')+'<div style="font-size:11px;color:var(--text2)">'+escH(x.source_of_release||'')+'</div></td>'
      +'<td style="padding:10px 12px;font-size:11px;line-height:1.35">'+escH([x.ventilation_controls,x.ignition_controls,x.detection_controls].filter(Boolean).join(' | ')||'--')+'</td>'
      +'<td style="padding:10px 12px;'+(due?'color:var(--red);font-weight:800':'')+'">'+(x.next_inspection_date?new Date(x.next_inspection_date).toLocaleDateString('en-GB'):'--')+(due?'<div style="font-size:10px;color:#A32D2D;font-weight:900">OVERDUE</div>':soon?'<div style="font-size:10px;color:#C2410C;font-weight:900">DUE SOON</div>':'')+'</td>'
      +'<td style="padding:10px 12px;text-align:center"><span style="background:'+cfg[0]+';color:'+cfg[1]+';padding:3px 9px;border-radius:99px;font-weight:800;font-size:11px">'+cfg[2]+'</span></td>'
      +'<td style="padding:10px 12px;text-align:right;white-space:nowrap"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0245"><i class="ti ti-edit"></i></button> <button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0246"><i class="ti ti-shield-check"></i>RA</button> <button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0247"><i class="ti ti-key"></i>PTW</button></td>'
      +'</tr>';
  });
  h+='</tbody></table></div>';
  el.innerHTML=h;
}

function atexShowForm(show){
  document.getElementById('atex-register-view').style.display=show?'none':'block';
  document.getElementById('atex-form').style.display=show?'block':'none';
}

async function atexLoadReferenceOptions(selectedRA,selectedPermit){
  var raSel=document.getElementById('atex-ra');
  var permitSel=document.getElementById('atex-permit');
  if(raSel){
    await fillRiskAssessmentSelect('atex-ra',selectedRA);
  }
  if(permitSel){
    permitSel.innerHTML='<option value="">Select an actual permit...</option>';
    try{var permits=await api('/permits?select=id,permit_number,permit_type,permit_type_v2,status'+cf()+'&order=created_at.desc&limit=150');(permits||[]).forEach(function(p){var ref=p.permit_number||p.id,type=p.permit_type_v2||p.permit_type||'permit',o=document.createElement('option');o.value=ref;verifiedReferenceOption(o,p,ref,'permits');o.dataset.permitType=type;o.textContent=ref+' - '+type.replace(/_/g,' ')+(p.status?' ['+p.status+']':'');permitSel.appendChild(o);});}catch(_){ }
    if(selectedPermit)setSelectValueWithFallback('atex-permit',selectedPermit);
  }
}

async function atexNew(){
  atexEditId=null;
  document.getElementById('atex-form3title').textContent='New ATEX Area';
  document.getElementById('atex-del-btn').style.display='none';
  ['atex-ref','atex-name','atex-location','atex-plant','atex-substance','atex-release','atex-ventilation','atex-ignition','atex-detection','atex-equipment','atex-ra','atex-permit','atex-last','atex-next','atex-resp','atex-notes'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  await atexLoadReferenceOptions();
  fillPersonSelect('atex-resp');
  document.getElementById('atex-zone').value='zone_2';
  document.getElementById('atex-material').value='gas_vapour';
  document.getElementById('atex-status').value='controlled';
  var next=new Date();next.setFullYear(next.getFullYear()+1);
  var nx=document.getElementById('atex-next');if(nx)nx.value=next.toISOString().slice(0,10);
  atexShowForm(true);
}

async function atexEdit(id){
  var x=atexAreas.find(r=>r.id===id);if(!x)return;
  atexEditId=id;
  document.getElementById('atex-form3title').textContent='Edit ATEX Area';
  document.getElementById('atex-del-btn').style.display=isMgr()?'inline-flex':'none';
  await atexLoadReferenceOptions(x.linked_ra_ref,x.linked_permit_ref||x.linked_permit_type);
  var f={'atex-ref':'area_ref','atex-name':'area_name','atex-location':'location','atex-plant':'plant_area','atex-substance':'substance','atex-release':'source_of_release','atex-ventilation':'ventilation_controls','atex-ignition':'ignition_controls','atex-detection':'detection_controls','atex-equipment':'linked_equipment','atex-ra':'linked_ra_ref','atex-permit':'linked_permit_type','atex-last':'last_inspection_date','atex-next':'next_inspection_date','atex-resp':'responsible_person','atex-notes':'notes'};
  Object.entries(f).forEach(function(e){var el=document.getElementById(e[0]);if(el)el.value=x[e[1]]||'';});
  fillPersonSelect('atex-resp',x.responsible_person||'');
  document.getElementById('atex-zone').value=x.zone_type||'zone_2';
  document.getElementById('atex-material').value=x.material_type||'gas_vapour';
  document.getElementById('atex-status').value=x.status||'controlled';
  atexShowForm(true);
}

function atexBack(){atexShowForm(false);atexLoadRegister();}

async function atexSave(){
  if(!isMgr()){toast('Only managers/admins can save ATEX areas',false);return;}
  var name=document.getElementById('atex-name')?.value?.trim();
  if(!name){toast('Please enter area name',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  if(!g('atex-location')){toast('Please enter the ATEX area location',false);return;}
  if(!g('atex-substance')){toast('Please enter the flammable substance or combustible dust',false);return;}
  if(!g('atex-ventilation')||!g('atex-ignition')){toast('Please describe ventilation and ignition source controls',false);return;}
  var nextDate=g('atex-next');
  if(!nextDate){var d=new Date();d.setFullYear(d.getFullYear()+1);nextDate=d.toISOString().slice(0,10);}
  var raLink=verifiedReferenceSelection('atex-ra'),permitLink=verifiedReferenceSelection('atex-permit'),permitOpt=document.getElementById('atex-permit')?.selectedOptions?.[0];
  var body={company_id:ccid(),area_ref:g('atex-ref'),area_name:name,location:g('atex-location'),plant_area:g('atex-plant'),zone_type:g('atex-zone')||'zone_2',material_type:g('atex-material')||'gas_vapour',substance:g('atex-substance'),source_of_release:g('atex-release'),ventilation_controls:g('atex-ventilation'),ignition_controls:g('atex-ignition'),detection_controls:g('atex-detection'),linked_equipment:g('atex-equipment'),linked_ra_ref:raLink.ref,linked_ra_id:raLink.id,linked_permit_ref:permitLink.ref,linked_permit_id:permitLink.id,linked_permit_type:permitOpt?.dataset?.permitType||null,last_inspection_date:g('atex-last'),next_inspection_date:nextDate,status:g('atex-status')||'controlled',responsible_person:g('atex-resp'),notes:g('atex-notes'),updated_at:new Date().toISOString()};
  var previous=atexEditId?(atexAreas.find(function(x){return x.id===atexEditId;})||{}):{};
  var shouldCreateAction=['action_required','out_of_service'].includes(body.status)&&previous.status!==body.status;
  var savedAtexId=atexEditId||null, savedAtexRef=body.area_ref||name;
  try{
    if(atexEditId){
      var updated=await apiWriteWithMissingColumnFallback('/atex_areas?id=eq.'+atexEditId,{m:'PATCH',p:'return=representation',b:body},'ATEX area');
      if(Array.isArray(updated)&&!updated.length)throw new Error('record not found or permission denied');
      savedAtexRef=updated?.[0]?.area_ref||savedAtexRef;
    }
    else{
      body.created_by=prof?.id;
      var res=await apiWriteWithMissingColumnFallback('/atex_areas',{m:'POST',p:'return=representation',b:body},'ATEX area');
      if(res?.[0]?.id){
        savedAtexId=res[0].id;
        if(!body.area_ref){
          savedAtexRef=await nextCompanyRef('atex_areas','area_ref','ATEX-');
          await api('/atex_areas?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{area_ref:savedAtexRef}});
        }else{
          savedAtexRef=body.area_ref;
        }
      }
    }
    if(shouldCreateAction){
      try{
        await api('/action_tracker',{m:'POST',p:'return=minimal',b:{
          company_id:ccid(),title:'ATEX action required: '+name.substring(0,60),
          source_type:'atex',source_module:'atex',source_id:savedAtexId,source_ref:'ATEX - '+savedAtexRef,
          action_type:'corrective',
          description:'ATEX area requires action: '+name+' at '+(body.location||'location')+'. '+(body.notes||body.ignition_controls||'Review controls and inspection status.'),
          responsible:body.responsible_person||null,assigned_to_name:body.responsible_person||null,
          priority:body.status==='out_of_service'?'high':'medium',status:'open',created_by:prof?.id
        }});
      }catch(ex){console.warn('ATEX MAP action failed',ex);}
    }
    toast('ATEX area saved');atexBack();
  }catch(e){toast(actionErrorMessage('Save ATEX area','ATEX areas',e.message),false);}
}

async function atexDelete(){
  if(!atexEditId)return;
  if(!isMgr()){toast('Only managers/admins can archive ATEX areas',false);return;}
  var current=atexAreas.find(function(x){return x.id===atexEditId;})||{};
  var hard=current.status==='archived'||isSA();
  var ok=await appConfirm({
    title:hard?'Delete ATEX area':'Archive ATEX area',
    message:hard?'Delete this ATEX area?':'Archive this ATEX area?',
    detail:hard?'This removes the record from the database.':'The area will be hidden from the active register but retained for traceability.',
    confirmText:hard?'Delete':'Archive',
    cancelText:'Keep record',
    danger:true
  });
  if(!ok)return;
  try{
    if(hard){
      var deleted=await api('/atex_areas?id=eq.'+atexEditId,{m:'DELETE',p:'return=representation'});
      if(Array.isArray(deleted)&&!deleted.length)throw new Error('record not found or permission denied');
    }else{
      var archived=await api('/atex_areas?id=eq.'+atexEditId,{m:'PATCH',p:'return=representation',b:{status:'archived',updated_at:new Date().toISOString()}});
      if(Array.isArray(archived)&&!archived.length)throw new Error('record not found or permission denied');
    }
    toast(hard?'Deleted':'Archived');atexBack();
  }
  catch(e){toast(actionErrorMessage(hard?'Delete ATEX area':'Archive ATEX area','ATEX areas',e.message),false);}
}

