function mocEdit(id){
  var x=mocData.find(r=>r.id===id);if(!x)return;mocEditId=id;
  document.getElementById('moc-form3title').textContent='Edit Change Request';document.getElementById('moc-form3ref').textContent=mocRef(x);
  document.getElementById('moc-title').value=x.title||'';document.getElementById('moc-location').value=x.location||'';document.getElementById('moc-priority').value=x.priority||'medium';document.getElementById('moc-status').value=mocCanonicalStatus(x.lifecycle_status||x.status);document.getElementById('moc-target').value=x.target_date||'';
  var typeTxt=mocMetaFromDescription(x.description,'Change type');var typeKey=x.change_type||Object.keys(MOC_TYPE_LABELS).find(k=>MOC_TYPE_LABELS[k]===typeTxt)||'other';document.getElementById('moc-type').value=typeKey;
  fillPersonSelect('moc-owner',x.owner_id||x.assigned_to_id||x.responsible||x.owner_name||x.assigned_to_name);
  document.getElementById('moc-reason').value=x.reason||mocMetaFromDescription(x.description,'Reason');
  document.getElementById('moc-current').value=x.current_situation||mocMetaFromDescription(x.description,'Current situation');
  document.getElementById('moc-proposed').value=x.proposed_change||mocMetaFromDescription(x.description,'Proposed change');
  document.getElementById('moc-risk-review').value=x.risk_review||mocMetaFromDescription(x.description,'Risk review');
  document.getElementById('moc-pre-actions').value=x.pre_implementation_actions||mocMetaFromDescription(x.description,'Pre-implementation actions');
  document.getElementById('moc-post-review').value=x.post_change_verification||mocMetaFromDescription(x.description,'Post-change verification');
  var impacts=Array.isArray(x.impacted_areas)?x.impacted_areas:(mocMetaFromDescription(x.description,'Impacted areas')||'').split(',').map(s=>s.trim());
  document.querySelectorAll('.moc-impact').forEach(function(cb){cb.checked=impacts.indexOf(cb.value)!==-1;});
  var actionBtn=document.getElementById('moc-create-action-btn');if(actionBtn)actionBtn.style.display=mocLegacyMode?'none':'inline-flex';
  connectedRecordsMount('moc-connected-records',mocLegacyMode?null:relationshipEndpoint('moc','moc_change_requests',x.id,mocRef(x)),{allowCreate:isMgr(),defaultRelationshipType:'related_to'});
  mocShowForm(true);
}
async function mocSave(){
  var title=document.getElementById('moc-title')?.value?.trim();if(!title){toast('Please enter the change title',false);return;}
  var ownerSel=document.getElementById('moc-owner'),ownerPerson=personFromValue(ownerSel?.value);var ownerId=ownerPerson?.id||null;var ownerName=ownerPerson?personFullName(ownerPerson):(ownerSel?.value||'');
  var impacts=[].slice.call(document.querySelectorAll('.moc-impact:checked')).map(function(x){return x.value;});
  try{
    if(mocLegacyMode){
      var legacyLifecycle=document.getElementById('moc-status')?.value||'draft';var legacyStatus=({draft:'open',screening:'open',impact_assessment:'open',pending_approval:'open',approved:'in_progress',implementation:'in_progress',verification:'pending_verification',rejected:'cancelled'}[legacyLifecycle]||legacyLifecycle);
      var legacyBody={company_id:ccid(),title:title,description:mocBuildDescription(),action_type:'preventive',priority:document.getElementById('moc-priority')?.value||'medium',status:legacyStatus,source_type:'moc',source_module:'moc',location:document.getElementById('moc-location')?.value||null,target_date:document.getElementById('moc-target')?.value||null,assigned_to_id:ownerId||null,assigned_to_name:ownerName||null,responsible:ownerName||null,updated_at:new Date().toISOString()};
      if(mocEditId){await api('/action_tracker?id=eq.'+mocEditId,{m:'PATCH',p:'return=minimal',b:legacyBody});toast('Legacy MOC updated');}
      else{legacyBody.created_by=prof?.id;var oldRes=await api('/action_tracker',{m:'POST',p:'return=representation',b:legacyBody});if(oldRes?.[0]?.id){var oldRef=await nextCompanyRef('action_tracker','source_ref','MOC-'+new Date().getFullYear()+'-');await api('/action_tracker?id=eq.'+oldRes[0].id,{m:'PATCH',p:'return=minimal',b:{source_id:oldRes[0].id,source_ref:oldRef,action_ref:oldRef}});toast('Legacy MOC created: '+oldRef);}}
    }else{
      var body={company_id:ccid(),title:title,change_type:document.getElementById('moc-type')?.value||'process',reason:document.getElementById('moc-reason')?.value||null,current_situation:document.getElementById('moc-current')?.value||null,proposed_change:document.getElementById('moc-proposed')?.value||null,impacted_areas:impacts,risk_review:document.getElementById('moc-risk-review')?.value||null,pre_implementation_actions:document.getElementById('moc-pre-actions')?.value||null,post_change_verification:document.getElementById('moc-post-review')?.value||null,priority:document.getElementById('moc-priority')?.value||'medium',lifecycle_status:document.getElementById('moc-status')?.value||'draft',location:document.getElementById('moc-location')?.value||null,target_date:document.getElementById('moc-target')?.value||null,owner_id:ownerId||null,owner_name:ownerName||null,updated_by:prof?.id||null};
      if(mocEditId){await api('/moc_change_requests?id=eq.'+mocEditId,{m:'PATCH',p:'return=minimal',b:body});toast('MOC updated');}
      else{body.created_by=prof?.id||null;body.moc_ref=await nextCompanyRef('moc_change_requests','moc_ref','MOC-'+new Date().getFullYear()+'-');var res=await api('/moc_change_requests',{m:'POST',p:'return=representation',b:body});if(res?.[0]?.id)toast('MOC created: '+body.moc_ref);}
    }
    mocShowForm(false);loadMOC();
  }catch(e){toastActionError('Save change request','Management of Change',e);}
}
async function mocDelete(){
  if(!mocEditId)return;
  var x=mocData.find(r=>r.id===mocEditId)||{};
  try{
    var status=mocCanonicalStatus(x.lifecycle_status||x.status),table=mocLegacyMode?'action_tracker':'moc_change_requests',statusField=mocLegacyMode?'status':'lifecycle_status';
    if(status!=='cancelled'){if(!(await appConfirmAction({title:'Cancel MOC request',message:'Cancel this change request instead of deleting it?',detail:'Cancelled changes remain traceable for audit and management review.',confirmText:'Cancel request',cancelText:'Back',variant:'danger'})))return;var cancelBody={};cancelBody[statusField]='cancelled';await api('/'+table+'?id=eq.'+mocEditId,{m:'PATCH',p:'return=minimal',b:cancelBody});toast('MOC cancelled');mocShowForm(false);loadMOC();return;}
    if(!(await appConfirmDelete('cancelled MOC request','Permanent deletion should be used only for duplicate/test records.')))return;
    await api('/'+table+'?id=eq.'+mocEditId,{m:'DELETE'});toast('MOC deleted');mocShowForm(false);loadMOC();
  }catch(e){toastActionError('Delete change request','Management of Change',e);}
}
