async function mocCreateCorrectiveAction(){
  var x=mocData.find(function(r){return r.id===mocEditId;});if(!x||mocLegacyMode){toast('Save this MOC in the dedicated register first.',false);return;}
  if(!(await appConfirmAction({title:'Create linked corrective action',message:'Create a separate Master Action Plan item for '+mocRef(x)+'?',detail:'The action will have its own owner, due date and closure status. The MOC lifecycle remains independent.',confirmText:'Create action',cancelText:'Back'})))return;
  try{
    var actionRef=await nextCompanyRef('action_tracker','action_ref','MAP-COR-'+new Date().getFullYear()+'-');
    var body={company_id:ccid(),action_ref:actionRef,title:'MOC action: '+(x.title||mocRef(x)),description:x.pre_implementation_actions||x.risk_review||'Complete the controls required by '+mocRef(x),action_type:'corrective',priority:x.priority||'medium',status:'open',source_type:'moc',source_module:'moc',source_table:'moc_change_requests',source_id:x.id,source_ref:mocRef(x),location:x.location||null,target_date:x.target_date||null,assigned_to_id:x.owner_id||null,assigned_to_name:x.owner_name||null,responsible:x.owner_name||null,created_by:prof?.id||null};
    var result=await api('/action_tracker',{m:'POST',p:'return=representation',b:body});var action=result&&result[0];
    if(action){try{await relationshipCreate(relationshipEndpoint('moc','moc_change_requests',x.id,mocRef(x)),relationshipEndpoint('action','action_tracker',action.id,actionRef),'generated_action',{});}catch(linkError){console.warn('MOC action created; relationship link pending',linkError);}toast('Linked corrective action created: '+actionRef);mocEdit(x.id);}
  }catch(e){toastActionError('Create corrective action','Management of Change',e);}
}
