function dcRenderAckTable(d){
  var now=new Date();
  var stCfg={pending:['#FEF9EC','#854F0B'],acknowledged:['#EAF3DE','#3B6D11'],overdue:['#FCEBEB','#A32D2D'],declined:['#f3f4f6','#6B7280']};
  var h='<div class="table-scroll"><table class="data-table" style="min-width:980px"><thead><tr><th>Employee</th><th>Document</th><th>Version</th><th>Due date</th><th>Acknowledged</th><th>Status</th><th style="width:70px"></th></tr></thead><tbody>';
  d.forEach(function(a,i){
    var bg=i%2===0?'#fff':'#f9fafb';
    var sc=stCfg[a.status]||stCfg.pending;
    var isOverdue=a.status==='pending'&&a.due_date&&new Date(a.due_date)<now;
    h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
      +'<td style="padding:8px 14px"><div style="font-weight:700">'+escH(a.employee_name||'-')+'</div><div style="font-size:10px;color:var(--text2)">'+escH(a.department||'')+'</div></td>'
      +'<td style="padding:8px;max-width:200px"><div style="font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escH(a.doc_title||'-')+'</div><div style="font-size:10px;font-family:monospace;color:#7C3AED">'+escH(a.doc_ref||'')+'</div></td>'
      +'<td style="padding:8px;font-family:monospace;font-size:11px;font-weight:700">'+escH(a.doc_version||'-')+'</td>'
      +'<td style="padding:8px;font-size:11px;color:'+(isOverdue?'var(--red)':'inherit');
    h+='">'+(a.due_date?new Date(a.due_date).toLocaleDateString('en-GB')+(isOverdue?' - overdue':''):'-')+'</td>'
      +'<td style="padding:8px;font-size:11px">'+(a.acknowledged_at?new Date(a.acknowledged_at).toLocaleDateString('en-GB'):'-')+'</td>'
      +'<td style="padding:8px"><span style="background:'+sc[0]+';color:'+sc[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700;text-transform:capitalize">'+escH(isOverdue?'Overdue':a.status)+'</span></td>'
      +'<td style="padding:8px"><div style="display:flex;gap:4px">'+(a.status==='pending'&&isMgr()?'<button class="btn btn-sm" style="background:var(--green);color:#fff;border-color:var(--green);font-size:10px" data-id="'+a.id+'" data-auris-generated-onclick="g0259"><i class="ti ti-check"></i></button>':'')+'</div></td></tr>';
  });
  return h+'</tbody></table></div>';
}

