async function legalRefreshMetrics(){
  var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
  var safeLegal=function(p){return api(p).catch(function(){return [];});};
  try{
    var now=new Date();
    var soon=new Date(now.getTime()+30*86400000);
    var results=await Promise.all([
      safeLegal('/compliance_gaps?select=id,status'+cf()),
      safeLegal('/compliance_assessments?select=id'+cf()),
      safeLegal('/compliance_calendar?select=id,status,due_date'+cf())
    ]);
    var gaps=results[0]||[], assessments=results[1]||[], calendar=results[2]||[];
    var due30=calendar.filter(function(x){
      if(x.status==='completed'||!x.due_date)return false;
      var d=new Date(x.due_date);
      return d>=now&&d<=soon;
    });
    setM('lr-m3gaps',gaps.filter(function(x){return ['open','in_progress'].includes(x.status);}).length);
    setM('lr-m3assessments',assessments.length);
    setM('lr-m3cal-due',due30.length);
  }catch(e){}
}

function legalSwitchTab(tab,btn){
  document.querySelectorAll('[id^="legal-tab-"]').forEach(t=>t.classList.remove('active'));
  if(btn)btn.classList.add('active');
  ['register','changes','assessments','gaps','calendar','dashboard'].forEach(function(t){
    var el=document.getElementById('legal-view-'+t);if(el)el.style.display=t===tab?'block':'none';
  });
  ['legal-req-form','legal-chg-form','lca-form','gap-form','cal-form'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.style.display='none';
  });
  // Update new-btn label
  var labels={register:'Add requirement',changes:'Add change',assessments:'New assessment',gaps:'Add gap',calendar:'Add event',dashboard:null};
  var newBtn=document.getElementById('legal-new-btn');
  if(newBtn){if(labels[tab]){newBtn.innerHTML='<i class="ti ti-plus"></i>'+labels[tab];newBtn.style.display=isMgr()?'inline-flex':'none';}else newBtn.style.display='none';}
  if(tab==='register')legalLoadRegister();
  else if(tab==='changes')legalLoadChanges();
  else if(tab==='assessments')lcaLoad();
  else if(tab==='gaps')gapLoad();
  else if(tab==='calendar')calLoad('overdue',document.getElementById('cal-btn-overdue'));
  else if(tab==='dashboard')legalRenderDashboard();
}

