async function legalParsePdfFile(file){
  if(!file)return;
  var msg=document.getElementById('lr-pdf-status-msg');
  var preview=document.getElementById('lr-pdf-preview');
  if(msg)msg.textContent='Reading PDF... this can take a few seconds for long Acts.';
  if(preview)preview.innerHTML='<div class="loading-msg">Extracting legal sections...</div>';
  try{
    if(!window.pdfjsLib)throw new Error('PDF reader is not loaded. Check your internet connection and try again.');
    if(window.pdfjsLib.GlobalWorkerOptions){
      window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    }
    var buffer=await file.arrayBuffer();
    var pdf=await window.pdfjsLib.getDocument({data:buffer}).promise;
    var pages=[];
    for(var p=1;p<=pdf.numPages;p++){
      var page=await pdf.getPage(p);
      var content=await page.getTextContent();
      var lastY=null,line='';
      content.items.forEach(function(item){
        var y=Math.round(item.transform[5]);
        if(lastY!==null&&Math.abs(y-lastY)>4){pages.push(line.trim());line='';}
        line+=(line?' ':'')+item.str;
        lastY=y;
      });
      if(line.trim())pages.push(line.trim());
      pages.push('');
      if(msg)msg.textContent='Reading PDF page '+p+' of '+pdf.numPages+'...';
    }
    var fullText=pages.join('\n');
    legalApplyPdfMetadata(fullText,file.name);
    legalPdfImportRows=legalParseActSections(fullText);
    legalRenderPdfPreview(legalPdfImportRows,file.name);
  }catch(e){
    legalPdfImportRows=[];
    if(msg)msg.textContent='Could not read PDF: '+e.message;
    if(preview)preview.innerHTML='<div style="padding:14px;color:var(--red);font-size:13px">PDF import failed. '+escH(e.message)+'</div>';
  }
}

function legalCleanPdfLine(line){
  return (line||'').replace(/\s+/g,' ').replace(/\s+([,.;:])/g,'$1').trim();
}

function legalApplyPdfMetadata(text,fileName){
  var meta=legalDetectLegislationMeta(text,fileName);
  var legEl=document.getElementById('lr-pdf-legislation');
  var prefixEl=document.getElementById('lr-pdf-prefix');
  if(meta.legislation&&legEl)legEl.value=meta.legislation;
  if(meta.prefix&&prefixEl)prefixEl.value=meta.prefix;
}

function legalDetectLegislationMeta(text,fileName){
  var cleaned=(text||'').replace(/\s+/g,' ').trim();
  var upper=cleaned.toUpperCase();
  var name='';
  var known=[
    {re:/OCCUPATIONAL\s+SAFETY\s+AND\s+HEALTH\s+ACT/i,name:'Occupational Safety and Health Act 2005',prefix:'OSH'},
    {re:/ENVIRONMENT\s+PROTECTION\s+ACT/i,name:'Environment Protection Act 2002',prefix:'EPA'},
    {re:/FIRE\s+SERVICES\s+ACT/i,name:'Fire Services Act',prefix:'FIRE'},
    {re:/WORKERS'?[\s-]+RIGHTS\s+ACT/i,name:'Workers Rights Act',prefix:'WRA'},
    {re:/EMPLOYMENT\s+RIGHTS\s+ACT/i,name:'Employment Rights Act',prefix:'ERA'}
  ];
  for(var i=0;i<known.length;i++){
    if(known[i].re.test(cleaned))return {legislation:known[i].name,prefix:known[i].prefix};
  }
  var shortTitle=cleaned.match(/This\s+(Act|Regulation|Regulations)\s+may\s+be\s+cited\s+as\s+the\s+([^.;]+?)(?:\.|,| and shall|$)/i);
  if(shortTitle&&shortTitle[2])name=legalCleanLegislationName(shortTitle[2]);
  if(!name){
    var title=upper.match(/([A-Z][A-Z\s,'()&-]{8,}?(?:ACT|REGULATIONS?|ORDER|RULES)(?:\s+NO\.?\s*\d+\s+OF\s+\d{4}|\s+\d{4})?)/);
    if(title&&title[1])name=legalTitleCase(legalCleanLegislationName(title[1]));
  }
  if(!name&&fileName){
    name=legalTitleCase(legalCleanLegislationName(fileName.replace(/\.pdf$/i,'').replace(/^\d+[\.\-\s]*/,'')));
  }
  return {legislation:name||'Imported Legal Act',prefix:legalMakeLegislationPrefix(name||fileName||'LEG')};
}

function legalCleanLegislationName(name){
  return (name||'')
    .replace(/\s*\(\d+\)\s*$/,'')
    .replace(/\s+No\.?\s*\d+\s+of\s+\d{4}/i,'')
    .replace(/[,;]\s*$/,'')
    .replace(/\s+/g,' ')
    .trim();
}

function legalTitleCase(s){
  var small={and:1,of:1,the:1,in:1,on:1,for:1,to:1,a:1,an:1};
  return (s||'').toLowerCase().split(/\s+/).map(function(w,i){
    if(i>0&&small[w])return w;
    return w.charAt(0).toUpperCase()+w.slice(1);
  }).join(' ').replace(/\bOsha\b/g,'OSHA').replace(/\bOsh\b/g,'OSH').replace(/\bIso\b/g,'ISO');
}

function legalMakeLegislationPrefix(name){
  var n=(name||'').toUpperCase();
  if(/OCCUPATIONAL\s+SAFETY\s+AND\s+HEALTH|OSH\b/.test(n))return 'OSH';
  if(/ENVIRONMENT\s+PROTECTION/.test(n))return 'EPA';
  if(/FIRE/.test(n))return 'FIRE';
  if(/WORKERS'?[\s-]+RIGHTS/.test(n))return 'WRA';
  if(/EMPLOYMENT\s+RIGHTS/.test(n))return 'ERA';
  var words=n.replace(/[^A-Z0-9\s]/g,' ').split(/\s+/).filter(function(w){
    return w&&!['THE','OF','AND','ACT','REGULATION','REGULATIONS','NO','NUMBER','REVISED','LAWS','MAURITIUS'].includes(w)&&!/^\d+$/.test(w);
  });
  var prefix=words.slice(0,3).map(function(w){return w.charAt(0);}).join('');
  if(prefix.length<2)prefix=(words[0]||'LEG').slice(0,4);
  return (prefix||'LEG').slice(0,8);
}

function legalParseActSections(text){
  var raw=(text||'').split(/\n+/).map(legalCleanPdfLine).filter(Boolean);
  var lines=raw.filter(function(line){
    if(/^Revised Laws of Mauritius$/i.test(line))return false;
    if(/^Occupational Safety and Health Act$/i.test(line))return false;
    if(/^\[Issue\s+\d+\]/i.test(line))return false;
    if(/^O\d+\s+\d+/i.test(line))return false;
    if(/^\d+\s+\[Issue\s+\d+\]/i.test(line))return false;
    if(/^SECTION$/i.test(line))return false;
    return true;
  });
  var bodyStart=0, shortTitleHits=0;
  for(var i=0;i<lines.length;i++){
    if(/^1\.\s+Short title\b/i.test(lines[i])){
      shortTitleHits++;
      if(shortTitleHits>=2){bodyStart=i;break;}
    }
  }
  if(!bodyStart){
    for(var j=0;j<lines.length;j++){
      if(/^PART\s+I\b/i.test(lines[j])&&/^1\.\s+Short title\b/i.test(lines[j+1]||'')){bodyStart=j;break;}
    }
  }
  lines=lines.slice(bodyStart);
  var sections=[], current=null, currentPart='', lastNo=0, inSchedules=false;
  lines.forEach(function(line){
    if(inSchedules)return;
    if(lastNo>=100&&/^(FIRST|SECOND|THIRD|FOURTH|FIFTH|SIXTH|SEVENTH|EIGHTH|NINTH|TENTH|ELEVENTH|TWELFTH|THIRTEENTH|FOURTEENTH|FIFTEENTH|SIXTEENTH|SEVENTEENTH|EIGHTEENTH|NINETEENTH|TWENTIETH|TWENTY-FIRST)\s+SCHEDULE\b/i.test(line)){
      inSchedules=true;
      return;
    }
    var partMatch=line.match(/^(PART\s+[IVXLC]+)\b\s*(.*)$/i);
    if(partMatch){currentPart=legalCleanPdfLine(partMatch[1]+' '+(partMatch[2]||''));return;}
    var sec=line.match(/^(\d{1,3})\.\s+(.{3,})$/);
    if(sec){
      var no=parseInt(sec[1],10);
      if(no>=1&&no<=130&&(lastNo===0||no>lastNo||no===1)){
        if(current)sections.push(current);
        current={section:String(no),title:legalCleanPdfLine(sec[2]),part:currentPart,requirement:''};
        lastNo=no;
        return;
      }
    }
    if(current)current.requirement+=(current.requirement?' ':'')+line;
  });
  if(current)sections.push(current);
  return sections.filter(function(s){return s.title&&s.requirement&&s.requirement.length>20;}).map(function(s){
    var inferred=legalInferRequirementMeta(s.title+' '+s.requirement);
    s.category=inferred.category;
    s.obligation_type=inferred.obligation_type;
    s.frequency=inferred.frequency;
    return s;
  });
}

function legalInferRequirementMeta(text){
  var t=(text||'').toLowerCase();
  var category='health_safety';
  if(/committee|consultation|representative|safety and health committee|employee representative/.test(t))category='consultation';
  else if(/training|instruction|information|competenc|competent person|supervision|briefing/.test(t))category='training';
  else if(/accident|incident|dangerous occurrence|notification|notify|reporting|record of accident|investigation/.test(t))category='incident_reporting';
  else if(/health surveillance|medical examination|occupational illness|occupational disease|exposure monitoring|biological monitoring|audiometry|spirometry/.test(t))category='occupational_health';
  else if(/first aid|hygiene|sanitary|washing|drinking water|welfare|toilet|rest room|changing room|facilities/.test(t))category='welfare';
  else if(/ppe|personal protective|protective equipment|respirator|helmet|glove|safety shoes|eye protection|hearing protection/.test(t))category='ppe';
  else if(/machinery|machine|guard|interlock|moving part|lifting appliance|pressure vessel|hoist|crane|forklift|tool|equipment/.test(t))category='machinery';
  else if(/fire|flammable|explosive|explosion|means of escape|emergency exit|fire extinguisher|alarm|evacuation/.test(t))category='fire';
  else if(/environment|pollution|waste|effluent|emission|spill|contamination|discharge/.test(t))category='environment';
  else if(/chemical|hazardous|corrosive|fume|gas|vapour|substance|asbestos|biological|sds|material safety data/.test(t))category='chemical';
  else if(/electric|electrical|voltage|wiring|circuit|earthing|energised|energized/.test(t))category='electrical';
  else if(/construction|scaffold|ladder|excavation|demolition|work at height|roof work|temporary works/.test(t))category='construction';
  else if(/noise|vibration/.test(t))category='noise';
  else if(/cleanliness|overcrowding|ventilation|temperature|lighting|floor|workplace|premises|passageway|traffic route|housekeeping/.test(t))category='workplace_conditions';
  var obligation=/\bmay\b/.test(t)&&!/\bshall\b|\bmust\b/.test(t)?'conditional':'mandatory';
  var frequency=/notify|notification|report|accident|dangerous occurrence|certificate|registration|permit/.test(t)?'as_required':'ongoing';
  return {category:category,obligation_type:obligation,frequency:frequency};
}

function legalCategoryOptionsHtml(selected){
  return Object.keys(LEGAL_CAT_CFG).map(function(k){
    var c=LEGAL_CAT_CFG[k]||LEGAL_CAT_CFG.other;
    return '<option value="'+escH(k)+'" '+(k===selected?'selected':'')+'>'+escH(c.label)+'</option>';
  }).join('');
}

function legalStatusScore(status){
  if(status==='compliant')return 100;
  if(status==='partial')return 50;
  return 0;
}

function legalRefSortValue(x){
  var s=String(x?.section||'').trim();
  var ref=String(x?.req_ref||'').trim();
  var first=(s.match(/\d+/)||ref.match(/\d+/)||['999999'])[0];
  return parseInt(first,10)||999999;
}

function legalRenderPdfPreview(rows,fileName){
  var msg=document.getElementById('lr-pdf-status-msg');
  var preview=document.getElementById('lr-pdf-preview');
  if(msg)msg.textContent=rows.length+' sections detected from '+fileName+'. Review before importing.';
  if(!preview)return;
  if(!rows.length){
    preview.innerHTML='<div style="padding:14px;color:var(--red);font-size:13px">No legal sections were detected. Try another PDF or a searchable text PDF.</div>';
    return;
  }
  var h='<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px;flex-wrap:wrap">'
    +'<div style="font-size:12px;color:var(--text2)">Selected rows will be imported as Legal Register requirements.</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap">'
    +'<button class="btn btn-sm" data-auris-generated-onclick="g0261">Select all</button>'
    +'<button class="btn btn-sm" data-auris-generated-onclick="g0262">Select none</button>'
    +'<button class="btn btn-primary btn-sm" data-auris-generated-onclick="g0263"><i class="ti ti-database-import"></i>Import selected</button>'
    +'</div></div>';
  h+='<div style="max-height:420px;overflow:auto;border:1px solid var(--border);border-radius:10px;background:#fff"><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#1a3a5c;color:#fff"><th style="width:38px;padding:8px;color:#fff"></th><th style="padding:8px;color:#fff;text-align:left">Section</th><th style="padding:8px;color:#fff;text-align:left">Title / requirement preview</th><th style="padding:8px;color:#fff;text-align:left">Category</th></tr></thead><tbody>';
  rows.forEach(function(r,i){
    var cat=LEGAL_CAT_CFG[r.category]||LEGAL_CAT_CFG.other;
    h+='<tr>'
      +'<td style="padding:8px;text-align:center"><input type="checkbox" class="lr-pdf-row" data-idx="'+i+'" checked style="width:16px!important;height:16px!important;margin:0"/></td>'
      +'<td style="padding:8px;font-family:monospace;font-weight:800;color:#185FA5;white-space:nowrap">'+escH(r.section)+'</td>'
      +'<td style="padding:8px"><div style="font-weight:700">'+escH(r.title)+'</div><div style="font-size:11px;color:var(--text2);line-height:1.35">'+escH(r.requirement.substring(0,220))+(r.requirement.length>220?'...':'')+'</div>'+(r.part?'<div style="font-size:10px;color:#6B7280;margin-top:3px">'+escH(r.part)+'</div>':'')+'</td>'
      +'<td style="padding:8px"><select class="lr-pdf-cat" data-idx="'+i+'" style="width:170px;padding:6px 8px;border:1px solid var(--border);border-radius:8px;font-size:12px">'+legalCategoryOptionsHtml(r.category||'health_safety')+'</select><div style="font-size:10px;color:'+cat.color+';font-weight:700;margin-top:3px">Auto: '+escH(cat.label)+'</div></td>'
      +'</tr>';
  });
  h+='</tbody></table></div>';
  preview.innerHTML=h;
}

function legalTogglePdfRows(checked){
  document.querySelectorAll('.lr-pdf-row').forEach(function(cb){cb.checked=checked;});
}

async function legalImportPdfRows(){
  if(!isMgr()){toast('Only managers/admins can import legal requirements',false);return;}
  var selected=Array.from(document.querySelectorAll('.lr-pdf-row:checked')).map(function(cb){
    var idx=parseInt(cb.dataset.idx,10);
    var row=Object.assign({},legalPdfImportRows[idx]||{});
    var cat=document.querySelector('.lr-pdf-cat[data-idx="'+idx+'"]');
    if(cat)row.category=cat.value||row.category;
    return row;
  }).filter(function(x){return x&&x.title;});
  if(!selected.length){toast('Select at least one section to import',false);return;}
  var legislation=(document.getElementById('lr-pdf-legislation')?.value||'Imported Legal Act').trim();
  var prefix=(document.getElementById('lr-pdf-prefix')?.value||'LEG').trim().toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8)||'LEG';
  var status=document.getElementById('lr-pdf-status')?.value||'partial';
  var score=legalStatusScore(status);
  var source=document.getElementById('lr-pdf-input')?.files?.[0]?.name||null;
  var existing=new Set((lrAllData||[]).filter(function(x){return x.legislation===legislation;}).map(function(x){return String(x.section||'').trim();}));
  var rows=selected.filter(function(x){return !existing.has(String(x.section||'').trim());}).map(function(x){
    return {company_id:ccid(),req_ref:prefix+'-'+String(x.section).padStart(3,'0'),legislation:legislation,legislation_type:'statutory',part:x.part||null,title:x.title,section:x.section,requirement:x.requirement,category:x.category||'health_safety',jurisdiction:'Mauritius',authority:legislation.toLowerCase().includes('environment')?'Ministry of Environment':'OSHI',obligation_type:x.obligation_type||'mandatory',frequency:x.frequency||'ongoing',applicable:true,status:status,compliance_score:score,notes:source?'Imported from PDF: '+source:null,source_url:source,last_verified_at:new Date().toISOString(),created_by:prof?.id,updated_at:new Date().toISOString()};
  });
  if(!rows.length){toast('All selected sections already exist for this legislation',false);return;}
  var msg=document.getElementById('lr-pdf-status-msg');
  try{
    if(msg)msg.textContent='Importing '+rows.length+' sections...';
    for(var i=0;i<rows.length;i+=50){await api('/legal_requirements',{m:'POST',p:'return=minimal',b:rows.slice(i,i+50)});}
    toast('Imported '+rows.length+' legal sections');
    legalCancelPdfImport();
    legalLoadRegister();
  }catch(e){
    if(/part|source_url|last_verified_at|schema cache|column/i.test(e.message||'')){
      try{
        var basicRows=rows.map(function(r){var x=Object.assign({},r);delete x.part;delete x.source_url;delete x.last_verified_at;return x;});
        for(var j=0;j<basicRows.length;j+=50){await api('/legal_requirements',{m:'POST',p:'return=minimal',b:basicRows.slice(j,j+50)});}
        toast(isSA()?('Imported '+basicRows.length+' sections. Source tracking setup is still pending for this workspace.'):'Imported '+basicRows.length+' sections. Source tracking can be enabled later by SEPHS admin.');
        legalCancelPdfImport();
        legalLoadRegister();
        return;
      }catch(e2){
        if(msg)msg.textContent=actionErrorMessage('Import legislation','Legal Compliance',e2);
        toast(actionErrorMessage('Import legislation','Legal Compliance',e2),false);
        return;
      }
    }
    if(msg)msg.textContent=actionErrorMessage('Import legislation','Legal Compliance',e);
    toast(actionErrorMessage('Import legislation','Legal Compliance',e),false);
  }
}

// -- LEGAL REGISTER ------------------------------------------------------------
async function legalLoadRegister(){
  var el=document.getElementById('lr-table');if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/legal_requirements?select=*'+cf()+'&order=legislation,section');
    lrAllData=d||[];
    var now=new Date();
    var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
    var apps=(d||[]).filter(x=>x.applicable!==false&&x.status!=='not_applicable');
    setM('lr-m3compliant',(d||[]).filter(x=>x.status==='compliant').length);
    setM('lr-m3partial',(d||[]).filter(x=>x.status==='partial').length);
    setM('lr-m3noncompliant',(d||[]).filter(x=>x.status==='non_compliant').length);
    setM('lr-m3total',(d||[]).length);
    // Populate legislation filter
    var legSel=document.getElementById('lr-filter-leg');
    if(legSel){
      var legs=[...new Set((d||[]).map(x=>x.legislation).filter(Boolean))].sort();
      var existing=Array.from(legSel.options).map(o=>o.value);
      legs.forEach(function(leg){if(!existing.includes(leg)){var o=document.createElement('option');o.value=leg;o.textContent=leg.length>45?leg.substring(0,45)+'-':leg;legSel.appendChild(o);}});
    }
    legalFilterRegister();
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

function legalFilterRegister(){
  var el=document.getElementById('lr-table');if(!el)return;
  var q=(document.getElementById('lr-search')?.value||'').toLowerCase();
  var fs=document.getElementById('lr-filter-status')?.value||'';
  var fl=document.getElementById('lr-filter-leg')?.value||'';
  var fc=document.getElementById('lr-filter-cat')?.value||'';
  var showArchived=document.getElementById('lr-filter-archived')?.value==='true';
  var filt=lrAllData.filter(function(x){
    var mQ=!q||(x.legislation||'').toLowerCase().includes(q)||(x.title||'').toLowerCase().includes(q)||(x.requirement||'').toLowerCase().includes(q)||(x.req_ref||'').toLowerCase().includes(q)||(x.section||'').toLowerCase().includes(q);
    var mS=!fs||x.status===fs;
    var mL=!fl||x.legislation===fl;
    var mC=!fc||(x.category||'')=== fc;
    var mA=showArchived||!legalReqArchived(x);
    return mQ&&mS&&mL&&mC&&mA;
  });
  filt.sort(function(a,b){
    var leg=(a.legislation||'').localeCompare(b.legislation||'');
    if(leg!==0)return leg;
    var na=legalRefSortValue(a), nb=legalRefSortValue(b);
    if(na!==nb)return na-nb;
    return String(a.req_ref||'').localeCompare(String(b.req_ref||''),undefined,{numeric:true,sensitivity:'base'});
  });
  if(!filt.length){
    el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600;margin-bottom:8px">No requirements found</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0264"><i class="ti ti-plus"></i>Add first requirement</button>':'')+'</div>';
    return;
  }
  var archivedCount=(lrAllData||[]).filter(legalReqArchived).length;
  var bulk=isMgr()?'<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border-bottom:1px solid var(--border);background:#f9fafb;flex-wrap:wrap"><div style="font-size:12px;color:var(--text2)">'+filt.length+' visible requirement'+(filt.length>1?'s':'')+' sorted by legislation and section number'+(archivedCount&&!showArchived?' Â· '+archivedCount+' archived hidden':'')+'</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-sm" data-auris-generated-onclick="g0265"><i class="ti ti-checks"></i>Select visible</button><button class="btn btn-sm" data-auris-generated-onclick="g0266"><i class="ti ti-square"></i>Clear</button><button class="btn btn-sm" style="color:var(--red);border-color:#fecaca" data-auris-generated-onclick="g0267"><i class="ti ti-archive"></i>Archive selected</button><button class="btn btn-sm" style="background:#FCEBEB;color:#A32D2D;border-color:#fecaca" data-auris-generated-onclick="g0268"><i class="ti ti-archive"></i>Archive legislation</button></div></div>':'';
  var h=bulk+'<div class="table-scroll"><table class="data-table" style="min-width:1180px"><thead><tr>'+(isMgr()?'<th style="width:38px;text-align:center"><input type="checkbox" id="lr-select-all-visible" data-auris-generated-onchange="g0269" style="width:16px!important;height:16px!important;margin:0"/></th>':'')+'<th>Ref</th><th>Legislation</th><th style="min-width:300px">Section / Requirement</th><th>Category</th><th>Obligation</th><th>Responsibility</th><th style="text-align:center">Score</th><th>Status</th><th style="width:50px"></th></tr></thead><tbody>';
  filt.forEach(function(x,i){
    var bg=i%2===0?'#fff':'#f9fafb';
    var sc=LEG_STATUS_CFG[x.status]||LEG_STATUS_CFG.non_compliant;
    var catCfg=LEGAL_CAT_CFG[x.category||'other']||LEGAL_CAT_CFG.other;
    var hasGap=x.gap||x.gap_identified;
    var score=x.compliance_score!=null?x.compliance_score:sc.score;
    var scoreColor=score==null?'#6B7280':score>=80?'#1D9E75':score>=50?'#EF9F27':score>=20?'#C2410C':'#A32D2D';
    var archived=legalReqArchived(x);
    h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+';cursor:pointer'+(archived?';opacity:.62':'')+'" data-auris-runtime-onclick="r0097" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id]))+'">'
      +(isMgr()?'<td style="padding:8px;text-align:center"><input type="checkbox" class="lr-row-select" data-id="'+x.id+'" data-auris-generated-onclick="g0179" style="width:16px!important;height:16px!important;margin:0"/></td>':'')
      +'<td style="padding:8px 14px;font-family:monospace;font-size:11px;font-weight:700;color:#185FA5">'+escH(displayRecordRef(x,'req_ref','LEG-DRAFT'))+'</td>'
      +'<td style="padding:8px;max-width:180px"><div style="font-size:11px;font-weight:600;color:#185FA5">'+escH((x.legislation||'-').substring(0,45))+'</div>'+(x.legislation_type?'<div style="font-size:10px;color:var(--text2);text-transform:capitalize">'+escH(x.legislation_type.replace(/_/g,' '))+'</div>':'')+'</td>'
      +'<td style="padding:8px;max-width:250px"><div style="font-weight:600">'+escH(x.title||('Section '+(x.section||'-')))+'</div><div style="font-size:11px;color:var(--text2)">'+escH((x.requirement||'').substring(0,80))+(x.requirement?.length>80?'-':'')+'</div>'+(hasGap?'<span style="background:#FCEBEB;color:#A32D2D;padding:1px 6px;border-radius:4px;font-size:10px;font-weight:700;margin-top:2px;display:inline-block">GAP</span>':'')+(archived?'<span style="background:#F3F4F6;color:#6B7280;padding:1px 6px;border-radius:4px;font-size:10px;font-weight:800;margin-left:4px;display:inline-block">ARCHIVED</span>':'')+'</td>'
      +'<td style="padding:8px"><span style="background:'+catCfg.color+'15;color:'+catCfg.color+';padding:2px 7px;border-radius:99px;font-size:10px;font-weight:600">'+catCfg.emoji+' '+catCfg.label+'</span></td>'
      +'<td style="padding:8px;font-size:11px;text-transform:capitalize">'+escH((x.obligation_type||'mandatory').replace(/_/g,' '))+'</td>'
      +'<td style="padding:8px;font-size:11px">'+escH(x.responsibility||x.responsible_person||'-')+'</td>'
      +'<td style="padding:8px;text-align:center;font-weight:800;color:'+scoreColor+'">'+(score!=null?score+'%':'-')+'</td>'
      +'<td style="padding:8px"><span style="background:'+sc.bg+';color:'+sc.tc+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+sc.label+'</span></td>'
      +'<td style="padding:8px"><button class="btn btn-sm" title="View requirement" data-id="'+x.id+'" data-auris-generated-onclick="g0270"><i class="ti ti-eye"></i></button></td></tr>';
  });
  h+='</tbody></table></div>';el.innerHTML=h;
}

function legalStatusBadge(s){var c=LEG_STATUS_CFG[s]||LEG_STATUS_CFG.non_compliant;return '<span style="background:'+c.bg+';color:'+c.tc+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+c.label+'</span>';}
function legalReqArchived(x){
  return ohIsArchivedText(x?.notes)||ohIsArchivedText(x?.comments)||String(x?.status||'').toLowerCase()==='archived'||(String(x?.applicable)==='false'&&/archived|retired|deleted/i.test(String(x?.notes||'')));
}
function legalArchiveBody(x){
  return {applicable:false,status:'not_applicable',compliance_score:0,notes:ohArchivedText(x?.notes||'Archived from legal register'),updated_at:new Date().toISOString()};
}

