function legalReqEditMode(edit){
  var review=document.getElementById('lr-review-card'),form=document.getElementById('lr-edit-card'),save=document.getElementById('lr-save-btn'),ai=document.getElementById('lr-ai-btn'),editBtn=document.getElementById('lr-edit-btn'),del=document.getElementById('lr-del-btn');
  if(review)review.style.display=edit?'none':'block';
  if(form)form.style.display=edit?'block':'none';
  if(save)save.style.display=edit?'inline-flex':'none';
  if(ai)ai.style.display=edit?'inline-flex':'none';
  if(editBtn)editBtn.style.display=(!edit&&isMgr())?'inline-flex':'none';
  if(del)del.style.display=(edit&&isMgr()&&lrEditId)?'inline-flex':'none';
}
function legalReqReviewHtml(x){
  var st=x.status||'non_compliant';
  var sc=LEG_STATUS_CFG[st]||LEG_STATUS_CFG.non_compliant;
  var cat=LEGAL_CAT_CFG[x.category||'other']||LEGAL_CAT_CFG.other;
  var hasGap=!!(x.gap||x.gap_identified);
  var row=function(label,value){return '<div><div class="form3label">'+label+'</div><div style="font-weight:700;color:#111827;white-space:pre-wrap">'+escH(value||'-')+'</div></div>';};
  return '<div style="display:grid;grid-template-columns:1.2fr .8fr .8fr .8fr;gap:10px;margin-bottom:14px">'
    +row('Legislation',x.legislation)
    +row('Section / ref',x.section||x.subsection)
    +'<div><div class="form3label">Category</div><span style="background:'+cat.color+'15;color:'+cat.color+';padding:3px 9px;border-radius:99px;font-size:12px;font-weight:800">'+cat.emoji+' '+escH(cat.label)+'</span></div>'
    +'<div><div class="form3label">Status</div><span style="background:'+sc.bg+';color:'+sc.tc+';padding:3px 9px;border-radius:99px;font-size:12px;font-weight:800">'+escH(sc.label)+'</span></div>'
    +'</div><div class="card" style="background:#F8FBFF;border-color:#BFDBFE;margin-bottom:14px"><div class="card-title" style="color:#0F766E">'+escH(x.title||'Legal requirement')+'</div><div style="white-space:pre-wrap;font-size:13px;line-height:1.5;color:#111827">'+escH(x.requirement||'No wording recorded.')+'</div></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px"><div class="card" style="border-left:4px solid #1D9E75"><div class="card-title" style="color:#1D9E75">Current controls and evidence</div>'+row('Controls in place',x.controls||'No current controls recorded')+'<div style="height:10px"></div>'+row('Evidence required',x.evidence_required)+'<div style="height:10px"></div>'+row('Evidence location / document ref',x.evidence_location)+'</div><div class="card" style="border-left:4px solid '+(hasGap?'#DC2626':'#1D9E75')+'"><div class="card-title" style="color:'+(hasGap?'#DC2626':'#1D9E75')+'">'+(hasGap?'Gap identified':'No gap identified')+'</div>'+row('Further controls / recommendations',x.further_controls||x.gap_description||x.recommendations)+'<div style="height:10px"></div>'+row('Penalty / risk',x.penalty_risk)+'</div></div>'
    +'<div class="card"><div class="card-title">Responsibility and review</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px">'+row('Responsibility',x.responsibility||x.responsible_person)+row('Target date',x.target_date?new Date(x.target_date).toLocaleDateString('en-GB'):'')+row('Last assessed',x.last_assessed_date?new Date(x.last_assessed_date).toLocaleDateString('en-GB'):'')+row('Assessed by',x.assessed_by)+'</div>'+(x.notes?'<div style="margin-top:12px">'+row('Notes',x.notes)+'</div>':'')+'</div>';
}
function legalLoadReqIntoForm(x){
  document.getElementById('lr-form3title').textContent=x.title||x.legislation||'Edit Requirement';
  document.getElementById('lr-form3ref-badge').textContent=displayRecordRef(x,'req_ref','LEG-DRAFT');
  document.getElementById('lr-del-btn').style.display=isMgr()?'inline-flex':'none';
  var gf=function(fid,val){var el=document.getElementById(fid);if(el)el.value=val||'';};
  gf('lr-leg-main',x.legislation);gf('lr-leg-title',x.title);gf('lr-section',x.section);
  gf('lr-subsection',x.subsection);gf('lr-requirement',x.requirement);gf('lr-controls',x.controls);
  gf('lr-evidence-req',x.evidence_required);gf('lr-evidence-loc',x.evidence_location);
  gf('lr-further-controls',x.further_controls||x.gap_description);gf('lr-penalty',x.penalty_risk);
  gf('lr-notes',x.notes);gf('lr-responsibility',x.responsibility||x.responsible_person);
  gf('lr-jurisdiction',x.jurisdiction||'Mauritius');gf('lr-authority',x.authority);
  gf('lr-assessed-by',x.assessed_by);
  gf('lr-target-date',x.target_date);gf('lr-effective-date',x.effective_date);
  gf('lr-review-date',x.review_date);gf('lr-last-assessed',x.last_assessed_date);
  document.getElementById('lr-leg-type').value=x.legislation_type||'statutory';
  document.getElementById('lr-category').value=x.category||'health_safety';
  document.getElementById('lr-obligation').value=x.obligation_type||'mandatory';
  document.getElementById('lr-frequency').value=x.frequency||'ongoing';
  document.getElementById('lr-applicable').value=x.applicable!==false?'true':'false';
  var st=x.status||'non_compliant';
  document.getElementById('lr-status').value=st;
  document.querySelectorAll('[name="lr-status-r"]').forEach(r=>{r.checked=r.value===st;});
  document.getElementById('lr-gap').checked=!!(x.gap||x.gap_identified);
  var sc=x.compliance_score!=null?x.compliance_score:(LEG_STATUS_CFG[st]?.score||0);
  document.getElementById('lr-compliance-score').value=sc!=null?sc:0;
  document.getElementById('lr-score-display').textContent=(sc!=null?sc:0)+'%';
  var aiPanel=document.getElementById('legal-ai-assess-panel');if(aiPanel)aiPanel.style.display='none';
}
function legalOpenReq(id){
  var x=lrAllData.find(r=>r.id===id);if(!x)return;
  lrEditId=id;
  document.getElementById('lr-form3title').textContent=x.title||x.legislation||'Legal Requirement';
  document.getElementById('lr-form3ref-badge').textContent=displayRecordRef(x,'req_ref','LEG-DRAFT');
  document.getElementById('lr-del-btn').style.display=isMgr()?'inline-flex':'none';
  var review=document.getElementById('lr-review-card');if(review)review.innerHTML=legalReqReviewHtml(x);
  legalReqEditMode(false);
  document.getElementById('legal-view-register').style.display='none';
  document.getElementById('legal-req-form').style.display='block';
}
function legalEditReq(){
  var x=lrAllData.find(r=>r.id===lrEditId);if(!x)return;
  legalLoadReqIntoForm(x);
  legalReqEditMode(true);
}

function legalScoreUpdate(val){
  var el=document.getElementById('lr-score-display');if(el)el.textContent=val+'%';
  // Auto-set status
  var v=parseInt(val);var autoSt=v>=90?'compliant':v>=50?'partial':'non_compliant';
  document.getElementById('lr-status').value=autoSt;
  document.querySelectorAll('[name="lr-status-r"]').forEach(r=>{r.checked=r.value===autoSt;});
}

function legalSetStatus(status){
  var hidden=document.getElementById('lr-status');
  if(hidden)hidden.value=status;
  document.querySelectorAll('[name="lr-status-r"]').forEach(function(r){r.checked=r.value===status;});
  var scoreMap={compliant:100,partial:50,non_compliant:0,not_applicable:0};
  var score=scoreMap[status]??0;
  var slider=document.getElementById('lr-compliance-score');
  var display=document.getElementById('lr-score-display');
  if(slider)slider.value=score;
  if(display)display.textContent=score+'%';
}

async function legalSaveReq(){
  if(!workflowCanMutate('legal','legal compliance'))return;
  if(!isMgr()){toast('Only managers/admins can change the legal register.',false);return;}
  var leg=document.getElementById('lr-leg-main')?.value?.trim();if(!leg){toast('Please enter legislation name',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var score=parseInt(g('lr-compliance-score'))||0;
  var st=g('lr-status')||'non_compliant';
  var body={company_id:ccid(),legislation:leg,title:g('lr-leg-title'),section:g('lr-section'),subsection:g('lr-subsection'),requirement:g('lr-requirement'),legislation_type:g('lr-leg-type')||'statutory',category:g('lr-category')||'health_safety',jurisdiction:g('lr-jurisdiction')||'Mauritius',authority:g('lr-authority'),obligation_type:g('lr-obligation')||'mandatory',frequency:g('lr-frequency')||'ongoing',applicable:g('lr-applicable')!=='false',status:st,compliance_score:score,controls:g('lr-controls'),evidence_required:g('lr-evidence-req'),evidence_location:g('lr-evidence-loc'),gap:document.getElementById('lr-gap')?.checked||false,gap_identified:document.getElementById('lr-gap')?.checked||false,further_controls:g('lr-further-controls'),penalty_risk:g('lr-penalty'),notes:g('lr-notes'),responsibility:g('lr-responsibility'),responsible_person:g('lr-responsibility'),target_date:g('lr-target-date')||null,effective_date:g('lr-effective-date')||null,review_date:g('lr-review-date')||null,last_assessed_date:g('lr-last-assessed')||null,assessed_by:g('lr-assessed-by'),updated_at:new Date().toISOString()};
  try{
    if(lrEditId){await api('/legal_requirements?id=eq.'+lrEditId,{m:'PATCH',p:'return=minimal',b:body});toast('Requirement updated!');}
    else{body.created_by=prof?.id;var res=await api('/legal_requirements',{m:'POST',p:'return=representation',b:body});if(res?.[0]?.id){var typeCode={statutory:'REQ',regulatory:'REG',iso_standard:'ISO',client_standard:'CLI',industry_code:'IND',other:'LEG'}[body.legislation_type]||'REQ';var ref=await nextCompanyRef('legal_requirements','req_ref',typeCode+'-');await api('/legal_requirements?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{req_ref:ref}});toast('Requirement saved! Ref: '+ref);if(body.gap){try{await api('/compliance_gaps',{m:'POST',p:'return=minimal',b:{company_id:ccid(),legislation:leg,section:body.section,gap_description:body.further_controls||'Gap identified - controls inadequate',risk_level:'high',status:'open',created_by:prof?.id}});}catch(ex){}}};}
    legalReqBack();
  }catch(e){toast(actionErrorMessage('Save legal requirement','Legal Compliance',e.message),false);}
}
async function legalDeleteReq(){
  if(!workflowCanMutate('legal','legal compliance'))return;
  if(!isMgr()){toast('Only managers/admins can delete legal requirements.',false);return;}
  if(!lrEditId)return;
  var ok=await appConfirmAction({title:'Delete legal section',message:'Delete this legal requirement from the register?',detail:'This removes the selected section from the current legal register. Use this for duplicate, test or wrongly imported sections.',confirmText:'Delete section',cancelText:'Back',variant:'danger'});
  if(!ok)return;
  try{await legalDeletePath('/legal_requirements?id=eq.'+lrEditId);toast('Legal section deleted');legalReqBack();}catch(e){toast(actionErrorMessage('Delete legal section','Legal Compliance',e.message),false);}
}
async function legalDeleteReqFromList(id){
  if(!workflowCanMutate('legal','legal compliance'))return;
  if(!isMgr()){toast('Only managers/admins can delete legal requirements.',false);return;}
  var ok=await appConfirmAction({title:'Archive legal section',message:'Archive this legal requirement from the active register?',detail:'Archived sections are hidden from normal use but retained for traceability.',confirmText:'Archive section',cancelText:'Back',variant:'danger'});
  if(!ok)return;
  var row=(lrAllData||[]).find(function(r){return r.id===id;})||{};
  mtgApiWithSchemaFallback('/legal_requirements?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:legalArchiveBody(row)},['updated_at']).then(function(){lrAllData=lrAllData.map(function(r){return r.id===id?Object.assign({},r,legalArchiveBody(r)):r;});legalFilterRegister();legalRefreshMetrics();toast('Legal section archived');}).catch(function(e){toast(actionErrorMessage('Archive legal section','Legal Compliance',e.message),false);});
}

function legalToggleVisibleSelection(checked){
  document.querySelectorAll('.lr-row-select').forEach(function(cb){cb.checked=checked;});
  var all=document.getElementById('lr-select-all-visible');
  if(all)all.checked=checked;
}

async function legalDeleteIds(ids,label){
  if(!workflowCanMutate('legal','legal compliance'))return;
  if(!ids.length)return;
  var rows=(lrAllData||[]).filter(function(x){return ids.includes(x.id);});
  for(var i=0;i<rows.length;i++){
    await mtgApiWithSchemaFallback('/legal_requirements?id=eq.'+rows[i].id,{m:'PATCH',p:'return=minimal',b:legalArchiveBody(rows[i])},['updated_at']);
  }
  lrAllData=lrAllData.map(function(x){return ids.includes(x.id)?Object.assign({},x,legalArchiveBody(x)):x;});
  legalFilterRegister();
  legalRefreshMetrics();
  toast('Archived '+ids.length+' '+(label||'requirement')+(ids.length>1?'s':'')+' from the active register');
}

async function legalDeletePath(path){
  await api(path,{m:'DELETE'});
}

async function legalDeleteSelectedReqs(){
  if(!isMgr()){toast('Only managers/admins can delete legal requirements',false);return;}
  var ids=Array.from(document.querySelectorAll('.lr-row-select:checked')).map(function(cb){return cb.dataset.id;}).filter(Boolean);
  if(!ids.length){toast('Select at least one section to archive',false);return;}
  var ok=await appConfirmAction({title:'Archive selected legal sections',message:'Archive '+ids.length+' selected legal section'+(ids.length>1?'s':'')+'?',detail:'Archived sections are hidden from the active legal register but kept for traceability. Use the Include archived filter to view them.',confirmText:'Archive selected',cancelText:'Keep sections',variant:'danger'});
  if(!ok)return;
  try{await legalDeleteIds(ids,'section');}
  catch(e){toast(actionErrorMessage('Archive selected legal sections','Legal Compliance',e.message),false);}
}

async function legalDeleteCurrentLegislation(){
  if(!isMgr()){toast('Only managers/admins can delete legislation',false);return;}
  var leg=document.getElementById('lr-filter-leg')?.value||'';
  if(!leg){
    var selectedIds=Array.from(document.querySelectorAll('.lr-row-select:checked')).map(function(cb){return cb.dataset.id;}).filter(Boolean);
    var selectedLegs=[...new Set(lrAllData.filter(function(x){return selectedIds.includes(x.id);}).map(function(x){return x.legislation;}).filter(Boolean))];
    if(selectedLegs.length===1)leg=selectedLegs[0];
  }
  if(!leg){toast('Choose one legislation in the filter first, or select rows from one legislation only',false);return;}
  var ids=lrAllData.filter(function(x){return x.legislation===leg&&!legalReqArchived(x);}).map(function(x){return x.id;}).filter(Boolean);
  if(!ids.length){toast('No records found for this legislation',false);return;}
  var ok=await appConfirm({
    title:'Archive full legislation',
    message:'Archive all '+ids.length+' active sections for "'+leg+'"?',
    detail:'Archived sections are hidden from the active register but retained for audit history.',
    confirmText:'Archive legislation',
    cancelText:'Keep legislation',
    danger:true
  });
  if(!ok)return;
  try{
    await legalDeleteIds(ids,'section');
    var sel=document.getElementById('lr-filter-leg');
    if(sel){
      Array.from(sel.options).forEach(function(o){if(o.value===leg)o.remove();});
      sel.value='';
    }
  }catch(e){toast(actionErrorMessage('Archive legislation','Legal Compliance',e.message),false);}
}

function legalFilteredRequirements(){
  var q=(document.getElementById('lr-search')?.value||'').toLowerCase();
  var fs=document.getElementById('lr-filter-status')?.value||'';
  var fl=document.getElementById('lr-filter-leg')?.value||'';
  var fc=document.getElementById('lr-filter-cat')?.value||'';
  return (lrAllData||[]).filter(function(x){
    var mQ=!q||(x.legislation||'').toLowerCase().includes(q)||(x.title||'').toLowerCase().includes(q)||(x.requirement||'').toLowerCase().includes(q)||(x.req_ref||'').toLowerCase().includes(q)||(x.section||'').toLowerCase().includes(q);
    return mQ&&(!fs||x.status===fs)&&(!fl||x.legislation===fl)&&(!fc||(x.category||'')===fc);
  }).sort(function(a,b){return (a.legislation||'').localeCompare(b.legislation||'')||legalRefSortValue(a)-legalRefSortValue(b);});
}
function legalGapLabel(x){return (x&&(x.gap===true||x.gap==='true'||x.gap_identified===true||x.gap_identified==='true'))?'Yes':'No';}
function legalIsStandardRequirement(x){
  var t=String(x?.legislation_type||'').toLowerCase();
  var leg=String(x?.legislation||'').toLowerCase();
  return ['iso_standard','client_standard','industry_code'].includes(t)||leg.includes('iso ')||leg.includes('standard')||t.includes('standard');
}
function legalAssessmentScopeOptionsHtml(selected){
  var items=[...new Set((lrAllData||[]).map(function(x){return x.legislation;}).filter(Boolean))].sort();
  return '<option value="">Select legislation / standard...</option>'+items.map(function(name){
    return '<option value="'+escH(name)+'" '+(name===selected?'selected':'')+'>'+escH(name)+'</option>';
  }).join('');
}
function legalPopulateAssessmentScopeOptions(){
  var sel=document.getElementById('lca-scope-item');if(!sel)return;
  var current=sel.value||'';
  sel.innerHTML=legalAssessmentScopeOptionsHtml(current);
  if(current&&Array.from(sel.options).some(function(o){return o.value===current;}))sel.value=current;
  legalAssessmentScopeChanged();
}
function legalAssessmentScopeChanged(){
  var mode=document.getElementById('lca-scope-mode')?.value||'all';
  var item=document.getElementById('lca-scope-item');
  if(item)item.disabled=mode!=='one';
  legalRenderAssessmentMatrix();
}
function legalAssessmentRows(){
  var mode=document.getElementById('lca-scope-mode')?.value||'all';
  var item=document.getElementById('lca-scope-item')?.value||'';
  var rows=(lrAllData||[]).slice();
  if(mode==='legislation')rows=rows.filter(function(x){return !legalIsStandardRequirement(x);});
  else if(mode==='standards')rows=rows.filter(function(x){return legalIsStandardRequirement(x);});
  else if(mode==='one'&&item)rows=rows.filter(function(x){return x.legislation===item;});
  return rows.sort(function(a,b){return (a.legislation||'').localeCompare(b.legislation||'')||legalRefSortValue(a)-legalRefSortValue(b);});
}
function legalAssessmentScopeLabel(){
  var mode=document.getElementById('lca-scope-mode')?.value||'all';
  var item=document.getElementById('lca-scope-item')?.value||'';
  if(mode==='legislation')return 'All legislation / acts';
  if(mode==='standards')return 'All standards';
  if(mode==='one')return item||'Selected legislation / standard';
  return 'All legal register';
}
function legalPrintRegisterEvidence(){
  var rows=legalFilteredRequirements();
  if(!rows.length){toast('No legal requirements to print',false);return;}
  var short=function(v,n){v=String(v||'').replace(/\s+/g,' ').trim();return v.length>n?v.slice(0,n-1)+'...':v;};
  var full=function(v,fallback){return escH(String(v||fallback||'-').trim());};
  var company=co?.name||prof?.company_name||'Company';
  var comp=rows.filter(function(x){return x.status==='compliant';}).length;
  var part=rows.filter(function(x){return x.status==='partial';}).length;
  var nonC=rows.filter(function(x){return x.status==='non_compliant';}).length;
  var gaps=rows.filter(function(x){return legalGapLabel(x)==='Yes';}).length;
  var totalApplicable=rows.filter(function(x){return x.status!=='not_applicable'&&x.applicable!==false;}).length||1;
  var score=Math.round((comp*100+part*50)/totalApplicable);
  var currentLeg='';
  var html='<style>@page{size:A4 landscape;margin:8mm}.report-page{width:297mm;max-width:none!important;padding:7mm}.legal-print-title{font-size:16pt;font-weight:900;color:#111827;margin:0}.legal-print-sub{font-size:8.5pt;color:#64748b;margin-top:2px}.legal-print-meta{font-size:8.5pt;color:#475569;text-align:right}.legal-summary{display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin:10px 0 10px}.legal-chip{border:1px solid #d7dee8;border-radius:6px;padding:6px 8px;background:#f8fafc}.legal-chip b{display:block;font-size:15pt;line-height:1;color:#173F63}.legal-chip span{font-size:7.5pt;color:#64748b;text-transform:uppercase;font-weight:700}.legal-print-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:7.2pt;line-height:1.26}.legal-print-table th{background:#173F63;color:#fff;padding:5px 6px;border:1px solid #173F63;text-align:left;text-transform:uppercase;font-size:7pt;letter-spacing:.02em}.legal-print-table td{padding:5px 6px;border:1px solid #d7dee8;vertical-align:top;overflow:visible;overflow-wrap:anywhere;word-break:normal;white-space:normal}.legal-print-table tr{height:auto!important}.legal-print-table tr:nth-child(even){background:#fbfdff}.leg-group td{background:#eaf3ff!important;color:#173F63;font-weight:900;font-size:8.5pt;padding:5px 7px}.muted{color:#64748b}.small{font-size:7pt}.req-title{font-weight:900;color:#111827}.req-excerpt{color:#334155;margin-top:2px;white-space:pre-wrap;overflow:visible}.badge{display:inline-block;border-radius:999px;padding:2px 7px;font-weight:900;font-size:7pt;white-space:nowrap}.gap-yes{background:#fee2e2;color:#991b1b}.gap-no{background:#dcfce7;color:#166534}.status-compliant{background:#dcfce7;color:#166534}.status-partial{background:#fef3c7;color:#92400e}.status-non_compliant{background:#fee2e2;color:#991b1b}.status-not_applicable{background:#e5e7eb;color:#475569}tr{break-inside:auto;page-break-inside:auto}</style>'
    +'<div class="report-page"><div class="rpt-header"><div><div class="legal-print-title">Legal Compliance Register</div><div class="legal-print-sub">'+escH(company)+' - operational evidence view</div></div><div class="legal-print-meta"><b>Generated:</b> '+new Date().toLocaleDateString('en-GB')+'<br><b>Scope:</b> '+rows.length+' visible requirements<br><b>Score:</b> '+score+'%</div></div>'
    +'<div class="legal-summary"><div class="legal-chip"><b>'+rows.length+'</b><span>Requirements</span></div><div class="legal-chip"><b>'+comp+'</b><span>Compliant</span></div><div class="legal-chip"><b>'+part+'</b><span>Partial</span></div><div class="legal-chip"><b>'+nonC+'</b><span>Non-compliant</span></div><div class="legal-chip"><b>'+gaps+'</b><span>Open gaps</span></div></div>'
    +'<table class="legal-print-table"><thead><tr><th style="width:7%">Ref</th><th style="width:23%">Section / requirement</th><th style="width:22%">Current controls</th><th style="width:9%">Status</th><th style="width:7%">Gap</th><th style="width:20%">Recommendations / further controls</th><th style="width:7%">Action by</th><th style="width:5%">Target</th></tr></thead><tbody>';
  rows.forEach(function(x){
    if((x.legislation||'')!==currentLeg){
      currentLeg=x.legislation||'Unspecified legislation';
      html+='<tr class="leg-group"><td colspan="8">'+escH(currentLeg)+' <span class="muted small">- '+escH((x.legislation_type||'').replace(/_/g,' ')||'legal requirement')+'</span></td></tr>';
    }
    var st=x.status||'partial';
    var stCfg=LEG_STATUS_CFG[st]||LEG_STATUS_CFG.partial;
    html+='<tr><td><b>'+escH(displayRecordRef(x,'req_ref','LEG-DRAFT'))+'</b></td>'
      +'<td><div class="req-title">'+escH(x.title||x.section||'-')+'</div><div class="muted small">'+escH(x.section||'')+'</div><div class="req-excerpt">'+full(x.requirement,'-')+'</div></td>'
      +'<td>'+full(x.controls,'No current controls recorded')+'</td>'
      +'<td><span class="badge status-'+escH(st)+'">'+escH(stCfg.label||st)+'</span><div class="muted small">'+(x.compliance_score!=null?escH(x.compliance_score)+'%':'')+'</div></td>'
      +'<td><span class="badge '+(legalGapLabel(x)==='Yes'?'gap-yes':'gap-no')+'">'+legalGapLabel(x)+'</span></td>'
      +'<td>'+full(x.further_controls||x.recommendations||x.gap_description,'-')+'</td>'
      +'<td>'+escH(x.responsibility||x.responsible_person||'-')+'</td>'
      +'<td>'+escH(x.target_date?new Date(x.target_date).toLocaleDateString('en-GB'):'-')+'</td></tr>';
  });
  aurisPrint(html+'</tbody></table></div>','Legal Compliance Register');
}
function legalRequirementOptionsHtml(selectedId){
  var h='<option value="">Select section to amend...</option>';
  (lrAllData||[]).slice().sort(function(a,b){return (a.legislation||'').localeCompare(b.legislation||'')||legalRefSortValue(a)-legalRefSortValue(b);}).forEach(function(x){
    var section=[x.section,x.subsection].filter(Boolean).join('.');
    var label=displayRecordRef(x,'req_ref','LEG')+' - '+(section?('s.'+section+' - '):'')+(x.title||x.legislation||'');
    h+='<option value="'+escH(x.id||'')+'" '+(x.id===selectedId?'selected':'')+'>'+escH(label.substring(0,140))+'</option>';
  });
  return h;
}
function legalChangeSectionSummaryHtml(x){
  if(!x)return '<div style="font-size:12px;color:var(--text2)">No legal register section selected yet.</div>';
  var ref=displayRecordRef(x,'req_ref','LEG');
  var section=[x.section,x.subsection].filter(Boolean).join('.');
  var req=String(x.requirement||'').trim();
  return '<div style="display:grid;grid-template-columns:120px 1fr;gap:10px;align-items:start">'
    +'<div><div class="form3label">Register ref</div><b style="font-family:monospace;color:#185FA5">'+escH(ref)+'</b></div>'
    +'<div><div class="form3label">Section concerned</div><b>'+escH((section?('s.'+section+' - '):'')+(x.title||x.legislation||'-'))+'</b>'
    +(req?'<div style="font-size:12px;color:#374151;line-height:1.45;margin-top:6px;white-space:pre-wrap">'+escH(req.substring(0,420))+(req.length>420?'...':'')+'</div>':'')+'</div></div>';
}
function legalChangeSetSectionSummary(x){
  var box=document.getElementById('lc-section-summary');
  if(box)box.innerHTML=legalChangeSectionSummaryHtml(x);
}
function legalChangeSectionChanged(){
  var id=document.getElementById('lc-section-id')?.value||'';
  var x=(lrAllData||[]).find(function(r){return r.id===id;});
  if(!x){legalChangeSetSectionSummary(null);return;}
  var leg=document.getElementById('lc-legislation');if(leg)leg.value=x.legislation||'';
  var cat=document.getElementById('lc-category');if(cat)cat.value=x.category||'health_safety';
  var ref=document.getElementById('lc-section-ref');if(ref)ref.value=[x.section,x.subsection].filter(Boolean).join('.')||displayRecordRef(x,'req_ref','');
  var prev=document.getElementById('lc-current-wording');if(prev)prev.value=x.requirement||'';
  legalChangeSetSectionSummary(x);
}
function legalRenderAssessmentMatrix(){
  var box=document.getElementById('lca-matrix');if(!box)return;
  var currentMode=document.getElementById('lca-scope-mode')?.value||'all';
  var currentItem=document.getElementById('lca-scope-item')?.value||'';
  var rows=legalAssessmentRows();
  if(!rows.length){box.innerHTML='<div style="padding:18px;color:var(--text2);text-align:center">No legal register sections available. Add or import legislation first.</div>';return;}
  var h='<div class="card" style="margin-bottom:10px;background:#F8FBFF;border-color:#BFDBFE"><div style="display:grid;grid-template-columns:220px minmax(260px,1fr) auto;gap:10px;align-items:end">'
    +'<div><label class="form3label">Assessment scope</label><select id="lca-scope-mode" data-auris-generated-onchange="g0271"><option value="all">All legal register</option><option value="legislation">All legislation / acts</option><option value="standards">All standards</option><option value="one">One legislation or standard</option></select></div>'
    +'<div><label class="form3label">Select legislation / standard</label><select id="lca-scope-item" data-auris-generated-onchange="g0272">'+legalAssessmentScopeOptionsHtml(currentItem)+'</select></div>'
    +'<button type="button" class="btn btn-sm" data-auris-generated-onclick="g0273">Mark all no gap</button>'
    +'</div><div style="font-size:12px;color:var(--text2);margin-top:8px">Saving updates the legal register, sends gaps to Gap Analysis, and creates related actions in the Master Action Plan.</div></div>'
    +'<div class="table-scroll"><table class="data-table lca-worksheet" style="min-width:1120px"><thead><tr><th style="width:95px">Ref</th><th style="width:230px">Legislation / section</th><th style="width:340px">Requirement</th><th style="width:290px">Assessment result</th><th style="width:310px">Gap action</th></tr></thead><tbody>';
  rows.forEach(function(x){
    var st=x.status||'compliant';
    if(x.applicable===false)st='not_applicable';
    if((x.gap||x.gap_identified)&&st==='compliant')st=(x.controls?'partial':'non_compliant');
    var hasGap=st==='partial'||st==='non_compliant'||!!(x.gap||x.gap_identified);
    h+='<tr class="lca-row" data-id="'+escH(x.id||'')+'"><td style="font-family:monospace;font-weight:800;color:#185FA5;vertical-align:top">'+escH(displayRecordRef(x,'req_ref','LEG-DRAFT'))+'</td>'
      +'<td style="vertical-align:top"><div style="font-size:13px;font-weight:900;color:#0F766E;line-height:1.25">'+escH(x.title||x.section||'Untitled section')+'</div><div style="font-size:11px;color:#475569;margin-top:5px;font-weight:700">'+escH(x.legislation||'-')+'</div><div style="font-size:10px;color:var(--text2);margin-top:5px">'+(legalIsStandardRequirement(x)?'Standard':'Legislation / Act')+(x.section?' - '+escH(x.section):'')+'</div></td>'
      +'<td style="font-size:12px;vertical-align:top;line-height:1.35;white-space:pre-wrap">'+escH(x.requirement||'-')+'</td>'
      +'<td style="vertical-align:top"><label class="form3label">Current controls</label><textarea class="lca-controls" data-auris-generated-oninput="g0274" style="min-height:58px;font-size:12px">'+escH(x.controls||'')+'</textarea><div style="display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;margin-top:8px"><select class="lca-status" data-auris-generated-onchange="g0275"><option value="compliant" '+(st==='compliant'?'selected':'')+'>Compliant</option><option value="partial" '+(st==='partial'?'selected':'')+'>Partial compliance</option><option value="non_compliant" '+(st==='non_compliant'?'selected':'')+'>Non-compliant</option><option value="not_applicable" '+(st==='not_applicable'?'selected':'')+'>N/A</option></select><label style="display:flex;align-items:center;gap:6px;font-size:12px;font-weight:700;color:#991B1B"><input type="checkbox" class="lca-gap" data-auris-generated-onchange="g0276" '+(hasGap?'checked':'')+' style="width:18px!important;height:18px!important"/> Gap</label></div></td>'
      +'<td style="vertical-align:top"><label class="form3label">Further controls / recommendations</label><textarea class="lca-reco" data-auris-generated-oninput="g0274" style="min-height:58px;font-size:12px">'+escH(x.further_controls||x.recommendations||x.gap_description||'')+'</textarea><div style="display:grid;grid-template-columns:1fr 140px;gap:8px;margin-top:8px"><input class="lca-resp" data-auris-generated-oninput="g0274" value="'+escH(x.responsibility||x.responsible_person||'')+'" placeholder="Action by"/><input type="date" class="lca-target" data-auris-generated-onchange="g0277" value="'+escH(x.target_date||'')+'"/></div></td></tr>';
  });
  box.innerHTML=h+'</tbody></table></div>';
  var modeEl=document.getElementById('lca-scope-mode');if(modeEl)modeEl.value=currentMode;
  var item=document.getElementById('lca-scope-item');if(item){item.value=currentItem;item.disabled=currentMode!=='one';}
  document.querySelectorAll('#lca-matrix .lca-row').forEach(lcaUpdateGapFields);
  lcaUpdateLiveScore();
}
function lcaUpdateGapFields(tr,clearValues){
  if(!tr)return;
  var gap=!!tr.querySelector('.lca-gap')?.checked;
  ['.lca-reco','.lca-resp','.lca-target'].forEach(function(sel){
    var el=tr.querySelector(sel);if(!el)return;
    if(clearValues&&!gap)el.value='';
    el.disabled=!gap;
    el.style.background=gap?'':'#f3f4f6';
    el.style.opacity=gap?'1':'.65';
    el.title=gap?'':'Select Gap before adding recommendations, action owner or target date';
  });
}
function lcaGapChanged(cb){
  var tr=cb.closest('.lca-row'),sel=tr?.querySelector('.lca-status');
  if(sel&&cb.checked&&sel.value==='compliant')sel.value='partial';
  if(sel&&!cb.checked&&(sel.value==='partial'||sel.value==='non_compliant'))sel.value='compliant';
  lcaUpdateGapFields(tr,true);
  lcaUpdateLiveScore();
}
function lcaStatusChanged(sel){
  var tr=sel.closest('.lca-row'),cb=tr?.querySelector('.lca-gap');
  if(cb)cb.checked=sel.value==='partial'||sel.value==='non_compliant';
  lcaUpdateGapFields(tr,sel.value==='compliant'||sel.value==='not_applicable');
  lcaUpdateLiveScore();
}
function lcaUpdateLiveScore(){
  var counts={compliant:0,partial:0,non:0,na:0};
  document.querySelectorAll('#lca-matrix .lca-row').forEach(function(tr){
    var st=tr.querySelector('.lca-status')?.value||'compliant';
    if(st==='compliant')counts.compliant++;
    else if(st==='partial')counts.partial++;
    else if(st==='non_compliant')counts.non++;
    else counts.na++;
  });
  var set=function(id,v){var el=document.getElementById(id);if(el)el.value=v;};
  set('lcaf-compliant',counts.compliant);set('lcaf-partial',counts.partial);set('lcaf-noncompliant',counts.non);set('lcaf-na',counts.na);
  lcaCalcScore();
}
function lcaMarkAllNoGap(){
  document.querySelectorAll('#lca-matrix .lca-status').forEach(function(sel){sel.value='compliant';});
  document.querySelectorAll('#lca-matrix .lca-gap').forEach(function(cb){cb.checked=false;});
  document.querySelectorAll('#lca-matrix .lca-row').forEach(function(tr){lcaUpdateGapFields(tr,true);});
  lcaUpdateLiveScore();
}
async function lcaSyncAssessmentRows(assessmentRef){
  var rows=Array.from(document.querySelectorAll('#lca-matrix .lca-row'));
  var date=document.getElementById('lcaf-date')?.value||new Date().toISOString().slice(0,10);
  var assessor=document.getElementById('lcaf-assessor')?.value||prof?.full_name||prof?.email||null;
  var counts={compliant:0,partial:0,non:0,na:0,gaps:0};
  for(var i=0;i<rows.length;i++){
    var tr=rows[i], id=tr.dataset.id;if(!id)continue;
    var req=(lrAllData||[]).find(function(x){return x.id===id;})||{};
    var controls=tr.querySelector('.lca-controls')?.value||null;
    var rowStatus=tr.querySelector('.lca-status')?.value||'compliant';
    var gap=rowStatus==='partial'||rowStatus==='non_compliant'||!!tr.querySelector('.lca-gap')?.checked;
    var reco=tr.querySelector('.lca-reco')?.value||null;
    var resp=tr.querySelector('.lca-resp')?.value||null;
    var target=tr.querySelector('.lca-target')?.value||null;
    var status=rowStatus;
    if(!gap){reco=null;resp=null;target=null;}
    var score=status==='compliant'?100:(status==='partial'?50:0);
    if(status==='compliant')counts.compliant++;else if(status==='partial')counts.partial++;else if(status==='not_applicable')counts.na++;else counts.non++;
    if(gap)counts.gaps++;
    await mtgApiWithSchemaFallback('/legal_requirements?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{controls:controls,gap:gap,gap_identified:gap,further_controls:reco,recommendations:reco,responsibility:resp,responsible_person:resp,target_date:target||null,last_assessed_date:date,assessed_by:assessor,status:status,compliance_score:score,updated_at:new Date().toISOString()}},['recommendations','responsibility','responsible_person','target_date','last_assessed_date','assessed_by','gap_identified','updated_at']);
    if(gap){
      var gapDesc=reco||('Compliance gap for '+(req.title||req.section||req.legislation||'legal requirement'));
      try{
        var gapRows=await api('/compliance_gaps?select=id&legislation=eq.'+encodeURIComponent(req.legislation||'')+'&section=eq.'+encodeURIComponent(req.section||'')+'&status=neq.closed'+cf()+'&limit=1');
        var gapBody={company_id:ccid(),legislation:req.legislation||'',section:req.section||'',gap_description:gapDesc,gap_type:'missing_control',risk_level:'high',action_required:reco||gapDesc,responsible_person:resp,target_date:target||null,status:'open',updated_at:new Date().toISOString(),created_by:prof?.id};
        if(gapRows?.[0]?.id)await mtgApiWithSchemaFallback('/compliance_gaps?id=eq.'+gapRows[0].id,{m:'PATCH',p:'return=minimal',b:gapBody},['gap_type','updated_at','created_by']);
        else{var createdGap=await mtgApiWithSchemaFallback('/compliance_gaps',{m:'POST',p:'return=representation',b:gapBody},['gap_type','updated_at','created_by']);if(createdGap?.[0]?.id){var gref=await nextCompanyRef('compliance_gaps','gap_ref','GAP-'+new Date().getFullYear()+'-');await api('/compliance_gaps?id=eq.'+createdGap[0].id,{m:'PATCH',p:'return=minimal',b:{gap_ref:gref}});}}
      }catch(ex){console.warn('Compliance gap sync failed',ex);}
      try{
        var src=(assessmentRef||'Compliance assessment')+' - '+displayRecordRef(req,'req_ref','LEG');
        var existing=await api('/action_tracker?select=id&source_module=eq.legal&source_ref=eq.'+encodeURIComponent(src)+'&status=neq.closed'+cf()+'&limit=1');
        var actBody={company_id:ccid(),title:'Close legal compliance gap: '+String(req.title||req.section||req.legislation||'').substring(0,80),description:gapDesc,action_type:'corrective',priority:'high',status:'open',source_type:'legal',source_module:'legal',source_id:id,source_ref:src,assigned_to_name:resp||null,responsible:resp||null,target_date:target||null,created_by:prof?.id,updated_at:new Date().toISOString()};
        if(existing?.[0]?.id)await mtgApiWithSchemaFallback('/action_tracker?id=eq.'+existing[0].id,{m:'PATCH',p:'return=minimal',b:actBody},['action_type','responsible','updated_at','created_by']);
        else await mtgApiWithSchemaFallback('/action_tracker',{m:'POST',p:'return=minimal',b:actBody},['action_type','responsible','updated_at','created_by']);
      }catch(ex2){console.warn('Legal MAP sync failed',ex2);}
    }
  }
  return counts;
}

// -- REGULATORY CHANGES --------------------------------------------------------
function legalChangeFilterText(x){
  return [
    x.date_received,x.source,x.jurisdiction,x.legislation,x.section,x.section_ref,
    legalChangeSectionLabel(x),x.category,x.changes_identified,x.changes,
    x.action_required,x.action,x.responsible_person,x.comments
  ].filter(Boolean).join(' ').toLowerCase();
}
function legalClearChangeFilters(){
  ['lc-chg-search','lc-chg-category','lc-chg-applicable','lc-chg-implemented'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.value='';
  });
  legalRenderChanges();
}
function legalRenderChanges(){
  var el=document.getElementById('lc-table');if(!el)return;
  var all=lcAllData||[];
  if(!all.length){
    el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600;margin-bottom:8px">No regulatory changes recorded</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0278"><i class="ti ti-plus"></i>Add change</button>':'')+'</div>';
    return;
  }
  var q=String(document.getElementById('lc-chg-search')?.value||'').trim().toLowerCase();
  var cat=document.getElementById('lc-chg-category')?.value||'';
  var app=document.getElementById('lc-chg-applicable')?.value||'';
  var imp=document.getElementById('lc-chg-implemented')?.value||'';
  var d=all.filter(function(x){
    var implemented=x.implemented===true||x.implemented==='true';
    var applicable=x.applicable!==false&&x.applicable!=='false';
    if(q&&!legalChangeFilterText(x).includes(q))return false;
    if(cat&&x.category!==cat)return false;
    if(app&&String(applicable)!==app)return false;
    if(imp&&String(implemented)!==imp)return false;
    return true;
  });
  var count=document.getElementById('lc-chg-count');if(count)count.textContent=d.length+' of '+all.length+' changes';
  if(!d.length){
    el.innerHTML='<div style="text-align:center;padding:36px;color:var(--text2)"><div style="font-size:34px;margin-bottom:10px"><i class="ti ti-filter-off"></i></div><div style="font-weight:700;margin-bottom:6px">No regulatory changes match the filters</div><button class="btn" data-auris-generated-onclick="g0279"><i class="ti ti-refresh"></i>Clear filters</button></div>';
    return;
  }
  var h='<div class="table-scroll"><table class="data-table" style="min-width:1220px"><thead><tr><th>Date</th><th>Legislation</th><th>Section / ref</th><th>Change</th><th>Category</th><th>Action required</th><th>Applicable?</th><th>Implemented?</th><th style="width:50px"></th></tr></thead><tbody>';
  d.forEach(function(x,i){
    var bg=i%2===0?'#fff':'#f9fafb';
    var archived=ohIsArchivedText(x.comments);
    var impVal=x.implemented===true||x.implemented==='true';
    var appVal=x.applicable!==false&&x.applicable!=='false';
    h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+(archived?';opacity:.6':'')+'">'
      +'<td style="padding:8px 14px;font-size:11px;white-space:nowrap">'+(x.date_received?new Date(x.date_received).toLocaleDateString('en-GB'):'-')+'</td>'
      +'<td style="padding:8px;font-weight:600;max-width:180px">'+escH(x.legislation||'-')+'<div style="font-size:10px;color:var(--text2)">'+escH(x.source||'')+'</div>'+(archived?'<div style="font-size:10px;color:#6B7280;font-weight:800">Archived</div>':'')+'</td>'
      +'<td style="padding:8px;font-size:11px;font-weight:800;color:#185FA5;max-width:150px">'+escH(legalChangeSectionLabel(x)||'-')+'</td>'
      +'<td style="padding:8px;max-width:250px;font-size:11px">'+escH((x.changes_identified||x.changes||'-').substring(0,100))+(((x.changes_identified||x.changes||'').length>100)?'-':'')+'</td>'
      +'<td style="padding:8px">'+(x.category?'<span style="background:'+(LEGAL_CAT_CFG[x.category]?.color||'#6B7280')+'15;color:'+(LEGAL_CAT_CFG[x.category]?.color||'#6B7280')+';padding:1px 7px;border-radius:99px;font-size:10px;font-weight:600">'+(LEGAL_CAT_CFG[x.category]?.emoji||'*')+' '+escH(LEGAL_CAT_CFG[x.category]?.label||x.category)+'</span>':'-')+'</td>'
      +'<td style="padding:8px;font-size:11px">'+escH((x.action_required||x.action||'-').substring(0,60))+'</td>'
      +'<td style="padding:8px;text-align:center">'+(appVal?'<span style="color:#1D9E75;font-weight:700">Yes</span>':'<span style="color:#6B7280">No</span>')+'</td>'
      +'<td style="padding:8px;text-align:center">'+(impVal?'<span style="background:#EAF3DE;color:#3B6D11;padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">Done</span>':'<span style="background:#FEF9EC;color:#854F0B;padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">Pending</span>')+'</td>'
      +'<td style="padding:8px"><div style="display:flex;gap:4px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0280" title="View change"><i class="ti ti-eye"></i></button>'+(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0281"><i class="ti ti-trash"></i></button>':'')+'</div></td></tr>';
  });
  h+='</tbody></table></div>';el.innerHTML=h;
}
async function legalLoadChanges(){
  var el=document.getElementById('lc-table');if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/legal_changes?select=*'+cf()+'&order=date_received.desc');
    lcAllData=d||[];
    legalRenderChanges();
  }catch(e){el.innerHTML=setupFriendlyMessage('Legal changes register',e.message);}
}

function legalChgBack(){document.getElementById('legal-chg-form').style.display='none';document.getElementById('legal-view-changes').style.display='block';document.querySelectorAll('[id^="legal-tab-"]').forEach(t=>t.classList.remove('active'));document.getElementById('legal-tab-changes')?.classList.add('active');legalLoadChanges();}
function legalNewChange(){
  fillPplDrops();lcEditId=null;
  legalChangeEditMode(true);
  document.getElementById('lc-form3title').textContent='New Regulatory Change';
  document.getElementById('lc-del-btn').style.display='none';
  var section=document.getElementById('lc-section-id');if(section)section.innerHTML=legalRequirementOptionsHtml('');
  ['lc-source','lc-legislation','lc-changes','lc-action','lc-comments','lc-responsible','lc-section-ref','lc-current-wording','lc-new-wording'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['lc-date','lc-effective-date'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  document.getElementById('lc-date').value=new Date().toISOString().slice(0,10);
  document.getElementById('lc-jurisdiction').value='Mauritius';
  document.getElementById('lc-category').value='health_safety';
  document.getElementById('lc-applicable').value='true';
  document.getElementById('lc-implemented').value='false';
  var ct=document.getElementById('lc-change-type');if(ct)ct.value='amendment';
  legalChangeSetSectionSummary(null);
  document.getElementById('legal-view-changes').style.display='none';document.getElementById('legal-chg-form').style.display='block';
}
function legalChangeTextFromComments(x,label){
  var txt=String(x?.comments||'');
  var re=new RegExp(label+' wording:\\n([\\s\\S]*?)(?:\\nNew wording:|\\nPrevious wording:|$)','i');
  var m=txt.match(re);
  return m&&m[1]?m[1].trim():'';
}
function legalChangeMetaFromComments(x){
  var txt=String(x?.comments||'');
  var m=txt.match(/AURIS360_CHANGE_META:({[\s\S]*?})\s*(?:\n|$)/);
  if(!m)return {};
  try{return JSON.parse(m[1]);}catch(_){return {};}
}
function legalChangeSectionLabel(x){
  var meta=legalChangeMetaFromComments(x);
  var reqId=x.requirement_id||x.legal_requirement_id||meta.requirement_id||'';
  var req=(lrAllData||[]).find(function(r){return String(r.id)===String(reqId);})||{};
  var sec=x.section||x.section_ref||meta.section_ref||[req.section,req.subsection].filter(Boolean).join('.');
  var title=req.title||x.section_title||'';
  return [sec,title].filter(Boolean).join(' - ')||displayRecordRef(req,'req_ref','');
}
function legalChangeData(id){
  var x=(lcAllData||[]).find(function(r){return String(r.id)===String(id);})||null;
  if(!x)return null;
  var meta=legalChangeMetaFromComments(x);
  if(!x.requirement_id&&meta.requirement_id)x.requirement_id=meta.requirement_id;
  if(!x.legal_requirement_id&&meta.requirement_id)x.legal_requirement_id=meta.requirement_id;
  if(!x.section&&meta.section_ref)x.section=meta.section_ref;
  if(!x.section_ref&&meta.section_ref)x.section_ref=meta.section_ref;
  if(!x.change_type&&meta.change_type)x.change_type=meta.change_type;
  if(!x.effective_date&&meta.effective_date)x.effective_date=meta.effective_date;
  if(!x.previous_wording)x.previous_wording=legalChangeTextFromComments(x,'Previous');
  if(!x.new_wording)x.new_wording=legalChangeTextFromComments(x,'New');
  return x;
}
function legalChangeUserComments(x){
  return String(x?.comments||'').replace(/AURIS360_CHANGE_META:{[\s\S]*?}\s*/,'').replace(/Amendment tracking:[\s\S]*/,'').trim();
}
function legalChangeEditMode(edit){
  var review=document.getElementById('lc-review-card'),form=document.getElementById('lc-edit-card'),save=document.getElementById('lc-save-btn'),editBtn=document.getElementById('lc-edit-btn'),del=document.getElementById('lc-del-btn'),print=document.getElementById('lc-print-btn');
  if(review)review.style.display=edit?'none':'block';
  if(form)form.style.display=edit?'block':'none';
  if(save)save.style.display=edit?'inline-flex':'none';
  if(editBtn)editBtn.style.display=(!edit&&isMgr())?'inline-flex':'none';
  if(del)del.style.display=(edit&&isMgr()&&lcEditId)?'inline-flex':'none';
  if(print)print.style.display=edit?'none':'inline-flex';
}
function legalChangeBadge(label,color,bg){
  return '<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:99px;font-size:11px;font-weight:900;background:'+bg+';color:'+color+'">'+label+'</span>';
}
function legalChangeReviewHtml(x){
  var imp=x.implemented===true||x.implemented==='true';
  var app=x.applicable!==false&&x.applicable!=='false';
  var archived=ohIsArchivedText(x.comments);
  var oldW=x.previous_wording||'No previous wording captured.';
  var newW=x.new_wording||x.changes_identified||x.changes||'No replacement wording captured.';
  var cat=x.category?'<span style="background:'+(LEGAL_CAT_CFG[x.category]?.color||'#6B7280')+'15;color:'+(LEGAL_CAT_CFG[x.category]?.color||'#6B7280')+';padding:4px 10px;border-radius:99px;font-size:11px;font-weight:900">'+(LEGAL_CAT_CFG[x.category]?.emoji||'*')+' '+escH(LEGAL_CAT_CFG[x.category]?.label||x.category)+'</span>':'-';
  return '<div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px">'
    +'<div><div style="font-size:12px;color:var(--text2);font-weight:700;text-transform:uppercase">Regulatory change brief</div><div style="font-size:20px;font-weight:900;color:#854F0B">'+escH(x.legislation||'Regulatory change')+'</div><div style="font-size:12px;color:var(--text2)">'+escH(legalChangeSectionLabel(x)||'No linked section')+'</div></div>'
    +'<div style="display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap">'+(archived?legalChangeBadge('Archived','#6B7280','#F3F4F6'):'')+legalChangeBadge(app?'Applicable':'Not applicable',app?'#047857':'#64748b',app?'#ECFDF5':'#F3F4F6')+legalChangeBadge(imp?'Implemented':'Pending action',imp?'#047857':'#B45309',imp?'#ECFDF5':'#FEF3C7')+'</div>'
    +'</div>'
    +'<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:14px">'
    +'<div class="card" style="padding:12px"><div class="form3label">Date received</div><b>'+escH(x.date_received?new Date(x.date_received).toLocaleDateString('en-GB'):'-')+'</b></div>'
    +'<div class="card" style="padding:12px"><div class="form3label">Effective date</div><b>'+escH(x.effective_date?new Date(x.effective_date).toLocaleDateString('en-GB'):'-')+'</b></div>'
    +'<div class="card" style="padding:12px"><div class="form3label">Source / publication</div><b>'+escH(x.source||'-')+'</b></div>'
    +'<div class="card" style="padding:12px"><div class="form3label">Change type</div><b>'+escH(String(x.change_type||'amendment').replace(/_/g,' '))+'</b></div>'
    +'<div class="card" style="padding:12px"><div class="form3label">Category</div>'+cat+'</div>'
    +'</div>'
    +'<div class="card" style="background:#F8FBFF;border-color:#BFDBFE;margin-bottom:14px"><div class="card-title" style="color:#185FA5">Affected legal register section</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:14px"><div><div class="form3label">Legislation</div><b>'+escH(x.legislation||'-')+'</b></div><div><div class="form3label">Section / ref</div><b style="color:#185FA5;font-size:16px">'+escH(legalChangeSectionLabel(x)||'-')+'</b></div></div></div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px"><div class="card" style="background:#FEF2F2;border-color:#FECACA"><div class="card-title" style="color:#991B1B">Previous wording</div><div style="white-space:pre-wrap;font-size:13px;line-height:1.5;color:#7F1D1D">'+escH(oldW)+'</div></div><div class="card" style="background:#ECFDF5;border-color:#A7F3D0"><div class="card-title" style="color:#047857">New wording / replacement</div><div style="white-space:pre-wrap;font-size:13px;line-height:1.5;color:#064E3B;font-weight:700">'+escH(newW)+'</div></div></div>'
    +'<div class="card" style="margin-bottom:14px"><div class="card-title">Implementation follow-up</div><div style="display:grid;grid-template-columns:2fr 2fr 1fr;gap:14px"><div><div class="form3label">Changes identified</div><div style="white-space:pre-wrap">'+escH(x.changes_identified||x.changes||'-')+'</div></div><div><div class="form3label">Action required</div><div style="white-space:pre-wrap">'+escH(x.action_required||x.action||'-')+'</div></div><div><div class="form3label">Responsible person</div><b>'+escH(x.responsible_person||'-')+'</b><div class="form3label" style="margin-top:10px">Status</div>'+(imp?legalChangeBadge('Done','#047857','#ECFDF5'):legalChangeBadge('Pending','#B45309','#FEF3C7'))+'</div></div></div>'
    +(legalChangeUserComments(x)?'<div class="card"><div class="card-title">Comments</div><div style="white-space:pre-wrap">'+escH(legalChangeUserComments(x))+'</div></div>':'');
}
function legalPrintChange(){
  var x=legalChangeData(lcEditId);if(!x)return;
  var html='<!doctype html><html><head><title>AURIS360 - Regulatory Change</title><style>@page{size:A4 portrait;margin:12mm}body{font-family:Arial,sans-serif;color:#111827}h1{color:#854F0B;margin:0}.meta{color:#475569;font-size:12px;margin-bottom:12px}.box{border:1px solid #cbd5e1;border-radius:8px;padding:10px;margin:10px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.label{font-size:11px;color:#64748b;text-transform:uppercase;font-weight:700}.text{white-space:pre-wrap;font-size:12px;line-height:1.45}.old{background:#fff1f2}.new{background:#ecfdf5}.badge{display:inline-block;padding:3px 8px;border-radius:99px;background:#f3f4f6;font-weight:700;font-size:11px}table{width:100%;border-collapse:collapse}td{border:1px solid #cbd5e1;padding:7px;font-size:12px;vertical-align:top}</style></head><body><h1>Regulatory Change Brief</h1><div class="meta">Generated '+new Date().toLocaleDateString('en-GB')+' - '+escH(companyName())+'</div>'
    +'<table><tr><td><div class="label">Legislation</div><b>'+escH(x.legislation||'-')+'</b></td><td><div class="label">Section / ref</div><b>'+escH(legalChangeSectionLabel(x)||'-')+'</b></td></tr><tr><td><div class="label">Date received</div>'+escH(x.date_received?new Date(x.date_received).toLocaleDateString('en-GB'):'-')+'</td><td><div class="label">Effective date</div>'+escH(x.effective_date?new Date(x.effective_date).toLocaleDateString('en-GB'):'-')+'</td></tr><tr><td><div class="label">Source</div>'+escH(x.source||'-')+'</td><td><div class="label">Status</div><span class="badge">'+(x.implemented===true||x.implemented==='true'?'Implemented':'Pending')+'</span></td></tr></table>'
    +'<div class="grid"><div class="box old"><div class="label">Previous wording</div><div class="text">'+escH(x.previous_wording||'No previous wording captured.')+'</div></div><div class="box new"><div class="label">New wording / replacement</div><div class="text">'+escH(x.new_wording||x.changes_identified||x.changes||'No replacement wording captured.')+'</div></div></div>'
    +'<div class="box"><div class="label">Change and action required</div><div class="text">'+escH(x.changes_identified||x.changes||'-')+'</div><hr><div class="text">'+escH(x.action_required||x.action||'-')+'</div></div>'
    +'<div class="box"><div class="label">Responsible person</div>'+escH(x.responsible_person||'-')+'</div></body></html>';
  printHtmlDoc(html);
}
function legalOpenChg(id){
  var x=legalChangeData(id);if(!x)return;lcEditId=id;
  document.getElementById('lc-form3title').textContent=x.legislation||'Regulatory Change';
  document.getElementById('lc-del-btn').style.display=isMgr()?'inline-flex':'none';
  var review=document.getElementById('lc-review-card');if(review)review.innerHTML=legalChangeReviewHtml(x);
  legalChangeEditMode(false);
  document.getElementById('legal-view-changes').style.display='none';document.getElementById('legal-chg-form').style.display='block';
}
function legalEditChg(){
  var x=legalChangeData(lcEditId);if(!x)return;
  document.getElementById('lc-form3title').textContent=x.legislation||'Edit Change';
  document.getElementById('lc-del-btn').style.display=isMgr()?'inline-flex':'none';
  var gf=function(fid,val){var el=document.getElementById(fid);if(el)el.value=val||'';};
  var section=document.getElementById('lc-section-id');if(section)section.innerHTML=legalRequirementOptionsHtml(x.requirement_id||x.legal_requirement_id||'');
  var req=(lrAllData||[]).find(function(r){return String(r.id)===String(x.requirement_id||x.legal_requirement_id||'');});
  gf('lc-date',x.date_received);gf('lc-source',x.source);gf('lc-jurisdiction',x.jurisdiction||'Mauritius');gf('lc-legislation',x.legislation);gf('lc-changes',x.changes_identified||x.changes);gf('lc-action',x.action_required||x.action);gf('lc-comments',legalChangeUserComments(x));gf('lc-responsible',x.responsible_person);gf('lc-effective-date',x.effective_date);
  gf('lc-section-ref',x.section||x.section_ref);gf('lc-current-wording',x.previous_wording);gf('lc-new-wording',x.new_wording);
  legalChangeSetSectionSummary(req||null);
  var ct=document.getElementById('lc-change-type');if(ct)ct.value=x.change_type||'amendment';
  document.getElementById('lc-category').value=x.category||'health_safety';
  document.getElementById('lc-applicable').value=x.applicable!==false&&x.applicable!=='false'?'true':'false';
  document.getElementById('lc-implemented').value=x.implemented===true||x.implemented==='true'?'true':'false';
  legalChangeEditMode(true);
  document.getElementById('legal-view-changes').style.display='none';document.getElementById('legal-chg-form').style.display='block';
}
async function legalSaveChg(){
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var reqId=g('lc-section-id');
  var req=(lrAllData||[]).find(function(x){return x.id===reqId;})||{};
  var previous=g('lc-current-wording')||req.requirement||null;
  var newer=g('lc-new-wording');
  var meta={requirement_id:reqId||null,section_ref:g('lc-section-ref')||req.section||null,change_type:g('lc-change-type')||'amendment',effective_date:g('lc-effective-date')||null};
  var changeNote='Amendment tracking: '+(reqId?('section '+(req.section||g('lc-section-ref')||displayRecordRef(req,'req_ref','LEG'))+' selected. '):'No linked section selected. ')+(newer?'New wording captured. ':'')
    +(previous?'\nPrevious wording:\n'+previous:'')+(newer?'\nNew wording:\n'+newer:'');
  var body={company_id:ccid(),date_received:g('lc-date')||null,source:g('lc-source'),jurisdiction:g('lc-jurisdiction')||'Mauritius',legislation:g('lc-legislation')||req.legislation,category:g('lc-category')||req.category||'health_safety',section:g('lc-section-ref')||req.section,requirement_id:reqId||null,legal_requirement_id:reqId||null,change_type:g('lc-change-type')||'amendment',previous_wording:previous,new_wording:newer,changes_identified:g('lc-changes'),changes:g('lc-changes'),action_required:g('lc-action'),action:g('lc-action'),responsible_person:g('lc-responsible'),effective_date:g('lc-effective-date')||null,applicable:g('lc-applicable')!=='false',implemented:g('lc-implemented')==='true',comments:[g('lc-comments'),'AURIS360_CHANGE_META:'+JSON.stringify(meta),changeNote].filter(Boolean).join('\n'),updated_at:new Date().toISOString()};
  try{
    if(reqId&&newer){
      await mtgApiWithSchemaFallback('/legal_requirements?id=eq.'+reqId,{m:'PATCH',p:'return=minimal',b:{requirement:newer,notes:[req.notes,'Amended '+(g('lc-effective-date')||g('lc-date')||new Date().toISOString().slice(0,10))+' via regulatory change '+(g('lc-source')||'')+'. Previous wording retained in Regulatory Changes.'].filter(Boolean).join('\n'),last_verified_at:new Date().toISOString(),updated_at:new Date().toISOString()}},['last_verified_at','updated_at']);
    }
    if(lcEditId){await mtgApiWithSchemaFallback('/legal_changes?id=eq.'+lcEditId,{m:'PATCH',p:'return=minimal',b:body},['section','requirement_id','legal_requirement_id','change_type','previous_wording','new_wording','updated_at']);toast('Updated!');}
    else{body.created_by=prof?.id;await mtgApiWithSchemaFallback('/legal_changes',{m:'POST',p:'return=minimal',b:body},['section','requirement_id','legal_requirement_id','change_type','previous_wording','new_wording','updated_at','created_by']);toast(reqId&&newer?'Change recorded and legal section updated!':'Change recorded!');}
    legalChgBack();legalLoadRegister();
  }catch(e){toast(actionErrorMessage('Save regulatory change','Legal Compliance',e.message),false);}
}
async function legalDeleteChg(){
  if(!lcEditId)return;
  try{
    var rows=await api('/legal_changes?id=eq.'+lcEditId+'&select=comments');
    var current=rows?.[0]||{};
    if(!ohIsArchivedText(current.comments)){
      if(!(await appConfirmAction({title:'Archive regulatory change',message:'Archive this regulatory change instead of deleting it?',detail:'Regulatory change history is legal evidence and should remain traceable for future reviews.',confirmText:'Archive change',cancelText:'Back',variant:'danger'})))return;
      await api('/legal_changes?id=eq.'+lcEditId,{m:'PATCH',p:'return=minimal',b:{comments:ohArchivedText(current.comments),updated_at:new Date().toISOString()}});
      toast('Regulatory change archived');
      legalChgBack();
      return;
    }
    if(!(await appConfirmDelete('archived regulatory change','This change is already archived. Permanent deletion should be used only for duplicate/test records.')))return;
    await api('/legal_changes?id=eq.'+lcEditId,{m:'DELETE'});toast('Deleted!');legalChgBack();
  }catch(e){toast(actionErrorMessage('Delete regulatory change','Legal Compliance',e.message),false);}
}
async function legalDeleteChgFromList(id){
  try{
    var current=(lcAllData||[]).find(function(x){return x.id===id;})||{};
    if(!ohIsArchivedText(current.comments)){
      if(!(await appConfirmAction({title:'Archive regulatory change',message:'Archive this regulatory change instead of deleting it?',detail:'Regulatory change history is legal evidence and should remain traceable for future reviews.',confirmText:'Archive change',cancelText:'Back',variant:'danger'})))return;
      var comments=ohArchivedText(current.comments);
      await api('/legal_changes?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{comments:comments,updated_at:new Date().toISOString()}});
      var idx=lcAllData.findIndex(function(x){return x.id===id;});
      if(idx>=0)lcAllData[idx]=Object.assign({},lcAllData[idx],{comments:comments});
      legalLoadChanges();toast('Regulatory change archived');
      return;
    }
    if(!(await appConfirmDelete('archived regulatory change','This change is already archived. Permanent deletion should be used only for duplicate/test records.')))return;
    await api('/legal_changes?id=eq.'+id,{m:'DELETE'});lcAllData=lcAllData.filter(x=>x.id!==id);legalLoadChanges();toast('Deleted!');
  }catch(e){toast(actionErrorMessage('Delete regulatory change','Legal Compliance',e.message),false);}
}

// -- COMPLIANCE ASSESSMENTS ----------------------------------------------------
async function lcaLoad(){
  var el=document.getElementById('lca-list');if(!el)return;el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/compliance_assessments?select=*'+cf()+'&order=assessment_date.desc');lcaAllData=d||[];
    var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
    setM('lr-m3assessments',(d||[]).length);
    if(!d||!d.length){el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-check"></i></div><div style="font-weight:600;margin-bottom:8px">No compliance assessments recorded</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0282"><i class="ti ti-plus"></i>New assessment</button>':'')+'</div>';return;}
    var stCfg={draft:['#f3f4f6','#6B7280'],completed:['#EFF6FF','#185FA5'],reviewed:['#FEF9EC','#854F0B'],approved:['#EAF3DE','#3B6D11']};
    var h='<div class="table-scroll"><table class="data-table" style="min-width:980px"><thead><tr><th>Assessment</th><th>Type</th><th>Date</th><th>Assessor</th><th style="text-align:center">Requirements</th><th style="text-align:center">Score</th><th>Status</th><th style="width:60px"></th></tr></thead><tbody>';
    d.forEach(function(x,i){
      var sc2=stCfg[x.status]||stCfg.draft;
      var score=x.overall_score;
      var scoreColor=score==null?'#6B7280':score>=80?'#1D9E75':score>=60?'#EF9F27':score>=40?'#C2410C':'#A32D2D';
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+(i%2?'#fafafa':'#fff')+';border-left:4px solid '+scoreColor+'">'
        +'<td style="padding:10px 12px"><div style="font-weight:800">'+escH(x.title||'Compliance Assessment')+'</div><div style="font-family:monospace;font-size:11px;font-weight:700;color:'+scoreColor+'">'+escH(x.assessment_ref||'--')+'</div></td>'
        +'<td style="padding:10px 12px;text-transform:capitalize">'+escH((x.assessment_type||'periodic').replace(/_/g,' '))+'</td>'
        +'<td style="padding:10px 12px">'+(x.assessment_date?new Date(x.assessment_date).toLocaleDateString('en-GB'):'--')+'</td>'
        +'<td style="padding:10px 12px">'+escH(x.assessor||'--')+'</td>'
        +'<td style="padding:10px 12px;text-align:center">'+(x.total_requirements||0)+' <span style="color:#1D9E75;font-weight:800">'+(x.compliant_count||0)+'?</span> <span style="color:#EF9F27;font-weight:800">'+(x.partial_count||0)+'?</span> <span style="color:#E24B4A;font-weight:800">'+(x.non_compliant_count||0)+'?</span></td>'
        +'<td style="padding:10px 12px;text-align:center;font-size:18px;font-weight:900;color:'+scoreColor+'">'+(score!=null?score+'%':'--')+'</td>'
        +'<td style="padding:10px 12px"><span style="background:'+sc2[0]+';color:'+sc2[1]+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:800;text-transform:capitalize">'+escH(x.status||'draft')+'</span></td>'
        +'<td style="padding:10px 12px"><button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0283"><i class="ti ti-edit"></i></button></td>'
        +'</tr>';
    });
    h+='</tbody></table></div>';el.innerHTML=h;
  }catch(e){el.innerHTML=setupFriendlyMessage('Compliance assessments',e.message);}
}

function lcaCalcScore(){
  var c=parseInt(document.getElementById('lcaf-compliant')?.value)||0;
  var p=parseInt(document.getElementById('lcaf-partial')?.value)||0;
  var n=parseInt(document.getElementById('lcaf-noncompliant')?.value)||0;
  var na=parseInt(document.getElementById('lcaf-na')?.value)||0;
  var total=c+p+n;
  var score=total>0?Math.round((c*100+p*50)/total):0;
  var el=document.getElementById('lca-score-number');
  if(el){
    var color=score>=80?'#1D9E75':score>=60?'#EF9F27':score>=40?'#C2410C':'#A32D2D';
    el.textContent=score+'%';el.style.color=color;
  }
  var prevEl=document.getElementById('lca-score-preview');
  if(prevEl)prevEl.style.background=score>=80?'#f0fdf4':score>=60?'#FFFBEB':score>=40?'#FFF7ED':'#FEF2F2';
}

function lcaBack(){document.getElementById('lca-form').style.display='none';document.getElementById('legal-view-assessments').style.display='block';document.querySelectorAll('[id^="legal-tab-"]').forEach(t=>t.classList.remove('active'));document.getElementById('legal-tab-assessments')?.classList.add('active');lcaLoad();}
function lcaNew(){
  fillPplDrops();lcaEditId=null;
  document.getElementById('lca-form3title').textContent='New Compliance Assessment';
  document.getElementById('lca-form3ref').textContent='CA-AUTO';
  document.getElementById('lca-del-btn').style.display='none';
  ['lcaf-title','lcaf-assessor','lcaf-scope','lcaf-methodology','lcaf-findings','lcaf-recommendations','lcaf-approved-by','lcaf-audit-ref'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['lcaf-date','lcaf-next-date','lcaf-approved-date'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  document.getElementById('lcaf-title').value='Legal compliance assessment - '+new Date().toLocaleDateString('en-GB');
  document.getElementById('lcaf-date').value=new Date().toISOString().slice(0,10);
  document.getElementById('lcaf-type').value='periodic';
  document.getElementById('lcaf-status').value='draft';
  ['lcaf-compliant','lcaf-partial','lcaf-noncompliant','lcaf-na'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='0';});
  document.getElementById('lca-score-number').textContent='-';
  document.getElementById('legal-view-assessments').style.display='none';document.getElementById('lca-form').style.display='block';
  legalPopulateAssessmentScopeOptions();
  legalRenderAssessmentMatrix();
  lcaUpdateLiveScore();
}
