function calBack(){document.getElementById('cal-form').style.display='none';document.getElementById('legal-view-calendar').style.display='block';document.querySelectorAll('[id^="legal-tab-"]').forEach(t=>t.classList.remove('active'));document.getElementById('legal-tab-calendar')?.classList.add('active');calLoad(calCurrentFilter,document.getElementById('cal-btn-'+calCurrentFilter));}
