// -- Patch mtgSwitchTab to handle new tabs -------------------------------------
// Override the existing function
function mtgSwitchTab(tab, btn){
  document.querySelectorAll('[id^="mtg-tab-"]').forEach(t=>{t.classList.remove('active');});
  if(btn)btn.classList.add('active');
  // Hide all views
  ['schedule','minutes','tbt','alerts','bulletins'].forEach(function(t){
    var el=document.getElementById('mtg-view-'+t);if(el)el.style.display='none';
  });
  // Hide all forms
  ['tbt-form','alert-form','bulletin-form'].forEach(function(id){
    var el=document.getElementById(id);if(el)el.style.display='none';
  });
  // Show selected
  var viewEl=document.getElementById('mtg-view-'+tab);
  if(viewEl)viewEl.style.display='block';
  // Load data
  if(tab==='schedule'){
    var c=document.getElementById('mtg-roadmap-container');
    if(c)c.innerHTML='<div class="loading-msg">Loading roadmap...</div>';
    mtgLoadSeries();
    setTimeout(function(){
      var c2=document.getElementById('mtg-roadmap-container');
      if(c2&&/Loading roadmap/i.test(c2.textContent||''))mtgLoadSeries();
    },300);
  }
  else if(tab==='minutes'){mtgLoadMinutes();}
  else if(tab==='tbt'){tbtLoad();}
  else if(tab==='alerts'){alertLoad();}
  else if(tab==='bulletins'){bulletinLoad();}
}

