async function tbtLoad(){
  var el=document.getElementById('tbt-list');if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  var ft=document.getElementById('tbt-filter-cat')?.value||'';
  try{
    var q='/toolbox_talks?select=*'+cf()+'&order=talk_date.desc';
    if(ft)q+='&topic_category=eq.'+ft;
    var d=await api(q);tbtAllData=d||[];
    // Metrics
    var now=new Date();var m=now.getMonth();var y=now.getFullYear();
    var setM=function(id,v){var e=document.getElementById(id);if(e)e.textContent=v;};
    setM('tbt-m3total',(d||[]).length);
    setM('tbt-m3month',(d||[]).filter(x=>x.talk_date&&new Date(x.talk_date).getMonth()===m&&new Date(x.talk_date).getFullYear()===y).length);
    setM('tbt-m3attendees',(d||[]).reduce((s,x)=>s+tbtStoredCount(x),0));
    setM('tbt-m3actions',(d||[]).reduce((s,x)=>s+((x.actions_raised||[]).length),0));
    if(!d||!d.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600;margin-bottom:8px">No toolbox talks recorded yet</div>'+(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0294"><i class="ti ti-plus"></i>Record first TBT</button>':'')+'</div>';
      return;
    }
    // Register table
    var h='<div class="table-scroll">'
      +'<table class="data-table" style="min-width:1080px">'
      +'<thead><tr>'
      +'<th>Ref</th>'
      +'<th>Toolbox talk</th>'
      +'<th>Date</th>'
      +'<th>Presenter</th>'
      +'<th>Location</th>'
      +'<th style="text-align:center">Attendees</th>'
      +'<th style="text-align:center">Actions</th>'
      +'<th style="text-align:center">Status</th>'
      +'<th style="width:70px"></th>'
      +'</tr></thead><tbody>';
    d.forEach(function(x){
      var cfg=TBT_TOPIC_CFG[x.topic_category||'other']||TBT_TOPIC_CFG.other;
      var actions=(x.actions_raised||[]).length;
      var attendees=tbtStoredCount(x);
      var dt=x.talk_date?new Date(x.talk_date).toLocaleDateString('en-GB'):'-';
      var stColor=x.status==='completed'?'#1D9E75':x.status==='planned'?'#185FA5':'#6B7280';
      h+='<tr style="border-bottom:1px solid var(--border);border-left:5px solid '+cfg.color+';cursor:pointer" data-id="'+x.id+'" data-auris-generated-onclick="g0295">'
        +'<td style="padding:10px;font-family:monospace;font-weight:800;color:'+cfg.color+'">'+escH(x.tbt_ref||'TBT')+'</td>'
        +'<td style="padding:10px;min-width:260px"><div style="font-weight:800">'+escH(x.title||'Untitled TBT')+'</div><div style="font-size:11px;color:'+cfg.color+';font-weight:700;margin-top:2px">'+cfg.emoji+' '+escH(cfg.label)+(x.duration_mins?' - '+escH(x.duration_mins)+' min':'')+'</div></td>'
        +'<td style="padding:10px;white-space:nowrap">'+dt+'</td>'
        +'<td style="padding:10px">'+escH(x.presenter||'-')+'</td>'
        +'<td style="padding:10px">'+escH(x.location||'-')+'</td>'
        +'<td style="padding:10px;text-align:center;font-weight:800;color:#185FA5">'+attendees+'</td>'
        +'<td style="padding:10px;text-align:center;font-weight:800;color:'+(actions>0?'#854F0B':'#6B7280')+'">'+actions+'</td>'
        +'<td style="padding:10px;text-align:center"><span style="font-size:10px;font-weight:800;color:'+stColor+';background:'+stColor+'15;padding:3px 8px;border-radius:99px;text-transform:capitalize">'+escH(x.status||'completed')+'</span></td>'
        +'<td style="padding:10px;text-align:center"><button class="btn btn-sm" data-auris-runtime-onclick="r0099" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id]))+'"><i class="ti ti-eye"></i></button></td>'
        +'</tr>';
    });
    h+='</tbody></table></div>';el.innerHTML=h;
  }catch(e){el.innerHTML=registerErrorHtml('register',e.message);}
}

function tbtShowForm(){
  document.getElementById('mtg-view-tbt').style.display='none';
  document.getElementById('tbt-form').style.display='block';
}
function tbtBack(){
  document.getElementById('tbt-form').style.display='none';
  document.getElementById('mtg-view-tbt').style.display='block';
  document.querySelectorAll('[id^="mtg-tab-"]').forEach(function(t){t.classList.remove('active');});
  document.getElementById('mtg-tab-tbt')?.classList.add('active');
  tbtLoad();
}

function tbtNew(){
  tbtEditId=null;
  document.getElementById('tbt-form3title').textContent='New Toolbox Talk';
  document.getElementById('tbt-form3ref').textContent='TBT-AUTO';
  document.getElementById('tbt-del-btn').style.display='none';
  ['tbtf-title','tbtf-location','tbtf-dept','tbtf-key-points',
   'tbtf-hazards','tbtf-incidents','tbtf-notes'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  tbtSetPresenterControl(prof?.full_name||prof?.email||'');
  document.getElementById('tbtf-date').value=new Date().toISOString().slice(0,10);
  document.getElementById('tbtf-duration').value='15';
  document.getElementById('tbtf-att-count').value='0';
  document.getElementById('tbtf-category').value='safety_general';
  document.getElementById('tbtf-status').value='completed';
  document.getElementById('tbtf-attendees-list').innerHTML='';
  document.getElementById('tbt-actions-list').innerHTML='';
  document.getElementById('tbt-preview-title').textContent='Toolbox Talk';
  document.getElementById('tbt-preview-count').textContent='0';
  tbtLoadWorkOptions('');
  tbtShowForm();
}

function tbtEdit(id){
  var x=tbtAllData.find(r=>r.id===id);if(!x)return;
  tbtEditId=id;
  document.getElementById('tbt-form3title').textContent=x.title||'Edit TBT';
  document.getElementById('tbt-form3ref').textContent=x.tbt_ref||'-';
  document.getElementById('tbt-del-btn').style.display=isMgr()?'inline-flex':'none';
  var gf=function(fid,val){var el=document.getElementById(fid);if(el)el.value=val||'';};
  gf('tbtf-title',x.title);gf('tbtf-location',x.location);gf('tbtf-dept',x.department);
  tbtSetPresenterControl(x.presenter||prof?.full_name||prof?.email||'');gf('tbtf-key-points',x.key_points);
  gf('tbtf-hazards',x.hazards_discussed);gf('tbtf-incidents',x.incidents_referenced);
  var link=tbtParseLinkedWork(x.notes||'');
  gf('tbtf-notes',tbtStripLinkedWork(x.notes||''));gf('tbtf-date',x.talk_date);
  document.getElementById('tbtf-duration').value=x.duration_mins||15;
  document.getElementById('tbtf-att-count').value=tbtStoredCount(x);
  document.getElementById('tbtf-category').value=x.topic_category||'safety_general';
  document.getElementById('tbtf-status').value=x.status||'completed';
  // Render attendees
  var attEl=document.getElementById('tbtf-attendees-list');
  if(attEl)attEl.innerHTML=(x.attendees||[]).map(function(a,i){return tbtAttendeeRow(a.name||'',a.dept||'',i,a.confirmed_at||'',a.confirmation_method||'');}).join('');
  // Render actions
  var actEl=document.getElementById('tbt-actions-list');
  if(actEl)actEl.innerHTML=(x.actions_raised||[]).map(function(a,i){return tbtActionRow(a.description||'',a.assigned_to||'',a.due_date||'',i);}).join('');
  document.getElementById('tbt-preview-title').textContent=x.title||'Toolbox Talk';
  document.getElementById('tbt-preview-count').textContent=tbtStoredCount(x);
  tbtLoadWorkOptions(link.id||x.work_order_id||'');
  tbtShowForm();
}

function tbtStoredCount(x){
  var attendees=Array.isArray(x?.attendees)?x.attendees:[];
  return attendees.filter(function(a){return a&&(a.name||a.full_name||a.person_name);}).length || parseInt(x?.attendance_count||0)||0;
}
function tbtPersonOptions(selected){
  var cur=selected||'';
  var html='<option value="">Select person...</option>';
  (people||[]).forEach(function(p){
    var nm=personFullName(p);
    html+='<option value="'+escH(nm)+'" '+(nm===cur?'selected':'')+'>'+escH([p.last_name,p.first_name].filter(Boolean).join(', ')||nm)+(p.job_title?' -- '+escH(p.job_title):'')+'</option>';
  });
  if(cur && html.indexOf('value="'+escH(cur)+'"')<0)html+='<option value="'+escH(cur)+'" selected>'+escH(cur)+' (saved text)</option>';
  return html;
}
function tbtSetPresenterControl(value){
  var wrap=document.getElementById('tbtf-presenter-wrap');
  if(!wrap)return;
  var v=value||prof?.full_name||prof?.email||'';
  if(isSA()){
    wrap.innerHTML='<select id="tbtf-presenter">'+tbtPersonOptions(v)+'</select><div style="font-size:10px;color:var(--text2);margin-top:3px">SEPHS admin may correct the presenter if entering historical records.</div>';
  }else{
    wrap.innerHTML='<input type="text" id="tbtf-presenter" value="'+escH(v)+'" readonly style="background:#f9fafb"/><div style="font-size:10px;color:var(--text2);margin-top:3px">Automatically set to the person completing the toolbox talk.</div>';
  }
}
function tbtFillAttendeeDept(sel){
  var row=sel.closest('.tbt-att-row');
  var p=personByDisplayName(sel.value);
  var dept=row?.querySelector('.tbt-att-dept');
  if(dept&&p)dept.value=p.department||'';
  tbtUpdateCount();
}
function tbtLinkedWorkMarker(work){
  if(!work||!work.id)return '';
  return '\n\n[AURIS360_LINKED_WORK:'+JSON.stringify({id:work.id,ref:work.ref||'',title:work.title||''})+']';
}
function tbtParseLinkedWork(notes){
  var m=String(notes||'').match(/\[AURIS360_LINKED_WORK:({[\s\S]*?})\]/);
  if(!m)return {};
  try{return JSON.parse(m[1])||{};}catch(_){return {};}
}
function tbtStripLinkedWork(notes){
  return String(notes||'').replace(/\n?\n?\[AURIS360_LINKED_WORK:{[\s\S]*?}\]/,'').trim();
}
async function tbtLoadWorkOptions(selected){
  var sel=document.getElementById('tbtf-work-link');if(!sel)return;
  sel.innerHTML='<option value="">No linked work / activity</option>';
  try{
    if(!wsAllData||!wsAllData.length){
      try{wsAllData=await api('/work_schedule?select=id,ref_number,title,location,status,planned_start'+cf()+'&order=planned_start.desc&limit=100')||[];}catch(_){}
    }
    sel.innerHTML='<option value="">No linked work / activity</option>'+(wsAllData||[]).map(function(w){
      var label=[w.ref_number,w.title,w.location].filter(Boolean).join(' - ');
      return '<option value="'+escH(w.id)+'" '+(w.id===selected?'selected':'')+'>'+escH(label||w.id)+'</option>';
    }).join('');
  }catch(e){console.warn('Could not load work options for TBT',e);}
}
function tbtSelectedWork(){
  var sel=document.getElementById('tbtf-work-link');
  if(!sel||!sel.value)return null;
  var w=(wsAllData||[]).find(function(x){return x.id===sel.value;})||{};
  return {id:sel.value,ref:w.ref_number||'',title:w.title||sel.options[sel.selectedIndex]?.text||''};
}
function tbtConfirmAttendee(btn){
  var row=btn.closest('.tbt-att-row');
  var name=row?.querySelector('.tbt-att-name')?.value||'';
  if(!name){toast('Select attendee first',false);return;}
  var pin=row.querySelector('.tbt-att-pin')?.value?.trim()||'';
  var p=personByDisplayName(name);
  var expected=[p?.employee_number,p?.id_number].filter(Boolean).map(function(x){return String(x).trim();});
  if(expected.length && expected.indexOf(pin)<0){toast('Employee code / ID does not match this person',false);return;}
  if(!expected.length && !pin){toast('Enter employee code / PIN to confirm attendance',false);return;}
  var ts=new Date().toISOString();
  row.dataset.confirmedAt=ts;
  row.dataset.confirmationMethod=expected.length?'employee_code':'manual_pin';
  var dt=row.querySelector('.tbt-att-confirm3dt');if(dt)dt.value=tbtDateTimeLocalValue(ts);
  var status=row.querySelector('.tbt-att-confirm3status');
  if(status)status.innerHTML='<span style="color:#1D9E75;font-weight:700"><i class="ti ti-circle-check"></i> Confirmed '+new Date(ts).toLocaleString()+'</span>';
  var pinEl=row.querySelector('.tbt-att-pin');if(pinEl)pinEl.value='';
}
function tbtDateTimeLocalValue(value){
  if(!value)return '';
  var d=new Date(value);if(isNaN(d))return '';
  var pad=function(n){return String(n).padStart(2,'0');};
  return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes());
}
function tbtSyncConfirmationTime(input){
  var row=input.closest('.tbt-att-row');if(!row)return;
  if(input.value){
    row.dataset.confirmedAt=new Date(input.value).toISOString();
    if(!row.dataset.confirmationMethod)row.dataset.confirmationMethod='admin_adjusted';
  }else{
    row.dataset.confirmedAt='';
  }
  var status=row.querySelector('.tbt-att-confirm3status');
  if(status)status.innerHTML=row.dataset.confirmedAt?'<span style="color:#1D9E75;font-weight:700"><i class="ti ti-circle-check"></i> Confirmed '+new Date(row.dataset.confirmedAt).toLocaleString()+'</span>':'<span style="color:var(--text2)">Not confirmed</span>';
}
function tbtAttendeeRow(name,dept,idx,confirmedAt,method){
  var confirmedText=confirmedAt?'<span style="color:#1D9E75;font-weight:700"><i class="ti ti-circle-check"></i> Confirmed '+new Date(confirmedAt).toLocaleString()+'</span>':'<span style="color:var(--text2)">Not confirmed</span>';
  var adminTime=isSA()?'<input type="datetime-local" class="tbt-att-confirm3dt" value="'+escH(tbtDateTimeLocalValue(confirmedAt))+'" data-auris-generated-onchange="g0296" title="SEPHS admin may correct confirmation date/time" style="width:175px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/>':'';
  return '<div class="tbt-att-row" style="display:flex;gap:6px;align-items:center;margin-bottom:8px;flex-wrap:wrap">'
    +'<select class="tbt-att-name" data-auris-generated-onchange="g0297" style="flex:1 1 240px;min-width:220px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px">'+tbtPersonOptions(name)+'</select>'
    +'<input type="text" placeholder="Dept" value="'+escH(dept)+'" class="tbt-att-dept" style="flex:0 1 150px;min-width:110px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/>'
    +'<input type="password" placeholder="Employee code / PIN" class="tbt-att-pin" style="flex:0 1 155px;min-width:135px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/>'
    +'<button class="btn btn-sm" style="color:#1D9E75;padding:4px 8px;white-space:nowrap" data-auris-generated-onclick="g0298"><i class="ti ti-signature"></i>Confirm</button>'
    +adminTime
    +'<span class="tbt-att-confirm3status" style="font-size:10px;min-width:160px;flex:1 1 170px">'+confirmedText+'</span>'
    +'<button class="btn btn-sm" style="color:var(--red);padding:4px 8px;margin-left:auto" data-auris-generated-onclick="g0299"><i class="ti ti-x"></i></button>'
    +'</div>'.replace('class="tbt-att-row"','class="tbt-att-row" data-confirmed-at="'+escH(confirmedAt||'')+'" data-confirmation-method="'+escH(method||'')+'"');
}
function tbtAttendeeConfirmedAt(row){
  var dt=row.querySelector('.tbt-att-confirm3dt');
  if(dt&&dt.value){
    row.dataset.confirmedAt=new Date(dt.value).toISOString();
    if(!row.dataset.confirmationMethod)row.dataset.confirmationMethod='admin_adjusted';
  }
  return row.dataset.confirmedAt||null;
}

function tbtActionRow(desc,assigned,due,idx){
  return '<div class="tbt-act-row" style="display:flex;gap:6px;align-items:center;margin-bottom:6px;flex-wrap:wrap">'
    +'<input type="text" placeholder="Action description..." value="'+escH(desc)+'" class="tbt-act-desc" style="flex:3;min-width:150px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/>'
    +'<input type="text" placeholder="Assigned to" value="'+escH(assigned)+'" class="tbt-act-assigned" style="flex:2;min-width:100px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/>'
    +'<input type="date" value="'+escH(due)+'" class="tbt-act-due" style="flex:1;min-width:120px;padding:5px 8px;border:1px solid var(--border);border-radius:6px;font-size:12px"/>'
    +'<button class="btn btn-sm" style="color:var(--red);padding:4px 8px" data-auris-generated-onclick="g0300"><i class="ti ti-x"></i></button>'
    +'</div>';
}

function tbtAIVal(id){
  var el=document.getElementById(id);
  return el ? String(el.value||'').trim() : '';
}

function tbtAIContext(){
  var cat=document.getElementById('tbtf-category');
  var work=tbtSelectedWork();
  var workFull=work&&work.id?(wsAllData||[]).find(function(w){return w.id===work.id;})||{}:{};
  return {
    title:tbtAIVal('tbtf-title'),
    category:tbtAIVal('tbtf-category'),
    category_label:cat&&cat.selectedIndex>=0?cat.options[cat.selectedIndex].text:'',
    date:tbtAIVal('tbtf-date'),
    location:tbtAIVal('tbtf-location'),
    department:tbtAIVal('tbtf-dept'),
    duration_minutes:tbtAIVal('tbtf-duration')||'15',
    presenter:tbtAIVal('tbtf-presenter'),
    linked_work:workFull.id?{
      ref:workFull.ref_number||work.ref||'',
      title:workFull.title||work.title||'',
      location:workFull.location||'',
      description:workFull.description||workFull.notes||'',
      supervisor:workFull.supervisor_name||'',
      team:workFull.team_members||'',
      status:workFull.status||''
    }:work,
    existing_key_points:tbtAIVal('tbtf-key-points'),
    existing_hazards:tbtAIVal('tbtf-hazards'),
    incidents_referenced:tbtAIVal('tbtf-incidents'),
    notes:tbtAIVal('tbtf-notes')
  };
}

function tbtAIList(items){
  if(!Array.isArray(items)||!items.length)return '<div style="font-size:12px;color:var(--text2)">No item generated.</div>';
  return '<ul style="margin:6px 0 0 18px;padding:0;line-height:1.5">'+items.map(function(x){return '<li>'+escH(typeof x==='string'?x:(x.description||JSON.stringify(x)))+'</li>';}).join('')+'</ul>';
}

function tbtAIRenderDraft(out){
  window.tbtAIDraft=out||{};
  var panel=document.getElementById('tbt-ai-draft-panel'); if(!panel)return;
  panel.innerHTML='<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap">'
    +'<div><div style="font-size:15px;font-weight:900;color:#185FA5"><i class="ti ti-robot"></i> AI toolbox talk draft</div>'
    +'<div style="font-size:12px;color:var(--text2);margin-top:3px">Review the draft and apply only what you want. Nothing is saved until you click Save.</div></div>'
    +'<button type="button" class="btn btn-sm" data-auris-generated-onclick="g0301"><i class="ti ti-x"></i>Hide</button></div>'
    +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;margin-top:14px">'
    +'<div style="background:#fff;border:1px solid var(--border);border-radius:8px;padding:12px"><div style="font-weight:800;color:#185FA5">Title</div><div style="font-size:13px;margin-top:6px">'+escH(out.title||'')+'</div></div>'
    +'<div style="background:#fff;border:1px solid var(--border);border-radius:8px;padding:12px"><div style="font-weight:800;color:#A32D2D">Hazards</div>'+tbtAIList(out.hazards)+'</div>'
    +'<div style="background:#fff;border:1px solid var(--border);border-radius:8px;padding:12px"><div style="font-weight:800;color:#065F46">Key points</div>'+tbtAIList(out.key_points)+'</div>'
    +'<div style="background:#fff;border:1px solid var(--border);border-radius:8px;padding:12px"><div style="font-weight:800;color:#854F0B">Questions to ask</div>'+tbtAIList(out.worker_questions)+'</div>'
    +'</div>'
    +'<div style="margin-top:12px;background:#fff;border:1px solid var(--border);border-radius:8px;padding:12px"><div style="font-weight:800;color:#374151">Closing message</div><div style="font-size:13px;line-height:1.5;margin-top:5px">'+escH(out.closing_message||'')+'</div></div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">'
    +'<button type="button" class="btn btn-sm btn-primary" data-auris-generated-onclick="g0302"><i class="ti ti-check"></i>Apply content</button>'
    +'<button type="button" class="btn btn-sm" data-auris-generated-onclick="g0303"><i class="ti ti-plus"></i>Add action items</button>'
    +'</div>';
  panel.style.display='block';
  panel.scrollIntoView({behavior:'smooth',block:'nearest'});
}

function tbtAIApplyContent(){
  var out=window.tbtAIDraft||{};
  if(out.title)document.getElementById('tbtf-title').value=out.title;
  if(Array.isArray(out.key_points))document.getElementById('tbtf-key-points').value=out.key_points.join('\n');
  if(Array.isArray(out.hazards))document.getElementById('tbtf-hazards').value=out.hazards.join('\n');
  var notes=[];
  if(Array.isArray(out.worker_questions)&&out.worker_questions.length)notes.push('Questions asked:\n'+out.worker_questions.join('\n'));
  if(out.closing_message)notes.push('Closing message:\n'+out.closing_message);
  if(notes.length)document.getElementById('tbtf-notes').value=notes.join('\n\n');
  tbtUpdateCount();
  toast('AI toolbox talk content applied. Review before saving.');
}

function tbtAIApplyActions(){
  var out=window.tbtAIDraft||{};
  var list=Array.isArray(out.action_items)?out.action_items:[];
  var el=document.getElementById('tbt-actions-list'); if(!el||!list.length)return;
  list.slice(0,6).forEach(function(a){
    var d='';
    if(a.due_in_days!=null){var dt=new Date();dt.setDate(dt.getDate()+(parseInt(a.due_in_days,10)||7));d=dt.toISOString().slice(0,10);}
    el.insertAdjacentHTML('beforeend',tbtActionRow(a.description||String(a||''),a.assigned_to_role||a.assigned_to||'',d,el.querySelectorAll('.tbt-act-row').length));
  });
  toast('AI action items added. Review ownership and due dates.');
}

async function tbtAIGenerateDraft(){
  if(!canUseAI || !canUseAI()){toast('AURIS AI is restricted to authorised HSE/admin roles.',false);return;}
  var ctx=tbtAIContext();
  if(!ctx.title && !ctx.category && !(ctx.linked_work&&ctx.linked_work.title)){toast('Enter a topic/title or select linked work first.',false);return;}
  var panel=document.getElementById('tbt-ai-draft-panel');
  if(panel){panel.style.display='block';panel.innerHTML='<div style="font-weight:800;color:#185FA5"><i class="ti ti-loader"></i> AURIS is drafting the toolbox talk...</div><div style="font-size:12px;color:var(--text2);margin-top:5px">Using the selected category, location and linked work context.</div>';}
  try{
    var txt=await callAI([{role:'user',content:'Create a practical toolbox talk draft and return ONLY valid JSON with this exact shape: {"title":"...","hazards":["..."],"key_points":["..."],"worker_questions":["..."],"closing_message":"...","action_items":[{"description":"...","assigned_to_role":"Supervisor / HSE Officer / Worker / Maintenance","due_in_days":7}]}.\n\nRules: keep it short enough for a 10-15 minute talk, practical for frontline workers, include stop-work authority, PPE/controls where relevant, and make it specific to the linked work/location if provided.\n\nToolbox talk context:\n'+JSON.stringify(ctx,null,2)}],
      'You are a senior HSE trainer. Write practical, engaging toolbox talk content for workers. Return only JSON.');
    var out=aiExtractJson(txt)||{};
    tbtAIRenderDraft(out);
    toast('AI toolbox talk draft ready.');
  }catch(e){if(panel)panel.innerHTML=aiFriendlyErrorHtml(e);toast(aiFriendlyError(e),false);}
}
function tbtAddAttendee(){
  // Work Schedule has its own embedded #tbt-attendees-list. The standalone TBT
  // page uses #tbtf-attendees-list. Find the visible one so the row appears
  // where the user is actually looking.
  var lists = document.querySelectorAll('#tbtf-attendees-list,#tbt-attendees-list');
  var el = null;
  for (var i = 0; i < lists.length; i++) {
    if (lists[i].offsetParent !== null) { el = lists[i]; break; }  // offsetParent === null means hidden
  }
  if (!el) el = lists[0];  // fall back to first if nothing is visible
  if (!el) return;
  var idx=el.querySelectorAll('.tbt-att-row').length;
  el.insertAdjacentHTML('beforeend',tbtAttendeeRow('','',idx));
  tbtUpdateCount();
}

function tbtAddAction(){
  // Same duplicate-ID issue as tbtAddAttendee - find the visible #tbt-actions-list.
  var lists = document.querySelectorAll('#tbt-actions-list');
  var el = null;
  for (var i = 0; i < lists.length; i++) {
    if (lists[i].offsetParent !== null) { el = lists[i]; break; }
  }
  if (!el) el = lists[0];
  if (!el) return;
  var idx=el.querySelectorAll('.tbt-act-row').length;
  el.insertAdjacentHTML('beforeend',tbtActionRow('','','',idx));
}

function tbtUpdateCount(){
  var names=document.querySelectorAll('.tbt-att-name');
  var filled=Array.from(names).filter(n=>n.offsetParent!==null&&n.value.trim()).length;
  var total=filled;
  var countEl=document.getElementById('tbtf-att-count');if(countEl)countEl.value=total;
  var prevEl=document.getElementById('tbt-preview-count');if(prevEl)prevEl.textContent=total;
  var titleEl=document.getElementById('tbt-preview-title');
  if(titleEl)titleEl.textContent=document.getElementById('tbtf-title')?.value||'Toolbox Talk';
}

async function tbtSave(){
  var title=document.getElementById('tbtf-title')?.value?.trim();if(!title){toast('Please enter TBT title',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  // Collect attendees
  var attendees=[];
  document.querySelectorAll('.tbt-att-row').forEach(function(row){
    if(row.offsetParent===null)return;
    var name=row.querySelector('.tbt-att-name')?.value?.trim();
    var dept=row.querySelector('.tbt-att-dept')?.value?.trim()||'';
    if(name){var attendeePerson=personFromValue(name);attendees.push({person_id:attendeePerson?.id||null,name,dept,organization_snapshot:attendeePerson?.company_name||attendeePerson?.department||dept||null,role_snapshot:attendeePerson?.job_title||null,confirmed_at:tbtAttendeeConfirmedAt(row),confirmation_method:row.dataset.confirmationMethod||null});}
  });
  // Collect actions
  var actions_raised=[];
  document.querySelectorAll('.tbt-act-row').forEach(function(row){
    if(row.offsetParent===null)return;
    var desc=row.querySelector('.tbt-act-desc')?.value?.trim();
    var assigned=row.querySelector('.tbt-act-assigned')?.value?.trim()||'';
    var due=row.querySelector('.tbt-act-due')?.value||'';
    if(desc)actions_raised.push({description:desc,assigned_to:assigned,due_date:due||null});
  });
  var linkedWork=tbtSelectedWork();
  var cleanNotes=tbtStripLinkedWork(g('tbtf-notes')||'');
  var body={company_id:ccid(),title,topic_category:g('tbtf-category')||'safety_general',talk_date:g('tbtf-date'),location:g('tbtf-location'),department:g('tbtf-dept'),presenter:g('tbtf-presenter'),presenter_person_id:personFromValue(g('tbtf-presenter'))?.id||null,attendee_person_ids:attendees.map(function(a){return a.person_id;}).filter(Boolean),duration_mins:parseInt(g('tbtf-duration'))||15,key_points:g('tbtf-key-points'),hazards_discussed:g('tbtf-hazards'),incidents_referenced:g('tbtf-incidents'),notes:cleanNotes+tbtLinkedWorkMarker(linkedWork),attendees,actions_raised,status:g('tbtf-status')||'completed',updated_at:new Date().toISOString()};
  try{
    if(tbtEditId){
      await apiWriteWithMissingColumnFallback('/toolbox_talks?id=eq.'+tbtEditId,{m:'PATCH',p:'return=minimal',b:body},'Toolbox Talk');
      toast('TBT updated!');
      // Auto-create MAP actions for any new action items
      for(var act of actions_raised){
        if(act.description&&!tbtEditId){
          try{await api('/action_tracker',{m:'POST',p:'return=minimal',b:{company_id:ccid(),title:act.description,description:act.description,source_type:'toolbox_talk',source_module:'meeting',priority:'medium',status:'open',assigned_to_name:act.assigned_to||null,target_date:act.due_date||null,created_by:prof?.id}});}catch(ex){}
        }
      }
    }else{
      body.created_by=prof?.id;
      var res=await apiWriteWithMissingColumnFallback('/toolbox_talks',{m:'POST',p:'return=representation',b:body},'Toolbox Talk');
      if(res?.[0]?.id){
        var yr=new Date().getFullYear();
        var seq=1;
        try{
          var prefix='TBT-'+yr+'-';
          var existing=await api('/toolbox_talks?select=tbt_ref&company_id=eq.'+ccid()+'&tbt_ref=like.'+encodeURIComponent(prefix+'*')+'&order=tbt_ref.desc&limit=1');
          var last=(existing&&existing[0]&&existing[0].tbt_ref)||'';
          var m=String(last).match(/-(\d+)$/);
          seq=m?parseInt(m[1],10)+1:1;
        }catch(refErr){
          seq=(tbtAllData||[]).filter(function(x){return String(x.tbt_ref||'').indexOf('TBT-'+yr+'-')===0;}).length+1;
        }
        var ref='TBT-'+yr+'-'+String(seq).padStart(3,'0');
        await api('/toolbox_talks?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{tbt_ref:ref}});
        toast('TBT saved! Ref: '+ref);
        // Auto-create MAP actions
        for(var act2 of actions_raised){
          if(act2.description){
            try{await api('/action_tracker',{m:'POST',p:'return=minimal',b:{company_id:ccid(),title:act2.description,description:act2.description,source_type:'toolbox_talk',source_module:'meeting',source_id:res[0].id,source_ref:ref,priority:'medium',status:'open',assigned_to_name:act2.assigned_to||null,target_date:act2.due_date||null,created_by:prof?.id}});}catch(ex){}
          }
        }
      }
    }
    tbtBack();
  }catch(e){toastActionError('Save toolbox talk','Toolbox Talk',e);}
}

function tbtCurrentFormData(){
  var g=function(id){var el=document.getElementById(id);return el?el.value||'':'';};
  var attendees=[];
  document.querySelectorAll('.tbt-att-row').forEach(function(row){
    if(row.offsetParent===null)return;
    var name=row.querySelector('.tbt-att-name')?.value?.trim();
    var dept=row.querySelector('.tbt-att-dept')?.value?.trim()||'';
    if(name)attendees.push({name:name,dept:dept,confirmed_at:tbtAttendeeConfirmedAt(row),confirmation_method:row.dataset.confirmationMethod||null});
  });
  var actions_raised=[];
  document.querySelectorAll('.tbt-act-row').forEach(function(row){
    if(row.offsetParent===null)return;
    var desc=row.querySelector('.tbt-act-desc')?.value?.trim();
    if(desc)actions_raised.push({description:desc,assigned_to:row.querySelector('.tbt-act-assigned')?.value?.trim()||'',due_date:row.querySelector('.tbt-act-due')?.value||''});
  });
  var linkedWork=tbtSelectedWork();
  return {id:tbtEditId,title:g('tbtf-title'),tbt_ref:document.getElementById('tbt-form3ref')?.textContent||'TBT-AUTO',topic_category:g('tbtf-category'),talk_date:g('tbtf-date'),location:g('tbtf-location'),department:g('tbtf-dept'),presenter:g('tbtf-presenter'),duration_mins:g('tbtf-duration'),key_points:g('tbtf-key-points'),hazards_discussed:g('tbtf-hazards'),incidents_referenced:g('tbtf-incidents'),notes:g('tbtf-notes'),status:g('tbtf-status'),attendees:attendees,actions_raised:actions_raised,linked_work:linkedWork};
}

function printToolboxTalk(id){
  var formOpen=document.getElementById('tbt-form')?.style.display!=='none';
  var t=(formOpen&&(id===tbtEditId||!id))?tbtCurrentFormData():(tbtAllData||[]).find(function(x){return x.id===id;});
  if(!t){toast('Open or select a toolbox talk first',false);return;}
  var ref=displayRecordRef(t,'tbt_ref','TBT-DRAFT');
  var attendees=Array.isArray(t.attendees)?t.attendees:[];
  var actions=Array.isArray(t.actions_raised)?t.actions_raised:[];
  var linkedWork=t.linked_work||tbtParseLinkedWork(t.notes||'');
  var fmtDate=function(v){return v?new Date(v).toLocaleDateString('en-GB'):'-';};
  var html='<style>@page{size:A4;margin:10mm}.rpt-section{break-inside:avoid}</style><div class="report-page">'
    +aurisHeader('Toolbox Talk / Safety Briefing',t.title||'Toolbox Talk',ref)
    +'<div class="rpt-section"><div class="rpt-section-title">Talk Details</div><div class="rpt-grid">'
    +fld('Topic Category',auditLabel(t.topic_category||'safety_general'))
    +fld('Date',fmtDate(t.talk_date))
    +fld('Location / Area',t.location)
    +fld('Department',t.department)
    +fld('Presenter',t.presenter)
    +fld('Duration',t.duration_mins?(t.duration_mins+' minutes'):'-')
    +fld('Status',auditLabel(t.status||'completed'))
    +fld('Attendees',String(attendees.length))
    +fld('Linked Work / Activity',linkedWork.id?[linkedWork.ref,linkedWork.title].filter(Boolean).join(' - '):'-',true)
    +'</div></div>'
    +'<div class="rpt-section"><div class="rpt-section-title blue">Content Covered</div><div class="rpt-grid">'
    +fld('Key Points Covered',t.key_points,true)
    +fld('Hazards Discussed',t.hazards_discussed,true)
    +fld('Incidents / Near Misses Referenced',t.incidents_referenced,true)
    +fld('Notes',tbtStripLinkedWork(t.notes||''),true)
    +'</div></div>'
    +'<div class="rpt-section"><div class="rpt-section-title secondary">Attendance Register</div>'
    +(attendees.length?'<table><thead><tr><th style="width:8%">No.</th><th>Name</th><th>Department</th><th>Signature</th></tr></thead><tbody>'
      +attendees.map(function(a,i){return '<tr><td style="text-align:center;font-weight:700">'+(i+1)+'</td><td>'+escH(a.name||'')+'</td><td>'+escH(a.dept||'')+'</td><td>'+escH(a.confirmed_at?new Date(a.confirmed_at).toLocaleString():'Not confirmed')+'<br><span style="font-size:8pt;color:#6b7280">'+escH(a.confirmation_method||'')+'</span></td></tr>';}).join('')
      +'</tbody></table>':'<p style="color:#6b7280;font-size:9pt;padding:8px">No attendees recorded.</p>')
    +'</div>'
    +'<div class="rpt-section"><div class="rpt-section-title amber">Actions Raised</div>'
    +(actions.length?'<table><thead><tr><th>Action</th><th>Assigned To</th><th>Due Date</th></tr></thead><tbody>'
      +actions.map(function(a){return '<tr><td>'+escH(a.description||'')+'</td><td>'+escH(a.assigned_to||'')+'</td><td>'+fmtDate(a.due_date)+'</td></tr>';}).join('')
      +'</tbody></table>':'<p style="color:#6b7280;font-size:9pt;padding:8px">No actions raised.</p>')
    +'</div>'
    +'<div class="rpt-signatures">'
    +'<div class="rpt-sig-box"><div class="sig-line">'+escH(t.presenter||'')+'</div><label>Presenter / Date</label></div>'
    +'<div class="rpt-sig-box"><div class="sig-line"></div><label>Supervisor / Date</label></div>'
    +'<div class="rpt-sig-box"><div class="sig-line"></div><label>HSE Review / Date</label></div>'
    +'</div>'
    +aurisFooter('Toolbox Talk')
    +'</div>';
  aurisPrint(html,'Toolbox Talk - '+ref);
}

async function tbtDelete(){
  if(!tbtEditId)return;
  try{
    var rows=await api('/toolbox_talks?id=eq.'+tbtEditId+'&select=status,notes');
    var current=rows?.[0]||{};
    if(String(current.status||'completed').toLowerCase()!=='archived'&&!ohIsArchivedText(current.notes)){
      if(!(await appConfirmAction({title:'Archive toolbox talk',message:'Archive this toolbox talk instead of deleting it?',detail:'Toolbox talks are training/communication evidence and should remain traceable.',confirmText:'Archive TBT',cancelText:'Back',variant:'danger'})))return;
      await api('/toolbox_talks?id=eq.'+tbtEditId,{m:'PATCH',p:'return=minimal',b:{status:'archived',notes:ohArchivedText(current.notes),updated_at:new Date().toISOString()}});
      toast('TBT archived');
      tbtBack();
      return;
    }
    if(!(await appConfirmDelete('archived toolbox talk','Permanent deletion should be used only for duplicate/test toolbox talks.')))return;
    await api('/toolbox_talks?id=eq.'+tbtEditId,{m:'DELETE'});
    toast('Deleted!');
    tbtBack();
  }catch(e){toastActionError('Delete toolbox talk','Toolbox Talk',e);}
}

