async function bulletinPreview(id){
  var x=(bulletinAllData||[]).find(function(r){return r.id===id;});
  if(!x){toast('Bulletin not found',false);return;}
  if(!x.file_url){toast('No attachment linked to this bulletin',false);return;}
  auditLogEvent('open','bulletins','Safety bulletin attachment opened',{bulletin_ref:x.bulletin_ref||null,title:x.title||null,file_name:x.file_name||null,file_url:x.file_url||null},{related_table:'safety_bulletins',related_id:x.id,company_id:x.company_id||ccid()});
  await bulletinRecordCheck(id).catch(function(e){console.warn('Bulletin check record failed',e);});
  dcOpenViewer({file_url:x.file_url,file_name:x.file_name||x.title||'Safety bulletin',file_mime:dcMimeFromName(x.file_name||x.file_url)});
}
async function bulletinPreviewCurrent(){
  var url=document.getElementById('bullf-file-url')?.value||'';
  var name=document.getElementById('bullf-file-name')?.value||document.getElementById('bullf-title')?.value||'Safety bulletin';
  if(!url){toast('No attachment URL to preview',false);return;}
  if(bulletinEditId){
    auditLogEvent('open','bulletins','Safety bulletin attachment opened',{bulletin_ref:document.getElementById('bull-form3ref')?.textContent||null,title:document.getElementById('bullf-title')?.value||null,file_name:name,file_url:url},{related_table:'safety_bulletins',related_id:bulletinEditId,company_id:ccid()});
    await bulletinRecordCheck(bulletinEditId).catch(function(e){console.warn('Bulletin check record failed',e);});
  }
  dcOpenViewer({file_url:url,file_name:name,file_mime:dcMimeFromName(name||url)});
}

function bulletinEdit(id){
  var x=bulletinAllData.find(r=>r.id===id);if(!x)return;
  bulletinEditId=id;
  document.getElementById('bull-form3title').textContent=x.title||'Edit Bulletin';
  document.getElementById('bull-form3ref').textContent=x.bulletin_ref||'-';
  document.getElementById('bull-del-btn').style.display=isMgr()?'inline-flex':'none';
  var gf=function(fid,val){var el=document.getElementById(fid);if(el)el.value=val||'';};
  gf('bullf-title',x.title);gf('bullf-summary',x.summary);gf('bullf-key-messages',x.key_messages);
  gf('bullf-content',x.content);gf('bullf-topics',(x.topics||[]).join(', '));
  gf('bullf-author',x.author);gf('bullf-approved-by',x.approved_by);
  gf('bullf-audience',x.target_audience);gf('bullf-file-url',x.file_url);
  gf('bullf-file-name',x.file_name);gf('bullf-pub-date',x.publication_date);
  document.getElementById('bullf-type').value=x.bulletin_type||'safety_bulletin';
  document.getElementById('bullf-dist-method').value=x.distribution_method||'email';
  document.getElementById('bullf-status').value=x.status||'published';
  document.getElementById('bullf-issue-no').value=x.issue_number||'';
  bulletinRenderChecks(x);
  bulletinShowForm();
}

async function bulletinSave(){
  var title=document.getElementById('bullf-title')?.value?.trim();if(!title){toast('Please enter bulletin title',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};
  var body={company_id:ccid(),title,bulletin_type:g('bullf-type')||'safety_bulletin',issue_number:parseInt(g('bullf-issue-no'))||null,publication_date:g('bullf-pub-date')||new Date().toISOString().slice(0,10),summary:g('bullf-summary'),key_messages:g('bullf-key-messages'),content:g('bullf-content'),topics:g('bullf-topics')?g('bullf-topics').split(',').map(t=>t.trim()).filter(Boolean):[],author:g('bullf-author'),approved_by:g('bullf-approved-by'),target_audience:g('bullf-audience'),distribution_method:g('bullf-dist-method')||'email',file_url:g('bullf-file-url'),file_name:g('bullf-file-name'),status:g('bullf-status')||'published',updated_at:new Date().toISOString()};
  try{
    if(bulletinEditId){
      await api('/safety_bulletins?id=eq.'+bulletinEditId,{m:'PATCH',p:'return=minimal',b:body});
      toast('Bulletin updated!');
    }else{
      body.created_by=prof?.id;
      var res=await api('/safety_bulletins',{m:'POST',p:'return=representation',b:body});
      if(res?.[0]?.id){var yr=new Date().getFullYear();var ref=await nextCompanyRef('safety_bulletins','bulletin_ref','BULL-'+yr+'-');await api('/safety_bulletins?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{bulletin_ref:ref}});toast('Bulletin published! Ref: '+ref);}
    }
    bulletinBack();
  }catch(e){toastActionError('Save safety bulletin','Training & Competency',e);}
}

async function bulletinDelete(){
  if(!bulletinEditId)return;
  try{
    var rows=await api('/safety_bulletins?id=eq.'+bulletinEditId+'&select=status,summary');
    var current=rows?.[0]||{};
    if(String(current.status||'published').toLowerCase()!=='archived'&&!ohIsArchivedText(current.summary)){
      if(!(await appConfirmAction({title:'Archive bulletin',message:'Archive this bulletin instead of deleting it?',detail:'Bulletins are communication evidence and should remain available historically.',confirmText:'Archive bulletin',cancelText:'Back',variant:'danger'})))return;
      await api('/safety_bulletins?id=eq.'+bulletinEditId,{m:'PATCH',p:'return=minimal',b:{status:'archived',summary:ohArchivedText(current.summary),updated_at:new Date().toISOString()}});
      toast('Bulletin archived');
      bulletinBack();
      return;
    }
    if(!(await appConfirmDelete('archived bulletin','Permanent deletion should be used only for duplicate/test bulletins.')))return;
    await api('/safety_bulletins?id=eq.'+bulletinEditId,{m:'DELETE'});
    toast('Deleted!');
    bulletinBack();
  }catch(e){toastActionError('Delete safety bulletin','Training & Competency',e);}
}

