function trainingRecordRef(x,fallback){
  return x?.certificate||x?.reference||x?.id?.slice(0,8)||fallback||'TRAIN';
}

function trainingAudit(action,summary,table,row,details){
  try{
    row=row||{};
    auditLogEvent(action,'training',summary,{
      person_name:row.person_name||row.employee_name||null,
      topic:row.training_topic||row.training_type||row.authorisation_type||row.competency_name||row.title||null,
      reference:trainingRecordRef(row),
      status:row.status||row.level||null,
      date:row.training_date||row.induction_date||row.planned_date||row.issue_date||row.assessed_date||null,
      expiry_date:row.expiry_date||row.refresher_due||null,
      details:details||{}
    },{related_table:table||'training',related_id:row.id||details?.id||null,company_id:row.company_id||ccid()});
  }catch(_){}
}

function tpNormalizeType(v){
  v=String(v||'').trim().toLowerCase().replace(/\s+/g,'_').replace(/-/g,'_');
  var map={classroom:'internal',on_job:'internal',on_the_job:'internal',in_house:'internal',internal_training:'internal',e_learning:'online',elearning:'online',external_course:'external'};
  v=map[v]||v||'internal';
  return ['internal','external','online','toolbox','induction','refresher'].includes(v)?v:'internal';
}
function tpTypeLabel(v){
  return {internal:'Classroom / internal',external:'External course',online:'Online / e-learning',toolbox:'Toolbox talk',induction:'Induction',refresher:'Refresher'}[tpNormalizeType(v)]||'Classroom / internal';
}

async function trainingQueueNotice(row,event,opts){
  try{
    row=row||{};opts=opts||{};
    var p=trainPersonByName(row.person_name)||personByDisplayName(row.person_name)||((people||[]).find(function(x){return x.id===row.person_id;}));
    var email=usersContactEmail(p);
    if(!email)return false;
    var labels={assigned:'Training assigned',completed:'Training completed',expired:'Training expired',expiring:'Training / certificate expiring',failed:'Training follow-up required'};
    var label=labels[event]||'Training update';
    var topic=row.training_topic||row.authorisation_type||row.competency_name||row.title||opts.topic||'Training';
    var due=row.expiry_date||row.refresher_due||row.target_date||opts.due||'';
    var body='<div style="font-family:Arial,sans-serif;background:#f4f6f8;padding:20px"><div style="max-width:620px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb">'
      +'<div style="background:#5B21B6;color:#fff;padding:18px 22px"><div style="font-size:20px;font-weight:700">AURIS360</div><div style="font-size:13px;opacity:.85">Training & competency update</div></div>'
      +'<div style="padding:22px"><h2 style="margin:0 0 14px;font-size:18px">'+escH(label)+'</h2>'
      +'<table style="width:100%;border-collapse:collapse;font-size:14px">'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600;width:150px">Person</td><td style="padding:8px">'+escH(row.person_name||peopleName(p)||'-')+'</td></tr>'
      +'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Training</td><td style="padding:8px">'+escH(topic)+'</td></tr>'
      +(due?'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Due / expiry</td><td style="padding:8px">'+escH(due)+'</td></tr>':'')
      +(opts.message?'<tr><td style="padding:8px;background:#f9fafb;font-weight:600">Message</td><td style="padding:8px">'+escH(opts.message)+'</td></tr>':'')
      +'</table><div style="margin-top:18px;text-align:center"><a href="https://auris360.app/?goto=training" style="display:inline-block;background:#1D9E75;color:#fff;padding:11px 22px;border-radius:8px;text-decoration:none;font-weight:700">Open Training</a></div></div>'
      +'<div style="padding:12px 22px;background:#f4f6f8;font-size:11px;color:#6B7280;text-align:center">Automated notification from AURIS360.</div></div></div>';
    await queueNotification({company_id:row.company_id||ccid(),type:'training',subject:'[AURIS360] '+label+': '+topic,body_html:body,to_email:email,to_name:row.person_name||peopleName(p)||email,from_name:'AURIS360 Training',related_module:'training',related_table:opts.related_table||'training_followup',related_id:row.id||opts.related_id||null,related_ref:opts.related_ref||row.training_ref||row.reference||topic,status:'pending'});
    return true;
  }catch(_){return false;}
}

async function trainingSaveWithFallback(path,request,body,fallbackKeys){
  try{
    return await api(path,request);
  }catch(e){
    if(!/schema cache|column|Could not find/i.test(e.message||''))throw e;
    var slim=Object.assign({},body||{});
    (fallbackKeys||[]).forEach(function(k){delete slim[k];});
    var req=Object.assign({},request,{b:slim});
    return apiWriteWithMissingColumnFallback(path,req,'Training record');
  }
}

function tpProviderMarker(v){
  v=obNormText(v||'');
  return v?'\n\n[Training institution / provider: '+v.replace(/[\r\n\[\]]/g,' ').trim()+']':'';
}
function tpStripProviderNote(v){
  return String(v||'').replace(/\n*\[Training institution \/ provider:[^\]]*\]\s*$/i,'').trim();
}
function tpProviderFromRecord(x){
  var m=String(x?.notes||'').match(/\[Training institution \/ provider:\s*([^\]]+)\]/i);
  return x?.training_provider||x?.training_institution||x?.provider_name||(m?m[1].trim():'');
}

function trainingPreviewAttachment(url,name){
  if(!url){toast('No attachment to preview',false);return;}
  var dataMime=(String(url).match(/^data:([^;,]+)/)||[])[1];
  dcOpenViewer({file_url:url,file_name:name||'Training attachment',file_mime:dataMime||dcMimeFromName(name||url)});
}

// -- COMPETENCY MATRIX -------------------------------------------------------
async function cmLoad(){
  var el=document.getElementById('cm3table');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var [comps, people_data, cm] = await Promise.all([
      api('/competencies?select=*'+cf()+'&order=sort_order,name'),
      api('/people?select=id,first_name,last_name,job_title&status=eq.active'+cf()+'&order=last_name'),
      api('/competency_matrix?select=*'+cf())
    ]);
    compAllData=comps||[];
    cmAllData=cm||[];
    if(!compAllData.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">'
        +'<div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div>'
        +'<div style="font-weight:600;margin-bottom:8px">No competencies defined yet</div>'
        +(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0309"><i class="ti ti-plus"></i>Add first competency</button>':'')
        +'</div>';
      return;
    }
    var ppl=people_data||[];
    // Build matrix
    var cmMap={};
    cmAllData.forEach(function(r){cmMap[r.person_id+'_'+r.competency_id]=r;});

    var html='<table style="border-collapse:collapse;font-size:12px;min-width:100%">';
    // Header
    html+='<thead><tr><th style="padding:8px 12px;background:#1a3a5c;color:#fff;text-align:left;min-width:160px;position:sticky;left:0;z-index:3">Person / Role</th>';
    compAllData.forEach(function(comp){
      html+='<th style="padding:6px 4px;background:#1a3a5c;color:#cce4ff;text-align:center;min-width:80px;font-size:10px;font-weight:600;max-width:90px;word-wrap:break-word">'+escH(comp.name)+'</th>';
    });
    if(isMgr())html+='<th style="padding:6px;background:#1a3a5c;width:60px"></th>';
    html+='</tr></thead><tbody>';
    // Rows
    ppl.forEach(function(p,pi){
      var bg=pi%2===0?'#fff':'#f9fafb';
      html+='<tr style="border-bottom:1px solid #f0f0f0">';
      html+='<td style="padding:8px 12px;background:'+bg+';position:sticky;left:0;z-index:2;border-right:2px solid #e5e7eb;font-weight:600">'
        +escH(p.last_name+', '+p.first_name)
        +'<br><span style="font-size:10px;color:var(--text2);font-weight:400">'+escH(p.job_title||'')+'</span>'
        +'</td>';
      compAllData.forEach(function(comp){
        var entry=cmMap[p.id+'_'+comp.id];
        var cur=entry?entry.current_level:null;
        var req=entry?entry.required_level:2;
        var isGap=cur!==null&&cur<req;
        var bg2=cur!==null?LEVEL_COLORS[cur]:'#f9fafb';
        var col2=cur!==null?LEVEL_TEXT[cur]:'#ccc';
        html+='<td style="padding:4px;text-align:center;background:'+bg+'">'
          +'<div style="width:52px;height:28px;border-radius:6px;background:'+bg2+';color:'+col2+';font-weight:700;font-size:12px;display:flex;align-items:center;justify-content:center;margin:0 auto;cursor:pointer;border:1px solid '+(isGap?'var(--red)':'transparent')+';position:relative" '
          +'title="'+escH(comp.name)+': Level '+(cur!==null?cur:'-')+' (required: '+req+')" '
          +'data-pid="'+p.id+'" data-cid="'+comp.id+'" data-auris-generated-onclick="g0310">'
          +(cur!==null?cur:'-')
          +(isGap?'<span style="position:absolute;top:-4px;right:-4px;width:8px;height:8px;border-radius:50%;background:var(--red)"></span>':'')
          +'</div></td>';
      });
      if(isMgr()){
        html+='<td style="padding:4px;background:'+bg+'"></td>';
      }
      html+='</tr>';
    });
    html+='</tbody></table>';
    // Gap legend
    el.innerHTML=html+'<div style="padding:10px 16px;border-top:1px solid var(--border);background:#fafafa;font-size:11px;color:var(--text2);display:flex;gap:16px;flex-wrap:wrap">'
      +LEVEL_COLORS.map(function(c,i){return '<span style="display:flex;align-items:center;gap:4px"><span style="width:14px;height:14px;border-radius:3px;background:'+c+';border:1px solid #e5e7eb;display:inline-block"></span>'+i+' - '+['No knowledge','Theoretical','First experience','Good level','Expert'][i]+'</span>';}).join('')
      +'<span style="display:flex;align-items:center;gap:4px"><span style="width:14px;height:14px;border-radius:3px;background:#fff;border:2px solid var(--red);display:inline-block"></span>Gap identified</span>'
      +'</div>';
  }catch(e){if(el)el.innerHTML=registerErrorHtml('register',e.message);console.error(e);}
}

async function cmEditCell(personId, compId){
  var entry=cmAllData.find(function(r){return r.person_id===personId&&r.competency_id===compId;});
  var comp=compAllData.find(function(c){return c.id===compId;});
  var person=(people||[]).find(function(p){return p.id===personId;});
  var cur=entry?entry.current_level:0;
  var req=entry?entry.required_level:2;
  var levelOptions=[
    {value:0,label:'0 - No knowledge'},
    {value:1,label:'1 - Theoretical'},
    {value:2,label:'2 - First experience'},
    {value:3,label:'3 - Good level'},
    {value:4,label:'4 - Expert'}
  ];
  var newCur=await appPrompt({title:'Update competency',message:'Competency: '+(comp?.name||'')+'. Select the current competency level.',value:String(cur),options:levelOptions});
  if(newCur===null)return;
  var newReq=await appPrompt({title:'Update competency',message:'Required level for this role',value:String(req),options:levelOptions});
  if(newReq===null)return;
  try{
    var body={company_id:ccid(),person_id:personId,competency_id:compId,
      current_level:parseInt(newCur)||0,required_level:parseInt(newReq)||2,updated_at:new Date().toISOString()};
    var savedEntry=null;
    if(entry){
      await api('/competency_matrix?id=eq.'+entry.id,{m:'PATCH',p:'return=minimal',b:body});
      savedEntry=Object.assign({},entry,body);
      trainingAudit('update','Competency matrix cell updated','competency_matrix',Object.assign({},savedEntry,{person_name:personFullName(person),competency_name:comp?.name}),{old_current_level:cur,old_required_level:req,new_current_level:body.current_level,new_required_level:body.required_level});
    }else{
      var created=await api('/competency_matrix',{m:'POST',p:'return=representation',b:body});
      savedEntry=(created&&created[0])||body;
      trainingAudit('create','Competency matrix cell added','competency_matrix',Object.assign({},savedEntry,{person_name:personFullName(person),competency_name:comp?.name}),{current_level:body.current_level,required_level:body.required_level});
    }
    if(body.current_level<body.required_level){
      try{
        await api('/action_tracker',{m:'POST',p:'return=minimal',b:{
          company_id:ccid(),
          source_module:'training',
          source_ref:'Competency gap - '+(comp?.name||'Competency'),
          source_id:(savedEntry&&savedEntry.id)||entry?.id||null,
          description:'Competency gap identified for '+(personFullName(person)||'person')+': '+(comp?.name||'competency')+' current level '+body.current_level+', required level '+body.required_level+'.',
          responsible:null,
          priority:'medium',
          status:'open',
          created_by:prof?.id
        }});
        trainingAudit('follow_up','Competency gap MAP action created','competency_matrix',Object.assign({},savedEntry||entry||body,{person_name:personFullName(person),competency_name:comp?.name}),{current_level:body.current_level,required_level:body.required_level});
        toast('Updated! Competency gap added to MAP.');
      }catch(ex){toast('Updated!');console.warn('Competency MAP action failed',ex);}
    }else toast('Updated!');
    cmLoad();
  }catch(e){toastActionError('Update competency matrix','Training & Competency',e);}
}

async function cmAddCompetency(){
  var name=await appPrompt({title:'Add competency',message:'Competency name',placeholder:'e.g. Fire extinguisher use'});
  if(!name||!name.trim())return;
  var cat=await appPrompt({title:'Add competency',message:'Category',value:'General',placeholder:'e.g. Fire Safety, Technical, Personal'});
  try{
    var body={company_id:ccid(),name:name.trim(),category:cat||'General',sort_order:compAllData.length};
    var created=await api('/competencies',{m:'POST',p:'return=representation',b:body});
    trainingAudit('create','Competency catalogue item added','competencies',(created&&created[0])||Object.assign({competency_name:body.name},body),{category:body.category});
    toast('Competency added!');
    cmLoad();
  }catch(e){toastActionError('Add competency','Training & Competency',e);}
}

// -- TRAINING NEEDS ANALYSIS -------------------------------------------------
async function tnaLoad(){
  var el=document.getElementById('tna-table');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/training_needs?select=*'+cf()+'&order=category,role_name,training_topic');
    tnAllData=d||[];
    if(!tnAllData.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">'
        +'<div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div>'
        +'<div style="font-weight:600;margin-bottom:8px">No training needs defined yet</div>'
        +(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0311"><i class="ti ti-plus"></i>Add requirement</button>':'')
        +'</div>';
      return;
    }
    // Group by role
    var byRole={};
    tnAllData.forEach(function(r){if(!byRole[r.role_name])byRole[r.role_name]=[];byRole[r.role_name].push(r);});
    var topics=[...new Set(tnAllData.map(function(r){return r.training_topic;}))];
    var cats=['INDUCTION','EMERGENCY','HIGH RISK WORK','GENERAL'];

    var html='<table style="border-collapse:collapse;font-size:12px;min-width:100%">';
    html+='<thead><tr><th style="padding:8px 12px;background:#1a3a5c;color:#fff;text-align:left;min-width:160px;position:sticky;left:0;z-index:3">Role</th>';
    topics.forEach(function(t){
      html+='<th style="padding:6px 4px;background:#1a3a5c;color:#cce4ff;text-align:center;min-width:70px;font-size:10px;font-weight:600;max-width:80px;word-wrap:break-word">'+escH(t)+'</th>';
    });
    html+='</tr></thead><tbody>';
    Object.entries(byRole).forEach(function(e,ri){
      var role=e[0], reqs=e[1];
      var bg=ri%2===0?'#fff':'#f9fafb';
      html+='<tr style="border-bottom:1px solid #f0f0f0"><td style="padding:8px 12px;background:'+bg+';position:sticky;left:0;z-index:2;border-right:2px solid #e5e7eb;font-weight:600">'+escH(role)+'</td>';
      topics.forEach(function(t){
        var req=reqs.find(function(r){return r.training_topic===t;});
        var val=req?req.requirement:'N';
        var bg2=val==='M'?'#EAF3DE':val==='D'?'#E6F1FB':'#f3f4f6';
        var col2=val==='M'?'#3B6D11':val==='D'?'#185FA5':'#9CA3AF';
        html+='<td style="padding:4px;text-align:center;background:'+bg+'">'
          +'<span style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:6px;background:'+bg2+';color:'+col2+';font-weight:700;font-size:12px">'+val+'</span>'
          +'</td>';
      });
      html+='</tr>';
    });
    html+='</tbody></table>';
    el.innerHTML=html;
  }catch(e){if(el)el.innerHTML=registerErrorHtml('register',e.message);console.error(e);}
}

async function tnaAddRow(){
  var role=await appPrompt({title:'Add training need',message:'Role name',placeholder:'e.g. Supervisor'});if(!role)return;
  role=obNormText(role);
  var topic=await appPrompt({title:'Add training need',message:'Training topic',placeholder:'e.g. Permit to Work'});if(!topic)return;
  topic=obNormText(topic);
  var cat=await appPrompt({title:'Add training need',message:'Category',value:'GENERAL',placeholder:'INDUCTION, EMERGENCY, HIGH RISK WORK or GENERAL'});
  var req=await appPrompt({title:'Add training need',message:'Requirement',value:'D',placeholder:'M, D or N'});
  cat=obNormText(cat||'GENERAL').toUpperCase();
  req=obNormText(req||'').toUpperCase();
  if(!['M','D','N'].includes((req||'').toUpperCase())){toast('Invalid value. Use M, D or N',false);return;}
  var dup=(tnAllData||[]).find(function(x){return obNormText(x.role_name).toLowerCase()===role.toLowerCase()&&obNormText(x.training_topic).toLowerCase()===topic.toLowerCase();});
  if(dup){toast('This training need already exists for the selected role',false);return;}
  api('/training_needs',{m:'POST',p:'return=minimal',b:{
    company_id:ccid(),role_name:role,training_topic:topic,
    category:cat,requirement:req
  }}).then(function(){toast('Added!');tnaLoad();}).catch(function(e){toastActionError('Add training need','Training & Competency',e);});
}

// -- TRAINING PLAN -----------------------------------------------------------
function trainPlanPrevYear(){trainYear--;var yl=document.getElementById('tp-year-label');if(yl)yl.textContent=trainYear;tpLoad();}
function trainPlanNextYear(){trainYear++;var yl=document.getElementById('tp-year-label');if(yl)yl.textContent=trainYear;tpLoad();}

async function tpLoad(){
  var el=document.getElementById('tp-table');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/training_plan?select=*'+cf()+'&year=eq.'+trainYear+'&order=month,planned_date');
    var trainingRecords=await api('/training_followup?select=training_topic,training_date,person_name,certificate'+cf()+'&order=training_date.desc').catch(function(){return [];});
    tpAllData=d||[];
    var today=new Date();
    var planned=tpAllData.filter(function(x){return x.status==='planned'||x.status==='confirmed';}).length;
    var completed=tpAllData.filter(function(x){return x.status==='completed';}).length;
    var progress=tpAllData.filter(function(x){return x.status==='confirmed';}).length;
    var overdue=tpAllData.filter(function(x){
      return (x.status==='planned'||x.status==='confirmed')&&x.planned_date&&new Date(x.planned_date)<today;
    }).length;
    var setM=function(id,v,c){var e=document.getElementById(id);if(e){e.textContent=v;if(c)e.style.color=c;}};
    setM('tp-m3planned',planned);setM('tp-m3completed',completed);
    setM('tp-m3progress',progress);setM('tp-m3overdue',overdue,'#E24B4A');
    if(!tpAllData.length){
      if(el)el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">'
        +'<div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div>'
        +'<div style="font-weight:600;margin-bottom:8px">No training planned for '+trainYear+'</div>'
        +(isMgr()?'<button class="btn btn-primary" data-auris-generated-onclick="g0312"><i class="ti ti-plus"></i>Plan first training</button>':'')
        +'</div>';
      return;
    }
    var months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var statusBadge=function(s){
      var cfg={planned:['#E6F1FB','#185FA5'],confirmed:['#EAF3DE','#3B6D11'],completed:['#1D9E75','#fff'],cancelled:['#f3f4f6','#6B7280'],postponed:['#FEF9EC','#854F0B']};
      var c=cfg[s]||cfg.planned;
      return '<span style="background:'+c[0]+';color:'+c[1]+';padding:2px 8px;border-radius:99px;font-size:11px;font-weight:600">'+s.charAt(0).toUpperCase()+s.slice(1)+'</span>';
    };
    var priorityBadge=function(p){
      var cfg={low:['#f3f4f6','#6B7280'],medium:['#E6F1FB','#185FA5'],high:['#FEF9EC','#854F0B'],critical:['#FCEBEB','#A32D2D']};
      var c=cfg[p]||cfg.medium;
      return '<span style="background:'+c[0]+';color:'+c[1]+';padding:2px 6px;border-radius:4px;font-size:11px;font-weight:600">'+p+'</span>';
    };
    function tpEvidenceBadge(x){
      var topic=String(x.training_topic||'').trim().toLowerCase();
      var actual=x.actual_date||'';
      var matches=(trainingRecords||[]).filter(function(r){
        var sameTopic=String(r.training_topic||'').trim().toLowerCase()===topic;
        var sameDate=!actual||String(r.training_date||'')===actual;
        return topic&&sameTopic&&sameDate;
      });
      if(matches.length)return '<span class="badge badge-green">'+matches.length+' record'+(matches.length>1?'s':'')+'</span>'+(matches.some(function(r){return r.certificate;})?'<div class="muted">Certificate evidence</div>':'');
      if(String(x.status||'').toLowerCase()==='completed')return '<span class="badge badge-amber">Evidence missing</span><div class="muted">Add attendance/training record</div>';
      return '<span class="muted">Not due yet</span>';
    }
    var h='<div class="table-scroll"><table class="data-table" style="min-width:980px">';
    h+='<thead><tr>';
    h+='<th style="width:50px">Month</th>';
    h+='<th>Training</th>';
    h+='<th style="width:120px">Target group</th>';
    h+='<th style="width:80px">Type</th>';
    h+='<th style="width:80px">Priority</th>';
    h+='<th style="width:100px">Planned date</th>';
    h+='<th style="width:130px">Evidence</th>';
    h+='<th style="width:110px">Status</th>';
    h+='<th style="width:70px"></th>';
    h+='</tr></thead><tbody>';
    tpAllData.forEach(function(x,i){
      var bg=i%2===0?'#fff':'#f9fafb';
      var mo=x.month?months[x.month-1]:'-';
      var dt=x.planned_date?new Date(x.planned_date).toLocaleDateString('en-GB'):'-';
      var isOverdue=(x.status==='planned'||x.status==='confirmed')&&x.planned_date&&new Date(x.planned_date)<today;
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+(isOverdue?';border-left:3px solid var(--red)':'')+'">';
      h+='<td style="padding:8px 10px;font-weight:700;color:var(--text2)">'+mo+'</td>';
      h+='<td style="padding:8px 10px"><div style="font-weight:600">'+escH(x.training_topic||'-')+'</div>'+(x.trainer?'<div style="font-size:11px;color:var(--text2)"><i class="ti ti-user"></i> '+escH(x.trainer)+'</div>':'')+'</td>';
      h+='<td style="padding:8px 10px;font-size:11px">'+escH(x.target_group||'-')+'</td>';
      h+='<td style="padding:8px 10px;font-size:11px">'+escH(tpTypeLabel(x.training_type))+'</td>';
      h+='<td style="padding:8px 10px">'+priorityBadge(x.priority||'medium')+'</td>';
      h+='<td style="padding:8px 10px;font-size:11px'+(isOverdue?';color:var(--red);font-weight:600':'')+'">'+dt+(isOverdue?' - overdue':'')+'</td>';
      h+='<td style="padding:8px 10px">'+tpEvidenceBadge(x)+'</td>';
      h+='<td style="padding:8px 10px">'+statusBadge(x.status||'planned')+'</td>';
      h+='<td style="padding:8px 10px"><div style="display:flex;gap:4px">'
        +'<button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0313"><i class="ti ti-edit"></i></button>'
        +(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0314"><i class="ti ti-trash"></i></button>':'')
        +'</div></td>';
      h+='</tr>';
    });
    h+='</tbody></table></div>';
    if(el)el.innerHTML=h;
  }catch(e){if(el)el.innerHTML=registerErrorHtml('register',e.message);console.error(e);}
}

function tpShowForm(){
  document.getElementById('train-view-plan').style.display='none';
  document.getElementById('tp-form').style.display='block';
}
function tpBack(){
  document.getElementById('tp-form').style.display='none';
  document.getElementById('train-view-plan').style.display='block';
  tpLoad();
}

function tpNew(){
  tpEditingId=null;
  document.getElementById('tp-form3title').textContent='New Training';
  document.getElementById('tp-del-btn').style.display='none';
  ['tp-topic','tp-group','tp-trainer','tp-provider','tp-location','tp-objective','tp-notes'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  fillPersonSelect('tp-trainer');
  ['tp-planned-date','tp-actual-date'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var tp=document.getElementById('tp-type');if(tp)tp.value='internal';
  var pp=document.getElementById('tp-priority');if(pp)pp.value='medium';
  var sp=document.getElementById('tp-status');if(sp)sp.value='planned';
  var dur=document.getElementById('tp-duration');if(dur)dur.value='';
  var bud=document.getElementById('tp-budget');if(bud)bud.value='';
  var mo=document.getElementById('tp-month');if(mo)mo.value='';
  tpShowForm();
}

function tpOpen(id){
  var x=tpAllData.find(function(r){return r.id===id;});
  if(!x)return;
  tpEditingId=id;
  document.getElementById('tp-form3title').textContent='Edit Training';
  document.getElementById('tp-del-btn').style.display=isMgr()?'inline-flex':'none';
  var flds={'tp-topic':'training_topic','tp-group':'target_group','tp-trainer':'trainer','tp-location':'location','tp-objective':'objective'};
  Object.entries(flds).forEach(function(e){var el=document.getElementById(e[0]);if(el)el.value=x[e[1]]||'';});
  var providerEl=document.getElementById('tp-provider');if(providerEl)providerEl.value=tpProviderFromRecord(x)||'';
  var notesEl=document.getElementById('tp-notes');if(notesEl)notesEl.value=tpStripProviderNote(x.notes||'');
  fillPersonSelect('tp-trainer',x.trainer);
  setSelectValueWithFallback('tp-trainer',x.trainer);
  var pd=document.getElementById('tp-planned-date');if(pd)pd.value=x.planned_date||'';
  var ad=document.getElementById('tp-actual-date');if(ad)ad.value=x.actual_date||'';
  var tp=document.getElementById('tp-type');if(tp)tp.value=tpNormalizeType(x.training_type);
  var pp=document.getElementById('tp-priority');if(pp)pp.value=x.priority||'medium';
  var sp=document.getElementById('tp-status');if(sp)sp.value=x.status||'planned';
  var dur=document.getElementById('tp-duration');if(dur)dur.value=x.duration_hours||'';
  var bud=document.getElementById('tp-budget');if(bud)bud.value=x.budget||'';
  var mo=document.getElementById('tp-month');if(mo)mo.value=x.month||'';
  tpShowForm();
}

async function tpSave(){
  var topic=obNormText(document.getElementById('tp-topic')?.value);
  if(!topic){toast('Please enter a training topic',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?obNormText(el.value)||null:null;};
  var planned=g('tp-planned-date'), actual=g('tp-actual-date'), status=g('tp-status')||'planned';
  var duration=g('tp-duration'), budget=g('tp-budget'), provider=g('tp-provider'), monthVal=document.getElementById('tp-month')?.value;
  if(planned&&actual&&actual<planned){toast('Actual date cannot be before planned date',false);return;}
  if(status==='completed'&&!actual){toast('Completed training must have an actual date',false);return;}
  if(duration&&Number(duration)<0){toast('Duration cannot be negative',false);return;}
  if(budget&&Number(budget)<0){toast('Budget cannot be negative',false);return;}
  if(!monthVal&&planned)monthVal=String(new Date(planned).getMonth()+1);
  var body={
    company_id:ccid(),year:trainYear,
    training_topic:topic,target_group:g('tp-group'),
    month:monthVal?parseInt(monthVal):null,
    training_type:tpNormalizeType(g('tp-type')),priority:g('tp-priority')||'medium',
    status:status,trainer:g('tp-trainer'),location:g('tp-location'),
    planned_date:planned,actual_date:actual,
    duration_hours:duration?parseFloat(duration):null,
    budget:budget?parseFloat(budget):null,
    training_provider:provider,objective:g('tp-objective'),notes:tpStripProviderNote(g('tp-notes')||'')+tpProviderMarker(provider),updated_at:new Date().toISOString()
  };
  try{
    if(tpEditingId){
      var current=tpAllData.find(function(x){return x.id===tpEditingId;})||{};
      await trainingSaveWithFallback('/training_plan?id=eq.'+tpEditingId,{m:'PATCH',p:'return=minimal',b:body},body,['training_provider','training_institution','provider_name']);
      trainingAudit('update','Training plan item updated','training_plan',Object.assign({id:tpEditingId},body),{old_status:current.status||null,new_status:body.status||null});
      if(current.status!=='completed'&&body.status==='completed')trainingAudit('complete','Training plan item completed','training_plan',Object.assign({id:tpEditingId},body),{actual_date:body.actual_date});
      toast('Updated!');
    }
    else{
      body.created_by=prof?.id;
      var created=await trainingSaveWithFallback('/training_plan',{m:'POST',p:'return=representation',b:body},body,['training_provider','training_institution','provider_name']);
      trainingAudit('create','Training plan item created','training_plan',created?.[0]||body,{planned_date:body.planned_date});
      toast('Training added to plan!');
    }
    tpBack();
  }catch(e){toastActionError('Save training provider','Training & Competency',e);console.error(e);}
}

async function tpDelete(){
  if(!tpEditingId)return;
  if(!(await appConfirmAction({title:'Cancel training plan item',message:'Cancel this planned training?',detail:'The plan item is kept for history and marked as cancelled.',confirmText:'Cancel training',cancelText:'Back'})))return;
  try{var current=tpAllData.find(function(x){return x.id===tpEditingId;})||{id:tpEditingId};await api('/training_plan?id=eq.'+tpEditingId,{m:'PATCH',p:'return=minimal',b:{status:'cancelled',updated_at:new Date().toISOString()}});trainingAudit('cancel','Training plan item cancelled','training_plan',Object.assign({},current,{status:'cancelled'}),{old_status:current.status||null,new_status:'cancelled'});toast('Training plan item cancelled');tpBack();}
  catch(e){toastActionError('Delete training provider','Training & Competency',e);}
}

async function tpDeleteFromList(id){
  if(!(await appConfirmAction({title:'Cancel training plan item',message:'Cancel this planned training?',detail:'The plan item is kept for history and marked as cancelled.',confirmText:'Cancel training',cancelText:'Back'})))return;
  try{var current=tpAllData.find(function(x){return x.id===id;})||{id:id};await api('/training_plan?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{status:'cancelled',updated_at:new Date().toISOString()}});trainingAudit('cancel','Training plan item cancelled','training_plan',Object.assign({},current,{status:'cancelled'}),{old_status:current.status||null,new_status:'cancelled'});toast('Training plan item cancelled');tpLoad();}
  catch(e){toastActionError('Delete training provider','Training & Competency',e);}
}
async function trainingAIGapReview(){
  var panel=document.getElementById('train-ai-gap-panel');
  if(typeof canUseAI==='function'&&!canUseAI()){toast('AURIS AI is restricted to authorised HSE/admin roles.',false);return;}
  if(panel){panel.style.display='block';panel.innerHTML='<div class="card" style="border-left:4px solid #5B21B6"><div style="font-weight:800;color:#5B21B6"><i class="ti ti-loader"></i> AURIS is reviewing training gaps...</div><div style="font-size:12px;color:var(--text2);margin-top:5px">Checking the training plan, records, competencies, inductions and active staff.</div></div>';}
  try{
    var today=new Date().toISOString().slice(0,10);
    var data=await Promise.all([
      api('/training_plan?select=*'+cf()+'&year=eq.'+trainYear+'&order=month,planned_date').catch(function(){return [];}),
      api('/training_followup?select=*'+cf()+'&order=training_date.desc').catch(function(){return [];}),
      api('/competency_matrix?select=*'+cf()).catch(function(){return [];}),
      api('/competencies?select=*'+cf()).catch(function(){return [];}),
      api('/training_needs?select=*'+cf()).catch(function(){return [];}),
      api('/induction_records?select=*'+cf()+'&order=induction_date.desc').catch(function(){return [];}),
      api('/people?select=id,first_name,last_name,job_title,department,status'+cf()+'&status=eq.active').catch(function(){return people||[];}),
      api('/elearning_enrolments?select=*'+cf()).catch(function(){return [];})
    ]);
    var ctx={today:today,year:trainYear,training_plan:data[0]||[],training_records:data[1]||[],competency_matrix:data[2]||[],competencies:data[3]||[],training_needs:data[4]||[],inductions:data[5]||[],active_people:data[6]||[],elearning:data[7]||[]};
    var prompt='Review this AURIS360 Training & Competency dataset as a senior HSE training manager. Return STRICT JSON only with keys: summary string, urgent_gaps array of objects {gap,risk,evidence,recommended_training,target_group,priority,due_date}, recommended_plan_items array of objects {topic,target_group,type,priority,planned_date,objective,notes}, assurance_checks array of strings, management_message string. Prioritise legal/HSE critical gaps, overdue training, missing induction, expiring certificates and competency gaps. Use concise professional wording. Dataset: '+JSON.stringify(ctx).slice(0,18000);
    var raw=await callAI([{role:'user',content:prompt}], 'You are AURIS, an expert HSE training and competency assurance assistant. Return valid JSON only.');
    var out=aiExtractJson(raw)||{};
    trainingAIRenderGapReview(out,ctx);
    toast('Training AI review ready');
  }catch(e){if(panel)panel.innerHTML=aiFriendlyErrorHtml(e);toast(aiFriendlyError(e),false);}
}

function trainingAIRenderGapReview(out,ctx){
  var panel=document.getElementById('train-ai-gap-panel');if(!panel)return;
  var gaps=Array.isArray(out.urgent_gaps)?out.urgent_gaps:[];
  var items=Array.isArray(out.recommended_plan_items)?out.recommended_plan_items:[];
  window.trainingAiPlanItems=items;
  var checks=Array.isArray(out.assurance_checks)?out.assurance_checks:[];
  var h='<div class="card" style="border-left:4px solid #5B21B6;background:#fff">';
  h+='<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap"><div><div style="font-weight:900;color:#5B21B6;font-size:15px"><i class="ti ti-robot"></i> AI Training & Competency Gap Review</div><div style="font-size:12px;color:var(--text2);margin-top:4px">Review before applying. Based on '+(ctx.active_people||[]).length+' active people, '+(ctx.training_plan||[]).length+' plan items and '+(ctx.training_records||[]).length+' training records.</div></div><button class="btn btn-sm" data-auris-generated-onclick="g0315"><i class="ti ti-x"></i></button></div>';
  h+='<div style="margin-top:12px;padding:10px 12px;border-radius:8px;background:#F5F3FF;color:#4C1D95;font-size:13px;line-height:1.45">'+escH(out.summary||'AURIS reviewed the training data and prepared suggested competency actions.')+'</div>';
  if(gaps.length){
    h+='<div style="margin-top:14px;font-weight:800">Priority gaps</div><div class="table-scroll" style="margin-top:8px"><table class="data-table" style="min-width:980px"><thead><tr><th>Gap</th><th>Risk</th><th>Evidence</th><th>Recommended training</th><th style="width:90px">Priority</th><th style="width:100px">Due</th></tr></thead><tbody>';
    gaps.slice(0,8).forEach(function(g,i){h+='<tr style="border-bottom:1px solid var(--border);background:'+(i%2?'#fff':'#f9fafb')+'"><td style="padding:8px;font-weight:700">'+escH(g.gap||'Gap')+'</td><td style="padding:8px">'+escH(g.risk||'')+'</td><td style="padding:8px;color:var(--text2)">'+escH(g.evidence||'')+'</td><td style="padding:8px">'+escH(g.recommended_training||'')+'<div style="font-size:11px;color:var(--text2)">'+escH(g.target_group||'')+'</div></td><td style="padding:8px">'+escH(g.priority||'medium')+'</td><td style="padding:8px">'+escH(g.due_date||'')+'</td></tr>';});
    h+='</tbody></table></div>';
  }
  if(items.length){
    h+='<div style="margin-top:14px;font-weight:800">Suggested training plan items</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px;margin-top:8px">';
    items.slice(0,6).forEach(function(it,i){h+='<div style="border:1px solid var(--border);border-radius:8px;padding:10px;background:#fafafa"><div style="font-weight:800">'+escH(it.topic||'Training')+'</div><div style="font-size:12px;color:var(--text2);margin-top:4px">'+escH(it.target_group||'')+'</div><div style="font-size:12px;margin-top:6px"><b>Priority:</b> '+escH(it.priority||'medium')+' &nbsp; <b>Date:</b> '+escH(it.planned_date||'')+'</div><div style="font-size:12px;color:var(--text2);margin-top:6px;line-height:1.4">'+escH(it.objective||it.notes||'')+'</div><button class="btn btn-sm btn-primary" style="margin-top:8px" data-i="'+i+'" data-auris-generated-onclick="g0316"><i class="ti ti-plus"></i>Prefill plan</button></div>';});
    h+='</div>';
  }
  if(checks.length){h+='<div style="margin-top:14px;font-weight:800">Assurance checks</div><ul style="margin:8px 0 0 18px;color:var(--text2);font-size:12px;line-height:1.5">'+checks.slice(0,8).map(function(c){return '<li>'+escH(c)+'</li>';}).join('')+'</ul>';}
  if(out.management_message)h+='<div style="margin-top:12px;padding:10px 12px;border-radius:8px;background:#EFF6FF;color:#1E3A8A;font-size:12px;line-height:1.45"><b>Management note:</b> '+escH(out.management_message)+'</div>';
  h+='</div>';
  panel.innerHTML=h;
}

function trainingAIApplyPlanItem(i){
  var it=(window.trainingAiPlanItems||[])[i];if(!it)return;
  tpNew();
  var set=function(id,v){var el=document.getElementById(id);if(el&&v!=null)el.value=v;};
  set('tp-topic',it.topic||it.recommended_training||'');
  set('tp-group',it.target_group||'');
  set('tp-type',tpNormalizeType(it.type||'internal'));
  set('tp-priority',it.priority||'medium');
  set('tp-planned-date',it.planned_date||'');
  if(it.planned_date){var m=new Date(it.planned_date).getMonth()+1;if(m>0)set('tp-month',String(m));}
  set('tp-objective',it.objective||'');
  set('tp-notes',it.notes||'Suggested by AURIS AI training gap review. Review before saving.');
  toast('AI suggestion copied into training plan form - review then save');
}

// -- TRAINING FOLLOW-UP ------------------------------------------------------
async function tfLoad(){
  var el=document.getElementById('tf-table');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/training_followup?select=*'+cf()+'&order=training_date.desc');
    tfAllData=d||[];
    // Populate person dropdowns
    var opts='<option value="">Select person...</option>';
    (people||[]).forEach(function(p){opts+='<option value="'+p.id+'">'+p.last_name+', '+p.first_name+(p.job_title?' - '+p.job_title:'')+'</option>';});
    ['tfr-person','authr-person'].forEach(function(id){var sel=document.getElementById(id);if(sel)sel.innerHTML=opts;});
    tfRender(tfAllData);
  }catch(e){if(el)el.innerHTML=registerErrorHtml('register',e.message);console.error(e);}
}

function tfFilter(){
  var q=(document.getElementById('tf-search')?.value||'').toLowerCase();
  var filtered=tfAllData.filter(function(x){
    return !q||(x.person_name||'').toLowerCase().includes(q)||(x.training_topic||'').toLowerCase().includes(q);
  });
  tfRender(filtered);
}

function tfRender(data){
  var el=document.getElementById('tf-table');if(!el)return;
  if(!data.length){
    el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">No training records found.'+(isMgr()?' <button class="btn btn-primary btn-sm" data-auris-generated-onclick="g0317"><i class="ti ti-plus"></i>Add record</button>':'')+'</div>';
    return;
  }
  var today=new Date();
  var soon=new Date();soon.setDate(soon.getDate()+30);
  var h='<div class="table-scroll"><table class="data-table" style="min-width:980px"><thead><tr>'
    +'<th>Name</th>'
    +'<th>Training</th>'
    +'<th style="width:100px">Date</th>'
    +'<th style="width:130px">Certificate</th>'
    +'<th style="width:100px">Expiry</th>'
    +'<th style="width:100px">Refresher</th>'
    +'<th style="text-align:center;width:70px">Result</th>'
    +'<th style="width:70px"></th>'
    +'</tr></thead><tbody>';
  data.forEach(function(x,i){
    var bg=i%2===0?'#fff':'#f9fafb';
    var dt=x.training_date?new Date(x.training_date).toLocaleDateString('en-GB'):'-';
    var exp=x.expiry_date?new Date(x.expiry_date):'';
    var ref=x.refresher_due?new Date(x.refresher_due):'';
    var expStr=exp?exp.toLocaleDateString('en-GB'):'-';
    var refStr=ref?ref.toLocaleDateString('en-GB'):'-';
    var expAlert=exp&&exp<today?'color:var(--red);font-weight:700':exp&&exp<soon?'color:var(--amber);font-weight:600':'';
    var refAlert=ref&&ref<today?'color:var(--red);font-weight:700':ref&&ref<soon?'color:var(--amber);font-weight:600':'';
    var certUrl=x.certificate_url||x.evidence_url||'';
    var certCell=certUrl
      ? '<button class="btn btn-sm" title="Preview certificate" data-url="'+escH(certUrl)+'" data-name="'+escH(x.certificate||x.training_topic||'Training certificate')+'" data-auris-generated-onclick="g0318"><i class="ti ti-eye"></i> '+escH(x.certificate||'Certificate')+'</button>'
      : escH(x.certificate||'-');
    var archived=/\[Archived/i.test(String(x.notes||''));
    var result=archived?'<span class="badge gray">Archived</span>':x.passed===true?'<span style="color:var(--green);font-weight:700">Pass</span>':x.passed===false?'<span style="color:var(--red)">Fail</span>':'-';
    h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
      +'<td style="padding:8px 10px;font-weight:600">'+escH(x.person_name||'-')+'</td>'
      +'<td style="padding:8px 10px">'+escH(x.training_topic||'-')+'</td>'
      +'<td style="padding:8px 10px">'+dt+'</td>'
      +'<td style="padding:8px 10px;font-size:11px">'+certCell+'</td>'
      +'<td style="padding:8px 10px;'+expAlert+'">'+expStr+(expAlert.includes('red')?' ?':'')+'</td>'
      +'<td style="padding:8px 10px;'+refAlert+'">'+refStr+(refAlert.includes('red')?' ?':'')+'</td>'
      +'<td style="padding:8px 10px;text-align:center">'+result+'</td>'
      +'<td style="padding:8px 10px"><div style="display:flex;gap:4px">'
      +'<button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0319"><i class="ti ti-edit"></i></button>'
      +(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0320"><i class="ti ti-trash"></i></button>':'')
      +'</div></td>'
      +'</tr>';
  });
  h+='</tbody></table></div>';
  el.innerHTML=h;
}

function tfShowForm(){
  document.getElementById('train-view-followup').style.display='none';
  document.getElementById('tf-form').style.display='block';
}
function tfBack(){
  document.getElementById('tf-form').style.display='none';
  document.getElementById('train-view-followup').style.display='block';
  tfLoad();
}

function tfNew(){
  tfEditingId=null;
  document.getElementById('tf-form3title').textContent='New Training Record';
  document.getElementById('tf-del-btn').style.display='none';
  ['tfr-name','tfr-course','tfr-trainer','tfr-cert','tfr-cert-url','tfr-notes'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  fillPersonSelect('tfr-trainer');
  ['tfr-date','tfr-expiry','tfr-refresher'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var sc=document.getElementById('tfr-score');if(sc)sc.value='';
  var ps=document.getElementById('tfr-passed');if(ps)ps.value='true';
  var per=document.getElementById('tfr-person');if(per)per.value='';
  tfShowForm();
}

function tfOpen(id){
  var x=tfAllData.find(function(r){return r.id===id;});
  if(!x)return;
  tfEditingId=id;
  document.getElementById('tf-form3title').textContent='Edit Training Record';
  document.getElementById('tf-del-btn').style.display=isMgr()?'inline-flex':'none';
  var flds={'tfr-name':'person_name','tfr-course':'training_topic','tfr-trainer':'trainer','tfr-cert':'certificate','tfr-cert-url':'certificate_url','tfr-notes':'notes'};
  Object.entries(flds).forEach(function(e){var el=document.getElementById(e[0]);if(el)el.value=x[e[1]]||'';});
  var certUrl=document.getElementById('tfr-cert-url');if(certUrl)certUrl.value=x.certificate_url||x.evidence_url||'';
  fillPersonSelect('tfr-trainer',x.trainer);
  setSelectValueWithFallback('tfr-trainer',x.trainer);
  ['tfr-date','tfr-expiry','tfr-refresher'].forEach(function(id){
    var key={'tfr-date':'training_date','tfr-expiry':'expiry_date','tfr-refresher':'refresher_due'}[id];
    var el=document.getElementById(id);if(el)el.value=x[key]||'';
  });
  var sc=document.getElementById('tfr-score');if(sc)sc.value=x.score||'';
  var ps=document.getElementById('tfr-passed');if(ps)ps.value=String(x.passed!==false);
  var per=document.getElementById('tfr-person');if(per)per.value=x.person_id||'';
  tfShowForm();
}

async function tfSave(){
  var course=obNormText(document.getElementById('tfr-course')?.value);
  if(!course){toast('Please enter a training topic',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?obNormText(el.value)||null:null;};
  var personId=g('tfr-person');
  var pickedPerson=(people||[]).find(function(p){return p.id===personId;});
  var name=g('tfr-name')||personFullName(pickedPerson);
  var trainingDate=g('tfr-date'), expiry=g('tfr-expiry'), refresher=g('tfr-refresher'), score=g('tfr-score');
  if(!personId&&!name){toast('Please select or enter the person trained',false);return;}
  if(!trainingDate){toast('Please enter the training date',false);return;}
  if(expiry&&expiry<trainingDate){toast('Certificate expiry cannot be before training date',false);return;}
  if(refresher&&refresher<trainingDate){toast('Refresher due date cannot be before training date',false);return;}
  if(score&&(Number(score)<0||Number(score)>100)){toast('Score must be between 0 and 100',false);return;}
  var body={
    company_id:ccid(),person_id:personId||null,
    person_name:name||null,training_topic:course,
    training_date:trainingDate,trainer:g('tfr-trainer'),certificate:g('tfr-cert'),
    certificate_url:g('tfr-cert-url'),evidence_url:g('tfr-cert-url'),
    expiry_date:expiry,refresher_due:refresher,
    score:score?parseFloat(score):null,
    passed:document.getElementById('tfr-passed')?.value!=='false',
    notes:g('tfr-notes'),updated_at:new Date().toISOString()
  };
  Object.assign(body,personIdentityPayload(personId||name));
  try{
    if(tfEditingId){
      var current=tfAllData.find(function(x){return x.id===tfEditingId;})||{};
      await trainingSaveWithFallback('/training_followup?id=eq.'+tfEditingId,{m:'PATCH',p:'return=minimal',b:body},body,['certificate_url','evidence_url']);
      var row=Object.assign({},current,body,{id:tfEditingId});
      trainingAudit('update','Training follow-up record updated','training_followup',row,{old_passed:current.passed,new_passed:body.passed});
      if(body.passed===false){
        trainingAudit('fail','Training follow-up required after failed result','training_followup',row,{score:body.score});
        await trainingQueueNotice(row,'failed',{related_table:'training_followup',related_id:tfEditingId,message:'Arrange retraining or reassessment.'});
      }
      toast('Updated!');
    }
    else{
      body.created_by=prof?.id;
      var res=await trainingSaveWithFallback('/training_followup',{m:'POST',p:'return=representation',b:body},body,['certificate_url','evidence_url']);
      var saved=res?.[0]||body;
      trainingAudit(body.passed===false?'fail':'create',body.passed===false?'Training follow-up required after failed result':'Training follow-up record created','training_followup',saved,{score:body.score});
      var added=false;
      if(body.passed===false&&res?.[0]?.id){
        try{
          await api('/action_tracker',{m:'POST',p:'return=minimal',b:{
            company_id:ccid(),
            source_module:'training',
            source_id:res[0].id,
            source_ref:'Failed training - '+course,
            description:'Training follow-up required: '+(name||'Person')+' failed '+course+'. '+(body.notes||'Arrange retraining or reassessment.'),
            responsible:body.trainer||null,
            target_date:body.refresher_due||body.expiry_date||null,
            priority:'medium',
            status:'open',
            created_by:prof?.id
          }});
          added=true;
        }catch(ex){console.warn('Training MAP action failed',ex);}
        await trainingQueueNotice(saved,'failed',{related_table:'training_followup',related_id:res[0].id,message:'Arrange retraining or reassessment.'});
      }
      toast('Record saved!'+(added?' Action added to MAP.':''));
    }
    tfBack();
  }catch(e){toastActionError('Save training follow-up','Training & Competency',e);console.error(e);}
}

async function tfDelete(){
  if(!tfEditingId)return;
  var current=tfAllData.find(function(r){return r.id===tfEditingId;})||{};
  var archived=/\[Archived/i.test(String(current.notes||''));
  if(!archived){
    if(!(await appConfirmAction({title:'Archive training follow-up',message:'Archive this training follow-up instead of deleting it?',detail:'Training history is evidence of competence. The record will remain available for audit history. Permanent delete is only available after archiving.',confirmText:'Archive record',cancelText:'Back'})))return;
    try{await api('/training_followup?id=eq.'+tfEditingId,{m:'PATCH',p:'return=minimal',b:{notes:('[Archived '+new Date().toISOString().slice(0,10)+'] '+(current.notes||'')).trim()}});trainingAudit('archive','Training follow-up archived','training_followup',Object.assign({id:tfEditingId},current),{});toast('Training follow-up archived');tfBack();}
    catch(e){toastActionError('Delete training file','Training & Competency',e);}
    return;
  }
  if(!(await appConfirmDelete('training follow-up record','This record is already archived. Permanent deletion should be used only for duplicate/test records.')))return;
  try{await api('/training_followup?id=eq.'+tfEditingId,{m:'DELETE'});trainingAudit('delete','Training follow-up permanently deleted','training_followup',Object.assign({id:tfEditingId},current),{});toast('Deleted!');tfBack();}
  catch(e){toastActionError('Delete training file','Training & Competency',e);}
}

async function tfDeleteFromList(id){
  var current=tfAllData.find(function(r){return r.id===id;})||{};
  var archived=/\[Archived/i.test(String(current.notes||''));
  if(!archived){
    if(!(await appConfirmAction({title:'Archive training follow-up',message:'Archive this training follow-up instead of deleting it?',detail:'Training history is evidence of competence. The record will remain available for audit history.',confirmText:'Archive record',cancelText:'Back'})))return;
    try{
      var archivedNotes=('[Archived '+new Date().toISOString().slice(0,10)+'] '+(current.notes||'')).trim();
      await api('/training_followup?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{notes:archivedNotes}});
      trainingAudit('archive','Training follow-up archived','training_followup',Object.assign({id:id},current),{});
      var idx=tfAllData.findIndex(function(x){return x.id===id;});
      if(idx>=0)tfAllData[idx]=Object.assign({},tfAllData[idx],{notes:archivedNotes});
      toast('Training follow-up archived');
      tfRender(tfAllData);
    }catch(e){toastActionError('Archive training follow-up','Training & Competency',e);}
    return;
  }
  if(!(await appConfirmDelete('training follow-up record','This record is already archived. Permanent deletion should be used only for duplicate/test records.')))return;
  try{await api('/training_followup?id=eq.'+id,{m:'DELETE'});trainingAudit('delete','Training follow-up permanently deleted','training_followup',Object.assign({id:id},current),{});tfAllData=tfAllData.filter(function(x){return x.id!==id;});toast('Deleted!');tfRender(tfAllData);}
  catch(e){toastActionError('Delete training follow-up','Training & Competency',e);}
}

// -- AUTHORISATIONS ----------------------------------------------------------
async function authLoad(){
  var el=document.getElementById('auth-table');
  if(!el)return;
  el.innerHTML='<div class="loading-msg">Loading...</div>';
  try{
    var d=await api('/authorisations?select=*'+cf()+'&order=expiry_date,person_name');
    authAllData=d||[];
    var popts='<option value="">Select person...</option>';
    (people||[]).forEach(function(p){popts+='<option value="'+p.id+'">'+p.last_name+', '+p.first_name+(p.job_title?' -- '+p.job_title:'')+'</option>';});
    var psel=document.getElementById('authr-person');if(psel)psel.innerHTML=popts;
    // Populate type filter
    var types=[...new Set(authAllData.map(function(x){return x.authorisation_type;}).filter(Boolean))];
    var typeSel=document.getElementById('auth-filter-type');
    if(typeSel)typeSel.innerHTML='<option value="">All types</option>'+types.map(function(t){return '<option value="'+escH(t)+'">'+escH(t)+'</option>';}).join('');
    // Alerts for expiring
    authShowAlerts();
    authRender(authAllData);
  }catch(e){if(el)el.innerHTML=registerErrorHtml('register',e.message);console.error(e);}
}

function authShowAlerts(){
  var alertEl=document.getElementById('auth-alerts');
  if(!alertEl)return;
  var today=new Date();
  var soon=new Date();soon.setDate(soon.getDate()+60);
  var expiring=authAllData.filter(function(x){return x.expiry_date&&new Date(x.expiry_date)<=soon&&x.status==='active';});
  var expired=authAllData.filter(function(x){return x.status==='expired'||(x.expiry_date&&new Date(x.expiry_date)<today&&x.status==='active');});
  if(!expiring.length&&!expired.length){alertEl.innerHTML='';return;}
  var h='';
  if(expired.length){
    h+='<div style="background:#FCEBEB;border:1px solid #fca5a5;border-radius:8px;padding:10px 14px;margin-bottom:8px;font-size:12px">'
      +'<strong style="color:var(--red)">'+expired.length+' expired authorisation'+(expired.length!==1?'s':'')+':</strong> '
      +expired.slice(0,5).map(function(x){return escH(x.person_name)+' ('+escH(x.authorisation_type)+')';}).join(', ')
      +'</div>';
  }
  if(expiring.filter(function(x){return new Date(x.expiry_date)>=today;}).length){
    var exp2=expiring.filter(function(x){return new Date(x.expiry_date)>=today;});
    h+='<div style="background:#FEF9EC;border:1px solid #fcd34d;border-radius:8px;padding:10px 14px;margin-bottom:8px;font-size:12px">'
      +'<strong style="color:var(--amber)">'+exp2.length+' authorisation'+(exp2.length!==1?'s':'')+' expiring within 60 days:</strong> '
      +exp2.slice(0,5).map(function(x){return escH(x.person_name)+' ('+escH(x.authorisation_type)+' - '+new Date(x.expiry_date).toLocaleDateString('en-GB')+')';}).join(', ')
      +'</div>';
  }
  alertEl.innerHTML=h;
}

function authFilter(){
  var q=(document.getElementById('auth-search')?.value||'').toLowerCase();
  var ft=document.getElementById('auth-filter-type')?.value||'';
  var filtered=authAllData.filter(function(x){
    var matchQ=!q||(x.person_name||'').toLowerCase().includes(q)||(x.authorisation_type||'').toLowerCase().includes(q);
    var matchT=!ft||x.authorisation_type===ft;
    return matchQ&&matchT;
  });
  authRender(filtered);
}

function authRender(data){
  var el=document.getElementById('auth-table');if(!el)return;
  if(!data.length){
    el.innerHTML='<div style="text-align:center;padding:40px;color:var(--text2)">No authorisations found.'+(isMgr()?' <button class="btn btn-primary btn-sm" data-auris-generated-onclick="g0321"><i class="ti ti-plus"></i>Add</button>':'')+'</div>';
    return;
  }
  var today=new Date();var soon=new Date();soon.setDate(soon.getDate()+60);
  var statusBadge=function(s,exp){
    var isExpired=exp&&new Date(exp)<today;
    var isWarn=exp&&new Date(exp)<=soon&&new Date(exp)>=today;
    if(isExpired||s==='expired')return '<span style="background:#FCEBEB;color:#A32D2D;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:600">Expired</span>';
    if(isWarn)return '<span style="background:#FEF9EC;color:#854F0B;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:600">Expiring soon</span>';
    if(s==='active')return '<span style="background:#EAF3DE;color:#3B6D11;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:600">Active</span>';
    if(s==='pending')return '<span style="background:#E6F1FB;color:#185FA5;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:600">Pending</span>';
    return '<span style="background:#f3f4f6;color:#6B7280;padding:2px 8px;border-radius:99px;font-size:11px;font-weight:600">'+s+'</span>';
  };
  // Group by person
  var byPerson={};
  data.forEach(function(x){if(!byPerson[x.person_name])byPerson[x.person_name]=[];byPerson[x.person_name].push(x);});
  var h='<div class="table-scroll"><table class="data-table" style="min-width:980px"><thead><tr>'
    +'<th>Person</th>'
    +'<th>Authorisation type</th>'
    +'<th style="width:100px">Issue date</th>'
    +'<th style="width:100px">Expiry date</th>'
    +'<th style="width:130px">Reference</th>'
    +'<th style="width:120px">Status</th>'
    +'<th style="width:70px"></th>'
    +'</tr></thead><tbody>';
  Object.entries(byPerson).forEach(function(e,pi){
    var name=e[0],auths=e[1];
    auths.forEach(function(x,ai){
      var bg=pi%2===0?'#fff':'#f9fafb';
      var iss=x.issue_date?new Date(x.issue_date).toLocaleDateString('en-GB'):'-';
      var exp=x.expiry_date?new Date(x.expiry_date).toLocaleDateString('en-GB'):'-';
      var certUrl=x.certificate_url||x.evidence_url||'';
      var refCell=certUrl
        ? '<button class="btn btn-sm" title="Preview certificate" data-url="'+escH(certUrl)+'" data-name="'+escH(x.reference||x.authorisation_type||'Authorisation certificate')+'" data-auris-generated-onclick="g0318"><i class="ti ti-eye"></i> '+escH(x.reference||'Evidence')+'</button>'
        : escH(x.reference||'-');
      var isExpiredOrWarn=x.expiry_date&&(new Date(x.expiry_date)<today||new Date(x.expiry_date)<=soon);
      h+='<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
        +(ai===0?'<td rowspan="'+auths.length+'" style="padding:8px 12px;font-weight:700;border-right:1px solid #e5e7eb;vertical-align:top">'+escH(name)+'</td>':'')
        +'<td style="padding:8px 10px;font-weight:600">'+escH(x.authorisation_type||'-')+'</td>'
        +'<td style="padding:8px 10px">'+iss+'</td>'
        +'<td style="padding:8px 10px'+(isExpiredOrWarn?';color:var(--red)':'')+'">'+exp+(isExpiredOrWarn?' ?':'')+'</td>'
        +'<td style="padding:8px 10px;font-size:11px">'+refCell+(x.scope||x.restrictions?'<div class="muted">'+escH(x.scope||x.restrictions)+'</div>':'')+'</td>'
        +'<td style="padding:8px 10px">'+statusBadge(x.status,x.expiry_date)+'</td>'
        +'<td style="padding:8px 10px"><div style="display:flex;gap:4px">'
        +'<button class="btn btn-sm" data-id="'+x.id+'" data-auris-generated-onclick="g0322"><i class="ti ti-edit"></i></button>'
        +(isMgr()?'<button class="btn btn-sm" style="color:var(--red)" data-id="'+x.id+'" data-auris-generated-onclick="g0323"><i class="ti ti-trash"></i></button>':'')
        +'</div></td>'
        +'</tr>';
    });
  });
  h+='</tbody></table></div>';
  el.innerHTML=h;
}

function authShowForm(){
  document.getElementById('train-view-auth').style.display='none';
  document.getElementById('auth-form').style.display='block';
}
function authBack(){
  document.getElementById('auth-form').style.display='none';
  document.getElementById('train-view-auth').style.display='block';
  authLoad();
}

function authNew(){
  authEditingId=null;
  document.getElementById('auth-form3title').textContent='New Authorisation';
  document.getElementById('auth-del-btn').style.display='none';
  ['authr-name','authr-type','authr-ref','authr-cert-url','authr-scope','authr-issuer','authr-notes'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var popts='<option value="">Select person...</option>';
  (people||[]).forEach(function(p){popts+='<option value="'+p.id+'">'+p.last_name+', '+p.first_name+(p.job_title?' -- '+p.job_title:'')+'</option>';});
  var psel=document.getElementById('authr-person');if(psel)psel.innerHTML=popts;
  ['authr-dept','authr-job-title'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['authr-issue','authr-expiry'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  var st=document.getElementById('authr-status');if(st)st.value='active';
  var per=document.getElementById('authr-person');if(per)per.value='';
  authShowForm();
}

function authOpen(id){
  var x=authAllData.find(function(r){return r.id===id;});
  if(!x)return;
  authEditingId=id;
  document.getElementById('auth-form3title').textContent='Edit Authorisation';
  document.getElementById('auth-del-btn').style.display=isMgr()?'inline-flex':'none';
  var flds={'authr-name':'person_name','authr-type':'authorisation_type','authr-ref':'reference','authr-cert-url':'certificate_url','authr-scope':'scope','authr-issuer':'issuing_body','authr-notes':'notes'};
  Object.entries(flds).forEach(function(e){var el=document.getElementById(e[0]);if(el)el.value=x[e[1]]||'';});
  var certUrl=document.getElementById('authr-cert-url');if(certUrl)certUrl.value=x.certificate_url||x.evidence_url||'';
  var scope=document.getElementById('authr-scope');if(scope)scope.value=x.scope||x.restrictions||'';
  var popts='<option value="">Select person...</option>';
  (people||[]).forEach(function(p){popts+='<option value="'+p.id+'">'+p.last_name+', '+p.first_name+(p.job_title?' -- '+p.job_title:'')+'</option>';});
  var psel=document.getElementById('authr-person');if(psel)psel.innerHTML=popts;
  var p=(people||[]).find(function(p){return p.id===x.person_id||personFullName(p)===x.person_name;});
  if(p){var dept=document.getElementById('authr-dept');if(dept)dept.value=p.department||'';var title=document.getElementById('authr-job-title');if(title)title.value=p.job_title||'';}
  var iss=document.getElementById('authr-issue');if(iss)iss.value=x.issue_date||'';
  var exp=document.getElementById('authr-expiry');if(exp)exp.value=x.expiry_date||'';
  var st=document.getElementById('authr-status');if(st)st.value=x.status||'active';
  var per=document.getElementById('authr-person');if(per)per.value=x.person_id||p?.id||'';
  authShowForm();
}

async function authSave(){
  var type=obNormText(document.getElementById('authr-type')?.value);
  var name=obNormText(document.getElementById('authr-name')?.value);
  if(!type||!name){toast('Please enter person name and authorisation type',false);return;}
  var g=function(id){var el=document.getElementById(id);return el?obNormText(el.value)||null:null;};
  var issue=g('authr-issue'), expiry=g('authr-expiry'), status=g('authr-status')||'active';
  if(issue&&expiry&&expiry<issue){toast('Expiry date cannot be before issue date',false);return;}
  if(expiry&&new Date(expiry)<new Date()&&status==='active')status='expired';
  var body={
    company_id:ccid(),
    person_id:g('authr-person')||null,person_name:name,
    authorisation_type:type,status:status,
    issue_date:issue,expiry_date:expiry,
    reference:g('authr-ref'),certificate_url:g('authr-cert-url'),evidence_url:g('authr-cert-url'),
    scope:g('authr-scope'),restrictions:g('authr-scope'),
    issuing_body:g('authr-issuer'),notes:g('authr-notes'),
    updated_at:new Date().toISOString()
  };
  try{
    if(authEditingId){
      var current=authAllData.find(function(x){return x.id===authEditingId;})||{};
      await trainingSaveWithFallback('/authorisations?id=eq.'+authEditingId,{m:'PATCH',p:'return=minimal',b:body},body,['certificate_url','evidence_url','scope','restrictions']);
      trainingAudit('update','Training authorisation updated','authorisations',Object.assign({},current,body,{id:authEditingId}),{old_status:current.status||null,new_status:body.status||null});
      toast('Updated!');
    }
    else{
      body.created_by=prof?.id;
      var created=await trainingSaveWithFallback('/authorisations',{m:'POST',p:'return=representation',b:body},body,['certificate_url','evidence_url','scope','restrictions']);
      trainingAudit('create','Training authorisation added','authorisations',created?.[0]||body,{expiry_date:body.expiry_date});
      toast('Authorisation added!');
    }
    authBack();
  }catch(e){toastActionError('Save training authorisation','Training & Competency',e);console.error(e);}
}

async function authDelete(){
  if(!authEditingId)return;
  if(!(await appConfirmAction({title:'Expire authorisation',message:'Mark this authorisation as expired?',detail:'The record is kept for evidence and audit history.',confirmText:'Expire',cancelText:'Back'})))return;
  try{var current=authAllData.find(function(x){return x.id===authEditingId;})||{id:authEditingId};await api('/authorisations?id=eq.'+authEditingId,{m:'PATCH',p:'return=minimal',b:{status:'expired',updated_at:new Date().toISOString()}});trainingAudit('expire','Training authorisation expired','authorisations',Object.assign({},current,{status:'expired'}),{old_status:current.status||null,new_status:'expired'});toast('Authorisation expired');authBack();}
  catch(e){toastActionError('Delete training authorisation','Training & Competency',e);}
}

async function authDeleteFromList(id){
  if(!(await appConfirmAction({title:'Expire authorisation',message:'Mark this authorisation as expired?',detail:'The record is kept for evidence and audit history.',confirmText:'Expire',cancelText:'Back'})))return;
  try{var current=authAllData.find(function(x){return x.id===id;})||{id:id};await api('/authorisations?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{status:'expired',updated_at:new Date().toISOString()}});trainingAudit('expire','Training authorisation expired','authorisations',Object.assign({},current,{status:'expired'}),{old_status:current.status||null,new_status:'expired'});toast('Authorisation expired');authLoad();}
  catch(e){toastActionError('Delete training authorisation','Training & Competency',e);}
}

