// ===== AUDIT_JS.JS =====
// ===================================================================
// AUDIT & INSPECTION MANAGEMENT - Complete JS
// Inspections - Audits - Pre-Start - Findings - Mobile features
// ===================================================================

let auditAllData=[], auditEditId=null, auditCurrentTab='all';
let auditTemplates=[], auditFindingsData=[];

const AUDIT_TYPE_CFG = {
  workplace:       {emoji:'*',label:'Workplace Inspection',      color:'#1e40af',bg:'#EFF6FF', border:'#bfdbfe'},
  behavioral:      {emoji:'*', label:'Behavioral Safety Obs.',    color:'#5B21B6',bg:'#F5F3FF', border:'#ddd6fe'},
  equipment:       {emoji:'*', label:'Equipment Inspection',      color:'#9A3412',bg:'#FFF7ED', border:'#fed7aa'},
  ppe:             {emoji:'*',label:'PPE Inspection',             color:'#065F46',bg:'#ECFDF5', border:'#a7f3d0'},
  fire:            {emoji:'*',label:'Fire Safety Inspection',     color:'#991B1B',bg:'#FEF2F2', border:'#fecaca'},
  environmental:   {emoji:'*',label:'Environmental Inspection',   color:'#065F46',bg:'#ECFDF5', border:'#a7f3d0'},
  iso_audit:       {emoji:'*',label:'ISO Audit',                  color:'#374151',bg:'#f9fafb', border:'#e5e7eb'},
  internal_audit:  {emoji:'*',label:'Internal Audit',             color:'#1e40af',bg:'#EFF6FF', border:'#bfdbfe'},
  supplier_audit:  {emoji:'*',label:'Supplier Audit',             color:'#854F0B',bg:'#FFFBEB', border:'#fcd34d'},
  contractor_audit:{emoji:'*',label:'Contractor Audit',           color:'#9A3412',bg:'#FFF7ED', border:'#fed7aa'},
  regulatory:      {emoji:'*', label:'Regulatory Inspection',     color:'#991B1B',bg:'#FEF2F2', border:'#fecaca'},
  prestart:        {emoji:'*',label:'Pre-Start Inspection',       color:'#065F46',bg:'#ECFDF5', border:'#a7f3d0'},
};

// -- Entry point ----------------------------------------------------
function loadInsps() {
  // Expose ps-add-btn based on role
  var psBtn = document.getElementById('ps-add-btn');
  if(psBtn) psBtn.style.display = isMgr()?'inline-flex':'none';
  auditSwitchTab('all', document.getElementById('insp-tab-all'));
  auditLoadTemplates();
  auditWatchOffline();
}

function inspSwitchTab(tab, btn) {
  // Backward compat alias
  if(tab==='site') auditSwitchTab('workplace', document.getElementById('insp-tab-workplace'));
  else if(tab==='prestart') auditSwitchTab('prestart', document.getElementById('insp-tab-prestart'));
  else auditSwitchTab(tab, btn);
}

function auditTypeForTab(tab) {
  if(tab === 'audit') return 'internal_audit';
  if(['workplace','behavioral','equipment','ppe','fire','environmental'].includes(tab)) return tab;
  return 'workplace';
}

function auditStartFromCurrentTab() {
  var tab = auditCurrentTab || 'all';
  if(tab === 'prestart') { psNew(); return; }
  if(tab === 'findings') { toast('Use an inspection record to add findings', false); return; }
  auditNew(auditTypeForTab(tab));
}

function auditStartButtonLabel(tab) {
  var labels = {
    all: 'New inspection',
    workplace: 'Start workplace inspection',
    behavioral: 'Start behavioural inspection',
    equipment: 'Start equipment inspection',
    ppe: 'Start PPE inspection',
    fire: 'Start fire inspection',
    environmental: 'Start environmental inspection',
    audit: 'Start audit',
    prestart: 'New pre-start check'
  };
  return labels[tab] || 'New inspection';
}

function auditSwitchTab(tab, btn) {
  auditCurrentTab = tab;
  document.querySelectorAll('[id^="insp-tab-"]').forEach(function(t){t.classList.remove('active');});
  if(btn) btn.classList.add('active');
  // Show/hide views
  document.getElementById('audit-view-register').style.display  = tab==='findings'||tab==='prestart' ? 'none' : 'block';
  document.getElementById('audit-view-prestart').style.display  = tab==='prestart' ? 'block' : 'none';
  document.getElementById('audit-view-findings').style.display  = tab==='findings' ? 'block' : 'none';
  document.getElementById('audit-form3view').style.display      = 'none';
  // Update filter label
  var cfg = AUDIT_TYPE_CFG[tab];
  var labelEl = document.getElementById('audit-filter-label');
  if(labelEl) labelEl.textContent = cfg ? cfg.emoji+' '+cfg.label : '';
  // Update type filter
  var typeFilter = document.getElementById('audit-filter-type');
  if(typeFilter && ['workplace','behavioral','equipment','ppe','fire','environmental'].includes(tab)) typeFilter.value = tab;
  else if(typeFilter) typeFilter.value = '';
  // Update new button label
  var newBtn = document.getElementById('insp-new-btn');
  if(newBtn) {
    newBtn.style.display = tab === 'findings' ? 'none' : 'inline-flex';
    newBtn.innerHTML = '<i class="ti ti-plus"></i>'+auditStartButtonLabel(tab);
  }
  // Load content
  if(tab === 'prestart') { psLoad(); return; }
  if(tab === 'findings') { findingsLoad(); return; }
  auditLoad(tab === 'audit' ? ['iso_audit','internal_audit','supplier_audit','contractor_audit','regulatory'] : (tab==='all'?null:[tab]));
}

// -- Load inspection register --------------------------------------
async function auditLoad(typeFilter) {
  var el = document.getElementById('audit-register-list'); if(!el) return;
  el.innerHTML = '<div class="loading-msg">Loading...</div>';
  try {
    var q = '/inspections?select=*'+cf()+'&order=inspection_date.desc,created_at.desc';
    var d = await api(q);
    auditAllData = d||[];
    var now = new Date(); var m = now.getMonth(); var y = now.getFullYear();
    // Metrics
    function sm(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}
    sm('audit-m3total', auditAllData.length);
    sm('audit-m3done', auditAllData.filter(function(x){return x.status==='completed'||x.status==='closed';}).length);
    sm('audit-m3overdue', auditAllData.filter(function(x){
      return x.status!=='closed'&&x.status!=='completed'&&x.planned_date&&new Date(x.planned_date)<now;
    }).length);
    // Apply filter and render
    auditFilter();
  } catch(e) {
    el.innerHTML = '<div style="padding:20px;color:var(--text2);text-align:center">'+escH(e.message)+'</div>';
  }
  // Load findings count separately
  try {
    var findings = await api('/audit_findings?select=id,finding_type,status'+cf());
    var fEl = document.getElementById('audit-m3findings');
    if(fEl) fEl.textContent = (findings||[]).filter(function(x){return x.status==='open';}).length;
    var mEl = document.getElementById('audit-m3major');
    if(mEl) mEl.textContent = (findings||[]).filter(function(x){return x.finding_type==='major_nc';}).length;
    // avg score
    var scored = auditAllData.filter(function(x){return x.score_good>=0&&(x.score_good+x.score_insuf)>0;});
    var avgScore = scored.length>0 ? Math.round(scored.reduce(function(s,x){return s+(x.score_good/(x.score_good+x.score_insuf)*100);},0)/scored.length) : null;
    var sEl = document.getElementById('audit-m3score');
    if(sEl) sEl.textContent = avgScore!=null ? avgScore+'%' : '-';
  } catch(ex) {}
}

function auditFilter() {
  var el = document.getElementById('audit-register-list'); if(!el) return;
  var q = (document.getElementById('audit-search')?.value||'').toLowerCase();
  var ft = document.getElementById('audit-filter-type')?.value||'';
  var fs = document.getElementById('audit-filter-status')?.value||'';
  var filt = (auditAllData||[]).filter(function(x) {
    var mQ = !q || (x.site||'').toLowerCase().includes(q) || (x.inspection_type||'').toLowerCase().includes(q) ||
              (x.reference_no||x.id||'').toLowerCase().includes(q) || (x.inspector||x.by||x.if_by||'').toLowerCase().includes(q);
    var activeTypes = auditCurrentTab==='audit' ? ['iso_audit','internal_audit','supplier_audit','contractor_audit','regulatory'] : null;
    var mT = (!ft || (x.inspection_type||'workplace') === ft) && (!activeTypes || activeTypes.includes(x.inspection_type||'workplace'));
    var mS = !fs || x.status === fs;
    return mQ && mT && mS;
  });
  if(!filt.length) {
    el.innerHTML = '<div style="text-align:center;padding:48px;color:var(--text2)"><div style="font-size:44px;margin-bottom:12px">-</div><div style="font-weight:700;font-size:14px;margin-bottom:8px">No inspections found</div><button class="btn btn-primary" data-auris-generated-onclick="g0324"><i class="ti ti-plus"></i>Start inspection</button></div>';
    return;
  }
  var h = '<div class="table-scroll"><table class="data-table" style="min-width:1060px">'
    + '<thead><tr>'
    + '<th>Ref</th>'
    + '<th>Type</th>'
    + '<th>Site / Department</th>'
    + '<th>Date</th>'
    + '<th>Inspector</th>'
    + '<th>Standard</th>'
    + '<th style="text-align:center">Score</th>'
    + '<th style="text-align:center">Status</th>'
    + '<th style="text-align:center">Action</th>'
    + '</tr></thead><tbody>';
  filt.forEach(function(x) {
    var type = x.inspection_type || 'workplace';
    var cfg = AUDIT_TYPE_CFG[type] || AUDIT_TYPE_CFG.workplace;
    var score = (x.score_good!=null&&(x.score_good+x.score_insuf)>0) ? Math.round(x.score_good/(x.score_good+x.score_insuf)*100) : null;
    var scoreColor = score==null?'#6B7280':score>=80?'#1D9E75':score>=60?'#EF9F27':'#DC2626';
    var stCfg = {open:['#FCEBEB','#A32D2D'],in_progress:['#EFF6FF','#185FA5'],completed:['#EAF3DE','#3B6D11'],closed:['#EAF3DE','#3B6D11'],archived:['#f3f4f6','#6B7280']};
    var sc = stCfg[x.status||'open']||stCfg.open;
    var isOverdue = x.status!=='closed'&&x.status!=='completed'&&x.planned_date&&new Date(x.planned_date)<new Date();
    var ref = displayRecordRef(x,'reference_no','INSP-DRAFT');
    h += '<tr style="border-bottom:1px solid var(--border);border-left:5px solid '+cfg.border+';cursor:pointer" data-id="'+x.id+'" data-auris-generated-onclick="g0325">'
      + '<td style="padding:10px;font-family:monospace;font-weight:800;color:'+cfg.color+'">'+escH(ref)+'</td>'
      + '<td style="padding:10px"><span style="background:'+cfg.bg+';color:'+cfg.color+';padding:3px 8px;border-radius:99px;font-size:10px;font-weight:700;border:1px solid '+cfg.border+'">'+escH(cfg.label)+'</span></td>'
      + '<td style="padding:10px;font-weight:600">'+escH(x.site||x.if_site||'-')+(x.department?' <span style="color:var(--text2);font-weight:500">/ '+escH(x.department)+'</span>':'')+(isOverdue?' <span style="background:#FCEBEB;color:#DC2626;padding:1px 6px;border-radius:4px;font-size:9px;font-weight:700">OVERDUE</span>':'')+'</td>'
      + '<td style="padding:10px;color:var(--text2)">'+escH((x.inspection_date||x.if_date)?new Date(x.inspection_date||x.if_date).toLocaleDateString('en-GB'):'-')+'</td>'
      + '<td style="padding:10px;color:var(--text2)">'+escH(x.inspector||x.by||x.if_by||'-')+'</td>'
      + '<td style="padding:10px;color:var(--text2)">'+escH(x.audit_standard||'-')+'</td>'
      + '<td style="padding:10px;text-align:center;font-weight:800;color:'+scoreColor+'">'+(score!=null?score+'%':'-')+'</td>'
      + '<td style="padding:10px;text-align:center"><span style="background:'+sc[0]+';color:'+sc[1]+';padding:3px 8px;border-radius:99px;font-size:10px;font-weight:700;text-transform:capitalize">'+escH(x.status||'open')+'</span></td>'
      + '<td style="padding:10px;text-align:center"><button class="btn btn-sm" data-auris-runtime-onclick="r0102" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id]))+'"><i class="ti ti-edit"></i></button></td>'
      + '</tr>';
  });
  el.innerHTML = h + '</tbody></table></div>';
}
