function auditNew(preType) {
  auditEditId = null;
  var type = preType || 'workplace';
  auditSelectType(type,{skipTemplate:true});
  document.getElementById('audit-form3title').textContent = 'New Inspection';
  document.getElementById('audit-form3ref').textContent = 'REF-AUTO';
  document.getElementById('audit-delete-btn').style.display = 'none';
  document.getElementById('audit-form3view').style.display = 'block';
  document.getElementById('audit-view-register').style.display = 'none';
  document.getElementById('audit-view-prestart').style.display = 'none';
  document.getElementById('audit-view-findings').style.display = 'none';
  // Clear form
  ['if-site','if-by','if-pos','if-neg','if-sign-inspector','if-sign-reviewer',
   'audit-dept','audit-scope','audit-lead-auditor','audit-team','audit-auditee',
   'audit-gps-address','audit-lat','audit-lng'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  ['if-by','if-sign-inspector','if-sign-reviewer'].forEach(function(id){fillPersonSelect(id);});
  ['if-date','if-sign-date','if-sign-reviewer-date'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  document.getElementById('if-date').value = new Date().toISOString().slice(0,10);
  document.getElementById('audit-priority').value = 'medium';
  document.getElementById('audit-status').value = 'open';
  document.getElementById('if-checklist').innerHTML = '';
  document.getElementById('audit-photos-list').innerHTML = '';
  document.getElementById('if-actions-body').innerHTML = '';
  document.getElementById('if-actions-empty').style.display = 'block';
  document.getElementById('if-score').textContent = '0 Good / 0 Insufficient';
  document.getElementById('audit-score-display').textContent = '-';
  document.getElementById('audit-score-detail').textContent = '';
  document.getElementById('audit-score-bar').style.width = '0%';
  // Load template for type
  auditAutoLoadTemplate(type);
}

function auditOpen(id) {
  var x = auditAllData.find(function(r){return r.id===id;}); if(!x) return;
  auditEditId = id;
  var type = x.inspection_type || 'workplace';
  auditSelectType(type,{skipTemplate:true});
  document.getElementById('audit-form3title').textContent = x.site || 'Edit Inspection';
  document.getElementById('audit-form3ref').textContent = x.reference_no || '-';
  document.getElementById('audit-delete-btn').style.display = isMgr()?'inline-flex':'none';
  document.getElementById('audit-form3view').style.display = 'block';
  document.getElementById('audit-view-register').style.display = 'none';
  document.getElementById('audit-view-prestart').style.display = 'none';
  var gf=function(fid,val){var el=document.getElementById(fid);if(el)el.value=val||'';};
  gf('if-site',x.site||x.if_site); fillPersonSelect('if-by',x.inspector||x.by||x.if_by);
  gf('if-date',x.inspection_date||x.if_date); gf('if-pos',x.positive_obs||x.if_pos);
  gf('if-neg',x.negative_obs||x.if_neg); fillPersonSelect('if-sign-inspector',x.sign_inspector);
  gf('if-sign-date',x.sign_date); fillPersonSelect('if-sign-reviewer',x.sign_reviewer);
  gf('if-sign-reviewer-date',x.sign_reviewer_date); gf('audit-dept',x.department);
  gf('audit-scope',x.audit_scope); gf('audit-lead-auditor',x.lead_auditor);
  gf('audit-team',x.audit_team); gf('audit-auditee',x.auditee);
  gf('audit-gps-address',x.gps_address); gf('audit-lat',x.lat); gf('audit-lng',x.lng);
  if(document.getElementById('audit-standard')&&x.audit_standard) document.getElementById('audit-standard').value=x.audit_standard;
  document.getElementById('audit-priority').value = x.priority||'medium';
  document.getElementById('audit-status').value = x.status||'open';
  // Rebuild checklist from saved items
  if(x.items){
    window.chkItems=(x.items||[]).map(function(i){return{ca:i.category||'',item:i.item||i.item_name||'',guidance:i.guidance||''};});
    buildChecklist(x.items);
  }
  else auditAutoLoadTemplate(type);
  // Photos
  var photosEl = document.getElementById('audit-photos-list');
  if(photosEl) {
    photosEl.innerHTML = '';
    var photos = Array.isArray(x.photos)?x.photos:[];
    photos.forEach(function(url){auditAddPhotoRow(url);});
  }
  // Actions
  var actBody = document.getElementById('if-actions-body');
  if(actBody) {
    actBody.innerHTML = '';
    (x.action_items||[]).forEach(function(a){actBody.insertAdjacentHTML('beforeend',inspActionRowHTML(a));});
    document.getElementById('if-actions-empty').style.display = (x.action_items||[]).length?'none':'block';
  }
  updateScore();
}

// -- Select type and configure form --------------------------------
function auditSelectType(type, opts) {
  opts = opts || {};
  document.getElementById('audit-type').value = type;
  var cfg = AUDIT_TYPE_CFG[type] || AUDIT_TYPE_CFG.workplace;
  var banner = document.getElementById('audit-form3banner');
  if(banner) banner.style.background = 'linear-gradient(135deg,'+cfg.color+'cc,'+cfg.color+')';
  document.getElementById('audit-form3type-label').textContent = cfg.label;
  // Style type buttons
  document.querySelectorAll('.audit-type-btn').forEach(function(b) {
    var t=b.dataset.type; var bc=AUDIT_TYPE_CFG[t]||{};
    if(t===type){b.style.borderColor=bc.color||cfg.color;b.style.transform='scale(1.05)';b.style.boxShadow='0 2px 10px '+(bc.color||cfg.color)+'40';}
    else{b.style.borderColor='';b.style.transform='';b.style.boxShadow='';}
  });
  // Show/hide audit-specific fields
  var auditTypes = ['iso_audit','internal_audit','supplier_audit','contractor_audit','regulatory'];
  var stdRow = document.getElementById('audit-standard-row');
  var findSec = document.getElementById('audit-findings-section');
  if(stdRow) stdRow.style.display = auditTypes.includes(type)?'block':'none';
  if(findSec) findSec.style.display = auditTypes.includes(type)?'block':'none';
  if(!opts.skipTemplate && document.getElementById('audit-form3view')?.style.display !== 'none') {
    auditAutoLoadTemplate(type);
  }
}

// -- Templates ------------------------------------------------------
function auditBuiltinTemplateOptions(){
  return [
    ['workplace','AURIS360 Workplace Inspection'],
    ['behavioral','AURIS360 Behavioural Safety Inspection'],
    ['equipment','AURIS360 Equipment Inspection'],
    ['ppe','AURIS360 PPE Inspection'],
    ['fire','AURIS360 Fire Safety Inspection'],
    ['environmental','AURIS360 Environmental Inspection'],
    ['iso_audit','AURIS360 ISO 45001 Audit'],
    ['internal_audit','AURIS360 Internal Audit'],
    ['supplier_audit','AURIS360 Supplier Audit'],
    ['contractor_audit','AURIS360 Contractor Audit'],
    ['regulatory','AURIS360 Regulatory Audit']
  ].map(function(x){return '<option value="__builtin__:'+x[0]+'">'+x[1]+'</option>';}).join('');
}
async function auditLoadTemplates() {
  try {
    var d = await api('/checklist_templates?select=*'+cf()+'&order=template_name');
    auditTemplates = d||[];
    // Also check for default templates seeded in DB
    var sel = document.getElementById('audit-template-select');
    if(sel) {
      sel.innerHTML = '<option value="">Load template...</option>'+auditBuiltinTemplateOptions()
        + (auditTemplates||[]).map(function(t){return '<option value="'+t.id+'">'+escH(t.template_name)+'</option>';}).join('');
    }
  } catch(e) {
    // Use built-in default templates if DB not available
    auditTemplates = [];
    var sel = document.getElementById('audit-template-select');
    if(sel) sel.innerHTML = '<option value="">Load template...</option>'+auditBuiltinTemplateOptions();
  }
}

async function auditLoadTemplate() {
  var sel = document.getElementById('audit-template-select');
  if(!sel||!sel.value) return;
  if(sel.value.indexOf('__builtin__:')===0){
    var builtinType=sel.value.split(':')[1]||'workplace';
    var fallback=AUDIT_DEFAULT_CHECKLISTS[builtinType]||AUDIT_DEFAULT_CHECKLISTS.workplace;
    window.chkItems=fallback;
    buildChecklist([]);
    toast('Template loaded');
    return;
  }
  var tmpl = auditTemplates.find(function(t){return t.id===sel.value;});
  if(!tmpl) return;
  var items = typeof tmpl.items==='string'?JSON.parse(tmpl.items):(tmpl.items||[]);
  // Convert to chkItems format
  window.chkItems = items.map(function(item){return{ca:item.category||'',item:item.item||item.item_name||'',guidance:item.guidance||''};});
  buildChecklist([]);
  toast('Template loaded: '+tmpl.template_name);
}

async function auditAutoLoadTemplate(type) {
  // Try to load the default template for this type
  try {
    if(AUDIT_DEFAULT_CHECKLISTS[type]) {
      window.chkItems = AUDIT_DEFAULT_CHECKLISTS[type];
      buildChecklist([]);
      var sel=document.getElementById('audit-template-select'); if(sel)sel.value='__builtin__:'+type;
      return;
    }
    var templates = auditTemplates.filter(function(t){return t.inspection_type===type&&t.is_default;});
    if(!templates.length && auditTemplates.length===0) {
      // Load from DB
      var d = await api('/checklist_templates?select=*'+cf()+'&inspection_type=eq.'+type+'&is_default=eq.true&limit=1');
      templates = d||[];
    }
    if(templates[0]) {
      var items = typeof templates[0].items==='string'?JSON.parse(templates[0].items):(templates[0].items||[]);
      window.chkItems = items.map(function(item){return{ca:item.category||'',item:item.item||item.item_name||'',guidance:item.guidance||''};});
      buildChecklist([]);
    } else {
      // Use built-in fallback
      var fallback = AUDIT_DEFAULT_CHECKLISTS[type];
      if(fallback) {
        window.chkItems = fallback;
        buildChecklist([]);
      }
    }
  } catch(e) {
    var fallback = AUDIT_DEFAULT_CHECKLISTS[type];
    if(fallback) { window.chkItems = fallback; buildChecklist([]); }
  }
}

