// -- Role helper (extend existing RL) --------------------------------
// Map new roles to numeric levels for isMgr()/isAdm() checks
function getRoleLevel(role) {
  var rlMap = {
    sephs_admin:4, admin:4, hse_manager:4, hse_officer:4, manager:4,
    site_manager:3, auditor:3, hr:3,
    supervisor:2, inspector:2,
    employee:1, contractor:1, executive:1
  };
  return rlMap[role]||0;
}

function canAccess(minRole) {
  if(!prof) return false;
  var userLevel = getRoleLevel(prof.role||'employee');
  var minLevel = getRoleLevel(minRole);
  return userLevel >= minLevel;
}

