let usersAllData = [];

function usersCanEditUser(u){
if(!u||!isMgr())return false;
if(!isSA()&&u.role==='sephs_admin')return false;
if(!isSA()&&prof?.company_id&&u.company_id&&u.company_id!==prof.company_id)return false;
return true;
}

function usersCanAdminUser(u){
if(!u||!isAdm())return false;
if(u.id===prof?.id)return false;
if(!isSA()&&u.role==='sephs_admin')return false;
if(!isSA()&&prof?.company_id&&u.company_id&&u.company_id!==prof.company_id)return false;
return true;
}

function usersCanResetPassword(u){
if(!u)return false;
if(u.id===prof?.id)return usersCanEditUser(u);
if(usersCanAdminUser(u))return true;
var role=typeof activeRole==='function'?activeRole():(prof?.role||'');
if(role==='hse_manager'&&usersCanEditUser(u))return true;
return false;
}

function usersRoleChangeAllowed(target,newRole){
if(!target)return false;
if(target.id===prof?.id&&newRole!==target.role)return false;
if(!isAdm()&&newRole!==target.role)return false;
if(!isSA()&&newRole==='sephs_admin')return false;
return true;
}

