// -- Load users -------------------------------------------------------
async function usersLoad() {
  var el = document.getElementById('users-list'); if(!el) return;
  el.innerHTML = '<div class="loading-msg">Loading users...</div>';
  try {
    var filter = prof?.company_id&&!isSA() ? '&company_id=eq.'+prof.company_id : '';
    var d = await api('/profiles?select=*,companies(name)'+filter+'&order=full_name');
    usersAllData = d||[];
    // Metrics
    function sm(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}
    sm('um3total', usersAllData.length);
    sm('um3active', usersAllData.filter(function(u){return u.status!=='inactive';}).length);
    var mgrs = usersAllData.filter(function(u){return ['hse_manager','site_manager','manager','supervisor','admin','sephs_admin'].includes(u.role);});
    sm('um3managers', mgrs.length);
    sm('um3contractors', usersAllData.filter(function(u){return u.role==='contractor';}).length);
    sm('um3pending', 0); // will update from invites if tracked
    usersFilter();
  } catch(e) {
    el.innerHTML = '<div style="padding:20px;color:var(--text2);text-align:center">'+escH(e.message)+'</div>';
  }
}

function usersFilter() {
  var el = document.getElementById('users-list'); if(!el) return;
  var q  = (document.getElementById('users-search')?.value||'').toLowerCase();
  var fr = document.getElementById('users-filter-role')?.value||'';
  var fs = document.getElementById('users-filter-status')?.value||'';
  var filt = usersAllData.filter(function(u) {
    var mQ = !q || (u.full_name||'').toLowerCase().includes(q) ||
              (u.email||'').toLowerCase().includes(q) ||
              (u.department||'').toLowerCase().includes(q) ||
              (u.companies?.name||'').toLowerCase().includes(q);
    var mR = !fr || u.role===fr;
    var mS = !fs || (fs==='active' ? u.status!=='inactive' : u.status==='inactive');
    return mQ && mR && mS;
  });
  var countEl = document.getElementById('users-count-label');
  if(countEl) countEl.textContent = filt.length+' user'+(filt.length!==1?'s':'');
  usersRender(filt);
}

function usersFmtLastLogin(ts){
  if(!ts) return 'Never';
  var d=new Date(ts), now=new Date(), diff=(now-d)/1000;
  if(diff<60) return 'Just now';
  if(diff<3600) return Math.floor(diff/60)+' min ago';
  if(diff<86400) return Math.floor(diff/3600)+'h ago';
  if(diff<604800) return Math.floor(diff/86400)+'d ago';
  return d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
}
function isDeliverableEmail(email){
  var v=String(email||'').trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)&&!v.endsWith('.local');
}
function usersIsGeneratedLogin(u){
  return !!(u && (u.synthetic_email || String(u.email||'').trim().toLowerCase().endsWith('.local')));
}
function notificationRecipientIssue(email){
  var v=String(email||'').trim();
  if(!v)return 'Missing recipient email address. Add a real email address or use a future WhatsApp/SMS contact.';
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))return 'Invalid recipient email address. Check the user profile or notification setting.';
  if(v.toLowerCase().endsWith('.local'))return 'Login-only address. This user needs a real notification email, or a future WhatsApp/SMS contact.';
  return '';
}
var notificationQueueRows=[];
var NOTIFICATION_RELATION_MODULES={
  safety_observations:'observation',events:'events',investigations:'events',risk_assessments:'risk',permits:'permit',documents:'documents',
  action_tracker:'actions',training_followup:'training',training_sessions:'training',training_records:'training',elearning_enrolments:'training',
  elearning_courses:'training',companies:'admin'
};
function notificationRelationship(payload){
  payload=payload||{};var table=String(payload.related_table||'').trim();
  var metadata=payload.metadata&&typeof payload.metadata==='object'?payload.metadata:{};
  var saved=metadata.relationship&&typeof metadata.relationship==='object'?metadata.relationship:{};
  return {module:String(payload.related_module||saved.module||NOTIFICATION_RELATION_MODULES[table]||'').trim(),table:table||String(saved.table||'').trim(),
    id:String(payload.related_id||saved.id||'').trim(),ref:String(payload.related_ref||saved.ref||'').trim(),company_id:String(payload.company_id||saved.company_id||'').trim(),url:String(payload.record_url||saved.url||'').trim()};
}
function notificationRecordUrl(rel){
  if(!rel||!rel.module)return '';
  try{
    var origin=window.location&&/^https?:/.test(window.location.origin||'')&&!/localhost|127\.0\.0\.1/.test(window.location.hostname||'')?window.location.origin:'https://auris360.app';
    var url=new URL(origin+(window.location&&window.location.pathname&&window.location.pathname!=='/'?window.location.pathname:'/'));
    url.searchParams.set('goto',rel.module);if(rel.id)url.searchParams.set('record',rel.id);if(rel.ref)url.searchParams.set('ref',rel.ref);
    if(rel.table)url.searchParams.set('table',rel.table);if(rel.company_id)url.searchParams.set('company',rel.company_id);return url.toString();
  }catch(_){return '';}
}
function notificationLinkBody(html,url){
  if(!url)return String(html||'');var safe=String(url).replace(/&/g,'&amp;').replace(/"/g,'&quot;');var content=String(html||'');
  var replaced=false;content=content.replace(/href="https:\/\/(?:auris360\.app|app\.auris360\.com|auris-360\.vercel\.app)[^"]*"/g,function(){replaced=true;return 'href="'+safe+'"';});
  if(replaced)return content;
  var link='<div style="margin:18px 0;text-align:center"><a href="'+safe+'" style="display:inline-block;background:#1D9E75;color:#fff;padding:11px 22px;border-radius:8px;text-decoration:none;font-weight:700">Open exact record in AURIS360</a></div>';
  return content.indexOf('</body>')>=0?content.replace('</body>',link+'</body>'):content+link;
}
async function notificationLogEvent(row,eventType,detail){
  var rel=notificationRelationship(row);if(!row?.id||!row?.company_id)return false;
  try{await api('/notification_events',{m:'POST',p:'return=minimal',b:{company_id:row.company_id,notification_id:row.id,event_type:eventType,related_module:rel.module||null,related_table:rel.table||null,related_id:rel.id||null,related_ref:rel.ref||null,actor_id:prof?.id||null,detail:detail||{}}});return true;}catch(_){return false;}
}
async function queueNotification(payload){
  var body=Object.assign({status:'pending'}, payload||{});
  var rel=notificationRelationship(body),exempt=['test_email','system'].includes(String(body.type||''));
  if(!exempt&&(!rel.module||!rel.table||!rel.id||!rel.ref))throw new Error('Workflow notification requires related module, table, record ID and reference.');
  rel.url=rel.url||notificationRecordUrl(rel);
  body.related_module=rel.module||null;body.related_table=rel.table||null;body.related_id=rel.id||null;body.related_ref=rel.ref||null;body.record_url=rel.url||null;
  body.metadata=Object.assign({},body.metadata||{},{relationship:rel});
  body.body_html=notificationLinkBody(body.body_html,rel.url);
  var issue=notificationRecipientIssue(body.to_email);
  if(issue){
    body.status='failed';
    body.error_msg=body.error_msg||issue;
    body.retry_count=body.retry_count||1;
    body.to_email=String(body.to_email||'undeliverable@auris360.local').trim();
  }
  try{return await api('/notification_queue',{m:'POST',p:'return=representation',b:body});}
  catch(e){
    if(/metadata/i.test(e.message||'')){var withoutMetadata=Object.assign({},body);delete withoutMetadata.metadata;return api('/notification_queue',{m:'POST',p:'return=representation',b:withoutMetadata});}
    if(!/related_module|related_ref|record_url|schema cache|could not find/i.test(e.message||''))throw e;
    var legacy=Object.assign({},body);delete legacy.related_module;delete legacy.related_ref;delete legacy.record_url;
    try{return await api('/notification_queue',{m:'POST',p:'return=representation',b:legacy});}
    catch(e2){delete legacy.metadata;return api('/notification_queue',{m:'POST',p:'return=representation',b:legacy});}
  }
}
async function notificationOpen(id){
  var row=(notificationQueueRows||[]).find(function(x){return String(x.id)===String(id);});if(!row)return toast('Notification is no longer in the recent list. Refresh and try again.',false);
  var rel=notificationRelationship(row);
  if(!rel.module||!rel.table||!rel.id){await notificationLogEvent(row,'failed_target',{reason:'relationship_missing'});return toast('This legacy notification has no exact source record. Open the relevant module from the sidebar.',false);}
  var request=deepLinkNormalise({goto:rel.module,record:rel.id,ref:rel.ref,table:rel.table,company:rel.company_id});
  if(!request||!canAccessPage(deepLinkPage(request))){await notificationLogEvent(row,'failed_target',{reason:'access_denied'});return toast('Your current role cannot open this notification source.',false);}
  await notificationLogEvent(row,'opened',{surface:'notification_settings'});
  deepLinkStore(request);
  var opened=await deepLinkResume('notification-open');if(!opened)await notificationLogEvent(row,'failed_target',{reason:'record_unavailable'});
}
function usersContactEmail(u){
  return u?.real_email||u?.notification_email||(isDeliverableEmail(u?.email)?u.email:'');
}
function usersPreferredChannel(u){
  return u?.preferred_notification_channel||u?.notification_channel||(usersContactEmail(u)?'email':(u?.whatsapp_phone||u?.phone?'phone':'in_app'));
}
function usersChannelLabel(ch){
  return ({email:'Email',whatsapp:'WhatsApp',sms:'SMS',phone:'Phone',in_app:'In-app only'})[ch]||String(ch||'In-app only');
}
function usersNotifyStatus(u){
  var email=usersContactEmail(u), channel=usersPreferredChannel(u);
  if(email&&channel==='email')return '<span class="badge bg">Email ready</span>';
  if(channel==='whatsapp'&&(u.whatsapp_phone||u.phone)&&u.whatsapp_opted_in_at&&!u.whatsapp_opted_out_at)return '<span class="badge bb">WhatsApp opted in</span>';
  if(channel==='whatsapp')return '<span class="badge ba">WhatsApp consent required</span>';
  if(channel==='sms'&&(u.mobile_phone||u.phone))return '<span class="badge bb">SMS ready</span>';
  if(!isDeliverableEmail(u?.email))return '<span class="badge ba">Login only</span>';
  return '<span class="badge bgr">In-app only</span>';
}
function usersRender(data) {
  var el = document.getElementById('users-list'); if(!el) return;
  if(!data.length) {
    el.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text2)"><div style="font-size:40px;margin-bottom:12px"><i class="ti ti-circle-dot"></i></div><div style="font-weight:600">No users found</div></div>';
    return;
  }
  var h = '<div class="table-scroll"><table class="data-table" style="min-width:980px">'
    + '<thead><tr>'
    + '<th>User</th>'
    + '<th>Email</th>'
    + (isSA()?'<th>Company</th>':'')
    + '<th>Role</th>'
    + '<th>Department</th>'
    + '<th>Job title</th>'
    + '<th>Status</th>'
    + '<th>Last login</th>'
    + (isMgr()?'<th style="width:170px">Actions</th>':'')
    + '</tr></thead><tbody>';
  data.forEach(function(u, i) {
    var bg = i%2===0?'#fff':'#f9fafb';
    var rc = HSE_ROLES[u.role] || {label:u.role||'-',emoji:'?',color:'#6B7280',bg:'#f3f4f6'};
    var isActive = u.status !== 'inactive';
    var isSelf = u.id === prof?.id;
    var canEdit = usersCanEditUser(u);
    var canAdmin = usersCanAdminUser(u);
    h += '<tr data-user-id="'+escH(u.id)+'" style="border-bottom:1px solid #f0f0f0;background:'+bg+(isSelf?';outline:2px solid #185FA5 inset':'')+';cursor:pointer">'
      + '<td style="padding:8px 14px">'
      + '<div style="display:flex;align-items:center;gap:8px">'
      + '<div style="width:32px;height:32px;border-radius:50%;background:'+rc.color+';color:#fff;display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;flex-shrink:0">'
      + (u.full_name?u.full_name[0].toUpperCase():rc.emoji)+'</div>'
      + '<div><div style="font-weight:700">'+escH(u.full_name||'-')+(isSelf?'<span style="font-size:9px;background:#185FA5;color:#fff;padding:1px 5px;border-radius:3px;margin-left:4px">YOU</span>':'')+'</div>'
      + '</div></div></td>'
      + '<td style="padding:8px;font-family:monospace;font-size:11px;color:var(--text2)">'+escH(u.email||'-')+'</td>'
      + (isSA()?'<td style="padding:8px;font-size:11px">'+escH(u.companies?.name||'-')+'</td>':'')
      + '<td style="padding:8px"><span style="background:'+rc.bg+';color:'+rc.color+';padding:3px 10px;border-radius:99px;font-size:10px;font-weight:700;white-space:nowrap">'+rc.emoji+' '+rc.label+'</span></td>'
      + '<td style="padding:8px;font-size:11px">'+escH(u.department||'-')+'</td>'
      + '<td style="padding:8px;font-size:11px">'+escH(u.job_title||'-')+'</td>'
      + '<td style="padding:8px;text-align:center"><span style="background:'+(isActive?'#EAF3DE':'#f3f4f6')+';color:'+(isActive?'#3B6D11':'#6B7280')+';padding:2px 8px;border-radius:99px;font-size:10px;font-weight:700">'+(isActive?'Active':'Inactive')+'</span></td>'
      + '<td style="padding:8px;font-size:11px;color:var(--text2)">'+usersFmtLastLogin(u.last_login)+'</td>'
      + (isMgr()
        ? '<td style="padding:8px"><div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:center">'
          + (canEdit?'<button class="btn btn-sm" title="Edit user" data-id="'+u.id+'" data-auris-generated-onclick="g0336"><i class="ti ti-edit"></i></button>':'<span style="font-size:11px;color:var(--text3)">Protected</span>')
          + (canAdmin&&!usersIsGeneratedLogin(u)?'<button class="btn btn-sm" title="Send password reset email" data-id="'+u.id+'" data-auris-generated-onclick="g0337"><i class="ti ti-key"></i></button>':'')
          + (usersCanResetPassword(u)?'<button class="btn btn-sm" title="'+(isSelf?'Change my password':'Set temporary password')+'" data-id="'+u.id+'" data-auris-generated-onclick="g0338"><i class="ti ti-lock-cog"></i></button>':'')
          + (canAdmin?'<button class="btn btn-sm" style="color:'+(!isActive?'var(--green)':'var(--red)')+'" title="'+(isActive?'Deactivate (block login)':'Reactivate')+'" data-id="'+u.id+'" data-active="'+(isActive?'1':'0')+'" data-auris-generated-onclick="g0339"><i class="ti ti-'+(isActive?'user-off':'user-check')+'"></i></button>':'')
          + (canAdmin?'<button class="btn btn-sm" style="color:var(--red)" title="Deactivate user and preserve history" data-id="'+u.id+'" data-auris-generated-onclick="g0340"><i class="ti ti-user-off"></i></button>':'')
          + '</div></td>'
        : '')
      + '</tr>';
  });
  el.innerHTML = h + '</tbody></table></div>';
}

// -- Edit user --------------------------------------------------------
var usersProfileCurrentId=null;
var usersProfileCurrentTab='profile';
function usersOpenProfile(id){
  var u=(usersAllData||[]).find(function(x){return x.id===id;});
  if(!u){toast('User not found',false);return;}
  usersProfileCurrentId=id;
  usersProfileCurrentTab='profile';
  usersRenderProfileModal();
  var modal=document.getElementById('user-profile-modal');
  if(modal)modal.style.display='flex';
}
function usersCloseProfile(){
  var modal=document.getElementById('user-profile-modal');
  if(modal)modal.style.display='none';
}
document.addEventListener('click',function(ev){
  var row=ev.target.closest('#users-list tbody tr');
  if(!row||ev.target.closest('button'))return;
  var id=row.dataset.userId||'';
  if(id)usersOpenProfile(id);
});
function usersProfileSwitch(tab){
  usersProfileCurrentTab=tab||'profile';
  usersRenderProfileModal();
}
function usersProfileField(icon,label,value){
  return '<div style="display:grid;grid-template-columns:26px 120px 1fr;gap:10px;align-items:start;padding:9px 0">'
    +'<i class="ti '+icon+'" style="color:#9ca3af;font-size:16px;margin-top:1px"></i>'
    +'<div style="color:#8b8f98;font-size:13px">'+escH(label)+'</div>'
    +'<div style="color:#374151;font-size:13px;font-weight:500">'+escH(value||'-')+'</div>'
    +'</div>';
}
function usersWhatsappConsentActive(u){return !!(u&&u.whatsapp_opted_in_at&&!u.whatsapp_opted_out_at&&u.whatsapp_phone);}
var usersNotificationPreferences=null;
async function usersLoadNotificationPreferences(){
  if(usersProfileCurrentId!==prof?.id)return;
  try{var rows=await api('/notification_user_preferences?profile_id=eq.'+encodeURIComponent(prof.id)+'&limit=1');usersNotificationPreferences=rows&&rows[0]?rows[0]:{};usersRenderNotificationPreferenceControls();}
  catch(e){usersNotificationPreferences={schema_missing:true,error:e.message};usersRenderNotificationPreferenceControls();}
}
function usersRenderNotificationPreferenceControls(){
  var el=document.getElementById('upm3-notification-preferences');if(!el)return;var p=usersNotificationPreferences||{};
  if(p.schema_missing){el.innerHTML='<div style="padding:12px;background:#FFFBEB;border:1px solid #FDE68A;border-radius:9px;color:#92400E;font-size:12px"><strong>Preference controls require setup.</strong> Run <code>notification_user_preferences_upgrade.sql</code>.</div>';return;}
  var checked=function(v,defaultValue){return (v==null?defaultValue:v)?'checked':'';};
  el.innerHTML='<div style="font-weight:800;color:var(--text);margin-bottom:9px">Delivery preferences & quiet hours</div>'
    +'<div style="font-size:11px;color:var(--text2);line-height:1.5;margin-bottom:12px">In-app notifications always remain available. These controls apply to external email, push and consented WhatsApp delivery.</div>'
    +'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:12px"><label><input type="checkbox" id="upm3-pref-email" '+checked(p.email_enabled,true)+'> Email</label><label><input type="checkbox" id="upm3-pref-push" '+checked(p.push_enabled,true)+'> Push</label><label><input type="checkbox" id="upm3-pref-wa" '+checked(p.whatsapp_enabled,true)+'> WhatsApp</label></div>'
    +'<label style="display:flex;align-items:center;gap:7px;font-weight:700"><input type="checkbox" id="upm3-pref-quiet" '+checked(p.quiet_hours_enabled,false)+'> Enable quiet hours</label>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr 1.5fr;gap:8px;margin-top:9px"><div><label style="font-size:10px">From</label><input type="time" id="upm3-pref-start" value="'+escH(String(p.quiet_start||'20:00').slice(0,5))+'"></div><div><label style="font-size:10px">Until</label><input type="time" id="upm3-pref-end" value="'+escH(String(p.quiet_end||'06:00').slice(0,5))+'"></div><div><label style="font-size:10px">Timezone</label><select id="upm3-pref-timezone"><option>Asia/Dubai</option><option>Indian/Mauritius</option><option>UTC</option><option>Europe/London</option></select></div></div>'
    +'<label style="display:flex;align-items:flex-start;gap:7px;margin-top:10px;font-size:11px"><input type="checkbox" id="upm3-pref-override" '+checked(p.allow_urgent_override,true)+'> Allow urgent acknowledgement-required safety alerts to override quiet hours. Every override is audited.</label>'
    +'<div style="margin-top:10px"><label style="font-size:10px">External alert burst limit per hour</label><input type="number" min="1" max="60" id="upm3-pref-limit" value="'+Number(p.max_external_alerts_per_hour||10)+'"></div>'
    +'<button class="btn" style="margin-top:12px" data-auris-generated-onclick="g0341"><i class="ti ti-device-floppy"></i>Save delivery preferences</button>';
  var tz=document.getElementById('upm3-pref-timezone');if(tz)tz.value=p.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Dubai';
}
async function usersSaveNotificationPreferences(){
  if(usersProfileCurrentId!==prof?.id)return toast('Only the account owner can change delivery preferences.',false);
  var val=function(id){return document.getElementById(id)?.value;},on=function(id){return !!document.getElementById(id)?.checked;};
  try{var result=await api('/rpc/set_my_notification_preferences',{m:'POST',b:{p_timezone:val('upm3-pref-timezone')||'Asia/Dubai',p_quiet_enabled:on('upm3-pref-quiet'),p_quiet_start:val('upm3-pref-start')||'20:00',p_quiet_end:val('upm3-pref-end')||'06:00',p_allow_urgent_override:on('upm3-pref-override'),p_email_enabled:on('upm3-pref-email'),p_push_enabled:on('upm3-pref-push'),p_whatsapp_enabled:on('upm3-pref-wa'),p_max_external_alerts:Number(val('upm3-pref-limit')||10)}});usersNotificationPreferences=Array.isArray(result)?result[0]:result;toast('Delivery preferences saved.');usersRenderNotificationPreferenceControls();}catch(e){toastActionError('Save notification preferences','Users & Roles',e);}
}
async function usersSetWhatsappConsent(optedIn){
  var u=(usersAllData||[]).find(function(x){return x.id===usersProfileCurrentId;});
  if(!u||u.id!==prof?.id)return toast('Only the account owner can change WhatsApp consent.',false);
  var phone=document.getElementById('upm3-whatsapp-phone')?.value||u.whatsapp_phone||u.phone||'';
  if(optedIn&&!/^\+[1-9][0-9]{7,14}$/.test(phone.replace(/[\s()-]/g,'')))return toast('Enter the WhatsApp number in international format, for example +2305xxxxxxx.',false);
  if(!optedIn&&!(await appConfirmAction({title:'Disable WhatsApp alerts?',message:'AURIS360 will stop queueing new WhatsApp alerts for this account.',detail:'In-app and email notification evidence remains available.',confirmText:'Disable WhatsApp',cancelText:'Keep enabled'})))return;
  try{
    await api('/rpc/set_my_whatsapp_consent',{m:'POST',b:{p_opted_in:!!optedIn,p_phone:phone,p_consent_version:'2026-08'}});
    await usersLoad();usersProfileCurrentId=prof.id;usersProfileCurrentTab='notifications';usersRenderProfileModal();
    toast(optedIn?'WhatsApp alerts enabled. Delivery also requires your company WhatsApp channel to be active.':'WhatsApp alerts disabled.');
  }catch(e){toastActionError('Update WhatsApp consent','Users & Roles',e);}
}
