// -- Role permission matrix --------------------------------------------
function rolesRenderMatrix() {
  var thead = document.getElementById('roles-matrix-head');
  var tbody = document.getElementById('roles-matrix-body');
  if(!thead||!tbody) return;

  // Column headers
  var headerRow = '<tr style="background:#1a3a5c;color:#fff">'
    + '<th style="padding:10px 14px;text-align:left;min-width:200px;position:sticky;left:0;background:#1a3a5c;z-index:2">Module / Feature</th>';
  ROLE_KEYS.forEach(function(rk) {
    var rc = HSE_ROLES[rk];
    headerRow += '<th style="padding:8px 6px;text-align:center;min-width:80px;font-size:10px">'
      + '<div style="font-size:16px;margin-bottom:2px">'+rc.emoji+'</div>'
      + '<div style="font-size:9px;line-height:1.2;white-space:normal">'+rc.label+'</div>'
      + '</th>';
  });
  headerRow += '</tr>';
  thead.innerHTML = headerRow;

  // Rows
  var currentSection = '';
  var h = '';
  Object.entries(ROLE_PERMISSIONS).forEach(function(entry, i) {
    var module = entry[0]; var perms = entry[1];
    var isSubRow = module.startsWith('?');
    var bg = i%2===0?'#fff':'#f9fafb';
    if(isSubRow) bg = bg==='#fff'?'#f9f9ff':'#f3f3fa';
    h += '<tr style="border-bottom:1px solid #f0f0f0;background:'+bg+'">'
      + '<td style="padding:'+(isSubRow?'6px 14px 6px 28px':'8px 14px')+';font-size:12px;font-weight:'+(isSubRow?'500':'700')+';position:sticky;left:0;background:'+bg+';z-index:1;color:'+(isSubRow?'var(--text2)':'inherit')+'">'
      + (isSubRow?'<span style="color:var(--text2);margin-right:4px">+</span>':'')
      + escH(module.replace('?','').trim())+'</td>';
    ROLE_KEYS.forEach(function(rk, ri) {
      var hasPerm = perms[ri] !== false && perms[ri] !== undefined ? perms[ri] : false;
      // Map legacy roles: manager?hse_manager level, inspector?supervisor level
      if(rk==='manager') hasPerm = perms[ROLE_KEYS.indexOf('hse_manager')];
      if(rk==='inspector') hasPerm = perms[ROLE_KEYS.indexOf('supervisor')];
      var rc = HSE_ROLES[rk];
      h += '<td style="padding:6px;text-align:center">'
        + '<span style="display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;font-size:12px;background:'+(hasPerm?rc.bg:'transparent')+';">'
        + (hasPerm?'<span style="color:'+rc.color+';font-weight:900">?</span>':'<span style="color:#e5e7eb">-</span>')
        + '</span></td>';
    });
    h += '</tr>';
  });
  tbody.innerHTML = h;

  // Role description cards below the table
  var descDiv = document.getElementById('roles-matrix-table')?.closest('.card');
  if(descDiv) {
    var existing = document.getElementById('roles-desc-cards');
    if(!existing) {
      var descEl = document.createElement('div');
      descEl.id = 'roles-desc-cards';
      descEl.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px;padding:14px 0 0';
      descEl.innerHTML = ROLE_KEYS.map(function(rk) {
        var rc = HSE_ROLES[rk];
        return '<div style="border:2px solid '+rc.bg+';border-radius:10px;padding:10px 12px;background:#fff">'
          + '<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px">'
          + '<span style="font-size:18px">'+rc.emoji+'</span>'
          + '<span style="font-weight:700;font-size:12px;color:'+rc.color+'">'+rc.label+'</span>'
          + '</div>'
          + '<div style="font-size:11px;color:var(--text2);line-height:1.5">'+escH(rc.desc)+'</div>'
          + '</div>';
      }).join('');
      descDiv.appendChild(descEl);
    }
  }
}

// -- Apply roles to UI (enhanced) ------------------------------------
// -----------------------------------------------------------------------
// PRODUCTION MODULE SET
// These built client-facing modules are globally available. Sensitive
// platform pages remain role-controlled through ROLE_ALLOWED.
// -----------------------------------------------------------------------
var LAUNCHED_MODULES = [
  'dashboard','executive','kpi','workschedule','events','observation',
  'inspection','risk','tools','fleet','atex','sitemap','permit','contractor',
  'emergency','fire','chemical','ohealth','ppe','esg','noise','meetings',
  'training','actions','moc','legal','sop','swms','documents','people'
];

var DEV_MODE_KEY = 'auris360_dev_mode';

function devModeOn() {
  // Only sephs_admin can have dev-mode active (others can't enable it)
  if(!isSA()) return false;
  try { return localStorage.getItem(DEV_MODE_KEY) === '1'; }
  catch(e) { return false; }
}

function devModeToggle() {
  if(!isSA()) return;
  var cur = devModeOn();
  try { localStorage.setItem(DEV_MODE_KEY, cur?'0':'1'); } catch(e){}
  // Re-apply gating across the app
  applyRoles();
  modulesMenuBuild();
  // Re-trigger dashboard render to refresh navigation visibility there too
  if(typeof dashRouteView === 'function') dashRouteView();
  devModeUpdateUI();
  toast(cur?'Rollout view active - only launched modules visible':'Admin tools active - all modules visible', true);
}

// Update the SEPHS-only rollout/admin tools button appearance.
// Show button only for sephs_admin; hide for everyone else.
function devModeUpdateUI() {
  var btn = document.getElementById('dev-mode-toggle');
  if(!btn) return;
  if(!isSA()) { btn.style.display = 'none'; return; }
  btn.style.display = 'inline-flex';
  var on = devModeOn();
  var icon = document.getElementById('dev-mode-icon');
  var label = document.getElementById('dev-mode-label');
  if(on) {
    btn.style.background = '#FEF3C7';
    btn.style.borderColor = '#FCD34D';
    btn.style.color = '#92400E';
    if(icon) icon.style.color = '#92400E';
    if(label){ label.textContent = isSA() ? 'Admin tools' : ''; label.style.display = isSA() ? '' : 'none'; }
  } else {
    btn.style.background = '';
    btn.style.borderColor = 'transparent';
    btn.style.color = '';
    if(icon) icon.style.color = '';
    if(label){ label.textContent = 'Rollout view'; label.style.display = ''; }
  }
}

// -----------------------------------------------------------------------
// SEPHS_ADMIN COMPANY SWITCHER - view data scoped to one client at a time.
// Default: sees all companies. Pick one ? all subsequent queries filter to it.
// -----------------------------------------------------------------------
var SA_COMPANY_CTX_KEY = 'auris360_sa_company_ctx';
var saCompanyList = [];  // cached list of {id, name}

function saCompanyGetContext() {
  try { return localStorage.getItem(SA_COMPANY_CTX_KEY) || null; }
  catch(e) { return null; }
}
function saCompanySetContext(companyId) {
  try {
    if(companyId) localStorage.setItem(SA_COMPANY_CTX_KEY, companyId);
    else localStorage.removeItem(SA_COMPANY_CTX_KEY);
  } catch(e){}
  sephsCompanyContext = companyId;
  saCompanyUpdateLabel();
  sidebarApplyCompanyLogo();
}

function saCompanyUpdateLabel() {
  var lbl = document.getElementById('sa-company-label');
  if(!lbl) return;
  if(!sephsCompanyContext) {
    lbl.textContent = 'All companies';
  } else {
    var co = saCompanyList.find(function(c){return c.id===sephsCompanyContext;});
    lbl.textContent = co ? co.name : 'Selected company';
  }
}

async function saCompanyInit() {
  // Only run for sephs_admin
  if(!isSA()) {
    var w = document.getElementById('sa-company-switcher');
    if(w) w.style.display = 'none';
    return;
  }
  var w = document.getElementById('sa-company-switcher');
  if(w) w.style.display = 'inline-flex';
  // Load company list (only once per session)
  if(saCompanyList.length === 0) {
    try {
      // Direct query bypassing cf() since we want ALL companies
      var data = await api('/companies?select=id,name,logo_url&order=name.asc');
      saCompanyList = data || [];
    } catch(e) {
      console.warn('Could not load companies:', e);
    }
  }
  // Restore saved context
  var saved = saCompanyGetContext();
  if(saved) {
    sephsCompanyContext = saved;
  }
  saCompanyUpdateLabel();
  sidebarApplyCompanyLogo();
}

function saCompanyMenuToggle(evt) {
  if(evt) evt.stopPropagation();
  var menu = document.getElementById('sa-company-menu');
  if(!menu) return;
  var willOpen = !menu.classList.contains('open');
  if(willOpen) {
    modulesMenuClose();
    menu.style.display = '';
    saCompanyMenuBuild();
  }
  menu.classList.toggle('open', willOpen);
}
function saCompanyMenuClose() {
  var menu = document.getElementById('sa-company-menu');
  if(menu) {
    menu.classList.remove('open');
    menu.style.display = '';
  }
}

function saCompanyMenuBuild() {
  var menu = document.getElementById('sa-company-menu');
  if(!menu) return;
  var html = '<div class="modules-menu-section">View context</div>';
  // "All companies" option at top
  var isAllActive = !sephsCompanyContext;
  html += '<div class="modules-menu-item'+(isAllActive?' active':'')+'" data-auris-generated-onclick="g0345"><i class="ti ti-globe"></i>All companies (portfolio view)</div>';
  if(saCompanyList.length === 0) {
    html += '<div style="padding:10px 14px;font-size:11px;color:var(--text3)">No companies loaded yet.</div>';
  } else {
    html += '<div class="modules-menu-section">Companies (' + saCompanyList.length + ')</div>';
    saCompanyList.forEach(function(c){
      var isActive = sephsCompanyContext === c.id;
      html += '<div class="modules-menu-item'+(isActive?' active':'')+'" data-auris-runtime-onclick="r0109" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([c.id]))+'"><i class="ti ti-building"></i>'+escapeHtml(c.name||'(unnamed)')+'</div>';
    });
  }
  menu.innerHTML = html;
}

async function saCompanyPick(companyId) {
  saCompanyMenuClose();
  saCompanySetContext(companyId);
  await loadRolloutRuntimeConfig();
  applyRoles();

  // Reload the current page's data with the new filter context.
  // We re-invoke showPage() for the active page, which reuses the canonical
  // loader map defined inside showPage itself - no risk of name drift.
  var activePage = document.querySelector('.page.active');
  var activeId = activePage ? activePage.id.replace('page-','') : 'dashboard';
  // Re-show the page (will trigger its loader from showPage's L map)
  if(typeof showPage === 'function') {
    showPage(activeId, null);
  }

  // Toast confirmation
  var co = companyId ? saCompanyList.find(function(c){return c.id===companyId;}) : null;
  if(typeof toast === 'function') {
    toast(co ? 'Viewing data for: '+co.name : 'Viewing data for: All companies (portfolio view)', true);
  }
  setTimeout(function(){if(typeof deepLinkResume==='function')deepLinkResume('company-switch');},220);
}

// Close company switcher on outside click
document.addEventListener('click', function(e){
  var menu = document.getElementById('sa-company-menu');
  var trigger = document.getElementById('sa-company-trigger');
  if(!menu || !menu.classList.contains('open')) return;
  if(menu.contains(e.target) || (trigger && trigger.contains(e.target))) return;
  saCompanyMenuClose();
});

// Module is "launched" if it's in LAUNCHED_MODULES, OR if user is sephs_admin in dev mode.
function isModuleLaunched(pageKey) {
  if(LAUNCHED_MODULES.indexOf(pageKey) !== -1) return true;
  if(isSA()) return true;  // sephs_admin always sees all modules
  if(devModeOn()) return true;  // dev mode also shows all
  return false;
}

// -----------------------------------------------------------------------
// SIDEBAR - collapsible + hidden states with localStorage persistence
// States: '' (expanded, default) ? 'collapsed' (icons only) ? 'hidden' (off)
// -----------------------------------------------------------------------
var SIDEBAR_STATE_KEY = 'auris360_sidebar_state';
var SIDEBAR_STATES = ['', 'collapsed'];

function sidebarGetState() {
  try {
    var s = localStorage.getItem(SIDEBAR_STATE_KEY) || '';
    return SIDEBAR_STATES.indexOf(s) === -1 ? '' : s;
  }
  catch(e) { return ''; }
}
function sidebarSetState(s) {
  if(SIDEBAR_STATES.indexOf(s) === -1) s = '';
  try { localStorage.setItem(SIDEBAR_STATE_KEY, s); } catch(e){}
  sidebarApplyState(s);
}
function sidebarApplyState(s) {
  if(SIDEBAR_STATES.indexOf(s) === -1) s = '';
  var sb = document.querySelector('.sidebar');
  if(!sb) return;
  sidebarEnhanceNavItems();
  sb.classList.remove('collapsed','hidden');
  if(s === 'collapsed') sb.classList.add('collapsed');
  // Tooltip data - annotate every nav item for icon-only mode.
  document.querySelectorAll('.sidebar .nav-item').forEach(function(el){
    var txt=(el.textContent||'').trim();
    if(txt){
      el.dataset.tip=txt;
      el.setAttribute('title',txt);
      el.setAttribute('aria-label',txt);
    }
  });
  // Update toggle icon
  var icon = document.getElementById('sidebar-toggle-icon');
  if(icon) {
    if(s === 'collapsed') icon.className = 'ti ti-layout-sidebar-left-collapse';
    else icon.className = 'ti ti-menu-2';
  }
}
function sidebarEnhanceNavItems(){
  document.querySelectorAll('.sidebar .nav-item').forEach(function(el){
    var onclick=el.getAttribute('onclick')||'';
    var match=onclick.match(/showPage\('([^']+)'/);
    if(match) el.setAttribute('data-nav-key',match[1]);
    if(match && match[1] === 'contractor'){
      var contractorIcon = el.querySelector('i');
      if(contractorIcon) contractorIcon.className = 'ti ti-helmet';
    }
    if(!el.querySelector('.nav-label')){
      var labelParts=[];
      Array.prototype.slice.call(el.childNodes).forEach(function(node){
        if(node.nodeType===3 && node.textContent.trim()){
          labelParts.push(node.textContent.trim());
          el.removeChild(node);
        }
      });
      if(labelParts.length){
        var span=document.createElement('span');
        span.className='nav-label';
        span.textContent=labelParts.join(' ');
        el.appendChild(span);
      }
    }
  });
}
var sidebarCycleLocked = false;
function sidebarCycle() {
  if(sidebarCycleLocked) return;
  sidebarCycleLocked = true;
  setTimeout(function(){ sidebarCycleLocked = false; }, 480);
  var cur = sidebarGetState();
  var i = SIDEBAR_STATES.indexOf(cur);
  var next = SIDEBAR_STATES[(i + 1) % SIDEBAR_STATES.length];
  sidebarSetState(next);
}
// Keyboard shortcut: Ctrl+B (and Cmd+B on Mac)
document.addEventListener('keydown', function(e){
  if((e.ctrlKey || e.metaKey) && e.key === 'b') {
    // Only when app is visible (not on login screen)
    var app = document.getElementById('app');
    if(app && app.style.display !== 'none') {
      e.preventDefault();
      sidebarCycle();
    }
  }
});

