let adminCompaniesData = [], adminSitesData = [], adminAccessData = [], adminUsersData = [];
let adminEditCoId = null, adminEditSiteId = null;
let adminActiveSiteFilter = null;  // currently selected site for data filtering

const SITE_TYPE_CFG = {
  group:    {emoji:'*', label:'Group',    color:'#5B21B6', order:1},
  region:   {emoji:'*',  label:'Region',   color:'#185FA5', order:2},
  country:  {emoji:'*',  label:'Country',  color:'#0891B2', order:3},
  site:     {emoji:'*', label:'Site',     color:'#065F46', order:4},
  facility: {emoji:'*',  label:'Facility', color:'#854F0B', order:5},
  building: {emoji:'*', label:'Building', color:'#374151', order:6},
  area:     {emoji:'*', label:'Area',     color:'#6B7280', order:7},
  zone:     {emoji:'*', label:'Zone',     color:'#9CA3AF', order:8},
};

const RISK_CFG = {
  critical: {color:'#DC2626', bg:'#FCEBEB'},
  high:     {color:'#C2410C', bg:'#FEF6E7'},
  medium:   {color:'#854F0B', bg:'#FEF9EC'},
  low:      {color:'#3B6D11', bg:'#EAF3DE'},
};

// -- Entry point ----------------------------------------------------------------
async function loadAdmin() {
  adminTab('overview', document.getElementById('adm3tab-overview'));
}

function adminTab(tab, btn) {
  document.querySelectorAll('[id^="adm3tab-"]').forEach(function(t){t.classList.remove('active');});
  if(btn) btn.classList.add('active');
  ['overview','companies','sites','hierarchy','oversight','access','modules'].forEach(function(t){
    var el = document.getElementById('adm3view-'+t);
    if(el) el.style.display = t===tab ? 'block' : 'none';
  });
  if(tab === 'overview')   adminLoadOverview();
  else if(tab === 'companies') adminLoadCompanies();
  else if(tab === 'sites')     adminLoadSites();
  else if(tab === 'hierarchy') adminLoadHierarchyData();
  else if(tab === 'oversight') adminLoadOversight();
  else if(tab === 'access')    adminLoadAccessList();
  else if(tab === 'modules')   adminLoadModuleAccess();
}

// -- Load all data --------------------------------------------------------------
async function adminLoadAll() {
  var safe = async function(p){try{return await p;}catch(e){return [];}};
  var results = await Promise.all([
    safe(api('/companies?select=*&order=name')),
    safe(api('/sites?select=*&order=name')),
    safe(api('/profiles?select=id,full_name,email,role,status,company_id,department,job_title,last_login&order=full_name')),
  ]);
  adminCompaniesData = results[0]||[];
  adminSitesData     = results[1]||[];
  adminUsersData     = results[2]||[];
  // Metrics
  function sm(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}
  sm('adm3m3companies', adminCompaniesData.length);
  sm('adm3m3sites', adminSitesData.filter(function(s){return s.status!=='inactive';}).length);
  sm('adm3m3workers', adminSitesData.reduce(function(s,x){return s+(parseInt(x.headcount)||0);},0) || adminCompaniesData.reduce(function(s,x){return s+(parseInt(x.headcount)||0);},0));
  // Populate dropdowns across the page
  adminPopulateDropdowns();
}

function adminCompanyUsers(companyId){
  return (adminUsersData||[]).filter(function(u){return u.company_id===companyId;});
}

function adminCompanyUserCount(companyId){
  return adminCompanyUsers(companyId).length;
}

function adminPopulateDropdowns() {
  var cos = adminCompaniesData;
  // Company selects
  ['adm3co-parent','adm3hier-filter-co','adm3sites-filter-co','oversight-co-sel'].forEach(function(id){
    var el = document.getElementById(id); if(!el) return;
    var first = el.options[0];
    el.innerHTML = '';
    el.appendChild(first);
    cos.forEach(function(c){
      var o=document.createElement('option'); o.value=c.id; o.textContent=c.name;
      el.appendChild(o);
    });
  });
  // Site company select in site form
  var siteCo = document.getElementById('adm3site-company');
  if(siteCo){
    siteCo.innerHTML='<option value="">Select company...</option>';
    cos.forEach(function(c){var o=document.createElement('option');o.value=c.id;o.textContent=c.name;siteCo.appendChild(o);});
  }
  // Site parent select
  adminRefreshSiteParentSelect();
  // Access modal site select
  var accSite = document.getElementById('adm3acc-site');
  if(accSite){
    accSite.innerHTML='<option value="">Select site...</option>';
    adminSitesData.forEach(function(s){
      var o=document.createElement('option'); o.value=s.id;
      var cfg=SITE_TYPE_CFG[s.site_type]||{emoji:'*'};
      o.textContent=cfg.emoji+' '+s.name+(s.city?' ('+s.city+')':'');
      accSite.appendChild(o);
    });
  }
  // Site switcher in overview
  var switcher = document.getElementById('adm3site-switcher');
  if(switcher){
    switcher.innerHTML='<option value="">All sites (no filter)</option>';
    var grouped = {};
    adminSitesData.forEach(function(s){
      if(!grouped[s.company_id]) grouped[s.company_id]=[];
      grouped[s.company_id].push(s);
    });
    Object.entries(grouped).forEach(function(e){
      var co = adminCompaniesData.find(function(c){return c.id===e[0];});
      var og = document.createElement('optgroup');
      og.label = co?.name||'Unknown';
      e[1].forEach(function(s){
        var o=document.createElement('option'); o.value=s.id;
        var cfg=SITE_TYPE_CFG[s.site_type]||{emoji:'*'};
        o.textContent=cfg.emoji+' '+s.name;
        if(adminActiveSiteFilter===s.id) o.selected=true;
        og.appendChild(o);
      });
      switcher.appendChild(og);
    });
  }
}

function adminRefreshSiteParentSelect(companyId) {
  var el = document.getElementById('adm3site-parent'); if(!el) return;
  el.innerHTML='<option value="">None (top-level)</option>';
  var filter = companyId || document.getElementById('adm3site-company')?.value;
  var sites = filter ? adminSitesData.filter(function(s){return s.company_id===filter;}) : adminSitesData;
  sites.forEach(function(s){
    var o=document.createElement('option'); o.value=s.id;
    var cfg=SITE_TYPE_CFG[s.site_type]||{emoji:'*'};
    o.textContent=cfg.emoji+' '+s.name;
    if(adminEditSiteId && s.id===adminEditSiteId) return; // can't be own parent
    el.appendChild(o);
  });
}

// -- Overview -------------------------------------------------------------------
async function adminLoadOverview() {
  await adminLoadAll();
  // Update context card
  var coName = document.getElementById('adm3ctx-company');
  var coRole = document.getElementById('adm3ctx-role');
  if(coName) coName.textContent = prof?.company_name || adminCompaniesData.find(function(c){return c.id===prof?.company_id;})?.name || 'AURIS360';
  if(coRole){ var rc=typeof HSE_ROLES!=='undefined'?HSE_ROLES[prof?.role]:null; coRole.textContent=(rc?rc.emoji+' '+rc.label:(prof?.role||'').replace(/_/g,' '))+' - '+(isSA()?'Platform Admin':'Company Access'); }
  // Render company cards
  adminRenderOverviewCards();
  // Aggregate KPIs
  await adminRenderAggKPIs();
  // Metrics from DB
  try {
    var safe = async function(p){try{return await p;}catch(e){return [];}};
    var evd = await safe(api('/events?select=id,status&status=neq.closed'+(isSA()?'':'&company_id=eq.'+prof?.company_id)));
    var acd = await safe(api('/action_tracker?select=id,status&status=neq.closed'+(isSA()?'':'&company_id=eq.'+prof?.company_id)));
    function sm(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}
    sm('adm3m3incidents',(evd||[]).length);
    sm('adm3m3actions',(acd||[]).length);
  } catch(ex) {}
}

function adminFilterCompanies() {
  var q = (document.getElementById('adm3search-co')?.value||'').toLowerCase();
  var filt = adminCompaniesData.filter(function(c){return !q||(c.name||'').toLowerCase().includes(q)||(c.industry||'').toLowerCase().includes(q);});
  adminRenderOverviewCards(filt);
}

function adminRenderOverviewCards(data) {
  var el = document.getElementById('adm3companies-grid'); if(!el) return;
  var cos = data || adminCompaniesData;
  if(!cos.length){ el.innerHTML='<div style="text-align:center;padding:30px;color:var(--text2)"><div style="font-size:36px;margin-bottom:8px"><i class="ti ti-circle-dot"></i></div><div>No companies yet</div></div>'; return; }
  el.innerHTML = cos.map(function(co) {
    var sites = adminSitesData.filter(function(s){return s.company_id===co.id;});
    var headcount = parseInt(co.headcount)||0;
    var tierColors = {starter:['#6B7280','#f3f4f6'],professional:['#185FA5','#EFF6FF'],enterprise:['#5B21B6','#F5F3FF']};
    var tc = tierColors[co.subscription_tier||'professional']||tierColors.professional;
    var typeCfg = {group:'Group',subsidiary:'Subsidiary',client:'Client',standalone:'Standalone'};
    return '<div class="card" style="padding:0;overflow:hidden;cursor:pointer;border:2px solid '+(co.active!==false?'#185FA5':'#e5e7eb')+';transition:all .15s" data-auris-runtime-onclick="r0111" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([co.id]))+'" data-auris-generated-onmouseover="g0288" data-auris-generated-onmouseout="g0088">'
      + '<div style="height:4px;background:'+(co.active!==false?'linear-gradient(90deg,#185FA5,#1D9E75)':'#e5e7eb')+'"></div>'
      + '<div style="padding:12px 14px">'
      + '<div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:8px">'
      + '<div style="display:flex;align-items:center;gap:8px">'
      + (aurisSafeMediaUrl(co.logo_url,'image')?'<img src="'+escH(aurisSafeMediaUrl(co.logo_url,'image'))+'" style="width:36px;height:36px;border-radius:8px;object-fit:contain;border:1px solid #f3f4f6" data-auris-generated-onerror="g0347"/>':
        '<div style="width:36px;height:36px;border-radius:8px;background:#185FA5;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;flex-shrink:0">'+(co.name?co.name[0].toUpperCase():'?')+'</div>')
      + '<div><div style="font-weight:700;font-size:13px">'+escH(co.name)+'</div>'
      + '<div style="font-size:10px;color:var(--text2)">'+escH(co.industry||'-')+'</div>'
      + '</div></div>'
      + '<span style="background:'+tc[1]+';color:'+tc[0]+';padding:2px 7px;border-radius:99px;font-size:9px;font-weight:700;text-transform:uppercase">'+escH(co.subscription_tier||'pro')+'</span>'
      + '</div>'
      + '<div style="display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:6px;text-align:center">'
      + '<div style="background:#f9fafb;border-radius:6px;padding:5px 4px"><div style="font-size:15px;font-weight:800;color:#185FA5">'+sites.length+'</div><div style="font-size:9px;color:var(--text2)">Sites</div></div>'
      + '<div style="background:#f9fafb;border-radius:6px;padding:5px 4px"><div style="font-size:15px;font-weight:800;color:#5B21B6">'+adminCompanyUserCount(co.id)+'</div><div style="font-size:9px;color:var(--text2)">Users</div></div>'
      + '<div style="background:#f9fafb;border-radius:6px;padding:5px 4px"><div style="font-size:15px;font-weight:800;color:#1D9E75">'+headcount+'</div><div style="font-size:9px;color:var(--text2)">Workers</div></div>'
      + '<div style="background:#f9fafb;border-radius:6px;padding:5px 4px"><div style="font-size:15px;font-weight:800;color:'+(co.active!==false?'#1D9E75':'#6B7280')+'">'+(co.active!==false?'?':'?')+'</div><div style="font-size:9px;color:var(--text2)">Status</div></div>'
      + '</div>'
      + '<div style="display:flex;gap:4px;margin-top:8px">'
      + '<span style="font-size:10px;color:var(--text2);background:#f3f4f6;padding:1px 6px;border-radius:3px">'+escH(typeCfg[co.company_type||'standalone']||co.company_type||'-')+'</span>'
      + (co.country?'<span style="font-size:10px;color:var(--text2)">'+escH(co.country)+'</span>':'')
      + '</div>'
      + '</div></div>';
  }).join('');
}

async function adminRenderAggKPIs() {
  var el = document.getElementById('adm3agg-kpis'); if(!el) return;
  var safe = async function(p){try{return await p;}catch(e){return [];}};
  var q = isSA()?'':'&company_id=eq.'+prof?.company_id;
  var results = await Promise.all([
    safe(api('/events?select=id,severity&status=neq.closed'+q)),
    safe(api('/action_tracker?select=id,status'+q)),
    safe(api('/inspections?select=id,score_good,score_insuf'+q+'&order=created_at.desc&limit=20')),
  ]);
  var events=results[0]||[]; var actions=results[1]||[]; var insps=results[2]||[];
  var criHigh = events.filter(function(x){return ['critical','high'].includes(x.severity);}).length;
  var overdue = actions.filter(function(x){return x.status!=='closed';}).length;
  var avgScore = insps.length>0?Math.round(insps.reduce(function(s,x){var t=(x.score_good||0)+(x.score_insuf||0);return s+(t>0?(x.score_good||0)/t*100:0);},0)/insps.length):null;
  var kpis = [
    {label:'Critical/High incidents open', value:criHigh, color:criHigh>0?'#DC2626':'#1D9E75', icon:'*'},
    {label:'Overdue actions', value:overdue, color:overdue>0?'#EF9F27':'#1D9E75', icon:'*'},
    {label:'Avg inspection score', value:avgScore!=null?avgScore+'%':'-', color:avgScore!=null?(avgScore>=80?'#1D9E75':avgScore>=60?'#EF9F27':'#DC2626'):'#6B7280', icon:'*'},
    {label:'Active sites', value:adminSitesData.filter(function(s){return s.status==='active';}).length, color:'#185FA5', icon:'*'},
  ];
  el.innerHTML = kpis.map(function(k){
    return '<div style="display:flex;align-items:center;justify-content:space-between;padding:6px 8px;background:#f9fafb;border-radius:6px">'
      +'<div style="display:flex;align-items:center;gap:6px"><span style="font-size:12px">'+k.icon+'</span><span style="font-size:11px;font-weight:600;color:var(--text2)">'+k.label+'</span></div>'
      +'<span style="font-size:14px;font-weight:800;color:'+k.color+'">'+k.value+'</span>'
      +'</div>';
  }).join('');
}

// -- Site switcher ---------------------------------------------------------------
function adminSwitchSite(siteId) {
  adminActiveSiteFilter = siteId || null;
  if(siteId) {
    var site = adminSitesData.find(function(s){return s.id===siteId;});
    toast('Now viewing site: '+(site?.name||siteId));
    // Inject site filter - override the cf() function temporarily
    window._adminSiteOverride = siteId;
  } else {
    window._adminSiteOverride = null;
    toast('Site filter cleared - showing all data');
  }
}

