// -------------------------------------------------------------------------
// MODULE ACCESS - per-company control of which modules a client can see.
// -------------------------------------------------------------------------
// Catalog of all known client modules with friendly names and icons. Module
// access controls availability by company; role rules still control who can
// open sensitive areas.
var MODULE_CATALOG = [
  { key:'dashboard',   icon:'ti-layout-dashboard', name:'HSE Control Centre', note:'Always enabled' },
  { key:'kpi',         icon:'ti-target',           name:'Objectives & KPIs' },
  { key:'events',      icon:'ti-alert-triangle',   name:'Incident Management' },
  { key:'observation', icon:'ti-eye',              name:'BBS Observations' },
  { key:'training',    icon:'ti-school',           name:'Training' },
  { key:'meetings',    icon:'ti-calendar',         name:'HSE Meetings' },
  { key:'ppe',         icon:'ti-shield',           name:'PPE Management' },
  { key:'emergency',   icon:'ti-flame',            name:'Emergency' },
  { key:'permit',      icon:'ti-id-badge',         name:'Permit to Work' },
  { key:'fire',        icon:'ti-flame',            name:'Fire Certificates' },
  { key:'chemical',    icon:'ti-flask',            name:'Chemical Control' },
  { key:'fleet',       icon:'ti-car',              name:'Fleet Management' },
  { key:'atex',        icon:'ti-flame',            name:'ATEX Areas' },
  { key:'sitemap',     icon:'ti-map-2',            name:'Site Map' },
  { key:'risk',        icon:'ti-chart-bar',        name:'Risk Assessment' },
  { key:'inspection',  icon:'ti-clipboard-check',  name:'Audits & Inspections' },
  { key:'tools',       icon:'ti-tool',             name:'Tools & Equipment' },
  { key:'contractor',  icon:'ti-users',            name:'Contractors' },
  { key:'ohealth',     icon:'ti-stethoscope',      name:'Occupational Health' },
  { key:'noise',       icon:'ti-volume',           name:'Occupational Noise Management' },
  { key:'legal',       icon:'ti-scale',            name:'Legal Register' },
  { key:'workschedule',icon:'ti-calendar-week',    name:'Work Schedule' },
  { key:'documents',   icon:'ti-file',             name:'Documents' },
  { key:'sop',         icon:'ti-book',             name:'SOPs' },
  { key:'swms',        icon:'ti-file-check',       name:'SWMS / Method Statements' },
  { key:'people',      icon:'ti-id-badge',         name:'People' },
  { key:'actions',     icon:'ti-checkbox',         name:'Action Tracker' },
  { key:'moc',         icon:'ti-arrows-exchange',  name:'Management of Change' },
  { key:'esg',         icon:'ti-leaf',             name:'ESG' },
];

// Module presets - for one-click setup of common configurations
var MODULE_PRESETS = {
  starter: ['dashboard','kpi'],
  rollout:   ['dashboard','kpi','events','observation','training','meetings','ppe','emergency','permit'],
  production: DEFAULT_CLIENT_MODULES.slice(),
  none:    ['dashboard'],  // keep dashboard so they don't see a blank app
  all:     []  // filled at runtime to match LAUNCHED_MODULES
};

var currentModuleCompanyId = null;
var currentModuleAccess = [];

function openModuleAccess(coId) {
  if (!isSA()) { toast('Sephs admin only', false); return; }
  var co = (adminCompaniesData||[]).find(function(c){return c.id===coId;});
  if (!co) { toast('Company not found', false); return; }
  currentModuleCompanyId = coId;
  currentModuleAccess = moduleSanitizeAccess(co.module_access||[]);
  document.getElementById('adm3modules-co-name').textContent = co.name;
  renderModuleAccessList();
  document.getElementById('adm3modules-modal').style.display = 'flex';
}

function closeModuleAccess() {
  document.getElementById('adm3modules-modal').style.display = 'none';
  currentModuleCompanyId = null;
  currentModuleAccess = [];
}

function renderModuleAccessList() {
  var host = document.getElementById('adm3modules-modal-list');
  if (!host) return;
  var launched = (typeof LAUNCHED_MODULES !== 'undefined') ? LAUNCHED_MODULES : [];
  host.innerHTML = MODULE_CATALOG.map(function(m){
    var isLaunched = launched.indexOf(m.key) !== -1;
    var checked = currentModuleAccess.indexOf(m.key) !== -1;
    var isDashboard = m.key === 'dashboard';
    var disabled = isDashboard;  // dashboard always on
    var statusBadge = isLaunched
      ? '<span style="font-size:9px;background:#ECFDF5;color:#047857;padding:2px 6px;border-radius:999px;font-weight:600">LIVE</span>'
      : '<span style="font-size:9px;background:#F3F4F6;color:#4B5563;padding:2px 6px;border-radius:999px;font-weight:600">DISABLED</span>';
    return '<label style="display:flex;align-items:center;gap:10px;padding:9px 11px;border:1px solid '+(checked?'#5B21B6':'#E5E7EB')+';border-radius:8px;cursor:'+(disabled?'not-allowed':'pointer')+';background:'+(checked?'#F5F3FF':'#fff')+';opacity:'+(disabled?'0.7':'1')+'">'
      + '<input type="checkbox" '+(checked?'checked':'')+' '+(disabled?'disabled':'')+' data-auris-runtime-onchange="r0114" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([m.key]))+'" style="width:16px;height:16px;cursor:'+(disabled?'not-allowed':'pointer')+'"/>'
      + '<i class="ti '+m.icon+'" style="font-size:18px;color:'+(checked?'#5B21B6':'#6B7280')+'"></i>'
      + '<div style="flex:1;min-width:0">'
      + '<div style="font-size:12px;font-weight:600;color:var(--text)">'+escH(m.name)+'</div>'
      + (m.note ? '<div style="font-size:10px;color:var(--text2);font-style:italic">'+escH(m.note)+'</div>' : '')
      + '</div>'
      + statusBadge
      + '</label>';
  }).join('');
}

function toggleModuleAccess(key, checked) {
  if (key === 'dashboard') return;  // always on, can't toggle
  var idx = currentModuleAccess.indexOf(key);
  if (checked && idx === -1) currentModuleAccess.push(key);
  else if (!checked && idx !== -1) currentModuleAccess.splice(idx, 1);
  renderModuleAccessList();
}

function moduleAccessSelectPreset(name) {
  if (name === 'all') {
    currentModuleAccess = moduleLiveKeys();
  } else if (MODULE_PRESETS[name]) {
    currentModuleAccess = moduleSanitizeAccess(MODULE_PRESETS[name].slice());
  }
  // Always include dashboard
  if (currentModuleAccess.indexOf('dashboard') === -1) currentModuleAccess.unshift('dashboard');
  renderModuleAccessList();
}

async function saveModuleAccess() {
  if (!currentModuleCompanyId) { toast('No company selected', false); return; }
  // Always ensure dashboard is in the list
  currentModuleAccess = moduleSanitizeAccess(currentModuleAccess||[]);
  try {
    await api('/companies?id=eq.'+currentModuleCompanyId, {
      m:'PATCH',
      p:'return=minimal',
      b: { module_access: currentModuleAccess }
    });
    // Update local cache so the UI reflects immediately
    var co = (adminCompaniesData||[]).find(function(c){return c.id===currentModuleCompanyId;});
    if (co) co.module_access = currentModuleAccess.slice();
    // If sephs_admin is currently viewing this company via the switcher, refresh nav
    if (typeof refreshSidebarVisibility === 'function') {
      try { refreshSidebarVisibility(); } catch(_){}
    }
    toast('Module access saved ('+currentModuleAccess.length+' modules)');
    closeModuleAccess();
  } catch (e) {
    toast(actionErrorMessage('Save branding','Settings',e.message), false);
  }
}

async function adminSaveAccess(){
  var email=obNormText(document.getElementById('adm3acc-email')?.value).toLowerCase();
  var siteId=document.getElementById('adm3acc-site')?.value;
  if(!email||!siteId){toast('Email and site required',false);return;}
  if(!obEmailOk(email)){toast('Please enter a valid user email',false);return;}
  // Lookup user profile
  try{
    var users=await api('/profiles?email=eq.'+encodeURIComponent(email)+(prof?.company_id&&!isSA()?'&company_id=eq.'+prof.company_id:'')+'&select=id,full_name');
    if(!users||!users.length){toast('User not found: '+email,false);return;}
    var userId=users[0].id;
    var existing=await api('/user_site_access?select=id&user_id=eq.'+userId+'&site_id=eq.'+siteId+'&limit=1');
    if(existing&&existing.length){toast('This user already has access to the selected site',false);return;}
    var body={user_id:userId,site_id:siteId,company_id:ccid(),role_override:document.getElementById('adm3acc-role')?.value||null,access_level:document.getElementById('adm3acc-level')?.value||'read_write',granted_by:prof?.id};
    await api('/user_site_access',{m:'POST',p:'return=minimal',b:body});
    toast('Access granted to '+escH(users[0].full_name||email));
    adminCloseAccessModal(); adminLoadAccessList();
  }catch(e){toast(actionErrorMessage('Complete action','AURIS360',e),false);}
}

async function adminRevokeAccess(id){
  if(!(await appConfirmAction({title:'Revoke site access',message:'Revoke this site access?',detail:'The user will no longer have this site-specific access entry.',confirmText:'Revoke access',cancelText:'Cancel'})))return;
  try{await api('/user_site_access?id=eq.'+id,{m:'DELETE'});toast('Access revoked!');adminLoadAccessList();}
  catch(e){toastActionError('Revoke module access','Users & Roles',e);}
}

