function indRenderChecklist(){
  var host=document.getElementById('ind-checklist-body');if(!host)return;
  host.innerHTML=INDUCTION_CHECKLIST_SECTIONS.map(function(sec){
    var rows=sec.items.map(function(it){
      return '<tr style="border-bottom:1px solid #eef2f7">'
        +'<td style="padding:7px 8px;font-weight:700;line-height:1.35">'+escH(it[1])+'</td>'
        +'<td style="padding:7px 4px;text-align:center"><input type="checkbox" class="ind-topic" data-ind-key="'+escH(it[0])+'" value="'+escH(it[0])+'" style="accent-color:var(--green);width:17px;height:17px"/></td>'
        +'<td style="padding:7px 4px;text-align:center"><input type="checkbox" class="ind-topic-na" data-ind-key="'+escH(it[0])+'" value="na:'+escH(it[0])+'" style="accent-color:#9CA3AF;width:17px;height:17px"/></td>'
        +'<td style="padding:6px 8px"><input type="text" class="ind-topic-remarks" data-ind-key="'+escH(it[0])+'" placeholder="Remarks..." style="padding:5px 8px;font-size:11px;border:1px solid var(--border);border-radius:6px;width:100%"/></td>'
        +'</tr>';
    }).join('');
    return '<div style="border:1px solid var(--border);border-radius:10px;background:#fff;overflow:hidden;margin-bottom:10px">'
      +'<div style="padding:9px 12px;background:#185FA5;color:#fff;font-weight:900;font-size:12px;text-transform:uppercase;letter-spacing:.02em">'+escH(sec.title)+'</div>'
      +'<div style="overflow:auto"><table style="width:100%;min-width:620px;border-collapse:collapse;font-size:12px">'
      +'<thead><tr style="background:#f8fafc;color:var(--text2);font-size:10px;text-transform:uppercase"><th style="padding:7px 8px;text-align:left">Item covered / explained / demonstrated</th><th style="padding:7px;text-align:center;width:54px">Yes</th><th style="padding:7px;text-align:center;width:54px">N/A</th><th style="padding:7px 8px;text-align:left;width:220px">Remarks</th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';
  }).join('');
  indWireChecklistMutualExclusion();
}

function indWireChecklistMutualExclusion(){
  document.querySelectorAll('.ind-topic,.ind-topic-na').forEach(function(cb){
    cb.onchange=function(){
      if(!this.checked)return;
      var key=this.getAttribute('data-ind-key');
      var other=this.classList.contains('ind-topic')?document.querySelector('.ind-topic-na[data-ind-key="'+key+'"]'):document.querySelector('.ind-topic[data-ind-key="'+key+'"]');
      if(other)other.checked=false;
    };
  });
}

function indCollectChecklistTopics(){
  var topics=Array.from(document.querySelectorAll('.ind-topic:checked')).map(function(cb){return cb.value;});
  Array.from(document.querySelectorAll('.ind-topic-na:checked')).forEach(function(cb){topics.push(cb.value);});
  Array.from(document.querySelectorAll('.ind-topic-remarks')).forEach(function(input){
    var key=input.getAttribute('data-ind-key'), val=(input.value||'').trim();
    if(key&&val)topics.push('remark:'+key+':'+val);
  });
  return topics;
}

function indApplyChecklistTopics(topics){
  indRenderChecklist();
  document.querySelectorAll('.ind-topic,.ind-topic-na').forEach(function(cb){cb.checked=false;});
  document.querySelectorAll('.ind-topic-remarks').forEach(function(input){input.value='';});
  (Array.isArray(topics)?topics:[]).forEach(function(v){
    v=String(v||'');
    if(v.indexOf('remark:')===0){
      var m=v.match(/^remark:([^:]+):(.*)$/);
      if(m){var input=document.querySelector('.ind-topic-remarks[data-ind-key="'+m[1]+'"]');if(input)input.value=m[2]||'';}
      return;
    }
    if(v.indexOf('na:')===0){var na=document.querySelector('.ind-topic-na[value="'+v.replace(/"/g,'\\"')+'"]');if(na)na.checked=true;return;}
    var cb=document.querySelector('.ind-topic[value="'+v.replace(/"/g,'\\"')+'"]');if(cb)cb.checked=true;
  });
}

function indNew(){ window.indEditId=null;var el=document.getElementById('ind-form');if(!el)return;document.getElementById('ind-form3title').textContent='New Induction';if(document.getElementById('ind-del-btn'))document.getElementById('ind-del-btn').style.display='none';['indf-person','indf-emp-id','indf-dept','indf-job-title','indf-inducted-by','indf-extra-topics','indf-notes'].forEach(function(id){var e=document.getElementById(id);if(e)e.value='';});fillPersonSelect('indf-person');fillPersonSelect('indf-inducted-by',prof?.full_name||personFullName(prof));indApplyChecklistTopics([]);if(document.getElementById('indf-ind-date'))document.getElementById('indf-ind-date').value=new Date().toISOString().slice(0,10);var iv=document.getElementById('train-view-induction');if(iv)iv.style.display='none';el.style.display='block'; }
async function indSave(){ var person=document.getElementById('indf-person')?.value?.trim();if(!person){toast('Please enter person name',false);return;}var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};var topics=indCollectChecklistTopics();var extraTopics=g('indf-extra-topics');if(extraTopics)topics.push('additional:'+extraTopics);var body={company_id:ccid(),person_name:person,employee_id:g('indf-emp-id'),department:g('indf-dept'),job_title:g('indf-job-title'),induction_type:g('indf-type')||'new_employee',induction_date:g('indf-ind-date'),inducted_by:g('indf-inducted-by'),topics_covered:topics,notes:g('indf-notes'),status:g('indf-status')||'completed',completed:g('indf-status')==='completed',updated_at:new Date().toISOString()};Object.assign(body,personIdentityPayload(person));body.inducted_by_person_id=personFromValue(body.inducted_by)?.id||null;try{if(window.indEditId){await apiWriteWithMissingColumnFallback('/induction_records?id=eq.'+window.indEditId,{m:'PATCH',p:'return=minimal',b:body},'Induction record');trainingAudit('update','Induction record updated','induction_records',Object.assign({id:window.indEditId},body),{topics_count:topics.length});toast('Updated!');}else{body.created_by=prof?.id;var created=await apiWriteWithMissingColumnFallback('/induction_records',{m:'POST',p:'return=representation',b:body},'Induction record');trainingAudit('create','Induction record created','induction_records',(created&&created[0])||body,{topics_count:topics.length});toast('Induction saved!');}indBack();}catch(e){toast(actionErrorMessage('Save induction','Training register',e.message),false);} }
