function elcFillRequiredPeople(selected){
  var s=document.getElementById('elcf-enrol-people');if(!s)return;
  selected=selected||[];
  s.innerHTML=(people||[]).map(function(p){
    var nm=personFullName(p);
    return '<option value="'+escH(nm)+'" '+(selected.includes(nm)?'selected':'')+'>'+escH([p.last_name,p.first_name].filter(Boolean).join(', ')||nm)+(p.job_title?' -- '+escH(p.job_title):'')+'</option>';
  }).join('');
  var host=document.getElementById('elcf-enrol-checklist');
  if(host){
    host.innerHTML=(people||[]).map(function(p,i){
      var nm=personFullName(p);var checked=selected.includes(nm)?' checked':'';
      return '<label style="display:grid;grid-template-columns:18px 1fr;gap:8px;align-items:start;padding:8px 10px;border:1px solid var(--border);border-radius:8px;background:#fff;cursor:pointer">'
        +'<input type="checkbox" class="elc-person-check" value="'+escH(nm)+'"'+checked+' data-auris-generated-onchange="g0359" style="width:16px;height:16px;margin-top:1px;accent-color:var(--green)"/>'
        +'<span><strong style="font-size:12px">'+escH([p.last_name,p.first_name].filter(Boolean).join(', ')||nm)+'</strong>'+(p.job_title?'<span class="muted" style="display:block;font-size:11px">'+escH(p.job_title)+'</span>':'')+'</span></label>';
    }).join('')||'<div class="muted" style="padding:10px">No people found in the People register.</div>';
  }
  elcSyncPeopleSelectFromChecks();
}
function elcSyncPeopleSelectFromChecks(){
  var checks=Array.from(document.querySelectorAll('.elc-person-check'));
  var selected=checks.filter(function(c){return c.checked;}).map(function(c){return c.value;});
  var s=document.getElementById('elcf-enrol-people');
  if(s)Array.from(s.options||[]).forEach(function(o){o.selected=selected.includes(o.value);});
  var c=document.getElementById('elc-selected-count');if(c)c.textContent=selected.length+' selected';
}
function elcToggleAllPeople(on){
  document.querySelectorAll('.elc-person-check').forEach(function(c){c.checked=!!on;});
  elcSyncPeopleSelectFromChecks();
}
