async function dashLoadMyElearning(){
  var host=document.getElementById('dp-my-elearning');if(!host)return;
  host.innerHTML='<div class="loading-msg">Loading...</div>';
  var keys=dashMyElearningNames();
  if(!keys.length){host.innerHTML='<div class="empty">No user profile matched for e-learning.</div>';return;}
  var courses=elcAllData&&elcAllData.length?elcAllData:await api('/elearning_courses?company_id=eq.'+ccid()+'&select=*').catch(function(){return [];});
  elcAllData=courses||[];
  var rows=await api('/elearning_enrolments?company_id=eq.'+ccid()+'&select=*&order=target_date.asc').catch(function(){return [];});
  var mine=(rows||[]).filter(function(x){var p=String(x.person_name||'').trim().toLowerCase();return p&&keys.includes(p);}).filter(function(x){return !['cancelled','archived'].includes(String(x.status||'').toLowerCase());});
  if(!mine.length){host.innerHTML='<div style="padding:18px;text-align:center;color:var(--text2);font-size:12px">No e-learning assigned to you.</div>';return;}
  var today=new Date().toISOString().slice(0,10);
  host.innerHTML=mine.slice(0,5).map(function(x){
    var course=elcCourseById(x.course_id)||{};
    var status=String(x.status||'enrolled').toLowerCase();
    var done=status==='completed';
    var due=x.target_date||x.due_date||'No target date';
    var overdue=!done&&x.target_date&&x.target_date<today;
    var cert=done?eleTrainingCertificateRef(x):'';
    var tone=done?'#DCFCE7':overdue?'#FEE2E2':'#EFF6FF';
    var color=done?'#166534':overdue?'#991B1B':'#185FA5';
    return '<div style="border:1px solid var(--border);border-left:4px solid '+color+';border-radius:10px;padding:10px 12px;margin-bottom:8px;background:#fff">'
      +'<div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap">'
      +'<div style="min-width:0;flex:1"><div style="font-weight:800;font-size:13px;color:var(--text);white-space:normal">'+escH(elcCourseLabel(x.course_id))+'</div>'
      +'<div style="font-size:11px;color:var(--text2);margin-top:3px">Target: '+escH(due)+(x.completion_date?' - Completed: '+escH(x.completion_date):'')+(cert?' - Certificate: '+escH(cert):'')+'</div></div>'
      +'<span class="pill" style="background:'+tone+';color:'+color+'">'+escH(done?'Completed':(overdue?'Overdue':(x.status||'Assigned')))+'</span></div>'
      +'<div style="display:flex;gap:6px;margin-top:9px;flex-wrap:wrap">'
      +(course.course_url?'<button class="btn btn-sm" data-auris-runtime-onclick="r0117" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id]))+'"><i class="ti ti-player-play"></i>'+escH(done?'Review':'Watch')+'</button>':'')
      +(!done&&eleWatchFinished(x)&&isMgr()?'<button class="btn btn-sm btn-primary" data-auris-runtime-onclick="r0118" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id]))+'"><i class="ti ti-certificate"></i>Issue certificate</button>':'')
      +'</div></div>';
  }).join('')+(mine.length>5?'<button class="btn btn-sm" data-auris-generated-onclick="g0361">View all assigned courses</button>':'');
}
async function dashCompleteElearning(id){
  try{
    var rows=await api('/elearning_enrolments?id=eq.'+id+'&select=*');var x=rows?.[0];if(!x)return;
    if(!eleWatchFinished(x)){toast('Please watch the full video first. The certificate unlocks after full viewing.',false);return;}
    var today=new Date().toISOString().slice(0,10);var c=elcCourseById(x.course_id)||{};
    var completion=x.completion_date||today;
    var body={status:'completed',completion_date:completion,updated_at:new Date().toISOString(),certificate_ref:eleTrainingCertificateRef(Object.assign({},x,{completion_date:completion})),certificate_issued_at:new Date().toISOString(),valid_from:completion};
    if(!x.attempts)body.attempts=1;
    if(!x.expiry_date)body.expiry_date=eleAddMonthsISO(completion,parseInt(c.validity_months,10)||12);
    try{await elePatchWithTrackingFallback(id,body);}
    catch(e){if(!/schema cache|column|Could not find/i.test(e.message||''))throw e;await api('/elearning_enrolments?id=eq.'+id,{m:'PATCH',p:'return=minimal',b:{status:'completed',completion_date:completion,updated_at:body.updated_at}});}
    await eleSyncCompletedTraining(Object.assign({},x,body)).catch(function(){return false;});
    auditLogEvent('complete','training','E-learning completed from dashboard',{person_name:x.person_name,course:elcCourseLabel(x.course_id)},{related_table:'elearning_enrolments',related_id:id,company_id:ccid()});
    toast('E-learning completed. Certificate added to training records.');
    dashLoadMyElearning();
    if(typeof loadDash==='function')setTimeout(loadDash,250);
  }catch(e){toast(actionErrorMessage('Complete e-learning','Training register',e.message),false);}
}
function eleBaseBody(g,person){var body={company_id:ccid(),person_name:person,department:g('elef-dept'),course_id:g('elef-course-id')||null,enrolment_date:g('elef-enrol-date')||null,completion_date:g('elef-comp-date')||null,status:g('elef-status')||'enrolled',updated_at:new Date().toISOString()};return Object.assign(body,personIdentityPayload(person));}
function eleFullBody(g,person){
  var body=eleBaseBody(g,person);
  body.target_date=g('elef-target-date')||null;body.score=parseInt(g('elef-score'))||null;body.expiry_date=g('elef-expiry')||null;body.attempts=parseInt(g('elef-attempts'))||null;body.time_spent_minutes=parseInt(g('elef-time'))||null;
  if(String(body.status||'').toLowerCase()==='completed'){
    if(!body.completion_date)body.completion_date=new Date().toISOString().slice(0,10);
    if(!body.expiry_date)body.expiry_date=eleAddMonthsISO(body.completion_date,12);
    body.certificate_ref=eleTrainingCertificateRef(body);
    body.certificate_issued_at=new Date().toISOString();
    body.valid_from=body.completion_date;
  }
  return body;
}
function eleTrainingCertificateRef(body){
  var c=elcCourseById(body.course_id);
  var code=String(c?.course_code||c?.title||'ELC').toUpperCase().replace(/[^A-Z0-9]+/g,'').slice(0,10)||'ELC';
  var year=String(body.completion_date||new Date().toISOString()).slice(0,4);
  return 'ELC-'+code+'-'+year;
}
async function eleSyncCompletedTraining(body){
  if(String(body.status||'').toLowerCase()!=='completed'||!body.completion_date)return false;
  var topic=elcCourseLabel(body.course_id);
  var person=body.person_name||'';
  var existing=await api('/training_followup?company_id=eq.'+ccid()+'&person_name=eq.'+encodeURIComponent(person)+'&training_topic=eq.'+encodeURIComponent(topic)+'&training_date=eq.'+encodeURIComponent(body.completion_date)+'&select=id&limit=1').catch(function(){return [];});
  if(existing&&existing.length)return false;
  var p=trainPersonByName(person)||personByDisplayName(person);
  await api('/training_followup',{m:'POST',p:'return=minimal',b:{
    company_id:ccid(),
    person_id:p?.id||null,
    person_name:person,
    training_topic:topic,
    training_date:body.completion_date,
    trainer:'E-learning',
    certificate:eleTrainingCertificateRef(body),
    expiry_date:body.expiry_date||null,
    refresher_due:body.expiry_date||null,
    score:body.score||null,
    passed:true,
    notes:'Automatically created from e-learning completion'+(body.target_date?' (target date: '+body.target_date+')':''),
    created_by:prof?.id,
    updated_at:new Date().toISOString()
  }});
  return true;
}
async function eleQueueAssignmentNotice(body){
  if(window.eleEditId)return false;
  var p=trainPersonByName(body.person_name)||personByDisplayName(body.person_name);
  var email=usersContactEmail(p);
  if(!email)return false;
  var course=body.course_title||elcCourseLabel(body.course_id);
  var due=body.target_date||body.completion_date||'to be confirmed';
  await queueNotification({
    company_id:ccid(),
    type:'training',
    subject:'[AURIS360] E-learning assigned: '+course,
    body_html:'<p>Hello '+escH(body.person_name||'')+',</p><p>You have been assigned the e-learning course <strong>'+escH(course)+'</strong>.</p><p>Target completion date: <strong>'+escH(due)+'</strong>.</p><p>Please log in to AURIS360 to complete the course.</p>',
    to_email:email,
    to_name:body.person_name,
    from_name:'AURIS360 Training',
    related_module:'training',
    related_table:'elearning_enrolments',
    related_id:body.id||null,
    related_ref:body.enrolment_ref||body.reference||course
  });
  return true;
}
async function eleSave(){ var person=document.getElementById('elef-person')?.value?.trim();if(!person){toast('Please enter person name',false);return;}var g=function(id){var el=document.getElementById(id);return el?el.value||null:null;};eleStatusChange();var body=eleFullBody(g,person);var enrolId=window.eleEditId||null;try{if(window.eleEditId){await apiWriteWithMissingColumnFallback('/elearning_enrolments?id=eq.'+window.eleEditId,{m:'PATCH',p:'return=minimal',b:body},'E-learning enrolment');}else{body.created_by=prof?.id;var created=await apiWriteWithMissingColumnFallback('/elearning_enrolments',{m:'POST',p:'return=representation',b:body},'E-learning enrolment');enrolId=created?.[0]?.id||null;await eleQueueAssignmentNotice(Object.assign({},body,{id:enrolId})).catch(function(){});}var added=await eleSyncCompletedTraining(body).catch(function(){return false;});trainingAudit(body.status==='completed'?'complete':(window.eleEditId?'update':'assign'),body.status==='completed'?'E-learning completed':(window.eleEditId?'E-learning enrolment updated':'E-learning enrolment assigned'),'elearning_enrolments',Object.assign({id:enrolId},body,{course_title:elcCourseLabel(body.course_id)}),{training_record_added:!!added});toast((window.eleEditId?'Updated!':'Enrolment saved!')+(added?' Training record added.':''));eleBack();}catch(e){toast(actionErrorMessage('Save e-learning enrolment','Training register',e.message),false);} }
async function eleDelete(){ if(!window.eleEditId)return;try{var rows=await api('/elearning_enrolments?id=eq.'+window.eleEditId+'&select=*');var row=(rows&&rows[0])||{id:window.eleEditId};var status=String(row.status||'').toLowerCase();if(!['cancelled','archived'].includes(status)){if(!(await appConfirmAction({title:'Cancel enrolment',message:'Cancel this e-learning enrolment instead of deleting it?',detail:'The enrolment remains linked to the person and course for training history.',confirmText:'Cancel enrolment',cancelText:'Back'})))return;await api('/elearning_enrolments?id=eq.'+window.eleEditId,{m:'PATCH',p:'return=minimal',b:{status:'cancelled',updated_at:new Date().toISOString()}});trainingAudit('cancel','E-learning enrolment cancelled','elearning_enrolments',Object.assign({},row,{status:'cancelled'}),{previous_status:row.status||null});toast('Enrolment cancelled');eleBack();return;}if(!(await appConfirmDelete('e-learning enrolment','This enrolment is already cancelled/archived. Permanent deletion should be used only for duplicate/test records.')))return;await api('/elearning_enrolments?id=eq.'+window.eleEditId,{m:'DELETE'});trainingAudit('delete','E-learning enrolment permanently deleted','elearning_enrolments',row,{previous_status:row.status||null});toast('Deleted!');eleBack();}catch(e){toast(actionErrorMessage('Delete e-learning enrolment','Training register',e.message),false);} }
