function eleCertificateDisplay(x){
  if(String(x?.status||'').toLowerCase()!=='completed')return '-';
  return eleTrainingCertificateRef(x||{});
}
function eleTimeframeState(x){
  var status=String(x?.status||'enrolled').toLowerCase();
  var due=x?.target_date||x?.due_date||'';
  var completed=x?.completion_date||'';
  var today=new Date().toISOString().slice(0,10);
  if(status==='completed'){
    if(due&&completed&&completed>due)return {label:'Completed late',bg:'#FEF2F2',color:'#991B1B'};
    return {label:'Completed on time',bg:'#ECFDF5',color:'#065F46'};
  }
  if(['cancelled','archived'].includes(status))return {label:status.replace('_',' '),bg:'#F3F4F6',color:'#4B5563'};
  if(due&&due<today){
    var days=Math.ceil((new Date(today)-new Date(due))/86400000);
    return {label:'Overdue '+days+'d',bg:'#FEF2F2',color:'#991B1B'};
  }
  if(due){
    var left=Math.ceil((new Date(due)-new Date(today))/86400000);
    return {label:left<=7?'Due soon':'On target',bg:left<=7?'#FFFBEB':'#EFF6FF',color:left<=7?'#854F0B':'#185FA5'};
  }
  return {label:'No target date',bg:'#F3F4F6',color:'#4B5563'};
}
