// ===================================================================
// PWA - Service Worker registration & install prompt
// ===================================================================

var _pwaInstallPrompt = null;
function pwaIsIOSDevice(){
  return /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform==='MacIntel' && navigator.maxTouchPoints>1);
}
function pwaIsStandalone(){
  return window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone===true;
}
function pwaRefreshInstallButton(){
  var installBtn = document.getElementById('pwa-install-btn');
  if(!installBtn)return;
  var shouldShow = !pwaIsStandalone() && (!!_pwaInstallPrompt || pwaIsIOSDevice());
  installBtn.style.display = shouldShow ? 'flex' : 'none';
  installBtn.title = pwaIsIOSDevice() ? 'Install on iPad/iPhone using Share > Add to Home Screen' : 'Install AURIS360 as an app';
}
function pwaEscapeHtml(value){
  return String(value || '').replace(/[&<>"']/g, function(ch){
    return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[ch];
  });
}
function pwaShowInstallInstructions(isIOS){
  var existing = document.getElementById('pwa-install-help-modal');
  if(existing) existing.remove();

  var steps = isIOS ? [
    'Open AURIS360 in Safari on your iPad or iPhone.',
    'Tap the Share button in the browser toolbar.',
    'Choose Add to Home Screen from the share menu.',
    'Tap Add. AURIS360 will appear like an app on the home screen.'
  ] : [
    'Open AURIS360 in Chrome or Edge on your device.',
    'Tap the browser menu button.',
    'Choose Install app or Add to Home Screen.',
    'Confirm the installation when prompted.'
  ];

  var modal = document.createElement('div');
  modal.id = 'pwa-install-help-modal';
  modal.setAttribute('role', 'dialog');
  modal.setAttribute('aria-modal', 'true');
  modal.style.cssText = 'position:fixed;inset:0;z-index:10000;background:rgba(15,23,42,.48);display:flex;align-items:center;justify-content:center;padding:20px;';
  modal.innerHTML =
    '<div style="width:min(520px,100%);background:#fff;border-radius:16px;box-shadow:0 24px 70px rgba(15,23,42,.25);overflow:hidden;">' +
      '<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 20px;background:#109873;color:#fff;">' +
        '<div>' +
          '<div style="font-size:18px;font-weight:800;">Install AURIS360</div>' +
          '<div style="font-size:13px;opacity:.9;">' + (isIOS ? 'iPad / iPhone setup' : 'Mobile app setup') + '</div>' +
        '</div>' +
        '<button type="button" data-pwa-close style="border:0;background:rgba(255,255,255,.18);color:#fff;border-radius:10px;width:36px;height:36px;font-size:22px;line-height:1;cursor:pointer;">&times;</button>' +
      '</div>' +
      '<div style="padding:20px;">' +
        '<div style="display:grid;gap:12px;">' +
          steps.map(function(step, idx){
            return '<div style="display:grid;grid-template-columns:34px 1fr;gap:12px;align-items:start;">' +
              '<div style="width:34px;height:34px;border-radius:999px;background:#e7f7f1;color:#08775b;display:flex;align-items:center;justify-content:center;font-weight:800;">' + (idx + 1) + '</div>' +
              '<div style="font-size:14px;color:#334155;line-height:1.45;padding-top:6px;">' + pwaEscapeHtml(step) + '</div>' +
            '</div>';
          }).join('') +
        '</div>' +
        '<div style="margin-top:18px;padding:12px 14px;border:1px solid #dbeafe;background:#eff6ff;border-radius:12px;color:#1e3a8a;font-size:13px;line-height:1.45;">Installing AURIS360 gives users a cleaner full-screen experience and quick access from the home screen.</div>' +
        '<div style="margin-top:18px;display:flex;justify-content:flex-end;gap:10px;">' +
          '<button type="button" data-pwa-close class="btn" style="min-width:110px;">Close</button>' +
        '</div>' +
      '</div>' +
    '</div>';

  modal.addEventListener('click', function(e){
    if(e.target === modal || e.target.closest('[data-pwa-close]')) modal.remove();
  });
  document.body.appendChild(modal);
}

// Register service worker
if('serviceWorker' in navigator) {
  var aurisRefreshingForUpdate = false;
  navigator.serviceWorker.addEventListener('controllerchange', function() {
    if(aurisRefreshingForUpdate) return;
    aurisRefreshingForUpdate = true;
    window.location.reload();
  });
  window.addEventListener('load', function() {
    navigator.serviceWorker.register('/sw.js')
      .then(function(reg) {
        console.log('AURIS360 SW registered:', reg.scope);
        reg.update();
        // Check for updates every 10 minutes
        setInterval(function() { reg.update(); }, 10 * 60 * 1000);
        // When a new SW is waiting, prompt user to update
        reg.addEventListener('updatefound', function() {
          var newWorker = reg.installing;
          if(!newWorker) return;
          newWorker.addEventListener('statechange', function() {
            if(newWorker.state === 'installed' && navigator.serviceWorker.controller) {
              // New version available
              if(typeof toast === 'function') {
                toast('AURIS360 update installed - refreshing once');
              }
              // skipWaiting() causes controllerchange; that single handler is
              // the authoritative reload path and prevents a double refresh.
            }
          });
        });
      })
      .catch(function(err) {
        console.warn('AURIS360 SW registration failed:', err);
      });
  });
}

// Capture install prompt (Android/Chrome)
window.addEventListener('beforeinstallprompt', function(e) {
  e.preventDefault();
  _pwaInstallPrompt = e;
  // Show install button in sidebar if visible
  pwaRefreshInstallButton();
});

// Handle app installed event
window.addEventListener('appinstalled', function() {
  _pwaInstallPrompt = null;
  pwaRefreshInstallButton();
  if(typeof toast === 'function') toast('AURIS360 installed as app');
});

// Show PWA install prompt
function pwaInstall() {
  if(!_pwaInstallPrompt) {
    pwaShowInstallInstructions(pwaIsIOSDevice());
    return;
  }
  _pwaInstallPrompt.prompt();
  _pwaInstallPrompt.userChoice.then(function(result) {
    if(result.outcome === 'accepted') {
      if(typeof toast === 'function') toast('AURIS360 installed');
    }
    _pwaInstallPrompt = null;
    pwaRefreshInstallButton();
  });
}

window.addEventListener('load', pwaRefreshInstallButton);

// Record-aware deep-link router (AP-040). The request is captured before
// authentication and retained through login, role preview and company context
// changes until the exact record opens or the user dismisses the request.
var DEEP_LINK_STORAGE_KEY='auris360_pending_deep_link_v1';
var pendingDeepLinkRequest=null;
var deepLinkOpening=false;
var deepLinkLastAttempt=0;
var DEEP_LINK_DEFAULT_TABLES={
  events:'events',event:'events',investigation:'investigations',observation:'safety_observations',inspection:'inspections',
  risk:'risk_assessments',permit:'permits',meetings:'toolbox_talks',legal:'legal_requirements',chemical:'chemical_register',fire:'fire_equipment',ppe:'ppe_catalogue',
  tools:'tools_register',atex:'atex_areas',contractor:'contractors',noise:'noise_surveys',training:'training_followup',
  actions:'action_tracker',action:'action_tracker',moc:'moc_change_requests',documents:'documents',sop:'sop_video_projects',swms:'documents'
};
function deepLinkNormalise(raw){
  raw=raw||{};
  var moduleName=String(raw.goto||raw.module||'').toLowerCase().trim();
  if(!/^[a-z0-9_-]{1,64}$/.test(moduleName))return null;
  var clean=function(v,max){v=String(v||'').trim();return v&&v.length<=(max||180)?v:'';};
  return {goto:moduleName,record:clean(raw.record||raw.id,180),ref:clean(raw.ref,240),table:clean(raw.table,80).toLowerCase(),company:clean(raw.company,80),captured_at:raw.captured_at||new Date().toISOString()};
}
function deepLinkReadUrl(){
  try{var q=new URLSearchParams(window.location.search);if(!q.get('goto'))return null;return deepLinkNormalise({goto:q.get('goto'),record:q.get('record'),ref:q.get('ref'),table:q.get('table'),company:q.get('company')});}catch(_){return null;}
}
function deepLinkReadStored(){try{return deepLinkNormalise(JSON.parse(sessionStorage.getItem(DEEP_LINK_STORAGE_KEY)||'null'));}catch(_){return null;}}
function deepLinkStore(req){pendingDeepLinkRequest=req||null;try{if(req)sessionStorage.setItem(DEEP_LINK_STORAGE_KEY,JSON.stringify(req));else sessionStorage.removeItem(DEEP_LINK_STORAGE_KEY);}catch(_){}}
function deepLinkCaptureRequest(){var req=deepLinkReadUrl()||pendingDeepLinkRequest||deepLinkReadStored();if(req)deepLinkStore(req);return req;}
function deepLinkClear(removeQuery){
  deepLinkStore(null);
  var notice=document.getElementById('deep-link-notice');if(notice)notice.remove();
  if(removeQuery!==false)try{var url=new URL(window.location.href);['goto','record','ref','table','company'].forEach(function(k){url.searchParams.delete(k);});history.replaceState(null,'',url.pathname+(url.search||'')+(url.hash||''));}catch(_){}
}
function deepLinkShowNotice(message,retry){
  try{var failed=pendingDeepLinkRequest||deepLinkReadStored();rolloutRecordHealthEvent('failed_deep_link',{module_key:failed?.goto||'',record_table:failed?.table||null,record_id:failed?.record||null,record_ref:failed?.ref||null,fingerprint:['deep-link',failed?.goto||'',failed?.record||'',String(message||'').slice(0,80)].join(':'),detail:{reason:String(message||'').slice(0,500),retryable:!!retry}});}catch(_){}
  var el=document.getElementById('deep-link-notice');
  if(!el){el=document.createElement('div');el.id='deep-link-notice';el.style.cssText='position:fixed;right:18px;top:84px;z-index:940;max-width:470px;background:#fff;border:1px solid #F5B7B1;border-left:5px solid #DC2626;border-radius:10px;padding:12px 14px;box-shadow:0 12px 34px rgba(15,23,42,.22);font-size:12px;color:#334155';document.body.appendChild(el);}
  el.innerHTML='<div style="font-weight:900;color:#991B1B;margin-bottom:4px"><i class="ti ti-link-off"></i> Linked record could not be opened</div><div>'+escH(message)+'</div><div style="display:flex;gap:7px;justify-content:flex-end;margin-top:9px">'+(retry?'<button class="btn btn-sm" data-auris-generated-onclick="g0362"><i class="ti ti-refresh"></i>Retry</button>':'')+'<button class="btn btn-sm" data-auris-generated-onclick="g0363">Dismiss</button></div>';
}
function deepLinkPage(req){
  if(req.goto==='prestart')return 'inspection';
  if(req.goto==='action'||req.goto==='actions')return 'actions';
  var adapter=typeof mapSourceAdapter==='function'?mapSourceAdapter({source_module:req.goto,source_ref:req.ref||'',source_table:req.table||''}):null;
  return adapter&&adapter.page?adapter.page:req.goto;
}
function deepLinkRecordUrl(endpoint){
  endpoint=endpoint||{};var url=new URL(window.location.origin+window.location.pathname);
  url.searchParams.set('goto',endpoint.module||endpoint.goto||'dashboard');
  if(endpoint.id||endpoint.record)url.searchParams.set('record',endpoint.id||endpoint.record);
  if(endpoint.ref)url.searchParams.set('ref',endpoint.ref);
  if(endpoint.table)url.searchParams.set('table',endpoint.table);
  if(endpoint.company_id||endpoint.company)url.searchParams.set('company',endpoint.company_id||endpoint.company);
  return url.toString();
}
function deepLinkScheduleResume(reason){
  // Authentication, company context and responsive navigation initialise in
  // parallel. Retry at bounded intervals so a valid link cannot be lost to a
  // one-shot timing race; successful navigation clears the stored request.
  [120,500,1200,2400].forEach(function(delay){
    setTimeout(function(){
      var pending=deepLinkReadUrl()||pendingDeepLinkRequest||deepLinkReadStored();
      if(!pending||!prof||typeof deepLinkResume!=='function')return;
      Promise.resolve(deepLinkResume((reason||'navigation')+'-'+delay)).catch(function(){});
    },delay);
  });
}
async function deepLinkResume(reason){
  var req=deepLinkCaptureRequest();
  if(!req||!prof||typeof showPage!=='function'||deepLinkOpening)return false;
  if(Date.now()-deepLinkLastAttempt<350)return false;
  deepLinkLastAttempt=Date.now();deepLinkOpening=true;
  try{
    var page=deepLinkPage(req);
    if(!document.getElementById('page-'+page)){
      deepLinkShowNotice('The link targets an unknown AURIS360 module ('+req.goto+').',false);return false;
    }
    if(!canAccessPage(page)){
      deepLinkShowNotice('Your current role does not have access to '+page.replace(/-/g,' ')+'. Ask an administrator for access or select an authorised role.',true);return false;
    }
    if(req.company&&isSA()&&saCompanyGetContext()!==req.company){saCompanySetContext(req.company);await new Promise(function(resolve){setTimeout(resolve,180);});}
    showPage(page,null);
    if(req.goto==='prestart'){
      await new Promise(function(resolve){setTimeout(resolve,180);});
      var prestart=document.getElementById('insp-tab-prestart');if(prestart&&typeof auditSwitchTab==='function')auditSwitchTab('prestart',prestart);
      deepLinkClear(true);return true;
    }
    if(!req.record){deepLinkClear(true);return true;}
    await new Promise(function(resolve){setTimeout(resolve,360);});
    var opened=false;
    if(page==='actions'&&typeof mapEdit==='function'){await mapEdit(req.record);opened=String(typeof mapEditingId!=='undefined'?mapEditingId:'')===String(req.record);}
    else{
      var source={source_module:req.goto,source_type:req.goto,source_table:req.table||DEEP_LINK_DEFAULT_TABLES[req.goto]||'',source_id:req.record,source_ref:req.ref||req.record};
      var adapter=mapSourceAdapter(source);
      if(adapter)opened=await mapOpenExactSource(adapter,source);
      if(!opened&&req.ref)mapApplySourceSearch(page,req.ref);
    }
    if(opened){
      try{auditLogEvent('open','deep_link','Record-aware link opened',{goto:req.goto,record:req.record,ref:req.ref,table:req.table,reason:reason||'navigation'},{related_table:req.table||null,related_id:req.record,company_id:ccid()});}catch(_){}
      toast('Opened '+(req.ref||'the linked record')+'.');deepLinkClear(true);return true;
    }
    var context=isSA()?' Confirm the correct company is selected, then retry.':' The record may be unavailable, archived, or outside your company access.';
    deepLinkShowNotice('AURIS360 opened the '+page.replace(/-/g,' ')+' module but could not open '+(req.ref||req.record)+'.'+context,true);
    return false;
  }catch(e){deepLinkShowNotice('The linked record could not be opened: '+(e.message||e),true);return false;}
  finally{deepLinkOpening=false;}
}
deepLinkCaptureRequest();
window.addEventListener('load',function(){deepLinkScheduleResume('page-load');});

// Offline field reporting queue - Phase 1
const OFFLINE_QUEUE_KEY='auris360_offline_queue_v1';
var offlineSyncInFlight=false;
function offlineQueueRead(){
  try{return JSON.parse(localStorage.getItem(OFFLINE_QUEUE_KEY)||'[]')||[];}catch(_){return [];}
}
function offlineDraftCompanyId(item){return String(item?.company_id||item?.body?.company_id||'');}
function offlineDraftCanSync(item,companyId){return !!companyId&&offlineDraftCompanyId(item)===String(companyId);}
function offlineDraftDeduplicate(items){
  var seen={};return (items||[]).filter(function(item){
    var id=String(item?.local_id||'');if(!id)return true;if(seen[id])return false;seen[id]=true;return true;
  });
}
function offlineQueueWrite(items){
  try{localStorage.setItem(OFFLINE_QUEUE_KEY,JSON.stringify(offlineDraftDeduplicate(items||[])));}catch(e){toast('Could not save offline draft: device storage is full',false);}
  offlineRefreshBanner();
  if(typeof offlineRenderQueueSettings==='function')offlineRenderQueueSettings();
}
function offlineIsNetworkError(e){
  var msg=String(e?.message||e||'').toLowerCase();
  return !navigator.onLine || msg.includes('failed to fetch') || msg.includes('network') || msg.includes('load failed') || msg.includes('timeout');
}
function offlineQueueAdd(item){
  var q=offlineQueueRead();
  item.local_id=item.local_id||('offline-'+Date.now()+'-'+Math.random().toString(16).slice(2));
  item.created_at=item.created_at||new Date().toISOString();
  item.status='pending';
  q.push(item);
  offlineQueueWrite(q);
  return item.local_id;
}
function offlineBlobToDataUrl(blob){
  return new Promise(function(resolve,reject){
    var r=new FileReader();
    r.onload=function(){resolve(r.result);};
    r.onerror=function(){reject(r.error||new Error('Could not read photo'));};
    r.readAsDataURL(blob);
  });
}
function offlineImageFromDataUrl(dataUrl){
  return new Promise(function(resolve,reject){
    var img=new Image();
    img.onload=function(){resolve(img);};
    img.onerror=function(){reject(new Error('Could not process photo'));};
    img.src=dataUrl;
  });
}
function offlineCanvasToBlob(canvas,type,quality){
  return new Promise(function(resolve){
    canvas.toBlob(function(blob){resolve(blob);},type||'image/jpeg',quality||0.75);
  });
}
async function offlineCompressPhoto(file){
  var original=await offlineBlobToDataUrl(file);
  var img=await offlineImageFromDataUrl(original);
  var maxSide=1600;
  var scale=Math.min(1,maxSide/Math.max(img.width||maxSide,img.height||maxSide));
  var w=Math.max(1,Math.round((img.width||maxSide)*scale));
  var h=Math.max(1,Math.round((img.height||maxSide)*scale));
  var canvas=document.createElement('canvas');
  canvas.width=w;canvas.height=h;
  var ctx=canvas.getContext('2d');
  ctx.drawImage(img,0,0,w,h);
  var blob=await offlineCanvasToBlob(canvas,'image/jpeg',0.74);
  return {
    name:hseCleanFileName((file.name||'photo').replace(/\.[^.]+$/,'')+'.jpg'),
    type:'image/jpeg',
    size:blob?blob.size:file.size,
    data_url:blob?await offlineBlobToDataUrl(blob):original
  };
}
async function offlineCollectPhotos(files){
  var out=[],total=0;
  files=files||[];
  for(var i=0;i<files.length&&out.length<6;i++){
    try{
      var p=await offlineCompressPhoto(files[i]);
      total+=p.size||0;
      if(total>4.5*1024*1024){toast('Offline photo storage limit reached. Some photos were not kept offline.',false);break;}
      out.push(p);
    }catch(e){toast(actionErrorMessage('Store offline photo','Offline mode',e),false);}
  }
  return out;
}
function offlinePhotoBlob(photo){
  var parts=(photo.data_url||'').split(',');
  var mime=(parts[0].match(/:(.*?);/)||[])[1]||photo.type||'image/jpeg';
  var bin=atob(parts[1]||'');
  var len=bin.length;
  var arr=new Uint8Array(len);
  for(var i=0;i<len;i++)arr[i]=bin.charCodeAt(i);
  var blob=new Blob([arr],{type:mime});
  blob.name=photo.name||'offline-photo.jpg';
  return blob;
}
async function offlineUploadIncidentPhotos(eventId,companyId,incidentRef,photos){
  photos=photos||[];
  for(var i=0;i<photos.length;i++){
    var photo=photos[i],blob=offlinePhotoBlob(photo);
    var path=await hseUploadEvidencePhoto(blob,companyId,'incidents/'+eventId);
    await api('/incident_evidence',{m:'POST',p:'return=minimal',b:{
      company_id:companyId,event_id:eventId,evidence_type:'photo',
      title:'Incident photo - '+(incidentRef||eventId),
      file_url:path,file_name:photo.name||'offline-photo.jpg',file_size:String(photo.size||blob.size||''),
      description:'Synced from offline incident draft',
      collected_by:prof?.full_name||prof?.email||null,
      collected_date:new Date().toISOString().slice(0,10),
      created_by:prof?.id||null
    }});
  }
}
async function offlineUploadObservationPhotos(obsId,companyId,obsRef,photos,existingNotes){
  photos=photos||[];
  if(!photos.length)return;
  var links=[];
  for(var i=0;i<photos.length;i++){
    var photo=photos[i],blob=offlinePhotoBlob(photo);
    var path=await hseUploadEvidencePhoto(blob,companyId,'observations/'+obsId);
    links.push((photo.name||'offline-photo.jpg')+': '+path);
  }
  var note='\n\nPhoto evidence synced from offline draft:\n'+links.map(function(x){return '- '+x;}).join('\n');
  await api('/safety_observations?id=eq.'+obsId,{m:'PATCH',p:'return=minimal',b:{feedback_notes:((existingNotes||'')+note).trim(),updated_at:new Date().toISOString()}});
}
async function offlineQueueIncident(body, operation, remoteId){
  var customValues=[];
  try{customValues=await customCollectRecordValues('events');}catch(_){}
  var photos=[];
  if(typeof imsPendingPhotos!=='undefined'&&imsPendingPhotos&&imsPendingPhotos.length){
    photos=await offlineCollectPhotos(imsPendingPhotos);
    imsClearPhotos();
  }
  offlineQueueAdd({module:'incident',operation:operation||'insert',remote_id:remoteId||null,company_id:body.company_id,body:body,custom_values:customValues,photos:photos});
}
async function offlineQueueObservation(body, operation, remoteId){
  var customValues=[];
  try{customValues=await customCollectRecordValues('observation');}catch(_){}
  var photos=[];
  if(typeof obsPendingPhotos!=='undefined'&&obsPendingPhotos&&obsPendingPhotos.length){
    photos=await offlineCollectPhotos(obsPendingPhotos);
    obsClearPhotos();
  }
  offlineQueueAdd({module:'observation',operation:operation||'insert',remote_id:remoteId||null,company_id:body.company_id,body:body,custom_values:customValues,photos:photos});
}
function offlineEnsureBanner(){
  var el=document.getElementById('offline-sync-banner');
  if(el)return el;
  el=document.createElement('div');
  el.id='offline-sync-banner';
  el.style.cssText='display:none;position:fixed;left:50%;bottom:78px;transform:translateX(-50%);z-index:9999;background:#1a3a5c;color:#fff;border-radius:12px;box-shadow:0 10px 35px rgba(0,0,0,.22);padding:10px 12px;gap:10px;align-items:center;max-width:calc(100vw - 24px);font-size:12px';
  el.innerHTML='<span id="offline-sync-text" style="font-weight:700;white-space:nowrap"></span><button class="btn btn-sm" style="background:#fff;color:#1a3a5c;border-color:#fff" data-auris-generated-onclick="g0364"><i class="ti ti-refresh"></i>Sync now</button>';
  document.body.appendChild(el);
  return el;
}
function offlineRefreshBanner(){
  var q=offlineQueueRead().filter(function(x){return x.status!=='synced';});
  var el=offlineEnsureBanner();
  var txt=document.getElementById('offline-sync-text');
  if(!q.length){el.style.display='none';return;}
  if(txt)txt.textContent=q.length+' offline report'+(q.length>1?'s':'')+' pending';
  el.style.display='flex';
}
async function offlineSyncIncident(item){
  var body=Object.assign({},item.body||{});
  var customValues=item.custom_values||[];
  if(item.operation==='patch'&&item.remote_id){
    await api('/events?id=eq.'+item.remote_id,{m:'PATCH',p:'return=minimal',b:body});
    await customSaveCollectedValues('events',item.remote_id,body.company_id,customValues);
    await offlineUploadIncidentPhotos(item.remote_id,body.company_id,body.event_ref||body.incident_number||item.remote_id,item.photos||[]);
    return item.remote_id;
  }
  body.created_by=body.created_by||prof?.id||null;
  var res=await api('/events',{m:'POST',p:'return=representation',b:body});
  if(res?.[0]?.id){
    var yr=new Date().getFullYear(),seq=1;
    try{
      var existing=await api('/events?select=event_ref&company_id=eq.'+body.company_id+'&event_ref=like.INC-'+yr+'-*&order=event_ref.desc&limit=1');
      var match=existing?.[0]?.event_ref?.match(/INC-\d{4}-(\d+)/);
      if(match)seq=parseInt(match[1])+1;
    }catch(_){}
    var ref='INC-'+yr+'-'+String(seq).padStart(4,'0');
    await api('/events?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{event_ref:ref,incident_number:ref}});
    await customSaveCollectedValues('events',res[0].id,body.company_id,customValues);
    await offlineUploadIncidentPhotos(res[0].id,body.company_id,ref,item.photos||[]);
    return res[0].id;
  }
}
async function offlineSyncObservation(item){
  var body=Object.assign({},item.body||{});
  var customValues=item.custom_values||[];
  if(item.operation==='patch'&&item.remote_id){
    await api('/safety_observations?id=eq.'+item.remote_id,{m:'PATCH',p:'return=minimal',b:body});
    await customSaveCollectedValues('safety_observations',item.remote_id,body.company_id,customValues);
    await offlineUploadObservationPhotos(item.remote_id,body.company_id,body.obs_ref||item.remote_id,item.photos||[],body.feedback_notes);
    return item.remote_id;
  }
  body.created_by=body.created_by||prof?.id||null;
  var res=await api('/safety_observations',{m:'POST',p:'return=representation',b:body});
  if(res?.[0]?.id){
    var yr=new Date().getFullYear();
    var typeCode={bbs_observation:'BBS',positive_behaviour:'POS',unsafe_behaviour:'UBA',unsafe_condition:'UCC',near_miss:'NM',good_practice:'GP'}[body.obs_type]||'OBS';
    var ref='OBS-'+typeCode+'-'+yr+'-'+String(Date.now()).slice(-4);
    await api('/safety_observations?id=eq.'+res[0].id,{m:'PATCH',p:'return=minimal',b:{obs_ref:ref}});
    await customSaveCollectedValues('safety_observations',res[0].id,body.company_id,customValues);
    await offlineUploadObservationPhotos(res[0].id,body.company_id,ref,item.photos||[],body.feedback_notes);
    return res[0].id;
  }
}
async function offlineSyncNow(){
  if(offlineSyncInFlight){toast('Offline synchronization is already running.');return;}
  if(!navigator.onLine){toast('Still offline. Sync will work when internet returns.',false);return;}
  offlineSyncInFlight=true;
  try{
  var q=offlineQueueRead();
  var activeCompany=ccid();
  var pending=q.filter(function(x){return x.status!=='synced'&&offlineDraftCanSync(x,activeCompany);});
  if(!pending.length){offlineRefreshBanner();toast('No offline reports pending');return;}
  toast('Syncing '+pending.length+' offline report'+(pending.length>1?'s':'')+'...');
  var ok=0,failed=0;
  for(var i=0;i<q.length;i++){
    var item=q[i];
    if(item.status==='synced')continue;
    if(!offlineDraftCanSync(item,activeCompany))continue;
    try{
      if(item.module==='incident')await offlineSyncIncident(item);
      else if(item.module==='observation')await offlineSyncObservation(item);
      else continue;
      item.status='synced';item.synced_at=new Date().toISOString();ok++;
    }catch(e){
      item.status='pending';item.last_error=e.message||'Sync failed';failed++;
    }
  }
  offlineQueueWrite(q.filter(function(x){return x.status!=='synced';}));
  if(ok)toast(ok+' offline report'+(ok>1?'s':'')+' synced');
  if(failed)toast(failed+' offline report'+(failed>1?'s':'')+' still pending',false);
  if(ok||failed)auditLogEvent('sync','offline','Offline drafts sync completed',{synced:ok,failed:failed});
  offlineRenderQueueSettings();
  }finally{offlineSyncInFlight=false;}
}
window.addEventListener('load', offlineRefreshBanner);
function offlineDraftLabel(item){
  var b=item.body||{};
  if(item.module==='incident')return 'Incident - '+(b.description||b.event_type||'Draft incident').toString().slice(0,80);
  if(item.module==='observation')return 'BBS - '+(b.observation_text||b.unsafe_act_description||b.unsafe_condition_description||'Draft observation').toString().slice(0,80);
  return 'Offline draft';
}
function offlineRenderQueueSettings(){
  var el=document.getElementById('offline-drafts-body');if(!el)return;
  var q=offlineQueueRead().filter(function(x){return x.status!=='synced';});
  if(!q.length){
    el.innerHTML='<div style="padding:20px;text-align:center;color:var(--text2);border:1px dashed var(--border);border-radius:10px">No offline drafts pending.</div>';
    return;
  }
  el.innerHTML='<div class="table-scroll"><table class="data-table" style="min-width:760px"><thead><tr><th>Draft</th><th>Created</th><th>Photos</th><th>Status</th><th>Actions</th></tr></thead><tbody>'
    +q.map(function(x){
      var b=x.body||{};
      return '<tr style="border-bottom:1px solid var(--border)">'
        +'<td style="padding:9px"><div style="font-weight:800">'+escH(offlineDraftLabel(x))+'</div><div style="color:var(--text2);font-size:11px">'+escH(b.location||b.department||x.module||'')+'</div></td>'
        +'<td style="padding:9px;color:var(--text2)">'+(x.created_at?new Date(x.created_at).toLocaleString():'-')+'</td>'
        +'<td style="padding:9px;text-align:center">'+((x.photos||[]).length||0)+'</td>'
        +'<td style="padding:9px">'+(x.last_error?'<span style="color:var(--red);font-weight:700">'+escH(x.last_error)+'</span>':'<span style="color:#854F0B;font-weight:700">Pending</span>')+'</td>'
        +'<td style="padding:9px;text-align:right;white-space:nowrap"><button class="btn btn-sm" data-auris-runtime-onclick="r0125" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.local_id]))+'"><i class="ti ti-refresh"></i>Retry</button> <button class="btn btn-sm" data-auris-runtime-onclick="r0126" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.local_id]))+'" style="color:var(--red)"><i class="ti ti-trash"></i></button></td>'
        +'</tr>';
    }).join('')+'</tbody></table></div>';
}
async function offlineRetryDraft(localId){
  if(!navigator.onLine){toast('Still offline. Retry when internet is back.',false);return;}
  var q=offlineQueueRead();
  var item=q.find(function(x){return x.local_id===localId;});
  if(!item){toast('Offline draft not found',false);offlineRenderQueueSettings();return;}
  if(!offlineDraftCanSync(item,ccid())){
    toast('Switch to the company where this draft was created before syncing it.',false);return;
  }
  try{
    if(item.module==='incident')await offlineSyncIncident(item);
    else if(item.module==='observation')await offlineSyncObservation(item);
    else throw new Error('Unsupported offline draft type');
    offlineQueueWrite(q.filter(function(x){return x.local_id!==localId;}));
    toast('Offline draft synced');
  }catch(e){
    item.last_error=e.message||'Sync failed';
    offlineQueueWrite(q);
    toast(item.last_error,false);
  }
}
async function offlineDeleteDraft(localId){
  var ok=await appConfirm({title:'Delete offline draft',message:'Delete this locally saved draft?',detail:'This cannot be recovered if it has not synced yet.',confirmText:'Delete draft',cancelText:'Keep draft',danger:true});
  if(!ok)return;
  offlineQueueWrite(offlineQueueRead().filter(function(x){return x.local_id!==localId;}));
  toast('Offline draft deleted');
}

// Online/offline status notification
window.addEventListener('online', function() {
  offlineSyncNow();
  if(typeof toast === 'function') toast('Back online');
  // Trigger background sync if supported
  if('serviceWorker' in navigator && 'SyncManager' in window) {
    navigator.serviceWorker.ready.then(function(reg) {
      reg.sync.register('sync-incidents').catch(function(){});
      reg.sync.register('sync-observations').catch(function(){});
    });
  }
});
if('serviceWorker' in navigator){
  navigator.serviceWorker.addEventListener('message',function(event){
    if(event.data&&event.data.type==='SYNC_REQUEST')offlineSyncNow();
  });
}
window.addEventListener('offline', function() {
  if(typeof toast === 'function') toast('You are offline - data will sync when reconnected', false);
});




