var MODULE_COLORS = {
  dashboard:'#185FA5', executive:'#5B21B6', kpi:'#185FA5',
  workschedule:'#065F46', events:'#DC2626', observation:'#9A3412',
  inspection:'#1D9E75', risk:'#C2410C', tools:'#374151', fleet:'#185FA5', atex:'#C2410C', sitemap:'#0F6E56',
  moc:'#0F6E56',
  permit:'#854F0B', contractor:'#0891B2', emergency:'#DC2626', fire:'#B91C1C', chemical:'#7C3AED',
  ohealth:'#065F46', ppe:'#1D9E75', esg:'#065F46',
  noise:'#EF9F27', meetings:'#185FA5', training:'#5B21B6',
  actions:'#DC2626', legal:'#374151', sop:'#374151',
  documents:'#374151', people:'#185FA5', users:'#5B21B6',
  admin:'#185FA5', integrations:'#0891B2', 'ai-insights':'#5B21B6', approvals:'#1D9E75', audit:'#374151',
  settings:'#374151'
};

function mobileApplyAccess() {
  ['dashboard','events','observation','kpi'].forEach(function(page){
    var btn=document.getElementById('mob-btn-'+page);
    if(btn) btn.style.display = (typeof canAccessPage !== 'function' || canAccessPage(page)) ? 'flex' : 'none';
  });
  var more=document.getElementById('mob-btn-modules');
  if(more){
    var extras=(MOBILE_MODULES||[]).some(function(m){
      return ['dashboard','events','observation','kpi'].indexOf(m.k)===-1 && (typeof canAccessPage !== 'function' || canAccessPage(m.k));
    });
    more.style.display=extras?'flex':'none';
  }
}

function applyQuickAccessVisibility() {
  var pairs = [
    ['dash-action-incident','events'],
    ['dash-action-bbs','observation'],
    ['dash-action-training','training'],
    ['dash-action-permit','permit'],
    ['mobile-home-incident','events'],
    ['mobile-home-bbs','observation'],
    ['mobile-home-kpi','kpi']
  ];
  pairs.forEach(function(pair){
    var el = document.getElementById(pair[0]);
    if(el) el.style.display = (typeof canAccessPage !== 'function' || canAccessPage(pair[1])) ? '' : 'none';
  });
  var dashboard = document.getElementById('page-dashboard');
  if(dashboard && typeof canAccessPage === 'function') {
    dashboard.querySelectorAll('[onclick*="showPage("]').forEach(function(el){
      var oc = el.getAttribute('onclick') || '';
      var m = oc.match(/showPage\(['"]([^'"]+)['"]/);
      if(m) el.style.display = canAccessPage(m[1]) ? '' : 'none';
    });
  }
}

function mobileNavTo(page, title, btnEl) {
  if(typeof canAccessPage === 'function' && !canAccessPage(page)){
    toast('Your role does not have access to this module', false);
    mobileCloseModules();
    mobileCloseSidebar();
    return;
  }
  if (_mobileCurrentPg !== page) {
    _mobileHistory.push(page);
    if (_mobileHistory.length > 30) _mobileHistory.shift();
  }
  _mobileCurrentPg = page;
  var titleEl = document.getElementById('mobile-page-title');
  if (titleEl) titleEl.textContent = title || page;
  var backBtn = document.getElementById('mobile-back-btn');
  var menuBtn = document.getElementById('mobile-menu-btn');
  if (backBtn && menuBtn) {
    var showBack = _mobileHistory.length > 1 && page !== 'dashboard';
    backBtn.style.display = showBack ? 'flex' : 'none';
    menuBtn.style.display = showBack ? 'none' : 'flex';
  }
  mobileSetBottomNavActive(page, btnEl);
  mobileCloseModules();
  mobileCloseSidebar();
  showPage(page, null);
}

function mobileSetBottomNavActive(page, btnEl) {
  document.querySelectorAll('.mob-nav-btn').forEach(function(b) { b.classList.remove('active'); });
  var activeBtn = null;
  if (btnEl && btnEl.classList && btnEl.classList.contains('mob-nav-btn')) activeBtn = btnEl;
  if (!activeBtn) activeBtn = document.getElementById('mob-btn-' + page);
  if (!activeBtn) activeBtn = document.getElementById('mob-btn-modules');
  if (activeBtn) activeBtn.classList.add('active');
}

function mobileGoBack() {
  if (_mobileHistory.length > 1) {
    _mobileHistory.pop();
    var prev = _mobileHistory[_mobileHistory.length - 1];
    var mod = null;
    for (var i = 0; i < MOBILE_MODULES.length; i++) {
      if (MOBILE_MODULES[i].k === prev) { mod = MOBILE_MODULES[i]; break; }
    }
    mobileNavTo(prev, mod ? mod.l : prev, null);
  } else {
    mobileNavTo('dashboard', 'Dashboard', null);
  }
}

// Intercept browser back button - prevent app from closing
window.addEventListener('popstate', function(e) {
  if (window.innerWidth > 768) return;
  e.preventDefault();
  if (_modulesOpen) { mobileCloseModules(); }
  else if (document.querySelector('.sidebar.open')) { mobileCloseSidebar(); }
  else if (_mobileHistory.length > 1) { mobileGoBack(); }
  else { history.pushState(null, '', window.location.href); }
});

// Push initial history state so back button works
if (window.innerWidth <= 768) {
  history.pushState(null, '', window.location.href);
}

function mobileToggleSidebar() {
  var sidebar = document.querySelector('.sidebar');
  var backdrop = document.getElementById('sidebar-backdrop');
  if (!sidebar) return;
  if (sidebar.classList.contains('open')) {
    mobileCloseSidebar();
  } else {
    sidebar.classList.add('open');
    if (backdrop) { backdrop.style.display = 'block'; backdrop.classList.add('active'); }
    history.pushState(null, '', window.location.href);
  }
}

function mobileCloseSidebar() {
  var sidebar = document.querySelector('.sidebar');
  var backdrop = document.getElementById('sidebar-backdrop');
  if (!sidebar) return;
  sidebar.classList.remove('open');
  if (backdrop) { backdrop.style.display = 'none'; backdrop.classList.remove('active'); }
}

function mobileToggleModules() {
  if (_modulesOpen) { mobileCloseModules(); } else { mobileOpenModules(); }
}

function mobileOpenModules() {
  _modulesOpen = true;
  mobileRenderModulesGrid();
  var drawer = document.getElementById('mobile-modules-drawer');
  var panel  = document.getElementById('mobile-modules-panel');
  if (drawer) {
    drawer.style.display = 'block';
    drawer.classList.add('open');
  }
  if (panel) {
    panel.style.transition = 'none';
    panel.style.transform = 'translateY(100%)';
    setTimeout(function() {
      panel.style.transition = 'transform .3s cubic-bezier(.4,0,.2,1)';
      panel.style.transform = 'translateY(0)';
    }, 10);
  }
  var mb = document.getElementById('mob-btn-modules');
  if (mb) mb.classList.add('active');
  history.pushState(null, '', window.location.href);
}

function mobileCloseModules(immediate) {
  _modulesOpen = false;
  var panel  = document.getElementById('mobile-modules-panel');
  var drawer = document.getElementById('mobile-modules-drawer');
  if (immediate) {
    if (panel) panel.style.transform = 'translateY(100%)';
    if (drawer) {
      drawer.classList.remove('open');
      drawer.style.display = 'none';
    }
    var mbNow = document.getElementById('mob-btn-modules');
    if (mbNow) mbNow.classList.remove('active');
    return;
  }
  if (panel) {
    panel.style.transform = 'translateY(100%)';
    setTimeout(function() {
      if (drawer) {
        drawer.classList.remove('open');
        drawer.style.display = 'none';
      }
    }, 300);
  } else {
    if (drawer) {
      drawer.classList.remove('open');
      drawer.style.display = 'none';
    }
  }
  var mb = document.getElementById('mob-btn-modules');
  if (mb && _mobileCurrentPg !== 'dashboard' && _mobileCurrentPg !== 'events' && _mobileCurrentPg !== 'observation' && _mobileCurrentPg !== 'kpi') {
    mb.classList.add('active');
  } else if (mb) {
    mb.classList.remove('active');
  }
}

function mobileRenderModulesGrid() {
  var grid = document.getElementById('mobile-modules-grid');
  if (!grid) return;
  var html = '';
  for (var i = 0; i < MOBILE_MODULES.length; i++) {
    var m = MOBILE_MODULES[i];
    if (typeof canAccessPage === 'function' && !canAccessPage(m.k)) continue;
    var color = MODULE_COLORS[m.k] || '#185FA5';
    var isCur = m.k === _mobileCurrentPg;
    html += '<button type="button" data-page="' + m.k + '" data-label="' + m.l + '" class="mob-module-btn"'
      + ' data-auris-named-action="mobile-nav"'
      + ' style="display:flex;flex-direction:column;align-items:center;justify-content:center;'
      + 'gap:6px;padding:14px 6px;border:2px solid ' + (isCur ? color : 'transparent') + ';'
      + 'background:' + (isCur ? color + '18' : 'transparent') + ';'
      + 'border-radius:12px;touch-action:manipulation;-webkit-tap-highlight-color:transparent;width:100%;">'
      + '<div style="width:44px;height:44px;border-radius:12px;background:' + color + '18;'
      + 'display:flex;align-items:center;justify-content:center;">'
      + '<i class="ti ' + m.i + '" style="font-size:22px;color:' + color + '"></i></div>'
      + '<span style="font-size:10px;font-weight:600;color:var(--text);text-align:center;line-height:1.2">'
      + m.l + '</span></button>';
  }
  grid.innerHTML = html;
}

function mobileSearchModulesRender(q, el) {
  var ql = q.toLowerCase();
  var html = '';
  var found = 0;
  for (var i = 0; i < MOBILE_MODULES.length; i++) {
    var m = MOBILE_MODULES[i];
    if (typeof canAccessPage === 'function' && !canAccessPage(m.k)) continue;
    if (m.l.toLowerCase().indexOf(ql) === -1) continue;
    found++;
    var color = MODULE_COLORS[m.k] || '#185FA5';
    html += '<div data-page="' + m.k + '" data-label="' + m.l + '" class="mob-search-result"'
      + ' style="display:flex;align-items:center;gap:12px;padding:12px 4px;'
      + 'border-bottom:1px solid var(--border);touch-action:manipulation;-webkit-tap-highlight-color:transparent;">'
      + '<i class="ti ' + m.i + '" style="font-size:20px;color:' + color + ';width:28px"></i>'
      + '<span style="font-size:14px;font-weight:500;color:var(--text)">' + m.l + '</span></div>';
  }
  if (!found) html = '<div style="padding:12px;color:var(--text2);font-size:13px">No modules found</div>';
  el.innerHTML = html;
  el.querySelectorAll('.mob-search-result').forEach(function(d) {
    d.addEventListener('click', function() {
      mobileNavTo(d.getAttribute('data-page'), d.getAttribute('data-label'), null);
      mobileToggleSearch();
    });
  });
}


function mobileToggleSearch() {
  var overlay = document.getElementById('mobile-search-overlay');
  if (!overlay) return;
  if (overlay.style.display !== 'none' && overlay.style.display !== '') {
    overlay.style.display = 'none';
    var inp = document.getElementById('mobile-search-input');
    if (inp) inp.value = '';
    document.getElementById('mobile-search-results').innerHTML = '';
  } else {
    overlay.style.display = 'block';
    setTimeout(function() {
      var inp = document.getElementById('mobile-search-input');
      if (inp) inp.focus();
    }, 150);
  }
}

function mobileSearchModules(q) {
  var el = document.getElementById('mobile-search-results');
  if (!el) return;
  if (!q.trim()) { el.innerHTML = ''; return; }
  mobileSearchModulesRender(q, el);
}

function mobileNormalizeButtons() {
  if (window.innerWidth > 768) return;
  document.querySelectorAll('button:not([type])').forEach(function(btn) {
    btn.setAttribute('type', 'button');
  });
}

function mobileSetViewportHeight() {
  if (window.innerWidth > 768) return;
  var vh = (window.visualViewport ? window.visualViewport.height : window.innerHeight) * 0.01;
  document.documentElement.style.setProperty('--auris-vh', vh + 'px');
}

function mobileStartButtonObserver() {
  if (window.innerWidth > 768 || window._mobileButtonObserver) return;
  mobileNormalizeButtons();
  window._mobileButtonObserver = new MutationObserver(function() {
    mobileNormalizeButtons();
  });
  window._mobileButtonObserver.observe(document.body, { childList: true, subtree: true });
}


// Close sidebar when nav item clicked from sidebar on mobile
document.addEventListener('click', function(e) {
  var navItem = e.target.closest ? e.target.closest('.nav-item') : null;
  if (navItem && window.innerWidth <= 768) {
    var onclickAttr = navItem.getAttribute('onclick') || '';
    var match = onclickAttr.match(/showPage\('([\w-]+)'/);
    if (match) {
      var pageKey = match[1];
      var mod = null;
      for (var i = 0; i < MOBILE_MODULES.length; i++) {
        if (MOBILE_MODULES[i].k === pageKey) { mod = MOBILE_MODULES[i]; break; }
      }
      _mobileCurrentPg = pageKey;
      if (_mobileHistory[_mobileHistory.length-1] !== pageKey) _mobileHistory.push(pageKey);
      var titleEl = document.getElementById('mobile-page-title');
      if (titleEl) titleEl.textContent = mod ? mod.l : pageKey;
      var backBtn = document.getElementById('mobile-back-btn');
      var menuBtn = document.getElementById('mobile-menu-btn');
      if (backBtn && menuBtn) {
        var showBack = _mobileHistory.length > 1 && pageKey !== 'dashboard';
        backBtn.style.display = showBack ? 'flex' : 'none';
        menuBtn.style.display = showBack ? 'none' : 'flex';
      }
      setTimeout(mobileCloseSidebar, 200);
      // Also scroll main to top
      var mainEl = document.querySelector('.main');
      if (mainEl) mainEl.scrollTop = 0;
    }
  }
});

// Scroll to top on mobile navigation - non-recursive
if (typeof showPage === 'function') {
  var _sp = showPage;
  showPage = function(name, el) {
    _sp(name, el);
    if (window.innerWidth <= 768) {
      setTimeout(function() {
        var mainEl = document.querySelector('.main');
        if (mainEl) mainEl.scrollTop = 0;
      }, 50);
    }
  };
}

window.addEventListener('resize', function() {
  mobileSetViewportHeight();
  if (window.innerWidth > 768) {
    mobileCloseSidebar();
    mobileCloseModules();
  }
});

if (window.visualViewport) {
  window.visualViewport.addEventListener('resize', mobileSetViewportHeight);
  window.visualViewport.addEventListener('scroll', mobileSetViewportHeight);
}

window.addEventListener('load', function() {
  if (window.innerWidth <= 768) {
    mobileSetViewportHeight();
    history.pushState(null, '', window.location.href);
    var titleEl = document.getElementById('mobile-page-title');
    if (titleEl) titleEl.textContent = 'Dashboard';
    mobileStartButtonObserver();
  }
});




// -----------------------------------------------------------
// EMAIL NOTIFICATIONS - Settings, queue display, test send
// -----------------------------------------------------------

function notifCompanyId(){
return (isSA()&&sephsCompanyContext)?sephsCompanyContext:prof?.company_id;
}

async function loadNotifSettings() {
  var el = document.getElementById('notif-settings-body');
  if (!el) return;
  el.innerHTML = '<div class="loading">Loading...</div>';
  try {
    var companyId=notifCompanyId();
    if(!companyId){el.innerHTML='<div style="color:var(--red);padding:12px">No company selected for notification settings.</div>';return;}
    var healthPromise=loadNotificationDeliveryHealth(companyId);
    var rows = await api('/notification_settings?company_id=eq.' + companyId + '&limit=1');
    var s = rows && rows[0] ? rows[0] : {};
    var whatsappSettings={};
    try{var waRows=await api('/whatsapp_channel_settings?company_id=eq.'+encodeURIComponent(companyId)+'&limit=1');whatsappSettings=waRows&&waRows[0]?waRows[0]:{};}catch(waError){whatsappSettings={schema_missing:true};}
    var queue = await api('/notification_queue?company_id=eq.' + encodeURIComponent(companyId) + '&order=created_at.desc&limit=25');
    notificationQueueRows=queue||[];
    var health=await healthPromise;
    el.innerHTML = renderNotificationDeliveryHealth(health)+renderNotifSettings(s, notificationQueueRows, whatsappSettings);
    if(typeof loadNotificationEscalationSettings==='function')loadNotificationEscalationSettings(companyId);
    if(typeof loadNotificationAcknowledgementSettings==='function')loadNotificationAcknowledgementSettings(companyId);
  } catch(e) {
    el.innerHTML = '<div style="color:var(--red);padding:12px">Error loading settings: ' + escH(e.message) + '</div>';
  }
}

async function loadNotificationDeliveryHealth(companyId){
  try{
    var response=await fetch('/api/notification-health?company_id='+encodeURIComponent(companyId),{headers:{Authorization:'Bearer '+tok},cache:'no-store'});
    var body=await response.json().catch(function(){return{};});
    if(!response.ok)throw new Error(body.error||'Health endpoint returned '+response.status);
    return body;
  }catch(error){return {error:error.message||String(error)};}
}
async function runNotificationRoutingSimulation(){
  var companyId=notifCompanyId(),el=document.getElementById('notification-readiness-matrix');
  if(!companyId||!el)return;
  el.innerHTML='<div class="loading" style="padding:14px">Running read-only routing simulation...</div>';
  try{
    var response=await fetch('/api/notification-health?company_id='+encodeURIComponent(companyId)+'&simulate=true',{headers:{Authorization:'Bearer '+tok},cache:'no-store'});
    var body=await response.json().catch(function(){return{};});
    if(!response.ok)throw new Error(body.error||'Readiness endpoint returned '+response.status);
    el.outerHTML=renderNotificationReadiness(body);
    toast('Read-only simulation complete. No notifications were created or sent.');
  }catch(error){el.innerHTML='<div style="color:var(--red);padding:12px">Simulation failed: '+escH(error.message||error)+'</div>';}
}
function notificationReadinessBadge(status){var map={ready:['Ready','#065F46','#DCFCE7','ti-circle-check'],review:['Review','#92400E','#FEF3C7','ti-alert-triangle'],blocked:['Blocked','#991B1B','#FEE2E2','ti-circle-x']};var m=map[status]||map.blocked;return '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 8px;border-radius:99px;background:'+m[2]+';color:'+m[1]+';font-size:10px;font-weight:850"><i class="ti '+m[3]+'"></i>'+m[0]+'</span>';}
function renderNotificationReadiness(health){
  var readiness=health&&health.readiness;if(!readiness)return '';
  var items=(readiness.items||[]).map(function(item){return '<div style="border:1px solid var(--border);border-radius:9px;background:#fff;padding:11px"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><strong style="font-size:11px">'+escH(item.label)+'</strong>'+notificationReadinessBadge(item.status)+'</div><div style="font-size:10px;color:var(--text2);line-height:1.45;margin-top:6px">'+escH(item.detail||'')+'</div>'+(item.remediation?'<div style="font-size:10px;color:#92400E;line-height:1.45;margin-top:5px"><strong>Required:</strong> '+escH(item.remediation)+'</div>':'')+'</div>';}).join('');
  var simulation=health.simulation,scenarioHtml='';
  if(simulation){scenarioHtml='<div style="border-top:1px solid #BFDBFE;margin-top:12px;padding-top:12px"><div style="font-size:11px;font-weight:850;color:#1E3A8A">Routing simulation</div><div style="font-size:10px;color:#475569;margin:4px 0 8px">'+escH(simulation.message)+'</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:7px">'+(simulation.scenarios||[]).map(function(x){return '<div style="background:#fff;border:1px solid var(--border);border-radius:8px;padding:9px"><div style="display:flex;justify-content:space-between;gap:6px"><strong style="font-size:10px">'+escH(x.label)+'</strong>'+notificationReadinessBadge(x.deliverable?'ready':'blocked')+'</div><div style="font-size:9px;color:var(--text2);margin-top:5px">Channels: '+escH((x.channels||[]).join(', ')||'none configured')+(x.level?' Â· Level '+Number(x.level):'')+'</div></div>';}).join('')+'</div></div>';}
  return '<div id="notification-readiness-matrix" style="border:1px solid #BFDBFE;background:#EFF6FF;border-radius:12px;padding:14px;margin:0 0 16px"><div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap;margin-bottom:11px"><div><div style="font-size:14px;font-weight:900;color:#1E3A8A">Operational readiness matrix</div><div style="font-size:11px;color:#475569;margin-top:3px">'+Number(readiness.ready||0)+' of '+Number(readiness.total||0)+' controls ready. Checks are company-scoped and do not expose secrets or personal recipient details.</div></div><div style="display:flex;gap:8px;align-items:center">'+notificationReadinessBadge(readiness.status)+'<button type="button" class="btn btn-sm" data-auris-generated-onclick="g0365"><i class="ti ti-route"></i>Run read-only simulation</button></div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px">'+items+'</div>'+scenarioHtml+'</div>';
}
function notificationHealthBadge(status){var map={operational:['Operational','#065F46','#DCFCE7','ti-circle-check'],review:['Review','#92400E','#FEF3C7','ti-alert-triangle'],setup:['Setup required','#991B1B','#FEE2E2','ti-plug-connected-x']};var m=map[status]||map.setup;return '<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 9px;border-radius:99px;background:'+m[2]+';color:'+m[1]+';font-size:11px;font-weight:800"><i class="ti '+m[3]+'"></i>'+m[0]+'</span>';}
function notificationHealthCount(c){c=c||{};var parts=Object.keys(c).filter(function(k){return Number(c[k])>0;}).map(function(k){return escH(k.replace(/_/g,' '))+': <strong>'+Number(c[k])+'</strong>';});return parts.length?parts.join(' · '):'No delivery activity in the last 7 days';}
function renderNotificationDeliveryHealth(health){
  if(!health||health.error)return '<div style="border:1px solid #FDE68A;background:#FFFBEB;border-radius:10px;padding:14px;margin-bottom:16px;color:#92400E;font-size:12px"><strong>Delivery health unavailable.</strong> '+escH(health?.error||'Refresh and try again.')+'</div>';
  var channels=health.channels||{},labels={email:['ti-mail','Email'],inApp:['ti-bell','In-app'],push:['ti-device-mobile-message','Browser / mobile push'],whatsapp:['ti-brand-whatsapp','WhatsApp']};
  var cards=Object.keys(labels).map(function(key){var x=channels[key]||{},meta=[];if(key==='email')meta.push(x.provider?'Provider: '+x.provider.toUpperCase():'Provider missing',x.deliveryWebhookConfigured?'Delivery webhook configured':'Delivery webhook not confirmed');if(key==='push')meta.push((x.activeSubscriptions||0)+' active device subscription(s)',x.schemaInstalled?'Push schema installed':'Push schema missing');if(key==='whatsapp')meta.push((x.activeConsents||0)+' active consent(s)',x.tenantEnabled?'Tenant channel enabled':'Tenant channel disabled',x.template?'Template: '+x.template:'Template missing');if(key==='inApp'&&x.note)meta.push(x.note);return '<div style="border:1px solid var(--border);border-radius:11px;background:#fff;padding:13px"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><div style="display:flex;gap:8px;align-items:center;font-weight:850"><i class="ti '+labels[key][0]+'" style="color:var(--green);font-size:18px"></i>'+labels[key][1]+'</div>'+notificationHealthBadge(x.status)+'</div><div style="font-size:11px;color:var(--text2);margin-top:10px;line-height:1.5">'+notificationHealthCount(x.counts)+'</div><div style="font-size:10px;color:var(--text3);margin-top:7px">'+meta.map(escH).join(' · ')+'</div></div>';}).join('');
  var emailEvidence=channels.email||{},evidenceSummary='<div style="font-size:10px;color:#475569;margin-top:10px"><i class="ti ti-link"></i> '+(emailEvidence.signedRecordLinksConfigured?'Signed record links enabled':'Direct record links; evidence tracking disabled')+' · '+Number(emailEvidence.uniqueRecordOpens||0)+' unique record open(s) · '+(emailEvidence.deliveredToOpenPercent==null?'Conversion awaiting delivered email':'Delivered-to-opened: '+emailEvidence.deliveredToOpenPercent+'%')+'</div>';
  var warnings=(health.schemaWarnings||[]).length?'<div style="padding:10px 12px;background:#FEF2F2;border:1px solid #FECACA;border-radius:9px;color:#991B1B;font-size:11px;margin-top:10px"><strong>Missing database components:</strong> '+health.schemaWarnings.map(escH).join(', ')+'</div>':'';
  return '<div style="border:1px solid #BAE6D3;background:#F0FDF9;border-radius:12px;padding:14px;margin-bottom:16px"><div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap;margin-bottom:12px"><div><div style="font-size:14px;font-weight:900;color:#065F46">Notification delivery health</div><div style="font-size:11px;color:#047857;margin-top:3px">Configuration and company activity for the last '+Number(health.periodDays||7)+' days. Secret values are never displayed.</div></div><div style="font-size:10px;color:var(--text2)">Checked '+escH(new Date(health.checkedAt).toLocaleString())+'</div></div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:9px">'+cards+'</div>'+evidenceSummary+warnings+'<div style="font-size:10px;color:#92400E;margin-top:10px"><i class="ti ti-clock"></i> '+escH(health.schedules?.warning||'Confirm production schedules before relying on urgent delivery.')+'</div></div>'+renderNotificationReadiness(health);
}

function renderNotifSettings(s, queue, whatsappSettings) {
  var fields = [
    {id:'email_enabled',           val: s.email_enabled !== false,           label:'Email notifications enabled'},
    {id:'notify_on_incident',      val: s.notify_on_incident !== false,      label:'Notify on new incident (HSE managers + admins)'},
    {id:'notify_on_permit',        val: s.notify_on_permit !== false,        label:'Notify permit requester on status change'},
    {id:'notify_on_overdue',       val: s.notify_on_overdue !== false,       label:'Daily digest of overdue actions'},
    {id:'notify_on_investigation', val: s.notify_on_investigation !== false, label:'Notify investigator when assigned'},
    {id:'notify_on_audit',         val: s.notify_on_audit !== false,         label:'Notify participants when audit scheduled'},
  ];
  var incidentRules = s.event_recipients || {};
  if (typeof incidentRules === 'string') {
    try { incidentRules = JSON.parse(incidentRules); } catch(_) { incidentRules = {}; }
  }
  var incidentTypeKeys = ['injury','near_miss','dangerous_occurrence','property_damage','environmental','vehicle','unsafe_act','unsafe_condition','fire','occupational_disease','security'];

  var togglesHtml = fields.map(function(f) {
    var bg  = f.val ? 'var(--green)' : 'var(--border)';
    var dot = f.val ? '22px' : '2px';
    return '<label style="display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--border);cursor:pointer">'
      + '<div data-field="' + f.id + '" class="notif-toggle" style="width:44px;height:24px;border-radius:12px;background:' + bg + ';position:relative;cursor:pointer;transition:background .2s;flex-shrink:0">'
      + '<div class="notif-dot" style="width:20px;height:20px;border-radius:50%;background:#fff;position:absolute;top:2px;left:' + dot + ';transition:left .2s;box-shadow:0 1px 3px rgba(0,0,0,.2)"></div></div>'
      + '<span style="font-size:13px;color:var(--text)">' + f.label + '</span></label>';
  }).join('');

  function notifStatusBadge(n){
    var st=String(n.status||'pending').toLowerCase();
    var cls=(st==='sent'||st==='delivered')?'bg':(st==='failed'||st==='bounced')?'br':'bgr';
    return '<span class="badge '+cls+'">'+escH(st.toUpperCase())+'</span>';
  }
  function notifToCell(n){
    var email=String(n.to_email||'').trim();
    var warn=!isDeliverableEmail(email)?'<div style="font-size:10px;color:var(--orange);margin-top:3px">Login-only or invalid address</div>':'';
    return escH(email||'-')+warn;
  }
  var qPending=queue.filter(function(n){return (n.status||'pending')==='pending';}).length;
  var qSent=queue.filter(function(n){return ['sent','delivered'].includes(n.status||'');}).length;
  var qFailed=queue.filter(function(n){return ['failed','bounced'].includes(n.status||'');}).length;
  var recentRows = queue.length ? queue.map(function(n) {
    var color = (n.status==='sent'||n.status==='delivered') ? 'var(--green)' : (n.status==='failed'||n.status==='bounced') ? 'var(--red)' : 'var(--text2)';
    var err = n.error_msg ? '<div style="font-size:10px;color:var(--red);margin-top:3px;max-width:360px;white-space:normal">'+escH(n.error_msg)+'</div>' : '';
    var rel=notificationRelationship(n),canOpen=!!(rel.module&&rel.table&&rel.id);
    return '<tr>'
      + '<td style="padding:8px 10px">' + escH((n.subject||'').substring(0,50)) + err + '</td>'
      + '<td style="padding:8px 10px">' + notifToCell(n) + '</td>'
      + '<td style="padding:8px 10px"><strong>'+escH(rel.ref||'System notification')+'</strong><div style="font-size:10px;color:var(--text2)">'+escH(rel.module?auditLabel(rel.module):'No source record')+'</div></td>'
      + '<td style="padding:8px 10px">' + notifStatusBadge(n) + '</td>'
      + '<td style="padding:8px 10px;color:var(--text2);font-size:11px">'
      + (n.created_at ? new Date(n.created_at).toLocaleString() : '') + '</td>'
      + '<td style="padding:8px 10px;text-align:right">'+(canOpen?'<button class="btn btn-sm" data-auris-runtime-onclick="r0127" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([n.id]))+'"><i class="ti ti-external-link"></i>Open record</button>':'<span style="font-size:10px;color:var(--text3)">Not applicable</span>')+'</td>'
      + '</tr>';
  }).join('') : '<tr><td colspan="6" style="padding:16px;text-align:center;color:var(--text2)">No notifications yet</td></tr>';
  var recipientRows = incidentTypeKeys.map(function(k) {
    var cfg = (typeof IMS_TYPE_CFG !== 'undefined' && IMS_TYPE_CFG[k]) ? IMS_TYPE_CFG[k] : {label:k.replace(/_/g,' '), emoji:''};
    var recipients = Array.isArray(incidentRules[k]) ? incidentRules[k] : [];
    var value = recipients.map(function(r){
      if (typeof r === 'string') return r;
      return r.name && r.email ? r.name + ' <' + r.email + '>' : (r.email || r.name || '');
    }).filter(Boolean).join(', ');
    return '<div style="display:grid;grid-template-columns:minmax(140px,210px) 1fr;gap:10px;align-items:center;padding:8px 0;border-bottom:1px solid var(--border)">'
      + '<label for="notif-recip-' + k + '" style="font-size:12px;font-weight:700;color:var(--text)">' + cfg.emoji + ' ' + escH(cfg.label) + '</label>'
      + '<input type="text" class="notif-event-recips" data-type="' + k + '" id="notif-recip-' + k + '" value="' + escH(value) + '" placeholder="name@company.com, HSE Manager <hse@company.com>" style="font-size:12px"/>'
      + '</div>';
  }).join('');

  return '<div style="background:#EFF6FF;border:1px solid #bfdbfe;border-radius:10px;padding:12px 14px;margin-bottom:16px;font-size:12px;color:#1e40af">'
    + '<strong>Email sender:</strong> configured securely on the server. This screen controls notification rules and recipients only. Login-only addresses ending in <strong>.local</strong> cannot receive email; add a real notification email now, or WhatsApp/SMS when that integration is activated.'
    + '<input type="hidden" id="notif-from3email" value="' + escH(s.from_email||'') + '"/>'
    + '<input type="hidden" id="notif-resend-key" value="' + escH(s.resend_api_key||'') + '"/>'
    + '</div>'
    + '<div id="notif-toggles" style="margin-bottom:16px">' + togglesHtml + '</div>'
    + '<div id="notification-escalation-settings"></div>'
    + '<div id="notification-acknowledgement-settings"></div>'
    + renderWhatsappChannelSettings(whatsappSettings||{})
    + '<div style="border:1px solid var(--border);border-radius:10px;padding:14px;margin-bottom:16px;background:#fff">'
    + '<div style="font-size:13px;font-weight:800;margin-bottom:4px">Incident recipients by event type</div>'
    + '<div style="font-size:12px;color:var(--text2);margin-bottom:10px">Company Admin can add the people to notify for each incident type. Use real email addresses, separated by commas.</div>'
    + recipientRows
    + '</div>'
    + '<div style="display:flex;gap:10px;margin-bottom:20px">'
    + '<button class="btn btn-primary" data-auris-generated-onclick="g0366"><i class="ti ti-device-floppy"></i>Save Settings</button>'
    + '<button class="btn" data-auris-generated-onclick="g0367"><i class="ti ti-mail"></i>Send Test Email</button>'
    + '<button class="btn" data-auris-generated-onclick="g0368"><i class="ti ti-refresh"></i>Refresh Status</button>'
    + '</div>'
    + '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:10px">'
    + '<div style="font-size:13px;font-weight:600">Recent Notifications</div>'
    + '<div style="display:flex;gap:6px;flex-wrap:wrap;font-size:11px"><span class="badge bgr">Pending '+qPending+'</span><span class="badge bg">Sent '+qSent+'</span><span class="badge br">Failed '+qFailed+'</span></div>'
    + '</div>'
    + '<div style="overflow-x:auto"><table style="width:100%;font-size:12px;min-width:900px">'
    + '<thead><tr style="border-bottom:2px solid var(--border)">'
    + '<th style="padding:8px 10px;text-align:left">Subject</th><th style="padding:8px 10px;text-align:left">To</th>'
    + '<th style="padding:8px 10px;text-align:left">Source record</th><th style="padding:8px 10px;text-align:left">Status</th><th style="padding:8px 10px;text-align:left">Time</th><th style="padding:8px 10px;text-align:right">Action</th>'
    + '</tr></thead><tbody>' + recentRows + '</tbody></table></div>';
}

function renderWhatsappChannelSettings(s){
  if(s.schema_missing)return '<div style="border:1px solid #FDE68A;background:#FFFBEB;border-radius:10px;padding:14px;margin-bottom:16px;font-size:12px;color:#92400E"><strong>WhatsApp not installed.</strong> Run <code>whatsapp_notifications_upgrade.sql</code> before configuring this channel.</div>';
  var level=Number(s.minimum_escalation_level==null?2:s.minimum_escalation_level);
  var levelOption=function(value,label){return '<option value="'+value+'" '+(level===value?'selected':'')+'>'+label+'</option>';};
  return '<div style="border:1px solid #BBF7D0;background:#F0FDF4;border-radius:10px;padding:14px;margin-bottom:16px">'
    +'<div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap"><div><div style="font-size:13px;font-weight:800;color:#065F46"><i class="ti ti-brand-whatsapp"></i> WhatsApp Cloud API</div><div style="font-size:12px;color:#047857;margin-top:4px">Approved templates only. Access token and app secret stay in Vercel and are never shown here.</div></div>'
    +'<label style="display:flex;align-items:center;gap:7px;font-size:12px;font-weight:700"><input type="checkbox" id="notif-wa-enabled" '+(s.enabled?'checked':'')+'> Channel enabled</label></div>'
    +'<div class="form3row" style="margin-top:12px"><div class="form3group"><label class="form3label">Meta phone number ID</label><input id="notif-wa-phone-id" value="'+escH(s.phone_number_id||'')+'" placeholder="Meta phone_number_id"></div><div class="form3group"><label class="form3label">Approved template</label><input id="notif-wa-template" value="'+escH(s.alert_template_name||'auris360_alert')+'"></div></div>'
    +'<div class="form3row"><div class="form3group"><label class="form3label">Template language</label><input id="notif-wa-language" value="'+escH(s.template_language||'en')+'" placeholder="en"></div><div class="form3group"><label class="form3label">Minimum escalation level</label><select id="notif-wa-level">'+levelOption(0,'All governed alerts')+levelOption(1,'Level 1+')+levelOption(2,'Level 2+ (recommended)')+levelOption(3,'Level 3 only')+'</select></div></div>'
    +'<label style="display:flex;align-items:center;gap:7px;font-size:12px"><input type="checkbox" id="notif-wa-preferred" '+(s.allow_preferred_high_priority!==false?'checked':'')+'> Also send high/urgent alerts when an opted-in user selected WhatsApp as preferred</label>'
    +'<button class="btn" style="margin-top:12px;border-color:#10B981;color:#047857" data-auris-generated-onclick="g0369"><i class="ti ti-device-floppy"></i>Save WhatsApp channel</button></div>';
}

async function saveWhatsappChannelSettings(){
  var companyId=notifCompanyId();if(!companyId)return toast('No company selected.',false);
  var body={company_id:companyId,enabled:!!document.getElementById('notif-wa-enabled')?.checked,provider:'meta_cloud',phone_number_id:(document.getElementById('notif-wa-phone-id')?.value||'').trim()||null,alert_template_name:(document.getElementById('notif-wa-template')?.value||'auris360_alert').trim(),template_language:(document.getElementById('notif-wa-language')?.value||'en').trim(),minimum_escalation_level:Number(document.getElementById('notif-wa-level')?.value||2),allow_preferred_high_priority:!!document.getElementById('notif-wa-preferred')?.checked,updated_by:prof?.id||null,updated_at:new Date().toISOString()};
  if(body.enabled&&!body.phone_number_id)return toast('Enter the Meta phone number ID before enabling WhatsApp.',false);
  if(!/^[a-z0-9_]+$/i.test(body.alert_template_name))return toast('Template name may contain only letters, numbers and underscores.',false);
  try{var existing=await api('/whatsapp_channel_settings?company_id=eq.'+encodeURIComponent(companyId)+'&limit=1');if(existing&&existing[0])await api('/whatsapp_channel_settings?company_id=eq.'+encodeURIComponent(companyId),{m:'PATCH',p:'return=minimal',b:body});else await api('/whatsapp_channel_settings',{m:'POST',p:'return=minimal',b:body});toast('WhatsApp channel settings saved.');loadNotifSettings();}catch(e){toastActionError('Save WhatsApp channel','Notification Settings',e);}
}


var _notifToggles = {};
function notifToggle(el, field) {}  // legacy - see event delegation below

function parseNotifRecipients(text) {
  return String(text || '').split(',').map(function(part) {
    var raw = part.trim();
    if (!raw) return null;
    var match = raw.match(/^(.*?)<([^>]+)>$/);
    if (match) return { name: match[1].trim(), email: match[2].trim() };
    return { name: '', email: raw };
  }).filter(function(r) {
    return r && r.email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(r.email);
  });
}

function validateNotifRecipientsInput(text) {
  var invalid=[];
  String(text||'').split(',').forEach(function(part){
    var raw=part.trim();
    if(!raw)return;
    var match=raw.match(/^(.*?)<([^>]+)>$/);
    var email=match?match[2].trim():raw;
    if(!isDeliverableEmail(email))invalid.push(raw);
  });
  return invalid;
}

function validateNotifRecipientFields() {
  var bad=[];
  document.querySelectorAll('.notif-event-recips').forEach(function(input){
    var invalid=validateNotifRecipientsInput(input.value);
    if(invalid.length){
      var type=input.getAttribute('data-type')||'event';
      bad.push(type.replace(/_/g,' ')+': '+invalid.join(', '));
      input.style.borderColor='var(--red)';
    } else {
      input.style.borderColor='';
    }
  });
  return bad;
}

function collectNotifEventRecipients() {
  var rules = {};
  document.querySelectorAll('.notif-event-recips').forEach(function(input) {
    var type = input.getAttribute('data-type');
    var recipients = parseNotifRecipients(input.value);
    if (type && recipients.length) rules[type] = recipients;
  });
  return rules;
}

// Event delegation for notification toggles
document.addEventListener('click', function(e) {
  var toggle = e.target.closest('.notif-toggle');
  if (!toggle) return;
  var field = toggle.getAttribute('data-field');
  if (!field) return;
  if (!_notifToggles) _notifToggles = {};
  var isOn = toggle.style.background.includes('1D9E75') || toggle.style.background === 'var(--green)';
  var newVal = !isOn;
  _notifToggles[field] = newVal;
  toggle.style.background = newVal ? 'var(--green)' : 'var(--border)';
  var dot = toggle.querySelector('.notif-dot');
  if (dot) dot.style.left = newVal ? '22px' : '2px';
});

async function saveNotifSettings() {
  try {
    var companyId=notifCompanyId();
    if(!companyId){toast('No company selected for notification settings.',false);return;}
    var bad=validateNotifRecipientFields();
    if(bad.length){toast('Invalid notification email(s): '+bad[0],false);return;}
    var existing = await api('/notification_settings?company_id=eq.' + companyId + '&limit=1');
    var mergedRules = collectNotifEventRecipients();
    if (existing && existing[0] && existing[0].event_recipients) {
      var oldRules = existing[0].event_recipients;
      if (typeof oldRules === 'string') { try { oldRules = JSON.parse(oldRules); } catch(_) { oldRules = {}; } }
      if (oldRules.permit_approvers) mergedRules.permit_approvers = oldRules.permit_approvers;
    }
    var updates = { event_recipients: mergedRules, updated_at: new Date().toISOString() };
    Object.assign(updates, _notifToggles || {});
    if (existing && existing[0]) {
      await api('/notification_settings?company_id=eq.' + companyId, {m:'PATCH', p:'return=minimal', b:updates});
    } else {
      updates.company_id = companyId;
      await api('/notification_settings', {m:'POST', p:'return=minimal', b:updates});
    }
    toast('Notification settings saved');
    _notifToggles = {};
    loadNotifSettings();
  } catch(e) {
    var msg = e.message || '';
    if (msg.includes('event_recipients')) msg = 'Database update needed: add event_recipients to notification_settings.';
    toast('Error: ' + msg, false);
  }
}

async function sendTestEmail() {
  var companyId=notifCompanyId();
  var contactEmail=usersContactEmail(prof);
  if (!contactEmail && !prof?.email) { toast('No email on your profile', false); return; }
  if (!companyId) { toast('No company selected for test email', false); return; }
  if (!isDeliverableEmail(contactEmail)) {
    toast('This profile uses a login-only email. Add a real notification email before sending a test.', false);
    return;
  }
  try {
    await queueNotification({
      company_id:companyId,
      type:'test_email',
      subject:'AURIS360 Test Email',
      body_html:'<div style="font-family:Arial,sans-serif;padding:24px;max-width:500px">'
        + '<div style="background:#1D9E75;padding:16px;color:#fff;border-radius:8px 8px 0 0;font-size:18px;font-weight:700">AURIS360</div>'
        + '<div style="padding:20px;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 8px 8px">'
        + '<p>Your email notifications are working correctly.</p>'
        + '<p style="color:#6b7280;font-size:13px">This test was queued from AURIS360 and will be sent by the server email worker.</p>'
        + '</div></div>',
      to_email:contactEmail,
      to_name:prof.full_name||''
    });
    toast('Test email queued for '+contactEmail+'. Check Recent Notifications for status.');
    loadNotifSettings();
  } catch(e) { toast('Error: ' + e.message, false); }
}

