function approvalsCanView(){
  return ['sephs_admin','admin','hse_manager','hse_officer'].indexOf(activeRole()) !== -1;
}
function approvalsCompanyFilter(){
  if(isSA() && sephsCompanyContext) return sephsCompanyContext;
  if(isSA()) return null;
  return prof?.company_id || null;
}
async function approvalsSafe(promise){
  try{return await promise;}catch(e){console.warn('Approval Center source skipped:',e.message);return [];}
}
function approvalsStatusLabel(s){
  return auditLabel(String(s||'pending').replace(/_/g,' '));
}
function approvalsStatusBadge(s){
  var raw=String(s||'pending').toLowerCase();
  var bg=raw.indexOf('approved')>=0?'#EAF3DE':raw.indexOf('reject')>=0?'#FCEBEB':raw.indexOf('review')>=0?'#EFF6FF':'#FEF9EC';
  var c=raw.indexOf('approved')>=0?'#3B6D11':raw.indexOf('reject')>=0?'#A32D2D':raw.indexOf('review')>=0?'#185FA5':'#854F0B';
  return '<span style="display:inline-flex;align-items:center;padding:3px 8px;border-radius:999px;background:'+bg+';color:'+c+';font-size:11px;font-weight:700">'+escH(approvalsStatusLabel(raw))+'</span>';
}
function approvalsDate(value){
  if(!value)return null;var d=new Date(value);return isNaN(d.getTime())?null:d;
}
function approvalsDateLabel(value,emptyLabel){
  var d=approvalsDate(value);return d?d.toLocaleDateString():(value?String(value):(emptyLabel||'-'));
}
function approvalsCompanyPath(base){
  var cid=approvalsCompanyFilter();
  return base + (cid ? '&company_id=eq.'+encodeURIComponent(cid) : '');
}

function approvalsPick(row,fields){
  for(var i=0;i<(fields||[]).length;i++){var v=row?.[fields[i]];if(v!==null&&v!==undefined&&String(v).trim()!=='')return v;}
  return '';
}
function approvalsAdapterStatus(row,adapter){
  var allowed=adapter.statuses||[];
  for(var i=0;i<(adapter.status||['status']).length;i++){
    var value=String(row?.[adapter.status[i]]||'').toLowerCase();
    if(allowed.indexOf(value)!==-1)return value;
  }
  return '';
}
function approvalsAdapterRow(adapter,row){
  var status=approvalsAdapterStatus(row,adapter);if(!status||adapter.filter&&!adapter.filter(row))return null;
  var id=row.id||row.record_id||row.related_id;if(!id)return null;
  var openId=approvalsPick(row,adapter.openId)||id;
  return {row_key:adapter.table+':'+id,adapter_key:adapter.key,source:adapter.key,module:adapter.module,table:adapter.table,record_id:id,id:id,
    ref:String(approvalsPick(row,adapter.ref)||displayRecordRef(row,['reference_no','reference','code'],'REVIEW-DRAFT')),
    title:String(approvalsPick(row,adapter.title)||adapter.module+' record awaiting review'),status:status,stage:adapter.stage||approvalsStatusLabel(status),step:adapter.stage||approvalsStatusLabel(status),
    approver:String(approvalsPick(row,adapter.approver)||'Role-based queue'),due_date:approvalsPick(row,adapter.due)||'',
    confidentiality:String(approvalsPick(row,adapter.confidentiality)||adapter.defaultConfidentiality||'Standard'),updated_at:row.updated_at||row.created_at||approvalsPick(row,adapter.due)||'',
    page:adapter.page,opener:adapter.opener||'',entity:adapter.entity||'',open_id:openId,open_table:adapter.openTable||adapter.table,company_id:row.company_id||approvalsCompanyFilter()};
}

async function loadApprovals(){
  var el=document.getElementById('approvals-table-body');if(!el)return;
  if(!approvalsCanView()){
    el.innerHTML='<tr><td colspan="8" style="padding:18px;color:var(--red);text-align:center">Access denied</td></tr>';
    return;
  }
  el.innerHTML='<tr><td colspan="8" style="padding:22px;text-align:center;color:var(--text2)">Loading governed review queues...</td></tr>';
  try{
    var cid=approvalsCompanyFilter();
    var scope=document.getElementById('approvals-scope-label');
    if(scope)scope.textContent=isSA()?(cid?'Selected company':'All companies'):(co?.name||'Current company');

    var tables=Array.from(new Set(APPROVAL_SOURCE_ADAPTERS.map(function(a){return a.table;})));
    var loads=[approvalsSafe(api(approvalsCompanyPath('/approval_requests?select=*&limit=300')))];
    tables.forEach(function(table){loads.push(approvalsSafe(api(approvalsCompanyPath('/'+table+'?select=*&limit=300'))));});
    var loaded=await Promise.all(loads),generic=loaded[0]||[],seen={},loadedByTable={};
    tables.forEach(function(table,index){loadedByTable[table]=loaded[index+1]||[];});
    approvalCenterRows=[];
    APPROVAL_SOURCE_ADAPTERS.forEach(function(adapter){
      (loadedByTable[adapter.table]||[]).forEach(function(sourceRow){var row=approvalsAdapterRow(adapter,sourceRow);if(row&&!seen[row.row_key]){seen[row.row_key]=true;approvalCenterRows.push(row);}});
    });
    (generic||[]).forEach(function(x){
      var id=x.related_id||x.id,table=x.related_table||'approval_requests',key=table+':'+id;
      if(!id||seen[key]||!['pending','submitted','pending_review','under_review','pending_approval','review'].includes(String(x.status||'pending').toLowerCase()))return;
      seen[key]=true;approvalCenterRows.push({
        row_key:'workflow:'+x.id,adapter_key:'workflow',source:'workflow',module:x.module_name||x.related_table||'Workflow',table:table,record_id:id,
        ref:displayRecordRef(x,['request_ref','approval_ref','related_ref'],'WF-DRAFT'),
        title:x.related_table||'Approval request',
        status:x.status||'pending',
        stage:x.current_step_no?('Approval level '+x.current_step_no):'Workflow review',step:x.current_step_no?('Approval level '+x.current_step_no):'Workflow review',
        approver:x.approver_name||x.assigned_to_name||'Role-based queue',due_date:x.due_date||x.review_due_date||'',confidentiality:x.confidentiality||'Standard',
        updated_at:x.updated_at||x.created_at,
        id:id,page:x.module_name||'',open_id:id,open_table:table,company_id:x.company_id||cid
      });
    });
    approvalCenterRows.sort(function(a,b){var ad=approvalsDate(a.due_date)||new Date('2999-12-31'),bd=approvalsDate(b.due_date)||new Date('2999-12-31');return ad-bd||(approvalsDate(b.updated_at)||0)-(approvalsDate(a.updated_at)||0);});
    approvalsRender();
  }catch(e){
    el.innerHTML='<tr><td colspan="8" style="padding:18px">'+setupFriendlyMessage('Approval Center',e.message)+'</td></tr>';
  }
}

function approvalsFilteredRows(){
  var q=(document.getElementById('approvals-search')?.value||'').toLowerCase();
  var status=document.getElementById('approvals-filter-status')?.value||'';
  var module=document.getElementById('approvals-filter-module')?.value||'';
  return (approvalCenterRows||[]).filter(function(x){
    if(status && String(x.status||'')!==status)return false;
    if(module && String(x.source||x.module||'')!==module)return false;
    if(q){
      var hay=[x.module,x.ref,x.title,x.status,x.stage,x.approver,x.confidentiality].join(' ').toLowerCase();
      if(hay.indexOf(q)===-1)return false;
    }
    return true;
  });
}

function approvalsRender(){
  var rows=approvalsFilteredRows();
  var tbody=document.getElementById('approvals-table-body');if(!tbody)return;
  var total=document.getElementById('approvals-count');if(total)total.textContent=String((approvalCenterRows||[]).length);
  var shown=document.getElementById('approvals-shown-count');if(shown)shown.textContent=String(rows.length);
  var pending=document.getElementById('approvals-pending-count');if(pending)pending.textContent=String((approvalCenterRows||[]).filter(function(x){return !['approved','rejected','closed','published','issued'].includes(String(x.status||'').toLowerCase());}).length);
  var statusSel=document.getElementById('approvals-filter-status');
  if(statusSel){
    var selectedStatus=statusSel.value,statuses=Array.from(new Set((approvalCenterRows||[]).map(function(x){return String(x.status||'');}).filter(Boolean))).sort();
    statusSel.innerHTML='<option value="">All statuses</option>'+statuses.map(function(s){return '<option value="'+escH(s)+'">'+escH(approvalsStatusLabel(s))+'</option>';}).join('');
    if(statuses.indexOf(selectedStatus)!==-1)statusSel.value=selectedStatus;
  }
  var modSel=document.getElementById('approvals-filter-module');
  if(modSel){
    var selected=modSel.value,modules=Array.from(new Set((approvalCenterRows||[]).map(function(x){return x.source||x.module||'';}))).sort();
    modSel.innerHTML='<option value="">All modules</option>'+modules.map(function(k){var row=approvalCenterRows.find(function(x){return (x.source||x.module)===k;});return '<option value="'+escH(k)+'">'+escH(row?.module||auditLabel(k))+'</option>';}).join('');
    if(modules.indexOf(selected)!==-1)modSel.value=selected;
  }
  if(!rows.length){
    tbody.innerHTML='<tr><td colspan="8" style="padding:26px;text-align:center;color:var(--text2)">No governed reviews match this view</td></tr>';
    return;
  }
  tbody.innerHTML=rows.map(function(x){
    return '<tr style="border-bottom:1px solid var(--border)">'
      +'<td style="padding:10px 12px;font-weight:800">'+escH(x.ref||'-')+'<div style="font-size:11px;color:var(--text2);font-weight:400">'+escH(x.module||'-')+'</div></td>'
      +'<td style="padding:10px 12px;max-width:420px">'+escH(x.title||'-')+'</td>'
      +'<td style="padding:10px 12px">'+approvalsStatusBadge(x.status)+'<div style="font-size:11px;color:var(--text2);margin-top:4px">'+escH(x.stage||'-')+'</div></td>'
      +'<td style="padding:10px 12px">'+escH(x.approver||'Role-based queue')+'</td>'
      +'<td style="padding:10px 12px;white-space:nowrap;'+(approvalsDate(x.due_date)&&approvalsDate(x.due_date)<new Date()?'color:var(--red);font-weight:800':'color:var(--text2)')+'">'+escH(approvalsDateLabel(x.due_date,'Not set'))+'</td>'
      +'<td style="padding:10px 12px;color:var(--text2);font-size:11px">'+escH(x.confidentiality||'Standard')+'</td>'
      +'<td style="padding:10px 12px;color:var(--text2);white-space:nowrap">'+escH(approvalsDateLabel(x.updated_at,'-'))+'</td>'
      +'<td style="padding:10px 12px;text-align:right"><button class="btn btn-sm" data-auris-runtime-onclick="r0128" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.row_key]))+'"><i class="ti ti-arrow-right"></i>Open record</button></td>'
      +'</tr>';
  }).join('');
}

async function approvalsOpen(rowKey){
  var x=(approvalCenterRows||[]).find(function(r){return r.row_key===rowKey;});if(!x)return toast('This approval is no longer in the current queue. Refresh and try again.',false);
  if(x.page&&!canAccessPage(x.page))return toast('Your current role cannot open '+x.module+'.',false);
  try{
    if(x.opener==='contractor_document'&&typeof cmuOpenDocument==='function'){showPage('contractor',null);return setTimeout(function(){cmuOpenDocument(x.open_id);},350);}
    if(x.opener==='swms'&&typeof swmsOpen==='function'){showPage('swms',null);return setTimeout(function(){swmsOpen(x.open_id);},350);}
    if(x.opener==='contractor_profile'&&typeof conOpenDetail==='function'){showPage('contractor',null);return setTimeout(function(){conOpenDetail(x.open_id);},350);}
    if(x.opener==='tools_profile'&&typeof teuOpenProfile==='function'){showPage('tools',null);return setTimeout(function(){teuOpenProfile(x.open_id);},350);}
    if(x.opener==='tools_assurance'&&typeof teuOpenAssurance==='function'){showPage('tools',null);return setTimeout(function(){teuOpenAssurance(x.open_id);},350);}
    if(x.opener==='tools_maintenance'&&typeof teuOpenMaintenance==='function'){showPage('tools',null);return setTimeout(function(){teuOpenMaintenance(x.open_id);},350);}
    if(x.opener==='bbs_entity'&&typeof bbsOpenEntity==='function'){showPage('observation',null);return setTimeout(function(){bbsOpenEntity(x.entity,x.open_id);},350);}
    if(x.opener==='engagement_review'&&typeof seOpenTeamReview==='function'){showPage('engagement',null);return setTimeout(function(){seOpenTeamReview(x.open_id);},350);}
    if(x.opener==='engagement_entity'&&typeof seOpenDrawer==='function'){showPage('engagement',null);return setTimeout(function(){seOpenDrawer('record-view',x.open_id,x.entity);},350);}
    if(x.opener==='noise_map'&&typeof noiseOpenMapWorkspace==='function'){showPage('noise',null);return setTimeout(function(){noiseOpenMapWorkspace(x.open_id);},350);}
    if(x.opener==='noise_record'&&typeof noiseOpenRecord==='function'){showPage('noise',null);return setTimeout(function(){noiseOpenRecord(x.entity,x.open_id);},350);}
    deepLinkStore(deepLinkNormalise({goto:x.page||x.adapter_key,record:x.open_id||x.record_id,ref:x.ref,table:x.open_table||x.table,company:x.company_id||''}));
    return deepLinkResume('approval-center');
  }catch(e){toast('Unable to open '+x.ref+': '+e.message,false);}
}

