var auditRows = [];

function auditCanView(){
  return ['sephs_admin','admin','hse_manager','hse_officer'].indexOf(activeRole()) !== -1;
}

function auditCompanyFilter(){
  if(isSA() && sephsCompanyContext) return sephsCompanyContext;
  if(isSA()) return null;
  return prof?.company_id || null;
}

async function loadAudit(){
  var el=document.getElementById('audit-table-body');
  if(!el)return;
  if(!auditCanView()){
    el.innerHTML='<tr><td colspan="7" style="padding:18px;color:var(--red);text-align:center">Access denied</td></tr>';
    return;
  }
  el.innerHTML='<tr><td colspan="7" style="padding:20px;text-align:center;color:var(--text2)">Loading audit trail...</td></tr>';
  try{
    var companyId=auditCompanyFilter();
    var scope=document.getElementById('audit-scope-label');
    if(scope)scope.textContent=isSA()?(companyId?'Selected company':'All companies'):(co?.name||'Current company');
    var path='/audit_events?select=*&order=created_at.desc&limit=300';
    if(companyId)path+='&company_id=eq.'+companyId;
    auditRows=await api(path)||[];
    auditPopulateFilters();
    auditRender();
  }catch(e){
    var msg=e.message||'Unknown error';
    el.innerHTML='<tr><td colspan="7" style="padding:18px">'+setupFriendlyMessage('Audit trail',msg)+'</td></tr>';
  }
}

function auditPopulateFilters(){
  var actionSel=document.getElementById('audit-filter-action');
  if(actionSel){
    var selectedAction=actionSel.value||'',actions=Array.from(new Set(AUDIT_EVENT_CONTRACT.mandatory.concat((auditRows||[]).map(function(x){return x.action||'';})).filter(Boolean))).sort();
    actionSel.innerHTML='<option value="">All actions</option>'+actions.map(function(a){return '<option value="'+escH(a)+'">'+escH(auditLabel(a))+'</option>';}).join('');
    if(actions.indexOf(selectedAction)!==-1)actionSel.value=selectedAction;
  }
  var moduleSel=document.getElementById('audit-filter-module');
  if(moduleSel){
    var current=moduleSel.value||'';
    var mods=[].concat(new Set((auditRows||[]).map(function(x){return x.module_name||x.related_table||'';}).filter(Boolean))).sort();
    moduleSel.innerHTML='<option value="">All modules</option>'+mods.map(function(m){return '<option value="'+escH(m)+'">'+escH(auditLabel(m))+'</option>';}).join('');
    moduleSel.value=current;
  }
  var count=document.getElementById('audit-count');
  if(count)count.textContent=String((auditRows||[]).length);
  var todayEl=document.getElementById('audit-today-count');
  if(todayEl){
    var today=new Date().toISOString().slice(0,10);
    todayEl.textContent=String((auditRows||[]).filter(function(x){return String(x.created_at||'').slice(0,10)===today;}).length);
  }
}

function auditLabel(v){
  return String(v||'').replace(/_/g,' ').replace(/\b\w/g,function(c){return c.toUpperCase();});
}

function auditActionBadge(action){
  var a=String(action||'').toLowerCase();
  var cfg={
    create:['#EAF3DE','#3B6D11'],
    update:['#EFF6FF','#185FA5'],
    delete:['#FCEBEB','#A32D2D'],
    login:['#ECFDF5','#065F46'],
    logout:['#F3F4F6','#374151'],
    ai_query:['#F5F3FF','#5B21B6'],
    ai_error:['#FCEBEB','#A32D2D'],
    export:['#FEF9EC','#854F0B'],
    sync:['#E0F2FE','#075985'],
    submit:['#FFF7ED','#9A3412'],
    approve:['#EAF3DE','#3B6D11'],
    reject:['#FCEBEB','#A32D2D'],
    archive:['#F3F4F6','#374151'],
    link:['#ECFDF5','#047857'],
    unlink:['#FFF1F2','#BE123C'],
    open_sensitive:['#F5F3FF','#6D28D9']
  }[a]||['#f3f4f6','#6B7280'];
  var bg=cfg[0], c=cfg[1];
  return '<span style="display:inline-flex;align-items:center;padding:3px 8px;border-radius:999px;background:'+bg+';color:'+c+';font-size:11px;font-weight:700">'+escH(auditLabel(a||'action'))+'</span>';
}

function auditFilteredRows(){
  var q=(document.getElementById('auditlog-search')?.value||'').toLowerCase();
  var action=document.getElementById('audit-filter-action')?.value||'';
  var module=document.getElementById('audit-filter-module')?.value||'';
  return (auditRows||[]).filter(function(x){
    if(action && String(x.action||'')!==action)return false;
    if(module && String(x.module_name||x.related_table||'')!==module)return false;
    if(q){
      var hay=[x.actor_name,x.actor_role,x.action,x.module_name,x.related_table,x.summary,JSON.stringify(x.details||{})].join(' ').toLowerCase();
      if(hay.indexOf(q)===-1)return false;
    }
    return true;
  });
}

function auditRender(){
  var el=document.getElementById('audit-table-body');if(!el)return;
  var rows=auditFilteredRows();
  var shown=document.getElementById('audit-shown-count');
  if(shown)shown.textContent=String(rows.length);
  if(!rows.length){
    el.innerHTML='<tr><td colspan="7" style="padding:24px;text-align:center;color:var(--text2)">No audit events found</td></tr>';
    return;
  }
  el.innerHTML=rows.map(function(x){
    var details=x.details||{};
    var fields=Array.isArray(details.changed_fields)?details.changed_fields.join(', '):'';
    return '<tr style="border-bottom:1px solid var(--border)">'
      +'<td style="padding:10px 12px;white-space:nowrap;color:var(--text2);font-size:12px">'+(x.created_at?new Date(x.created_at).toLocaleString():'-')+'</td>'
      +'<td style="padding:10px 12px">'+auditActionBadge(x.action)+'</td>'
      +'<td style="padding:10px 12px;font-weight:700">'+escH(auditLabel(x.module_name||x.related_table||'-'))+'</td>'
      +'<td style="padding:10px 12px">'+escH(x.actor_name||'-')+'<div style="font-size:11px;color:var(--text2)">'+escH(auditLabel(x.actor_role||''))+'</div></td>'
      +'<td style="padding:10px 12px;max-width:360px">'+escH(x.summary||'')+'<div style="font-size:11px;color:var(--text2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escH(fields||details.path||'')+'</div></td>'
      +'<td style="padding:10px 12px;font-family:monospace;font-size:11px;color:var(--text2)">'+escH(x.related_ref||x.related_id||'-')+(x.relationship_id?'<div style="margin-top:3px;color:#047857">Relationship '+escH(String(x.relationship_id).slice(0,8))+'</div>':'')+'</td>'
      +'<td style="padding:10px 12px;text-align:right"><button class="btn btn-sm" data-auris-runtime-onclick="r0129" data-auris-runtime-args="'+encodeURIComponent(JSON.stringify([x.id]))+'"><i class="ti ti-copy"></i>Details</button></td>'
      +'</tr>';
  }).join('');
}

function auditCopyDetails(id){
  var x=(auditRows||[]).find(function(r){return r.id===id;});
  if(!x)return;
  var txt=JSON.stringify(x,null,2);
  var modal=document.getElementById('audit-detail-modal');
  if(!modal){
    modal=document.createElement('div');
    modal.id='audit-detail-modal';
    modal.style.cssText='display:none;position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:920;align-items:center;justify-content:center;padding:16px';
    modal.innerHTML='<div class="card" style="width:100%;max-width:760px;max-height:88vh;overflow:auto;border-radius:12px;padding:0;box-shadow:0 20px 70px rgba(15,23,42,.30)">'
      +'<div style="padding:16px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;gap:12px;align-items:flex-start"><div><div style="font-size:16px;font-weight:900">Audit event details</div><div id="audit-detail-sub" style="font-size:12px;color:var(--text2);margin-top:3px"></div></div><button class="btn btn-sm" id="audit-detail-close"><i class="ti ti-x"></i></button></div>'
      +'<div id="audit-detail-body" style="padding:18px 20px"></div>'
      +'<div style="padding:14px 20px;border-top:1px solid var(--border);display:flex;justify-content:flex-end;gap:8px;background:#fff"><button class="btn" id="audit-detail-copy"><i class="ti ti-copy"></i>Copy JSON</button><button class="btn btn-primary" id="audit-detail-done">Done</button></div>'
      +'</div>';
    document.body.appendChild(modal);
  }
  var details=x.details||{};
  var fields=Array.isArray(details.changed_fields)?details.changed_fields:[];
  var sub=document.getElementById('audit-detail-sub');
  if(sub)sub.textContent=(x.created_at?new Date(x.created_at).toLocaleString():'-')+' - '+(x.actor_name||'User');
  var body=document.getElementById('audit-detail-body');
  if(body)body.innerHTML='<div style="display:grid;grid-template-columns:130px 1fr;gap:9px 14px;font-size:13px">'
    +'<div style="color:var(--text2);font-weight:700">Action</div><div>'+auditActionBadge(x.action)+'</div>'
    +'<div style="color:var(--text2);font-weight:700">Module</div><div style="font-weight:800">'+escH(auditLabel(x.module_name||x.related_table||'-'))+'</div>'
    +'<div style="color:var(--text2);font-weight:700">User</div><div>'+escH(x.actor_name||'-')+' <span style="color:var(--text2)">('+escH(auditLabel(x.actor_role||''))+')</span></div>'
    +'<div style="color:var(--text2);font-weight:700">Record</div><div style="font-family:monospace;font-size:12px">'+escH(x.related_id||'-')+'</div>'
    +'<div style="color:var(--text2);font-weight:700">Reference</div><div>'+escH(x.related_ref||'-')+'</div>'
    +'<div style="color:var(--text2);font-weight:700">Relationship</div><div style="font-family:monospace;font-size:12px">'+escH(x.relationship_id||'Not applicable')+'</div>'
    +'<div style="color:var(--text2);font-weight:700">Event code</div><div>'+escH(x.event_code||((x.module_name||'system')+'.'+(x.action||'event')))+'</div>'
    +'<div style="color:var(--text2);font-weight:700">Summary</div><div>'+escH(x.summary||'-')+'</div>'
    +'<div style="color:var(--text2);font-weight:700">Changed fields</div><div>'+escH(fields.length?fields.join(', '):'No field list recorded')+'</div>'
    +'</div><details style="margin-top:16px"><summary style="cursor:pointer;font-weight:800;color:var(--text2)">Raw event JSON</summary><pre style="margin-top:10px;white-space:pre-wrap;background:#0f172a;color:#e5e7eb;border-radius:8px;padding:12px;font-size:11px;max-height:260px;overflow:auto">'+escH(txt)+'</pre></details>';
  var close=function(){modal.style.display='none';};
  var closeBtn=document.getElementById('audit-detail-close');
  var doneBtn=document.getElementById('audit-detail-done');
  var copyBtn=document.getElementById('audit-detail-copy');
  if(closeBtn)closeBtn.onclick=close;
  if(doneBtn)doneBtn.onclick=close;
  if(copyBtn)copyBtn.onclick=function(){
    if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(txt).then(function(){toast('Audit details copied');});
    else toast(txt);
  };
  modal.onclick=function(e){if(e.target===modal)close();};
  modal.style.display='flex';
}

function auditExportCsv(){
  var rows=auditFilteredRows();
  if(!rows.length){toast('No audit rows to export',false);return;}
  var cols=['created_at','event_code','action','module_name','actor_name','actor_role','summary','related_table','related_id','related_ref','relationship_id','outcome','sensitivity','correlation_id'];
  var csv=[cols.join(',')].concat(rows.map(function(r){
    return cols.map(function(c){
      var v=r[c]||'';
      return '"'+String(v).replace(/"/g,'""')+'"';
    }).join(',');
  })).join('\n');
  var blob=new Blob([csv],{type:'text/csv;charset=utf-8'});
  var url=URL.createObjectURL(blob);
  var a=document.createElement('a');
  a.href=url;
  a.download='auris360-audit-trail-'+new Date().toISOString().slice(0,10)+'.csv';
  document.body.appendChild(a);
  a.click();
  setTimeout(function(){URL.revokeObjectURL(url);a.remove();},500);
  auditLogEvent('export','audit','Audit trail exported',{rows:rows.length,columns:cols});
}



// ================================================================
// AURIS360 PDF REPORT GENERATOR
// Uses browser print-to-PDF - no external libraries needed
// Reports: Incident, Risk Assessment, Audit, Permit, Contractor
// ================================================================

// -- Core print engine --------------------------------------------
function aurisPrint(html, title) {
  var printTitle=String(title||'');
  var isRiskPrint=printTitle.toLowerCase().includes('risk assessment');
  var isLandscapePrint=isRiskPrint||printTitle.toLowerCase().includes('fire certificate compliance report');
  var w = window.open('', '_blank', isLandscapePrint?'width=1280,height=820':'width=900,height=700');
  if (!w) { toast('Please allow popups for PDF generation', false); return; }
  var brand=(window.Brand&&window.Brand.get)?window.Brand.get():{};
  function safePrintColor(value,fallback){return /^#[0-9a-f]{3,8}$/i.test(String(value||''))?String(value):fallback;}
  var printVariables='--auris-print-primary:'+safePrintColor(brand.primary,'#1D9E75')+';--auris-print-secondary:'+safePrintColor(brand.secondary,'#0F6E56')+';--auris-print-accent:'+safePrintColor(brand.accent,'#EF9F27');
  w.document.write('<!DOCTYPE html><html><head>'
    + '<meta charset="UTF-8">'
    + '<title>' + escH(title) + '</title>'
    + '<link id="auris-print-styles" rel="stylesheet" href="/auris-print.css">'
    + '</head><body class="'+(isLandscapePrint?'auris-print-landscape':'auris-print-portrait')+'" style="'+printVariables+'">' + html + '</body></html>');
  w.document.close();
  w.focus();
  var printed=false;
  function printWhenReady(){if(printed)return;printed=true;w.focus();w.print();}
  var stylesheet=w.document.getElementById('auris-print-styles');
  if(stylesheet){stylesheet.addEventListener('load',printWhenReady,{once:true});stylesheet.addEventListener('error',printWhenReady,{once:true});}
  setTimeout(printWhenReady,1200);
}

function aurisPrintCSS() {
  // Pull live brand colours so the PDF/print output matches the on-screen branding
  var B = (window.Brand && window.Brand.get) ? window.Brand.get() : {primary:'#1D9E75', secondary:'#0F6E56', accent:'#EF9F27'};
  var P = B.primary   || '#1D9E75';
  var S = B.secondary || '#0F6E56';
  var A = B.accent    || '#EF9F27';
  return `
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: Arial, Helvetica, sans-serif; font-size: 11pt; color: #1a1a1a; background: #fff; }
    .report-page { max-width: 210mm; margin: 0 auto; padding: 12mm; }

    /* Header */
    .rpt-header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid ${P}; padding-bottom: 10px; margin-bottom: 16px; }
    .rpt-logo-wrap { display: flex; align-items: center; gap: 12px; min-width: 0; }
    .rpt-brand-pair { display: flex; align-items: center; gap: 14px; min-width: 0; }
    .rpt-brand-divider { width: 1px; height: 42px; background: #d1d5db; }
    .rpt-logo-img { max-height: 44px; max-width: 160px; object-fit: contain; }
    .rpt-auris-logo { height: 34px; width: auto; object-fit: contain; }
    .rpt-client-logo { max-height: 42px; max-width: 120px; object-fit: contain; border: 1px solid #e5e7eb; border-radius: 6px; padding: 3px; background: #fff; }
    .rpt-logo { font-size: 22pt; font-weight: 900; color: ${P}; letter-spacing: -1px; }
    .rpt-client-name { font-size: 13pt; font-weight: 900; color: #111827; line-height: 1.1; }
    .rpt-company { font-size: 9pt; color: #6b7280; margin-top: 2px; }
    .rpt-meta { text-align: right; font-size: 9pt; color: #6b7280; }
    .rpt-meta strong { color: #1a1a1a; }

    /* Title */
    .rpt-title { font-size: 16pt; font-weight: 700; color: #1a1a1a; margin-bottom: 4px; }
    .rpt-subtitle { font-size: 10pt; color: #6b7280; margin-bottom: 16px; }

    /* Sections */
    .rpt-section { margin-bottom: 16px; }
    .rpt-section-title { font-size: 11pt; font-weight: 700; color: #fff; background: ${P}; padding: 5px 10px; border-radius: 4px; margin-bottom: 8px; }
    .rpt-section-title.red { background: #DC2626; }
    .rpt-section-title.blue { background: #185FA5; }
    .rpt-section-title.amber { background: ${A}; }
    .rpt-section-title.secondary { background: ${S}; }
    .rpt-section-title.grey { background: #374151; }

    /* Fields grid */
    .rpt-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 16px; margin-bottom: 8px; }
    .rpt-grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px 12px; }
    .rpt-field { border-bottom: 1px solid #e5e7eb; padding-bottom: 4px; }
    .rpt-field label { font-size: 8pt; color: #6b7280; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; display: block; }
    .rpt-field span { font-size: 10pt; color: #1a1a1a; }
    .rpt-full { grid-column: 1 / -1; }

    /* Tables */
    table { width: 100%; border-collapse: collapse; font-size: 9pt; margin-bottom: 10px; page-break-inside: auto; }
    thead { display: table-header-group; }
    tfoot { display: table-footer-group; }
    tr { page-break-inside: avoid; page-break-after: auto; }
    th { background: #e5e7eb !important; color: #111827 !important; font-weight: 800; text-align: left; padding: 6px 8px; border: 1px solid #cbd5e1; font-size: 8pt; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    td { padding: 5px 8px; border: 1px solid #e5e7eb; vertical-align: top; overflow-wrap: anywhere; }
    tr:nth-child(even) td { background: #f9fafb; -webkit-print-color-adjust: exact; print-color-adjust: exact; }

    /* Badges */
    .badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 8pt; font-weight: 700; }
    .badge-red { background: #FEE2E2; color: #DC2626; }
    .badge-amber { background: #FEF3C7; color: #92400E; }
    .badge-green { background: #D1FAE5; color: #065F46; }
    .badge-blue { background: #DBEAFE; color: #1E40AF; }
    .badge-grey { background: #F3F4F6; color: #374151; }

    /* Signature boxes */
    .rpt-signatures { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; margin-top: 20px; }
    .rpt-sig-box { border-top: 2px solid #1a1a1a; padding-top: 6px; }
    .rpt-sig-box label { font-size: 8pt; color: #6b7280; font-weight: 600; display: block; }
    .rpt-sig-box .sig-line { height: 30px; }

    /* Footer */
    .rpt-footer { margin-top: 20px; padding-top: 8px; border-top: 1px solid #e5e7eb; display: flex; justify-content: space-between; font-size: 8pt; color: #9ca3af; }
    .rpt-footer-custom { margin-top: 6px; padding-top: 6px; border-top: 1px dashed #e5e7eb; text-align: center; font-size: 8pt; color: #6b7280; font-style: italic; }
    .rpt-powered { margin-top: 4px; text-align: center; font-size: 7pt; color: #b8bcc4; }
    .rpt-empty { border: 1px dashed #cbd5e1; border-radius: 8px; padding: 18px; text-align: center; color: #64748b; background: #f8fafc; font-size: 10pt; line-height: 1.45; }
    .rpt-print-note { margin: 0 0 10px; color: #64748b; font-size: 8pt; }

    /* Print settings */
    @page { size: A4; margin: 10mm; }
    @media print {
      html, body { background: #fff !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
      .no-print, .sidebar, .topbar, .mobile-topbar, .mobile-bottom3nav, .fab, .ai-fab, .dev-badge, button { display: none !important; }
      .report-page { box-shadow: none !important; margin: 0 auto !important; }
      a { color: #111827 !important; text-decoration: none !important; }
    }
  `;
}

function aurisHeader(title, subtitle, refNo) {
  var today = new Date().toLocaleDateString('en-GB', {day:'2-digit', month:'short', year:'numeric'});
  var B = (window.Brand && window.Brand.get) ? window.Brand.get() : {};
  var companyName = (co && co.name) || (B && B.display_name) || 'Company';
  var companyLogo = aurisSafeMediaUrl((co && co.logo_url) || '','image') || null;
  var tagline = (B && B.tagline) || 'HSE Management Platform';
  var aurisLogo = '/assets/auris360-logo-final.png';

  var logoBlock = '<div class="rpt-brand-pair">'
    + '<div class="rpt-logo-wrap"><img class="rpt-auris-logo" src="' + aurisLogo + '" alt="AURIS360"/><div><div class="rpt-logo" style="font-size:13pt">AURIS360</div><div class="rpt-company">HSE Management Platform</div></div></div>'
    + '<div class="rpt-brand-divider"></div>'
    + '<div class="rpt-logo-wrap">'
    + (companyLogo ? '<img class="rpt-client-logo" src="' + escH(companyLogo) + '" alt="' + escH(companyName) + '"/>' : '')
    + '<div><div class="rpt-client-name">' + escH(companyName) + '</div><div class="rpt-company">' + escH(tagline) + '</div></div>'
    + '</div></div>';

  return '<div class="rpt-header">'
    + logoBlock
    + '<div class="rpt-meta"><strong>' + escH(refNo||'') + '</strong><br>Generated: ' + today + '<br>' + escH(companyName) + '</div>'
    + '</div>'
    + '<div class="rpt-title">' + escH(title) + '</div>'
    + (subtitle ? '<div class="rpt-subtitle">' + escH(subtitle) + '</div>' : '');
}

function aurisFooter(docType) {
  var B = (window.Brand && window.Brand.get) ? window.Brand.get() : null;
  var customFooter = B && B.pdf_footer_text;
  var hidePoweredBy = B && B.hide_poweredby;
  var displayName = (B && B.display_name) || (co&&co.name) || 'AURIS360';

  var html = '<div class="rpt-footer">'
    + '<span>' + escH(displayName) + ' | ' + escH(docType) + '</span>'
    + '<span>This document is system3generated. Verify with original records.</span>'
    + '<span>Page 1 of 1</span>'
    + '</div>';

  if (customFooter) {
    html += '<div class="rpt-footer-custom">' + escH(customFooter) + '</div>';
  }
  if (!hidePoweredBy) {
    html += '<div class="rpt-powered" data-powered-by>Powered by AURIS360 - SEPHS Consulting</div>';
  }
  return html;
}

function fld(label, value, full) {
  return '<div class="rpt-field' + (full?' rpt-full':'') + '"><label>' + label + '</label><span>' + escH(value||'-') + '</span></div>';
}

function badge(val, map) {
  var cls = (map&&map[val]) || 'badge-grey';
  return '<span class="badge ' + cls + '">' + escH(val||'-') + '</span>';
}

// -- 1. INCIDENT REPORT ------------------------------------------
function printIncidentReport(invId) {
  // Look in the IMS data store first (canonical), fall back to the legacy var if present
  var src = (typeof imsInvAllData !== 'undefined' ? imsInvAllData : null) || (typeof invAllData !== 'undefined' ? invAllData : []);
  var inv = (src || []).find(function(x){ return x.id === invId; });
  if (!inv) { toast('Incident not found', false); return; }

  var sevMap = {critical:'badge-red', high:'badge-red', medium:'badge-amber', low:'badge-green', negligible:'badge-grey'};
  var statusMap = {open:'badge-red', 'under_investigation':'badge-amber', closed:'badge-green', 'no_action':'badge-grey'};

  var actions = (typeof actionAllData !== 'undefined' ? actionAllData : [])
    .filter(function(a){ return a.related_id === invId; });

  var html = '<div class="report-page">'
    + aurisHeader('Incident Report', 'Workplace Incident / Near Miss Investigation Record', displayRecordRef(inv,['inv_ref','event_ref','incident_number'],'INC-DRAFT'))

    + '<div class="rpt-section"><div class="rpt-section-title red">Incident Details</div>'
    + '<div class="rpt-grid">'
    + fld('Reference No.', inv.inv_ref)
    + fld('Date of Incident', inv.incident_date ? new Date(inv.incident_date).toLocaleDateString('en-GB') : '')
    + fld('Severity', '') + '</div>'
    + '<div class="rpt-grid">'
    + '<div class="rpt-field"><label>Severity</label><span>' + badge(inv.severity, sevMap) + '</span></div>'
    + '<div class="rpt-field"><label>Status</label><span>' + badge(inv.status, statusMap) + '</span></div>'
    + fld('Location', inv.location)
    + fld('Department', inv.department)
    + fld('Reported By', inv.reported_by)
    + fld('Person Involved', inv.person_involved)
    + '</div>'
    + '<div class="rpt-grid">'
    + fld('Description', inv.incident_description, true)
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title amber">Classification</div>'
    + '<div class="rpt-grid-3">'
    + fld('H&S Incident', inv.class_hs ? 'Yes' : 'No')
    + fld('Environmental', inv.class_env ? 'Yes' : 'No')
    + fld('Property Damage', inv.class_property ? 'Yes' : 'No')
    + fld('First Aid', inv.class_first_aid ? 'Yes' : 'No')
    + fld('Medical Treatment', inv.class_medical ? 'Yes' : 'No')
    + fld('Lost Time Injury', inv.class_lti ? 'Yes' : 'No')
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title">Root Cause Analysis</div>'
    + '<div class="rpt-grid">'
    + fld('Immediate Cause', inv.immediate_cause, true)
    + fld('Root Cause', inv.root_cause, true)
    + fld('Contributing Factors', inv.contributing_factors, true)
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title blue">Corrective Actions</div>'
    + (actions.length ? '<table><thead><tr><th>Action</th><th>Responsible</th><th>Due Date</th><th>Status</th></tr></thead><tbody>'
      + actions.map(function(a){
          return '<tr><td>' + escH(a.description||'') + '</td><td>' + escH(a.responsible||'') + '</td>'
            + '<td>' + (a.due_date?new Date(a.due_date).toLocaleDateString('en-GB'):'-') + '</td>'
            + '<td><span class="badge ' + (a.status==='closed'?'badge-green':a.status==='overdue'?'badge-red':'badge-amber') + '">' + escH(a.status||'') + '</span></td></tr>';
        }).join('') + '</tbody></table>'
      : '<p style="color:#6b7280;font-size:9pt;padding:8px">No corrective actions recorded.</p>')
    + '</div>'

    + '<div class="rpt-signatures">'
    + '<div class="rpt-sig-box"><div class="sig-line"></div><label>Reported By / Date</label></div>'
    + '<div class="rpt-sig-box"><div class="sig-line"></div><label>HSE Manager / Date</label></div>'
    + '<div class="rpt-sig-box"><div class="sig-line"></div><label>Site Manager / Date</label></div>'
    + '</div>'
    + aurisFooter('Incident Report')
    + '</div>';

  aurisPrint(html, 'Incident Report - ' + (inv.inv_ref||invId.substring(0,8)));
}

function raRiskMatrixPrintHtml(){
  var severity=[
    ['1','Negligible','First aid case, temporary stakeholder impact, minor asset damage or local mention'],
    ['2','Minor','Medical treatment injury, local concern under 1 week clean-up, asset loss under 5%'],
    ['3','Moderate','Major injury / hospitalisation, LTI 1-3 days, external scrutiny or asset loss under 10%'],
    ['4','Major','Single fatality or multiple major injuries, licence impact, asset loss under 30%'],
    ['5','Extreme','Multiple fatalities, long-term environmental impact, major asset destruction or government inquiry']
  ];
  var likelihood=[
    ['1','Rare','Exceptional circumstances (<5%)'],
    ['2','Unlikely','Could occur at some time (<35%)'],
    ['3','Possible','Might occur at some time (>35% - <65%)'],
    ['4','Likely','Will probably occur (>65% - <95%)'],
    ['5','Almost Certain','Expected in most circumstances (>95%)']
  ];
  var riskCell=function(score,s,p){
    var level=raRiskLevelFromFactors(s,p);
    var cfg={Low:['#D1FAE5','#065F46'],Medium:['#FEF3C7','#92400E'],High:['#FFEDD5','#C2410C'],'Very High':['#FEE2E2','#B91C1C'],Critical:['#7F1D1D','#fff']}[level]||['#F3F4F6','#374151'];
    return '<td style="padding:5px;border:1px solid #fff;text-align:center;background:'+cfg[0]+';color:'+cfg[1]+';font-weight:900">'+score+'<div style="font-size:7pt;font-weight:700">'+level+'</div></td>';
  };
  return '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">'
    +'<table><thead><tr><th colspan="3">Severity Criteria</th></tr></thead><tbody>'
    +severity.map(function(s){return '<tr><td style="width:8%;font-weight:900">'+s[0]+'</td><td style="width:28%;font-weight:700">'+s[1]+'</td><td>'+s[2]+'</td></tr>';}).join('')
    +'</tbody></table>'
    +'<table><thead><tr><th colspan="3">Likelihood / Probability Criteria</th></tr></thead><tbody>'
    +likelihood.map(function(p){return '<tr><td style="width:8%;font-weight:900">'+p[0]+'</td><td style="width:28%;font-weight:700">'+p[1]+'</td><td>'+p[2]+'</td></tr>';}).join('')
    +'</tbody></table></div>'
    +'<table><thead><tr><th style="width:20%">Likelihood x Severity</th>'
    +[1,2,3,4,5].map(function(s){return '<th>S'+s+'</th>';}).join('')
    +'</tr></thead><tbody>'
    +[5,4,3,2,1].map(function(p){
      return '<tr><th>P'+p+' '+likelihood[p-1][1]+'</th>'+[1,2,3,4,5].map(function(s){return riskCell(p*s,s,p);}).join('')+'</tr>';
    }).join('')
    +'</tbody></table>'
    +'<div style="font-size:8pt;color:#374151;background:#F8FBFF;border:1px solid #DBEAFE;padding:6px 8px;border-radius:4px"><strong>RAMS rule:</strong> inherent risk is assessed before controls, controls follow the hierarchy of controls, and residual High / Very High work must not proceed until reduced or escalated for senior management / HSE review.</div>';
}

// -- 2. RISK ASSESSMENT REPORT ----------------------------------
function printRiskAssessment(raId) {
  var ra = (raAllData||[]).find(function(x){ return x.id === raId; });
  if (!ra) { toast('Risk assessment not found', false); return; }

  var rows = Array.isArray(ra.rows) ? ra.rows : (Array.isArray(ra.baseline_rows) ? ra.baseline_rows : []);
  if(!rows.length && typeof raRisks !== 'undefined'){
    rows = (raRisks||[]).filter(function(r){ return r.ra_id === raId; }).map(function(r){
      return {hazard:r.hazard,risk:r.risk,harm:r.risk,rr:r.initial_rr,controls:r.control_measures,res_rr:r.residual_rr};
    });
  }
  var fmtDate=function(v){return v?new Date(v).toLocaleDateString('en-GB'):'-';};
  var val=function(){for(var i=0;i<arguments.length;i++){if(arguments[i]!==undefined&&arguments[i]!==null&&String(arguments[i]).trim()!=='')return arguments[i];}return '';};
  var ref=displayRecordRef(ra,['ra_ref','reference_no','reference'],'RA-DRAFT');
  var typeLabel=auditLabel(val(ra.ra_type_v2,ra.ra_type,'risk assessment'));
  var statusMap={draft:'badge-grey',pending_review:'badge-amber',pending_approval:'badge-amber',review:'badge-amber',active:'badge-green',approved:'badge-green',rejected:'badge-red',archived:'badge-grey'};
  var riskBadge=function(level,score){
    var s=parseInt(score||0)||0;
    var l=String(level||'').toLowerCase();
    var cls=(l.includes('critical')||s>=20)?'badge-red':(l.includes('very')||l.includes('high')||s>=12)?'badge-red':(l.includes('medium')||s>=6)?'badge-amber':(s>0?'badge-green':'badge-grey');
    return '<span class="badge '+cls+'">'+escH(level||score||'-')+'</span>';
  };
  var legalRefs=Array.isArray(ra.legal_refs)?ra.legal_refs:[];
  var approvalStatus=String(ra.status||'draft').replace(/_/g,' ');
  var taskSteps=[];
  rows.forEach(function(r){
    var t=val(r.task,r.step,r.activity);
    if(t&&!taskSteps.find(function(x){return x.text===t;}))taskSteps.push({no:taskSteps.length+1,text:t});
  });

  var html = '<style>@page{size:A4 landscape;margin:8mm}html,body{width:297mm;min-height:210mm}.report-page{width:297mm;max-width:none!important;padding:8mm;box-sizing:border-box}table{font-size:7.6pt;table-layout:fixed;width:100%}th,td{padding:3px 4px;word-break:break-word;vertical-align:top}.rpt-grid{gap:4px 12px}.rpt-section{break-inside:avoid}</style><div class="report-page">'
    + aurisHeader('Controlled Risk Assessment', val(ra.title,ra.activity,'Risk assessment'), ref)

    + '<div class="rpt-section"><div class="rpt-section-title secondary">Document Control</div>'
    + '<div class="rpt-grid-3">'
    + fld('Reference', ref)
    + fld('Revision', 'Rev '+(ra.revision||1))
    + '<div class="rpt-field"><label>Status</label><span>'+badge(ra.status||'draft',statusMap)+'</span></div>'
    + fld('RA Type', typeLabel)
    + fld('Generated By', prof?.full_name||prof?.email||'AURIS360')
    + fld('Printed On', fmtDate(new Date()))
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title">Assessment Details</div>'
    + '<div class="rpt-grid">'
    + fld('Activity / Task', val(ra.activity,ra.title), true)
    + fld('Scope', ra.scope, true)
    + fld('Site / Area', val(ra.site_name,ra.workshop,ra.location))
    + fld('Location', val(ra.location,ra.workshop))
    + fld('Department', ra.department)
    + fld('Assessor', val(ra.assessed_by,ra.ra_assessor,ra.assessor))
    + fld('Assessment Date', fmtDate(val(ra.ra_date,ra.assessment_date,ra.date)))
    + fld('Review Date', fmtDate(val(ra.review_date,ra.ra_review_date)))
    + fld('Overall Risk', val(ra.overall_risk_level,ra.overall_risk_score))
    + fld('Linked Permit', ra.permit_ref)
    + fld('Job Segment', val(ra.job_segment,ra.ra_job_seg))
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title secondary">Task / Activity Breakdown</div>'
    + (taskSteps.length?'<table><thead><tr><th style="width:10%">Step</th><th>Activity / Work Task Step</th></tr></thead><tbody>'
      + taskSteps.map(function(s){return '<tr><td style="text-align:center;font-weight:700">'+s.no+'</td><td>'+escH(s.text)+'</td></tr>';}).join('')
      + '</tbody></table>'
      : '<div class="rpt-grid">'+fld('Activity / Work Task',val(ra.activity,ra.title),true)+'</div>')
    + '</div>'

    + '<div class="rpt-section"><div class="rpt-section-title red">Hazards, Controls & Residual Risk</div>'
    + (rows.length ? '<table><thead><tr><th style="width:5%">Step</th><th style="width:12%">Hazard</th><th style="width:13%">Risk Description / Harm</th><th style="width:18%">Existing Controls</th><th style="width:7%">Initial</th><th style="width:16%">Further Actions / Controls</th><th style="width:7%">Residual</th><th style="width:8%">Action by</th><th style="width:8%">Target date</th><th style="width:6%">Legal ref</th></tr></thead><tbody>'
      + rows.map(function(r){
          var hazard=val(r.task,r.hazard,r.condition,r.observed_risk);
          var task=val(r.task,r.step,r.activity);
          if(task&&r.hazard)hazard=r.hazard;
          var harm=val(r.harm,r.risk,r.consequence,r.potential_harm);
          var initialLevel=val(r.rl,r.initial_rl,r.risk_level);
          var initialScore=val(r.rr,r.initial_rr,r.risk_score);
          var residualLevel=val(r.res_rl,r.residual_rl,r.residual_risk_level);
          var residualScore=val(r.res_rr,r.residual_rr,r.residual_risk_score);
          var stepNo=task?((taskSteps.find(function(s){return s.text===task;})||{}).no||''):'';
          return '<tr>'
            + '<td style="text-align:center;font-weight:700">' + escH(stepNo||'-') + '</td>'
            + '<td>' + escH(hazard||'-') + '</td>'
            + '<td>' + escH(harm||'-') + '</td>'
            + '<td>' + escH(val(r.controls,r.control_measures,'-')) + (r.hoc_level?'<br><span style="font-size:8pt;color:#185FA5">Hierarchy: '+escH(r.hoc_level)+'</span>':'') + '</td>'
            + '<td>' + riskBadge(initialLevel,initialScore) + '<br><span style="font-size:8pt;color:#6b7280">S '+escH(val(r.rs,r.s,r.initial_s,'-'))+' / P '+escH(val(r.rop,r.p,r.initial_p,'-'))+'</span></td>'
            + '<td>' + escH(val(r.further_controls,r.further_actions,r.additional_controls,'-')) + '</td>'
            + '<td>' + riskBadge(residualLevel,residualScore) + '<br><span style="font-size:8pt;color:#6b7280">S '+escH(val(r.res_s,r.rs2,'-'))+' / P '+escH(val(r.res_p,r.rp2,'-'))+'</span></td>'
            + '<td>' + escH(val(r.action_by,r.responsible,r.owner,r.who,'-')) + '</td>'
            + '<td>' + fmtDate(val(r.target_date,r.due_date)) + '</td>'
            + '<td>' + escH(val(r.legal_ref,r.legal,'-')) + '</td>'
            + '</tr>';
        }).join('') + '</tbody></table>'
      : '<p style="color:#6b7280;font-size:9pt;padding:8px">No hazards or controls recorded.</p>')
    + '</div>'

    + '<div class="rpt-section"><div class="rpt-section-title grey">Risk Matrix & Assessment Criteria</div>'
    + raRiskMatrixPrintHtml()
    + '</div>'

    + '<div class="rpt-section"><div class="rpt-section-title blue">RAMS Linkage & Legal References</div>'
    + '<div class="rpt-grid">'
    + fld('RAMS Pack', 'This risk assessment forms the RA part of the RAMS pack. The linked SWMS / method statement defines the safe work sequence.', true)
    + fld('Linked SWMS / Method Statement', val(ra.rams_document_name,ra.rams_document_url), true)
    + fld('Legal References', legalRefs.length?legalRefs.join('; '):'-', true)
    + fld('Revision Notes', ra.revision_notes, true)
    + fld('Rejection / Review Comment', ra.rejection_reason, true)
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title amber">Approval & Briefing</div>'
    + '<div class="rpt-grid">'
    + fld('Approval Status', approvalStatus)
    + fld('Briefed Persons', ra.ra_briefed, true)
    + '</div></div>'

    + '<div class="rpt-signatures">'
    + '<div class="rpt-sig-box"><div class="sig-line">'+escH(val(ra.ra_sign_assessor,ra.assessed_by,ra.ra_assessor,''))+'</div><label>Assessor / '+fmtDate(ra.ra_sign_assessor_date)+'</label></div>'
    + '<div class="rpt-sig-box"><div class="sig-line">'+escH(val(ra.ra_sign_reviewer,ra.reviewed_by,''))+'</div><label>Reviewer / '+fmtDate(ra.ra_sign_reviewer_date)+'</label></div>'
    + '<div class="rpt-sig-box"><div class="sig-line">'+escH(val(ra.ra_sign_approver,ra.approved_by,ra.ra_approver,''))+'</div><label>Approver / '+fmtDate(ra.ra_sign_approver_date)+'</label></div>'
    + '</div>'
    + aurisFooter('Risk Assessment Report')
    + '</div>';

  aurisPrint(html, 'Risk Assessment - ' + ref);
}

// -- 3. AUDIT REPORT --------------------------------------------
function printAuditReport(auditId) {
  var audit = (auditAllData||[]).find(function(x){ return x.id === auditId; });
  if (!audit) { toast('Audit not found', false); return; }

  var val=function(){for(var i=0;i<arguments.length;i++){if(arguments[i]!==undefined&&arguments[i]!==null&&String(arguments[i]).trim()!=='')return arguments[i];}return '';};
  var fmtDate=function(v){return v?new Date(v).toLocaleDateString('en-GB'):'-';};
  var formOpen = auditEditId === auditId && document.getElementById('audit-form3view')?.style.display !== 'none';
  var g=function(id){var el=document.getElementById(id);return el?el.value||'':'';};
  var liveItems = [];
  if(formOpen){
    liveItems = (window.chkItems||[]).map(function(c,i){
      if(!c.item)return null;
      var result = document.getElementById('cg-'+i)?.checked ? 'good'
        : (document.getElementById('ci-'+i)?.checked ? 'insufficient'
        : (document.getElementById('cn-'+i)?.checked ? 'na' : ''));
      return {category:c.ca||'',item:c.item||'',guidance:c.guidance||'',result:result,observation:document.getElementById('co-'+i)?.value||''};
    }).filter(Boolean);
  }
  var items = liveItems.length ? liveItems : (Array.isArray(audit.items) ? audit.items : (Array.isArray(audit.checklist_results) ? audit.checklist_results : []));
  var findings = ((typeof auditFindingsData !== 'undefined' ? auditFindingsData : []).concat(typeof auditFindings !== 'undefined' ? auditFindings : []))
    .filter(function(f){ return f.inspection_id === auditId || f.audit_id === auditId; });
  var actions = formOpen
    ? Array.from(document.querySelectorAll('.if-action-row')).map(function(row){
        return {description:row.querySelector('.ia-desc')?.value||'',responsible:row.querySelector('.ia-who')?.value||'',target_date:row.querySelector('.ia-due')?.value||''};
      }).filter(function(a){return a.description;})
    : (Array.isArray(audit.action_items)?audit.action_items:[]);
  var photos = Array.isArray(audit.photos)?audit.photos:[];
  var goodCnt = items.filter(function(x){return x.result==='good'||x.result==='ok'||x.result==='pass';}).length;
  var insufCnt = items.filter(function(x){return x.result==='insufficient'||x.result==='nc'||x.result==='fail';}).length;
  var scoredTotal = goodCnt + insufCnt;
  var score = scoredTotal ? Math.round(goodCnt/scoredTotal*100)+'%' : (audit.score||'-');
  var ref = displayRecordRef(audit,['reference_no','audit_ref'],'INSP-DRAFT');
  var type = val(formOpen?g('audit-type'):'',audit.inspection_type,audit.audit_type,'workplace');
  var resultBadge=function(r){
    r=String(r||'').toLowerCase();
    var label = r==='good'||r==='ok'||r==='pass'?'Good':(r==='insufficient'||r==='nc'||r==='fail'?'Insufficient':(r==='na'?'N/A':'-'));
    var cls = label==='Good'?'badge-green':label==='Insufficient'?'badge-red':label==='N/A'?'badge-grey':'badge-grey';
    return '<span class="badge '+cls+'">'+label+'</span>';
  };

  var html = '<div class="report-page">'
    + aurisHeader('Inspection / Audit Report', auditLabel(type), ref)

    + '<div class="rpt-section"><div class="rpt-section-title">Audit Details</div>'
    + '<div class="rpt-grid">'
    + fld('Inspection Type', auditLabel(type))
    + fld('Location / Area', val(formOpen?g('if-site'):'',audit.site,audit.if_site,audit.location))
    + fld('Date', fmtDate(val(formOpen?g('if-date'):'',audit.inspection_date,audit.if_date,audit.audit_date)))
    + fld('Inspector / Auditor', val(formOpen?g('if-by'):'',audit.inspector,audit.if_by,audit.by,audit.auditor))
    + fld('Department', val(formOpen?g('audit-dept'):'',audit.department))
    + fld('Score', score)
    + fld('Status', val(formOpen?g('audit-status'):'',audit.status))
    + fld('Priority', val(formOpen?g('audit-priority'):'',audit.priority))
    + fld('Audit Standard', val(formOpen?g('audit-standard'):'',audit.audit_standard))
    + fld('Scope', val(formOpen?g('audit-scope'):'',audit.audit_scope), true)
    + fld('GPS / Address', val(formOpen?g('audit-gps-address'):'',audit.gps_address), true)
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title blue">Inspection Checklist</div>'
    + (items.length ? '<table><thead><tr><th style="width:20%">Category</th><th>Item / Requirement</th><th style="width:12%">Result</th><th style="width:30%">Observation / Notes</th></tr></thead><tbody>'
      + items.map(function(it){
          return '<tr><td>'+escH(it.category||it.ca||'')+'</td><td>'+escH(it.item||it.item_name||'')+'</td><td>'+resultBadge(it.result)+'</td><td>'+escH(it.observation||it.obs||it.note||'')+'</td></tr>';
        }).join('') + '</tbody></table>'
      : '<p style="color:#6b7280;font-size:9pt;padding:8px">No checklist details recorded.</p>')
    + '</div>'

    + '<div class="rpt-section"><div class="rpt-section-title red">Findings & Non-Conformances</div>'
    + (findings.length ? '<table><thead><tr><th>Type</th><th>Clause</th><th>Finding</th><th>Evidence</th><th>Action Required</th><th>Assigned To</th></tr></thead><tbody>'
      + findings.map(function(f){
          return '<tr>'
            + '<td>' + escH(auditLabel(f.finding_type||f.category||'')) + '</td>'
            + '<td>' + escH(f.clause||'') + '</td>'
            + '<td>' + escH(f.description||f.finding||'') + '</td>'
            + '<td>' + escH(f.evidence||'') + '</td>'
            + '<td>' + escH(f.corrective_action||f.action_required||'') + '</td>'
            + '<td>' + escH(f.assigned_to||f.responsible||'') + '</td>'
            + '</tr>';
        }).join('') + '</tbody></table>'
      : '<p style="color:#6b7280;font-size:9pt;padding:8px">No findings recorded.</p>')
    + '</div>'

    + '<div class="rpt-section"><div class="rpt-section-title blue">General Observations</div>'
    + '<div class="rpt-grid">'
    + fld('Positive Observations', val(formOpen?g('if-pos'):'',audit.positive_obs,audit.if_pos,audit.positive_observations), true)
    + fld('Issues / Non-Conformances', val(formOpen?g('if-neg'):'',audit.negative_obs,audit.if_neg,audit.comments), true)
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title amber">Corrective Actions & Evidence</div>'
    + (actions.length ? '<table><thead><tr><th>Action</th><th>Responsible</th><th>Due Date</th></tr></thead><tbody>'
      + actions.map(function(a){return '<tr><td>'+escH(a.description||'')+'</td><td>'+escH(a.responsible||a.assigned_to||'')+'</td><td>'+fmtDate(a.target_date||a.due_date)+'</td></tr>';}).join('')
      + '</tbody></table>' : '<p style="color:#6b7280;font-size:9pt;padding:8px">No corrective actions recorded.</p>')
    + (photos.length ? '<div class="rpt-grid">'+fld('Evidence Links', photos.map(function(p){return p.url||p;}).join('; '), true)+'</div>' : '')
    + '</div>'

    + '<div class="rpt-signatures">'
    + '<div class="rpt-sig-box"><div class="sig-line">'+escH(val(formOpen?g('if-sign-inspector'):'',audit.sign_inspector,''))+'</div><label>Inspector / '+fmtDate(val(formOpen?g('if-sign-date'):'',audit.sign_date))+'</label></div>'
    + '<div class="rpt-sig-box"><div class="sig-line"></div><label>Area Manager / Date</label></div>'
    + '<div class="rpt-sig-box"><div class="sig-line">'+escH(val(formOpen?g('if-sign-reviewer'):'',audit.sign_reviewer,''))+'</div><label>HSE Manager / '+fmtDate(val(formOpen?g('if-sign-reviewer-date'):'',audit.sign_reviewer_date))+'</label></div>'
    + '</div>'
    + aurisFooter('Audit / Inspection Report')
    + '</div>';

  aurisPrint(html, 'Audit Report - ' + ref);
}

