function printPermit(permitId) {
  var ptw = (ptwAllData||[]).find(function(x){ return x.id === permitId; });
  if (!ptw) { toast('Permit not found', false); return; }

  var statusMap = {active:'badge-green', approved:'badge-green', pending:'badge-amber', rejected:'badge-red', closed:'badge-grey', expired:'badge-red'};

  var html = '<div class="report-page">'
    + aurisHeader('Permit to Work', ptw.permit_type||'Work Permit', displayRecordRef(ptw,['permit_number','permit_ref'],'PTW-DRAFT'))

    + '<div class="rpt-section"><div class="rpt-section-title">Permit Details</div>'
    + '<div class="rpt-grid">'
    + fld('Permit Number', ptw.permit_number)
    + fld('Permit Type', ptw.permit_type)
    + '<div class="rpt-field"><label>Status</label><span>' + badge(ptw.status, statusMap) + '</span></div>'
    + fld('Location', ptw.location)
    + fld('Start Date/Time', ptw.start_datetime ? new Date(ptw.start_datetime).toLocaleString('en-GB') : '')
    + fld('End Date/Time', ptw.end_datetime ? new Date(ptw.end_datetime).toLocaleString('en-GB') : '')
    + fld('Contractor', ptw.contractor_name)
    + fld('Issued To', ptw.issued_to)
    + fld('Approved By', ptw.approved_by)
    + fld('Supervisor', ptw.supervisor)
    + fld('Work Description', ptw.work_description, true)
    + '</div></div>'

    + '<div class="rpt-section"><div class="rpt-section-title red">Hazards Identified</div>'
    + '<div class="rpt-grid"><div class="rpt-field rpt-full"><label>Hazards</label><span>' + escH(ptw.hazards||'-') + '</span></div></div>'
    + '</div>'

    + '<div class="rpt-section"><div class="rpt-section-title blue">Precautions & PPE Required</div>'
    + '<div class="rpt-grid">'
    + fld('Precautions', ptw.precautions, true)
    + fld('PPE Required', ptw.ppe_required, true)
    + fld('Isolation Required', ptw.isolation_required ? 'Yes' : 'No')
    + fld('Hot Work', ptw.hot_work ? 'Yes' : 'No')
    + fld('Confined Space', ptw.confined_space ? 'Yes' : 'No')
    + fld('Working at Height', ptw.working_at_height ? 'Yes' : 'No')
    + '</div></div>'

    + '<div class="rpt-signatures">'
    + '<div class="rpt-sig-box"><div class="sig-line"></div><label>Issued By / Date</label></div>'
    + '<div class="rpt-sig-box"><div class="sig-line"></div><label>Approved By / Date</label></div>'
    + '<div class="rpt-sig-box"><div class="sig-line"></div><label>Closed By / Date</label></div>'
    + '</div>'
    + aurisFooter('Permit to Work')
    + '</div>';

  aurisPrint(html, 'Permit to Work - ' + (ptw.permit_number||permitId.substring(0,8)));
}

// -- 5. HSE MONTHLY SUMMARY REPORT ------------------------------
async function printMonthlySummary() {
  toast('Generating monthly report...');
  try {
    var now = new Date();
    var monthStart = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
    var monthEnd = new Date(now.getFullYear(), now.getMonth()+1, 0).toISOString();
    var monthName = now.toLocaleDateString('en-GB', {month:'long', year:'numeric'});

    // Fetch this month's data
    var cid = prof.company_id ? '&company_id=eq.' + prof.company_id : '';
    var [events, audits, actions, permits] = await Promise.all([
      api('/events?created_at=gte.' + monthStart + '&created_at=lte.' + monthEnd + cid + '&select=*'),
      api('/inspections?inspection_date=gte.' + monthStart + '&inspection_date=lte.' + monthEnd + cid + '&select=*'),
      api('/action_tracker?created_at=gte.' + monthStart + '&created_at=lte.' + monthEnd + cid + '&select=*'),
      api('/permits?created_at=gte.' + monthStart + '&created_at=lte.' + monthEnd + cid + '&select=*'),
    ]);

    events  = events  || [];
    audits  = audits  || [];
    actions = actions || [];
    permits = permits || [];

    var critical = events.filter(function(e){ return e.severity==='critical'||e.severity==='high'; }).length;
    var openActions = actions.filter(function(a){ return a.status==='open'; }).length;
    var overdueActions = actions.filter(function(a){ return a.status==='overdue'; }).length;
    var avgScore = audits.length
      ? Math.round(audits.reduce(function(s,a){ return s + (a.score_good||0)/(a.total_items||1)*100; }, 0) / audits.length)
      : 0;

    var html = '<div class="report-page">'
      + aurisHeader('Monthly HSE Summary Report', monthName, 'MONTHLY-' + now.getFullYear() + (now.getMonth()+1).toString().padStart(2,'0'))

      + '<div class="rpt-section"><div class="rpt-section-title">Key Performance Indicators</div>'
      + '<div class="rpt-grid-3">'
      + '<div class="rpt-field"><label>Total Incidents</label><span style="font-size:18pt;font-weight:700;color:#DC2626">' + events.length + '</span></div>'
      + '<div class="rpt-field"><label>High/Critical</label><span style="font-size:18pt;font-weight:700;color:#EF9F27">' + critical + '</span></div>'
      + '<div class="rpt-field"><label>Inspections Done</label><span style="font-size:18pt;font-weight:700;color:#1D9E75">' + audits.length + '</span></div>'
      + '<div class="rpt-field"><label>Open Actions</label><span style="font-size:18pt;font-weight:700;color:#185FA5">' + openActions + '</span></div>'
      + '<div class="rpt-field"><label>Overdue Actions</label><span style="font-size:18pt;font-weight:700;color:#DC2626">' + overdueActions + '</span></div>'
      + '<div class="rpt-field"><label>Avg Audit Score</label><span style="font-size:18pt;font-weight:700;color:#1D9E75">' + avgScore + '%</span></div>'
      + '</div></div>'

      + '<div class="rpt-section"><div class="rpt-section-title red">Incidents This Month</div>'
      + (events.length ? '<table><thead><tr><th>Ref</th><th>Date</th><th>Severity</th><th>Location</th><th>Status</th></tr></thead><tbody>'
        + events.map(function(e){
            var cls = e.severity==='critical'?'badge-red':e.severity==='high'?'badge-red':e.severity==='medium'?'badge-amber':'badge-green';
            return '<tr><td>' + escH(e.inv_ref||'-') + '</td>'
              + '<td>' + (e.incident_date?new Date(e.incident_date).toLocaleDateString('en-GB'):'-') + '</td>'
              + '<td><span class="badge ' + cls + '">' + escH(e.severity||'') + '</span></td>'
              + '<td>' + escH(e.location||'-') + '</td>'
              + '<td><span class="badge ' + (e.status==='closed'?'badge-green':'badge-amber') + '">' + escH(e.status||'') + '</span></td>'
              + '</tr>';
          }).join('') + '</tbody></table>'
        : '<p style="color:#6b7280;font-size:9pt;padding:8px">No incidents recorded this month. ?</p>')
      + '</div>'

      + '<div class="rpt-section"><div class="rpt-section-title blue">Inspections & Audits</div>'
      + (audits.length ? '<table><thead><tr><th>Type</th><th>Date</th><th>Location</th><th>Score</th><th>Status</th></tr></thead><tbody>'
        + audits.map(function(a){
            var sc = a.score_good && a.total_items ? Math.round(a.score_good/a.total_items*100)+'%' : (a.score||'-');
            return '<tr><td>' + escH(a.audit_type||'Inspection') + '</td>'
              + '<td>' + (a.inspection_date?new Date(a.inspection_date).toLocaleDateString('en-GB'):'-') + '</td>'
              + '<td>' + escH(a.location||'-') + '</td>'
              + '<td>' + sc + '</td>'
              + '<td><span class="badge ' + (a.status==='closed'?'badge-green':'badge-amber') + '">' + escH(a.status||'') + '</span></td>'
              + '</tr>';
          }).join('') + '</tbody></table>'
        : '<p style="color:#6b7280;font-size:9pt;padding:8px">No inspections recorded this month.</p>')
      + '</div>'

      + '<div class="rpt-section"><div class="rpt-section-title amber">Outstanding Actions</div>'
      + (openActions + overdueActions > 0
        ? '<table><thead><tr><th>Action</th><th>Responsible</th><th>Due Date</th><th>Status</th></tr></thead><tbody>'
          + actions.filter(function(a){ return a.status!=='closed'; }).map(function(a){
              return '<tr><td>' + escH(a.description||'') + '</td>'
                + '<td>' + escH(a.responsible||'-') + '</td>'
                + '<td>' + (a.due_date?new Date(a.due_date).toLocaleDateString('en-GB'):'-') + '</td>'
                + '<td><span class="badge ' + (a.status==='overdue'?'badge-red':'badge-amber') + '">' + escH(a.status||'') + '</span></td>'
                + '</tr>';
            }).join('') + '</tbody></table>'
        : '<p style="color:#6b7280;font-size:9pt;padding:8px">All actions are closed. ?</p>')
      + '</div>'

      + '<div class="rpt-signatures">'
      + '<div class="rpt-sig-box"><div class="sig-line"></div><label>Prepared By / Date</label></div>'
      + '<div class="rpt-sig-box"><div class="sig-line"></div><label>HSE Manager / Date</label></div>'
      + '<div class="rpt-sig-box"><div class="sig-line"></div><label>Senior Management / Date</label></div>'
      + '</div>'
      + aurisFooter('Monthly HSE Summary')
      + '</div>';

    aurisPrint(html, 'HSE Monthly Report - ' + monthName);
  } catch(e) {
    toast('Error generating report: ' + e.message, false);
  }
}

// -- Print buttons helper ----------------------------------------
function addPrintBtn(container, onclick, label) {
  var btn = document.createElement('button');
  btn.className = 'btn btn-sm';
  btn.style.cssText = 'gap:6px;';
  btn.innerHTML = '<i class="ti ti-printer"></i>' + (label||'Print PDF');
  if (typeof onclick === 'function') btn.addEventListener('click', onclick);
  if (container) container.appendChild(btn);
  return btn;
}

function printCleanRegisterTables(root) {
  if (!root) return;
  root.querySelectorAll('table').forEach(function(table) {
    table.classList.add('data-table');
    table.style.width = '100%';
    table.style.borderCollapse = 'collapse';
    var rows = Array.from(table.rows || []);
    if (!rows.length) return;
    var maxCols = rows.reduce(function(n, row) { return Math.max(n, row.cells ? row.cells.length : 0); }, 0);
    for (var c = maxCols - 1; c >= 0; c--) {
      var headerText = '';
      var firstRow = rows[0];
      if (firstRow && firstRow.cells && firstRow.cells[c]) {
        headerText = (firstRow.cells[c].textContent || '').replace(/\s+/g, ' ').trim().toLowerCase();
      }
      var bodyText = rows.slice(1).map(function(row) {
        return row.cells && row.cells[c] ? (row.cells[c].textContent || '').replace(/\s+/g, ' ').trim() : '';
      }).join('');
      var isActionColumn = !headerText || /^(action|actions|edit|delete|view|open)$/i.test(headerText);
      if (isActionColumn && !bodyText) {
        rows.forEach(function(row) {
          if (row.cells && row.cells[c]) row.deleteCell(c);
        });
      }
    }
  });
  root.querySelectorAll('thead tr, thead th').forEach(function(el) {
    el.style.background = '#e5e7eb';
    el.style.color = '#111827';
  });
}

function printCleanRegisterChrome(root) {
  if (!root) return;
  root.querySelectorAll('.mtg-tab,.inv-tab,.kpi-tab,.tab-btn,.topbar,.sidebar,.no-print').forEach(function(el) {
    el.remove();
  });
  root.querySelectorAll('[id*="filter"],[class*="filter"],[id*="search"],[class*="search"]').forEach(function(el) {
    if (el.closest('table') || el.querySelector('table,tbody')) return;
    var text = (el.textContent || '').replace(/\s+/g, ' ').trim();
    if (el.querySelector('input,select,button,.btn') || text.length < 100) el.remove();
  });
  root.querySelectorAll('div,section').forEach(function(el) {
    if (el.querySelector('table,img,canvas,svg')) return;
    if ((el.textContent || '').replace(/\s+/g, ' ').trim()) return;
    el.remove();
  });
}

function printReportContextLabel() {
  try {
    var visibleLabel = (document.getElementById('sa-company-label')?.textContent || '').replace(/\s+/g, ' ').trim();
    if (visibleLabel) return visibleLabel;
    if (typeof isSA === 'function' && isSA() && typeof sephsCompanyContext !== 'undefined' && sephsCompanyContext) {
      var list = Array.isArray(window.saCompanyList) ? window.saCompanyList : (typeof saCompanyList !== 'undefined' && Array.isArray(saCompanyList) ? saCompanyList : []);
      var selected = list.find(function(c){ return c.id === sephsCompanyContext; });
      if (selected && selected.name) return selected.name;
    }
    if (typeof co !== 'undefined' && co && co.name) return co.name;
    if (typeof prof !== 'undefined' && prof && prof.company_name) return prof.company_name;
  } catch(e) {}
  return 'Current company';
}

function printRegisterView(title, selector) {
  var node = document.querySelector(selector);
  if (!node) { toast('Nothing to print yet', false); return; }
  var clone = node.cloneNode(true);
  clone.querySelectorAll('.loading-msg').forEach(function(el) {
    el.className = 'rpt-empty';
    el.textContent = 'This view was still loading when the report was generated. Please refresh the module and print again if records are missing.';
  });
  printCleanRegisterChrome(clone);
  clone.querySelectorAll('button,.btn,input,select,textarea,[contenteditable="true"]').forEach(function(el) {
    if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
      var span = document.createElement('span');
      var type = (el.getAttribute('type') || '').toLowerCase();
      if (type === 'checkbox' || type === 'radio') {
        span.textContent = el.checked ? 'Yes' : 'No';
      } else {
        span.textContent = el.value || el.placeholder || '';
      }
      el.replaceWith(span);
    } else if (el.tagName === 'SELECT') {
      var span = document.createElement('span');
      span.textContent = el.options[el.selectedIndex]?.text || '';
      el.replaceWith(span);
    } else {
      el.remove();
    }
  });
  printCleanRegisterTables(clone);
  var cleanText = (clone.textContent || '').replace(/\s+/g, ' ').trim();
  if (!cleanText) {
    clone.innerHTML = '<div class="rpt-empty">No records are available for this view at the time of printing.</div>';
  }
  var context = printReportContextLabel();
  var subtitle = 'Register extract - ' + context + ' - Generated: ' + new Date().toLocaleString();
  var html = '<div class="report-page">'
    + aurisHeader(title || 'AURIS360 Register', subtitle, '')
    + '<div class="rpt-section">' + clone.innerHTML + '</div>'
    + aurisFooter(title || 'Register')
    + '</div>';
  aurisPrint(html, title || 'AURIS360 Register');
}

