function fireShowCertForm(id) {
  fireEditCertId = id;
  var modal = document.getElementById('fire-cert-modal');
  var title = document.getElementById('fire-cert-modal-title');
  if (title) title.textContent = id ? 'Edit Fire Certificate' : 'New Fire Certificate';
  // Clear fields
  ['fc-number','fc-premises','fc-address','fc-area','fc-maxocc',
   'fc-conditions','fc-doc-url','fc-notes','fc-renewal-date'].forEach(function(f){
    var el=document.getElementById(f); if(el) el.value='';
  });
  document.getElementById('fc-type').value = 'fire_certificate';
  document.getElementById('fc-status').value = 'valid';
  document.getElementById('fc-authority').value = 'Mauritius Fire & Rescue Service';
  document.getElementById('fc-renewal-submitted').value = 'false';
  document.getElementById('fc-issue-date').value = '';
  document.getElementById('fc-expiry-date').value = '';
  document.getElementById('fc-occupancy').value = '';

  if (id) {
    var c = fireAllCerts.find(function(x){ return x.id===id; });
    if (!c) return;
    document.getElementById('fc-number').value      = c.cert_number||'';
    document.getElementById('fc-type').value        = c.cert_type||'fire_certificate';
    document.getElementById('fc-premises').value    = c.premises_name||'';
    document.getElementById('fc-address').value     = c.address||'';
    document.getElementById('fc-occupancy').value   = c.occupancy_type||'';
    document.getElementById('fc-area').value        = c.floor_area||'';
    document.getElementById('fc-maxocc').value      = c.max_occupancy||'';
    document.getElementById('fc-authority').value   = c.issuing_authority||'Mauritius Fire & Rescue Service';
    document.getElementById('fc-status').value      = c.status||'valid';
    document.getElementById('fc-issue-date').value  = c.issue_date||'';
    document.getElementById('fc-expiry-date').value = c.expiry_date||'';
    document.getElementById('fc-renewal-submitted').value = c.renewal_submitted ? 'true' : 'false';
    document.getElementById('fc-renewal-date').value = c.renewal_date||'';
    document.getElementById('fc-conditions').value  = c.conditions||'';
    document.getElementById('fc-doc-url').value     = c.document_url||'';
    document.getElementById('fc-notes').value       = c.notes||'';
  }
  modal.style.display = 'flex';
}

async function fireSaveCert() {
  var premises = document.getElementById('fc-premises').value.trim();
  var expiry   = document.getElementById('fc-expiry-date').value;
  if (!premises) { toast('Premises name is required', false); return; }
  if (!expiry)   { toast('Expiry date is required', false); return; }

  var cid = (isSA() && sephsCompanyContext) ? sephsCompanyContext : prof.company_id;
  var body = {
    company_id:          cid,
    cert_number:         document.getElementById('fc-number').value.trim()||null,
    cert_type:           document.getElementById('fc-type').value,
    premises_name:       premises,
    address:             document.getElementById('fc-address').value.trim()||null,
    occupancy_type:      document.getElementById('fc-occupancy').value||null,
    floor_area:          parseFloat(document.getElementById('fc-area').value)||null,
    max_occupancy:       parseInt(document.getElementById('fc-maxocc').value)||null,
    issuing_authority:   document.getElementById('fc-authority').value.trim()||null,
    status:              document.getElementById('fc-status').value,
    issue_date:          document.getElementById('fc-issue-date').value||null,
    expiry_date:         expiry,
    renewal_submitted:   document.getElementById('fc-renewal-submitted').value === 'true',
    renewal_date:        document.getElementById('fc-renewal-date').value||null,
    conditions:          document.getElementById('fc-conditions').value.trim()||null,
    document_url:        document.getElementById('fc-doc-url').value.trim()||null,
    notes:               document.getElementById('fc-notes').value.trim()||null,
    updated_at:          new Date().toISOString()
  };

  try {
    if (fireEditCertId) {
      await api('/fire_certificates?id=eq.'+fireEditCertId, {m:'PATCH', p:'return=minimal', b:body});
      toast('Certificate updated');
    } else {
      body.created_by = prof.id;
      body.created_at = new Date().toISOString();
      await api('/fire_certificates', {m:'POST', p:'return=minimal', b:body});
      toast('Certificate added');
    }
    document.getElementById('fire-cert-modal').style.display = 'none';
    await fireLoadAll();
    fireRenderCerts();
  } catch(e) { toast(actionErrorMessage('Save fire certificate','Fire Certificates',e.message), false); }
}

async function fireDeleteCert(id) {
  try {
    var rows=await api('/fire_certificates?id=eq.'+id+'&select=status,notes');
    var current=rows?.[0]||{};
    if(String(current.status||'').toLowerCase()!=='archived'||!ohIsArchivedText(current.notes)){
      var ok=await appConfirm({title:'Archive fire certificate',message:'Archive this fire certificate instead of deleting it?',detail:'Fire certificates are compliance evidence and should remain traceable for renewals, audits and authority checks.',confirmText:'Archive certificate',cancelText:'Keep certificate',danger:true});
      if(!ok)return;
      await api('/fire_certificates?id=eq.'+id, {m:'PATCH', p:'return=minimal', b:{status:'archived',notes:ohArchivedText(current.notes),updated_at:new Date().toISOString()}});
      toast('Certificate archived');
      await fireLoadAll();
      fireRenderCerts();
      return;
    }
    if(!(await appConfirmDelete('archived fire certificate','Permanent deletion should be used only for duplicate/test certificates.')))return;
    await api('/fire_certificates?id=eq.'+id, {m:'DELETE', p:'return=minimal'});
    toast('Certificate deleted');
    await fireLoadAll();
    fireRenderCerts();
  } catch(e) { toast(actionErrorMessage('Delete fire certificate','Fire Certificates',e.message), false); }
}

